INSERT OR IGNORE INTO constant (id, name, symbol, difficulty, description, links, value, quantity_id, unit_id, compound_unit_id) VALUES
  ('pi', '{"en-us": "Pi", "cs-cz": "Pí"}', '\pi', 1, '{"en-us": "Pi is the ratio of a circle''s circumference to its diameter, approximately 3.14159.", "cs-cz": "Pí je poměr obvodu kruhu k jeho průměru, přibližně 3,14159."}', '["https://en.wikipedia.org/wiki/Pi"]', 3.141592653589793, NULL, NULL, NULL),
  ('euler_e', '{"en-us": "Euler''s number", "cs-cz": "Eulerovo číslo"}', 'e', 4, '{"en-us": "Euler''s number is the base of the natural logarithm, approximately 2.71828.", "cs-cz": "Eulerovo číslo je základ přirozeného logaritmu, přibližně 2,71828."}', '["https://en.wikipedia.org/wiki/E_(mathematical_constant)"]', 2.718281828459045, NULL, NULL, NULL),
  ('infinity', '{"en-us": "Infinity", "cs-cz": "Nekonečno"}', '\infty', 2, '{"en-us": "Infinity is an unbounded value greater than every real number; it is not a number in the usual sense.", "cs-cz": "Nekonečno je neohraničená hodnota větší než všechna reálná čísla; v běžném smyslu se nejedná o číslo."}', '["https://en.wikipedia.org/wiki/Infinity"]', NULL, NULL, NULL, NULL),
  ('gravitational_constant', '{"en-us": "Gravitational constant", "cs-cz": "Gravitační konstanta"}', 'G', 5, '{"en-us": "G determines the strength of gravity in Newton''s law of universal gravitation; measured as 6.674×10⁻¹¹ m³ kg⁻¹ s⁻².", "cs-cz": "G určuje sílu gravitace v Newtonově gravitačním zákoně; její změřená hodnota je 6,674×10⁻¹¹ m³ kg⁻¹ s⁻²."}', '["https://en.wikipedia.org/wiki/Gravitational_constant", "https://physics.nist.gov/cgi-bin/cuu/Value?bg"]', 6.6743e-11, NULL, 'metre', NULL),
  ('gas_constant', '{"en-us": "Gas constant", "cs-cz": "Molární plynová konstanta"}', 'R', 5, '{"en-us": "The universal gas constant relates the pressure, volume and temperature of an ideal gas; R = N_A·k_B ≈ 8.314 J mol⁻¹ K⁻¹.", "cs-cz": "Univerzální plynová konstanta spojuje tlak, objem a teplotu ideálního plynu; R = N_A·k_B ≈ 8,314 J mol⁻¹ K⁻¹."}', '["https://en.wikipedia.org/wiki/Gas_constant"]', 8.31446261815324, 'molar_entropy', 'joule', NULL),
  ('speed_of_light', '{"en-us": "Speed of light in vacuum", "cs-cz": "Rychlost světla ve vakuu"}', 'c', 5, '{"en-us": "The speed at which light travels in vacuum; an exact SI defining constant, c = 299 792 458 m/s.", "cs-cz": "Rychlost šíření světla ve vakuu; přesně definovaná SI konstanta, c = 299 792 458 m/s."}', '["https://en.wikipedia.org/wiki/Speed_of_light"]', 299792458.0, 'velocity', NULL, 'metre_per_second'),
  ('avogadro_number', '{"en-us": "Avogadro number", "cs-cz": "Avogadrova konstanta"}', 'N_\mathrm{A}', 4, '{"en-us": "The number of particles in one mole of substance; an exact SI defining constant, N_A = 6.02214076×10²³ mol⁻¹.", "cs-cz": "Počet částic v jednom molu látky; přesně definovaná SI konstanta, N_A = 6,02214076×10²³ mol⁻¹."}', '["https://en.wikipedia.org/wiki/Avogadro_constant"]', 6.02214076e+23, NULL, NULL, NULL),
  ('planck_constant', '{"en-us": "Planck constant", "cs-cz": "Planckova konstanta"}', 'h', 6, '{"en-us": "h relates the energy of a photon to its frequency (E = hν); an exact SI defining constant.", "cs-cz": "h spojuje energii fotonu s jeho frekvencí (E = hν); přesně definovaná SI konstanta."}', '["https://en.wikipedia.org/wiki/Planck_constant"]', 6.62607015e-34, 'angular_momentum', NULL, 'kilogram_metre_squared_per_second'),
  ('vacuum_permittivity', '{"en-us": "Vacuum permittivity", "cs-cz": "Permitivita vakua"}', '\varepsilon_0', 6, '{"en-us": "ε₀ quantifies how strong an electric field a charge produces in vacuum; ε₀ = 1/(μ₀c²) ≈ 8.854×10⁻¹² F/m.", "cs-cz": "ε₀ udává, jak silné elektrické pole vytvoří náboj ve vakuu; ε₀ = 1/(μ₀c²) ≈ 8,854×10⁻¹² F/m."}', '["https://en.wikipedia.org/wiki/Vacuum_permittivity"]', 8.8541878188e-12, 'permittivity', NULL, 'farad_per_metre'),
  ('vacuum_permeability', '{"en-us": "Vacuum permeability", "cs-cz": "Permeabilita vakua"}', '\mu_0', 7, '{"en-us": "μ₀ characterises the magnetic response of vacuum; μ₀ ≈ 1.257×10⁻⁶ H/m.", "cs-cz": "μ₀ charakterizuje magnetické chování vakua; μ₀ ≈ 1,257×10⁻⁶ H/m."}', '["https://en.wikipedia.org/wiki/Vacuum_permeability"]', 1.25663706127e-06, 'permeability', NULL, 'henry_per_metre'),
  ('boltzmann_constant', '{"en-us": "Boltzmann constant", "cs-cz": "Boltzmannova konstanta"}', 'k_\mathrm{B}', 6, '{"en-us": "k_B relates the average energy of particles to temperature; an exact SI defining constant.", "cs-cz": "k_B spojuje střední energii částic s teplotou; přesně definovaná SI konstanta."}', '["https://en.wikipedia.org/wiki/Boltzmann_constant"]', 1.380649e-23, 'entropy', NULL, 'joule_per_kelvin'),
  ('elementary_charge', '{"en-us": "Elementary charge", "cs-cz": "Elementární náboj"}', 'e', 7, '{"en-us": "e is the electric charge carried by a single proton; an exact SI defining constant.", "cs-cz": "e je elektrický náboj jednoho protonu; přesně definovaná SI konstanta."}', '["https://en.wikipedia.org/wiki/Elementary_charge"]', 1.602176634e-19, 'charge', 'coulomb', NULL),
  ('standard_gravity', '{"en-us": "Standard gravity", "cs-cz": "Normální tíhové zrychlení"}', 'g_0', 3, '{"en-us": "g₀ is the nominal gravitational acceleration at sea level on Earth, defined as 9.80665 m/s².", "cs-cz": "g₀ je normované gravitační zrychlení na hladině moře na Zemi, definované jako 9,80665 m/s²."}', '["https://en.wikipedia.org/wiki/Standard_gravity"]', 9.80665, 'acceleration', NULL, 'metre_per_second_squared'),
  ('coulomb_constant', '{"en-us": "Coulomb constant", "cs-cz": "Coulombova konstanta"}', 'k_\mathrm{e}', 6, '{"en-us": "k_e is the proportionality factor in Coulomb''s law, k_e = 1/(4πε₀) ≈ 8.988×10⁹ N m² C⁻².", "cs-cz": "k_e je koeficient proporcionality v Coulombově zákoně, k_e = 1/(4πε₀) ≈ 8,988×10⁹ N m² C⁻²."}', '["https://en.wikipedia.org/wiki/Coulomb_constant"]', 8987551786.17, NULL, 'newton', NULL),
  ('rydberg_constant', '{"en-us": "Rydberg constant", "cs-cz": "Rydbergova konstanta"}', 'R_\mathrm{H}', 8, '{"en-us": "R_H gives the limiting wavenumber of photons emitted by electron transitions in hydrogen.", "cs-cz": "R_H udává mezní vlnové číslo fotonů emitovaných při přechodech elektronů v atomu vodíku."}', '["https://en.wikipedia.org/wiki/Rydberg_constant"]', 10973731.56816, 'wavenumber', NULL, 'per_metre'),
  ('wiens_constant', '{"en-us": "Wien''s displacement constant", "cs-cz": "Wienova konstanta"}', 'b', 8, '{"en-us": "b gives the peak wavelength of black-body radiation for a given temperature, λ_max = b/T.", "cs-cz": "b udává vlnovou délku maxima záření absolutně černého tělesa při dané teplotě, λ_max = b/T."}', '["https://en.wikipedia.org/wiki/Wien%27s_displacement_law"]', 0.002897771955, NULL, 'metre', NULL),
  ('celsius_zero', '{"en-us": "Celsius zero in Kelvin", "cs-cz": "Nula Celsia v Kelvinech"}', '273.15', 3, '{"en-us": "The zero point of the Celsius scale expressed in kelvin; 0 °C = 273.15 K by definition.", "cs-cz": "Nulový bod Celsiovy stupnice vyjádřený v kelvinech; 0 °C = 273,15 K podle definice."}', '["https://en.wikipedia.org/wiki/Celsius"]', 273.15, 'temperature', 'kelvin', NULL),
  ('faraday_constant', '{"en-us": "Faraday constant", "cs-cz": "Faradayova konstanta"}', 'F', 8, '{"en-us": "F is the magnitude of electric charge per mole of electrons, F = N_A·e ≈ 96 485 C/mol.", "cs-cz": "F je velikost elektrického náboje jednoho molu elektronů, F = N_A·e ≈ 96 485 C/mol."}', '["https://en.wikipedia.org/wiki/Faraday_constant"]', 96485.33212331001, NULL, 'coulomb', NULL),
  ('hubble_constant', '{"en-us": "Hubble constant", "cs-cz": "Hubbleova konstanta"}', 'H_0', 8, '{"en-us": "H₀ is the present rate of expansion of the universe in Hubble''s law, v = H₀·d.", "cs-cz": "H₀ je současná rychlost rozpínání vesmíru v Hubbleově zákoně, v = H₀·d."}', '["https://en.wikipedia.org/wiki/Hubble%27s_law"]', 2.1927112672380573e-18, 'frequency', 'hertz', NULL),
  ('stefan_boltzmann_constant', '{"en-us": "Stefan-Boltzmann constant", "cs-cz": "Stefanova-Boltzmannova konstanta"}', '\sigma', 9, '{"en-us": "σ appears in the Stefan–Boltzmann law for the power radiated by a black body, j = σT⁴.", "cs-cz": "σ vystupuje ve Stefan–Boltzmannově zákoně pro výkon vyzařovaný absolutně černým tělesem, j = σT⁴."}', '["https://en.wikipedia.org/wiki/Stefan%E2%80%93Boltzmann_constant"]', 5.670374419e-08, NULL, 'watt', NULL),
  ('bohr_radius', '{"en-us": "Bohr radius", "cs-cz": "Bohrův poloměr"}', 'a_0', 8, '{"en-us": "a₀ is the most probable distance between the electron and the nucleus in a ground-state hydrogen atom.", "cs-cz": "a₀ je nejpravděpodobnější vzdálenost mezi elektronem a jádrem vodíkového atomu v základním stavu."}', '["https://en.wikipedia.org/wiki/Bohr_radius"]', 5.29177210544e-11, 'length', 'metre', NULL);

