INSERT OR IGNORE INTO formula (id, name, topic, difficulty, description, links) VALUES
  ('absolute_pressure', '{"en-us": "Absolute pressure"}', 'pressure', 5, '{"en-us": "Absolute pressure is measured relative to a perfect vacuum (zero pressure). Gauge pressure is measured relative to local atmospheric pressure. \nFor fluids at a specific depth, the formula $P_{abs} = P_{atm} + \\rho gh$ is used."}', '["https://byjus.com/absolute-pressure-formula/", "https://www.vedantu.com/jee-main/physics-absolute-pressure-formula", "https://www.easycalculation.com/formulas/absolute-pressure.html", "https://testbook.com/physics-formulas/absolute-pressure-formula", "https://www.geeksforgeeks.org/physics/absolute-pressure-formula/", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book:_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14:_Fluid_Mechanics/14.04:_Measuring_Pressure"]'),
  ('absorbance_transmittance', '{"en-us": "Absorbance from transmittance"}', 'analytical_chemistry', 6, '{"en-us": "This relationship is derived from the Beer-Lambert Law. \nTransmittance is a number between 0 and 1."}', '["https://en.wikipedia.org/wiki/Transmittance", "https://www.sigmaaldrich.com/GB/en/support/calculators-and-apps/absorbance-transmittance-conversion", "https://www.electrical4u.com/what-is-transmittance/", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Instrumental_Analysis_(LibreTexts)/13:_Introduction_to_Ultraviolet_Visible_Absorption_Spectrometry/13.01:_Transmittance_and_Absorbance"]'),
  ('absorbed_dose_formula', '{"en-us": "Absorbed dose"}', 'nuclear_physics', 7, '{"en-us": "Absorbed dose is defined as the energy absorbed per unit mass of the irradiated material."}', '["https://www.radiation-dosimetry.org/what-is-absorbed-dose-formula-equation-definition/", "https://en.wikipedia.org/wiki/Absorbed_dose", "https://en.wikipedia.org/wiki/Gray_(unit)", "https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/32%3A_Medical_Applications_of_Nuclear_Physics/32.02%3A_Biological_Effects_of_Ionizing_Radiation"]'),
  ('absorbed_dose_rate_formula', '{"en-us": "Absorbed dose rate"}', 'nuclear_physics', 8, '{"en-us": "Absorbed dose rate measures how quickly ionizing radiation deposits energy in matter, expressed as absorbed dose delivered per unit time (SI unit: gray per second). It is the key quantity for assessing radiation field intensity, since the total dose accumulated equals the rate multiplied by the exposure time."}', '["https://www.nuclear-power.com/nuclear-engineering/radiation-protection/absorbed-dose/absorbed-dose-rate/", "https://qudt.org/vocab/quantitykind/AbsorbedDoseRate", "https://www.radiation-dosimetry.org/what-is-absorbed-dose-formula-equation-definition/", "https://www.epa.gov/radiation/radiation-terms-and-units"]'),
  ('absorption_coefficient_optical', '{"en-us": "Absorption coefficient from absorbance"}', 'interference', 7, '{"en-us": "Relates the decadic absorbance measured for a uniform sample to the absorption coefficient, the quantity that measures how strongly a medium attenuates light per unit distance. Because absorbance is base-10 logarithmic while the absorption coefficient enters an exponential (base-e) attenuation law, the factor ln(10) ≈ 2.303 converts between the two. Assumes a homogeneous, non-scattering medium."}', '["https://en.wikipedia.org/wiki/Absorbance", "https://en.wikipedia.org/wiki/Beer%E2%80%93Lambert_law", "https://www.rp-photonics.com/absorbance.html", "https://www.rp-photonics.com/absorption_coefficient.html"]'),
  ('absorptivity_molar', '{"en-us": "Molar absorptivity from Beer-Lambert law"}', 'analytical_chemistry', 7, '{"en-us": "Molar absorptivity (also called molar extinction or molar attenuation coefficient) measures how strongly a chemical species absorbs light of a given wavelength per molar concentration. It is characteristic of the species and wavelength, and underlies quantitative absorption spectroscopy, allowing unknown concentrations to be determined from measured absorbance. The Beer-Lambert relation assumes dilute, homogeneous solutions and monochromatic light."}', '["https://en.wikipedia.org/wiki/Molar_absorptivity", "https://en.wikipedia.org/wiki/Beer%E2%80%93Lambert_law", "https://www.rp-photonics.com/absorbance.html"]'),
  ('ac_circuit_power_factor', '{"en-us": "AC circuit power factor"}', 'circuits', 8, '{"en-us": "The power factor is a dimensionless measure of how effectively an AC circuit converts supplied electrical power into useful (real) power, defined as the ratio of real power to apparent power. For sinusoidal waveforms it equals the cosine of the phase angle between voltage and current; values below one indicate reactive or distorted current flow. It is used for sizing and billing in power systems and for power factor correction."}', '["https://en.m.wikipedia.org/wiki/Power_factor", "https://eng.libretexts.org/Bookshelves/Electrical_Engineering/Electronics/AC_Electrical_Circuit_Analysis%3A_A_Practical_Approach_(Fiore)/07%3A_AC_Power/7.3%3A_Power_Triangle", "https://www.allaboutcircuits.com/textbook/alternating-current/chpt-11/true-reactive-and-apparent-power/", "https://ocw.mit.edu/courses/6-622-power-electronics-spring-2023/mit6_622_s23_lec04.pdf"]'),
  ('ac_power_average_resistive', '{"en-us": "Average power in an AC resistive circuit"}', 'circuits', 7, '{"en-us": "In a purely resistive AC circuit, voltage and current are in phase, so instantaneous power is always positive and oscillates at twice the line frequency. The average power delivered over a cycle equals half the product of the peak values, which is identical to using RMS values as in DC power calculations. This relation applies only to resistive loads; reactive elements contribute zero average power."}', '["https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/15%3A_Alternating-Current_Circuits/15.05%3A_Power_in_an_AC_Circuit", "https://hyperphysics.gsu.edu/hbase/electric/powerac.html", "https://www.miniphysics.com/power-dissipation-in-resistive-load.html"]'),
  ('acceleration_atwood_machine', '{"en-us": "Acceleration of an Atwood machine"}', 'newtons_laws', 6, '{"en-us": "An Atwood machine consists of two masses connected by a light string over an ideal frictionless pulley; the heavier mass accelerates downward while the lighter one rises. The magnitude of that acceleration is set by the imbalance of the two weights relative to the total inertia being accelerated. The result assumes a massless, inextensible string and a massless, frictionless pulley."}', '["https://en.wikipedia.org/wiki/Atwood%5fmachine", "https://web.physics.ucsb.edu/~lecturedemonstrations/Composer/Pages/12.33.html", "https://www.sciencing.com/solve-atwood-machine-problems-7349290/"]'),
  ('acceleration_from_net_force', '{"en-us": "Acceleration from net force"}', 'newtons_laws', 4, '{"en-us": "This is Newton''s second law solved for acceleration: a body''s acceleration is directly proportional to the net (resultant) external force acting on it and inversely proportional to its mass, pointing in the direction of that net force. It applies to any object or system of constant mass and is the standard starting point for dynamics problems. The force must be the vector sum of all external forces, not any single force."}', '["https://openstax.org/books/university-physics-volume-1/pages/5-3-newtons-second-law", "https://www.physicsclassroom.com/tutorial/newtons-laws/newtons-second-law/newtons-second-law", "https://phys.libretexts.org/Workbench/PH_245_Textbook_V2/03%3A_Module_2_-_Multi-Dimensional_Mechanics/3.03%3A_Objective_2.c./3.3.03%3A_Newton''s_Second_Law"]'),
  ('acid_dissociation_constant', '{"en-us": "Acid dissociation constant"}', 'acids_and_bases', 6, '{"en-us": "The acid dissociation constant Ka quantifies the strength of a weak acid HA in water, where HA partially dissociates into a proton and its conjugate base. A larger Ka means the equilibrium lies further toward the products, i.e. a stronger acid; values are commonly reported on the logarithmic pKa scale. Strictly it should be written with activities rather than concentrations and depends on temperature and ionic strength."}', '["https://en.wikipedia.org/wiki/Acid_dissociation_constant", "https://goldbook.iupac.org/terms/view/15441", "https://chem.libretexts.org/Courses/California_State_University_Chico/General_Chemistry_112/04%3A_Acids_and_Bases/4.04%3A_Acid_Strength_and_the_Acid_Dissociation_Constant_(Ka)"]'),
  ('acid_dissociation_percent_ionization', '{"en-us": "Percent ionization from Ka and concentration"}', 'acids_and_bases', 7, '{"en-us": "Percent ionization expresses what fraction of a weak acid''s molecules have dissociated into ions at equilibrium, stated as a percentage. Unlike the ionization constant, it depends on how concentrated the solution is, generally decreasing as the solution becomes more concentrated and increasing upon dilution. It provides an intuitive measure of acid strength in a given solution."}', '["https://chem.libretexts.org/Courses/College_of_Wooster/Analytical_Chemistry_for_CoW/10%3A_AcidBase_Equilibria/10.06%3A_Weak_Acids", "https://chem-textbook.ucalgary.ca/version2/chapter-14-main/relative-strengths-of-acids-and-bases/acid-and-base-ionization-constants/", "https://courses.lumenlearning.com/suny-albany-chemistry/chapter/relative-strengths-of-acids-and-bases-2/"]'),
  ('activity_from_decay_constant', '{"en-us": "Activity from decay constant"}', 'nuclear_physics', 7, '{"en-us": "The activity of a radioactive sample is its rate of decay, measured in becquerels (decays per second). It is directly proportional to the number of undecayed radioactive nuclei present, with the decay constant as the proportionality factor representing the per-nucleus decay probability per unit time. As nuclei decay, both their number and the sample''s activity fall off exponentially together."}', '["https://en.wikipedia.org/wiki/Radioactive_decay", "https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/31%3A_Radioactivity_and_Nuclear_Physics/31.05%3A_Half-Life_and_Activity", "https://www.savemyexams.com/a-level/physics/cie/25/revision-notes/23-nuclear-physics/23-2-radioactive-decay/activity-and-the-decay-constant/"]'),
  ('activity_time', '{"en-us": "Activity at time t"}', 'nuclear_physics', 7, '{"en-us": "Because radioactive decay is a first-order process, the activity of a sample falls off exponentially: it drops by half after each half-life. This law predicts the decay rate of a source at any elapsed time from its initial activity and the nuclide''s decay constant, and is used in radiometric dating, nuclear medicine dosing, and source calibration."}', '["https://en.wikipedia.org/wiki/Radioactive_decay", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Analytical_Chemistry_2.1_(Harvey)/13%3A_Kinetic_Methods/13.03%3A_Radiochemistry", "https://www.savemyexams.com/a-level/physics/cie/25/revision-notes/23-nuclear-physics/23-2-radioactive-decay/activity-and-the-decay-constant/", "https://www.miniphysics.com/activity-half-life-and-decay-constant.html"]'),
  ('adiabatic_process', '{"en-us": "Adiabatic Process"}', 'ideal_gases', 7, '{"en-us": "In a quasi-static, reversible adiabatic process an ideal gas expands or compresses with no heat exchanged with the surroundings, so pressure and volume are constrained to vary along a steeper curve than an isotherm. The exponent is the heat capacity ratio of the gas (about 1.4 for air). This condition is used to relate the states of a gas in engines, compressors, and atmospheric processes."}', '["https://openstax.org/books/university-physics-volume-2/pages/3-6-adiabatic-processes-for-an-ideal-gas", "https://en.wikipedia.org/wiki/Adiabatic", "http://hyperphysics.phy-astr.gsu.edu/HBASE/thermo/adiab.html", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Heat_and_Thermodynamics_(Tatum)/08%3A_Heat_Capacity_and_the_Expansion_of_Gases/8.04%3A_Reversible_Adiabatic_Expansion_of_an_Ideal_Gas"]'),
  ('adiabatic_temp_volume', '{"en-us": "Adiabatic relation (temperature-volume)"}', 'ideal_gases', 8, '{"en-us": "For a quasi-static adiabatic process (no heat exchange) of an ideal gas, the temperature and volume are not independent: the product of the temperature and the volume raised to the heat capacity ratio minus one stays constant along the process. It follows from combining the first law of thermodynamics with the ideal gas law and is used to find the temperature after an adiabatic compression or expansion."}', '["https://openstax.org/books/university-physics-volume-2/pages/3-6-adiabatic-processes-for-an-ideal-gas", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/03%3A_The_First_Law_of_Thermodynamics/3.07%3A_Adiabatic_Processes_for_an_Ideal_Gas", "https://www.vedantu.com/physics/adiabatic-process"]'),
  ('adiabatic_work', '{"en-us": "Adiabatic work of an ideal gas"}', 'heat', 8, '{"en-us": "Gives the work done by an ideal gas during a reversible adiabatic process, obtained by integrating the adiabatic pressure-volume condition. Because no heat is exchanged, this work equals the decrease in the gas''s internal energy; it is positive for expansion and negative for compression."}', '["https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Heat_and_Thermodynamics_(Tatum)/08%3A_Heat_Capacity_and_the_Expansion_of_Gases/8.04%3A_Reversible_Adiabatic_Expansion_of_an_Ideal_Gas", "https://openstax.org/books/university-physics-volume-2/pages/3-6-adiabatic-processes-for-an-ideal-gas", "https://www.vedantu.com/jee-main/physics-work-done-during-adiabatic-expansion"]'),
  ('amperes_law', '{"en-us": "Ampere''s law"}', 'magnetism', 8, '{"en-us": "Relates the circulation of the magnetic field around a closed loop to the total electric current passing through any surface bounded by that loop. It is one of Maxwell''s equations and is the standard tool for computing magnetic fields in configurations with high symmetry, such as straight wires, solenoids, and toroids. The steady-current form shown here neglects displacement current."}', '["https://en.wikipedia.org/wiki/Amp%C3%A8re%27s_circuital_law", "https://openstax.org/books/university-physics-volume-2/pages/12-5-amperes-law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields/12.06%3A_Amperes_Law"]'),
  ('amphere_maxwell_law', '{"en-us": "Ampere-Maxwell law"}', 'magnetism', 9, '{"en-us": "Generalizes Ampere''s law by adding Maxwell''s displacement current: a time-varying electric flux through a surface acts as a source of magnetic field just as conduction current does. This makes the law consistent for any surface bounded by the same loop (famously resolving the charging-capacitor paradox) and underlies the prediction of electromagnetic waves."}', '["https://en.wikipedia.org/wiki/Amp%C3%A8re%E2%80%93Maxwell_equation", "https://physicsbook.gatech.edu/Ampere-Maxwell_Law", "https://em.geosci.xyz/content/maxwell1_fundamentals/formative_laws/ampere_maxwell.html", "https://galileoandeinstein.phys.virginia.edu/more_stuff/Maxwell_Eq.html"]'),
  ('amplitude_modulation_wave_equation', '{"en-us": "Amplitude modulation wave"}', 'electromagnetic_waves', 8, '{"en-us": "Describes the standard single-tone amplitude-modulated signal: the envelope of a high-frequency carrier wave varies in proportion to a lower-frequency message signal, with the modulation index controlling the depth of that variation. It is the basic model of AM radio transmission and is used to analyze carrier and sideband content; overmodulation occurs when the index exceeds one."}', '["https://en.wikipedia.org/wiki/Amplitude_modulation", "https://user.eng.umd.edu/~tretter/commlab/c6713slides/ch5.pdf", "https://en.wikibooks.org/wiki/Communication_Systems/Amplitude_Modulation", "https://www.electronics-notes.com/articles/radio/modulation/amplitude-modulation-am-theory-equations-formulas.php"]'),
  ('analytical_sensitivity', '{"en-us": "Analytical Sensitivity"}', 'analytical_chemistry', 8, '{"en-us": "In analytical chemistry, sensitivity measures how strongly a method responds to changes in the amount of analyte: it is the slope of the calibration curve relating the instrument''s measured signal to the analyte concentration. A steeper calibration line means smaller concentration differences can be distinguished. For nonlinear calibration curves the sensitivity varies with concentration and equals the local slope."}', '["https://en.wikipedia.org/wiki/Calibration_curve", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Analytical_Chemistry_2.1_by_David_Harvey/Analytical_Chemistry_2.1_(Harvey)/05%3A_Standardizing_Analytical_Methods/5.03%3A_Determining_the_Sensitivity", "https://media.iupac.org/publications/analytical_compendium/Cha18sec432.pdf"]'),
  ('angle_diff_cosine', '{"en-us": "Angle difference identity for cosine"}', 'trigonometric_identities', 6, '{"en-us": "Expresses the cosine of the difference of two angles in terms of the sines and cosines of the individual angles. It holds for all real angles and is one of the fundamental sum-and-difference identities, used to compute exact values such as cos(15 degrees) and to derive many other trigonometric relations. Note that for cosine the sign between the terms is opposite to the sign between the angles."}', '["https://openstax.org/books/algebra-and-trigonometry-2e/pages/9-2-sum-and-difference-identities", "https://math.libretexts.org/Bookshelves/Precalculus/Elementary_Trigonometry_(Corral)/03%3A_Identities/3.02%3A_Sum_and_Difference_Formulas", "https://mathworld.wolfram.com/TrigonometricAdditionFormulas.html"]'),
  ('angle_diff_sine', '{"en-us": "Angle difference identity for sine"}', 'trigonometric_identities', 6, '{"en-us": "Expresses the sine of the difference of two angles in terms of the sines and cosines of the individual angles, with the same sign between terms as the sign between the angles. Valid for all real angles, it is one of the fundamental sum-and-difference identities and is used for exact-value computations and derivations throughout trigonometry and calculus."}', '["https://openstax.org/books/algebra-and-trigonometry-2e/pages/9-2-sum-and-difference-identities", "https://math.libretexts.org/Bookshelves/Precalculus/Elementary_Trigonometry_(Corral)/03%3A_Identities/3.02%3A_Sum_and_Difference_Formulas", "https://mathworld.wolfram.com/TrigonometricAdditionFormulas.html"]'),
  ('angle_diff_tangent', '{"en-us": "Angle difference identity for tangent"}', 'trigonometric_identities', 6, '{"en-us": "Expresses the tangent of the difference of two angles through the tangents of the individual angles, where the sign between the terms of the numerator matches the angle difference and the sign in the denominator is opposite. It follows from dividing the sine and cosine difference identities and holds wherever both tangents are defined."}', '["https://math.libretexts.org/Bookshelves/Precalculus/Precalculus_1e_(OpenStax)/07%3A_Trigonometric_Identities_and_Equations/7.02%3A_Sum_and_Difference_Identities", "https://proofwiki.org/wiki/Tangent_of_Difference", "https://www.cuemath.com/trigonometry/tan-a-minus-b/"]'),
  ('angle_of_deviation_mirror', '{"en-us": "Angle of deviation by a plane mirror"}', 'reflection', 5, '{"en-us": "The angle of deviation is the angle between the original direction of an incident ray and its direction after reflection by a plane mirror. Because the law of reflection makes the angles of incidence and reflection equal, a single reflection turns the ray through this deviation, which is largest (a full reversal) at normal incidence and shrinks as the ray strikes more obliquely."}', '["https://www.brainkart.com/article/Ray-Optics_41431/", "https://www.shaalaa.com/question-bank-solutions/what-is-angle-of-deviation-due-to-reflection_226521", "https://www.pw.live/chapter-optics-class-12/reflection-from-a-plane-surface"]'),
  ('angle_of_repose', '{"en-us": "Angle of repose"}', 'friction', 7, '{"en-us": "The angle of repose is the steepest inclination of a plane at which a body resting on it remains stationary, with static friction exactly balancing the downhill pull of gravity. It depends only on the coefficient of static friction between the surfaces and is used to characterize slopes of granular piles and the onset of sliding; cohesive or wet materials deviate from this ideal result."}', '["https://en.wikipedia.org/wiki/Angle_of_repose", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_I_-_Classical_Mechanics_(Gea-Banacloche)/08%3A_Motion_in_Two_Dimensions/8.03%3A_Inclined_Planes", "https://www.omnicalculator.com/physics/angle-of-repose"]'),
  ('angle_sum_cosine', '{"en-us": "Angle sum identity for cosine"}', 'trigonometric_identities', 6, '{"en-us": "Expresses the cosine of the sum of two angles in terms of the sines and cosines of the individual angles, with a minus sign between the terms that is opposite to the plus sign between the angles. Valid for all real angles, this fundamental identity underlies exact-value calculations, wave addition, and derivations of the other sum-and-difference formulas."}', '["https://openstax.org/books/algebra-and-trigonometry-2e/pages/9-2-sum-and-difference-identities", "https://math.libretexts.org/Bookshelves/Precalculus/Elementary_Trigonometry_(Corral)/03%3A_Identities/3.02%3A_Sum_and_Difference_Formulas", "https://mathworld.wolfram.com/TrigonometricAdditionFormulas.html"]'),
  ('angle_sum_sine', '{"en-us": "Angle sum identity for sine"}', 'trigonometric_identities', 6, '{"en-us": "This trigonometric identity, known as the sine addition formula, expresses the sine of a compound angle as a combination of the sines and cosines of its two component angles. It holds for all real angles and is used to evaluate sines of angles not on the unit circle, and to derive double-angle and product-to-sum formulas."}', '["https://www.cuemath.com/trigonometry/sin-a-plus-b", "https://www.softschools.com/math/trigonometry/sum_and_difference_of_angles_identities", "https://www.analyzemath.com/Trigonometry_2/sum_difference_product_trigonometric_formulas_questions.html", "https://fiveable.me/honors-pre-calc/key-terms/sine-sum-identity"]'),
  ('angle_sum_tangent', '{"en-us": "Angle sum identity for tangent"}', 'trigonometric_identities', 6, '{"en-us": "The tangent addition formula gives the tangent of a compound angle in terms of the tangents of its two component angles. It follows from the sine and cosine addition formulas and holds whenever the tangents are defined; it is used to find exact values such as the tangent of 75 degrees and to derive double-angle formulas."}', '["https://www.cuemath.com/trigonometry/tan-a-plus-b/", "https://mathworld.wolfram.com/TrigonometricAdditionFormulas.html", "https://www.geeksforgeeks.org/maths/tangent-addition-formula/", "https://proofwiki.org/wiki/Tangent_of_Sum"]'),
  ('angular_acceleration_from_torque', '{"en-us": "Angular acceleration from torque"}', 'torque', 6, '{"en-us": "This relation is Newton''s second law for rotation: the net torque acting on a rigid body about a fixed axis equals its moment of inertia times the resulting angular acceleration. The moment of inertia plays the role that mass plays in linear motion, so a larger moment of inertia means less angular acceleration for the same applied torque."}', '["https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Dourmashkin)/17%3A_Two-Dimensional_Rotational_Dynamics/17.04%3A_Torque_Angular_Acceleration_and_Moment_of_Inertia", "https://phys.libretexts.org/Bookshelves/University_Physics/Physics_%28Boundless%29/8%3A_Static_Equilibrium_Elasticity_and_Torque/8.8%3A_Torque_and_Angular_Acceleration", "https://www.vedantu.com/physics/angular-acceleration"]'),
  ('angular_displacement_constant_acceleration', '{"en-us": "Angular displacement at constant angular acceleration"}', 'circular_motion', 6, '{"en-us": "A rotational kinematics equation giving the angle swept by a body rotating about a fixed axis with constant angular acceleration, starting from a known initial spin rate. It is the rotational analogue of the corresponding linear motion equation and is valid only while the angular acceleration stays constant; angles must be expressed in radians."}', '["https://phys.libretexts.org/Workbench/PH_245_Textbook_V2/02:_Module_1-_One-Dimensional_Kinematics/2.02:_Objective_1.b./2.2.03:_Rotation_with_Constant_Angular_Acceleration", "https://openstax.org/books/physics/pages/6-3-rotational-motion", "https://www.albert.io/blog/rotational-kinematics-ap-physics-1-review", "https://www.miniphysics.com/kinematics-of-angular-motion.html"]'),
  ('angular_displacement_definition', '{"en-us": "Angular displacement from rotation"}', 'circular_motion', 5, '{"en-us": "This relation defines plane angle in radians: the angle swept out at the center of a circle equals the arc length traversed divided by the radius. It connects linear distance along a circular path to rotational motion and underlies the radian unit, since a full turn gives an arc of one circumference."}', '["https://en.wikipedia.org/wiki/Angular_displacement", "https://www.geeksforgeeks.org/physics/angular-displacement/", "https://www.vedantu.com/physics/angular-displacement", "https://softschools.com/formulas/physics/angular_displacement_formula/45"]'),
  ('angular_frequency', '{"en-us": "Angular frequency"}', 'harmonic_motion', 5, '{"en-us": "Angular frequency measures how quickly a periodic process advances through its cycle, expressed as an angle covered per unit time in radians per second rather than cycles per second. It is used throughout oscillation, wave, and circular-motion analysis because sinusoidal expressions become compact when written in terms of it."}', '["https://en.wikipedia.org/wiki/Angular_frequency", "https://www.geeksforgeeks.org/physics/angular-frequency/", "https://www.britannica.com/science/angular-frequency", "https://fiveable.me/principles-physics-iii-thermal-physics-waves/key-terms/angular-frequency"]'),
  ('angular_frequency_pendulum', '{"en-us": "Angular frequency of a simple pendulum"}', 'harmonic_motion', 6, '{"en-us": "For small-amplitude swings, a simple pendulum behaves as a simple harmonic oscillator whose angular frequency depends only on the local gravitational acceleration and the pendulum length — not on the bob''s mass or the oscillation amplitude. This result follows from applying the small-angle approximation to the pendulum equation of motion and underlies pendulum clocks."}', '["https://openstax.org/books/university-physics-volume-1/pages/15-4-pendulums", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_I_-_Classical_Mechanics_%28Gea-Banacloche%29/11%3A_Simple_Harmonic_Motion/11.03%3A_Pendulums", "https://sciencenotes.org/simple-pendulum-physics-formulas-and-applications", "https://lipa.physics.oregonstate.edu/sec_pendula.html"]'),
  ('angular_frequency_spring', '{"en-us": "Angular frequency of a spring-mass system"}', 'harmonic_motion', 6, '{"en-us": "A mass attached to an ideal spring oscillates in simple harmonic motion, and its angular frequency is set by the spring stiffness relative to the oscillating mass. A stiffer spring raises the frequency while a heavier mass lowers it; the result assumes Hooke''s-law restoring force with damping and the spring''s own mass neglected."}', '["https://en.wikipedia.org/wiki/Simple_harmonic_motion", "http://hyperphysics.phy-astr.gsu.edu/hbase/shm2.html", "https://www.webassign.net/asucolphysmechl2/lab_10/manual.pdf"]'),
  ('angular_momentum_eigenvalue', '{"en-us": "Angular momentum z-component eigenvalue"}', 'quantum_mechanics', 10, '{"en-us": "In quantum mechanics, measurement of the projection of orbital angular momentum along a chosen axis yields only discrete values. Each allowed value is set by the magnetic quantum number and expressed in units of the reduced Planck constant; this quantization underlies atomic energy-level splittings such as the Zeeman effect."}', '["https://phys.libretexts.org/Bookshelves/Quantum_Mechanics/Introductory_Quantum_Mechanics_(Fitzpatrick)/07:_Orbital_Angular_Momentum/7.04:_Eigenvalues_of_Lz", "https://titan.physx.u-szeged.hu/~dpiroska/atmolfiz/angular_momentum_in_quantum_mechanics.html"]'),
  ('angular_momentum_formula', '{"en-us": "Angular momentum"}', 'angular_momentum', 6, '{"en-us": "For a rigid body rotating about a fixed axis, the angular momentum equals the product of its moment of inertia about that axis and its angular velocity. It is the rotational analogue of linear momentum and is conserved when no net external torque acts — the principle behind a figure skater spinning faster when pulling in their arms."}', '["https://en.wikipedia.org/wiki/Angular_momentum", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/11%3A__Angular_Momentum/11.03%3A_Angular_Momentum", "https://www.softschools.com/formulas/physics/angular_momentum_formula/86/"]'),
  ('angular_momentum_gyroscope_precession', '{"en-us": "Gyroscope precession angular velocity"}', 'angular_momentum', 9, '{"en-us": "When a torque is applied to a spinning gyroscope, its spin axis does not tip over in the direction of the torque but sweeps sideways around a vertical axis — steady precession. The precession rate equals the applied torque divided by the spin angular momentum, valid when precession is slow compared with the spin; faster spin therefore means slower, more stable precession."}', '["https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/11%3A__Angular_Momentum/11.05%3A_Precession_of_a_Gyroscope", "https://pressbooks.online.ucf.edu/osuniversityphysics/chapter/11-3-precession-of-a-gyroscope/", "https://mechsimulator.com/blog/articles/gyroscope-angular-momentum-precession-guide/"]'),
  ('angular_momentum_orbital', '{"en-us": "Orbital angular momentum"}', 'angular_momentum', 8, '{"en-us": "The orbital angular momentum of a body circling a central point is the rotational analogue of linear momentum, obtained from mass, orbital speed, and orbit radius. For circular orbits it stays constant because gravity exerts no torque — the basis of Kepler''s second law and of analyses of satellites, planets, and orbiting electrons."}', '["http://hyperphysics.phy-astr.gsu.edu/hbase/amom.html", "https://brilliant.org/wiki/characteristics-of-circular-orbits/", "https://www.physicsoftheuniverse.com/calculator/angular_momentum.html"]'),
  ('angular_momentum_photon', '{"en-us": "Photon angular momentum"}', 'quantum_mechanics', 9, '{"en-us": "Each photon carries an intrinsic (spin) angular momentum whose magnitude is one reduced quantum of action, with sign set by its circular polarization (helicity). This quantized value underlies phenomena such as optical torque on birefringent particles and spin-to-orbital angular momentum conversion."}', '["https://en.wikipedia.org/wiki/Spin_angular_momentum_of_light", "https://en.wikipedia.org/wiki/Angular_momentum_of_light", "https://arxiv.org/abs/1609.05218"]'),
  ('angular_momentum_quantization', '{"en-us": "Angular momentum quantization"}', 'quantum_mechanics', 9, '{"en-us": "In quantum mechanics the orbital angular momentum of a particle (such as an electron in an atom) is quantized: its magnitude can only take discrete values determined by the azimuthal quantum number l. This result explains the shapes of atomic orbitals and underlies selection rules in atomic spectroscopy."}', '["https://en.wikipedia.org/wiki/Azimuthal_quantum_number", "https://scienceworld.wolfram.com/physics/ElectronAngularMomentum.html", "https://scienceworld.wolfram.com/physics/OrbitalAngularMomentum.html", "https://phys.libretexts.org/Bookshelves/Quantum_Mechanics/Advanced_Quantum_Mechanics_(Kok)/07%3A_Orbital_Angular_Momentum_and_Spin/7.01%3A_Orbital_Angular_Momentum"]'),
  ('angular_momentum_system_of_particles', '{"en-us": "Angular momentum of a system"}', 'angular_momentum', 6, '{"en-us": "The total angular momentum of a system of particles about a chosen origin is the vector sum of the angular momenta of the individual particles. Internal torques cancel in pairs, so this total changes only under net external torque, which makes it the conserved quantity behind the law of conservation of angular momentum."}', '["https://openstax.org/books/university-physics-volume-1/pages/11-2-angular-momentum", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Dourmashkin)/19:_Angular_Momentum/19.06:_Angular_Momentum_of_a_System_of_Particles"]'),
  ('angular_momentum_torque_impulse', '{"en-us": "Angular momentum from torque impulse"}', 'angular_momentum', 7, '{"en-us": "This is the angular impulse-momentum theorem: a net torque acting on a body over a time interval (the angular impulse) equals the resulting change in the body''s angular momentum. It is the rotational analogue of the linear impulse-momentum theorem and holds exactly for constant net torque; for varying torque the torque-time product is replaced by its integral."}', '["https://phys.libretexts.org/Courses/Gettysburg_College/Gettysburg_College_Physics_for_Physics_Majors/06%3A_C6)_Conservation_of_Angular_Momentum_I/6.02%3A_Angular_Momentum_and_Torque", "https://eng.libretexts.org/Bookshelves/Mechanical_Engineering/Introductory_Dynamics%3A_2D_Kinematics_and_Kinetics_of_Point_Masses_and_Rigid_Bodies_(Steeneken)/03%3A_Rigid_Body_Dynamics/12%3A_Angular_Impulse_and_Angular_Momentum/12.01%3A_Principle_of_angular_impulse_and_angular_momentum", "https://www.albert.io/blog/torque-and-angular-momentum-ap-physics-c-mechanics-review-3"]'),
  ('angular_momentum_vector_form', '{"en-us": "Angular momentum vector"}', 'angular_momentum', 7, '{"en-us": "The angular momentum of a point particle about a chosen origin is the moment of its linear momentum, given by the magnitude of the cross product of the particle''s position vector and its momentum. Only the component of momentum perpendicular to the position vector contributes, so a particle moving along a line through the origin carries no angular momentum about it."}', '["https://en.wikipedia.org/wiki/Angular_momentum", "http://hyperphysics.phy-astr.gsu.edu/hbase/amom.html", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/11%3A__Angular_Momentum/11.03%3A_Angular_Momentum"]'),
  ('angular_radius_of_the_airy_disk', '{"en-us": "Angular Radius Of The Airy Disk"}', 'diffraction', 8, '{"en-us": "Light focused through a circular aperture does not form a perfect point but a diffraction pattern whose bright central spot is the Airy disk. The angular radius measures the angle from the pattern''s center to the first dark ring, and it sets the diffraction-limited resolving power of telescopes, microscopes, and cameras via the Rayleigh criterion. Valid in the far field with the small-angle approximation."}', '["https://en.wikipedia.org/wiki/Airy_disk", "https://astronomy.swin.edu.au/cosmos/A/Airy+Disk", "https://astronomy.swin.edu.au/cosmos/R/Resolution"]'),
  ('angular_velocity_constant_acceleration', '{"en-us": "Angular velocity at constant angular acceleration"}', 'circular_motion', 6, '{"en-us": "This rotational kinematic relation gives the angular speed of a spinning body after a known time interval when its angular acceleration is constant. It is the exact rotational analogue of the straight-line motion equation for final velocity, obtained by replacing displacement, velocity, and acceleration with their angular counterparts. Commonly used for wheels, turbines, and other objects spun up or braked at a steady rate."}', '["https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/10%3A_Rotational_Motion_and_Angular_Momentum/10.02%3A_Kinematics_of_Rotational_Motion", "https://openstax.org/books/college-physics-2e/pages/10-2-kinematics-of-rotational-motion", "https://www.physicsclassroom.com/class/Balance-and-Rotation/Lesson-1-Rotational-Kinematics/Equations-of-Rotational-Kinematics"]'),
  ('angular_velocity_definition', '{"en-us": "Angular velocity definition"}', 'circular_motion', 4, '{"en-us": "Angular velocity measures how fast a body rotates: it is the angular displacement swept out per unit time, quoted in radians per second in SI. This ratio defines the average angular velocity over an interval; the instantaneous value is the limit of this ratio as the interval shrinks to zero. It is the rotational counterpart of linear speed and applies to wheels, gears, planets, and any spinning rigid body."}', '["https://en.wikipedia.org/wiki/Angular_velocity", "https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/06%3A_Uniform_Circular_Motion_and_Gravitation/6.01%3A_Rotation_Angle_and_Angular_Velocity", "https://www.grc.nasa.gov/www/k-12/airplane/angdva.html"]'),
  ('angular_velocity_squared_constant_acceleration', '{"en-us": "Angular velocity squared relation"}', 'circular_motion', 6, '{"en-us": "This rotational kinematic relation connects a spinning body''s initial and final angular speeds to the angle turned through, without involving the elapsed time. It holds only for constant angular acceleration and is the exact analogue of the corresponding straight-line motion equation, making it handy whenever the rotation time is unknown or irrelevant."}', '["https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/10%3A_Rotational_Motion_and_Angular_Momentum/10.02%3A_Kinematics_of_Rotational_Motion", "https://www.physicsclassroom.com/class/Balance-and-Rotation/Lesson-1-Rotational-Kinematics/Equations-of-Rotational-Kinematics", "https://unisium.io/guides/rotational-kinematics-3"]'),
  ('angular_wavenumber', '{"en-us": "Angular wavenumber from wavelength"}', 'mechanical_waves', 7, '{"en-us": "The angular wavenumber measures how rapidly a wave''s phase changes with position: it gives the number of radians contained in one metre of propagation path. It appears as the spatial factor kx in the sinusoidal expression of a travelling wave, plays the role of spatial frequency in the wave equation, and is proportional to photon momentum in quantum mechanics. It should not be confused with the spectroscopic wavenumber, which counts full cycles per unit distance instead of radians."}', '["https://en.wikipedia.org/wiki/Wavenumber", "https://www.rp-photonics.com/wavenumber.html", "https://brilliant.org/wiki/amplitude-frequency-wave-number-phase-shift", "https://byjus.com/physics/wave-number/"]'),
  ('annulus_sector_area', '{"en-us": "Area of an annular sector"}', 'circles', 6, '{"en-us": "An annular sector is the ring-shaped wedge bounded by two concentric circular arcs and two radial edges, like a bent strip cut from a washer. Its area grows linearly with the central angle and with the difference of the squares of the outer and inner radii, assuming both arcs share the same centre and the angle is expressed in radians. This shape arises in engineering calculations for washers, flange segments, and curved structural members."}', '["https://www.formuladen.com/en/area-of-annulus-sector-formula/Formula-30915", "https://www.redcrab-software.com/en/Calculator/Geometry/Annulus-Sector", "https://www.dalonmachinery.com/tools/calculators/area/annular-sector.php"]'),
  ('anti_reflective_coating_thickness', '{"en-us": "Anti-reflective coating condition"}', 'interference', 8, '{"en-us": "This gives the thinnest layer of a transparent material that suppresses reflection from a surface by destructive thin-film interference: light reflected from the top and bottom of the coating emerges half a wavelength out of phase and cancels. The result assumes normal incidence, a design wavelength in vacuum, and a coating whose refractive index lies between those of air and the substrate. Such quarter-wave coatings, typically magnesium fluoride on glass, are used on camera lenses, eyeglasses, and solar cells."}', '["https://en.wikipedia.org/wiki/Thin-film_interference", "http://labman.phys.utk.edu/phys136core/modules/m9/Thin%20films.html", "https://www.omnicalculator.com/physics/thin-film-optics"]'),
  ('apparent_depth_formula', '{"en-us": "Apparent depth formula"}', 'refraction', 6, '{"en-us": "When an object is viewed through a transparent medium such as water, refraction at the surface makes it appear shallower than it really is. This relation gives the apparent (perceived) depth in terms of the real depth and the refractive index of the medium, valid for near-normal viewing."}', '["https://phys.libretexts.org/Bookshelves/Optics/Geometric_Optics_(Tatum)/01%3A_Reflection_and_Refraction/1.04%3A_Real_and_Apparent_Depth", "https://openstax.org/books/university-physics-volume-3/pages/2-3-images-formed-by-refraction", "https://www.geeksforgeeks.org/physics/apparent-depth/", "https://testbook.com/physics/apparent-depth", "https://www.physicstutorials.org/optic/refraction-of-light/apparent-depth-real-depth/"]'),
  ('apparent_weight_fluid', '{"en-us": "Apparent weight in fluid"}', 'buoyancy', 6, '{"en-us": "An object submerged in a fluid weighs less on a scale than it does in air, because the fluid exerts an upward buoyant force (Archimedes'' principle). The apparent weight is what a scale reads while the object is immersed, and comparing it with the true weight is a standard way to measure an object''s volume or density."}', '["http://physics.bu.edu/~duffy/sc527_notes01/apparent_weight.html", "https://www.webassign.net/asucolphysmechl2/lab_8/manual.html", "https://jwu.pressbooks.pub/collegephysics/chapter/archimedes-principle/", "https://www.albert.io/blog/fluid-statics-and-buoyancy-ap-physics-2-review/"]'),
  ('arc_length', '{"en-us": "Arc length"}', 'circular_motion', 4, '{"en-us": "Gives the length of a circular arc as the radius multiplied by the central angle it subtends. The angle must be measured in radians; for angles in degrees the fraction of a full turn must be converted first. Widely used in geometry, trigonometry, and circular-motion kinematics."}', '["https://en.wikipedia.org/wiki/Circular_arc_length", "https://math.libretexts.org/Courses/Barton_Community_College/Book%3A_Technical_Mathematics_(Turner)/11%3A_Radian_Measure/11.02%3A_Arc_Length", "https://math.libretexts.org/Courses/Cosumnes_River_College/Math_375%3A_Pre-Calculus/04%3A_Radian_Measure_and_the_Circular_Functions/4.02%3A_Radian_Measure_and_Arc_Length", "https://www.mathwords.com/a/arc_circle.htm", "https://www.mathwarehouse.com/trigonometry/radians/s=r-theta-formula-equation.php"]'),
  ('area_annulus', '{"en-us": "Area of an annulus"}', 'circles', 4, '{"en-us": "An annulus is the ring-shaped region between two concentric circles. Its area equals the area of the outer disk minus that of the inner disk, so it depends only on the two radii. Used in geometry and engineering for washers, pipes, and circular rings."}', '["https://en.wikipedia.org/wiki/Annulus_(mathematics)", "https://mathworld.wolfram.com/Annulus.html", "https://www.mathsisfun.com/geometry/annulus.html", "https://www.mathwords.com/a/annulus.htm", "https://www.geeksforgeeks.org/maths/annulus-area-formula/"]'),
  ('area_circle', '{"en-us": "Area of a circle"}', 'circles', 2, '{"en-us": "Gives the region enclosed by a circle of a given radius. It is one of the most widely used formulas in geometry and appears throughout physics and engineering wherever circular cross-sections or rotational symmetry occur."}', '["https://en.wikipedia.org/wiki/Area_of_a_circle", "https://math.libretexts.org/Bookshelves/Geometry/Elementary_College_Geometry_(Africk)/07%3A_Regular_Polygons_and_Circles/7.06%3A_Area_of_a_Circle", "https://www.mathsisfun.com/geometry/circle-area.html", "https://www.mathwords.com/a/area_circle.htm"]'),
  ('area_ellipse', '{"en-us": "Area of an ellipse"}', 'plane_geometry', 4, '{"en-us": "Gives the region enclosed by an ellipse in terms of its two semi-axes. It generalizes the circle-area formula, reducing to the circle case when the two semi-axes are equal. Commonly used for orbital and architectural applications."}', '["https://en.wikipedia.org/wiki/Ellipse", "https://mathworld.wolfram.com/Ellipse.html", "https://www.mathwords.com/a/area_ellipse.htm", "https://www.mathsisfun.com/geometry/ellipse.html", "https://byjus.com/maths/area-of-ellipse/"]'),
  ('area_hexagon', '{"en-us": "Area of a regular hexagon"}', 'polygons', 4, '{"en-us": "Gives the region enclosed by a regular hexagon from its side length. The hexagon splits into six equilateral triangles, which is where the constant factor comes from; the result applies only to regular (equal-sided) hexagons."}', '["https://en.wikipedia.org/wiki/Regular_hexagon", "https://mathworld.wolfram.com/RegularHexagon.html", "https://proofwiki.org/wiki/Area_of_Regular_Hexagon", "https://www.cuemath.com/measurement/area-of-a-hexagon/", "https://www.math.net/hexagon"]'),
  ('area_kite', '{"en-us": "Area of a kite"}', 'plane_geometry', 3, '{"en-us": "A kite is a quadrilateral with two pairs of adjacent equal sides, whose diagonals intersect at right angles. Its area equals half the product of the diagonal lengths; the same relation also holds for any orthodiagonal quadrilateral, including the rhombus."}', '["https://en.wikipedia.org/wiki/Kite_(geometry)", "https://mathworld.wolfram.com/Kite.html", "https://www.mathwords.com/a/area_kite.htm", "https://www.cuemath.com/measurement/area-of-a-kite/", "https://byjus.com/maths/area-of-kite/"]'),
  ('area_rectangle', '{"en-us": "Area of a rectangle"}', 'plane_geometry', 1, '{"en-us": "Gives the region enclosed by a rectangle as the product of its two perpendicular side lengths. It is the most basic area formula and the basis for tiling arguments used to derive areas of triangles, parallelograms, and other shapes."}', '["https://en.wikipedia.org/wiki/Rectangle", "https://math.libretexts.org/Courses/Northwest_Florida_State_College/NWFSC_MGF_1130_Text/03%3A_Geometry/3.03%3A_Use_Properties_of_Rectangles_Triangles_and_Trapezoids", "https://brilliant.org/wiki/area-rectangles/", "https://www.mathwords.com/r/rectangle.htm"]'),
  ('area_regular_polygon', '{"en-us": "Area of a regular polygon"}', 'plane_geometry', 5, '{"en-us": "A regular polygon can be split into n congruent isosceles triangles whose height is the apothem, the perpendicular distance from the center to a side. Summing their areas gives half the apothem times the perimeter; it applies only to polygons with all sides and angles equal."}', '["https://mathworld.wolfram.com/RegularPolygon.html", "https://www.mathwords.com/a/area_regular_polygon.htm", "https://www.wikiwand.com/en/Apothem", "https://math.libretexts.org/Bookshelves/Applied_Mathematics/Technical_Mathematics_2e_(Chase)/01%3A_Sections/1.23%3A_Area_of_Regular_Polygons", "https://calcworkshop.com/polygons-circles/area-regular-polygon/"]'),
  ('area_sector', '{"en-us": "Area of a sector"}', 'circles', 4, '{"en-us": "A sector is the pie-slice region of a circle bounded by two radii and an arc. Its area is the fraction of the full circle corresponding to the central angle, which must be expressed in radians for this form of the relation."}', '["https://en.wikipedia.org/wiki/Circular_sector", "https://math.libretexts.org/Bookshelves/Precalculus/Elementary_Trigonometry_(Corral)/04%3A_Radian_Measure/4.03%3A_Area_of_a_Sector", "https://mathworld.wolfram.com/CircularSector.html", "https://www.cuemath.com/measurement/area-of-a-sector/", "https://www.omnicalculator.com/math/sector-area"]'),
  ('area_squere', '{"en-us": "Area of a square"}', 'plane_geometry', 1, '{"en-us": "Gives the region enclosed by a square from its single side length; since all four sides are equal, the area is the side multiplied by itself. It is the special case of the rectangle formula with equal sides and is the basis of square units of measurement."}', '["https://en.wikipedia.org/wiki/square", "https://mathworld.wolfram.com/Square.html", "https://www.mathsisfun.com/geometry/square.html", "https://www.mathwords.com/s/square.htm", "https://proofwiki.org/wiki/Area_of_Square"]'),
  ('area_thermal_expansion', '{"en-us": "Area thermal expansion"}', 'heat', 6, '{"en-us": "Describes how the surface area of a flat solid plate increases when heated. For an isotropic material the coefficient of area expansion equals twice the linear expansion coefficient, so the change in area can be computed directly from tabulated linear values. The relation is an approximation valid for small temperature changes."}', '["https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/13%3A_Temperature_Kinetic_Theory_and_the_Gas_Laws/13.02%3A_Thermal_Expansion_of_Solids_and_Liquids", "https://phys.libretexts.org/Bookshelves/University_Physics/Physics_(Boundless)/12:_Temperature_and_Kinetic_Theory/12.3:_Thermal_Expansion", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/01%3A_Temperature_and_Heat/1.04%3A_Thermal_Expansion"]'),
  ('area_trapezoid', '{"en-us": "Area of a trapezoid"}', 'plane_geometry', 3, '{"en-us": "Gives the area enclosed by a trapezoid, a quadrilateral with one pair of parallel sides called the bases. It can be interpreted as the average length of the two parallel sides taken over their perpendicular separation. Applies to any trapezoid (right, isosceles, or scalene) and underlies the trapezoidal rule used to approximate areas under curves."}', '["https://resources.wolframcloud.com/FormulaRepository/resources/Trapezoid-Area", "https://www.freemathhelp.com/area", "https://www.basic-mathematics.com/area-of-a-trapezoid.html", "https://www.calculatorsoup.com/calculators/geometry-plane/trapezoid.php"]'),
  ('area_triangle', '{"en-us": "Area of a triangle"}', 'triangles', 2, '{"en-us": "Gives the area enclosed by any triangle from the length of one side and the perpendicular distance of the opposite vertex from that side''s line. It reflects that a triangle occupies exactly half of the parallelogram or rectangle sharing its base and height. The height must be measured perpendicularly to the chosen base, even when it falls outside an obtuse triangle."}', '["https://en.wikipedia.org/wiki/Area_of_a_triangle", "https://www.mathopenref.com/trianglearea.html", "https://wumbo.net/formulas/area-of-triangle"]'),
  ('arithmetic_mean', '{"en-us": "Arithmetic mean"}', 'arithmetic', 2, '{"en-us": "The arithmetic mean is the most common measure of central tendency, obtained by summing the values in a data set and dividing by how many there are. For two values it gives their midpoint and is used everywhere from report grades to physical measurements. Unlike the median it is sensitive to extreme values, so outliers can pull it away from where most of the data lies."}', '["https://en.wikipedia.org/wiki/Arithmetic_mean", "https://www.mathwords.com/a/arithmetic_mean.htm", "https://www.cuemath.com/data/arithmetic-mean"]'),
  ('arithmetic_series_common_difference', '{"en-us": "Common difference of an arithmetic sequence"}', 'arithmetic', 3, '{"en-us": "The common difference is the constant that defines an arithmetic sequence: it is what each term exceeds the previous term by, and it must be identical for every consecutive pair of terms. A positive value gives a growing sequence, a negative value a decreasing one, and zero a constant sequence. Finding it from two neighboring terms is the first step in most arithmetic progression problems."}', '["https://en.wikipedia.org/wiki/Arithmetic_progression", "https://www.mathwords.com/c/common_difference.htm", "https://www.cuemath.com/algebra/common-difference/", "https://flexbooks.ck12.org/cbook/ck-12-cbse-math-class-10/section/5.2/primary/lesson/arithmetic-progression/"]'),
  ('arithmetic_series_nth_term', '{"en-us": "nth term of an arithmetic sequence"}', 'arithmetic', 3, '{"en-us": "Gives any term of an arithmetic sequence directly from its position, without listing all preceding terms. It reflects that reaching position n requires adding the common difference one fewer times than the position number, since the first term already occupies position one. Also known as the explicit or general-term formula of an arithmetic progression."}', '["https://en.wikipedia.org/wiki/Arithmetic_progression", "https://www.mathwords.com/a/arithmetic_sequence.htm", "https://www.cuemath.com/algebra/nth-term-of-an-ap/"]'),
  ('arithmetic_series_sum', '{"en-us": "Sum of arithmetic series"}', 'arithmetic', 4, '{"en-us": "Gives the total when the terms of an arithmetic sequence are added together. It works by pairing terms from opposite ends of the series, a technique famously used by Gauss as a schoolboy, so the sum equals the number of terms times the average of the first and last term. Applies to any finite arithmetic series, whether the terms grow or shrink."}', '["https://mathworld.wolfram.com/ArithmeticSeries.html", "https://www.cuemath.com/sum-of-arithmetic-sequence-formula/", "https://mathbitsnotebook.com/Algebra2/Sequences/SSGauss.html"]'),
  ('arrhenius_activation_energy', '{"en-us": "Arrhenius activation energy from two temperatures"}', 'chemical_kinetics', 8, '{"en-us": "Determines a reaction''s activation energy from kinetic measurements taken at just two temperatures, eliminating the need to know the pre-exponential factor or draw an Arrhenius plot. It follows by subtracting the linearized Arrhenius expressions at the two conditions, so both temperatures must be in kelvin and distinct. Widely used in chemical kinetics to characterize the energy barrier of a reaction."}', '["https://en.wikipedia.org/wiki/Arrhenius_equation", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_%28Physical_and_Theoretical_Chemistry%29/Kinetics/06%3A_Modeling_Reaction_Kinetics/6.02%3A_Temperature_Dependence_of_Reaction_Rates/6.2.03%3A_The_Arrhenius_Law/6.2.3.03%3A_The_Arrhenius_Law-_Activation_Energies", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_%28Physical_and_Theoretical_Chemistry%29/Kinetics/06%3A_Modeling_Reaction_Kinetics/6.02%3A_Temperature_Dependence_of_Reaction_Rates/6.2.03%3A_The_Arrhenius_Law/6.2.3.01%3A_Arrhenius_Equation", "https://www.vcalc.com/wiki/activation-energy-arrhenius-equation"]'),
  ('arrhenius_equation', '{"en-us": "Arrhenius equation"}', 'chemical_kinetics', 7, '{"en-us": "Central relation of chemical kinetics, giving the temperature dependence of a reaction''s rate constant. It combines the collision frequency with an exponential Boltzmann-type factor for the fraction of molecules able to surmount the activation energy barrier, so rates rise steeply with temperature. Assumes a constant activation energy and pre-exponential factor over the temperature range considered."}', '["https://en.wikipedia.org/wiki/Arrhenius_equation", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_%28Physical_and_Theoretical_Chemistry%29/Kinetics/06%3A_Modeling_Reaction_Kinetics/6.02%3A_Temperature_Dependence_of_Reaction_Rates/6.2.03%3A_The_Arrhenius_Law/6.2.3.01%3A_Arrhenius_Equation", "https://sciencenotes.org/arrhenius-equation-definition-formula-and-applications/", "https://www.sciencedirect.com/topics/engineering/arrhenius-equation"]'),
  ('atom_economy', '{"en-us": "Atom economy"}', 'chemical_reactions', 6, '{"en-us": "A green-chemistry metric, introduced by Barry Trost, that measures what fraction of the reactant mass ends up incorporated into the desired product rather than waste by-products. Unlike percentage yield, it can be assessed from the balanced equation alone and is used to compare alternative synthetic routes for sustainability."}', '["https://www.bbc.co.uk/bitesize/guides/zg9rxfr/revision/2", "https://www.omnicalculator.com/chemistry/atom-economy", "https://www.pearson.com/channels/calculators/atom-economy-calculator", "https://www.studypug.com/us/chemistry/percentage-yield-and-atom-economy?view=read"]'),
  ('atomic_bohr_model_velocity', '{"en-us": "Bohr model electron velocity"}', 'atomic_physics', 8, '{"en-us": "Gives the orbital speed of the electron in the nth circular orbit of Bohr''s model of hydrogen, obtained by combining Coulomb attraction with quantized angular momentum. The speed falls off inversely with orbit number and is largest in the ground state, remaining safely below the speed of light for hydrogen. Applies to hydrogen-like single-electron atoms within the semiclassical Bohr approximation."}', '["https://en.m.wikipedia.org/wiki/Bohr_model", "https://learn.careers360.com/school/question-using-bohrrsquos-atomic-model-derive-the-expression-for-the-velocity-of-electron-revolving-in-the-nth-orbit-of-hydrogen-atom-113017", "https://www.physicsforums.com/threads/derivation-of-velocity-in-nth-bohr-orbit.481997"]'),
  ('atomic_fine_structure_definition', '{"en-us": "Fine-structure constant"}', 'atomic_physics', 9, '{"en-us": "A fundamental dimensionless constant characterizing the strength of the electromagnetic interaction between elementary charged particles. Named for its role in explaining the fine splitting of atomic spectral lines, it also equals the ratio of the electron''s ground-state Bohr-orbit speed to the speed of light, and its smallness (about one over 137) underlies the success of perturbation methods in quantum electrodynamics."}', '["https://en.wikipedia.org/wiki/Fine-structure_constant", "https://physics.nist.gov/cuu/Constants/alpha.html", "https://www.britannica.com/science/fine-structure-constant", "https://sciencenotes.org/fine-structure-constant"]'),
  ('atomic_mass_defect', '{"en-us": "Atomic mass defect"}', 'atomic_structure', 8, '{"en-us": "The mass defect of an atomic nucleus is the amount by which the nucleus''s actual mass falls short of the combined mass of its separated protons and neutrons. This missing mass was converted to binding energy when the nucleus formed, so multiplying the defect by the speed of light squared gives the nuclear binding energy."}', '["https://www.geeksforgeeks.org/physics/how-to-calculate-mass-defect/", "https://www.miniphysics.com/mass-defect.html", "https://scienceinsights.org/how-to-calculate-mass-defect-formula-and-examples/", "https://www.aakash.ac.in/important-concepts/physics/mass-defect-and-binding-energy"]'),
  ('atomic_number_formula', '{"en-us": "Atomic number"}', 'atomic_structure', 3, '{"en-us": "The atomic number of an element equals the number of protons in the nucleus of each of its atoms, which also gives the nuclear charge. It uniquely identifies the chemical element and fixes its position on the periodic table; in a neutral atom it additionally equals the number of electrons."}', '["https://en.wikipedia.org/wiki/Atomic_number", "https://chem.libretexts.org/Bookshelves/Introductory_Chemistry/Introductory_Chemistry_(CK-12)/04%3A_Atomic_Structure/4.16%3A_Atomic_Number", "https://www.britannica.com/science/atomic-number", "https://sciencenotes.org/what-is-an-atomic-number-definition-and-examples/"]'),
  ('atomic_rydberg_energy_unit', '{"en-us": "Rydberg unit of energy"}', 'atomic_physics', 9, '{"en-us": "The Rydberg unit of energy is the photon energy corresponding to the Rydberg constant, i.e. the ionization energy of a ground-state hydrogen atom in the Bohr model, about 13.6 eV. It serves as a convenient natural energy unit for atomic spectra and hydrogen-like atoms."}', '["https://en.wikipedia.org/wiki/Rydberg_constant", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Book%3A_Quantum_States_of_Atoms_and_Molecules_%28Zielinksi_et_al%29/02%3A_Foundations_of_Quantum_Mechanics/2.07%3A_Derivation_of_the_Rydberg_Equation_from_Bohr%27s_Model", "https://energywavetheory.com/physics-constants/rydberg-unit-of-energy/", "https://scienceworld.wolfram.com/physics/Rydberg.html"]'),
  ('average_atomic_mass', '{"en-us": "Average atomic mass"}', 'atomic_structure', 5, '{"en-us": "The average atomic mass of an element is the weighted mean of the masses of its naturally occurring isotopes, each weighted by its fractional abundance in nature (the fractions must sum to one). It is the decimal mass value quoted on the periodic table and is used for stoichiometry with naturally mixed samples."}', '["https://chem.libretexts.org/Courses/University_of_Arkansas_Little_Rock/Chem_1402%3A_General_Chemistry_1_(Kattoum)/Text/2%3A_Atoms%2C_Molecules%2C_and_Ions/2.03%3A_Isotopic_Abundance_and_Atomic_Weight", "https://chem.libretexts.org/Bookshelves/Introductory_Chemistry/Introductory_Chemistry_(CK-12)/04%3A_Atomic_Structure/4.20%3A_Calculating_Average_Atomic_Mass", "https://biologyinsights.com/how-to-calculate-isotopes-and-average-atomic-mass/", "https://www.wikihow.com/Find-Average-Atomic-Mass"]'),
  ('average_force_impulse', '{"en-us": "Average force from impulse"}', 'impulse', 5, '{"en-us": "By the impulse-momentum theorem, the constant net force that would produce the same momentum change as a real (time-varying) force is found by dividing that momentum change by the contact time. This average force is widely used to analyze collisions and impacts, such as estimating forces in crashes or ball strikes."}', '["https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/08%3A_Linear_Momentum_and_Collisions/8.02%3A_Impulse", "https://en.wikipedia.org/wiki/Impulse_%28physics%29", "https://www.vedantu.com/jee-main/physics-average-force-formula"]'),
  ('average_kinetic_energy_molecule', '{"en-us": "Average kinetic energy per molecule"}', 'ideal_gases', 7, '{"en-us": "Kinetic theory shows that the mean translational kinetic energy of a single molecule in an ideal gas is fixed solely by the absolute temperature, with each of the three translational degrees of freedom contributing half of Boltzmann constant times temperature (equipartition). Notably it does not depend on the molecule''s mass or identity."}', '["https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Physical_Chemistry_(LibreTexts)/27%3A_The_Kinetic_Theory_of_Gases/27.01%3A_The_Average_Translational_Kinetic_Energy_of_a_Gas", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/02%3A_The_Kinetic_Theory_of_Gases/2.06%3A_The_Kinetic_Theory_of_Gases_(Summary)", "https://phys.libretexts.org/Bookshelves/University_Physics/Physics_(Boundless)/12:_Temperature_and_Kinetic_Theory/12.5:_Kinetic_Theory"]'),
  ('average_speed_maxwell_boltzmann', '{"en-us": "Average speed from Maxwell-Boltzmann distribution"}', 'ideal_gases', 8, '{"en-us": "This gives the mean molecular speed of a gas obtained by averaging over the Maxwell-Boltzmann speed distribution at absolute temperature. The average speed always lies between the most probable speed and the root-mean-square speed, and it grows with temperature while shrinking for heavier gases."}', '["https://en.wikipedia.org/wiki/Maxwell%E2%80%93Boltzmann_distribution", "https://chem.libretexts.org/Courses/City_College_of_San_Francisco/Chemistry_101A/03%3A_Topic_C-_Gas_Laws_and_Kinetic_Molecular_Theory/3.01%3A_Gases/3.1.10%3A_Molecular_Speed_Distribution", "https://completeera.com/maxwell-boltzmann-distribution-calculating-the-average-molecular-speed/"]'),
  ('average_velocity', '{"en-us": "Average velocity"}', 'constant_acceleration', 3, '{"en-us": "Average velocity is defined as the displacement of an object divided by the elapsed time during which that displacement occurs. It is a vector, so it carries direction and can be negative or zero even when motion occurred; it differs from average speed, which uses total path distance."}', '["https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_%28OpenStax%29/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_%28OpenStax%29/03%3A_Motion_Along_a_Straight_Line/3.02%3A_Position_Displacement_and_Average_Velocity", "https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_%28OpenStax%29/02%3A_Kinematics/2.03%3A_Time_Velocity_and_Speed", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Dourmashkin)/04%3A_One_Dimensional_Kinematics/4.03%3A_Velocity", "https://openstax.org/books/university-physics-volume-1/pages/3-1-position-displacement-and-average-velocity"]'),
  ('average_velocity_definition_general', '{"en-us": "Average velocity definition"}', 'constant_acceleration', 3, '{"en-us": "This is the general definition of average velocity for motion between two instants: the change in displacement over that interval divided by the corresponding elapsed time. Because it uses displacement, it is directional and can differ from the path length divided by the time."}', '["https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_%28OpenStax%29/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_%28OpenStax%29/03%3A_Motion_Along_a_Straight_Line/3.02%3A_Position_Displacement_and_Average_Velocity", "https://openstax.org/books/university-physics-volume-1/pages/3-1-position-displacement-and-average-velocity", "https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_%28OpenStax%29/02%3A_Kinematics/2.03%3A_Time_Velocity_and_Speed"]'),
  ('average_velocity_initial_final', '{"en-us": "Average velocity from initial and final"}', 'constant_acceleration', 3, '{"en-us": "For motion with constant acceleration, the average velocity over an interval equals the arithmetic mean of the initial and final velocities. This shortcut is valid only when acceleration is uniform; with varying acceleration the average must be computed from displacement and time instead."}', '["https://www.vedantu.com/jee-main/physics-average-velocity-formula", "https://www.azcalculator.com/calculators/constant-acceleration-average-velocity", "https://answers.completeera.com/post/how-to-find-initial-velocity-and-final-velocity-kinematics-made-simple"]'),
  ('avogadros_law_molar_volume', '{"en-us": "Molar volume at STP from Avogadro''s law"}', 'ideal_gases', 5, '{"en-us": "By Avogadro''s law, gas volume is proportional to the number of moles at fixed temperature and pressure, so the volume occupied by one mole of any ideal gas is a universal quantity. At standard temperature and pressure this molar volume is essentially identical for all ideal gases (about 22.4 L/mol), which makes it a staple conversion factor in gas stoichiometry."}', '["https://www.thermal-engineering.org/what-is-molar-volume-of-gases-22-4-l-mol-definition", "https://www.vedantu.com/chemistry/avogadro-law", "https://www.alloprof.qc.ca/en/students/vl/chemistry/the-molar-volume-of-gas-c1012", "https://www.physicsclassroom.com/Chemistry-Tutorial/Gases-and-Gas-Laws/Volume-and-the-Number-of-Moles"]'),
  ('banking_angle', '{"en-us": "Banking angle"}', 'circular_motion', 7, '{"en-us": "For a curve banked at the ideal angle, the horizontal component of the normal force alone supplies the required centripetal force, so a vehicle can round the turn without relying on friction. The tangent of that banking angle depends only on the travel speed, the radius of curvature, and gravitational acceleration; it is used in highway and racetrack design and in analyzing aircraft banked turns."}', '["https://en.wikipedia.org/wiki/Banked_turn", "https://livephysics.com/cheat-sheets/physics-banked-curve-design-reference/", "https://www.vedantu.com/formula/banking-of-road-formula"]'),
  ('bayes_factor', '{"en-us": "Bayes factor"}', 'probability', 9, '{"en-us": "The Bayes factor quantifies the relative evidence that observed data provide for one hypothesis or model over another, expressed as the ratio of their marginal likelihoods. It acts as the Bayesian alternative to the p-value in hypothesis testing and model comparison: values above 1 support the hypothesis in the numerator, values below 1 support the denominator hypothesis."}', '["https://en.wikipedia.org/wiki/Bayes_factor", "https://easystats.github.io/bayestestR/articles/bayes_factors.html", "https://plato.stanford.edu/entries/bayes-theorem", "https://metricgate.com/docs/bayes-factor"]'),
  ('bayes_theorem', '{"en-us": "Bayes'' theorem"}', 'probability', 7, '{"en-us": "Bayes'' theorem describes how to update the probability of a hypothesis when new evidence is observed, relating the posterior probability to the likelihood, the prior, and the total probability of the evidence. It is the foundation of Bayesian inference and is widely used in statistics, medical diagnosis, spam filtering, and machine learning. The denominator acts as a normalizing constant and must be nonzero."}', '["https://en.wikipedia.org/wiki/Bayes%27_theorem", "https://plato.stanford.edu/entries/bayes-theorem", "https://testbook.com/maths-formulas/bayes-theorem-formula", "https://statisticsfundamentals.com/statistics-and-probability/bayes-theorem/"]'),
  ('beat_frequency', '{"en-us": "Beat frequency"}', 'wave_interference', 6, '{"en-us": "When two waves of slightly different frequencies overlap, their superposition produces a periodic rise and fall in amplitude called beats. The beat frequency counts how many amplitude maxima occur per second and equals the magnitude of the difference between the two wave frequencies, which is why the result must be non-negative. It is commonly used for tuning musical instruments and comparing nearby frequencies."}', '["https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/17%3A_Sound/17.07%3A_Beats", "https://phys.libretexts.org/Courses/University_of_California_Davis/UCD%3A_Physics_7C_-_General_Physics/8%3A_Waves/8.6%3A_Beats", "http://hyperphysics.phy-astr.gsu.edu/hbase/Sound/beat.html", "https://www.geeksforgeeks.org/physics/beat-frequency-formula/"]'),
  ('beer_lambert_law', '{"en-us": "Beer-Lambert law"}', 'analytical_chemistry', 7, '{"en-us": "The Beer-Lambert law states that the absorbance of monochromatic light by a solution is directly proportional to the concentration of the absorbing species and the optical path length through the sample. It is the basis of quantitative spectrophotometry and colorimetric analysis. The linear relation holds for dilute, homogeneous, non-scattering samples and breaks down at high concentrations."}', '["https://biologynotesonline.com/beer-lambert-law", "https://www.calctool.org/optics/beer-lambert-law", "https://resources.wolframcloud.com/FormulaRepository/resources/BeerLambert-Law-With-Decadic-Absorbance", "https://www.scienceabc.com/pure-sciences/what-is-beers-law"]'),
  ('bernoulli_differential_equation', '{"en-us": "Bernoulli differential equation"}', 'differential_equations', 9, '{"en-us": "The Bernoulli differential equation is a first-order ordinary differential equation, named after Jacob Bernoulli, that is nonlinear unless the exponent on the dependent variable is zero or one. It is solved by the substitution u = y^(1-n), which converts it into a linear differential equation solvable with an integrating factor. The logistic equation is a notable special case."}', '["https://en.wikipedia.org/wiki/Bernoulli_differential_equation", "https://tutorial.math.lamar.edu/Classes/DE/Bernoulli.aspx", "https://mathsisfun.org/calculus/differential-equations-bernoulli"]'),
  ('bernoulli_energy_head_form', '{"en-us": "Bernoulli energy head form"}', 'bernoulli_equation', 7, '{"en-us": "This is the head form of Bernoulli''s equation, obtained by dividing each energy term by the fluid''s specific weight so that every term has dimensions of length (energy per unit weight). The three heads are the pressure head, velocity head, and elevation head, and their sum — the total head — stays constant along a streamline for steady, incompressible, inviscid flow. It is widely used in hydraulics and civil engineering, e.g. for the energy grade line."}', '["https://en.wikipedia.org/wiki/Bernoulli%27s_principle", "https://whatispiping.com/bernoullis-equation-principle-examples/", "https://miniwebtool.com/bernoulli-equation-calculator", "https://engineeringhulk.com/civil/fluid-mechanics-hydraulics/bernoullis-equation/"]'),
  ('bernoulli_horizontal_flow', '{"en-us": "Bernoulli''s equation for horizontal flow"}', 'bernoulli_equation', 7, '{"en-us": "Special case of Bernoulli''s equation at constant height (Bernoulli''s principle); valid for steady, incompressible, inviscid flow along a horizontal streamline. With the elevation terms gone, it shows that where the fluid speed increases the static pressure must decrease. It underlies venturi meters, atomizers, and airfoil lift arguments."}', '["https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/12%3A_Fluid_Dynamics_and_Its_Biological_and_Medical_Applications/12.02%3A_Bernoullis_Equation", "https://www.engineeringtoolbox.com/bernouilli-equation-d_183.html", "https://www.ajdesigner.com/bernoulli"]'),
  ('bernoulli_pressure_velocity_horizontal', '{"en-us": "Bernoulli: pressure-velocity relation (horizontal)"}', 'bernoulli_equation', 7, '{"en-us": "For steady, inviscid, incompressible flow along a horizontal streamline, this rearranged form of Bernoulli''s equation links the static-pressure drop between two points to the increase in flow speed between them. It quantifies Bernoulli''s principle: faster flow occurs where pressure is lower. It assumes equal elevation at both points and no viscous losses."}', '["https://en.wikipedia.org/wiki/Bernoulli%27s_principle", "https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/12%3A_Fluid_Dynamics_and_Its_Biological_and_Medical_Applications/12.02%3A_Bernoullis_Equation", "https://www.engineeringtoolbox.com/bernouilli-equation-d_183.html"]'),
  ('bernoulli_stagnation_pressure', '{"en-us": "Bernoulli stagnation pressure"}', 'bernoulli_equation', 7, '{"en-us": "Stagnation pressure (total pressure) is the pressure a flowing fluid reaches when it is brought to rest, converting its kinetic energy into pressure. It equals the sum of the static pressure and the dynamic pressure of the stream. Valid for steady, incompressible, inviscid flow along a streamline with negligible height change; measured by pitot tubes."}', '["https://en.wikipedia.org/wiki/Stagnation_pressure", "https://en.wikipedia.org/wiki/Dynamic_pressure", "https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/bernoullis-equation/"]'),
  ('bernoullis_equation', '{"en-us": "Bernoulli''s equation"}', 'bernoulli_equation', 7, '{"en-us": "Bernoulli''s equation is the statement of conservation of mechanical energy for a flowing fluid: the sum of static pressure, dynamic pressure, and hydrostatic pressure is the same at any two points along a streamline. It holds for steady, incompressible, inviscid flow and underlies analyses of pipe flow, venturi meters, and airfoil lift."}', '["https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/12%3A_Fluid_Dynamics_and_Its_Biological_and_Medical_Applications/12.02%3A_Bernoullis_Equation", "https://courses.lumenlearning.com/suny-osuniversityphysics/chapter/14-6-bernoullis-equation", "https://www.engineeringtoolbox.com/bernouilli-equation-d_183.html"]'),
  ('binomial_expansion_cubed_diff', '{"en-us": "Binomial Expansion (Cubed Difference)"}', 'polynomials', 5, '{"en-us": "This algebraic identity, also known as the cube of a difference, expands the cube of a two-term binomial where one term is subtracted from the other. It is a special case of the binomial theorem with alternating signs and is used to expand expressions, factor cubics, and simplify mental arithmetic such as cubing numbers near round values."}', '["https://www.cuemath.com/a-b-cube-formula", "https://proofwiki.org/wiki/Cube_of_Difference", "https://onlinemschool.com/math/library/multiplication_formulas/dif3/", "https://www.math-only-math.com/cube-of-the-difference-of-two-binomials.html"]'),
  ('binomial_probability', '{"en-us": "Binomial probability mass function"}', 'probability', 7, '{"en-us": "The binomial probability mass function gives the probability of observing exactly a specified number of successes in a fixed number of independent trials, each with the same success probability and only two possible outcomes. It applies when the trials are binary, independent, fixed in number, and identically distributed (the BINS conditions), and is used in quality control, survey sampling, and genetics."}', '["https://en.wikipedia.org/wiki/Binomial_distribution", "https://statisticsfundamentals.com/binomial-distribution/", "https://www.mathwords.com/b/binomial_probability_formula.htm", "https://statproofbook.github.io/P/bin-pmf.html"]'),
  ('binomial_theorem_cubed', '{"en-us": "Binomial Theorem (Cubed)"}', 'polynomials', 5, '{"en-us": "The cube of a sum of two terms expands into a four-term polynomial with coefficients 1, 3, 3, 1 taken from Pascal''s triangle. This special case of the binomial theorem (n = 3) is used to expand or factor cubic expressions in algebra."}', '["https://en.wikipedia.org/wiki/Binomial_theorem", "https://proofwiki.org/wiki/Binomial_Theorem/Examples/Cube_of_Sum", "https://www.mathsisfun.com/algebra/binomial-theorem.html", "https://www.geeksforgeeks.org/maths/cube-of-binomial/", "https://www.vedantu.com/maths/cube-of-a-binomial", "https://openstax.org/books/algebra-and-trigonometry/pages/13-6-binomial-theorem"]'),
  ('biochemical_lineweaver_burk_slope', '{"en-us": "Lineweaver-Burk plot slope"}', 'biochemistry', 8, '{"en-us": "The slope of the Lineweaver-Burk plot, the double-reciprocal linearization of the Michaelis-Menten equation used in enzyme kinetics. It relates the Michaelis constant to the maximum reaction velocity and lets both parameters be read off a straight line fitted to rate data; how inhibitors change this slope helps classify competitive, uncompetitive, and mixed inhibition."}', '["https://en.wikipedia.org/wiki/Lineweaver-Burk_plot", "https://www.medschoolcoach.com/mcat/lineweaver-burk-plots", "https://employees.csbsju.edu/cschaller/Reactivity/kinetics/arkenzymelb.htm", "https://www.pearson.com/channels/biochemistry/learn/jason/enzymes-and-enzyme-kinetics/lineweaver-burk-plot"]'),
  ('biot_savart_law', '{"en-us": "Biot-Savart law (current element)"}', 'magnetism', 8, '{"en-us": "Valid for steady currents; gives the magnetic field contribution from a current element dℓ carrying current I."}', '["https://en.wikipedia.org/wiki/Biot%E2%80%93Savart_law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields/12.02%3A_The_Biot-Savart_Law", "https://brilliant.org/wiki/biot-savart-law/", "https://www.vedantu.com/jee-main/physics-biot-savart-law"]'),
  ('blackbody_radiation_peak_frequency', '{"en-us": "Peak frequency of blackbody radiation"}', 'quantum_mechanics', 8, '{"en-us": "Valid for blackbody radiation; relates peak emission frequency to temperature."}', '["https://en.wikipedia.org/wiki/Wien%27s_displacement_law", "https://en.wikipedia.org/wiki/Planck%27s_law_of_black-body_radiation", "https://astronomy.stackexchange.com/questions/55956/wiens-law-gives-two-different-results", "http://math_research.uct.ac.za/~siphelo/admin/interferometry/1_Radio_Science/01_05_black_body_radiation.html"]'),
  ('bohr_magneton_definition', '{"en-us": "Bohr magneton"}', 'atomic_physics', 9, '{"en-us": "The Bohr magneton is a physical constant serving as the natural unit for the magnetic dipole moment of an electron caused by its orbital or spin angular momentum. It is used throughout atomic physics and quantum chemistry to express electron magnetic moments and to analyze paramagnetic and Zeeman-effect behavior."}', '["https://en.wikipedia.org/wiki/Bohr_magneton", "https://goldbook.iupac.org/terms/view/B00692", "https://proofwiki.org/wiki/Definition%3ABohr_Magneton", "https://jila.colorado.edu/~ajsh/courses/astr5110_24/notes/spin.pdf"]'),
  ('bohr_orbital_radius_n', '{"en-us": "Bohr orbital radius"}', 'atomic_physics', 8, '{"en-us": "Gives the radius of the electron''s allowed circular orbit in Bohr''s model of the hydrogen atom, which grows with the square of the principal quantum number. The innermost orbit (n = 1) equals the Bohr radius, and for hydrogen-like ions the orbit radii are reduced in proportion to the nuclear charge number."}', '["https://openstax.org/books/college-physics-2e/pages/30-3-bohrs-theory-of-the-hydrogen-atom", "https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/30%3A_Atomic_Physics/30.03%3A_Bohrs_Theory_of_the_Hydrogen_Atom", "https://openstax.org/books/chemistry-2e/pages/6-2-the-bohr-model", "https://en.wikipedia.org/wiki/Bohr_Radius"]'),
  ('bohr_radius', '{"en-us": "Bohr radius"}', 'atomic_physics', 8, '{"en-us": "The Bohr radius is the characteristic length scale of the hydrogen atom, equal to the most probable distance between the nucleus and the electron in the ground state of Bohr''s model. It serves as the atomic unit of length and fixes the size scale of hydrogen-like atoms."}', '["https://en.wikipedia.org/wiki/Bohr_radius", "https://goldbook.iupac.org/terms/view/B00693", "http://www.physicsbootcamp.org/sec-The-Bohr-Model.html", "https://math.stackexchange.com/questions/3637424/bohr-radius-of-an-atom"]'),
  ('boiling_point_elevation', '{"en-us": "Boiling point elevation"}', 'solutions', 7, '{"en-us": "A colligative property of dilute ideal solutions: dissolving a nonvolatile solute raises the boiling point of a solvent in proportion to the molal concentration of dissolved particles. It is used in ebullioscopy to estimate molar masses of solutes and their degree of dissociation into ions."}', '["https://en.m.wikipedia.org/wiki/Boiling-point_elevation", "https://en.wikipedia.org/wiki/Ebullioscopic_constant", "https://www.chemteam.info/Solutions/BP-elevation.html", "https://www.omnicalculator.com/chemistry/boiling-point-elevation"]'),
  ('boltzmann_entropy_formula', '{"en-us": "Boltzmann''s entropy formula"}', 'entropy', 9, '{"en-us": "The foundational relation of statistical mechanics, connecting the thermodynamic entropy of a system to the number of microscopic arrangements (microstates) consistent with its observed macrostate. It assumes all accessible microstates are equally probable and is engraved on Boltzmann''s tombstone."}', '["https://en.wikipedia.org/wiki/Boltzmann_entropy_formula", "https://en.wikipedia.org/wiki/Entropy_(statistical_thermodynamics)", "https://chem.libretexts.org/Courses/University_of_Wisconsin_Oshkosh/Chem_370%3A_Physical_Chemistry_1_-_Thermodynamics_(Gutow)/01%3A_Thermodynamics/1.05%3A_The_Boltzmann_Distribution_and_the_Statistical_Definition_of_Entropy", "https://barbatti.org/2022/05/23/is-boltzmanns-s-k-log-w-right/"]'),
  ('boltzmann_factor', '{"en-us": "Boltzmann factor"}', 'entropy', 8, '{"en-us": "Gives the relative probability that a system in thermal equilibrium at a given temperature occupies a state of a given energy: states of higher energy are exponentially less populated. This unnormalized weight is the building block of the Boltzmann distribution and the partition function in statistical mechanics."}', '["https://en.wikipedia.org/wiki/Boltzmann_distribution", "https://encyclopediaofmath.org/wiki/Boltzmann_weight", "https://courses.physics.illinois.edu/phys213/su2024/prelecture11.pdf", "https://chem.libretexts.org/Courses/Knox_College/Chem_321%3A_Physical_Chemistry_I/05%3A_Boltzmann/5.02%3A_The_Thermal_Boltzman_Distribution"]'),
  ('bond_dissociation_energy', '{"en-us": "Bond Dissociation Energy"}', 'chemical_bonding', 6, '{"en-us": "Estimates the enthalpy change of a reaction from bond dissociation energies: breaking bonds in the reactants absorbs energy while forming bonds in the products releases it. Since tabulated bond energies are averages over many molecules, the result is an approximation that works best for gas-phase reactions."}', '["https://chem.libretexts.org/Courses/University_of_Toronto/Chemistry%3A_Physical_Principles/05%3A_Thermochemistry/5.07%3A_Bond_Energies", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/10%3A_Chemical_Bonding_I%3A_Basic_Concepts/10.9%3A_Bond_Energies", "https://wisc.pb.unizin.org/minimisgenchem/chapter/bond-length-and-strength-m8q4/", "https://www.chadsprep.com/chads-general-chemistry-videos/bond-enthalpies/"]'),
  ('bond_order', '{"en-us": "Bond order"}', 'chemical_bonding', 6, '{"en-us": "In molecular orbital theory, bond order measures the net bonding between two atoms from the electron populations of the bonding and antibonding orbitals. It serves as an index of bond strength and stability: bond orders of one, two, and three correspond to single, double, and triple bonds, while a value of zero predicts that the species will not exist."}', '["https://en.wikipedia.org/wiki/Bond_order", "https://openstax.org/books/chemistry-2e/pages/8-4-molecular-orbital-theory", "https://chem.libretexts.org/Courses/CSU_Fullerton/Chem_325%3A_Inorganic_Chemistry_(Cooley)/02%3A_Molecules/2.06%3A_Molecular_Orbital_Theory", "https://chem-textbook.ucalgary.ca/version2/chapter-8-main/molecular-orbital-theory/bond-order/"]'),
  ('born_rule_quantum', '{"en-us": "Born rule for probability density"}', 'quantum_mechanics', 9, '{"en-us": "The Born rule links the quantum wavefunction to measurable outcomes: the probability density for finding a particle at a given position equals the squared magnitude of the normalized wavefunction at that point. It was formulated by Max Born in 1926 and underlies nearly all probabilistic predictions of quantum mechanics."}', '["https://en.wikipedia.org/wiki/Born_rule", "https://en.wikipedia.org/wiki/Born_probability", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Physical_Chemistry_(LibreTexts)/03%3A_The_Schrodinger_Equation_and_a_Particle_in_a_Box/3.04%3A_Wavefunctions_Have_a_Probabilistic_Interpretation", "https://www.physicsbook.gatech.edu/The_Born_Rule"]'),
  ('boyles_law', '{"en-us": "Boyle''s law"}', 'ideal_gases', 5, '{"en-us": "Boyle''s law states that for a fixed amount of gas held at constant temperature, the pressure is inversely proportional to the volume, so the pressure-volume product stays constant between two states. It holds exactly only for an ideal gas; real gases follow it closely at low pressures."}', '["https://en.wikipedia.org/wiki/Boyle%27s_law", "https://www.britannica.com/science/Boyles-law", "https://chem.libretexts.org/Courses/Napa_Valley_College/Chem_110%3A_Introductory_Chemistry/14%3A_Gases/14.04%3A_Boyles_Law_-_Pressure_and_Volume", "https://chem-textbook.ucalgary.ca/chapter-9-main/volume-and-pressure-boyles-law/"]'),
  ('braggs_law', '{"en-us": "Bragg''s law"}', 'atomic_physics', 8, '{"en-us": "Bragg''s law gives the condition for constructive interference of waves (typically X-rays) scattered by successive planes of atoms in a crystal: diffraction peaks occur only when the extra path difference between neighboring planes is a whole number of wavelengths. It is the basis of X-ray crystallography for determining crystal structures."}', '["https://en.wikipedia.org/wiki/Bragg_law", "https://www.britannica.com/science/Bragg-law", "https://eng.libretexts.org/Bookshelves/Materials_Science/Supplemental_Modules_(Materials_Science)/Electronic_Properties/X-ray_diffraction_Bragg%27s_law_and_Laue_equation", "https://phys.libretexts.org/Courses/Bowdoin_College/Phys1140%3A_Introductory_Physics_II%3A_Part_2/04%3A_Diffraction/4.07%3A_X-Ray_Diffraction", "https://serc.carleton.edu/research_education/geochemsheets/BraggsLaw.html"]'),
  ('bright_fringe_double_slit_position', '{"en-us": "Position of bright fringes in double-slit"}', 'diffraction', 7, '{"en-us": "In Young''s double-slit experiment this gives how far from the central maximum the m-th bright fringe appears on a screen. It follows from the constructive-interference path-difference condition combined with the small-angle approximation, valid when the screen distance is much larger than the slit separation."}', '["https://openstax.org/books/college-physics-2e/pages/27-3-youngs-double-slit-experiment", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/03%3A_Interference/3.02%3A_Young%27s_Double-Slit_Interference", "https://byjus.com/physics/youngs-double-slit-experiment-derivation/", "https://www.physicsclassroom.com/class/light/u12l3d"]'),
  ('buoyant_density_relation', '{"en-us": "Density from buoyant force measurement"}', 'buoyancy', 6, '{"en-us": "This relation, used in hydrostatic weighing, lets you find an object''s density without measuring its volume: weigh it in air and again while fully submerged in a fluid of known density. The difference between the two weights is the buoyant force, which equals the weight of displaced fluid by Archimedes'' principle."}', '["https://phys.libretexts.org/Bookshelves/Conceptual_Physics/Body_Physics_-_Motion_to_Metabolism_(Davis)/04%3A_Better_Body_Composition_Measurement/4.06%3A_Hydrostatic_Weighing", "https://openoregon.pressbooks.pub/bodyphysics2ed/chapter/hydrostatic/", "https://en.wikipedia.org/wiki/Archimedes_principle", "https://courses.lumenlearning.com/suny-physics/chapter/11-7-archimedes-principle/"]'),
  ('buoyant_force', '{"en-us": "Buoyant force"}', 'buoyancy', 5, '{"en-us": "The buoyant force is the upward force a fluid exerts on an immersed object, equal in magnitude to the weight of the fluid displaced (Archimedes'' principle). It applies to any fluid, whether the object is partially or fully submerged, and determines whether objects float or sink."}', '["https://en.wikipedia.org/wiki/Archimedes_principle", "https://www.britannica.com/science/Archimedes-principle", "https://phys.libretexts.org/Bookshelves/University_Physics/Physics_(Boundless)/10%3A_Fluids/10.3%3A_Archimedes_Principle", "https://physics.info/buoyancy/", "https://www.physicsclassroom.com/tutorial/fluids/pressure/buoyant-force-and-archimedes-principle"]'),
  ('buoyant_force_displaced_volume', '{"en-us": "Buoyant force from displaced volume"}', 'buoyancy', 5, '{"en-us": "By Archimedes'' principle, the upward buoyant force on an immersed object equals the weight of the fluid it pushes aside, computed here as the fluid density times gravitational acceleration times the displaced volume. For a fully submerged object the displaced volume is the object''s volume; for a floater it is only the submerged part."}', '["https://en.wikipedia.org/wiki/Archimedes_principle", "https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/11%3A_Fluid_Statics/11.07%3A_Archimedes_Principle", "https://physics.info/buoyancy/", "https://www.physicsclassroom.com/tutorial/fluids/pressure/buoyant-force-and-archimedes-principle"]'),
  ('buoyant_volume_displaced', '{"en-us": "Volume of fluid displaced by floating object"}', 'buoyancy', 2, '{"en-us": "A floating object settles so that it displaces a weight of fluid equal to its own weight (the principle of flotation). Since the displaced fluid''s mass therefore equals the object''s mass, the submerged volume follows from dividing that mass by the fluid density. It applies only to objects floating in static equilibrium."}', '["https://en.wikipedia.org/wiki/Buoyancy", "https://en.wikipedia.org/wiki/Archimedes_principle", "https://pressbooks.bccampus.ca/collegephysics/chapter/archimedes-principle/"]'),
  ('calibration_curve_linear_regression', '{"en-us": "Calibration curve (linear regression model)"}', 'analytical_chemistry', 8, '{"en-us": "In analytical chemistry, a calibration curve relates the instrument response measured for standards of known concentration to that concentration, with the straight-line fit obtained by ordinary least-squares regression. The fitted slope and intercept are then used to determine analyte concentrations in unknown samples by inverse prediction."}', '["https://en.wikipedia.org/wiki/Calibration_curve", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Analytical_Chemistry_2.1_by_David_Harvey/Analytical_Chemistry_2.1_(Harvey)/05%3A_Standardizing_Analytical_Methods/5.04%3A_Linear_Regression_and_Calibration_Curves", "https://pubs.rsc.org/en/content/articlehtml/2023/ay/d3ay90134c?page=search"]'),
  ('calorimeter_heat_capacity', '{"en-us": "Heat capacity of a calorimeter"}', 'thermochemistry', 6, '{"en-us": "The calorimeter constant is the amount of heat needed to raise the temperature of the entire calorimeter (hardware plus contents) by one degree, with units of energy per degree. It is determined by calibration, e.g. by adding a known quantity of heat and measuring the resulting temperature rise, and it corrects measured heat flows for heat absorbed by the apparatus itself."}', '["https://gchem.cm.utexas.edu/pdf/helpsheets/Calorimetry.pdf", "https://www.chemteam.info/Thermochem/Calculate-a-Calorimeter-Constant.html", "https://chem.libretexts.org/Courses/University_of_Toronto/Chemistry%3A_Physical_Principles/05%3A_Thermochemistry/5.05%3A_Calorimetry", "https://general.chemistrysteps.com/constant-pressure-calorimetry/"]'),
  ('capacitance_formula', '{"en-us": "Capacitance definition"}', 'capacitance', 6, '{"en-us": "Capacitance measures how much electric charge a conductor or pair of conductors stores per unit potential difference between them, measured in farads. It is a purely geometric/material property of the device, independent of the actual charge or voltage applied."}', '["https://en.wikipedia.org/wiki/Capacitance", "https://openstax.org/books/university-physics-volume-2/pages/8-1-capacitors-and-capacitance", "https://www.britannica.com/science/capacitance", "https://phys.libretexts.org/Courses/Berea_College/Electromagnetics_I_(Messina)/05%3A_Electrostatics/5.22%3A_Capacitance"]'),
  ('capacitance_parallel_plate_dielectric', '{"en-us": "Parallel plate capacitance with dielectric"}', 'capacitance', 7, '{"en-us": "This gives the capacitance of a parallel-plate capacitor whose gap is completely filled by an insulating dielectric material: larger plate area and higher relative permittivity raise the capacitance, while wider plate separation lowers it. The formula neglects edge effects, so it is accurate when the plates are close together compared with their size."}', '["https://openstax.org/books/college-physics-2e/pages/19-5-capacitors-and-dielectrics", "https://phys.libretexts.org/Courses/Joliet_Junior_College/JJC_-_PHYS_110/College_Physics_for_Health_Professions/19%3A_Electric_Potential_and_Electric_Field/19.06%3A_Capacitors_and_Dielectrics", "http://hyperphysics.phy-astr.gsu.edu/hbase/electric/pplate.html", "https://www.physicsbootcamp.org/Parallel-Plate-Capacitor.html"]'),
  ('capacitive_reactance', '{"en-us": "Capacitive reactance"}', 'circuits', 7, '{"en-us": "Capacitive reactance is the opposition a capacitor offers to alternating current, arising from its repeated storage and release of charge. Measured in ohms, it decreases as the signal frequency or capacitance increases, which is why capacitors block DC but pass high-frequency AC readily. It is used in AC circuit analysis, filter design, and impedance calculations."}', '["https://en.wikipedia.org/wiki/Capacitive_reactance", "https://www.allaboutcircuits.com/textbook/alternating-current/chpt-4/ac-capacitor-circuits/", "https://www.electronics-notes.com/articles/basic%5Fconcepts/capacitance/capacitive-reactance.php", "https://www.geeksforgeeks.org/physics/capacitive-reactance-formula/"]'),
  ('capacitor_charging_current', '{"en-us": "Capacitor charging current"}', 'capacitance', 7, '{"en-us": "When an uncharged capacitor charges through a resistor from a constant voltage source, the current is largest the instant the switch closes and then decays exponentially toward zero, governed by the RC time constant. This relation is used to analyze transient response in RC circuits and in timing and filter applications. It assumes an ideal source, an initially uncharged capacitor, and negligible inductance."}', '["https://phys.libretexts.org/Bookshelves/Electricity_and_Magnetism/Electricity_and_Magnetism_(Tatum)/05%3A_Capacitors/5.19%3A__Charging_a_Capacitor_Through_a_Resistor", "https://www.physicsclassroom.com/calcpad/Transient-RC-Circuits/Equation-Overview", "http://physics.bu.edu/~duffy/semester2/c11_RC.html", "https://www.physicsbook.gatech.edu/Charging_and_Discharging_a_Capacitor"]'),
  ('capacitor_energy', '{"en-us": "Energy stored in a capacitor"}', 'capacitance', 6, '{"en-us": "A charged capacitor stores electrical potential energy in the electric field between its plates; the amount grows with both the capacitance and the square of the voltage across it. This energy equals half the work done by the source during charging, since the capacitor voltage rises gradually from zero. It is used to size energy-storage elements, camera flash circuits, and defibrillators."}', '["https://openstax.org/books/university-physics-volume-2/pages/8-3-energy-stored-in-a-capacitor", "https://openstax.org/books/college-physics-ap-courses-2e/pages/19-7-energy-stored-in-capacitors", "https://hyperphysics.gsu.edu/hbase/electric/capeng2.html", "https://byjus.com/physics/energy-stored-in-a-capacitor/"]'),
  ('capacitor_energy_density_vacuum', '{"en-us": "Energy density in a capacitor (vacuum)"}', 'capacitance', 8, '{"en-us": "The energy stored in an electric field is spread throughout the space the field occupies, and this quantity gives the energy per unit volume held by the field between capacitor plates in vacuum. Because it depends only on the local field strength, it applies point-by-point to any electrostatic field configuration, not just parallel-plate capacitors. A dielectric-filled gap would use the material permittivity instead."}', '["https://openstax.org/books/university-physics-volume-2/pages/8-3-energy-stored-in-a-capacitor", "https://en.wikipedia.org/wiki/Electrical_potential_energy", "https://phys.libretexts.org/Bookshelves/Electricity_and_Magnetism/Book%3A_Applications_of_Maxwells_Equations_(Cochran_and_Heinrich)/03%3A_Electrostatic_Field_II/3.03%3A_Electrostatic_Field_Energy", "https://uclnatsci.github.io/Electromagnetism-Fluids-and-Waves/electromagnetism/EMenergy.html"]'),
  ('capacitor_energy_q', '{"en-us": "Energy stored in a capacitor from charge"}', 'capacitance', 6, '{"en-us": "This form of the capacitor energy relation applies when the charge on the plates is known directly rather than the voltage between them. It shows that for fixed charge, a larger capacitance stores less energy, since the same charge spreads over a lower potential difference. It follows from combining the definition of capacitance with the general work done charging a capacitor."}', '["https://openstax.org/books/university-physics-volume-2/pages/8-3-energy-stored-in-a-capacitor", "https://openstax.org/books/college-physics-ap-courses-2e/pages/19-7-energy-stored-in-capacitors", "https://hyperphysics.gsu.edu/hbase/electric/capeng2.html", "http://physics.bu.edu/~duffy/semester2/c07_capacitor_energy.html"]'),
  ('capacitor_energy_voltage_charge', '{"en-us": "Capacitor energy from voltage and charge"}', 'capacitance', 6, '{"en-us": "This form of the stored-energy relation uses both the charge held on the plates and the final voltage between them. The energy is half of their product because the capacitor''s voltage builds up gradually from zero during charging, so each increment of charge is moved through a lower potential difference than the last. It is useful when a capacitor''s charge and operating voltage are both known."}', '["https://openstax.org/books/university-physics-volume-2/pages/8-3-energy-stored-in-a-capacitor", "https://openstax.org/books/college-physics-ap-courses-2e/pages/19-7-energy-stored-in-capacitors", "https://hyperphysics.gsu.edu/hbase/electric/capeng2.html"]'),
  ('capacitors_in_series_general', '{"en-us": "Capacitors in series (general formula)"}', 'capacitance', 6, '{"en-us": "Capacitors connected in series all store the same charge while the applied voltage divides among them, and this rule gives the single equivalent capacitance that could replace the whole chain. The pattern extends to any number of capacitors by adding more reciprocal terms, and the result is always smaller than the smallest individual capacitance. It is used to simplify circuit networks before applying voltage or charge analysis."}', '["https://openstax.org/books/college-physics-2e/pages/19-6-capacitors-in-series-and-parallel", "https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/19%3A_Electric_Potential_and_Electric_Field/19.06%3A_Capacitors_in_Series_and_Parallel", "https://www.engineeringtoolbox.com/capacitors-parallel-series-d_1388.html", "https://farside.ph.utexas.edu/teaching/316/lectures/node46.html"]'),
  ('capillary_rise', '{"en-us": "Capillary rise"}', 'surface_tension', 8, '{"en-us": "Known as Jurin''s law, this relation gives the height to which a wetting liquid climbs (or is depressed) in a narrow tube due to surface tension acting against the weight of the liquid column. The rise grows with surface tension and shrinks as the tube gets wider or the liquid denser; a contact angle beyond ninety degrees flips the effect to a depression, as with mercury in glass. It assumes a thin cylindrical tube and a static equilibrium meniscus."}', '["https://en.wikipedia.org/wiki/Jurin%27s_Law", "https://farside.ph.utexas.edu/teaching/336L/Fluid/node45.html", "https://chem-textbook.ucalgary.ca/capillary-action-calculation/"]'),
  ('carnot_efficiency', '{"en-us": "Carnot efficiency"}', 'heat_engines', 7, '{"en-us": "The Carnot efficiency is the maximum theoretical efficiency any heat engine can achieve while operating between a hot and a cold reservoir, set by their absolute temperatures alone. By Carnot''s theorem, no real engine can exceed this bound, and the limit is reached only by an ideal, fully reversible cycle. It is used as a benchmark for power plants and engines; both temperatures must be expressed on an absolute (kelvin) scale."}', '["https://en.wikipedia.org/wiki/Carnot_heat_engine", "https://openstax.org/books/college-physics/pages/15-4-carnots-perfect-heat-engine-the-second-law-of-thermodynamics-restated", "https://en.wikipedia.org/wiki/Carnot_cycle"]'),
  ('catalytic_activity_concentration_formula', '{"en-us": "Catalytic activity concentration"}', 'chemical_kinetics', 8, '{"en-us": "This quantity expresses how much catalytic power — most often enzyme activity — is present per unit volume of a system, and is the standard way of reporting enzyme levels in clinical chemistry. Its SI-coherent unit is the katal per litre, though enzyme units per litre are also common. Reported values depend on the assay conditions such as temperature, pH, and substrate, which should be stated alongside the result."}', '["https://goldbook.iupac.org/terms/view/C00882", "https://goldbook.iupac.org/terms/view/C00881", "https://goldbook.iupac.org/terms/view/K03372", "https://labterminology.com/list-of-kinds-of-property/catalytic-activity-concentration-cat-c/"]'),
  ('catalytic_efficiency', '{"en-us": "Catalytic efficiency"}', 'biochemistry', 8, '{"en-us": "Also called the specificity constant, this second-order rate parameter measures how effectively an enzyme converts its substrate into product when substrate is scarce, and how strongly the enzyme discriminates between competing substrates. For the fastest enzymes it approaches the diffusion-controlled limit of roughly one hundred million to a billion per molar per second. It is a standard benchmark for comparing enzyme performance across substrates and mutants."}', '["https://en.wikipedia.org/wiki/Catalytic_efficiency", "https://bio.libretexts.org/Workbench/Biochem_Remix_Acevedo/06%3A_Enzyme_Activity/6.03%3A_Kinetics_with_Enzymes", "https://www.ncbi.nlm.nih.gov/books/NBK92007/"]'),
  ('cell_potential_standard', '{"en-us": "Standard cell potential"}', 'electrochemistry', 7, '{"en-us": "The standard cell potential is the voltage of an electrochemical cell when both half-cells are in their standard states — one molar solutions, one bar gas pressures, and 25 degrees Celsius. It combines the tabulated standard reduction potentials of the two electrodes and measures the driving force of the redox reaction: a positive value indicates a spontaneous galvanic cell. It is the starting point for predicting spontaneity and calculating equilibrium constants."}', '["https://openstax.org/books/chemistry-2e/pages/17-3-electrode-and-cell-potentials", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Supplemental_Modules_(Analytical_Chemistry)/Electrochemistry/Redox_Potentials/Standard_Potentials", "https://en.wikipedia.org/wiki/Standard_electrode_potential"]'),
  ('celsius_to_kelvin', '{"en-us": "Celsius to Kelvin conversion"}', 'temperature', 3, '{"en-us": "Converts a temperature expressed on the Celsius scale to the Kelvin scale, the SI base unit of thermodynamic temperature. The two scales have equal-sized degrees but different zero points: 0 degrees Celsius corresponds to about 273 kelvins at the freezing point of water, and absolute zero is 0 K."}', '["https://en.wikipedia.org/wiki/Temperature_conversion_formulas", "https://en.wikipedia.org/wiki/Kelvin", "https://www.nist.gov/pml/owm/si-units-temperature", "https://chem.libretexts.org/Bookshelves/Introductory_Chemistry/Map%3A__Introductory_Chemistry_(Corwin)/03%3A_The_Metric_System/3.08%3A_Temperature"]'),
  ('center_of_mass_two_particles', '{"en-us": "Center of mass of two particles"}', 'linear_momentum', 5, '{"en-us": "Gives the balance point of a system of two point masses along one axis as the mass-weighted average of their positions. The center of mass lies closer to the heavier particle, and it reduces to the plain midpoint when the two masses are equal. It is used in collision and rigid-body problems where the whole system can be treated as if its mass were concentrated at one point."}', '["https://phys.libretexts.org/Courses/University_of_California_Davis/UCD%3A_Physics_9HA__Classical_Mechanics/4%3A_Linear_Momentum/4.2%3A_Center_of_Mass", "http://www.geom.uiuc.edu/education/calc-init/static-beam/ctr-derive.html", "https://courses.physics.illinois.edu/phys211/su2012/Text/ch10.pdf"]'),
  ('center_of_mass_velocity', '{"en-us": "Velocity of the center of mass"}', 'linear_momentum', 6, '{"en-us": "The velocity of a system''s center of mass is the mass-weighted average of the velocities of its parts, which also equals the total momentum of the system divided by the total mass. Because an isolated system''s total momentum is conserved, its center of mass moves at constant velocity no matter how the individual particles move. This underlies collision analysis and the treatment of extended bodies as single particles."}', '["https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_I_-_Classical_Mechanics_(Gea-Banacloche)/03%3A_Momentum_and_Inertia/3.03%3A_Extended_Systems_and_Center_of_Mass", "https://openstax.org/books/university-physics-volume-1/pages/9-6-center-of-mass", "http://labman.phys.utk.edu/phys135core/modules/m7/center_of_mass.html"]'),
  ('center_of_mass_x_coordinate', '{"en-us": "Center of mass x-coordinate"}', 'linear_momentum', 6, '{"en-us": "Locates the center of mass of a system of particles along the x-axis as the mass-weighted average of the particles'' x-coordinates. Each particle contributes in proportion to its share of the total mass, so the point lies closer to the heavier particles. This coordinate is used to reduce a multi-particle system to a single equivalent point for dynamics and collision problems."}', '["https://phys.libretexts.org/Courses/Prince_Georges_Community_College/General_Physics_I%3A_Classical_Mechanics/34%3A__Center_of_Mass/34.01%3A_Discrete_Masses", "https://openstax.org/books/university-physics-volume-1/pages/9-6-center-of-mass", "https://math.libretexts.org/Bookshelves/Calculus/CLP-2_Integral_Calculus_(Feldman_Rechnitzer_and_Yeager)/02%3A_Applications_of_Integration/2.03%3A_Centre_of_Mass_and_Torque"]'),
  ('central_force_newton_gravitation', '{"en-us": "Central force in Newtonian gravitation"}', 'orbital_motion', 7, '{"en-us": "Newton''s law of universal gravitation gives the attractive force between two masses as a central force: its magnitude depends only on the separation and it always acts along the line joining the two centers of mass. It applies exactly to point masses (and spherically symmetric bodies) and governs satellite and planetary orbits. The force is attractive, mutual, and weakens with the square of the distance."}', '["https://en.wikipedia.org/wiki/Newton%27s_law_of_universal_gravitation", "https://openstax.org/books/university-physics-volume-1/pages/13-1-newtons-law-of-universal-gravitation", "https://www.britannica.com/science/Newtons-law-of-gravitation"]'),
  ('centripetal_acceleration', '{"en-us": "Centripetal acceleration"}', 'circular_motion', 5, '{"en-us": "Magnitude of the acceleration of an object in uniform circular motion, directed toward the center of the circular path. It arises because the velocity''s direction changes even while the speed stays constant, and it is perpendicular to the instantaneous velocity. Larger speeds and tighter turns demand greater centripetal acceleration."}', '["https://openstax.org/books/college-physics-2e/pages/6-2-centripetal-acceleration", "https://phys.libretexts.org/Courses/Texas_AM_University/TAMU_SA_GENERAL_PHYSICS_1301/06%3A_Uniform_Circular_Motion_and_Gravitation/6.03%3A_Centripetal_Acceleration", "https://openstax.org/books/physics/pages/6-2-uniform-circular-motion"]'),
  ('centripetal_acceleration_angular', '{"en-us": "Centripetal acceleration in terms of angular velocity"}', 'circular_motion', 5, '{"en-us": "Expresses the magnitude of centripetal acceleration using the angular velocity of the circular motion instead of the linear speed. It is equivalent to the speed-based form via the relation between arc length and angle, and is convenient for rotating systems such as wheels, centrifuges, and orbits where the rotation rate is known. Valid for uniform circular motion."}', '["https://openstax.org/books/college-physics-2e/pages/6-2-centripetal-acceleration", "https://openstax.org/books/university-physics-volume-1/pages/6-3-centripetal-force", "https://openbooks.lib.msu.edu/collegephysics1/chapter/centripetal-acceleration-2/"]'),
  ('centripetal_acceleration_formula', '{"en-us": "Centripetal acceleration (centripetal_acceleration_formula)"}', 'circular_motion', 5, '{"en-us": "Gives the magnitude of the center-seeking acceleration of a body following a circular or curved path in terms of its tangential speed and the radius of curvature. The acceleration is perpendicular to the velocity and points toward the center, growing with the square of the speed and shrinking as the curve widens. Used to analyze vehicles on curves, rotating machinery, and orbital motion."}', '["https://openstax.org/books/college-physics-2e/pages/6-2-centripetal-acceleration", "https://phys.libretexts.org/Bookshelves/Conceptual_Physics/Introduction_to_Physics_(Park)/02%3A_Mechanics_I_-_Motion_and_Forces/01%3A_Kinematics/1.09%3A_Centripetal_Acceleration", "https://www.engineeringtoolbox.com/centripetal-acceleration-d_1285.html"]'),
  ('centripetal_force', '{"en-us": "Centripetal force"}', 'circular_motion', 5, '{"en-us": "Net force required to keep a body of given mass moving on a circular path, directed toward the center of curvature. It is not a new kind of force but the name for whatever real force (tension, gravity, friction, a normal force) supplies the radial acceleration. Used in designing banked roads, centrifuges, and orbits; a larger required force means a tighter turn."}', '["https://en.wikipedia.org/wiki/Centripetal_force", "https://openstax.org/books/college-physics/pages/6-3-centripetal-force", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/06%3A_Applications_of_Newton''s_Laws/6.06%3A_Centripetal_Force"]'),
  ('centroid_triangle_x', '{"en-us": "Centroid of a triangle (x-coordinate)"}', 'coordinate_geometry', 5, '{"en-us": "Finds the x-coordinate of a triangle''s centroid — the point where its three medians intersect, also the geometric center of mass of a uniform triangular lamina. It is simply the arithmetic mean of the three vertices'' x-coordinates, and the centroid always lies inside the triangle. The y-coordinate is found the same way from the vertices'' y-values."}', '["https://mathworld.wolfram.com/TriangleCentroid.html", "https://brilliant.org/wiki/triangles-centroid/", "https://www.mathwords.com/t/triangle_centroid.htm"]'),
  ('cfse_octahedral', '{"en-us": "Crystal field stabilization energy (octahedral)"}', 'inorganic_chemistry', 9, '{"en-us": "Net energy by which a d-electron configuration in an octahedral ligand field is more stable than the same electrons spread evenly over all five d orbitals (the barycenter). Electrons in the lower t2g set stabilize the complex while electrons in the upper eg set destabilize it, so the balance depends on how many occupy each set. Used to compare complex stabilities, site preferences, and high-spin versus low-spin configurations; pairing energy must be accounted for separately."}', '["https://chem.libretexts.org/Courses/University_of_California_Davis/Chem_124A%3A_Fundamentals_of_Inorganic_Chemistry/09%3A_Crystal_Field_Theory/9.02%3A_Crystal_Field_Stabilization_Energy", "https://en.wikipedia.org/wiki/Crystal_field_theory", "https://chem.libretexts.org/Bookshelves/Inorganic_Chemistry/Introduction_to_Inorganic_Chemistry_(Wikibook)/05%3A_Coordination_Chemistry_and_Crystal_Field_Theory/5.06%3A_Crystal_Field_Stabilization_Energy_Pairing_and_Hund''s_Rule"]'),
  ('charge_density_formula', '{"en-us": "Charge density from charge and volume"}', 'electrostatics', 6, '{"en-us": "Defines the average volume charge density of a body as its total electric charge spread over the three-dimensional space it occupies. It characterizes how much charge resides in each unit of volume and is the starting point for computing electric fields from continuous charge distributions. The result carries a sign, since charge itself may be positive or negative."}', '["https://en.wikipedia.org/wiki/Charge_density", "https://openstax.org/books/university-physics-volume-2/pages/5-5-calculating-electric-fields-of-charge-distributions", "https://byjus.com/charge-density-formula/"]'),
  ('charge_on_capacitor', '{"en-us": "Charge stored in a capacitor"}', 'capacitance', 5, '{"en-us": "Gives the electric charge held on the plates of a capacitor in terms of its capacitance and the potential difference applied across it. Capacitance measures charge stored per volt, so a larger capacitance or higher voltage means more stored charge. This relation assumes an ideal linear capacitor."}', '["https://openstax.org/books/college-physics-2e/pages/19-5-capacitors-and-dielectrics", "https://openstax.org/books/university-physics-volume-2/pages/8-1-capacitors-and-capacitance", "https://phys.libretexts.org/Courses/Martin_Luther_College/MLC_-_Physical_Science/03%3A_Electricity_and_Magnetism/3.03%3A_Capacitors_and_Dielectrics", "https://en.wikipedia.org/wiki/Capacitance"]'),
  ('charles_law', '{"en-us": "Charles''s law"}', 'ideal_gases', 5, '{"en-us": "Charles''s law (the law of volumes) states that for a fixed amount of gas held at constant pressure, the volume is directly proportional to the absolute temperature. The two-state form lets you predict how a gas sample''s volume changes between an initial and a final temperature. Temperatures must be expressed in kelvin, and the law holds only approximately for real gases."}', '["https://en.wikipedia.org/wiki/Charles%27s_Law", "https://chem.libretexts.org/Bookshelves/Introductory_Chemistry/Fundamentals_of_General_Organic_and_Biological_Chemistry_(LibreTexts)/08%3A_Gases_Liquids_and_Solids/8.06%3A_Charless_Law-_The_Relation_between_Volume_and_Temperature", "https://www.engineeringtoolbox.com/charles-law-d_1277.html", "https://chem.libretexts.org/Courses/Pasadena_City_College/PCC_Chemistry_2A/02%3A_Energy_and_Matter/2.02%3A_Gas_Properties/2.2.03%3A_The_temperature-volume_relationship"]'),
  ('chemical_reaction_rate_average', '{"en-us": "Average rate of a chemical reaction"}', 'chemical_reactions', 5, '{"en-us": "The average reaction rate measures how quickly a species is consumed or produced over a finite time interval during a chemical reaction. Because rates are reported as positive quantities, the change in a reactant''s concentration carries a leading minus sign (products need no sign flip). It is the basis for distinguishing average rates from instantaneous rates in chemical kinetics."}', '["https://www.chem.purdue.edu/gchelp/howtosolveit/Kinetics/CalculatingRates.html", "https://chem.libretexts.org/Courses/University_of_Florida/CHM2047%3A_One-Semester_General_Chemistry_(Kleiman)/15%3A_Chemical_Kinetics/15.01%3A_Rates_of_Chemical_Reactions", "https://openstax.org/books/chemistry-atoms-first-2e/pages/17-1-chemical-reaction-rates"]'),
  ('chemical_reaction_yield_mass_product', '{"en-us": "Mass of product from limiting reactant"}', 'chemical_reactions', 6, '{"en-us": "Predicts the theoretical yield of a reaction: once the limiting reactant is identified, its mass fixes the maximum amount of product that can form. The calculation converts the limiting reactant''s mass to moles, scales by the mole ratio from the balanced chemical equation, and converts back to product mass. It assumes complete conversion and no side reactions, so real yields are typically lower."}', '["https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/04%3A_Chemical_Reactions/4.4%3A_Determining_the_Limiting_Reactant", "https://chem.libretexts.org/Courses/University_of_Toronto/Chemistry%3A_Physical_Principles/01%3A_Foundations_for_Success/1.06%3A_Reaction_Stoichiometry", "https://www.bbc.co.uk/bitesize/guides/z26f8mn/revision/5"]'),
  ('chi_squared_statistic', '{"en-us": "Chi-squared statistic"}', 'statistics', 8, '{"en-us": "Pearson''s chi-squared statistic quantifies how far observed category counts deviate from the counts expected under a null hypothesis, with deviations weighted by their expected sizes. It underpins chi-square tests of goodness of fit, independence, and homogeneity, and is compared against the chi-square distribution to obtain a p-value. Each expected count should be at least about five for the test to be valid."}', '["https://en.wikipedia.org/wiki/Pearson''s_chi-square_test", "https://itl.nist.gov/div898/handbook/eda/section3/eda35f.htm", "https://stats.libretexts.org/Courses/Penn_State_University_Greater_Allegheny/STAT_200%3A_Elementary_Statistics/11%3A_The_Chi-Square_Distribution/11.03%3A_Goodness-of-Fit_Test", "https://www.scribbr.com/statistics/chi-square-goodness-of-fit/"]'),
  ('chord_length', '{"en-us": "Chord length"}', 'circles', 5, '{"en-us": "Gives the straight-line distance between two points on a circle from the circle''s radius and the central angle the two radii to those points subtend. It follows from bisecting the isosceles triangle formed by the two radii. The angle may be in degrees or radians as long as the sine function matches, and the chord grows to a diameter when the angle is 180 degrees."}', '["https://proofwiki.org/wiki/Length_of_Chord_of_Circle", "https://www.mathwords.com/c/chord.htm", "https://www.geeksforgeeks.org/dsa/length-of-the-chord-of-the-circle-whose-radius-and-the-angle-subtended-at-the-center-by-the-chord-is-given/"]'),
  ('chromatographic_resolution', '{"en-us": "Chromatographic resolution"}', 'analytical_chemistry', 8, '{"en-us": "Resolution measures how completely two adjacent chromatographic peaks are separated, comparing the gap between their retention times with their baseline widths. It is used as a system-suitability and method-development criterion in chromatography; values of about 1.5 or greater indicate baseline separation. Widths here are measured at the baseline (other conventions use half-height widths with a different prefactor)."}', '["https://en.wikipedia.org/wiki/Resolution_(chromatography)", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Supplemental_Modules_(Analytical_Chemistry)/Analytical_Sciences_Digital_Library/Courseware/Separation_Science/02_Text/07_Appendix_1%3A__Derivation_of_the_Fundamental_Resolution_Equation", "https://lab-training.com/tools/resolution-calculator/"]'),
  ('circle_area_diameter', '{"en-us": "Circle area from diameter"}', 'circles', 2, '{"en-us": "Computes the area enclosed by a circle directly from its diameter, avoiding the intermediate step of halving to get the radius. It follows from the standard radius-based area formula together with the relation that a diameter is twice a radius. Useful whenever a measured or specified size is given as a diameter, such as pipes, disks, and wheels."}', '["https://www.mathsisfun.com/geometry/circle-area.html", "https://byjus.com/maths/area-of-circle/", "https://mathcracker.com/area-circle-diameter"]'),
  ('circle_segment_area', '{"en-us": "Area of a circular segment"}', 'circles', 6, '{"en-us": "Gives the area of a circular segment, the region bounded by a chord and the arc it cuts off. It equals the area of the pie-slice sector minus that of the triangle formed by the two radii and the chord, so the central angle must be expressed in radians. Used in geometry and in practical problems such as liquid volumes in horizontal cylindrical tanks."}', '["https://en.wikipedia.org/wiki/Circular_segment", "https://mathworld.wolfram.com/CircularSegment.html", "https://www.mathwords.com/a/area_segment_circle.htm"]'),
  ('circle_standard_form', '{"en-us": "Standard form of a circle"}', 'circles', 4, '{"en-us": "The standard (center-radius) form of a circle''s equation states that a point lies on the circle exactly when its squared horizontal and vertical offsets from the center sum to the squared radius. It follows from the Pythagorean theorem applied to the distance from the center to any point on the circle. Reading off the center and radius from this form is the usual first step for graphing a circle or converting from its expanded equation."}', '["https://www.mathsisfun.com/algebra/circle-equations.html", "https://math.libretexts.org/Courses/College_of_the_Desert/College_Algebra_for_Liberal_Arts_and_Humanities/02%3A_The_Rectangular_Coordinate_System_and_Graphs/2.02%3A_The_Circle", "https://byjus.com/maths/equation-of-a-circle/", "https://www.purplemath.com/modules/circle.htm"]'),
  ('circle_tangent_radius_perpendicular', '{"en-us": "Tangent-radius perpendicularity"}', 'circles', 4, '{"en-us": "States the tangent-to-a-circle theorem from Euclidean geometry: at the point where a tangent line touches a circle, the radius drawn to that point makes a right angle with the tangent. The converse also holds, so a line perpendicular to a radius at its endpoint on the circle is necessarily a tangent. This fact is the basis for many circle proofs and for tangent-length constructions."}', '["https://proofwiki.org/wiki/Radius_at_Right_Angle_to_Tangent", "https://brilliant.org/wiki/tangent-perpendicular-to-radius/", "https://math.libretexts.org/Bookshelves/Geometry/Elementary_College_Geometry_(Africk)/07%3A_Regular_Polygons_and_Circles/7.03%3A_Tangents_to_the_Circle", "https://en.wikipedia.org/wiki/Tangent_lines_to_circles"]'),
  ('circuit_current_division_parallel', '{"en-us": "Current division in parallel resistors (two)"}', 'circuits', 6, '{"en-us": "The current divider rule gives the share of a total current that flows through one of two parallel resistors. Because each branch sees the same voltage, the branch current is inversely proportional to its resistance, so the smaller resistor draws the larger current and the formula uses the opposite branch''s resistance in the numerator. It applies to linear resistive networks with exactly two parallel branches."}', '["https://en.wikipedia.org/wiki/Current_divider", "https://eng.libretexts.org/Workbench/Introduction_to_Circuit_Analysis/02%3A_Fundamental_Laws/2.03%3A_Kirchhof%27s_Current_Law/2.3.04%3A_Kirchhoff%27s_Current_Law", "https://www.electronics-tutorials.ws/dccircuits/current-divider.html", "https://www.allaboutcircuits.com/textbook/direct-current/chpt-6/current-divider-circuits/"]'),
  ('circuit_kirchhoff_loop_rule', '{"en-us": "Kirchhoff''s loop rule"}', 'circuits', 6, '{"en-us": "Kirchhoff''s loop rule (also called Kirchhoff''s voltage law) states that the algebraic sum of all voltage changes around any closed loop in a circuit equals zero, reflecting conservation of energy. Sources count as rises and loads as drops relative to the chosen traversal direction. It is used together with the junction rule to analyze multi-loop circuits."}', '["https://en.wikipedia.org/wiki/Kirchhoff%27s_circuit_laws", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/10%3A_Direct-Current_Circuits/10.04%3A_Kirchhoff%27s_Rules", "https://www.electronics-tutorials.ws/dccircuits/kirchhoffs-voltage-law.html", "https://www.allaboutcircuits.com/textbook/direct-current/chpt-6/kirchhoffs-voltage-law-kvl/"]'),
  ('circuit_voltage_division_series', '{"en-us": "Voltage division in series resistors"}', 'circuits', 6, '{"en-us": "The voltage divider rule gives the voltage appearing across one resistor of a series pair as a fraction of the total applied voltage, proportional to that resistor''s share of the total resistance. It follows from Ohm''s law and the fact that the same current flows through series elements. It applies to unloaded resistive dividers; a load connected across the output changes the ratio."}', '["https://www.electronics-tutorials.ws/dccircuits/voltage-divider.html", "https://circuitdigest.com/calculators/voltage-divider-calculator", "https://elecalculator.com/guides/circuit-analysis/voltage-divider-circuits/"]'),
  ('circular_motion_angular_to_linear_velocity', '{"en-us": "Linear velocity from angular velocity"}', 'circular_motion', 5, '{"en-us": "Relates the tangential (linear) speed of a point moving on a circular path to how fast the angle is swept, through the radius of the path. The linear speed grows in proportion to both the rotation rate and the distance from the axis. It assumes the point stays at a fixed radius and the angle is measured in radians."}', '["https://en.wikipedia.org/wiki/Angular_velocity", "https://phys.libretexts.org/Bookshelves/University_Physics/Mechanics_and_Relativity_(Idema)/07%3A_General_Rotational_Motion/7.01%3A_Linear_and_Angular_Velocity", "https://math.libretexts.org/Bookshelves/Precalculus/Book:_Trigonometry_(Sundstrom_and_Schlicker)/01:_The_Trigonometric_Functions/1.04:_Velocity_and_Angular_Velocity", "https://www.geeksforgeeks.org/physics/relation-between-angular-velocity-and-linear-velocity/"]'),
  ('circular_polarization_condition', '{"en-us": "Circular polarization amplitude condition"}', 'polarization', 9, '{"en-us": "One of the two requirements for a monochromatic plane wave to be circularly polarized: the magnitudes of its two orthogonal transverse electric-field components must match, so neither axis of rotation is favored. The second requirement is a relative phase shift of a quarter cycle between the components; together they make the field vector rotate with constant magnitude."}', '["https://en.wikipedia.org/wiki/Circular_polarization", "https://eng.libretexts.org/Bookshelves/Materials_Science/Supplemental_Modules_%28Materials_Science%29/Optical_Properties/Polarization_of_Waves", "https://next.gr/tutorials/rf-and-wireless-basics/polarization-of-electromagnetic-waves-tutorial", "https://www.mathworks.com/help/phased/ug/polarized-fields.html"]'),
  ('circumference_circle', '{"en-us": "Circumference of a circle"}', 'circles', 1, '{"en-us": "Gives the perimeter of a circle — the total distance around its boundary — from its radius. It follows directly from the definition of pi as the ratio of circumference to diameter. This relation is exact for any circle and is the basis for computing arc lengths, wheel travel distances, and rotational-to-linear motion conversions."}', '["https://en.wikipedia.org/wiki/Circumference", "https://www.mathopenref.com/circumferencederive.html", "https://www.cuemath.com/geometry/circumference-of-a-circle/", "https://wumbo.net/formulas/circumference-of-circle"]'),
  ('clausius_clapeyron', '{"en-us": "Clausius-Clapeyron equation"}', 'solutions', 8, '{"en-us": "Describes how the vapor pressure of a substance changes between two temperatures during a phase transition, governed by the enthalpy of vaporization. It is used to estimate vapor pressures, boiling points at different pressures, or latent heats from measured data. The integrated form assumes ideal vapor behavior and an approximately temperature-independent enthalpy of vaporization."}', '["https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Phase_Transitions/Clausius-Clapeyron_Equation", "https://en.wikipedia.org/wiki/Clausius%E2%80%93Clapeyron_relation", "https://web.mit.edu/16.unified/www/FALL/thermodynamics/notes/node64.html", "https://www.chemteam.info/GasLaw/Clasius-Clapeyron-Equation.html"]'),
  ('clausius_inequality', '{"en-us": "Clausius inequality"}', 'second_law', 9, '{"en-us": "A statement of the second law of thermodynamics: evaluated over any complete cycle, the net heat delivered to a system divided by the temperature at which it is exchanged cannot be positive. The equality holds only for fully reversible cycles, while real (irreversible) cycles give a negative value. This inequality underlies the definition of entropy and limits the performance of engines and refrigerators."}', '["https://en.wikipedia.org/wiki/Clausius_theorem", "https://pressbooks.pub/thermo/chapter/chapter-6-2", "https://www.sfu.ca/~mbahrami/ENSC%20388/Notes/Entropy.pdf", "https://engineerfix.com/what-the-clausius-inequality-reveals-about-entropy/"]'),
  ('coefficient_of_determination', '{"en-us": "Coefficient of determination"}', 'statistics', 8, '{"en-us": "Also known as R-squared, this statistic measures the proportion of the variance in the dependent variable that is explained by a regression model. It is computed from the unexplained variability left after fitting relative to the total variability around the mean, and ranges from 0 to 1 for models fitted by least squares. It is widely used to judge and compare goodness of fit."}', '["https://en.wikipedia.org/wiki/Coefficient_of_determination", "https://www.geeksforgeeks.org/maths/r-squared/", "https://statisticsfundamentals.com/simple-linear-regression/r-squared/", "https://mbrenndoerfer.com/writing/r-squared-coefficient-of-determination-formula-intuition-model-fit"]'),
  ('coefficient_of_performance', '{"en-us": "Coefficient of performance of a refrigerator"}', 'heat_engines', 7, '{"en-us": "Measures how efficiently a refrigerator moves heat, defined as the heat removed from the cold space per unit of net work supplied to the cycle, typically by the compressor. Unlike a heat-engine efficiency it can exceed one, since it compares useful heat moved rather than converted energy. Real values depend strongly on the temperature difference between reservoirs."}', '["https://www.thermal-engineering.org/what-is-coefficient-of-performance-cop-refrigerator-air-conditioner-definition/", "https://www.nuclear-power.com/nuclear-engineering/thermodynamics/thermodynamic-cycles/heating-and-air-conditioning/coefficient-of-performance-cop-refrigerator-air-conditioner/", "https://www.geeksforgeeks.org/physics/coefficient-of-performance-formula/"]'),
  ('coefficient_of_performance_heat_pump', '{"en-us": "Coefficient of performance of a heat pump"}', 'heat_engines', 7, '{"en-us": "Measures how efficiently a heat pump delivers heating, defined as the useful heat supplied to the warm space per unit of net work put into the cycle. Because the device moves existing thermal energy rather than generating it, this ratio can exceed one and is largest when the two reservoir temperatures are close. It is bounded above by the Carnot limit set by those temperatures."}', '["https://en.wikipedia.org/wiki/Coefficient_of_performance", "https://www.thermal-engineering.org/what-is-coefficient-of-performance-cop-heat-pump-definition", "https://www.linquip.com/blog/heat-pump-efficiency", "https://www.araner.com/blog/what-is-the-coefficient-of-performance-of-heat-pumps"]'),
  ('coefficient_of_restitution', '{"en-us": "Coefficient of restitution"}', 'collisions', 6, '{"en-us": "A dimensionless measure of how elastic a two-body collision is, given by the ratio of the relative speed of separation after impact to the relative speed of approach along the line of impact. It equals one for perfectly elastic collisions and vanishes when the bodies stick together in a perfectly inelastic one. It is used with momentum conservation to find post-collision velocities."}', '["https://en.wikipedia.org/wiki/Coefficient_of_restitution", "https://phys.libretexts.org/Courses/Merrimack_College/Conservation_Laws_Newton%27s_Laws_and_Kinematics_version_2.0/08%3A_C8)_Conservation_of_Energy-_Kinetic_and_Gravitational/8.05%3A_Relative_Velocity_and_the_Coefficient_of_Restitution", "https://www.vedantu.com/jee-main/physics-coefficient-of-restitution"]'),
  ('coefficient_of_variation', '{"en-us": "Coefficient of variation"}', 'statistics', 6, '{"en-us": "A unitless, relative measure of dispersion that expresses the standard deviation as a percentage of the mean. Because it strips units away, it allows comparison of variability between datasets with different scales or very different averages. It is only meaningful for ratio-scale data with a nonzero mean well away from zero."}', '["https://en.wikipedia.org/wiki/Coefficient_of_variation", "https://www.itl.nist.gov/div898/software/dataplot/refman2/auxillar/coefvari.htm", "https://www.geeksforgeeks.org/maths/coefficient-of-variation-formula/", "https://casrai.org/guides/coefficient-of-variation"]'),
  ('coherence_length_bandwidth', '{"en-us": "Coherence length from bandwidth"}', 'interference', 8, '{"en-us": "The coherence length is the propagation distance over which a light wave maintains a fixed phase relationship with itself. It is inversely proportional to the source''s spectral bandwidth, so narrow-linewidth lasers stay coherent over kilometers while broadband sources such as LEDs lose coherence within micrometers. This relation sets the maximum path-length difference usable in interferometry, coherent communications, and OCT imaging."}', '["https://en.wikipedia.org/wiki/Coherence_length", "https://www.rp-photonics.com/coherence_time.html", "https://ephotonics.com/coherence-length-calculator/", "https://www.toptica.com/fileadmin/Editors_English/04_applications/10_application_notes/01_Application_Note_-_Phase_and_Frequency_Locking_of_Diode_Lasers/Appl-1010_12_orders_of_coherence_control.pdf"]'),
  ('collision_elasticity_perfectly_elastic_relative_speed', '{"en-us": "Relative speed in elastic collision"}', 'collisions', 7, '{"en-us": "In a one-dimensional perfectly elastic collision, the relative speed at which two bodies approach each other before impact equals the relative speed at which they separate afterward. This follows from conserving both momentum and kinetic energy, and it corresponds to a coefficient of restitution of one. It serves as a shortcut equation when solving elastic collision problems."}', '["https://en.wikipedia.org/wiki/Elastic_collision", "https://openstax.org/books/college-physics-ap-courses/pages/8-4-elastic-collisions-in-one-dimension", "https://phys.libretexts.org/Courses/Merrimack_College/Conservation_Laws_Newton''s_Laws_and_Kinematics_version_2.0/08%3A_C8)_Conservation_of_Energy-_Kinetic_and_Gravitational/8.05%3A_Relative_Velocity_and_the_Coefficient_of_Restitution", "https://brilliant.org/wiki/analyzing-elastic-collisions/"]'),
  ('collision_kinetic_energy_loss', '{"en-us": "Kinetic energy loss in collision"}', 'collisions', 7, '{"en-us": "This relation gives the net change in the internal kinetic energy of a system during a collision. In an elastic collision it is zero, while in an inelastic collision it is negative because some kinetic energy is converted into heat, sound, or deformation; its magnitude is then reported as the energy lost. It is used to quantify how much ordered motion a crash or impact dissipates."}', '["https://openstax.org/books/college-physics-2e/pages/8-5-inelastic-collisions-in-one-dimension", "https://en.wikipedia.org/wiki/Inelastic_collision", "http://hyperphysics.phy-astr.gsu.edu/hbase/inecol.html", "https://www.usna.edu/Users/physics/mungan/_files/documents/Scholarship/PerfectlyInelastic.pdf"]'),
  ('collision_relative_approach_velocity', '{"en-us": "Relative approach velocity in collisions"}', 'collisions', 7, '{"en-us": "The relative approach velocity is the velocity of one colliding body as seen from the other, measuring how quickly the two bodies close on each other along the line of impact. A positive value indicates they are approaching; it is a key input for the coefficient-of-restitution relation used to analyze one-dimensional collisions."}', '["https://ocw.mit.edu/courses/8-01sc-classical-mechanics-fall-2016/mit8_01scs22_chapter15.pdf", "https://phys.libretexts.org/Courses/Merrimack_College/Conservation_Laws_Newton''s_Laws_and_Kinematics_version_2.0/08%3A_C8)_Conservation_of_Energy-_Kinetic_and_Gravitational/8.05%3A_Relative_Velocity_and_the_Coefficient_of_Restitution", "https://en.wikipedia.org/wiki/Relative_velocity"]'),
  ('combinations_ncr', '{"en-us": "Number of combinations"}', 'probability', 5, '{"en-us": "The binomial coefficient, or n choose r, counts how many distinct subsets of r items can be selected from a set of n distinguishable items when the order of selection does not matter. It is central to combinatorics and probability, appearing in counting arguments, lottery odds, and the binomial theorem, and applies for whole numbers with zero up to r equal to n without repetition."}', '["https://en.wikipedia.org/wiki/Combination", "https://mathworld.wolfram.com/BinomialCoefficient.html", "https://math.libretexts.org/Bookshelves/Combinatorics_and_Discrete_Mathematics/Combinatorics_(Morris)/02%3A_Enumeration/03%3A_Permutations_Combinations_and_the_Binomial_Theorem/3.02%3A_Combinations", "https://www.mathwords.com/c/combination_formula.htm"]'),
  ('combined_gas_law', '{"en-us": "Combined gas law"}', 'ideal_gases', 5, '{"en-us": "The combined gas law merges Boyle''s, Charles''s, and Gay-Lussac''s laws into a single statement relating the pressure, volume, and absolute temperature of a gas sample before and after a change of state. It is used to predict how one property shifts when the other two change, and it holds for a fixed amount of ideal gas, with temperatures expressed in kelvins."}', '["https://chem.libretexts.org/Courses/Anoka-Ramsey_Community_College/Introduction_to_Chemistry/09%3A_Gases/9.07%3A_The_Combined_Gas_Law", "https://www.chemteam.info/GasLaw/Gas-Combined.html", "https://www.physicsclassroom.com/Chemistry-Tutorial/Gases-and-Gas-Laws/Combined-Gas-Law", "https://en.wikipedia.org/?title=Combined_gas_law"]'),
  ('commutation_relation_quantum', '{"en-us": "Canonical commutation relation"}', 'quantum_mechanics', 10, '{"en-us": "The canonical commutation relation states how the quantum-mechanical position and momentum operators fail to commute, their commutator being defined as the difference of the two operator products. It is a cornerstone postulate of quantum mechanics, encoding that position and momentum are incompatible observables, and it directly implies the Heisenberg uncertainty principle."}', '["https://en.wikipedia.org/wiki/Canonical_commutation_relation", "https://en.wikipedia.org/wiki/canonical_quantization", "https://www.maths.dur.ac.uk/users/kasper.peeters/mathphys/uncertainty.html", "https://paulskrzypczyk.github.io/qm-lecture-notes/comm-up"]'),
  ('competitive_inhibition_velocity', '{"en-us": "Competitive inhibition velocity"}', 'biochemistry', 9, '{"en-us": "This modified Michaelis-Menten relation gives the initial reaction rate of an enzyme when a competitive inhibitor competes with the substrate for binding at the active site. The inhibitor raises the apparent Michaelis constant while leaving the maximum velocity unchanged, so inhibition can be overcome at high substrate concentration. It is widely used to analyze enzyme kinetics and to characterize inhibitor drugs."}', '["https://en.wikipedia.org/wiki/Competitive_inhibition", "https://bio.libretexts.org/Workbench/Biochem_Remix_Acevedo/06%3A_Enzyme_Activity/6.04%3A_Enzyme_Inhibition", "https://chem.libretexts.org/Courses/CSU_Chico/CSU_Chico%3A_CHEM_451_-_Biochemistry_I/CHEM_451_Test/08%3A_Transport_and_Kinetics/8.4%3A_Enzyme_Inhibition/Competitive_Inhibition", "https://math.libretexts.org/Bookshelves/Applied_Mathematics/Mathematical_Biology_(Chasnov)/06%3A_Biochemical_Reactions/6.03%3A_Competitive_Inhibition"]'),
  ('compound_interest', '{"en-us": "Compound interest future value"}', 'arithmetic', 5, '{"en-us": "This formula gives the future value of a sum of money earning compound interest, where interest is paid not only on the original principal but also on all previously accumulated interest. The rate is a nominal annual rate expressed as a decimal and applied over a whole number of compounding periods per year. It is standard for comparing savings accounts, investments, and loan balances."}', '["https://en.wikipedia.org/wiki/compound_interest", "https://openstax.org/books/contemporary-mathematics/pages/6-4-compound-interest", "https://math.libretexts.org/Courses/SUNY_Schenectady_County_Community_College/College_Mathematics_-_Abridged_Edition/05%3A_Savings_./5.02%3A_Compound_Interest", "https://www.purplemath.com/modules/expofcns3.htm"]'),
  ('compound_pendulum_period', '{"en-us": "Period of a compound (physical) pendulum"}', 'harmonic_motion', 8, '{"en-us": "A compound (physical) pendulum is an extended rigid body swinging about a fixed horizontal pivot under gravity, rather than a point mass on a massless string. Its small-angle oscillation period is set by the moment of inertia about the pivot and the distance from the pivot to the center of mass. It reduces to the simple-pendulum result in the point-mass limit and is the basis of precision gravimeters such as Kater''s reversible pendulum."}', '["https://ocw.mit.edu/courses/8-01sc-classical-mechanics-fall-2016/mit8_01scs22_chapter24.pdf", "https://www.physicsbootcamp.org/sho-Physical-Pendulum.html", "https://byjus.com/jee/simple-pendulum/", "https://unseel.com/physics/physical-pendulum"]'),
  ('compton_scattering', '{"en-us": "Compton scattering wavelength shift"}', 'quantum_mechanics', 9, '{"en-us": "The Compton shift is the increase in a photon''s wavelength after it scatters off a loosely bound (effectively free) electron, derived from relativistic energy and momentum conservation. The shift depends only on the scattering angle and not on the incident wavelength, growing from zero for forward scattering to twice the electron''s Compton wavelength for backscattering. Its 1923 observation was decisive evidence for the particle nature of light."}', '["https://en.wikipedia.org/wiki/Compton_scattering", "https://phys.libretexts.org/Bookshelves/Modern_Physics/Spiral_Modern_Physics_(D''Alessandris)/4%3A_The_Photon/4.2%3A_Compton_Scattering", "https://www.britannica.com/science/electromagnetic-radiation/Compton-effect", "https://www-users.york.ac.uk/~pjd113/notebooks/1_4_ComptonScattering.html"]'),
  ('compton_wavelength_definition', '{"en-us": "Compton wavelength"}', 'particle_physics', 8, '{"en-us": "The Compton wavelength is a fundamental length scale associated with a massive particle, defined as the wavelength of a photon whose energy equals the particle''s rest energy. It sets the scale for the wavelength shift in Compton scattering and marks the regime below which relativistic quantum effects become essential. For the electron it is about 2.43 picometers."}', '["https://en.wikipedia.org/wiki/Compton_wavelength", "https://phys.libretexts.org/Courses/Muhlenberg_College/MC_%3A_Physics_213_-_Modern_Physics/03%3A_Photons_and_Matter_Waves/3.04%3A_The_Compton_Effect", "https://proofwiki.org/wiki/Definition:Compton_Wavelength", "https://www.calctool.org/quantum-mechanics/compton-wavelength"]'),
  ('concentration_formula', '{"en-us": "Concentration from amount and volume"}', 'solution_stoichiometry', 4, '{"en-us": "Molar concentration (molarity) quantifies how much solute is dissolved in a given volume of solution. It is the central quantity for solution stoichiometry, allowing conversion between moles of reactants/products and measurable solution volumes. It assumes a homogeneous solution and is usually reported in mol/L (molar, M)."}', '["https://en.wikipedia.org/wiki/Molar_concentration", "https://chem.libretexts.org/Bookshelves/General_Chemistry/General_Chemistry_-_An_Atoms_First_Approach_(Halpern)/Unit_3%3A_Stoichiometry/Chapter_8%3A_Aqueous_Solutions/Chapter_8.02%3A_Solution_Concentrations", "https://chem.libretexts.org/Courses/Shasta_College/Introduction_to_General_Chemistry_%2C_Chem_1A/06%3A_Composition_of_Substances_and_Solutions/6.04%3A_Molarity", "https://www.alloprof.qc.ca/en/students/vl/sciences/calculating-molar-concentration-s1622"]'),
  ('concentration_from_mass_volume', '{"en-us": "Concentration from mass and volume"}', 'solution_stoichiometry', 4, '{"en-us": "Gives the molar concentration of a solution when the solute is measured by weight rather than in moles. The solute mass is first converted to an amount of substance using its molar mass, then related to the total solution volume. Widely used for preparing laboratory solutions of a target molarity from a weighed solid."}', '["https://bioprocesstools.com/blog/how-to-calculate-molarity/", "https://www.chemistrylearner.com/concentration-of-solution/molarity", "https://www.sigmaaldrich.com/US/en/support/calculators-and-apps/mass-molarity-calculator", "https://en.wikipedia.org/wiki/Molar_concentration"]'),
  ('concentration_ppm', '{"en-us": "Concentration in ppm"}', 'solution_stoichiometry', 4, '{"en-us": "Parts per million expresses trace-level concentrations: how many parts of solute are present per million parts of solution, by mass. It is used for very dilute mixtures such as pollutants in water or air, where molarity would be an unwieldy tiny number. Both masses must be in the same units, and the mass of solution includes the solute itself."}', '["https://chem.libretexts.org/Courses/Los_Angeles_Southwest_College/LASC__Chemistry_60_-_Introduction_to_General_Chemistry/03%3A_Composition_of_Substances_and_Solutions/3.05%3A_Other_Units_for_Solution_Concentrations", "https://pressbooks.online.ucf.edu/chemistryfundamentals/chapter/other-units-for-solution-concentrations/", "https://chem-textbook.ucalgary.ca/version2/review-of-background-topics/measurements-and-data/measurements-in-chemistry/parts-per-million-ppm-and-parts-per-billion-ppb/", "https://www.chemistrylearner.com/concentration-of-solution/parts-per-million"]'),
  ('conditional_probability', '{"en-us": "Conditional probability"}', 'probability', 6, '{"en-us": "The conditional probability of event A given that event B has occurred measures how likely A is once the sample space is restricted to outcomes where B happens. It underlies Bayes'' theorem, the multiplication rule, and independence testing. It is defined only when B has nonzero probability."}', '["https://en.wikipedia.org/wiki/Conditional_probability", "https://online.stat.psu.edu/stat414/Lesson04", "https://www.probabilitycourse.com/chapter1/1_4_0_conditional_probability.php", "https://math.libretexts.org/Courses/Los_Angeles_City_College/STAT_C1000/04%3A_Probability_Concepts/4.05%3A_Conditional_Probability_and_Multiplication__Rules"]'),
  ('conductance_formula', '{"en-us": "Conductance from resistance"}', 'circuits', 5, '{"en-us": "Electrical conductance measures how easily electric current passes through a component or circuit element. It is the reciprocal of resistance and offers the opposite viewpoint of the same property: high conductance means low opposition to current flow. Its SI unit is the siemens (S), formerly called the mho."}', '["https://en.wikipedia.org/wiki/Electrical_resistance_and_conductance", "https://eng.libretexts.org/Workbench/Introduction_to_Circuit_Analysis/01%3A_Basic_Concepts_and_Quantitites/1.07%3A_Resistance_and_Conductance", "https://www.allaboutcircuits.com/textbook/direct-current/chpt-5/conductance/", "https://goldbook.iupac.org/terms/view/E01925"]'),
  ('conservation_angular_momentum', '{"en-us": "Conservation of angular momentum"}', 'angular_momentum', 6, '{"en-us": "The total angular momentum of a system stays constant when no net external torque acts on it. Individual parts of the system may exchange rotational motion, but the total about the given axis cannot change. This law explains effects such as a figure skater spinning faster by pulling in their arms and governs rotating collisions and orbital motion."}', '["https://openstax.org/books/college-physics-ap-courses-2e/pages/10-5-angular-momentum-and-its-conservation", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/11%3A__Angular_Momentum/11.04%3A_Conservation_of_Angular_Momentum", "https://en.wikipedia.org/wiki/Conservation_of_angular_momentum", "https://brilliant.org/wiki/conservation-of-angular-momentum/"]'),
  ('conservation_momentum_1d', '{"en-us": "Conservation of momentum in one dimension"}', 'linear_momentum', 5, '{"en-us": "In an isolated system of two colliding bodies moving along one line, the total linear momentum before the collision equals the total after, even though each body''s momentum generally changes. This holds for elastic and inelastic collisions alike and follows from Newton''s third law when no net external force acts. Velocities are signed, so direction is handled by sign convention."}', '["https://openstax.org/books/college-physics/pages/8-4-elastic-collisions-in-one-dimension", "http://farside.ph.utexas.edu/teaching/301/lectures/node76.html", "http://www.studyphysics.ca/2007/30/05_momentum/03_1d.pdf", "https://ocw.mit.edu/courses/16-07-dynamics-fall-2009/a867999737497c79fd8ffe97641c503f_MIT16_07F09_Lec09.pdf"]'),
  ('conservation_momentum_2d_x', '{"en-us": "Conservation of momentum in 2D"}', 'linear_momentum', 6, '{"en-us": "In a two-dimensional collision with no net external force, each component of the total momentum is conserved independently. This is the x-axis statement of that law: it equates the sum of the objects'' initial x-components of momentum with the sum of their final x-components. It is written out alongside an identical y-component equation, giving two scalar equations for analyzing glancing collisions."}', '["https://openstax.org/books/college-physics-ap-courses-2e/pages/8-6-collisions-of-point-masses-in-two-dimensions", "https://openstax.org/books/university-physics-volume-1/pages/9-5-collisions-in-multiple-dimensions", "https://phys.libretexts.org/Courses/Prince_Georges_Community_College/General_Physics_I%3A_Classical_Mechanics/31%3A_Collisions/31.06%3A_Collisions_in_Two_Dimensions", "https://farside.ph.utexas.edu/teaching/301/lectures/node77.html"]'),
  ('conservation_of_mechanical_energy', '{"en-us": "Conservation of mechanical energy"}', 'conservation_of_energy', 5, '{"en-us": "The total mechanical energy of a system — kinetic plus potential — remains constant between two states when only conservative forces (gravity, spring forces) do work. Energy may shift form, but none is lost to friction or drag. This principle is the workhorse of mechanics problems such as falling bodies, pendulums, and roller coasters, where it relates speeds to heights without needing force details."}', '["https://openstax.org/books/university-physics-volume-1/pages/8-3-conservation-of-energy", "https://en.wikipedia.org/wiki/Conservation_of_mechanical_energy", "https://phys.libretexts.org/Bookshelves/Conceptual_Physics/Introduction_to_Physics_(Park)/03%3A_Unit_2-_Mechanics_II_-_Energy_and_Momentum_Oscillations_and_Waves_Rotation_and_Fluids/03%3A_Work_and_Energy/3.05%3A_Conservative_Forces_Potential_Energy_and_Conservation_of_Energy", "https://kpu.pressbooks.pub/foundationsofphysics/chapter/chapter-11-conservation-of-mechanical-energy/"]'),
  ('constructive_interference_condition', '{"en-us": "Constructive interference condition"}', 'wave_interference', 7, '{"en-us": "Two waves that start out in phase reinforce each other — producing a maximum or bright fringe — whenever the extra distance traveled by one wave is a whole number of wavelengths. This condition locates the maxima in interference patterns such as Young''s double-slit experiment, thin films, and diffraction gratings. The integer n is called the order number; it assumes coherent, in-phase sources."}', '["https://openstax.org/books/university-physics-volume-3/pages/3-2-mathematics-of-interference", "https://openstax.org/books/college-physics-2e/pages/27-3-youngs-double-slit-experiment", "https://ocw.mit.edu/courses/8-02-physics-ii-electricity-and-magnetism-spring-2007/c1ef2e99446d7c4255e32752af8f6d26_ch14_inter_diffr.pdf", "https://lipa.physics.oregonstate.edu/sec_phase_diff.html"]'),
  ('continuity_equation', '{"en-us": "Continuity equation"}', 'continuity_equation', 7, '{"en-us": "For an incompressible fluid flowing steadily through a pipe or channel, the volume passing any cross-section per unit time is the same everywhere along the flow. Consequently, fluid speeds up where the conduit narrows and slows where it widens — the reason water squirts faster from a pinched hose. It is the conservation-of-mass statement for fluids of constant density and assumes the pipe runs completely full."}', '["https://www.physicsclassroom.com/class/fluids/fluids-in-motion/equation-of-continuity", "https://brilliant.org/wiki/continuity-equation-fluids/", "https://boxsand.physics.oregonstate.edu/sites/boxsand.physics.oregonstate.edu/files/Media-3/Ryan/ph202_su18/lecture_complete/fluids/Fluid%20dynamics%20-%20continuity.pdf", "https://web.stanford.edu/~cantwell/AA210A_Course_Material/AA210A_Lectures/AA210A_Chapter_1_Intro_to_fluid_flow_Brian_J_Cantwell.pdf"]'),
  ('continuity_equation_mass_flow', '{"en-us": "Mass flow rate continuity"}', 'continuity_equation', 6, '{"en-us": "The mass of fluid crossing any cross-section of a stream tube per unit time is the same at every station along a steady flow, a direct statement of conservation of mass. Unlike the volume-based form, this version keeps the density explicit, so it applies to compressible gases as well as liquids. It is fundamental to nozzle, turbine, and duct analysis in aerodynamics and engineering."}', '["https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/mass-flow-rate-equations/", "https://www.grc.nasa.gov/www/K-12/airplane/mflchk.html", "https://eng.libretexts.org/Bookshelves/Civil_Engineering/Fluid_Mechanics_(Bar-Meir)/11%3A_Compressible_Flow_One_Dimensional/11.4_Isentropic_Flow/11.4.5%3A_Mass_Flow_Rate_(Number)", "http://brennen.caltech.edu/fluidbook/basicfluiddynamics/compressibleflow/onedimensionalisentropicflow.pdf"]'),
  ('conversion_efficiency_yield', '{"en-us": "Conversion efficiency from yield"}', 'percent_yield', 6, '{"en-us": "Percent yield measures the efficiency of a chemical reaction by comparing the amount of product actually obtained (actual yield) to the maximum amount predicted by stoichiometry from the limiting reactant (theoretical yield). It is used to assess how much material is lost to side reactions, incomplete conversion, or losses during purification. Actual and theoretical yields must be expressed in the same units."}', '["https://chem.libretexts.org/Bookshelves/Introductory_Chemistry/Introductory_Chemistry_(CK-12)/12%3A_Stoichiometry/12.09%3A_Theoretical_Yield_and_Percent_Yield", "https://www.cuemath.com/percentage-yield-formula", "https://sciencenotes.org/percent-yield-formula-and-definition/", "https://flexbooks.ck12.org/cbook/ck-12-chemistry-flexbook-2.0/section/12.9/primary/lesson/theoretical-yield-and-percent-yield-chem/"]'),
  ('convex_mirror_focal_sign', '{"en-us": "Convex mirror focal length sign"}', 'mirrors', 5, '{"en-us": "A convex mirror diverges light, so its focal point lies behind the reflecting surface. Under the real-is-positive sign convention this makes its focal length negative, with magnitude equal to half the radius of curvature. This sign matters when applying the mirror equation to locate virtual, upright, diminished images."}', '["https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_%28OpenStax%29/University_Physics_III_-_Optics_and_Modern_Physics_%28OpenStax%29/02%3A_Geometric_Optics_and_Image_Formation/2.03%3A_Spherical_Mirrors", "https://flexbooks.ck12.org/cbook/cbse-physics-class-10/section/1.4/primary/lesson/images-formed-by-convex-mirrors/", "https://www.geeksforgeeks.org/physics/sign-convention-for-spherical-mirrors/"]'),
  ('coordinate_geometry_centroid_formula', '{"en-us": "Centroid of a triangle (coordinates)"}', 'coordinate_geometry', 5, '{"en-us": "The centroid of a triangle is the point where its three medians intersect, and it acts as the triangle''s center of mass for a uniform lamina. In coordinates it is found by averaging the vertices'' positions separately in each direction. The centroid always lies inside the triangle and divides each median in a 2:1 ratio."}', '["https://en.m.wikipedia.org/wiki/Centroid", "https://www.cuemath.com/centroid-formula", "https://www.cuemath.com/geometry/centroid-of-a-triangle/"]'),
  ('coordination_number_definition', '{"en-us": "Coordination number definition"}', 'inorganic_chemistry', 6, '{"en-us": "In coordination chemistry, the coordination number of a central metal atom or ion is the count of ligand donor atoms directly bonded to it. For monodentate ligands this equals the number of ligands, while chelating (polydentate) ligands contribute one attachment point per donor atom. It determines the geometry of the complex, with values of 2, 4, and 6 being most common for transition metals."}', '["https://en.wikipedia.org/wiki/Coordination_number", "https://chem.libretexts.org/Bookshelves/Inorganic_Chemistry/Inorganic_Chemistry_(LibreTexts)/09:_Coordination_Chemistry_I_-_Structure_and_Isomers/9.05:_Coordination_Numbers_and_Structures", "https://www.britannica.com/science/coordination-number"]'),
  ('correlation_coefficient_formula', '{"en-us": "Pearson correlation coefficient"}', 'statistics', 7, '{"en-us": "The Pearson correlation coefficient measures the strength and direction of the linear relationship between two variables. It is a normalized, unitless version of the covariance, always falling between -1 and +1. Values near the extremes indicate strong linear association, while values near zero indicate little or no linear relationship; it captures only linear dependence."}', '["https://en.wikipedia.org/wiki/Pearson_correlation_coefficient", "https://stats.libretexts.org/Courses/Taft_College/PSYC_2200%3A_Elementary_Statistics_for_Behavioral_and_Social_Sciences_(Oja)/03%3A_Relationships/14%3A_Correlations/14.06%3A_Correlation_Formula-__Covariance_Divided_by_Variability", "https://www.danielsoper.com/statcalc/formulas.aspx?id=45"]'),
  ('cosecant_identity', '{"en-us": "Cosecant identity"}', 'trigonometric_identities', 5, '{"en-us": "The cosecant is one of the six trigonometric functions and is defined as the reciprocal of the sine, so it equals the ratio of the hypotenuse to the opposite side in a right triangle. It is undefined wherever the sine vanishes (at integer multiples of pi). This identity is used to rewrite expressions and prove other trigonometric relations."}', '["https://en.wikipedia.org/wiki/Trigonometric_functions", "https://www.cuemath.com/trigonometry/reciprocal-identities/", "https://www.mathwords.com/r/reciprocal_identities.htm"]'),
  ('cosecant_squared_identity', '{"en-us": "Cosecant Squared Identity"}', 'trigonometric_identities', 6, '{"en-us": "This Pythagorean identity relates the square of the cosecant to the square of the cotangent. It follows from dividing the fundamental identity sin²θ + cos²θ = 1 by sin²θ and holds wherever both functions are defined (sin θ ≠ 0). It is frequently used to simplify trigonometric expressions and to evaluate integrals involving cosecant."}', '["https://en.wikipedia.org/wiki/Pythagorean_trigonometric_identity", "https://www.mathdoubts.com/csc-squared-formula/", "https://mathalino.com/reviewer/derivation-of-formulas/derivation-of-pythagorean-identities"]'),
  ('cosine_definition', '{"en-us": "Cosine definition"}', 'right_triangles', 3, '{"en-us": "In a right triangle, the cosine of an acute angle is defined as the ratio of the length of the side adjacent to that angle to the length of the hypotenuse. This ratio depends only on the angle, not on the triangle''s size, which makes it the basis for solving right triangles. It is the ''CAH'' part of the SOH-CAH-TOA mnemonic."}', '["https://en.wikipedia.org/wiki/Sine_and_cosine", "https://math.libretexts.org/Courses/Reedley_College/Trigonometry/01:_The_Six_Trigonometric_Functions/1.02:_Right_Triangle_Trigonometry", "https://www.britannica.com/science/cosine"]'),
  ('cotangent_identity', '{"en-us": "Cotangent identity"}', 'trigonometric_identities', 5, '{"en-us": "This quotient identity defines the cotangent as the ratio of the cosine to the sine of the same angle, equivalently the reciprocal of the tangent. In a right triangle it equals the adjacent side divided by the opposite side. It is undefined wherever the sine vanishes (at integer multiples of pi) and is used to rewrite expressions in terms of sine and cosine."}', '["https://www.geeksforgeeks.org/maths/quotient-identities", "https://en.neurochispas.com/trigonometry/quotient-identities-formulas-and-examples/", "https://fiveable.me/honors-pre-calc/key-terms/quotient-identities"]'),
  ('coulomb_force_dielectric', '{"en-us": "Coulomb force in a dielectric medium"}', 'electrostatics', 7, '{"en-us": "When two point charges interact inside an insulating (dielectric) material, the surrounding medium polarizes and weakens their mutual electrostatic force. The force is reduced relative to vacuum by the medium''s relative permittivity (dielectric constant). This form of Coulomb''s law applies to point charges at rest in a homogeneous, linear dielectric."}', '["https://www.vedantu.com/jee-main/physics-permittivity-and-relative-permittivity-for-coulombs-law", "https://phys.libretexts.org/Bookshelves/Electricity_and_Magnetism/Electricity_and_Magnetism_(Tatum)/01%3A_Electric_Fields/1.05%3A_Coulomb%27s_Law", "https://farside.ph.utexas.edu/teaching/316/lectures/node45.html"]'),
  ('coulomb_force_vacuum', '{"en-us": "Coulomb force in vacuum"}', 'electrostatics', 6, '{"en-us": "Coulomb''s law in vacuum gives the electrostatic force between two stationary point charges. The force acts along the line joining the charges, is repulsive for like charges and attractive for opposite ones, and weakens with the square of their separation. It applies exactly to point (or spherically symmetric) charges at rest in free space."}', '["https://en.wikipedia.org/wiki/Coulomb%27s_law", "https://phys.libretexts.org/Bookshelves/Electricity_and_Magnetism/Electricity_and_Magnetism_(Tatum)/01%3A_Electric_Fields/1.05%3A_Coulomb%27s_Law", "https://openstax.org/books/physics/pages/18-2-coulombs-law"]'),
  ('coulombs_law', '{"en-us": "Coulomb''s law"}', 'electrostatics', 6, '{"en-us": "Coulomb''s law gives the magnitude of the electrostatic force between two point charges at rest: it is proportional to the product of the charges, inversely proportional to the square of their separation, and directed along the line joining them. Like charges repel and opposite charges attract. It is the foundation of electrostatics, valid for point charges or spherically symmetric charge distributions."}', '["https://en.wikipedia.org/wiki/Coulomb%27s_law", "https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/18%3A_Electric_Charge_and_Electric_Field/18.03%3A_Coulomb%27s_Law", "https://openstax.org/books/physics/pages/18-2-coulombs-law"]'),
  ('covariance_formula', '{"en-us": "Covariance of two variables"}', 'statistics', 7, '{"en-us": "Covariance measures how two random variables vary together: positive values indicate the variables tend to move in the same direction, negative values indicate opposite movement, and zero indicates no linear association. This computational form follows from expanding the definitional expectation of the product of deviations and is widely used in deriving correlations and portfolio variance."}', '["https://en.wikipedia.org/wiki/Covariance", "https://www.probabilitycourse.com/chapter5/5_3_1_covariance_correlation.php", "https://stats.libretexts.org/Bookshelves/Probability_Theory/Applied_Probability_(Pfeiffer)/12:_Variance_Covariance_and_Linear_Regression/12.02:_Covariance_and_the_Correlation_Coefficient", "https://www.britannica.com/topic/covariance"]'),
  ('critical_angle', '{"en-us": "Critical angle for total internal reflection"}', 'refraction', 6, '{"en-us": "The critical angle is the angle of incidence, measured from the normal, at which the refracted ray grazes along the boundary between two media. At incidence angles above it, light is completely reflected back into the incident medium (total internal reflection), which only occurs going from an optically denser to a rarer medium; this principle underlies optical fibers and prism binoculars."}', '["https://en.wikipedia.org/wiki/Total_internal_reflection", "https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_%28OpenStax%29/25%3A_Geometric_Optics/25.04%3A_Total_Internal_Reflection", "https://www.physicsclassroom.com/tutorial/refraction-and-lenses/total-internal-reflection/critical-angle", "http://labman.phys.utk.edu/phys222core/modules/m7/internal-reflection.html"]'),
  ('critical_reynolds_number', '{"en-us": "Critical Reynolds number"}', 'reynolds_number', 8, '{"en-us": "The critical Reynolds number is the approximate value of the Reynolds number at which fluid flow in a circular pipe transitions from laminar to turbulent regime. It is an empirical, geometry-dependent threshold (about 2300 for fully developed pipe flow) rather than a universal constant, since inlet conditions, roughness, and disturbances shift the observed transition point."}', '["https://en.wikipedia.org/wiki/Reynolds_number", "https://www.nuclear-power.com/nuclear-engineering/fluid-dynamics/reynolds-number/critical-reynolds-number/", "https://www.engineeringtoolbox.com/reynolds-number-d_237.html", "https://www.princeton.edu/~asmits/Bicycle_web/transition.html"]'),
  ('cross_product_magnitude', '{"en-us": "Cross product magnitude"}', 'linear_algebra', 6, '{"en-us": "The magnitude of the cross product of two vectors equals the area of the parallelogram they span. It vanishes when the vectors are parallel or antiparallel and is maximal when they are perpendicular; the cross-product vector itself points perpendicular to both inputs with direction given by the right-hand rule."}', '["https://en.wikipedia.org/wiki/Cross_product", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/12%3A_Vectors_in_Space/12.04%3A_The_Cross_Product", "http://lipa.physics.oregonstate.edu/sec_cross-product.html"]'),
  ('crystal_field_splitting_octahedral', '{"en-us": "Crystal field splitting energy (octahedral)"}', 'inorganic_chemistry', 9, '{"en-us": "In an octahedral transition-metal complex, the electrostatic field of six surrounding ligands splits the five d orbitals into a lower t2g set and a higher eg set. The octahedral crystal field splitting energy is the gap between these two sets; by convention it equals ten times the ligand-field parameter Dq. Its size relative to the pairing energy decides whether a complex is high-spin or low-spin and largely determines its color."}', '["https://chem.libretexts.org/Bookshelves/Inorganic_Chemistry/Supplemental_Modules_and_Websites_%28Inorganic_Chemistry%29/Crystal_Field_Theory/Crystal_Field_Theory", "https://chemistry.stackexchange.com/questions/31276/in-crystal-field-theory-what-does-%CE%94o-10dq-mean", "https://en.wikibooks.org/wiki/Introduction_to_Inorganic_Chemistry/Coordination_Chemistry_and_Crystal_Field_Theory"]'),
  ('current_density_definition_microscopic', '{"en-us": "Microscopic current density"}', 'current_electricity', 7, '{"en-us": "This relation connects the macroscopic current density in a conductor to the microscopic motion of its charge carriers: it equals the carrier number density times the charge per carrier times the average drift velocity. It applies when carriers of a single type drift through the material, as in metals or doped semiconductors, and shows why even tiny drift speeds yield sizable currents given enormous carrier densities."}', '["https://en.wikipedia.org/wiki/Drift_velocity", "https://phys.libretexts.org/Bookshelves/University_Physics/Book%3A_Introductory_Physics_-_Building_Models_to_Describe_Our_World_%28Martin_Neary_Rinaldo_and_Woodman%29/19%3A_Electric_Current/19.02%3A_Microscopic_model_of_current", "https://academic.mu.edu/phys/matthysd/web004/L0204.htm"]'),
  ('current_density_formula', '{"en-us": "Current density"}', 'current_electricity', 7, '{"en-us": "Current density is the amount of electric current flowing through a unit cross-sectional area of a conductor, measured in amperes per square meter. It characterizes how concentrated the charge flow is at a point and is used to size wires and analyze current distribution; the full quantity is a vector pointing along the motion of positive charge."}', '["https://en.wikipedia.org/wiki/Current_density", "https://www.geeksforgeeks.org/physics/current-density/", "https://www.vedantu.com/physics/current-density"]'),
  ('current_drift_velocity_relation', '{"en-us": "Current from drift velocity"}', 'current_electricity', 7, '{"en-us": "This relation expresses the electric current in a conductor in terms of the microscopic drift of its charge carriers: carrier density, carrier charge, cross-sectional area, and drift speed together determine the total charge passing a section per unit time. It applies to conductors or semiconductors with a single dominant carrier type moving at a uniform average drift speed."}', '["https://www.khanacademy.org/science/in-in-class-12th-physics-india/in-in-current-electricity/x51bd77206da864f3%3Adrift-of-electrons-the-origin-of-resistance/v/current-from-drift-velocity-i-neavd", "https://en.wikipedia.org/wiki/Drift_velocity", "https://www.electricalvolt.com/relation-between-current-and-drift-velocity", "https://www.electricaldeck.com/2023/07/relation-between-current-and-drift-velocity.html"]'),
  ('cyclotron_frequency', '{"en-us": "Cyclotron frequency"}', 'magnetism', 8, '{"en-us": "The cyclotron frequency is the rate at which a charged particle completes circular orbits in a plane perpendicular to a uniform magnetic field, with the magnetic force supplying the centripetal force. Remarkably, it depends only on the particle''s charge-to-mass ratio and the field strength — not on its speed or orbit radius — which is the property that makes cyclotron accelerators work; relativistic speeds cause the simple formula to break down."}', '["https://en.wikipedia.org/wiki/Cyclotron_motion", "https://www.omnicalculator.com/physics/cyclotron-frequency", "https://fiveable.me/principles-physics-ii/key-terms/cyclotron-frequency"]'),
  ('cyclotron_radius', '{"en-us": "Cyclotron radius"}', 'magnetism', 8, '{"en-us": "The cyclotron radius (also called Larmor radius or gyroradius) is the radius of the circular orbit traced by a charged particle moving perpendicular to a uniform magnetic field, where the magnetic Lorentz force supplies the centripetal force. The orbit grows with particle momentum and tightens with stronger fields or greater charge; it underlies mass spectrometer separation and cyclotron beam dynamics."}', '["https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_%28OpenStax%29/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_%28OpenStax%29/11%3A_Magnetic_Forces_and_Fields/11.04%3A_Motion_of_a_Charged_Particle_in_a_Magnetic_Field", "https://en.wikipedia.org/wiki/Cyclotron_motion", "https://physref.app/formulas/cyclotron-radius/"]'),
  ('cylinder_volume_from_diameter', '{"en-us": "Volume of a cylinder from diameter"}', 'plane_geometry', 3, '{"en-us": "This formula gives the volume enclosed by a right circular cylinder when its diameter rather than radius is measured directly. Since the circular base area involves half the diameter squared, a factor of four appears in the denominator. It is handy in practical settings such as piping, tanks, and machining where diameters are easier to measure than radii."}', '["https://www.omnicalculator.com/math/cylinder-volume", "https://www.ck12.org/flexi/geometry/volume-of-cylinders/how-to-find-volume-of-cylinder-with-diameter/"]'),
  ('dalton_law_partial_pressure', '{"en-us": "Dalton''s law of partial pressures"}', 'ideal_gases', 5, '{"en-us": "Dalton''s law states that the total pressure exerted by a mixture of non-reacting gases equals the sum of the partial pressures of its components, where each partial pressure is what that gas would exert if it occupied the container alone. It follows from the ideal gas model, in which gas molecules act independently, and is used to analyze gas mixtures such as air and collected-over-water gas samples."}', '["https://en.wikipedia.org/wiki/Dalton%27s_law", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_%28Physical_and_Theoretical_Chemistry%29/Physical_Properties_of_Matter/States_of_Matter/Properties_of_Gases/Gas_Laws/Dalton%27s_Law_%28Law_of_Partial_Pressures%29", "https://www.engineeringtoolbox.com/partial-pressure-ideal-gas-law-total-mixture-blending-d_1968.html"]'),
  ('damped_oscillator_ode', '{"en-us": "Damped harmonic oscillator differential equation"}', 'differential_equations', 9, '{"en-us": "Second-order linear ODE governing a displaced mass acted on by a spring-like restoring force and a viscous drag proportional to velocity. It is obtained from Newton''s second law after dividing out the mass; the balance between the damping coefficient and the natural frequency determines whether the motion is underdamped, critically damped, or overdamped."}', '["https://en.wikipedia.org/wiki/Harmonic_oscillator", "https://en.wikipedia.org/wiki/Damped_harmonic_oscillator", "https://phys.libretexts.org/Bookshelves/Mathematical_Physics_and_Pedagogy/Complex_Methods_for_the_Sciences_(Chong)/05%3A_Complex_Oscillations/5.01%3A_The_Damped_Harmonic_Oscillator", "https://farside.ph.utexas.edu/teaching/315/Waveshtml/node12.html"]'),
  ('de_broglie_wavelength', '{"en-us": "De Broglie wavelength"}', 'quantum_mechanics', 8, '{"en-us": "Central relation of de Broglie''s matter-wave hypothesis: every moving particle behaves as a wave whose wavelength is set by its momentum through Planck''s constant. Used to predict electron and neutron diffraction; the wave character becomes observable mainly for microscopic particles, since macroscopic momenta give negligibly short wavelengths."}', '["https://en.wikipedia.org/wiki/De_Broglie_wavelength", "https://phys.libretexts.org/Courses/Muhlenberg_College/MC_%3A_Physics_213_-_Modern_Physics/03%3A_Photons_and_Matter_Waves/3.06%3A_De_Broglies_Matter_Waves", "https://www.geeksforgeeks.org/physics/de-broglie-wavelength-formula/", "http://labman.phys.utk.edu/phys222core/modules/m10/matter_waves.html"]'),
  ('degree_of_polarization_formula', '{"en-us": "Degree of polarization from intensity"}', 'polarization', 8, '{"en-us": "Measures what fraction of a light beam''s intensity is polarized, obtained by rotating an ideal analyzer and recording the maximum and minimum transmitted intensities. It runs from 0 for unpolarized light to 1 for fully polarized light; the max/min form applies to partially linearly polarized beams."}', '["https://en.wikipedia.org/wiki/Degree_of_polarization", "https://www.physics.umd.edu/courses/Phys375/GammonSpring08/lab3.pdf", "https://interactivetextbooks.tudelft.nl/interactive-optics/content/Chap4_Polarisation/Polarization_2022_01Clean.html", "https://www.pw.live/school-prep/exams/polarization-formula"]'),
  ('degree_of_polymerization', '{"en-us": "Degree of polymerization"}', 'organic_chemistry', 8, '{"en-us": "Gives the number of monomeric repeat units in a polymer chain, a dimensionless measure of chain length. For a homopolymer it follows from the chain''s average molar mass and the repeat unit''s molar mass; number-average and weight-average variants exist because real polymers have a distribution of chain lengths."}', '["https://en.wikipedia.org/wiki/Degree_of_polymerization", "https://chem.libretexts.org/Bookshelves/Organic_Chemistry/Polymer_Chemistry_(Schaller)/04%3A_Polymer_Properties/4.01%3A_Molecular_Weight", "https://courses.ems.psu.edu/matse202/node/7", "https://eng.libretexts.org/Bookshelves/Materials_Science/Polymer_Physics_(Steimel)/Chapter_2%3A_Polymerization"]'),
  ('degree_of_unsaturation', '{"en-us": "Degree of unsaturation"}', 'organic_chemistry', 7, '{"en-us": "Counts the total number of rings plus pi bonds in an organic molecule from its molecular formula, comparing the hydrogen count against a fully saturated acyclic reference. Each ring or double bond contributes one degree and each triple bond two; oxygen and sulfur are ignored. Halogens are omitted here; subtracting them too gives the modern index of hydrogen deficiency."}', '["https://en.wikipedia.org/wiki/Degree_of_unsaturation", "https://chem.libretexts.org/Courses/can/CHEM_231%3A_Organic_Chemistry_I_Textbook/07%3A_Alkenes-_Structure_and_Reactivity/7.02%3A_Calculating_Degree_of_Unsaturation", "https://chem.libretexts.org/Bookshelves/Organic_Chemistry/Organic_Chemistry_I_(Liu)/02%3A_Fundamental_of_Organic_Structures/2.05%3A_Degree_of_Unsaturation_Index_of_Hydrogen_Deficiency", "https://www.chemistrysteps.com/degree-of-unsaturation/"]'),
  ('density_concentration_molar_mass', '{"en-us": "Mass concentration from molarity and molar mass"}', 'solutions', 7, '{"en-us": "Converts the molar concentration of a dissolved substance into its mass concentration by way of its molar mass, letting chemists switch between moles-per-liter and grams-per-liter when preparing solutions or running stoichiometry. Note it counts only solute mass per liter of solution, so it equals the solution''s density only for a pure substance."}', '["https://www.calcipedia.org/calculators/molarity-calculator/", "https://www.sigmaaldrich.com/US/en/support/calculators-and-apps/mass-molarity-calculator", "https://chem.libretexts.org/Courses/Fullerton_College/Introductory_Biochemistry/11%3A9_Solutions/11.03%3A_Concentration", "https://www.omnicalculator.com/chemistry/concentration"]'),
  ('density_formula', '{"en-us": "Density"}', 'pressure', 2, '{"en-us": "Defines density as how much mass is packed into a unit volume of a substance. It is an intensive material property used to identify substances, convert between mass and volume, and predict whether objects float or sink. For non-uniform materials it gives the average density; values change with temperature and pressure."}', '["https://en.wikipedia.org/wiki/Density", "https://openstax.org/books/college-physics/pages/11-2-density", "https://phys.libretexts.org/Bookshelves/Conceptual_Physics/Introduction_to_Physics_(Park)/03%3A_Unit_2-_Mechanics_II_-_Energy_and_Momentum_Oscillations_and_Waves_Rotation_and_Fluids/07%3A_Fluids/7.03%3A_Density", "https://www.britannica.com/science/density"]'),
  ('derivative_abs_x', '{"en-us": "Derivative of Absolute Value"}', 'derivatives', 6, '{"en-us": "Gives the slope of the absolute value function, which equals +1 where its input is positive and -1 where it is negative — the sign function. The derivative does not exist at the origin, where the graph has a corner, so the result holds away from zero."}', '["https://en.wikipedia.org/wiki/absolute_value", "https://proofwiki.org/wiki/Derivative_of_Absolute_Value_Function", "https://www.andreaminini.net/math/derivative-of-the-absolute-value", "https://www.analyzemath.com/calculus/Differentiation/absolute_value.html"]'),
  ('derivative_arccos', '{"en-us": "Derivative of arccosine"}', 'derivatives', 7, '{"en-us": "Gives the slope of the inverse cosine function on its principal branch. The slope is always negative because arccosine decreases over its domain, and it is undefined at the endpoints, where the graph becomes vertical. It is the mirror image of the arcsine slope and follows from implicit differentiation of the cosine relation."}', '["https://proofwiki.org/wiki/Derivatives_of_Inverse_Trigonometric_Functions", "https://www.cuemath.com/trigonometry/derivative-of-arccos/", "https://www.themathpage.com/aCalc/inverse-trig.htm", "https://www.maplesoft.com/support/help/maple/view.aspx?path=StudyGuides%2FCalculus%2FChapter2%2FDifferentiation%2FSection2-8%2FDerivInverseTrig"]'),
  ('derivative_arcsin', '{"en-us": "Derivative of arcsine"}', 'derivatives', 7, '{"en-us": "Gives the slope of the inverse sine function on its principal branch, where the graph rises steeply near the endpoints. The slope is always positive and grows without bound as the input approaches -1 or 1; the formula holds for inputs strictly between those limits and follows from implicit differentiation of the sine relation."}', '["https://proofwiki.org/wiki/Derivative_of_Arcsine_Function/Proof", "https://ocw.mit.edu/courses/18-01sc-single-variable-calculus-fall-2010/857933bc947b1ed184c79a5710fc86bc_MIT18_01SCF10_Ses15c.pdf", "https://math.libretexts.org/Courses/Monroe_Community_College/MTH_211_Calculus_II/Calculus_I_Review/Derivatives_of_the_Inverse_Trigonometric_Functions", "https://www.whitman.edu/mathematics/calculus_late_online/section09.05.html"]'),
  ('derivative_arctan', '{"en-us": "Derivative of arctangent"}', 'derivatives', 7, '{"en-us": "Gives the slope of the inverse tangent function, which is always positive and defined for every real input. The graph flattens toward horizontal as the input grows large in magnitude, reflecting the function''s horizontal asymptotes; the result follows from implicit differentiation of the tangent relation."}', '["https://proofwiki.org/wiki/Derivative_of_Arctangent_Function", "https://ocw.mit.edu/courses/18-01sc-single-variable-calculus-fall-2010/37028101f134cc6e0e41572fdc6735d8_MIT18_01SCF10_Ses15b.pdf", "https://www.cuemath.com/calculus/derivative-of-arctan/", "https://www.contemporarycalculus.com/cc/hoffman_calculus_7_4.pdf"]'),
  ('derivative_chain_rule', '{"en-us": "Chain rule"}', 'derivatives', 7, '{"en-us": "Rule for differentiating a composite function by introducing an intermediate variable: rates of change multiply along the chain of dependencies. It applies whenever the inner and outer functions are differentiable at the relevant points and is the workhorse behind implicit differentiation and related-rates problems."}', '["https://en.wikipedia.org/wiki/Chain_rule", "https://math.libretexts.org/Courses/Los_Angeles_City_College/MATH_261%3A_Calculus_I/01%3A_Limits/1.10%3A_Derivatives/1.10.07%3A_The_Chain_Rule", "https://math.hmc.edu/calculus/hmc-mathematics-calculus-online-tutorials/single-variable-calculus/chain-rule/", "https://tutorial.math.lamar.edu/classes/calci/chainrule.aspx", "https://www.mathsisfun.com/calculus/chain-rule.html"]'),
  ('derivative_constant_multiple_rule', '{"en-us": "Derivative constant multiple rule"}', 'derivatives', 5, '{"en-us": "The constant multiple rule states that a multiplicative constant can be factored out of a derivative: differentiating a constant times a function gives the constant times the derivative of the function. It is one of the basic differentiation rules and follows directly from the limit definition of the derivative."}', '["https://openstax.org/books/calculus-volume-1/pages/3-3-differentiation-rules", "https://tutorial.math.lamar.edu/classes/calci/DiffFormulas.aspx", "https://www.khanacademy.org/v/basic-differentiation-rules", "https://www.geeksforgeeks.org/maths/constant-multiple-rule/"]'),
  ('derivative_constant_rule', '{"en-us": "Derivative of a constant"}', 'derivatives', 5, '{"en-us": "The constant rule states that the derivative of a constant function is zero, since a constant function is a horizontal line with no rate of change. It is one of the most basic differentiation rules and follows immediately from the limit definition of the derivative."}', '["https://openstax.org/books/calculus-volume-1/pages/3-3-differentiation-rules", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/03%3A_Derivatives/3.03%3A_Differentiation_Rules", "https://en.wikipedia.org/wiki/Constant_factor_rule_in_differentiation", "https://tutorial.math.lamar.edu/classes/calci/DiffFormulas.aspx"]'),
  ('derivative_cos', '{"en-us": "Derivative of cosine"}', 'derivatives', 6, '{"en-us": "The derivative of the cosine function is the negative of the sine function. This means cosine is a decreasing function wherever its sine counterpart is increasing, and vice versa. The result holds when the angle is measured in radians and can be proved from the limit definition of the derivative."}', '["https://openstax.org/books/calculus-volume-1/pages/3-3-differentiation-rules", "https://www.khanacademy.org/math/ap-calculus-ab/ab-differentiation-1-new/ab-2-7/a/proving-the-derivatives-of-sinx-and-cosx", "https://ecampusontario.pressbooks.pub/scccalculus1/chapter/derivatives-of-trigonometric-functions/", "https://ocw.mit.edu/courses/18-01-single-variable-calculus-fall-2006/resources/lec3/"]'),
  ('derivative_cot', '{"en-us": "Derivative of cotangent"}', 'derivatives', 7, '{"en-us": "The derivative of the cotangent function is the negative square of the cosecant function, equivalently minus one over the squared sine. The result follows from applying the quotient rule to cotangent written as cosine over sine, and is valid wherever sine is nonzero and angles are in radians."}', '["https://math.dartmouth.edu/opencalc2/cole/lecture17.pdf", "https://www.math.stonybrook.edu/Videos/MAT131Online/Handouts/Lecture-14-Handout.pdf", "https://mathworld.wolfram.com/Cotangent.html", "https://openstax.org/books/calculus-volume-1/pages/3-3-differentiation-rules"]'),
  ('derivative_csc', '{"en-us": "Derivative of cosecant"}', 'derivatives', 7, '{"en-us": "The derivative of the cosecant function is the negative product of cosecant and cotangent. It follows from applying the quotient rule to cosecant written as one over sine, and holds wherever sine is nonzero with angles measured in radians."}', '["https://www.analyzemath.com/calculus/derivative/proof-derivative-of-cscx.html", "https://www.cuemath.com/trigonometry/derivative-of-cosec-x/", "https://math.dartmouth.edu/opencalc2/cole/lecture17.pdf", "https://math.dartmouth.edu/~klbooksite/2.09/209.html"]'),
  ('derivative_exp', '{"en-us": "Derivative of exponential"}', 'derivatives', 6, '{"en-us": "The natural exponential function is its own derivative, which is the property that makes it central to calculus and to modeling growth and decay. It follows from the limit definition of the derivative together with the fact that the slope of the curve equals its height at every point."}', '["https://web.ma.utexas.edu/users/m408n/CurrentWeb/LM3-1-4.php", "https://www.khanacademy.org/math/ap-calculus-ab/ab-differentiation-1-new/ab-2-7/a/proof-the-derivative-of-is", "https://ximera.osu.edu/mooculus/calculus1TextbookBySection/rulesOfDifferentiation/rulesOfDifferentiation/digInTheDerivativeOfEToTheX", "https://proofwiki.org/wiki/Exponential_Function_is_Differentiable"]'),
  ('derivative_exp_base', '{"en-us": "Derivative of exponential with base"}', 'derivatives', 7, '{"en-us": "The derivative of an exponential function with an arbitrary positive base equals the function itself scaled by the natural logarithm of the base. It generalizes the special case of the natural exponential and is valid for any base greater than zero and not equal to one."}', '["https://tutorial.math.lamar.edu/classes/calci/DiffExpLogFcns.aspx", "https://brilliant.org/wiki/derivatives-of-exponential-functions/", "https://www.analyzemath.com/calculus/derivative/proof-derivative-of-a%5Ex.html", "https://www.khanacademy.org/math/ap-calculus-ab/ab-differentiation-2-new/ab-3-1b/v/exponential-functions-differentiation-intro"]'),
  ('derivative_ln', '{"en-us": "Derivative of natural logarithm"}', 'derivatives', 6, '{"en-us": "The derivative of the natural logarithm is the reciprocal of its argument, defined for positive arguments. It follows from the fact that the natural logarithm is the inverse of the natural exponential function, and it underlies logarithmic differentiation and many integration results."}', '["https://tutorial.math.lamar.edu/classes/calci/diffexplogfcns.aspx", "https://math.libretexts.org/Courses/Monroe_Community_College/MTH_210_Calculus_I_(Professor_Dean)/Chapter_3%3A_Derivatives/3.9%3A_Derivatives_of_Ln_General_Exponential_and_Log_Functions_and_Logarithmic_Differentiation", "https://proofwiki.org/wiki/Derivative_of_Natural_Logarithm", "https://www.onlinemathlearning.com/derivative-ln.html"]'),
  ('derivative_log_base_a', '{"en-us": "Derivative of Log Base a"}', 'derivatives', 7, '{"en-us": "The derivative of a logarithm with an arbitrary base is the reciprocal of the argument times the natural logarithm of the base. It follows from rewriting the general logarithm in terms of the natural logarithm via the change-of-base formula, and holds for any positive base other than one."}', '["https://tutorial.math.lamar.edu/Classes/CalcI/DiffExpLogFcns.aspx", "https://math.libretexts.org/Courses/Irvine_Valley_College/Math_3AC%3A_Analytic_Geometry_and_Calculus_I/10%3A_Logarithms/10.03%3A_Derivatives_of_Logarithms", "https://proofwiki.org/wiki/Derivative_of_General_Logarithm_Function", "https://brilliant.org/wiki/derivative-of-logarithmic-functions/"]'),
  ('derivative_power_rule', '{"en-us": "Derivative power rule"}', 'derivatives', 6, '{"en-us": "The power rule is the workhorse of differentiation: to differentiate a variable raised to a constant exponent, bring the exponent down as a factor and reduce the exponent by one. It holds for any real exponent, including negative and fractional values, wherever the resulting expression is defined."}', '["https://en.wikipedia.org/wiki/Power_rule", "https://www.whitman.edu/mathematics/calculus_online/section03.01.html", "https://proofwiki.org/wiki/Power_Rule_for_Derivatives", "https://www.mathsisfun.com/calculus/power-rule.html"]'),
  ('derivative_product_rule', '{"en-us": "Product rule"}', 'derivatives', 7, '{"en-us": "The product rule gives the derivative of a product of two differentiable functions as the first function''s derivative times the second plus the first times the second''s derivative. It is essential because, unlike with sums, the derivative of a product is not simply the product of the derivatives."}', '["https://en.wikipedia.org/wiki/Product_rule", "https://tutorial.math.lamar.edu/classes/calci/ProductQuotientRule.aspx", "https://math.hmc.edu/calculus/hmc-mathematics-calculus-online-tutorials/single-variable-calculus/product-rule/", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_by_David_Guichard_(Improved)/03%3A_Rules_for_Finding_Derivatives/3.03%3A_The_Product_Rule"]'),
  ('derivative_quotient_rule', '{"en-us": "Quotient rule"}', 'derivatives', 7, '{"en-us": "The quotient rule gives the derivative of a ratio of two differentiable functions as the derivative of the numerator times the denominator minus the numerator times the derivative of the denominator, all over the square of the denominator. It requires the denominator to be nonzero and is often derived from the product rule."}', '["https://en.wikipedia.org/wiki/Quotient_rule", "https://tutorial.math.lamar.edu/Classes/CalcI/ProductQuotientRule.aspx", "https://math.hmc.edu/calculus/hmc-mathematics-calculus-online-tutorials/single-variable-calculus/quotient-rule/", "https://instruct.math.lsa.umich.edu/tutorial/derivative/quotient.html"]'),
  ('derivative_sec', '{"en-us": "Derivative of secant"}', 'derivatives', 7, '{"en-us": "The derivative of the secant function is the product of secant and tangent. It follows from applying the quotient rule to the reciprocal of cosine, and it is valid wherever cosine is nonzero."}', '["https://proofwiki.org/wiki/Derivative_of_Secant_Function", "https://www.cuemath.com/calculus/derivative-of-sec-x/", "https://www.khanacademy.org/math/ap-calculus-ab/ab-differentiation-1-new/ab-2-10/v/derivatives-of-secx-and-cscx", "https://www.geeksforgeeks.org/maths/derivative-of-sec-x/"]'),
  ('derivative_sin', '{"en-us": "Derivative of sine"}', 'derivatives', 6, '{"en-us": "The derivative of the sine function is the cosine function, proved from the limit definition of the derivative using standard trigonometric limits. The angle must be measured in radians for this result to hold."}', '["https://openstax.org/books/calculus-volume-1/pages/3-5-derivatives-of-trigonometric-functions", "https://math.libretexts.org/Courses/Los_Angeles_City_College/MATH_261%3A_Calculus_I/01%3A_Limits/1.10%3A_Derivatives/1.10.05%3A_Derivatives_of_Trigonometric_Functions", "https://www.khanacademy.org/math/ap-calculus-ab/ab-differentiation-1-new/ab-2-7/a/proving-the-derivatives-of-sinx-and-cosx", "https://proofwiki.org/wiki/Derivative_of_Sine_Function"]'),
  ('derivative_sum_rule', '{"en-us": "Derivative sum rule"}', 'derivatives', 5, '{"en-us": "The sum rule in differentiation states that the derivative of a sum of differentiable functions is the sum of their derivatives. It follows directly from the limit definition of the derivative and the sum law for limits, and extends to sums of any number of terms."}', '["https://en.wikipedia.org/wiki/Sum_rule_in_differentiation", "https://openstax.org/books/calculus-volume-1/pages/3-3-differentiation-rules", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/03%3A_Derivatives/3.03%3A_Differentiation_Rules", "https://tutorial.math.lamar.edu/classes/calci/DiffFormulas.aspx"]'),
  ('derivative_tan', '{"en-us": "Derivative of tangent"}', 'derivatives', 6, '{"en-us": "The derivative of the tangent function is the secant squared, equivalently the reciprocal of cosine squared. It follows from applying the quotient rule to tangent written as sine over cosine, and holds wherever cosine is nonzero."}', '["https://proofwiki.org/wiki/Derivative_of_Tangent_Function", "https://math.libretexts.org/Courses/Laney_College/Math_3A%3A_Calculus_1_(Fall_2022)/03%3A_Derivatives/3.06%3A_Derivatives_of_Trigonometric_Functions", "https://www.mathsisfun.com/calculus/derivatives-trig-proof.html", "https://courseware.cemc.uwaterloo.ca/11/assignments/194/4"]'),
  ('destructive_interference_condition', '{"en-us": "Destructive interference condition"}', 'wave_interference', 7, '{"en-us": "Destructive interference occurs when the path difference between two coherent, in-phase waves is a half-integer multiple of the wavelength, so a crest from one source arrives together with a trough from the other and the waves cancel. It is used to locate dark fringes or nodal lines in double-slit and two-source interference patterns."}', '["https://openstax.org/books/university-physics-volume-3/pages/3-2-mathematics-of-interference", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/03%3A_Interference/3.02%3A_Young''s_Double-Slit_Interference", "https://www.physicsclassroom.com/class/light/lesson-3/the-path-difference", "http://physics.bu.edu/~redner/211-sp06/class19/notes24_int2D.html"]'),
  ('determinant_2x2', '{"en-us": "Determinant of a 2×2 matrix"}', 'linear_algebra', 6, '{"en-us": "The determinant of a two-by-two matrix is a single scalar obtained by subtracting the product of the off-diagonal entries from the product of the diagonal entries. Its sign tells whether the matrix preserves orientation, and it is zero exactly when the matrix is singular (non-invertible)."}', '["https://www.mathsisfun.com/algebra/matrix-determinant.html", "https://www.geeksforgeeks.org/maths/determinant-of-2x2-matrix/", "https://math.libretexts.org/Courses/Ohio_Northern_University/Differential_Equations_and_Linear_Algebra_(Anup_Lamichhane)/04%3A_Matrices_and_Determinants/4.07%3A_Determinants", "https://books.physics.oregonstate.edu/LinAlg/det.html"]'),
  ('diesel_cycle_efficiency', '{"en-us": "Diesel cycle efficiency"}', 'heat_engines', 9, '{"en-us": "This is the air-standard thermal efficiency of the ideal Diesel cycle, the theoretical model for compression-ignition engines with isentropic compression, constant-pressure heat addition, isentropic expansion, and constant-volume heat rejection. It depends on the compression ratio, the cutoff ratio, and the ratio of specific heats; for a fixed compression ratio it is always slightly below the Otto cycle efficiency, though real diesels compensate with much higher compression ratios."}', '["https://kevinjkircher.com/wp-content/uploads/2023/04/diesel-and-dual-cycles.pdf", "https://www.nuclear-power.com/nuclear-engineering/thermodynamics/thermodynamic-cycles/diesel-cycle-diesel-engine/diesel-cycle-problem-with-solution/", "https://mechcodex.com/calculators/thermodynamics/diesel-cycle", "https://novasolver.jp/en/tools/diesel-cycle.html"]'),
  ('difference_of_cubes', '{"en-us": "Difference of cubes"}', 'polynomials', 4, '{"en-us": "A special factoring pattern that rewrites the difference of two perfect cubes as a product of a binomial and a trinomial. It holds for all real numbers and is widely used to simplify and factor cubic expressions; note the quadratic factor is irreducible over the reals."}', '["https://www.mathwarehouse.com/algebra/polynomial/how-to-expand-and-factor-difference-of-cubes.php", "https://www.mathwords.com/p/polynomials_difference_two_cubes.htm", "https://www.purplemath.com/modules/specfact2.htm", "https://www.khanacademy.org/math/algebra-home/alg-polynomials/alg-advanced-polynomial-factorization-methods/v/difference-of-cubes-factoring"]'),
  ('difference_of_squares', '{"en-us": "Difference of squares"}', 'polynomials', 3, '{"en-us": "A fundamental factoring identity stating that the difference of two squares factors into the product of a sum and a difference of the two base terms. It holds in any commutative ring and is used constantly to factor binomials, simplify rational expressions, and perform mental arithmetic."}', '["https://en.wikipedia.org/wiki/Difference_of_squares", "https://www.purplemath.com/modules/specfact.htm", "https://openstax.org/books/algebra-1/pages/6-6-3-factoring-the-difference-of-squares", "https://www.mathwords.com/d/difference_of_squares.htm"]'),
  ('diffraction_grating', '{"en-us": "Diffraction grating equation"}', 'diffraction', 7, '{"en-us": "This condition locates the principal maxima produced when monochromatic light hits a diffraction grating at normal incidence: bright orders appear where the path difference between adjacent slits is a whole number of wavelengths. It is the working equation of grating spectrometers, used to measure wavelengths and analyze spectra, and assumes plane waves and slits much smaller than the distance to the observer."}', '["https://phys.libretexts.org/Courses/University_of_California_Davis/UCD%3A_Physics_9B__Waves_Sound_Optics_Thermodynamics_and_Fluids/03%3A_Physical_Optics/3.03%3A_Diffraction_Gratings", "https://pressbooks.bccampus.ca/collegephysics/chapter/multiple-slit-diffraction/", "https://www.savemyexams.com/a-level/physics/aqa/17/revision-notes/3-waves/3-4-diffraction/3-4-2-the-diffraction-grating/", "https://www.miniphysics.com/diffraction-grating.html"]'),
  ('diffraction_grating_equation', '{"en-us": "Diffraction grating equation"}', 'diffraction', 7, '{"en-us": "The grating equation gives the discrete angles at which light of a given wavelength leaves a diffraction grating as bright principal maxima, arising where the path difference between adjacent slits equals an integer number of wavelengths. It underpins grating spectrometers and wavelength measurement, with normal incidence assumed in this simple form."}', '["https://www.newport.com/n/the-grating-equation", "https://openstax.org/books/college-physics-ap-courses/pages/27-4-multiple-slit-diffraction", "https://vikdhillon.staff.shef.ac.uk/teaching/phy217/instruments/phy217_inst_grating.html", "https://www.savemyexams.com/a-level/physics/cie/25/revision-notes/8-superposition/8-4-the-diffraction-grating/the-diffraction-grating/"]'),
  ('diffraction_grating_resolving_power', '{"en-us": "Resolving power of a diffraction grating"}', 'diffraction', 8, '{"en-us": "The resolving power measures a grating''s ability to separate two closely spaced spectral lines, defined as the average wavelength divided by the smallest resolvable wavelength difference under the Rayleigh criterion. It grows with both the diffraction order and the number of illuminated grooves, and it is a key specification for spectrometer design."}', '["https://www.newport.com/n/resolving-power/", "http://hyperphysics.phy-astr.gsu.edu/hbase/phyopt/gratres.html", "http://www.physicsbootcamp.org/section-dispersion-and-resolving-power-light.html", "https://www.edmundoptics.com/ViewDocument/MKS%20Diffraction%20Grating%20Handbook%20(8th%20edition).pdf"]'),
  ('diffraction_single_slit_intensity', '{"en-us": "Single-slit diffraction intensity pattern"}', 'diffraction', 9, '{"en-us": "Gives how the intensity of monochromatic light varies with angle across the pattern formed by Fraunhofer diffraction at a single narrow slit. The central maximum is by far the brightest, and the intensity falls to zero at the minima where the half phase difference is an integer multiple of pi."}', '["https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/04%3A_Diffraction/4.03%3A_Intensity_in_Single-Slit_Diffraction", "https://www.sciencefacts.net/single-slit-diffraction.html", "https://www.physicsbootcamp.org/section-intensity-in-diffraction-pattern-light"]'),
  ('dilution_equation', '{"en-us": "Dilution Equation"}', 'solution_stoichiometry', 5, '{"en-us": "States that the amount of solute stays constant when a solution is diluted by adding solvent: moles before dilution equal moles after. It is used to find any one of initial concentration, initial volume, final concentration, or final total volume when preparing solutions from a stock."}', '["https://www.aatbio.com/tools/quick-calculator/m1v1-formula-calculator", "https://topblogtenz.com/m1v1-m2v2-dilution-in-chemistry", "https://www.vaia.com/en-us/explanations/chemistry/physical-chemistry/dilution"]'),
  ('dipole_moment_formula', '{"en-us": "Electric dipole moment"}', 'chemical_bonding', 6, '{"en-us": "Measures the polarity of a bond or molecule as the product of the magnitude of the separated charge and the distance between the charge centers, with SI units of coulomb-meters (often expressed in debyes). It is used to predict molecular polarity and how molecules align in electric fields; it applies to two equal and opposite charges separated by a fixed distance."}', '["https://en.wikipedia.org/wiki/Electric_dipole_moment", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_%28Physical_and_Theoretical_Chemistry%29/Physical_Properties_of_Matter/Atomic_and_Molecular_Properties/Dipole_Moments", "https://www.chemistrylearner.com/dipole-moment.html"]'),
  ('discriminant_quadratic', '{"en-us": "Discriminant of a quadratic"}', 'polynomials', 4, '{"en-us": "The expression under the square root in the quadratic formula, which determines the nature of the roots of a quadratic equation without solving it. A positive value gives two distinct real roots, zero gives one repeated real root, and a negative value gives two complex conjugate roots."}', '["https://www.khanacademy.org/math/algebra/x2f8bb11595b61c86:quadratic-functions-equations/x2f8bb11595b61c86:quadratic-formula-a1/a/discriminant-review", "https://www.cuemath.com/algebra/discriminant/", "https://mathsathome.com/the-discriminant-quadratic/"]'),
  ('displacement_average_velocity', '{"en-us": "Displacement from average velocity"}', 'constant_acceleration', 3, '{"en-us": "One of the constant-acceleration kinematics equations: because velocity changes linearly with time under uniform acceleration, its arithmetic mean gives the average velocity over the interval. Multiplying that average by the elapsed time yields the displacement; it is most useful when both endpoint velocities and time are known but acceleration is not."}', '["https://phys.libretexts.org/Courses/Coalinga_College/Physical_Science_for_Educators_Volume_2/02%3A_Motion/2.03%3A_Motion_in_One-Dimension/2.3.07%3A_Displacement_During_Uniform_Acceleration", "https://www.calculatorsoup.com/calculators/physics/displacement_v_t.php", "https://unisium.io/guides/kinematics-4-average-velocity"]'),
  ('displacement_constant_acceleration', '{"en-us": "Displacement at constant acceleration"}', 'constant_acceleration', 4, '{"en-us": "One of the constant-acceleration kinematics (SUVAT) equations, giving the displacement of an object moving in a straight line as the contribution of its initial velocity plus the extra distance gained from uniform acceleration. It applies only when acceleration does not change over the interval."}', '["https://studyrocket.co.uk/revision/a-level-mathematics-b-mei-ocr/mechanics-kinematics/constant-acceleration-formulae", "https://en.neurochispas.com/physics/kinematic-equations-for-constant-acceleration", "https://mathsathome.com/displacement-velocity-acceleration"]'),
  ('displacement_with_final_velocity', '{"en-us": "Displacement using final velocity"}', 'constant_acceleration', 4, '{"en-us": "A rearranged constant-acceleration kinematics (SUVAT) equation that expresses displacement in terms of the final velocity instead of the initial one. It applies to straight-line motion with uniform acceleration and is handy when the ending speed and elapsed time are known but the starting speed is not."}', '["https://mathsathome.com/displacement-velocity-acceleration", "https://en.neurochispas.com/physics/kinematic-equations-for-constant-acceleration", "https://allphysicsfundamentals.com/kinematics-velocity-displacement/"]'),
  ('distance_3d', '{"en-us": "3D distance formula"}', 'coordinate_geometry', 5, '{"en-us": "Gives the straight-line (Euclidean) distance between two points in three-dimensional Cartesian space, obtained by applying the Pythagorean theorem twice along the diagonal of a rectangular box with the points at opposite corners. It is used throughout coordinate geometry, physics, and computer graphics."}', '["https://en.wikipedia.org/wiki/Euclidean_distance", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/12%3A_Vectors_in_Space/12.02%3A_Vectors_in_Three_Dimensions"]'),
  ('distance_formula_2d', '{"en-us": "Distance formula in 2D"}', 'coordinate_geometry', 4, '{"en-us": "Gives the straight-line (Euclidean) distance between two points in the Cartesian plane, derived by applying the Pythagorean theorem to a right triangle whose hypotenuse joins the two points. It is one of the most widely used formulas in coordinate geometry."}', '["https://en.wikipedia.org/wiki/Euclidean_distance", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/12%3A_Vectors_in_Space/12.02%3A_Vectors_in_Three_Dimensions"]'),
  ('distance_point_to_line', '{"en-us": "Distance from a point to a line"}', 'coordinate_geometry', 5, '{"en-us": "Gives the shortest (perpendicular) distance from a fixed point to an infinite line in the plane written as Ax + By + C = 0. The absolute value makes the distance nonnegative regardless of which side of the line the point lies on, and it is used in analytic geometry and in measuring scatter about a fitted line."}', '["https://en.wikipedia.org/wiki/Distance_from_a_point_to_a_line", "https://mathworld.wolfram.com/Point-LineDistance2-Dimensional.html"]'),
  ('doppler_effect_approaching', '{"en-us": "Doppler effect with source approaching"}', 'mechanical_waves', 6, '{"en-us": "Gives the higher pitch heard when a wave source moves directly toward a stationary observer through a medium: wavefronts bunch up ahead of the source, shortening the wavelength and raising the received frequency above the emitted one. It assumes the observer is at rest relative to the medium and that the source speed is less than the wave speed."}', '["https://en.wikipedia.org/wiki/Doppler_effect", "https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/17%3A_Physics_of_Hearing/17.04%3A_Doppler_Effect_and_Sonic_Booms"]'),
  ('doppler_effect_light_longitudinal', '{"en-us": "Longitudinal relativistic Doppler effect"}', 'relativity', 9, '{"en-us": "Gives the frequency of light measured by an observer when the source moves directly away along the line of sight at a relativistic speed, combining the classical wave-front bunching with relativistic time dilation. The result is the redshift used to interpret recession speeds of stars and galaxies; it involves no medium, unlike the sound Doppler effect."}', '["https://en.wikipedia.org/wiki/Relativistic_Doppler_effect", "https://en.wikipedia.org/wiki/Redshift"]'),
  ('doppler_effect_receding', '{"en-us": "Doppler effect with source receding"}', 'mechanical_waves', 6, '{"en-us": "Gives the frequency heard by a stationary observer when a wave source moves directly away from them. Because each wavefront is emitted from farther away, successive crests arrive later and the observed pitch drops below the emitted one; the shift grows with the source speed. Assumes a non-relativistic source moving in a uniform medium, such as sound in air."}', '["https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/17%3A_Sound/17.08%3A_The_Doppler_Effect", "https://en.wikipedia.org/wiki/Doppler_effect", "https://phys.libretexts.org/Courses/University_of_California_Davis/UCD%3A_Physics_7C_-_General_Physics/8%3A_Waves/8.4%3A_Doppler_Effect", "http://labman.phys.utk.edu/phys221core/modules/m12/doppler_effect.html", "https://www.easycalculation.com/formulas/doppler-shift-formula.html"]'),
  ('doppler_effect_sound', '{"en-us": "Doppler effect for sound"}', 'mechanical_waves', 6, '{"en-us": "General form of the Doppler effect for sound, covering a source and an observer both moving along the line joining them. Signs are chosen by direction of motion: motion toward each other raises the observed pitch, motion apart lowers it. It assumes non-relativistic speeds relative to the wave speed in the medium and breaks down as the source speed approaches the speed of sound."}', '["https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_%28OpenStax%29/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_%28OpenStax%29/17%3A_Sound/17.08%3A_The_Doppler_Effect", "https://en.wikipedia.org/wiki/Doppler_effect", "https://phys.libretexts.org/Courses/University_of_California_Davis/UCD%3A_Physics_7C_-_General_Physics/8%3A_Waves/8.4%3A_Doppler_Effect", "http://labman.phys.utk.edu/phys221core/modules/m12/doppler_effect.html", "https://physicsfundamentals.uk/learn/doppler-effect"]'),
  ('dose_equivalent_formula', '{"en-us": "Dose equivalent"}', 'nuclear_physics', 8, '{"en-us": "Dose (equivalent) is a radiation-protection quantity that scales the absorbed dose by a weighting factor accounting for how biologically damaging the radiation type is; photons and electrons have a factor of one while alpha particles have about twenty. It is measured in sieverts (Sv) and is used to compare the stochastic biological risk of different radiation exposures. Strictly, the ICRP applies this weighting when averaging over an organ or tissue."}', '["https://en.wikipedia.org/wiki/Equivalent_dose", "https://www.radiation-dosimetry.org/what-is-equivalent-dose-formula-equation-definition/", "https://www.nuclear-power.com/nuclear-engineering/radiation-protection/equivalent-dose/radiation-weighting-factor/", "https://www.rug.nl/education/courses/other-education/radiation-protection/a-z/a-z-data/radiation-weighting-factor?lang=en"]'),
  ('dot_product_2d', '{"en-us": "Dot product of two 2D vectors"}', 'linear_algebra', 5, '{"en-us": "Computes the scalar (dot) product of two planar vectors from their Cartesian components by multiplying matching coordinates and summing. The result is a single number, equal to the product of the magnitudes and the cosine of the angle between the vectors; it is zero exactly when the vectors are perpendicular. Used to find projections, angles, and work in physics."}', '["https://en.wikipedia.org/wiki/Dot_product", "https://mathinsight.org/dot_product_formula_components", "https://phys.libretexts.org/Courses/Prince_Georges_Community_College/General_Physics_I%3A_Classical_Mechanics/10%3A_The_Dot_Product/10.02%3A_Component_Form", "https://www.cuemath.com/algebra/dot-product/"]'),
  ('dot_product_3d', '{"en-us": "Dot product of two 3D vectors"}', 'linear_algebra', 6, '{"en-us": "Computes the scalar (dot) product of two spatial vectors by multiplying matching Cartesian components and adding the three products. The value equals the product of the vectors'' magnitudes and the cosine of the angle between them, so it vanishes for perpendicular vectors and is maximal for parallel ones. Widely used in physics and engineering to compute work, projections, and angles in space."}', '["https://en.wikipedia.org/wiki/Dot_product", "https://mathinsight.org/dot_product_formula_components", "https://calcworkshop.com/vectors-and-the-geometry-of-space/dot-product-in-3d/", "https://www.storyofmathematics.com/vector-dot-product/"]'),
  ('double_angle_cosine', '{"en-us": "Double-angle formula for cosine"}', 'trigonometric_identities', 5, '{"en-us": "Trigonometric identity that expresses the cosine of twice an angle in terms of the sine and cosine of the angle itself. It follows from the cosine addition formula by taking both angles equal, and it has equivalent forms written using only cosine or only sine via the Pythagorean identity. Used for simplifying expressions, evaluating exact values, and deriving power-reduction and half-angle formulas."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities", "https://www.geeksforgeeks.org/maths/double-angle-formula-for-cosine/", "https://www.cuemath.com/trigonometry/cos-2x/", "https://bhanzu.com/math/formula/double-angle"]'),
  ('double_angle_sine', '{"en-us": "Double-angle formula for sine"}', 'trigonometric_identities', 5, '{"en-us": "Trigonometric identity expressing the sine of twice an angle as twice the product of the sine and cosine of the angle. It is a special case of the sine addition formula with both angles equal, and it also has an equivalent form written purely in terms of the tangent. Used to simplify expressions, evaluate exact trig values, and in physics for relations such as projectile range."}', '["https://math.libretexts.org/Bookshelves/Algebra/Algebra_and_Trigonometry_1e_(OpenStax)/09%3A_Trigonometric_Identities_and_Equations/9.03%3A_Double-Angle_Half-Angle_and_Reduction_Formulas", "https://en.wikipedia.org/wiki/Proofs_of_trigonometric_identities", "https://proofwiki.org/wiki/Double_Angle_Formulas/Sine", "https://www.cuemath.com/trigonometry/sin-double-angle-formula/"]'),
  ('double_slit_bright_fringe_position', '{"en-us": "Double-slit bright fringe position"}', 'interference', 7, '{"en-us": "Gives where the m-th bright interference fringe appears on a screen in Young''s double-slit experiment, measured from the central maximum. It follows from the constructive-interference condition together with the small-angle approximation, so it applies when the screen is far compared with the slit separation. Bright fringes spread farther apart for longer wavelengths, wider screens, and narrower slit spacing."}', '["https://en.wikipedia.org/wiki/Double-slit_experiment", "https://openstax.org/books/university-physics-volume-3/pages/3-2-mathematics-of-interference"]'),
  ('double_slit_fringe', '{"en-us": "Double slit fringe spacing"}', 'interference', 7, '{"en-us": "Gives the distance between adjacent bright (or adjacent dark) fringes in a Young''s double-slit pattern on a screen. Derived from the constructive-interference condition using the small-angle approximation, valid when the screen is much farther from the slits than the slit separation. The spacing grows with wavelength and screen distance and shrinks as the slits are moved apart, which is how the experiment reveals wave behavior of light."}', '["https://en.wikipedia.org/wiki/Double-slit_experiment", "https://openstax.org/books/university-physics-volume-3/pages/3-2-mathematics-of-interference"]'),
  ('double_slit_path_difference', '{"en-us": "Double-slit interference path difference"}', 'interference', 7, '{"en-us": "Gives the extra distance one wave travels compared with the other from the two slits of a double-slit setup to a point seen at angle theta on a distant screen. Comparing this difference to the wavelength determines whether the waves arrive in phase (constructive interference, bright fringe) or out of phase (destructive, dark fringe). It relies on the far-field approximation, where the two rays are essentially parallel."}', '["https://en.wikipedia.org/wiki/Double-slit_experiment", "https://openstax.org/books/university-physics-volume-3/pages/3-2-mathematics-of-interference"]'),
  ('drag_force', '{"en-us": "Drag force on an object in a fluid"}', 'reynolds_number', 7, '{"en-us": "Quadratic drag law giving the resistive force a fluid exerts on a body moving through it at relatively high speed, where pressure (form) drag dominates over viscous drag. The resistance grows with the square of the relative speed and also depends on the fluid density, the reference area of the body, and a dimensionless drag coefficient determined by shape and surface roughness. Used for aircraft, vehicles, and falling objects; at very low Reynolds numbers Stokes'' linear drag applies instead."}', '["https://en.wikipedia.org/wiki/Drag_(physics)", "https://en.wikipedia.org/wiki/Drag_equation", "https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/drag-equation/"]'),
  ('drift_velocity', '{"en-us": "Drift velocity"}', 'current_electricity', 7, '{"en-us": "Gives the slow average velocity that charge carriers (such as free electrons) acquire along a conductor when a current flows, superimposed on their much faster random thermal motion. For a conductor of uniform cross-section, the drift speed depends on the current, the carrier number density, and the cross-sectional area. It explains why electrical signals travel fast even though individual electrons move only fractions of a millimetre per second."}', '["https://en.wikipedia.org/wiki/Drift_velocity", "http://hyperphysics.phy-astr.gsu.edu/hbase/electric/ohmmic.html"]'),
  ('dynamic_pressure_velocity_formula', '{"en-us": "Dynamic pressure from density and velocity"}', 'bernoulli_equation', 6, '{"en-us": "Dynamic pressure is the kinetic energy per unit volume of a flowing fluid, i.e. the pressure associated with the bulk motion of the flow rather than its random thermal motion. It equals the pressure rise that would occur if the flow were brought to rest (stagnation), appears as a term in Bernoulli''s equation, and is widely used in aerodynamics to compute lift, drag, and airspeed."}', '["https://en.wikipedia.org/wiki/Dynamic_pressure", "https://www.grc.nasa.gov/www/BGH/dynpress.html", "https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/dynamic-pressure-2/", "https://www.engineeringtoolbox.com/dynamic-pressure-d_1037.html"]'),
  ('dynamic_viscosity_definition', '{"en-us": "Dynamic viscosity from shear stress"}', 'reynolds_number', 8, '{"en-us": "Dynamic viscosity measures a fluid''s internal resistance to flow: it relates the shear stress between adjacent fluid layers to the rate at which velocity changes across them. This definition applies to Newtonian fluids in laminar flow, where the stress is proportional to the velocity gradient, and it enters calculations of viscous drag, lubrication, and the Reynolds number."}', '["https://en.wikipedia.org/wiki/Viscosity", "https://en.wikipedia.org/wiki/Newton%27s_law_of_viscosity", "https://physics.info/viscosity/", "https://www.grc.nasa.gov/WWW/BGH/viscosity.html", "https://www.engineeringtoolbox.com/dynamic-absolute-kinematic-viscosity-d_412.html"]'),
  ('effective_nuclear_charge', '{"en-us": "Effective nuclear charge (Slater''s rules)"}', 'atomic_structure', 8, '{"en-us": "The effective nuclear charge is the net positive attraction experienced by a particular electron in a multi-electron atom, reduced from the bare nuclear charge by the screening effect of the other electrons. Slater''s rules give an empirical scheme for estimating the shielding constant from the electron configuration, and the result helps explain periodic trends such as atomic radius and ionization energy."}', '["https://en.wikipedia.org/wiki/Slater%27s_rules", "https://chem.libretexts.org/Bookshelves/General_Chemistry/General_Chemistry_Supplement_(Eames)/Periodic_Trends/Slater%27s_Rules_for_Effective_Nuclear_Charge", "https://chem.libretexts.org/Courses/Mount_Royal_University/Chem_1201/Unit_2._Periodic_Properties_of_the_Elements/2.06%3A_Slater%27s_Rules", "https://www.geeksforgeeks.org/chemistry/effective-nuclear-charge/"]'),
  ('effective_spring_constant_series', '{"en-us": "Equivalent spring constant (series)"}', 'springs', 6, '{"en-us": "Springs connected end-to-end in series all carry the same force while their individual extensions add, so the combination behaves like a single spring that is softer than the softest spring in the chain. This relation is used to reduce multi-spring arrangements to one effective stiffness for Hooke''s-law analysis."}', '["https://en.wikipedia.org/wiki/Series_and_parallel_springs", "https://www.engineersedge.com/calculators/series_and_parallel_spring_15648.htm", "https://study.com/skill/learn/how-to-find-the-effective-spring-constant-of-a-set-of-springs-in-series-explanation.html"]'),
  ('efficiency_general', '{"en-us": "General efficiency"}', 'conservation_of_energy', 4, '{"en-us": "Efficiency measures how well a device or process converts input energy into useful output, expressed as a dimensionless ratio between zero and one (often quoted as a percentage). Because real machines inevitably dissipate some energy as heat, sound, or other waste forms, no real device can reach perfect efficiency; the concept is central to comparing engines, motors, and power systems."}', '["https://en.wikipedia.org/wiki/Energy_conversion_efficiency", "https://byjus.com/efficiency-formula/", "https://www.savemyexams.com/as/physics/cie/25/revision-notes/5-work-energy-and-power/5-1-energy-conservation/efficiency/", "https://www.schoolphysics.co.uk/age16-19/Mechanics/Dynamics/text/Efficiency_/index.html"]'),
  ('eigenvalue_definition', '{"en-us": "Eigenvalue equation"}', 'linear_algebra', 9, '{"en-us": "The defining relation of the eigenvalue problem: an eigenvector of a square matrix is a nonzero vector whose direction is unchanged when the matrix is applied to it, being merely stretched or shrunk by a scalar factor called the eigenvalue. Finding these pairs underlies matrix diagonalization and applications from vibration analysis and stability theory to quantum mechanics."}', '["https://en.wikipedia.org/wiki/Eigenvalues_and_eigenvectors", "https://math.libretexts.org/Courses/Mission_College/MAT_04C_Linear_Algebra_(Kravets)/06%3A_Eigenvalues_and_Eigenvectors/6.01%3A_Eigenvalues_and_Eigenvectors", "https://textbooks.math.gatech.edu/ila/eigenvectors.html", "https://mathworld.wolfram.com/Eigenvalue.html"]'),
  ('elastic_collision_final_velocity_1', '{"en-us": "Elastic collision final velocity 1 (1D)"}', 'collisions', 7, '{"en-us": "Gives the post-collision velocity of the first object in a head-on, perfectly elastic one-dimensional collision between two bodies, in terms of both initial velocities and the two masses. It follows from solving conservation of momentum together with conservation of kinetic energy, and it correctly reproduces limiting cases such as equal-mass objects exchanging velocities."}', '["https://openstax.org/books/college-physics-ap-courses-2e/pages/8-4-elastic-collisions-in-one-dimension", "https://jwu.pressbooks.pub/collegephysics/chapter/elastic-collisions-in-one-dimension/", "https://calculover.com/science/mechanics/elastic-collision/", "https://calculator.academy/elastic-collision-calculator-2/"]'),
  ('elastic_collision_final_velocity_2', '{"en-us": "Elastic collision final velocity 2 (1D)"}', 'collisions', 7, '{"en-us": "Gives the post-collision velocity of the second object in a head-on, perfectly elastic one-dimensional collision between two bodies, in terms of both initial velocities and the two masses. It is obtained by solving conservation of momentum and conservation of kinetic energy simultaneously, and is symmetric to the corresponding expression for object one under exchange of labels 1 and 2."}', '["https://openstax.org/books/college-physics-ap-courses-2e/pages/8-4-elastic-collisions-in-one-dimension", "https://jwu.pressbooks.pub/collegephysics/chapter/elastic-collisions-in-one-dimension/", "https://calculover.com/science/mechanics/elastic-collision/", "https://calculator.academy/elastic-collision-calculator-2/"]'),
  ('elastic_potential_energy', '{"en-us": "Elastic potential energy"}', 'springs', 5, '{"en-us": "Elastic potential energy is the energy stored in a deformed elastic object such as a stretched or compressed spring. It equals the work done to produce the deformation and is fully recoverable when the object returns to its undeformed shape, provided the deformation stays within the linear (Hooke''s law) regime. It is used in energy conservation problems involving springs, strings, and other elastic elements."}', '["https://en.wikipedia.org/wiki/Elastic_potential_energy", "https://openstax.org/books/college-physics-2e/pages/7-4-conservative-forces-and-potential-energy", "https://phys.libretexts.org/Bookshelves/Conceptual_Physics/Introduction_to_Physics_(Park)/03%3A_Unit_2-_Mechanics_II_-_Energy_and_Momentum_Oscillations_and_Waves_Rotation_and_Fluids/03%3A_Work_and_Energy/3.06%3A_Spring_Potential_Energy", "http://hyperphysics.gsu.edu/hbase/pespr.html"]'),
  ('electric_current', '{"en-us": "Electric current definition"}', 'current_electricity', 4, '{"en-us": "Electric current is the net rate at which electric charge flows through a cross-section of a conductor, such as the rate at which charge passes a point in a circuit. Its SI unit is the ampere, corresponding to one coulomb of charge passing per second, and it is measured with an ammeter. This defining relation applies to steady flow; for time-varying flow the instantaneous current is the corresponding derivative."}', '["https://en.wikipedia.org/wiki/Electric_current", "https://openstax.org/books/university-physics-volume-2/pages/9-1-electrical-current", "https://www.physicsclassroom.com/tutorial/Electric-Circuits/electric-current/electric-current", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/09%3A_Current_and_Resistance/9.02%3A_Electrical_Current"]'),
  ('electric_dipole_torque_uniform_field', '{"en-us": "Torque on an electric dipole in a uniform field"}', 'electrostatics', 8, '{"en-us": "In a uniform electric field, an electric dipole feels equal and opposite forces on its two charges, giving no net force but a couple that twists the dipole toward alignment with the field. The turning effect grows with charge, separation, and field strength, and depends on orientation: it vanishes when the dipole is aligned with the field and is maximal when the dipole is perpendicular to it. In non-uniform fields the dipole also experiences a net translational force."}', '["https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/05%3A_Electric_Charges_and_Fields/5.08%3A_Electric_Dipoles", "https://phys.libretexts.org/Courses/Berea_College/Introductory_Physics%3A_Berea_College/16%3A_Electric_Charges_and_Fields/16.04%3A_The_Electric_Dipole", "https://www.physicsbootcamp.org/Torque-on-an-Electric-Dipole.html", "https://www.careers360.com/physics/torque-on-an-electric-dipole-in-a-uniform-electric-field-topic-pge"]'),
  ('electric_field_charged_ring', '{"en-us": "Electric field on the axis of a charged ring"}', 'electric_fields', 8, '{"en-us": "Gives the electric field at a point on the symmetry axis of a thin ring carrying charge uniformly distributed around it, found by integrating the contributions of all charge elements; transverse components cancel by symmetry, leaving only the axial component. The field is zero at the ring''s center and reduces to that of a point charge far from the ring; off the axis the distribution requires a more general treatment."}', '["https://phys.libretexts.org/Bookshelves/Electricity_and_Magnetism/Electricity_and_Magnetism_(Tatum)/01%3A_Electric_Fields/1.06%3A_Electric_Field_E/1.6D%3A_Field_on_the_Axis_of_and_in_the_Plane_of_a_Charged_Ring", "https://web.pa.msu.edu/people/duxbury/courses/phy294H/lectures/lecture10/lecture10.html", "https://books.physics.oregonstate.edu/GSF/ering1act.html", "https://www.tutorchase.com/answers/a-level/physics/how-do-you-calculate-the-electric-field-due-to-a-ring-of-charge"]'),
  ('electric_field_charged_sphere_inside', '{"en-us": "Electric field inside a uniformly charged sphere"}', 'electrostatics', 8, '{"en-us": "Gives the electric field at a point inside a non-conducting sphere carrying charge uniformly throughout its volume. Derived from Gauss''s law, the field grows linearly with distance from the centre, is zero at the centre, and matches the exterior point-charge field at the surface."}', '["http://hyperphysics.phy-astr.gsu.edu/hbase/electric/elesph.html", "https://www.miniphysics.com/uy1-electric-field-of-a-uniformly-charged-sphere.html", "https://photonics101.com/fs-charge-configurations/homogeneously-charged-sphere.html", "https://0space.org/c/6022-ympem-02009-electric-field-uniformly-charged-sphere"]'),
  ('electric_field_definition', '{"en-us": "Electric field definition"}', 'electric_fields', 6, '{"en-us": "Defines the electric field strength at a point as the electrostatic force per unit charge experienced by a small positive test charge placed there. It is a vector quantity pointing along the force on a positive charge, measured in newtons per coulomb (or volts per meter), and assumes the test charge is small enough not to disturb the source charges."}', '["https://en.wikipedia.org/wiki/Electric_field", "https://openstax.org/books/physics/pages/18-3-electric-field", "https://www.physicsclassroom.com/tutorial/Static-Electricity/electric-fields/electric-field-intensity", "https://www.britannica.com/science/electric-field"]'),
  ('electric_field_dipole_on_axis', '{"en-us": "Electric field on the axis of a dipole"}', 'electric_fields', 8, '{"en-us": "Gives the electric field at a point on the axis of an electric dipole, far from the dipole''s centre. In this far-field limit the field falls off as the cube of the distance and points along the dipole moment; it is twice as strong as the equatorial field at the same distance."}', '["https://byjus.com/physics/electric-field-intensity-at-any-point-due-to-an-ideal-dipole/", "https://physicsbook.gatech.edu/Electric_Dipole", "https://www.khanacademy.org/science/in-in-class-12th-physics-india/in-in-electric-charges-and-field/x51bd77206da864f3:electric-dipoles/v/electric-field-due-to-dipole-on-the-axis-electric-charges-fields-physics-khan-academy", "https://phys.libretexts.org/Bookshelves/Electricity_and_Magnetism/Essential_Graduate_Physics_-_Classical_Electrodynamics_(Likharev)/03%3A_Dipoles_and_Dielectrics/3.01%3A_Electric_Dipole"]'),
  ('electric_field_dipole_perpendicular_axis', '{"en-us": "Electric field perpendicular to dipole axis"}', 'electric_fields', 8, '{"en-us": "Gives the electric field at a point on the equatorial line (perpendicular bisector) of an electric dipole, in the far-field limit where the point is much farther from the dipole than the charge separation. The field falls off as the cube of the distance, is half the axial field at the same distance, and points opposite to the dipole moment."}', '["https://jeenotes.in/physics/electrostatics/electric-dipole/", "https://physicsderivations.com/electric-field-due-to-a-dipole/", "https://www.ucale.org/field-intensity-on-equatorial-line-of-a-dipole/", "https://physicsbook.gatech.edu/Electric_Dipole"]'),
  ('electric_field_infinite_line_charge', '{"en-us": "Electric field of an infinite line charge"}', 'electric_fields', 8, '{"en-us": "Gives the electric field magnitude at a perpendicular distance from an infinitely long straight wire carrying uniform linear charge density, directed radially away from (or toward) the wire. Obtained from Gauss''s law with a cylindrical surface; it also approximates a very long finite wire when the distance is small compared with its length."}', '["http://physics.bu.edu/~duffy/semester2/c03_infline.html", "https://phys.libretexts.org/Courses/Berea_College/Electromagnetics_I_(Messina)/05%3A_Electrostatics/5.06%3A_Electric_Field_Due_to_an_Infinite_Line_Charge_using_Gauss_Law", "https://www.vedantu.com/jee-main/physics-electric-field-due-to-infinite-linear-charge-and-cylinders", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/05%3A_Electric_Charges_and_Fields/5.06%3A_Calculating_Electric_Fields_of_Charge_Distributions"]'),
  ('electric_field_infinite_plane', '{"en-us": "Electric field of an infinite plane"}', 'electric_fields', 8, '{"en-us": "Gives the electric field of a thin, infinitely extended sheet carrying uniform surface charge density, directed perpendicular to the sheet and away from it if positively charged. A key result of Gauss''s law is that this field is uniform, with a magnitude independent of the distance from the sheet; it also underlies the parallel-plate capacitor field."}', '["https://phys.libretexts.org/Bookshelves/Electricity_and_Magnetism/Electricity_and_Magnetism_(Tatum)/01%3A_Electric_Fields/1.06%3A_Electric_Field_E/1.6F%3A_Field_of_a_Uniformly_Charged_Infinite_Plane_Sheet", "https://farside.ph.utexas.edu/teaching/316/lectures/node27.html", "http://hyperphysics.phy-astr.gsu.edu/hbase/electric/elesht.html", "https://byjus.com/physics/electric-field-intensity-due-to-a-thin-uniformly-charged-infinite-plane-sheet/"]'),
  ('electric_field_parallel_plate_uniform', '{"en-us": "Electric field between parallel plates"}', 'electrostatics', 6, '{"en-us": "Relates the uniform electric field in the central region between two large, oppositely charged parallel conducting plates to the potential difference across them and their separation. The field is constant and points from the positive plate to the negative plate, valid away from the edge (fringing) regions."}', '["https://openstax.org/books/college-physics-ap-courses-2e/pages/19-2-electric-potential-in-a-uniform-electric-field", "https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/19%3A_Electric_Potential_and_Electric_Field/19.02%3A_Electric_Potential_in_a_Uniform_Electric_Field", "https://openbooks.lib.msu.edu/collegephysics2/chapter/electric-potential-in-a-uniform-electric-field-2/", "https://www.savemyexams.com/a-level/physics/aqa/17/revision-notes/7-fields-and-their-consequences/7-4-electric-fields/7-4-4-uniform-electric-field/"]'),
  ('electric_field_point_charge', '{"en-us": "Electric field of a point charge"}', 'electric_fields', 6, '{"en-us": "Gives the magnitude of the electric field produced by a point charge at a distance from it, directed radially away from a positive charge or toward a negative charge. It follows directly from Coulomb''s law divided by the test charge, falls off with the square of the distance, and is the building block for fields of more complex charge distributions via superposition."}', '["https://openstax.org/books/physics/pages/18-3-electric-field", "https://www.hyperphysics.phy-astr.gsu.edu/hbase/electric/elefie.html", "https://www.physicsbook.gatech.edu/Point_Charge", "https://www.miniphysics.com/uy1-electric-field-of-a-point-charge.html"]'),
  ('electric_force_field', '{"en-us": "Electric force on a charge in a field"}', 'electric_fields', 6, '{"en-us": "Gives the electrostatic force experienced by a charge placed at a point where the electric field is known. The force is parallel to the field for a positive charge and antiparallel for a negative one; this relation is the practical way to predict the motion of charged particles in fields."}', '["https://openstax.org/books/college-physics/pages/18-4-electric-field-concept-of-a-field-revisited", "https://phys.libretexts.org/Courses/Kettering_University/Electricity_and_Magnetism_with_Applications_to_Amateur_Radio_and_Wireless_Technology/02%3A_The_Electric_Field/2.04%3A_Electric_Fields_and_Forces", "https://www.vedantu.com/jee-main/physics-motion-of-a-charge-particle-in-an-electric-field"]'),
  ('electric_potential_charged_ring_axis', '{"en-us": "Electric potential on axis of a charged ring"}', 'electric_potential', 8, '{"en-us": "Gives the electric potential at a point on the symmetry axis of a thin ring carrying charge uniformly distributed around its circumference. Because every charge element is the same distance from an axial point, all contributions add equally; the potential is taken as zero at infinity and reduces to the point-charge value far from the ring."}', '["https://books.physics.oregonstate.edu/GSF/ring.html", "https://phys.libretexts.org/Courses/Kettering_University/Electricity_and_Magnetism_with_Applications_to_Amateur_Radio_and_Wireless_Technology/03%3A_The_Electric_Potential/3.07%3A_Common_Models_of_Electric_Potential", "https://www.vedantu.com/jee-main/physics-electric-field-due-to-a-uniformly-charged-ring", "https://www.shaalaa.com/question-bank-solutions/consider-circular-ring-radius-r-uniformly-charged-linear-charge-density-find-electric-potential-point-axis-distance-x-centre-ring_68913"]'),
  ('electric_potential_dipole', '{"en-us": "Electric potential of a dipole"}', 'electric_potential', 8, '{"en-us": "Gives the electric potential at a point far from an electric dipole, in terms of the dipole moment and the angle between the observation direction and the dipole axis. Valid in the far-field limit where the distance greatly exceeds the charge separation; the potential falls off as the square of the distance, faster than for a single point charge, and vanishes everywhere on the equatorial plane."}', '["https://www2.ph.ed.ac.uk/~mevans/em/lec5.pdf", "https://web2.ph.utexas.edu/~vadim/Classes/2017f/dipole.pdf", "https://www.concepts-of-physics.com/electromagnetism/electric-dipole.php", "https://www.aakash.ac.in/important-concepts/physics/potential-due-to-an-electric-dipole"]'),
  ('electric_potential_energy', '{"en-us": "Electric potential energy of two point charges"}', 'electrostatics', 7, '{"en-us": "Gives the potential energy stored in a pair of point charges as a function of their separation, with zero taken at infinite separation. The sign follows the product of the charges: positive (repulsive) for like charges and negative (attractive) for opposite charges; summing over pairs extends it to systems of many charges."}', '["https://en.wikipedia.org/wiki/Electric_potential_energy", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/07%3A_Electric_Potential/7.02%3A_Electric_Potential_Energy", "https://www.physicsbook.gatech.edu/Electric_Potential_Energy", "https://www.concepts-of-physics.com/electromagnetism/electric-potential-energy-of-system-of-point-charges.php"]'),
  ('electric_potential_multiple_charges', '{"en-us": "Electric potential from multiple point charges"}', 'electric_potential', 7, '{"en-us": "The total electric potential at a point produced by a collection of point charges is the algebraic (scalar) sum of the contributions of the individual charges, by the superposition principle. Because potential is a scalar, no vector components are needed; each contribution carries the sign of its source charge."}', '["https://hyperphysics.gsu.edu/hbase/electric/mulpoi.html", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/07%3A_Electric_Potential/7.04%3A_Calculations_of_Electric_Potential", "https://www.usna.edu/Users/physics/helton/documents/SP212_Lecture_Slides/SP212_Lecture_Slides_Lesson_11.pdf"]'),
  ('electric_potential_point_charge', '{"en-us": "Electric potential of a point charge"}', 'electric_potential', 6, '{"en-us": "Valid for a point charge, or outside a spherically symmetric charge distribution."}', '["https://openstax.org/books/college-physics/pages/19-3-electrical-potential-due-to-a-point-charge", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/07%3A_Electric_Potential/7.04%3A_Calculations_of_Electric_Potential", "https://hyperphysics.gsu.edu/hbase/electric/potpoi.html"]'),
  ('electric_potential_uniform_field', '{"en-us": "Electric potential in uniform field"}', 'electric_potential', 6, '{"en-us": "In a uniform electric field, such as that between parallel conducting plates, the potential difference between two points equals the field strength times the displacement measured along the field. Because the potential decreases in the direction the field points, a minus sign appears when the displacement is taken along the field direction."}', '["https://courses.lumenlearning.com/suny-physics/chapter/19-2-electric-potential-in-a-uniform-electric-field/", "https://pressbooks.online.ucf.edu/phy2054jr/chapter/electric-potential-in-a-uniform-electric-field/", "https://openstax.org/books/university-physics-volume-2/pages/7-4-determining-field-from-potential"]'),
  ('electrical_conductivity_formula', '{"en-us": "Electrical conductivity from resistivity"}', 'current_electricity', 6, '{"en-us": "Electrical conductivity measures how well a material conducts electric current and is defined as the reciprocal of its resistivity. It is an intrinsic material property, measured in siemens per meter, commonly denoted by sigma; good conductors such as copper have high conductivity, while insulators have very low conductivity."}', '["https://en.wikipedia.org/wiki/Electrical_resistivity_and_conductivity", "https://phys.libretexts.org/Courses/Georgia_State_University/GSU-TM-Introductory_Physics_II_(1112)/05%3A_Electric_Current_Resistance_and_Ohm%27s_Law/5.06%3A_Resistivity_and_Resistance", "https://www.electronics-notes.com/articles/basic_concepts/resistance/electrical-conductivity-conductance.php", "https://spark.iop.org/conductivity-electrical"]'),
  ('electrical_energy_power_time', '{"en-us": "Electrical energy from power and time"}', 'circuits', 4, '{"en-us": "The electrical energy consumed or supplied by a device equals its power consumption multiplied by the time it operates, valid for constant power. This relation underlies the kilowatt-hour used on electricity bills, since utilities charge for energy rather than power."}', '["https://openstax.org/books/university-physics-volume-2/pages/9-5-electrical-energy-and-power", "https://courses.lumenlearning.com/suny-physics/chapter/20-4-electric-power-and-energy/", "https://phys.libretexts.org/Courses/Coalinga_College/Physical_Science_for_Educators_Volume_2/04%3A_Electricity/4.05%3A_Electric_Circuits/4.5.01%3A_Energy_Transfer_in_Electric_Circuits"]'),
  ('electrical_power', '{"en-us": "Electrical power"}', 'circuits', 4, '{"en-us": "Electric power is the rate at which a circuit element converts electrical energy, measured in watts. It equals the product of the current through the element and the voltage drop across it, and applies to sources as well as dissipative devices such as resistors."}', '["https://openstax.org/books/physics/pages/19-4-electric-power", "https://en.wikipedia.org/wiki/Electrical_Power", "https://phys.libretexts.org/Courses/Joliet_Junior_College/JJC_-_PHYS_110/College_Physics_for_Health_Professions/20%3A_Electric_Current_Resistance_and_Ohm%27s_Law/20.05%3A_20.4_Electric_Power_and_Energy"]'),
  ('electrical_power_current_resistance', '{"en-us": "Electrical power from current and resistance"}', 'power', 5, '{"en-us": "The rate at which a resistor converts electrical energy into heat, known as Joule heating, depends on the square of the current through it and on its resistance. This form of Joule''s first law applies to ohmic resistive elements and is useful when current rather than voltage is known."}', '["https://en.wikipedia.org/wiki/Joule_heating", "https://openstax.org/books/university-physics-volume-2/pages/9-5-electrical-energy-and-power", "https://brilliant.org/wiki/heat-dissipated-by-resistors/", "https://phys.libretexts.org/Courses/Coalinga_College/Physical_Science_for_Educators_Volume_2/04%3A_Electricity/4.04%3A_Electric_Current_and_Resistance/4.4.05%3A_Electric_Power_and_Energy"]'),
  ('electrolysis_current_time_mass', '{"en-us": "Mass deposited in electrolysis"}', 'electrochemistry', 8, '{"en-us": "Faraday''s first law of electrolysis: the mass of a substance deposited or liberated at an electrode is proportional to the electric charge passed through the electrolyte. With constant current, charge is current times time, and the result also depends on the molar mass of the substance and on how many electrons its ions exchange in the electrode reaction."}', '["https://goldbook.iupac.org/terms/view/09075", "https://en.wikipedia.org/wiki/Faraday%27s_laws_of_electrolysis", "http://www.chem.latech.edu/~ramu/chem311/lec_notes/pchem_notes_7.pdf"]'),
  ('electrolysis_mass', '{"en-us": "Mass deposited in electrolysis"}', 'electrochemistry', 8, '{"en-us": "Faraday''s laws of electrolysis combined into one working relation: the mass of a substance transformed at an electrode is proportional to the electric charge passed through the cell and to the substance''s molar mass divided by the number of electrons exchanged per ion. It is used for electroplating calculations, coulometry, and battery capacity estimates."}', '["https://goldbook.iupac.org/terms/view/09075", "https://en.wikipedia.org/wiki/Faraday%27s_laws_of_electrolysis", "https://www.monash.edu/student-academic-success/chemistry/primary-galvanic-cells-and-fuel-cells-as-sources-of-energy/faradays-laws"]'),
  ('electromagnetic_induction_flux_linkage', '{"en-us": "Magnetic flux linkage"}', 'electromagnetic_induction', 7, '{"en-us": "Flux linkage is the total magnetic flux linked with a coil of N turns, assuming the same flux passes through every turn. Since each turn contributes its own flux, the linkage grows in proportion to the number of turns; it is this quantity whose rate of change determines the induced EMF in a coil under Faraday''s law."}', '["https://en.wikipedia.org/wiki/Flux_linkage", "https://www.savemyexams.com/a-level/physics/aqa/17/revision-notes/7-fields-and-their-consequences/7-9-electromagnetic-induction/7-9-2-magnetic-flux-linkage/", "https://www.albert.io/blog/ap-physics-c-em-magnetic-flux/"]'),
  ('electromagnetic_wave_impedance_vacuum', '{"en-us": "Impedance of free space"}', 'electromagnetic_waves', 8, '{"en-us": "The impedance of free space, also called the wave impedance of a vacuum, is the constant ratio of the electric field strength to the magnetic field strength for a plane electromagnetic wave traveling through vacuum, equal to about 376.7 ohms. It follows from Maxwell''s equations and is often approximated in engineering as 120 pi ohms."}', '["https://en.wikipedia.org/wiki/Impedance_of_free_space", "https://en.wikipedia.org/wiki/Intrinsic_impedance", "https://proofwiki.org/wiki/Definition:Impedance_of_Free_Space"]'),
  ('electromagnetic_wave_poynting_vector', '{"en-us": "Poynting vector magnitude"}', 'electromagnetic_waves', 9, '{"en-us": "The Poynting vector gives the directional energy flux of an electromagnetic field, that is, the power transported per unit area, measured in watts per square meter. Its magnitude equals the product of the electric and magnetic field magnitudes divided by the vacuum permeability, valid when the fields are perpendicular as in a plane wave; its direction is the direction of energy flow."}', '["https://en.wikipedia.org/wiki/Poynting_vector", "https://openstax.org/books/university-physics-volume-2/pages/16-3-energy-carried-by-electromagnetic-waves", "https://www.britannica.com/science/Poynting-vector"]'),
  ('electron_capacity_subshell', '{"en-us": "Electron capacity of a subshell"}', 'periodic_table', 5, '{"en-us": "Gives the maximum number of electrons that can occupy an atomic subshell with azimuthal quantum number l. Each of the 2l+1 orbitals in the subshell holds at most two electrons of opposite spin (Pauli exclusion principle), so s subshells hold 2 electrons, p hold 6, d hold 10, and f hold 14. It underpins electron configurations and the structure of the periodic table."}', '["https://en.wikipedia.org/wiki/Electron_shell", "https://en.wikipedia.org/wiki/Azimuthal_quantum_number", "https://www.vedantu.com/physics/azimuthal-quantum-number"]'),
  ('electronegativity_difference', '{"en-us": "Electronegativity difference"}', 'chemical_bonding', 5, '{"en-us": "The difference in electronegativity between two bonded atoms gauges how unevenly the bonding electrons are shared and helps classify the bond. A near-zero difference indicates a nonpolar covalent bond, an intermediate value a polar covalent bond, and a large difference (roughly above 1.8-2.0 on the Pauling scale) an ionic bond. It is a rule of thumb, not an exact criterion."}', '["https://chem-textbook.ucalgary.ca/version2/chapter-7a-main/ionic-and-covalent-bonding/electronegativity-and-bond-type/", "https://chem.libretexts.org/Courses/Stanford_Online_High_School/ChemTEN_S1/02%3A_COVALENCE/2.02%3A_STRUCTURE/2.2.04%3A_Electronegativity_and_Bond_Polarity", "https://www.omnicalculator.com/chemistry/electronegativity", "https://www.chemteam.info/Bonding/Electroneg-Bond-Polarity.html"]'),
  ('ellipse_eccentricity', '{"en-us": "Eccentricity of an ellipse"}', 'coordinate_geometry', 6, '{"en-us": "The eccentricity measures how strongly an ellipse deviates from a circle, computed from its semi-major axis a and semi-minor axis b. It is a dimensionless number between 0 and 1: a circle has eccentricity 0, while values approaching 1 indicate a long, thin ellipse. It is widely used in conic-section geometry and in orbital mechanics to characterize planetary and satellite orbits."}', '["https://en.wikipedia.org/wiki/Eccentricity_(mathematics)", "https://www.cuemath.com/geometry/eccentricity-of-ellipse", "https://www.geeksforgeeks.org/maths/eccentricity-of-ellipse/", "https://resources.wolframcloud.com/FormulaRepository/resources/Eccentricity-of-an-Ellipse"]'),
  ('ellipse_latus_rectum', '{"en-us": "Latus rectum of an ellipse"}', 'coordinate_geometry', 7, '{"en-us": "The latus rectum of an ellipse is the chord that passes through a focus perpendicular to the major axis, and an ellipse has two such chords of equal length. Its length depends only on the semi-major axis a and semi-minor axis b, and it measures the width of the ellipse at the focus. This quantity appears in conic-section geometry and in the analysis of elliptical orbits."}', '["https://www.cuemath.com/geometry/latus-rectum-of-ellipse", "https://mathmonks.com/latus-rectum", "https://www.mathwords.com/l/latus_rectum.htm", "https://allen.in/jee/maths/ellipse"]'),
  ('ellipse_standard_form', '{"en-us": "Standard equation of an ellipse"}', 'coordinate_geometry', 5, '{"en-us": "This is the standard form of the equation of an ellipse centered at the origin with its major axis along a coordinate axis, where a and b are the semi-major and semi-minor axes. Every point (x, y) satisfying it lies on the ellipse, whose foci satisfy the focal relationship with these axes. For a center at (h, k), x and y are simply replaced by the translated coordinates."}', '["https://en.wikipedia.org/wiki/Semi-major_and_semi-minor_axes", "https://www.cuemath.com/geometry/ellipse/", "https://courses.lumenlearning.com/waymakercollegealgebra/chapter/equations-of-ellipses/", "https://mathmonks.com/ellipse"]'),
  ('em_wave_frequency_wavelength', '{"en-us": "EM wave frequency from wavelength"}', 'electromagnetic_waves', 5, '{"en-us": "Relates the oscillation frequency of an electromagnetic wave to its wavelength through the speed of light, which is the same for all such waves in vacuum. Frequency and wavelength are inversely proportional: short wavelengths correspond to high frequencies, as across the spectrum from radio waves to gamma rays. In a material medium the speed of light is replaced by the slower phase velocity in the medium."}', '["https://www.pw.live/school-prep/exams/wavelength-to-frequency-formula", "https://scienceinsights.org/how-to-calculate-wavelength-formulas-examples/", "https://www.physicsoftheuniverse.com/calculator/frequency_wavelength.html", "https://sengpielaudio.com/calculator-wavelength.htm"]'),
  ('enantiomeric_excess', '{"en-us": "Enantiomeric excess"}', 'organic_chemistry', 8, '{"en-us": "Enantiomeric excess quantifies the optical purity of a chiral mixture by expressing how much one enantiomer outweighs its mirror image, as a percentage of the total. It runs from zero for a racemic mixture to one hundred percent for a pure enantiomer. The quantities used may be moles, concentrations, percentages, or chromatographic peak areas, provided both are in the same units."}', '["https://www.pearson.com/channels/calculators/enantiomeric-excess-calculator", "https://www.chemistrysteps.com/enantiomeric-excess-ee", "https://calculatorlib.com/enantiomeric-excess-calculator", "https://joteo.net/chemistry-calculators/enantiomeric-excess-ee-calculator/"]'),
  ('energy_conservation_nonconservative', '{"en-us": "Energy conservation with nonconservative work"}', 'conservation_of_energy', 6, '{"en-us": "Extends mechanical energy conservation to systems where friction, drag, or other nonconservative forces act. The work done by such forces accounts exactly for the change in the system''s total mechanical energy: positive work adds energy (for example a person pushing a crate), while negative work removes it (as friction does). It is used to solve motion problems without applying Newton''s laws force by force."}', '["https://openstax.org/books/college-physics-2e/pages/7-5-nonconservative-forces", "https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax)/07%3A_Work_Energy_and_Energy_Resources/7.05%3A_Nonconservative_Forces", "https://courses.lumenlearning.com/suny-physics/chapter/7-5-nonconservative-forces/", "https://theory.uwinnipeg.ca/physics/work/node10.html"]'),
  ('energy_density_electromagnetic_wave', '{"en-us": "Energy density of an electromagnetic wave"}', 'electromagnetic_waves', 8, '{"en-us": "Gives the energy stored per unit volume in the fields of a plane electromagnetic wave traveling through vacuum. Because the electric and magnetic contributions are exactly equal at every instant, the total density can be written using the electric field alone together with the vacuum permittivity. It underlies calculations of wave intensity and of the Poynting vector, and it scales with the square of the field amplitude."}', '["https://openstax.org/books/university-physics-volume-2/pages/16-3-energy-carried-by-electromagnetic-waves", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_%28OpenStax%29/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_%28OpenStax%29/16%3A_Electromagnetic_Waves/16.04%3A_Energy_Carried_by_Electromagnetic_Waves", "https://pressbooks.online.ucf.edu/osuniversityphysics2/chapter/energy-carried-by-electromagnetic-waves/", "https://resources.system-analysis.cadence.com/blog/msa2021-the-energy-density-of-electromagnetic-waves"]'),
  ('energy_in_inductor', '{"en-us": "Energy stored in an inductor"}', 'electromagnetic_induction', 7, '{"en-us": "An inductor carrying a current stores energy in the magnetic field it produces, and this energy can be recovered when the current falls. The stored energy grows with the square of the current, so doubling the current quadruples it, assuming constant inductance. This relation is used in RL and LC circuit analysis and in power-electronics designs such as switching converters."}', '["https://www.engineeringtoolbox.com/inductors-energy-stored-d_1391.html", "http://www.hyperphysics.phy-astr.gsu.edu/hbase/electric/indeng.html", "https://www.omnicalculator.com/physics/inductor-energy", "https://www.miniphysics.com/energy-in-inductor.html"]'),
  ('enthalpy_change_definition', '{"en-us": "Enthalpy change at constant pressure"}', 'thermochemistry', 6, '{"en-us": "Relates the enthalpy change of a system to its internal energy change plus the expansion work against a constant external pressure. This relation follows from the definition of enthalpy and holds for processes at fixed pressure, the usual condition for laboratory chemistry. It shows why enthalpy changes, not internal energy changes, are tabulated for reactions open to the atmosphere."}', '["https://en.wikipedia.org/wiki/Enthalpy", "https://openstax.org/books/chemistry-2e/pages/5-3-enthalpy"]'),
  ('enthalpy_definition', '{"en-us": "Enthalpy definition"}', 'thermochemistry', 6, '{"en-us": "Enthalpy is a thermodynamic state function that combines a system''s internal energy with the pressure-volume product of its surroundings. Because many chemical and physical processes occur at constant atmospheric pressure, enthalpy changes are more convenient to measure than internal energy changes, making this quantity central to thermochemistry. It is an extensive property measured in joules."}', '["https://en.wikipedia.org/wiki/Enthalpy", "https://openstax.org/books/chemistry-2e/pages/5-3-enthalpy"]'),
  ('enthalpy_from_heat', '{"en-us": "Enthalpy change from heat at constant pressure"}', 'thermochemistry', 6, '{"en-us": "At constant pressure, and assuming only pressure–volume work is possible, the enthalpy change of a system equals the heat exchanged with its surroundings. This makes enthalpy experimentally convenient, since most laboratory reactions run in open containers at atmospheric pressure."}', '["https://chem.libretexts.org/Bookshelves/General_Chemistry/Map:_Chemistry_-_The_Central_Science_(Brown_et_al.)/05:_Thermochemistry/5.03:_Enthalpy", "https://chem.libretexts.org/Courses/University_of_Toronto/Chemistry%3A_Physical_Principles/05%3A_Thermochemistry/5.04%3A_Enthalpy", "https://chem.academy/book/enthalpy.html"]'),
  ('entropy_change', '{"en-us": "Entropy change for reversible heat transfer"}', 'entropy', 8, '{"en-us": "Defines the entropy change of a system as the heat exchanged along a reversible path divided by the absolute temperature at which the transfer occurs. It applies directly to constant-temperature processes such as phase changes, and since entropy is a state function, the same value describes the real (possibly irreversible) change between the same states."}', '["https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Principles_of_Modern_Chemistry_(Oxtoby_et_al.)/Unit_4%3A_Equilibrium_in_Chemical_Reactions/13%3A_Spontaneous_Processes_and_Thermodynamic_Equilibrium/13.4%3A_Entropy_Changes_in_Reversible_Processes", "https://en.wikipedia.org/wiki/Reversible_process_(thermodynamics)", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Thermodynamics_and_Chemical_Equilibrium_(Ellgen)/09%3A_The_Second_Law_-_Entropy_and_Spontaneous_Change/9.06%3A_Entropy_Changes_for_A_Reversible_Process"]'),
  ('entropy_change_heating_ideal_gas', '{"en-us": "Entropy change of ideal gas with temperature and volume"}', 'entropy', 8, '{"en-us": "Gives the total entropy change of a fixed quantity of ideal gas between two states, combining a temperature contribution through the constant-volume molar heat capacity and a volume contribution through the gas constant. Because entropy is a state function, this value holds for any path between the same initial and final states."}', '["https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/entropy-of-a-gas-3/", "https://web.mit.edu/16.unified/www/FALL/thermodynamics/notes/node40.html", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Physical_Chemistry_(Fleming)/05%3A_The_Second_Law/5.04%3A_Calculating_Entropy_Changes"]'),
  ('entropy_change_surroundings', '{"en-us": "Entropy change of surroundings"}', 'entropy', 8, '{"en-us": "When the surroundings behave as a large constant-temperature reservoir, any heat released by the system is absorbed reversibly by the surroundings, so their entropy change follows from the heat exchanged at that reservoir temperature. This lets the surroundings'' contribution to the total entropy change be computed from calorimetric data, usually assuming constant pressure."}', '["https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/The_Live_Textbook_of_Physical_Chemistry_(Peverati)/07%3A_Calculation_of_Entropy_and_the_Third_Law_of_Thermodynamics/7.02%3A_Calculation_of_Ssurr", "https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/16%3A_Entropy_and_Spontaneous_Reactions/16.13%3A_Including_the_Surroundings", "https://chemistry.stackexchange.com/questions/133645/entropy-change-of-surroundings-and-system"]'),
  ('entropy_change_universe', '{"en-us": "Entropy change of the universe"}', 'second_law', 8, '{"en-us": "Expresses the total entropy change of the universe (system plus everything outside it) as the sum of the entropy changes of the system and its surroundings. It is the quantitative basis of the second law of thermodynamics: a process is spontaneous when this total is positive and at equilibrium when it is zero."}', '["https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_(Zumdahl_and_Decoste)/10%3A_Entropy_Gibbs_Energy_and_Spontaneity/10.05%3A_Entropy_and_the_Second_Law_of_Thermodynamics", "https://courses.lumenlearning.com/chemistryformajors/chapter/the-second-and-third-laws-of-thermodynamics", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Thermodynamics_and_Chemical_Equilibrium_(Ellgen)/09%3A_The_Second_Law_-_Entropy_and_Spontaneous_Change/9.08%3A_The_Entropy_of_the_Universe"]'),
  ('entropy_isothermal_expansion', '{"en-us": "Entropy change for isothermal expansion of ideal gas"}', 'entropy', 8, '{"en-us": "Gives the entropy gained by a fixed quantity of ideal gas expanding at constant temperature. Since internal energy of an ideal gas depends only on temperature, all heat absorbed reversibly during the expansion goes into work, and the entropy increase depends only on how much the volume grows."}', '["https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Physical_Chemistry_(Fleming)/05%3A_The_Second_Law/5.04%3A_Calculating_Entropy_Changes", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map:_Chemistry_-_The_Central_Science_(Brown_et_al.)/19:_Chemical_Thermodynamics/19.02:_Entropy_and_the_Second_Law_of_Thermodynamics", "https://completeera.com/entropy-change-of-an-ideal-gas-the-basics-of-thermodynamics/"]'),
  ('entropy_mixing_ideal_gases', '{"en-us": "Entropy of mixing ideal gases"}', 'entropy', 9, '{"en-us": "Quantifies the entropy increase when distinct ideal gases mix at constant temperature and pressure. Because ideal-gas molecules do not interact, each component expands independently into the total volume, and the entropy gain depends only on the composition of the final mixture; it is always positive for genuine mixing."}', '["https://en.wikipedia.org/wiki/Entropy_of_mixing", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_%28Physical_and_Theoretical_Chemistry%29/Thermodynamics/Ideal_Systems/Entropy_of_Mixing", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Thermodynamics_and_Chemical_Equilibrium_%28Ellgen%29/13%3A_Equilibria_in_Reactions_of_Ideal_Gases/13.03%3A_The_Thermodynamics_of_Mixing_Ideal_Gases"]'),
  ('entropy_surroundings_constant_pressure', '{"en-us": "Entropy change of surroundings at constant pressure"}', 'second_law', 8, '{"en-us": "For a process at constant pressure and constant temperature, the heat absorbed by the surroundings equals the enthalpy change the system releases, so the surroundings'' entropy change follows directly from tabulated reaction enthalpies. This relation is the bridge used to derive the Gibbs free energy spontaneity criterion."}', '["https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/16:_Entropy_and_Spontaneous_Reactions/16.13:_Including_the_Surroundings", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_(Zumdahl_and_Decoste)/10%3A_Entropy_Gibbs_Energy_and_Spontaneity/10.05%3A_Entropy_and_the_Second_Law_of_Thermodynamics", "https://chemistry.stackexchange.com/questions/53364/is-%CE%94s-of-a-system-related-to-temperature-and-change-in-enthalpy"]'),
  ('enzyme_reaction_velocity_definition', '{"en-us": "Enzyme reaction velocity definition"}', 'biochemistry', 7, '{"en-us": "Defines the velocity of an enzyme-catalyzed reaction as the instantaneous rate at which substrate is consumed (equivalently, the rate at which product appears for one-to-one stoichiometry). Initial velocities measured this way are the raw data on which enzyme kinetics, including Michaelis–Menten analysis, is built."}', '["https://en.wikipedia.org/wiki/Enzyme_kinetics", "https://clinicalpub.com/enzymes", "https://www.pearson.com/channels/biochemistry/study-guides/introduction-to-enzyme-kinetics-principles-and-1"]'),
  ('enzyme_specific_activity_formula', '{"en-us": "Enzyme assay specific activity"}', 'biochemistry', 8, '{"en-us": "Expresses the catalytic power of an enzyme preparation relative to its protein mass, usually determined under substrate-saturating assay conditions. Because inactive or contaminating protein adds mass without contributing activity, specific activity rises as an enzyme purification proceeds and is the standard measure of enzyme purity."}', '["https://en.wikipedia.org/wiki/Enzyme_assay", "https://en.wikipedia.org/wiki/Enzyme_unit"]'),
  ('enzyme_turnover_number', '{"en-us": "Enzyme turnover number"}', 'biochemistry', 8, '{"en-us": "Gives the number of substrate molecules a single active site converts per unit time when the enzyme is saturated with substrate. As an intrinsic property of the enzyme–substrate pair, it allows catalytic efficiency to be compared across enzymes independently of how much enzyme is present."}', '["https://en.wikipedia.org/wiki/Turnover_number", "https://en.wikipedia.org/wiki/Enzyme_kinetics", "https://clinicalpub.com/enzymes"]'),
  ('equilibrium_constant_definition', '{"en-us": "Equilibrium constant definition"}', 'chemical_equilibrium', 6, '{"en-us": "Defines the equilibrium constant of a reversible reaction as the value the reaction quotient takes once equilibrium is reached: product concentrations appear in the numerator and reactant concentrations in the denominator, each raised to its stoichiometric coefficient. For a given temperature it is independent of the starting concentrations, making it the key quantity for predicting how far a reaction proceeds."}', '["https://en.wikipedia.org/wiki/Equilibrium_constant", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Equilibria/Chemical_Equilibria/The_Equilibrium_Constant", "https://www.chemguide.co.uk/physical/equilibria/kc.html"]'),
  ('equilibrium_constant_expression', '{"en-us": "Equilibrium constant from concentrations"}', 'chemical_equilibrium', 6, '{"en-us": "The law of mass action states that for a reversible reaction at equilibrium and constant temperature, the ratio of product concentrations to reactant concentrations is constant. Each concentration is raised to the power of its stoichiometric coefficient in the balanced equation; only gaseous and aqueous species are included, since pure solids and liquids have effectively constant concentration."}', '["https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_%28Physical_and_Theoretical_Chemistry%29/Equilibria/Chemical_Equilibria/The_Equilibrium_Constant", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_%28Petrucci_et_al.%29/15%3A_Principles_of_Chemical_Equilibrium/15.2%3A_The_Equilibrium_Constant_Expression", "https://www.chemguide.co.uk/physical/equilibria/kc.html", "https://unacademy.com/content/jee/study-material/chemistry/equilibrium-constant-kp-and-kc"]'),
  ('equilibrium_constant_from_gibbs', '{"en-us": "Equilibrium constant from standard Gibbs"}', 'chemical_equilibrium', 8, '{"en-us": "Relates the thermodynamic spontaneity of a reaction to its equilibrium position: the standard Gibbs free energy change determines how far a reaction proceeds toward products at equilibrium. A negative standard free energy change gives an equilibrium constant greater than one (products favored), while a positive value gives less than one. Assumes standard-state free energy data and ideal behavior at the given absolute temperature."}', '["https://chem.libretexts.org/Courses/Grand_Rapids_Community_College/CHM_120_-_Survey_of_General_Chemistry%28Neils%29/7%3A_Equilibrium_and_Thermodynamics/7.11%3A_Gibbs_Free_Energy_and_Equilibrium", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_-_The_Central_Science_(Brown_et_al.)/19%3A_Chemical_Thermodynamics/19.07%3A_Free_Energy_and_the_Equilibrium_Constant", "https://www.chemguide.co.uk/physical/entropy/deltagandk.html"]'),
  ('equilibrium_temperature_dependence', '{"en-us": "Van ''t Hoff equation"}', 'chemical_equilibrium', 8, '{"en-us": "Describes how the equilibrium constant of a reaction changes with temperature, derived by combining the Gibbs free energy relation with thermodynamics. For an endothermic reaction (positive enthalpy change) the equilibrium constant increases as temperature rises, while for an exothermic reaction it decreases. The integrated two-temperature form assumes the standard enthalpy change stays constant over the temperature range."}', '["https://en.wikipedia.org/wiki/Van_%27t_Hoff_equation", "https://chem.libretexts.org/Courses/Millersville_University/CHEM_341-_Physical_Chemistry_I/09%3A_Chemical_Equilibria/9.06%3A_Temperature_Dependence_of_Equilibrium_Constants_-_the_van_t_Hoff_Equation", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Physical_Chemistry_%28LibreTexts%29/26%3A_Chemical_Equilibrium/26.07%3A_The_van_%27t_Hoff_Equation", "https://sciencenotes.org/vant-hoff-equation-definition-derivation-and-applications/"]'),
  ('error_propagation_sum', '{"en-us": "Error propagation for sum"}', 'statistics', 7, '{"en-us": "Gives the uncertainty of a quantity computed as the sum (or difference) of two independent measured values. The individual uncertainties combine in quadrature rather than adding directly, so the combined uncertainty is always smaller than a plain addition of errors would suggest. Assumes the input uncertainties are independent and expressed as standard deviations; correlated inputs require an extra covariance term."}', '["https://en.wikipedia.org/wiki/Propagation_of_uncertainty", "https://www.nist.gov/pml/nist-technical-note-1297/nist-tn-1297-5-combined-standard-uncertainty", "https://www.datacamp.com/tutorial/error-propogation"]'),
  ('escape_kinetic_energy', '{"en-us": "Escape kinetic energy"}', 'escape_velocity', 6, '{"en-us": "The minimum kinetic energy an object of a given mass must be given to escape from a celestial body''s gravitational field starting at distance r from its center. It exactly balances the magnitude of the gravitational potential energy at that distance, so the object reaches infinity with zero speed. Assumes a spherical body, no atmosphere, and no other forces acting on the object."}', '["https://en.wikipedia.org/wiki/Escape_velocity", "https://en.wikipedia.org/wiki/Gravitational_potential_energy"]'),
  ('escape_velocity_density_radius', '{"en-us": "Escape velocity from density and radius"}', 'escape_velocity', 7, '{"en-us": "Expresses the escape velocity of a uniform spherical body in terms of its average density and radius instead of its mass. Substituting the mass of a uniform sphere into the standard escape-velocity formula shows that escape speed grows linearly with radius and with the square root of the density. Assumes the body has a spherically symmetric, uniform mass distribution."}', '["https://en.wikipedia.org/wiki/Escape_velocity", "https://en.wikipedia.org/wiki/Gravitational_potential_energy"]'),
  ('escape_velocity_formula', '{"en-us": "Escape velocity"}', 'escape_velocity', 6, '{"en-us": "The minimum launch speed at which a projectile leaves a body''s gravitational field and coasts to infinity without further propulsion, derived from conservation of energy by equating kinetic energy to the depth of the gravitational potential well. It depends only on the body''s mass and the starting distance from its center, not on the projectile''s own mass or launch direction. Assumes no atmospheric drag and no other gravitational influences."}', '["https://en.wikipedia.org/wiki/Escape_velocity", "https://en.wikipedia.org/wiki/Gravitational_potential_energy"]'),
  ('escape_velocity_from_mass_radius', '{"en-us": "Escape velocity from mass and radius"}', 'escape_velocity', 6, '{"en-us": "Gives the minimum speed needed to break free from the gravitational pull of a planet or other spherical body, launched from its surface, in terms of the body''s mass and radius. The required speed decreases with larger radius for a fixed mass and increases with the square root of the mass. Assumes a spherically symmetric body, no atmosphere, and no propulsion after launch."}', '["https://en.wikipedia.org/wiki/Escape_velocity", "https://en.wikipedia.org/wiki/Gravitational_potential_energy"]'),
  ('escaping_velocity_from_gravitational_potential', '{"en-us": "Escape velocity from gravitational potential"}', 'escape_velocity', 7, '{"en-us": "Obtains the escape speed from the depth of the gravitational potential well at the starting point: the launch kinetic energy per unit mass must equal the magnitude of the gravitational potential energy per unit mass there. This energy-based view applies at any distance from the attracting body and follows directly from conservation of energy. Assumes a conservative gravitational field and no drag or other forces."}', '["https://en.wikipedia.org/wiki/Escape_velocity", "https://en.wikipedia.org/wiki/Gravitational_potential_energy"]'),
  ('euler_lagrange_equation', '{"en-us": "Euler-Lagrange equation"}', 'differential_equations', 10, '{"en-us": "The central condition of the calculus of variations and of Lagrangian mechanics: a function that makes the action functional stationary must satisfy this differential equation relating the Lagrangian, the generalized coordinate, and the generalized velocity. It is used to derive the equations of motion for mechanical systems and to solve optimization problems over functions, taking the same form in any choice of generalized coordinates."}', '["https://en.wikipedia.org/wiki/Euler%E2%80%93Lagrange_equation", "https://en.wikipedia.org/wiki/Calculus_of_variations"]'),
  ('euler_triangle_formula', '{"en-us": "Euler''s formula for triangle distance"}', 'triangles', 8, '{"en-us": "Euler''s theorem in triangle geometry relates the distance between a triangle''s circumcenter and incenter to its circumradius and inradius. The formula yields the well-known Euler inequality R >= 2r, with equality only for equilateral triangles, and is sometimes called the Euler triangle formula."}', '["https://en.wikipedia.org/wiki/Euler%27s_theorem_in_geometry", "https://en.wikipedia.org/wiki/Incircle_and_excircles_of_a_triangle", "https://mathworld.wolfram.com/EulerTriangleFormula.html", "https://artofproblemsolving.com/wiki/index.php/Euler%27s_Formula_for_a_Triangle"]'),
  ('excess_pressure_bubble', '{"en-us": "Excess pressure inside a spherical bubble"}', 'surface_tension', 8, '{"en-us": "A spherical bubble of gas in a liquid has an internal pressure higher than the surrounding liquid due to surface tension acting on its two interfaces (inner and outer surfaces). The excess pressure is inversely proportional to the bubble radius, so smaller bubbles require larger pressures to maintain equilibrium; this follows from the Young-Laplace equation."}', '["https://en.wikipedia.org/wiki/Surface_tension", "https://en.wikipedia.org/wiki/Young%E2%80%93Laplace_equation", "https://en.wikipedia.org/wiki/Laplace_pressure", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.05%3A_Cohesion_and_Adhesion_in_Liquids"]'),
  ('excess_pressure_droplet', '{"en-us": "Excess pressure inside a spherical droplet"}', 'surface_tension', 8, '{"en-us": "Also known as the Laplace pressure of a spherical drop, this gives how much greater the pressure inside a small liquid droplet is than the pressure of the surrounding gas. The excess arises because surface tension pulls the curved surface inward, and it grows as the droplet gets smaller; it assumes a static spherical interface with a single liquid-gas surface (a soap bubble has two surfaces and twice the effect)."}', '["https://en.wikipedia.org/wiki/Laplace_pressure", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Tatum)/20%3A_Miscellaneous/20.02%3A_Surface_Tension/20.2.01%3A_Excess_Pressure_Inside_Drops_and_Bubbles", "https://en.wikipedia.org/wiki/Young%E2%80%93Laplace_equation"]'),
  ('excess_reactant_mass', '{"en-us": "Excess reactant remaining mass"}', 'limiting_reactants', 6, '{"en-us": "In a reaction with a limiting reactant, this gives the amount of the excess reactant left over once the reaction stops. The moles consumed are found from the limiting reactant via the stoichiometric mole ratio, converted to mass with the molar mass, and subtracted from what was present initially. It assumes the reaction goes to completion."}', '["https://chem.libretexts.org/Courses/College_of_the_Canyons/Chem_151%3A_Preparatory_General_Chemistry_OER/08%3A_Quantities_in_Chemical_Reactions_(Stoichiometry)/8.06%3A_How_Much_of_the_Excess_Reactant_Remains_after_a_Reaction", "https://general.chemistrysteps.com/how-to-find-the-amount-of-excess-reactant/", "https://www.physicsclassroom.com/tutorial/stoichiometry/limiting-and-excess-reactants/determining-the-excess-amount", "https://chem.libretexts.org/Courses/Anoka-Ramsey_Community_College/Introduction_to_Chemistry/08:_Stoichiometry/8.06:_Limiting_Reactants_and_Excess_Reactants"]'),
  ('excess_reactant_remaining', '{"en-us": "Excess reactant remaining"}', 'limiting_reactants', 6, '{"en-us": "Gives the amount of substance of the excess reactant left over after a reaction stops when the limiting reactant is used up. The consumed amount is found from the limiting reactant using the stoichiometric mole ratio, then subtracted from the initial amount. It assumes a complete reaction and a balanced chemical equation."}', '["https://general.chemistrysteps.com/how-to-find-the-amount-of-excess-reactant/", "https://psiberg.com/how-to-calculate-excess-reactant", "https://www.physicsclassroom.com/tutorial/stoichiometry/limiting-and-excess-reactants/determining-the-excess-amount", "https://chem.libretexts.org/Courses/College_of_the_Canyons/Chem_151%3A_Preparatory_General_Chemistry_OER/08%3A_Quantities_in_Chemical_Reactions_(Stoichiometry)/8.06%3A_How_Much_of_the_Excess_Reactant_Remains_after_a_Reaction"]'),
  ('expected_value_binomial', '{"en-us": "Expected value of a binomial distribution"}', 'probability', 7, '{"en-us": "The mean (expected value) of a binomial random variable, i.e. the average number of successes expected in a fixed number of independent yes/no trials with a constant success probability. It follows from linearity of expectation applied to the sum of the individual Bernoulli trials, and is used to find average outcomes in repeated-trial experiments."}', '["https://en.wikipedia.org/wiki/Binomial_distribution", "https://www.thoughtco.com/expected-value-of-binomial-distribution-3126551", "https://proofwiki.org/wiki/Expectation_of_Binomial_Distribution"]'),
  ('expected_value_discrete', '{"en-us": "Expected value of a discrete random variable"}', 'probability', 6, '{"en-us": "Defines the mean (expectation) of a discrete random variable as a probability-weighted average: each possible outcome contributes in proportion to how likely it is. It represents the long-run average value over many repetitions of the experiment and requires a valid probability distribution whose probabilities sum to one."}', '["https://en.wikipedia.org/wiki/Expected_value", "https://stats.libretexts.org/Courses/Saint_Mary%27s_College_Notre_Dame/MATH_345__-_Probability_(Kuter)/3%3A_Discrete_Random_Variables/3.6%3A_Expected_Value_of_Discrete_Random_Variables", "https://www.geeksforgeeks.org/maths/how-to-calculate-the-mean-or-expected-value-of-a-discrete-random-variable/"]'),
  ('exponent_logarithm_inverse', '{"en-us": "Exponent as inverse of logarithm"}', 'logarithms', 4, '{"en-us": "States the inverse property connecting exponentials and logarithms with the same base: taking a logarithm and then exponentiating undoes itself, returning the original number. It holds for any valid logarithm base (positive and not equal to one) acting on a positive argument, and underpins solving exponential equations by taking logarithms."}', '["https://en.wikipedia.org/wiki/List_of_logarithmic_identities", "https://mathmonks.com/logarithm/logarithm-rules-properties", "https://k12.libretexts.org/Bookshelves/Mathematics/Analysis/3%3A_Exponential_and_Logarithmic_Functions/3.3%3A_Properties_of_Logarithms/3.3.3%3A_Inverse_Properties_of_Logarithms"]'),
  ('exponent_power_rule', '{"en-us": "Exponent power rule"}', 'exponents', 3, '{"en-us": "Also called the power of a power rule, this law of exponents says that raising an already-exponentiated quantity to another power multiplies the two exponents while keeping the base unchanged. It comes from counting repeated copies of the inner power and is used constantly when simplifying algebraic expressions and solving exponential equations."}', '["https://mathworld.wolfram.com/ExponentLaws.html", "https://www.cuemath.com/algebra/power-of-a-power-rule/", "https://www.mathsisfun.com/algebra/exponent-laws.html"]'),
  ('exponent_product_rule', '{"en-us": "Exponent product rule"}', 'exponents', 2, '{"en-us": "Also called the product law of exponents, this rule states that multiplying two powers that share the same base gives a single power whose exponent is the sum of the two exponents. It follows directly from counting factors of the base and is one of the fundamental laws used to simplify algebraic expressions."}', '["https://math.libretexts.org/Bookshelves/Applied_Mathematics/Calculus_for_Business_and_Social_Sciences_Corequisite_Workbook_(Dominguez_Martinez_and_Saykali)/05%3A_Exponents_and_Exponent_Rules/5.02%3A_The_Product_Rule_for_Exponents", "https://www.cuemath.com/numbers/multiplying-exponents/", "https://www.mathdoubts.com/indices-product-rule-same-base/"]'),
  ('exponent_quotient_rule', '{"en-us": "Exponent quotient rule"}', 'exponents', 3, '{"en-us": "Also called the quotient law of exponents, this rule states that dividing two powers with the same base leaves a single power whose exponent is the difference of the two exponents. It follows from canceling common factors of the base (or equivalently from adding the reciprocal with a negative exponent) and requires a nonzero base."}', '["https://en.wikipedia.org/wiki/Exponentiation", "https://mathworld.wolfram.com/ExponentLaws.html", "https://www.cuemath.com/algebra/exponent-rules/"]'),
  ('exponential_decay_diff_eq', '{"en-us": "Exponential decay differential equation"}', 'differential_equations', 7, '{"en-us": "The first-order differential equation defining exponential decay: a quantity changes at a rate proportional to its own current value, with the negative sign meaning the quantity decreases. It models processes such as radioactive disintegration, capacitor discharge, and first-order chemical reactions; solving it yields the familiar exponential decay law with time constant set by the decay constant."}', '["https://en.wikipedia.org/wiki/Exponential_decay", "https://en.wikipedia.org/wiki/Radioactive_decay"]'),
  ('exponential_growth_diff_eq', '{"en-us": "Exponential growth differential equation"}', 'differential_equations', 7, '{"en-us": "The first-order differential equation defining exponential growth (also known as the Malthusian law): a quantity changes at a rate directly proportional to its own current value. It models populations, compound interest, and chain reactions under unlimited resources; its solution is the exponential function with rate constant r (negative r gives decay instead)."}', '["https://en.wikipedia.org/wiki/Exponential_growth", "https://en.wikipedia.org/wiki/Malthusian_growth_model"]'),
  ('exponential_growth_solution', '{"en-us": "Exponential growth solution"}', 'differential_equations', 7, '{"en-us": "The closed-form solution of the proportional-growth differential equation: a quantity grows exponentially from its initial value, with the growth rate setting how fast it multiplies over time. It applies to unconstrained population growth, continuously compounded interest, and any process whose rate of change is proportional to the amount present; it assumes the growth rate stays constant."}', '["https://en.wikipedia.org/wiki/Exponential_function", "https://en.wikipedia.org/wiki/Exponential_growth", "https://en.wikipedia.org/wiki/Malthusian_growth_model"]'),
  ('exposure_formula', '{"en-us": "Radiation exposure"}', 'nuclear_physics', 8, '{"en-us": "Radiation exposure is a dosimetric quantity that measures the ionization produced by X-ray or gamma-ray photons in air, defined as the electric charge liberated by the radiation per unit mass of air. Its SI unit is the coulomb per kilogram (C/kg), which has largely replaced the legacy röntgen (R). Exposure is used in radiation protection as an intermediate step between source activity and quantities such as absorbed or equivalent dose that more directly describe energy deposition in tissue."}', '["https://en.wikipedia.org/wiki/Radiation_exposure", "https://en.wikipedia.org/wiki/Roentgen_(unit)", "https://en.wikipedia.org/wiki/Absorbed_dose", "https://www.nrc.gov/about-nrc/radiation/health-effects/measuring-radiation.html", "https://www.icrp.org/publication.asp?id=ICRP%20Publication%20103"]'),
  ('f_number', '{"en-us": "F-number of a lens"}', 'lenses', 7, '{"en-us": "The f-number (also called focal ratio or f-stop) of a lens is the dimensionless ratio of its focal length to the diameter of its entrance pupil. A lower f-number means a wider aperture that admits more light, while a higher f-number gives a smaller aperture, greater depth of field, and more diffraction."}', '["https://en.wikipedia.org/wiki/F-number", "https://phys.libretexts.org/Bookshelves/Optics/Geometric_Optics_(Tatum)/06%3A_Aperture_and_Resolution", "https://www.britannica.com/technology/f-number", "https://optics.ansys.com/hc/en-us/articles/360041042473-Numerical-aperture", "https://www.edmundoptics.com/knowledge-center/application-notes/optics/an-introduction-to-apertures/"]'),
  ('f_statistic_regression', '{"en-us": "F-statistic for regression"}', 'statistics', 9, '{"en-us": "The F-statistic for a multiple linear regression tests whether the model explains a significant portion of the response variance. It compares the mean square due to regression to the mean square of the residuals; under the null hypothesis that all slope coefficients are zero it follows an F-distribution with (p, n-p-1) degrees of freedom."}', '["https://en.wikipedia.org/wiki/F-test", "https://en.wikipedia.org/wiki/F-statistic", "https://www.itl.nist.gov/div898/handbook/eda/section3/eda3673.htm", "https://online.stat.psu.edu/stat501/lesson/6/6.2", "https://stattrek.com/regression/f-test", "https://www.khanacademy.org/math/statistics-probability/significance-tests-regression-inference"]'),
  ('factorial_definition', '{"en-us": "Factorial definition"}', 'arithmetic', 3, '{"en-us": "The factorial of a non-negative integer n is the product of all positive integers less than or equal to n, with the empty product for n=0 defined as 1 by convention. Factorials count permutations of n distinct objects, underlie the binomial coefficients, and admit a continuous extension to the gamma function for non-integer arguments."}', '["https://en.wikipedia.org/wiki/Factorial", "https://mathworld.wolfram.com/Factorial.html", "https://www.khanacademy.org/math/precalculus/xb83d8e8f1d8e0a80:prob-comb/xb83d8e8f1d8e0a80:combinatorics-basics/v/factorial-and-counting-arrangements", "https://www.britannica.com/science/factorial", "https://oeis.org/A000142"]'),
  ('faraday_constant_definition', '{"en-us": "Faraday constant in terms of fundamental constants"}', 'electrochemistry', 8, '{"en-us": "The Faraday constant represents the magnitude of electric charge carried by one mole of elementary charge carriers such as electrons or protons, expressed in coulombs per mole. Following the 2019 SI redefinition it has an exact value derived from the elementary charge and the Avogadro constant. It is widely used in electrolysis calculations to relate the amount of substance transformed to the charge passed through an electrochemical cell."}', '["https://en.wikipedia.org/wiki/Faraday_constant", "https://physics.nist.gov/cgi-bin/cuu/Value?f", "https://www.britannica.com/science/Faraday-constant", "https://goldbook.iupac.org/terms/view/F02325", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Supplemental_Modules_(Analytical_Chemistry)/Electrochemistry/Faraday''s_Law"]'),
  ('faraday_lenz_law', '{"en-us": "Faraday-Lenz law"}', 'electromagnetic_induction', 7, '{"en-us": "The Faraday-Lenz law states that the electromotive force induced in a closed conducting loop equals the negative time-rate-of-change of the magnetic flux through the loop. The negative sign (Lenz''s law) makes the induced emf oppose the change in flux that produces it. For a coil of N turns, the emf is multiplied by N."}', '["https://en.wikipedia.org/wiki/Faraday%27s_law_of_induction", "https://en.wikipedia.org/wiki/Lenz%27s_law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/13%3A_Electromagnetic_Induction/13.01%3A_Faradays_Law", "https://www.britannica.com/science/Faradays-law-of-induction", "https://www.khanacademy.org/science/physics/magnetic-forces-and-magnetic-fields/magnetic-flux-faradays-law/a/what-is-faradays-law"]'),
  ('faradays_law', '{"en-us": "Faraday''s law of induction"}', 'electromagnetic_induction', 7, '{"en-us": "For a coil of N tightly wound turns in a changing magnetic field, Faraday''s law states that the induced emf equals the negative of the total flux linkage rate of change. The negative sign is Lenz''s law, expressing that the induced emf opposes the change producing it. This is the foundation of transformers, generators, and induction-based motors."}', '["https://en.wikipedia.org/wiki/Faraday%27s_law_of_induction", "https://en.wikipedia.org/wiki/Electromagnetic_induction", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/13%3A_Electromagnetic_Induction/13.01%3A_Faradays_Law", "https://www.britannica.com/science/Faradays-law-of-induction", "https://www.khanacademy.org/science/physics/magnetic-forces-and-magnetic-fields/magnetic-flux-faradays-law/a/what-is-faradays-law"]'),
  ('first_law_adiabatic_process', '{"en-us": "First law: adiabatic process"}', 'first_law', 7, '{"en-us": "An adiabatic process involves no heat exchange with the surroundings. Under this constraint the first law of thermodynamics reduces to a balance between the change in internal energy and the work done on the system. Such processes approximate rapid compressions and expansions, as in engines and the atmosphere."}', '["https://en.wikipedia.org/wiki/Adiabatic_process", "https://en.wikipedia.org/wiki/First_law_of_thermodynamics", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book%3A_Thermodynamics_(Tatum)/03%3A_The_First_Law", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Thermodynamics/The_Four_Laws_of_Thermodynamics/The_First_Law_of_Thermodynamics", "https://www.britannica.com/science/first-law-of-thermodynamics"]'),
  ('first_law_cyclic_process', '{"en-us": "First law for a cyclic process"}', 'first_law', 7, '{"en-us": "Internal energy is a state function, so over a complete thermodynamic cycle the net change in internal energy is zero. Equivalently, the net heat absorbed equals the net work done by the system around the cycle, which is the basis for defining heat-engine efficiency."}', '["https://en.wikipedia.org/wiki/First_law_of_thermodynamics", "https://en.wikipedia.org/wiki/Thermodynamic_cycle", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book%3A_Thermodynamics_(Sire)/04%3A_The_First_Law_of_Thermodynamics/4.05%3A_Cyclic_Processes", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Physical_Chemistry_(LibreTexts)/05%3A_Phase_Diagrams/5.02%3A_First_Law_of_Thermodynamics"]'),
  ('first_law_internal_energy_change', '{"en-us": "First law: internal energy change"}', 'first_law', 7, '{"en-us": "The first law of thermodynamics expresses conservation of energy: the change in a closed system''s internal energy equals the heat added to the system plus the work done on it. This is one common sign convention; an equivalent form used in engineering writes the change as heat added minus work done by the system."}', '["https://en.wikipedia.org/wiki/First_law_of_thermodynamics", "https://en.wikipedia.org/wiki/Internal_energy", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book%3A_Thermodynamics_(Sire)/04%3A_The_First_Law_of_Thermodynamics/4.02%3A_Internal_Energy_and_the_First_Law", "https://www.khanacademy.org/science/physics/thermodynamics-essentials"]'),
  ('first_law_isobaric_process', '{"en-us": "First law of thermodynamics for isobaric process"}', 'first_law', 7, '{"en-us": "For an isobaric (constant-pressure) process the first law reduces to a relation between the heat added, the change in internal energy, and the pressure-volume work. The work done by the system at constant pressure is P times the change in volume, which is why the heat added at constant pressure equals the change in enthalpy."}', '["https://en.wikipedia.org/wiki/Isobaric_process", "https://en.wikipedia.org/wiki/First_law_of_thermodynamics", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book%3A_Thermodynamics_(Sire)/04%3A_The_First_Law_of_Thermodynamics/4.04%3A_Heat_Capacity_at_Constant_Pressure", "https://www.khanacademy.org/science/physics/thermodynamics-essentials"]'),
  ('first_law_isochoric_process', '{"en-us": "First law of thermodynamics for isochoric process"}', 'first_law', 7, '{"en-us": "An isochoric (constant-volume) process performs no pressure-volume work because the volume cannot change. Consequently, by the first law, all heat added to a closed system at constant volume goes into changing its internal energy; the molar heat capacity at constant volume relates this energy change to the temperature change."}', '["https://en.wikipedia.org/wiki/Isochoric_process", "https://en.wikipedia.org/wiki/First_law_of_thermodynamics", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book%3A_Thermodynamics_(Sire)/04%3A_The_First_Law_of_Thermodynamics/4.03%3A_Heat_Capacity_at_Constant_Volume", "https://www.khanacademy.org/science/physics/thermodynamics-essentials"]'),
  ('first_law_of_thermodynamics', '{"en-us": "First law of thermodynamics"}', 'first_law', 6, '{"en-us": "The first law of thermodynamics states that energy is conserved: the change in a closed system''s internal energy equals the heat added to the system minus the work done by the system. It is a restatement of the conservation of energy for thermodynamic processes and rules out perpetual-motion machines of the first kind."}', '["https://en.wikipedia.org/wiki/First_law_of_thermodynamics", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Thermodynamics/The_Four_Laws_of_Thermodynamics/First_Law_of_Thermodynamics", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/03%3A_The_First_Law_of_Thermodynamics", "https://www.khanacademy.org/science/physics/thermodynamics/specific-heat-and-heat-transfer/a/what-is-the-first-law-of-thermodynamics"]'),
  ('first_order_half_life', '{"en-us": "First-order half-life"}', 'chemical_kinetics', 7, '{"en-us": "The half-life of a first-order reaction is the time required for the reactant concentration to fall to half its initial value. It is independent of the initial concentration and is determined solely by the rate constant k, which is the basis for techniques such as radiocarbon dating."}', '["https://en.wikipedia.org/wiki/Rate_equation#First_order", "https://en.wikipedia.org/wiki/Half-life", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Kinetics/Reaction_Rates/First-Order_Reactions", "https://www.khanacademy.org/science/biology/biochemistry/chemical-reactions-rate-laws/v/first-order-reaction-half-life"]'),
  ('flow_velocity_pipe_radius_relation', '{"en-us": "Flow velocity from pipe radius change"}', 'continuity_equation', 6, '{"en-us": "For an incompressible fluid flowing through a pipe whose cross-section changes, mass conservation (the continuity equation) requires the product of cross-sectional area and flow speed to remain constant. For a circular pipe, this yields the relation between downstream and upstream velocities and the corresponding radii, and is the basis of the Venturi effect."}', '["https://en.wikipedia.org/wiki/Continuity_equation#Fluid_dynamics", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.02%3A_What_is_a_Fluid", "https://www.khanacademy.org/science/physics/fluids/what-is-a-fluid/v/what-is-a-fluid", "https://www.britannica.com/science/continuity-equation"]'),
  ('fluid_pressure_depth_relation', '{"en-us": "Pressure at depth in a fluid"}', 'pressure', 5, '{"en-us": "The pressure in a static fluid increases linearly with depth, as the weight of the overlying fluid adds to the pressure at the surface. This hydrostatic relation holds for an incompressible fluid in a gravitational field and is the basis of manometers, barometers, and the calculation of forces on submerged surfaces."}', '["https://en.wikipedia.org/wiki/Pressure#Hydrostatic_pressure", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.03%3A_Fluid_Statics", "https://www.khanacademy.org/science/physics/fluids/density-and-pressure-topic/a/what-is-pressure", "https://www.britannica.com/science/fluid-statics"]'),
  ('focal_length_mirror', '{"en-us": "Focal length of a spherical mirror"}', 'mirrors', 5, '{"en-us": "For a spherical mirror, the focal length is half the radius of curvature. This holds exactly in the paraxial (small-angle) approximation, where spherical aberration is negligible, and is the basis of the mirror equation relating object and image distances."}', '["https://en.wikipedia.org/wiki/Mirror#Curved_mirrors", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_(OpenStax)/02%3A_Reflection/2.02%3A_Spherical_Mirrors", "https://www.khanacademy.org/science/physics/geometric-optics/mirrors/v/concave-mirror-equation", "https://www.britannica.com/technology/mirror-optics"]'),
  ('force_between_parallel_wires', '{"en-us": "Force between parallel current-carrying wires"}', 'magnetism', 8, '{"en-us": "Two long, straight, parallel wires carrying currents exert an attractive or repulsive force on each other through their magnetic fields. The magnitude of the force per unit length is proportional to the product of the currents and inversely proportional to the separation; this relation is the basis for the formal definition of the ampere."}', '["https://en.wikipedia.org/wiki/Force_between_magnets#Force_between_two_parallel_electric_currents", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields/12.04%3A_Magnetic_Force_between_Two_Parallel_Currents", "https://www.khanacademy.org/science/physics/magnetic-forces-and-magnetic-fields/magnetic-force-on-current-carrying-wires/v/magnetic-force-between-two-wires", "https://www.britannica.com/science/electromagnetism/Magnetic-fields-and-forces"]'),
  ('force_from_pressure', '{"en-us": "Force from pressure"}', 'pressure', 4, '{"en-us": "Pressure is the normal force applied per unit area, so the force on a surface equals the pressure times the area on which it acts. This relation is used to convert between pressure (e.g. fluid or gas) and the total force exerted on a surface of known area, such as a piston, wall, or valve."}', '["https://en.wikipedia.org/wiki/Pressure", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.04%3A_Measuring_Pressure", "https://www.britannica.com/science/pressure", "https://www.physicsclassroom.com/class/fluids/Lesson-1/Pressure", "https://www.khanacademy.org/science/physics/fluids/density-and-pressure/a/what-is-pressure"]'),
  ('force_inclined_plane_normal', '{"en-us": "Normal force on an inclined plane"}', 'forces', 5, '{"en-us": "On a frictionless inclined plane making an angle θ with the horizontal, the component of the object''s weight perpendicular to the surface is balanced by the normal force, giving N = mg cos θ. This relation is used together with the parallel component mg sin θ to analyze static and sliding motion on a slope."}', '["https://en.wikipedia.org/wiki/Inclined_plane", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/06%3A_Applications_of_Newton''s_Laws/6.04%3A_Friction_(Part_1)", "https://www.physicsclassroom.com/class/vectors/Lesson-3/Inclined-Planes", "https://www.khanacademy.org/science/physics/forces-newtons-laws/inclined-planes-friction/a/what-are-inclined-planes", "https://www.britannica.com/science/inclined-plane"]'),
  ('force_inclined_plane_parallel', '{"en-us": "Parallel force component on an inclined plane"}', 'forces', 5, '{"en-us": "On a frictionless inclined plane at angle θ above the horizontal, the component of an object''s weight directed parallel to the surface (down the slope) is the gravitational force component mg sin θ. This component drives the object''s acceleration along the plane when no other force opposes it."}', '["https://en.wikipedia.org/wiki/Inclined_plane", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/06%3A_Applications_of_Newton''s_Laws/6.04%3A_Friction_(Part_1)", "https://www.physicsclassroom.com/class/vectors/Lesson-3/Inclined-Planes", "https://www.khanacademy.org/science/physics/forces-newtons-laws/inclined-planes-friction/a/inclined-planes-friction", "https://www.britannica.com/science/inclined-plane"]'),
  ('forced_oscillator_ode', '{"en-us": "Forced damped harmonic oscillator ODE"}', 'differential_equations', 9, '{"en-us": "The forced damped harmonic oscillator is a mass–spring system with viscous damping acted on by a sinusoidal driving force. Its equation of motion combines inertia, the velocity-proportional damping term 2γẋ, the restoring force ω₀²x, and the external drive F₀cos(ωt), and is the basis of resonance, AC circuits, and many models in physics and engineering. The form shown uses the normalization in which the driving amplitude is written directly (so it corresponds to F₀/m when written per unit mass)."}', '["https://en.wikipedia.org/wiki/Harmonic_oscillator", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Oscillations/15.06%3A_Forced_Oscillations", "https://math.libretexts.org/Bookshelves/Differential_Equations/Differential_Equations_(Chasnov)/07%3A_Second-Order_Linear_Constant-Coefficient_Differential_Equations/7.05%3A_Forced_Harmonic_Oscillator", "https://www.khanacademy.org/science/physics/oscillatory-motion/forced-oscillations-and-resonance", "https://www.britannica.com/science/harmonic-oscillator"]'),
  ('formal_charge_calculation', '{"en-us": "Formal charge calculation"}', 'chemical_bonding', 6, '{"en-us": "Formal charge is a bookkeeping tool for evaluating Lewis structures: it assigns to each atom a hypothetical charge equal to its group valence electrons minus the electrons assigned to it in the structure (its lone-pair electrons plus half of its bonding electrons). Structures whose atoms have formal charges closest to zero are typically the best representation of the molecule."}', '["https://en.wikipedia.org/wiki/Formal_charge", "https://chem.libretexts.org/Bookshelves/General_Chemistry/General_Chemistry_(OpenStax)/04%3A_Structural_Geometry_of_Molecules/4.05%3A_Formal_Charges_and_Resonance", "https://www.khanacademy.org/science/organic-chemistry/gen-chem-review/bonding-in-lewis-structures/v/formal-charge-1", "https://www.masterorganicchemistry.com/2010/09/24/formal-charge/", "https://www.britannica.com/science/formal-charge"]'),
  ('formal_charge_formula', '{"en-us": "Formal charge"}', 'chemical_bonding', 6, '{"en-us": "Formal charge is a bookkeeping tool for evaluating Lewis structures: each atom in a molecule is assigned a hypothetical charge equal to its group valence electrons minus the electrons assigned to it in the structure (its lone-pair electrons plus half of its shared bonding electrons). Structures in which the formal charges on all atoms are closest to zero (and any nonzero charges reside on the most electronegative atoms) are considered the best Lewis representation of the molecule."}', '["https://en.wikipedia.org/wiki/Formal_charge", "https://chem.libretexts.org/Bookshelves/General_Chemistry/General_Chemistry_(OpenStax)/04%3A_Structural_Geometry_of_Molecules/4.05%3A_Formal_Charges_and_Resonance", "https://www.khanacademy.org/science/organic-chemistry/gen-chem-review/bonding-in-lewis-structures/v/formal-charge-1", "https://www.masterorganicchemistry.com/2010/09/24/formal-charge/", "https://www.britannica.com/science/formal-charge"]'),
  ('fouriers_law', '{"en-us": "Heat conduction (Fourier''s law)"}', 'heat_transfer', 7, '{"en-us": "Fourier''s law of heat conduction states that the time rate of heat flow through a material is proportional to the cross-sectional area normal to the flow and to the temperature difference across it, and inversely proportional to the thickness. It is the foundational constitutive relation for conductive heat transfer and the starting point for deriving the heat equation."}', '["https://en.wikipedia.org/wiki/Thermal_conduction#Fourier%27s_law", "https://en.wikipedia.org/wiki/Fourier%27s_law", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book%3A_Thermodynamics_(Sun)_-_A_Course_in_Thermodynamics/05%3A_Heat_Transfer/5.02%3A_Conduction_-_Fouriers_Law", "https://www.britannica.com/science/Fouriers-law", "https://www.khanacademy.org/science/physics/thermodynamics/specific-heat-and-heat-transfer/v/thermal-conductivity"]'),
  ('fraction_submerged', '{"en-us": "Fraction of object submerged in fluid"}', 'buoyancy', 5, '{"en-us": "For a floating object in hydrostatic equilibrium, the fraction of the object''s volume submerged in a fluid equals the ratio of the object''s average density to the fluid''s density. This follows from equating the object''s weight to the weight of the displaced fluid (Archimedes'' principle)."}', '["https://en.wikipedia.org/wiki/Buoyancy", "https://www.britannica.com/science/Archimedes-principle", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.05%3A_Archimedes_Principle", "https://www.khanacademy.org/science/physics/fluids/buoyancy-archimedes-principle", "https://courses.lumenlearning.com/sunysb-physics/chapter/archimedes-principle/"]'),
  ('fractional_exponent_rule', '{"en-us": "Fractional exponent rule"}', 'exponents', 4, '{"en-us": "A fractional (rational) exponent m/n on a positive base a is defined as the n-th root of a raised to the m-th power. The numerator m gives the power and the denominator n gives the root index, so that a^(1/n) is the principal n-th root of a."}', '["https://en.wikipedia.org/wiki/Exponentiation#Rational_exponents", "https://www.khanacademy.org/math/algebra/x2f8bb11595b61c86:rational-exponents-radicals/x2f8bb11595b61c86:radicals-to-rational-exponents/v/rewriting-radicals-as-rational-exponents", "https://mathworld.wolfram.com/FractionalExponent.html", "https://www.cuemath.com/algebra/fractional-exponents/", "https://www.britannica.com/science/exponentiation"]'),
  ('free_fall_height', '{"en-us": "Free fall height from time"}', 'constant_acceleration', 4, '{"en-us": "For an object released from rest in a uniform gravitational field with negligible air resistance, the vertical distance fallen is half the gravitational acceleration times the square of the elapsed time. The result is the standard kinematic relation obtained by integrating the constant downward acceleration."}', '["https://en.wikipedia.org/wiki/Free_fall#Uniform_gravitational_field_without_air_resistance", "https://www.khanacademy.org/science/physics/one-dimensional-motion/kinematic-formulas/v/kinematic-formulas-1d", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/03%3A_Motion_Along_a_Straight_Line/3.05%3A_Free_Fall", "https://www.britannica.com/science/free-fall", "https://www.physicsclassroom.com/Class/1DKin/U1L5c.cfm"]'),
  ('free_fall_velocity_from_height', '{"en-us": "Free fall velocity from height"}', 'constant_acceleration', 4, '{"en-us": "For an object falling from rest through a height h in a uniform gravitational field with negligible air resistance, the speed reached is the square root of 2gh, independent of mass. It follows from energy conservation or from the constant-acceleration kinematic relation v² = u² + 2as."}', '["https://en.wikipedia.org/wiki/Free_fall#Uniform_gravitational_field_without_air_resistance", "https://www.khanacademy.org/science/physics/one-dimensional-motion/kinematic-formulas/v/kinematic-formulas-1d", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/03%3A_Motion_Along_a_Straight_Line/3.05%3A_Free_Fall", "https://www.britannica.com/science/free-fall", "https://www.physicsclassroom.com/Class/1DKin/U1L5c.cfm"]'),
  ('frequency_period', '{"en-us": "Frequency from period"}', 'harmonic_motion', 3, '{"en-us": "The frequency of a periodic phenomenon is the reciprocal of its period: f = 1/T. The period is the time to complete one full cycle, while frequency counts the number of cycles per unit time (measured in hertz)."}', '["https://en.wikipedia.org/wiki/Frequency#Definitions_and_units", "https://en.wikipedia.org/wiki/Period_(physics)", "https://www.khanacademy.org/science/physics/wave-mechanics-introduction/wave-properties/v/period-of-waves", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Waves/15.03%3A_Period_Frequency_and_Amplitude", "https://www.britannica.com/science/frequency"]'),
  ('friction_coefficient_static_definition', '{"en-us": "Coefficient of static friction"}', 'friction', 5, '{"en-us": "The coefficient of static friction, typically denoted \\mu_s, is an empirical, dimensionless quantity that characterizes the ratio of the maximum static friction force between two surfaces to the normal force pressing them together. It sets the threshold at which an applied force will cause an object to begin sliding, with \\mu_s usually larger than the corresponding kinetic coefficient."}', '["https://en.wikipedia.org/wiki/Friction#Static_friction", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/06:_Applying_Newton''s_Laws", "https://www.britannica.com/science/friction", "https://www.physics.libretexts.org/Bookshelves/Classical_Mechanics/Variational_Principles_in_Classical_Mechanics_(Cline)/04%3A_Lagrangian_Mechanics_with_Constraints/4.03%3A_Friction"]'),
  ('friction_force', '{"en-us": "Friction force"}', 'friction', 4, '{"en-us": "The Coulomb/Amontons friction law relates the magnitude of dry friction to the normal force pressing two surfaces together via an empirical coefficient of friction. For kinetic (sliding) friction the magnitude is approximately constant and independent of the apparent contact area and sliding speed, in the simple Amontons-Coulomb model."}', '["https://en.wikipedia.org/wiki/Friction#Kinetic_friction", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/06:_Applying_Newton''s_Laws", "https://www.britannica.com/science/friction", "https://www.physics.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Dutra)/04%3A_Lagrangian_Mechanics/4.02%3A_Constraints_and_Friction"]'),
  ('friction_force_horizontal', '{"en-us": "Friction force on a horizontal surface"}', 'friction', 4, '{"en-us": "On a flat horizontal surface, with no other vertical forces, the normal force on an object equals its weight, so the kinetic friction force reduces to the kinetic coefficient times the object''s weight. The formula assumes no applied vertical forces and a level surface, so that the normal force equals the gravitational force."}', '["https://en.wikipedia.org/wiki/Friction#Kinetic_friction", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/06:_Applying_Newton''s_Laws", "https://www.britannica.com/science/friction", "https://www.physics.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Dutra)/04%3A_Lagrangian_Mechanics/4.02%3A_Constraints_and_Friction"]'),
  ('friction_kinetic_energy_loss', '{"en-us": "Energy loss due to kinetic friction"}', 'friction', 5, '{"en-us": "The mechanical energy dissipated by kinetic friction over a sliding distance equals the product of the kinetic friction force and the distance traveled (work done against the friction force). All this energy is converted to heat, sound, and surface deformation; the formula assumes the friction force is approximately constant over the path."}', '["https://en.wikipedia.org/wiki/Friction#Kinetic_friction", "https://en.wikipedia.org/wiki/Work_(physics)#Moving_in_a_straight_line_(skid_to_a_stop)", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/06:_Applying_Newton''s_Laws", "https://www.britannica.com/science/friction", "https://www.physics.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Dutra)/04%3A_Lagrangian_Mechanics/4.02%3A_Constraints_and_Friction"]'),
  ('fringe_spacing_double_slit', '{"en-us": "Fringe spacing in double-slit"}', 'interference', 7, '{"en-us": "In the Young double-slit experiment, the equally spaced bright fringes on a distant screen are separated by a fringe spacing that increases linearly with the wavelength and the slit-to-screen distance and decreases as the slits are brought closer together. The formula applies in the small-angle, far-field (Fraunhofer) approximation where the path difference across the slits is approximately m*lambda."}', '["https://en.wikipedia.org/wiki/Double-slit_experiment", "https://en.wikipedia.org/wiki/Wave_interference#Between_two_plane_waves", "https://en.wikipedia.org/wiki/Diffraction", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_(OpenStax)/03%3A_Interference", "https://www.britannica.com/science/double-slit-experiment"]'),
  ('froude_number', '{"en-us": "Froude number"}', 'reynolds_number', 8, '{"en-us": "The Froude number is a dimensionless ratio of flow inertia to gravitational forces in free-surface or stratified flows, named after William Froude. It is widely used in naval architecture to compare wave-making resistance between ships of different sizes, in open-channel hydraulics to distinguish subcritical from supercritical flow, and in studies of animal locomotion."}', '["https://en.wikipedia.org/wiki/Froude_number", "https://www.britannica.com/science/Froude-number", "https://www.engineersedge.com/fluid_flow/froude_number.htm", "https://www.powderprocess.net/Mixing.html"]'),
  ('frustum_of_cone_lateral_area', '{"en-us": "Lateral area of a conical frustum"}', 'plane_geometry', 6, '{"en-us": "The lateral (side) surface area of a right circular conical frustum with top radius, bottom radius, and height. It is computed as the product of the average of the two base circumferences and the slant height. The two circular bases are excluded; the total surface area additionally includes the two base disks."}', '["https://en.wikipedia.org/wiki/Frustum", "https://mathworld.wolfram.com/ConicalFrustum.html", "https://www.cuemath.com/geometry/frustum-of-a-cone/", "https://math.libretexts.org/Bookshelves/Geometry/Geometry_(University_of_Utah)/05%3A_Perimeter_and_Area/5.07%3A_Frustums", "https://www.khanacademy.org/math/geometry-home/triangle-properties/special-right-triangles/v/frustums", "https://www.varsitytutors.com/hotmath/hotmath_help/topics/frustum"]'),
  ('frustum_of_cone_volume', '{"en-us": "Volume of a conical frustum"}', 'plane_geometry', 6, '{"en-us": "Volume of a right circular conical frustum with parallel circular bases of radii and perpendicular height. The formula follows from subtracting the small cone removed at the apex from the full cone. It is one of the oldest known volume formulas, appearing in the ancient Egyptian Moscow Mathematical Papyrus."}', '["https://en.wikipedia.org/wiki/Frustum", "https://mathworld.wolfram.com/ConicalFrustum.html", "https://www.cuemath.com/geometry/frustum-of-a-cone/", "https://math.libretexts.org/Bookshelves/Geometry/Geometry_(University_of_Utah)/05%3A_Perimeter_and_Area/5.07%3A_Frustums", "https://www.varsitytutors.com/hotmath/hotmath_help/topics/frustum"]'),
  ('gas_constant_boltzmann', '{"en-us": "Gas constant from Boltzmann constant"}', 'ideal_gases', 8, '{"en-us": "The molar gas constant is the Avogadro constant multiplied by the Boltzmann constant. It converts between the per-particle energy scale of statistical mechanics and the per-mole energy scale used in macroscopic thermodynamics and chemistry, appearing in the ideal gas law and many other fundamental equations."}', '["https://en.wikipedia.org/wiki/Gas_constant", "https://en.wikipedia.org/wiki/Boltzmann_constant", "https://en.wikipedia.org/wiki/Avogadro_constant", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Properties_of_Gases/Gas_Laws/The_Ideal_Gas_Law", "https://physics.nist.gov/cgi-bin/cuu/Value?r"]'),
  ('gauge_pressure_definition', '{"en-us": "Gauge pressure"}', 'pressure', 5, '{"en-us": "Gauge pressure is the pressure of a system measured relative to the local ambient atmospheric pressure, so it reads zero at atmospheric conditions and is positive or negative relative to that reference. It is the quantity most pressure gauges and tire-pressure meters display directly, since they are typically referenced to the surrounding atmosphere rather than to a perfect vacuum."}', '["https://en.wikipedia.org/wiki/Pressure#Gauge", "https://en.wikipedia.org/wiki/Gauge_pressure", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.04%3A_Measuring_Pressure", "https://www.engineeringtoolbox.com/gauge-absolute-pressure-d_519.html", "https://www.bbc.co.uk/bitesize/guides/zcwyw6f/revision/4"]'),
  ('gauss_law_electric', '{"en-us": "Gauss''s law for electricity"}', 'electric_fields', 8, '{"en-us": "Gauss''s law for electricity, one of Maxwell''s equations, states that the net electric flux through any closed surface (a Gaussian surface) is proportional to the total electric charge enclosed by that surface. It provides a powerful symmetry-based method for computing electric fields of highly symmetric charge configurations and is equivalent to Coulomb''s law."}', '["https://en.wikipedia.org/wiki/Gauss%27s_law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/06%3A_Gauss%27s_Law", "https://www.khanacademy.org/science/physics/charge-electric-force-and-voltage/gauss-law/v/gauss-law-overview", "https://www.britannica.com/science/Gauss-law", "https://courses.lumenlearning.com/suny-physics/chapter/19-2-gauss-law/"]'),
  ('gauss_law_magnetic', '{"en-us": "Gauss''s law for magnetism"}', 'magnetism', 8, '{"en-us": "Gauss''s law for magnetism, one of Maxwell''s equations, states that the net magnetic flux through any closed surface is zero. It is equivalent to the nonexistence of magnetic monopoles: magnetic field lines form closed loops with no sources or sinks."}', '["https://en.wikipedia.org/wiki/Gauss%27s_law_for_magnetism", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/08%3A_Electromagnetic_Induction", "https://www.khanacademy.org/science/physics/charge-electric-force-and-voltage/gauss-law/v/gauss-law-overview", "https://www.britannica.com/science/Gauss-law", "https://courses.lumenlearning.com/suny-physics/chapter/19-3-gauss-law-for-magnetism/"]'),
  ('gay_lussacs_law', '{"en-us": "Gay-Lussac''s law"}', 'ideal_gases', 5, '{"en-us": "Gay-Lussac''s law, in its pressure-temperature form, states that the pressure of a fixed amount of gas held at constant volume is directly proportional to its absolute temperature. It is one of the special cases of the ideal gas law, applying when volume and the amount of gas are held constant."}', '["https://en.wikipedia.org/wiki/Gay-Lussac%27s_law", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Properties_of_Gases/Gas_Laws/Gay-Lussac''s_Law", "https://www.britannica.com/science/Gay-Lussacs-law", "https://www.thoughtco.com/gay-lussaces-law-606469", "https://www.grc.nasa.gov/www/k-12/airplane/glussac.html"]'),
  ('general_energy_conservation', '{"en-us": "General conservation of energy"}', 'conservation_of_energy', 5, '{"en-us": "The law of conservation of energy states that the total energy of an isolated system remains constant over time. Energy may be transformed from one form to another (kinetic, potential, thermal, etc.) or transferred between objects, but it is neither created nor destroyed."}', '["https://en.wikipedia.org/wiki/Conservation_of_energy", "https://www.britannica.com/science/conservation-of-energy", "https://courses.lumenlearning.com/suny-physics/chapter/7-1-conservation-of-energy/", "https://www.physics.gov.au/learn/sites/default/files/Conservation_of_Energy.pdf", "https://opentextbc.ca/physicstestbook2/chapter/conservation-of-energy/"]'),
  ('geometric_distribution_mean', '{"en-us": "Geometric distribution mean"}', 'probability', 7, '{"en-us": "The geometric distribution models the number of independent Bernoulli trials needed to obtain the first success, with success probability p on each trial. Its expected value (mean) is the reciprocal of the success probability, so a rarer event requires a larger expected number of trials."}', '["https://en.wikipedia.org/wiki/Geometric_distribution", "https://mathworld.wolfram.com/GeometricDistribution.html", "https://www.britannica.com/science/geometric-distribution", "https://statproofbook.github.io/P/geomean", "https://online.stat.psu.edu/stat414/lesson/15/15.1"]'),
  ('geometric_distribution_probability', '{"en-us": "Geometric Distribution Probability"}', 'probability', 7, '{"en-us": "The geometric distribution gives the probability that the first success in a sequence of independent Bernoulli trials with success probability p occurs on the k-th trial. The probability decreases geometrically with k because each of the first k-1 trials must be a failure."}', '["https://en.wikipedia.org/wiki/Geometric_distribution", "https://mathworld.wolfram.com/GeometricDistribution.html", "https://www.britannica.com/science/geometric-distribution", "https://online.stat.psu.edu/stat414/lesson/15/15.1", "https://statproofbook.github.io/P/geopmf"]'),
  ('geometric_distribution_variance', '{"en-us": "Geometric distribution variance"}', 'probability', 8, '{"en-us": "The variance of a geometrically distributed random variable, defined as the number of trials until the first success, equals (1-p) divided by the square of the success probability. The variance grows rapidly as the success probability approaches zero."}', '["https://en.wikipedia.org/wiki/Geometric_distribution", "https://mathworld.wolfram.com/GeometricDistribution.html", "https://www.britannica.com/science/geometric-distribution", "https://online.stat.psu.edu/stat414/lesson/15/15.1", "https://statproofbook.github.io/P/geovar"]'),
  ('geometric_mean_formula', '{"en-us": "Geometric mean"}', 'arithmetic', 4, '{"en-us": "The geometric mean of a set of positive numbers is the n-th root of their product. Unlike the arithmetic mean, it is appropriate for quantities that combine multiplicatively, such as growth rates or ratios, and is always less than or equal to the arithmetic mean."}', '["https://en.wikipedia.org/wiki/Geometric_mean", "https://mathworld.wolfram.com/GeometricMean.html", "https://www.britannica.com/science/geometric-mean", "https://math.libretexts.org/Bookshelves/Algebra/Intermediate_Algebra/06%3A_Radical_Expressions_and_Functions/6.07%3A_Geometric_Mean", "https://www.cuemath.com/geometry/geometric-mean/"]'),
  ('geometric_series_infinite_sum', '{"en-us": "Sum of infinite geometric series"}', 'arithmetic', 5, '{"en-us": "When the common ratio r has absolute value less than 1, an infinite geometric series converges to a finite sum equal to its first term divided by one minus the common ratio. The formula follows by taking the limit of the finite geometric series sum as the number of terms grows without bound, since the trailing term vanishes."}', '["https://en.wikipedia.org/wiki/Geometric_series", "https://en.wikipedia.org/wiki/Geometric_progression", "https://mathworld.wolfram.com/GeometricSeries.html", "https://en.wikibooks.org/wiki/Algebra/Chapter_15/Geometric_Progression_(GP)"]'),
  ('geometric_series_nth_term', '{"en-us": "nth term of a geometric sequence"}', 'arithmetic', 4, '{"en-us": "The nth term of a geometric sequence with first term a_1 and common ratio r is obtained by multiplying a_1 by r raised to the power (n-1). This explicit formula generalizes the recursive definition in which each term equals the previous term multiplied by r."}', '["https://en.wikipedia.org/wiki/Geometric_progression", "https://en.wikipedia.org/wiki/Geometric_series", "https://mathworld.wolfram.com/GeometricSeries.html", "https://en.wikibooks.org/wiki/Algebra/Chapter_15/Geometric_Progression_(GP)"]'),
  ('geometric_series_sum', '{"en-us": "Sum of finite geometric series"}', 'arithmetic', 5, '{"en-us": "The sum of the first n terms of a geometric progression with first term a and common ratio r (with r not equal to 1) equals a times the quantity one minus r to the n over one minus r. The formula follows from multiplying the sum by r and subtracting it from itself, which cancels all interior terms and leaves only the endpoints."}', '["https://en.wikipedia.org/wiki/Geometric_series", "https://en.wikipedia.org/wiki/Geometric_progression", "https://mathworld.wolfram.com/GeometricSeries.html", "https://en.wikibooks.org/wiki/Algebra/Chapter_15/Geometric_Progression_(GP)"]'),
  ('gibbs_cell_potential', '{"en-us": "Gibbs free energy from cell potential"}', 'electrochemistry', 8, '{"en-us": "The maximum non-expansion work obtainable from an electrochemical reaction equals the change in Gibbs free energy, which is related to the cell potential by the negative of the number of moles of electrons transferred times the Faraday constant times the cell potential. A positive cell potential corresponds to a spontaneous reaction with negative Gibbs free energy change."}', '["https://en.wikipedia.org/wiki/Gibbs_free_energy", "https://en.wikipedia.org/wiki/Electrochemical_cell", "https://en.wikipedia.org/wiki/Nernst_equation", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Supplemental_Modules_(Analytical_Chemistry)/Electrochemistry/Reversible_Ions/Electrochemical_Cells"]'),
  ('gibbs_equilibrium', '{"en-us": "Gibbs free energy and equilibrium constant"}', 'chemical_equilibrium', 8, '{"en-us": "The standard Gibbs free energy change of a reaction is related to its equilibrium constant by the negative of the gas constant times absolute temperature times the natural logarithm of the equilibrium constant. A reaction with K greater than one has a negative standard free energy change and is product-favored at equilibrium."}', '["https://en.wikipedia.org/wiki/Equilibrium_constant", "https://en.wikipedia.org/wiki/Gibbs_free_energy", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Equilibria/Chemical_Equilibria/The_Equilibrium_Constant", "https://www.khanacademy.org/test-prep/mcat/chemical-processes/thermodynamics-and-equilibrium/a/free-energy-and-equilibrium"]'),
  ('gibbs_free_energy', '{"en-us": "Gibbs free energy"}', 'thermochemistry', 7, '{"en-us": "Gibbs free energy combines enthalpy and entropy into a single thermodynamic potential for processes at constant temperature and pressure. A negative change in Gibbs free energy indicates a spontaneous process, and equilibrium corresponds to the state at which this change is zero."}', '["https://en.wikipedia.org/wiki/Gibbs_free_energy", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Thermodynamics/Thermodynamic_Cycles/Thermodynamics_of_Biological_Processes/The_Gibbs_Free_Energy", "https://www.khanacademy.org/test-prep/mcat/chemical-processes/thermodynamics-and-equilibrium/a/gibbs-free-energy", "https://www.britannica.com/science/Gibbs-free-energy"]'),
  ('gibbs_nernst_relation', '{"en-us": "Gibbs free energy and cell potential"}', 'electrochemistry', 8, '{"en-us": "The maximum non-expansion (electrical) work obtainable from a thermodynamically closed system at constant temperature and pressure equals the change in Gibbs free energy. This relation provides the thermodynamic bridge between the Gibbs free energy of a cell reaction and the measured cell potential, and underlies the derivation of the Nernst equation."}', '["https://en.wikipedia.org/wiki/Nernst_equation", "https://en.wikipedia.org/wiki/Gibbs_free_energy", "https://en.wikipedia.org/wiki/Electrochemical_cell", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Supplemental_Modules_(Analytical_Chemistry)/Electrochemistry/Electrochemistry_and_Thermodynamics", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Electrochemistry/Electrochemical_Thermodynamics"]'),
  ('gibbs_nonstandard', '{"en-us": "Gibbs free energy under non-standard conditions"}', 'chemical_equilibrium', 8, '{"en-us": "The Gibbs free energy change of a chemical reaction at arbitrary composition is given by the standard Gibbs energy change plus a temperature-dependent correction involving the reaction quotient. This expression, which is the thermodynamic form of the Nernst equation, lets one compute the spontaneity of a reaction away from standard state and reduces to the standard change when all activities are unity."}', '["https://en.wikipedia.org/wiki/Gibbs_free_energy", "https://en.wikipedia.org/wiki/Reaction_quotient", "https://en.wikipedia.org/wiki/Chemical_equilibrium", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Equilibria/Chemical_Equilibria/Free_Energy_and_Chemical_Equilibria", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Thermodynamics/Thermodynamic_Cycles/Equilibrium_Constants_and_Gibbs_Energy"]'),
  ('gibbs_spontaneity_condition', '{"en-us": "Gibbs free energy spontaneity condition"}', 'second_law', 7, '{"en-us": "At constant temperature and pressure, the sign of the Gibbs free energy change determines whether a process is spontaneous, non-spontaneous, or at equilibrium. A negative change drives the process forward, a positive change requires input of free energy, and zero change corresponds to thermodynamic equilibrium."}', '["https://en.wikipedia.org/wiki/Spontaneous_process", "https://en.wikipedia.org/wiki/Gibbs_free_energy", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Thermodynamics/The_Four_Laws_of_Thermodynamics/Spontaneity_(Thermodynamics)", "https://www.khanacademy.org/science/biology/energy-and-enzymes/the-laws-of-thermodynamics/a/gibbs-free-energy"]'),
  ('gibbs_standard_reaction', '{"en-us": "Standard Gibbs free energy of reaction"}', 'thermochemistry', 7, '{"en-us": "The standard Gibbs energy change of a chemical reaction is obtained by combining the standard Gibbs energies of formation of the products and reactants, each weighted by its stoichiometric coefficient. Tabulated values of standard Gibbs energies of formation at 1 bar and a specified temperature are used to predict reaction spontaneity under standard conditions."}', '["https://en.wikipedia.org/wiki/Gibbs_free_energy", "https://en.wikipedia.org/wiki/Standard_Gibbs_energy_change_of_formation", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Thermodynamics/Thermodynamic_Cycles/Standard_Free_Energy_Change", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_-_The_Central_Science_(Brown_et_al.)/19%3A_Chemical_Thermodynamics/19.05%3A_Gibbs_Free_Energy"]'),
  ('grahams_law', '{"en-us": "Graham''s law of effusion"}', 'ideal_gases', 7, '{"en-us": "Graham''s law relates the rates at which two gases effuse through a small hole to the square roots of their molar masses. The empirical law follows from kinetic theory, which gives the rms speed of gas molecules as inversely proportional to the square root of their molar mass, and is widely used to separate isotopes and to estimate molecular weights from measured effusion rates."}', '["https://en.wikipedia.org/wiki/Graham%27s_law", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Kinetics/09._Gas_Phase_Kinetics/Graham''s_Laws_of_Effusion_and_Diffusion", "https://www.britannica.com/science/Grahams-law", "https://www.chem.purdue.edu/gchelp/atoms/therfflaw.html", "https://chem.libretexts.org/Bookshelves/Inorganic_Chemistry/Supplemental_Modules_and_Websites_(Inorganic_Chemistry)/Chemical_Reactions/Case_Studies/Graham''s_Law_of_Effusion"]'),
  ('gravitational_acceleration_at_height', '{"en-us": "Gravitational acceleration at height"}', 'newtonian_gravity', 6, '{"en-us": "The gravitational acceleration at a height above the surface of a spherical body of mass M and radius R is obtained by applying Newton''s law of universal gravitation at a distance R plus that height from the body''s center. The result falls off as the inverse square of the radial distance and is widely used in geophysics and orbital mechanics."}', '["https://en.wikipedia.org/wiki/Gravity_of_Earth", "https://en.wikipedia.org/wiki/Newton%27s_law_of_universal_gravitation", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(D''Inverno)/01%3A_The_Planetary_Model_of_the_Atom/1.04%3A_Gravitational_Field", "https://www.physicsclassroom.com/class/circles/Lesson-3/The-Value-of-g", "https://en.wikipedia.org/wiki/Standard_gravity"]'),
  ('gravitational_binding_energy_sphere', '{"en-us": "Gravitational binding energy of a uniform sphere"}', 'newtonian_gravity', 9, '{"en-us": "The gravitational binding energy of a uniform-density sphere is the minimum energy required to disperse its mass to infinity, equal in magnitude to its self-gravitational potential energy."}', '["https://en.wikipedia.org/wiki/Gravitational_binding_energy", "https://phys.libretexts.org/Bookshelves/Astronomy__Cosmology/Book%3A_Celestial_Mechanics_(Tatum)/02%3A_Gravitational_Field_and_Potential/2.06%3A_Gravitational_Binding_Energy", "https://www.britannica.com/science/gravitational-binding-energy", "https://www.astronomicalheritage.net/index.php/sites-articles-menu-item/197-binding-energy", "https://scienceworld.wolfram.com/physics/GravitationalBindingEnergy.html", "https://farside.ph.utexas.edu/teaching/336k/Newton/node114.html"]'),
  ('gravitational_binding_energy_uniform_sphere', '{"en-us": "Gravitational binding energy of a uniform sphere"}', 'newtonian_gravity', 9, '{"en-us": "The gravitational binding energy of a uniform-density sphere is the minimum energy required to disperse its mass to infinity, equal in magnitude to its self-gravitational potential energy."}', '["https://en.wikipedia.org/wiki/Gravitational_binding_energy", "https://phys.libretexts.org/Bookshelves/Astronomy__Cosmology/Book%3A_Celestial_Mechanics_(Tatum)/02%3A_Gravitational_Field_and_Potential/2.06%3A_Gravitational_Binding_Energy", "https://www.britannica.com/science/gravitational-binding-energy", "https://farside.ph.utexas.edu/teaching/336k/Newton/node114.html", "https://scienceworld.wolfram.com/physics/GravitationalBindingEnergy.html"]'),
  ('gravitational_field_inside_sphere', '{"en-us": "Gravitational field inside a uniform sphere"}', 'newtonian_gravity', 8, '{"en-us": "Inside a uniform-density sphere of total mass M and radius R, the gravitational field grows linearly with distance r from the centre, depending only on the mass enclosed within radius r."}', '["https://en.wikipedia.org/wiki/Gravitational_field", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Variational_Principles_in_Classical_Mechanics_(Cline)/02%3A_Review_of_Newtonian_Mechanics/2.06%3A_Gravitational_Field_of_a_Spherical_Shell_and_a_Uniform_Sphere", "https://farside.ph.utexas.edu/teaching/336k/Newton/node115.html", "https://www.britannica.com/science/gravity-physics", "https://scienceworld.wolfram.com/physics/GravitationalFieldInsideaSphere.html"]'),
  ('gravitational_field_strength', '{"en-us": "Gravitational field strength"}', 'newtonian_gravity', 5, '{"en-us": "The gravitational field strength at a point equals the gravitational force per unit test mass placed there; for a spherically symmetric body treated as a point mass at its centre, the field falls off as the inverse square of the distance from the centre."}', '["https://en.wikipedia.org/wiki/Gravitational_acceleration", "https://en.wikipedia.org/wiki/Gravitational_field", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/13%3A_Gravitation/13.02%3A_Newton''s_Law_of_Universal_Gravitation", "https://farside.ph.utexas.edu/teaching/336k/Newton/node113.html", "https://www.britannica.com/science/gravity-physics", "https://www.physicsclassroom.com/class/circles/Lesson-3/Newton-s-Law-of-Universal-Gravitation"]'),
  ('gravitational_force_two_masses', '{"en-us": "Gravitational force between two masses"}', 'newtonian_gravity', 5, '{"en-us": "Newton''s law of universal gravitation states that every pair of point masses attracts each other with a force proportional to the product of the masses and inversely proportional to the square of the distance between their centres; it also applies to spherically symmetric bodies, which attract as if all their mass were concentrated at the centre."}', '["https://en.wikipedia.org/wiki/Newton%27s_law_of_universal_gravitation", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/13%3A_Gravitation/13.02%3A_Newton''s_Law_of_Universal_Gravitation", "https://www.britannica.com/science/Newtons-law-of-gravitation", "https://www.physicsclassroom.com/class/circles/Lesson-3/Newton-s-Law-of-Universal-Gravitation", "https://farside.ph.utexas.edu/teaching/336k/Newton/node112.html", "https://scienceworld.wolfram.com/physics/NewtonsLawofUniversalGravitation.html"]'),
  ('gravitational_potential_energy', '{"en-us": "Gravitational potential energy"}', 'potential_energy', 4, '{"en-us": "Near the surface of a massive body such as Earth, where the gravitational field is approximately uniform, the gravitational potential energy of an object of mass m at height h above a chosen reference level is the work required to lift it there, with the constant g approximated by the standard surface gravity."}', '["https://en.wikipedia.org/wiki/Gravitational_energy", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/07%3A_Work_and_Kinetic_Energy/7.03%3A_Gravitational_Potential_Energy", "https://www.britannica.com/science/gravitational-potential-energy", "https://www.physicsclassroom.com/class/energy/Lesson-2/Mechanical-Energy", "https://farside.ph.utexas.edu/teaching/336k/Newton/node116.html"]'),
  ('gravitational_potential_point', '{"en-us": "Gravitational potential of a point mass"}', 'newtonian_gravity', 7, '{"en-us": "The gravitational potential at a point is the gravitational potential energy per unit mass that would be required to bring a test mass from infinity to that point in a conservative gravitational field. By convention the potential is taken to be zero at infinity, so the value is negative everywhere outside the source. The expression applies to a true point mass and, by the shell theorem, to the exterior of any spherically symmetric body of total mass M."}', '["https://en.wikipedia.org/wiki/Gravitational_potential", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Sunil_Patel)/12%3A_Gravitation/12.03%3A_Gravitational_Potential_Energy", "https://www.britannica.com/science/gravitational-potential", "https://astronomy.swin.edu.au/cosmos/g/gravitational+potential"]'),
  ('gravitational_potential_surface', '{"en-us": "Gravitational potential at surface"}', 'newtonian_gravity', 7, '{"en-us": "The gravitational potential at the surface of a spherically symmetric body equals the value of the point-mass potential evaluated at the body''s radius R. It is the negative of the work per unit mass needed to move a test mass from the surface to infinity, and provides a quick estimate of how strongly a body retains nearby objects."}', '["https://en.wikipedia.org/wiki/Gravitational_potential", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/13%3A_Gravitation/13.04%3A_Gravitational_Potential_Energy_and_Total_Energy", "https://www.britannica.com/science/gravitational-potential", "https://astronomy.swin.edu.au/cosmos/g/gravitational+potential"]'),
  ('gravitational_time_dilation', '{"en-us": "Gravitational time dilation"}', 'relativity', 9, '{"en-us": "Clocks deeper in a gravitational well run more slowly than clocks far from the source. The relation, derived from the Schwarzschild metric, gives the elapsed proper time t'' at radius r for a clock near a non-rotating spherical mass M, in terms of the coordinate time t_0 measured by a distant observer; it is valid in the weak-field limit when r is greater than the Schwarzschild radius."}', '["https://en.wikipedia.org/wiki/Gravitational_time_dilation", "https://phys.libretexts.org/Bookshelves/Astronomy__Cosmology/Cosmology_(Mehra)/4%3A_Gravity/4.2%3A_Gravitational_Redshift_and_Gravitational_Lensing", "https://www.britannica.com/science/gravitational-redshift", "https://math.temple.edu/~pasha/math144/Chapter8.pdf"]'),
  ('half_angle_cosine', '{"en-us": "Half-angle cosine identity"}', 'trigonometric_identities', 6, '{"en-us": "Expresses the square of the cosine of half an angle in terms of the cosine of the full angle. It follows from the angle-addition identity cos(2a) = 2cos²(a) - 1, and is widely used to evaluate trigonometric expressions at angles such as 22.5° or 75°."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities", "https://mathworld.wolfram.com/Half-AngleFormulas.html", "https://www.khanacademy.org/math/trigonometry/trig-identities-and-proofs/half-angle-identities/a/half-angle-identities", "https://www.cuemath.com/trigonometry/half-angle-formula/"]'),
  ('half_angle_sine', '{"en-us": "Half-angle sine identity"}', 'trigonometric_identities', 6, '{"en-us": "Expresses the square of the sine of half an angle in terms of the cosine of the full angle. It follows from the angle-addition identity cos(2a) = 1 - 2sin²(a), and is widely used to evaluate trigonometric expressions at angles such as 22.5° or 75°."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities", "https://mathworld.wolfram.com/Half-AngleFormulas.html", "https://www.khanacademy.org/math/trigonometry/trig-identities-and-proofs/half-angle-identities/a/half-angle-identities", "https://www.cuemath.com/trigonometry/half-angle-formula/"]'),
  ('half_angle_tangent_cosine_form', '{"en-us": "Half Angle Tangent (Cosine Form)"}', 'trigonometric_identities', 7, '{"en-us": "One of the two common forms of the tangent half-angle identity; expresses tan(θ/2) in terms of cos(θ) and sin(θ). It is useful in integral calculus and anywhere the tangent half-angle substitution t = tan(θ/2) is applied, such as in the Weierstrass substitution."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities", "https://mathworld.wolfram.com/Half-AngleFormulas.html", "https://www.khanacademy.org/math/trigonometry/trig-identities-and-proofs/half-angle-identities/a/half-angle-identities", "https://www.cuemath.com/trigonometry/half-angle-formula/"]'),
  ('half_angle_tangent_sine_form', '{"en-us": "Half Angle Tangent (Sine Form)"}', 'trigonometric_identities', 7, '{"en-us": "The tangent half-angle identity expresses tan(θ/2) in terms of the full-angle sine and cosine. It is widely used in calculus (Weierstrass/tangent half-angle substitution) to convert trigonometric integrals into rational form, and in geometry to relate rational values of the half-angle tangent to Pythagorean triples."}', '["https://en.wikipedia.org/wiki/Tangent_half-angle_formula", "https://en.wikipedia.org/wiki/List_of_trigonometric_identities", "https://math.libretexts.org/Bookshelves/Precalculus/Book%3A_Precalculus_(OpenStax)/7%3A_The_Unit_Circle-_Cosine_and_Sine/7.05%3A_Other_Trigonometric_Functions", "https://www.encyclopediaofmath.org/index.php?title=Tangent_formula", "https://planetmath.org/TangentOfHalvedAngle"]'),
  ('hall_voltage', '{"en-us": "Hall voltage"}', 'magnetism', 8, '{"en-us": "The Hall voltage is the transverse potential difference that develops across a current-carrying conductor or semiconductor placed in a magnetic field perpendicular to the current. It is widely used to measure magnetic field strength and to characterize charge carrier type, density, and mobility in materials."}', '["https://en.wikipedia.org/wiki/Hall_effect", "https://en.wikipedia.org/wiki/Hall_effect_sensor", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields/12.06%3A_The_Hall_Effect", "https://www.britannica.com/science/Hall-effect", "https://www.electronics-tutorials.ws/electromagnetism/hall-effect.html", "https://www.physics-and-radio-electronics.com/electronic-devices-and-circuits/sensors/hallsensor/halleffectformula.html"]'),
  ('harmonic_mean_formula', '{"en-us": "Harmonic mean"}', 'arithmetic', 6, '{"en-us": "The harmonic mean of two positive numbers is the reciprocal of the arithmetic mean of their reciprocals, equal to twice the product divided by the sum. It is one of the three Pythagorean means and is the appropriate average for rates and ratios, such as average speed over equal distances or the equivalent resistance of two equal resistors in parallel."}', '["https://en.wikipedia.org/wiki/Harmonic_mean", "https://math.libretexts.org/Bookshelves/Algebra/Intermediate_Algebra/05%3A_Radical_Expressions_and_Functions/5.07%3A_Harmonic_Mean", "https://www.britannica.com/science/harmonic-mean", "https://www.cuemath.com/data/harmonic-mean/", "https://www.calculator.net/harmonic-mean-calculator.html"]'),
  ('heat_capacity_definition_general', '{"en-us": "Heat capacity from heat and temperature change"}', 'heat', 5, '{"en-us": "Heat capacity is an extensive property of a body that quantifies the amount of heat energy required to produce a unit change in temperature. It depends on the conditions of the process (e.g. constant pressure or volume) and on the mass and composition of the material."}', '["https://en.wikipedia.org/wiki/Heat_capacity", "https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/15%3A_Thermodynamics-_Atoms_Molecules_and_Energy/15.08%3A_Heat_Capacity", "https://www.britannica.com/science/heat-capacity", "https://www.physicsclassroom.com/Class/thermalP/u18l1c.cfm", "https://www.khanacademy.org/science/physics/thermodynamics/specific-heat-and-heat-of-fusion/v/heat-capacity", "https://courses.lumenlearning.com/suny-physics/chapter/15-1-temperature-and-thermal-equilibrium/"]'),
  ('heat_capacity_ratio', '{"en-us": "Heat capacity ratio"}', 'ideal_gases', 7, '{"en-us": "The heat capacity ratio (also called the adiabatic index or Laplace''s coefficient) is the ratio of the heat capacity at constant pressure to the heat capacity at constant volume. It plays a key role in the speed of sound in gases and in the characterization of reversible adiabatic processes of ideal gases."}', '["https://en.wikipedia.org/wiki/Heat_capacity_ratio", "https://en.wikipedia.org/wiki/Relations_between_specific_heats", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Thermodynamics/Thermodynamic_Cycles/Heat_Capacity_Ratio", "https://www.britannica.com/science/heat-capacity-ratio", "https://www.engineersedge.com/heat_transfer/heat_capacity_ratio_gamma.htm", "https://physics.info/specific-heat/"]'),
  ('heat_conduction_composite_wall', '{"en-us": "Heat conduction through a composite wall"}', 'heat_transfer', 8, '{"en-us": "Steady-state heat conduction through a composite wall made of two layers in series is analogous to a thermal circuit in which the layer thermal resistances add. The rate of heat flow equals the temperature difference between the hot and cold sides divided by the sum of the per-layer thermal resistances, with the area appearing in the resistance definitions."}', '["https://en.wikipedia.org/wiki/Thermal_conductance_and_resistance", "https://en.wikipedia.org/wiki/Heat_conduction", "https://en.wikipedia.org/wiki/Thermal_insulation", "https://eng.libretexts.org/Bookshelves/Mechanical_Engineering/Heat_Transfer_(Bergman)/Conduction", "https://www.engineersedge.com/heat_transfer/composite_wall_thermal_resistance_13924.htm", "https://www.thermal-engineering.org/what-is-composite-wall-heat-transfer/"]'),
  ('heat_convection_newtons_law', '{"en-us": "Newton''s law of cooling (convection)"}', 'heat_transfer', 7, '{"en-us": "Newton''s law of cooling states that the rate of convective heat transfer from a body to its surroundings is proportional to the temperature difference between the body and the surrounding fluid. The proportionality constant is the convective heat transfer coefficient, which depends on the fluid properties, flow regime, and surface geometry. The law is most accurate for forced convection with small temperature differences; it is only approximate for natural (buoyancy-driven) convection and does not apply to radiative cooling."}', '["https://en.wikipedia.org/wiki/Newton%27s_law_of_cooling", "https://en.wikipedia.org/wiki/Heat_transfer_coefficient", "https://en.wikipedia.org/wiki/Convection_(heat_transfer)", "https://www.britannica.com/science/convection", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book%3A_Heat_and_Thermodynamics_(Tatum)/02%3A_Heat_as_a_Form_of_Energy/2.05%3A_Newton''s_Law_of_Cooling", "https://www.khanacademy.org/science/physics/work-and-energy/work-and-energy-tutorial/a/what-is-convection"]'),
  ('heat_engine_efficiency_formula', '{"en-us": "Heat engine efficiency"}', 'heat_engines', 6, '{"en-us": "Heat engine efficiency is the ratio of useful work output produced by a heat engine to the heat energy supplied from the high-temperature reservoir. By the second law of thermodynamics, this efficiency is always less than one, with the Carnot efficiency (depending only on the temperatures of the hot and cold reservoirs) setting the upper bound."}', '["https://en.wikipedia.org/wiki/Thermal_efficiency", "https://en.wikipedia.org/wiki/Heat_engine", "https://www.britannica.com/technology/heat-engine", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book%3A_Heat_and_Thermodynamics_(Tatum)/03%3A_The_Second_Law_of_Thermodynamics/3.05%3A_Heat_Engines", "https://www.khanacademy.org/science/physics/work-and-energy/work-and-energy-tutorial/a/heat-engines", "https://courses.lumenlearning.com/suny-physics/chapter/15-5-the-second-law-of-thermodynamics/"]'),
  ('heat_engine_refrigerator_coefficient', '{"en-us": "Coefficient of performance (refrigerator)"}', 'heat_engines', 7, '{"en-us": "The coefficient of performance (COP) of a refrigerator is the ratio of the heat removed from the cold reservoir to the net work input to the refrigerator. By the first law of thermodynamics, the work input equals the heat rejected to the hot reservoir minus the heat absorbed from the cold reservoir, so the COP can equivalently be written as the cold-reservoir heat divided by that difference. COP values greater than one are common because refrigeration requires moving heat rather than generating it."}', '["https://en.wikipedia.org/wiki/Coefficient_of_performance", "https://en.wikipedia.org/wiki/Heat_pump_and_refrigeration_cycle", "https://www.britannica.com/technology/heat-pump", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book%3A_Heat_and_Thermodynamics_(Tatum)/03%3A_The_Second_Law_of_Thermodynamics/3.06%3A_Refrigerators", "https://courses.lumenlearning.com/suny-physics/chapter/15-5-the-second-law-of-thermodynamics/"]'),
  ('heat_engine_thermal_efficiency', '{"en-us": "Thermal efficiency of a heat engine"}', 'heat_engines', 6, '{"en-us": "The thermal efficiency of a heat engine is the fraction of the heat input from the high-temperature reservoir that is converted into useful work. By the first law of thermodynamics, the work output equals the heat input minus the heat rejected to the cold reservoir, so the efficiency can also be written as one minus the ratio of rejected to absorbed heat. The second law of thermodynamics constrains this efficiency to be less than the Carnot efficiency determined by the reservoir temperatures."}', '["https://en.wikipedia.org/wiki/Thermal_efficiency", "https://en.wikipedia.org/wiki/Heat_engine", "https://www.britannica.com/technology/heat-engine", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book%3A_Heat_and_Thermodynamics_(Tatum)/03%3A_The_Second_Law_of_Thermodynamics/3.05%3A_Heat_Engines", "https://www.khanacademy.org/science/physics/work-and-energy/work-and-energy-tutorial/a/heat-engines"]'),
  ('heat_engine_work', '{"en-us": "Work done by a heat engine"}', 'heat_engines', 6, '{"en-us": "By the first law of thermodynamics, the work output of a cyclic heat engine equals the heat absorbed from the high-temperature reservoir minus the heat rejected to the low-temperature reservoir. This is a direct consequence of energy conservation for any device that returns to its initial state after one complete cycle."}', '["https://en.wikipedia.org/wiki/Heat_engine", "https://en.wikipedia.org/wiki/Thermal_efficiency", "https://en.wikipedia.org/wiki/First_law_of_thermodynamics", "https://www.britannica.com/technology/heat-engine", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book%3A_Heat_and_Thermodynamics_(Tatum)/03%3A_The_Second_Law_of_Thermodynamics/3.04%3A_The_First_Law_Applied_to_Heat_Engines"]'),
  ('heat_flow_conduction_fourier', '{"en-us": "Fourier''s law of heat conduction"}', 'heat_transfer', 7, '{"en-us": "Fourier''s law of heat conduction states that the time rate of heat flow through a homogeneous material is proportional to the cross-sectional area, the temperature difference between the two sides, and the material''s thermal conductivity, and inversely proportional to the thickness of the material. It is a constitutive law for heat conduction under steady-state conditions and assumes the material is homogeneous and isotropic; a more general differential form uses the temperature gradient."}', '["https://en.wikipedia.org/wiki/Thermal_conduction", "https://en.wikipedia.org/wiki/Fourier%27s_law", "https://www.britannica.com/science/Fouriers-law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/01%3A_Temperature_and_Heat", "https://www.khanacademy.org/science/physics/work-and-energy/work-and-energy-tutorial/a/heat-transfer-conduction"]'),
  ('heat_transfer', '{"en-us": "Heat transfer by temperature change"}', 'heat', 4, '{"en-us": "The amount of heat transferred to or from an object equals the product of its mass, its specific heat capacity, and the change in its temperature. This is the sensible-heat relation used in calorimetry and process heating/cooling calculations, and it applies to substances whose specific heat can be treated as approximately constant over the temperature interval of interest."}', '["https://en.wikipedia.org/wiki/Specific_heat_capacity", "https://en.wikipedia.org/wiki/Heat_capacity", "https://en.wikipedia.org/wiki/Sensible_heat", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/02%3A_Temperature_and_Heat", "https://www.khanacademy.org/science/physics/thermodynamics/specific-heat-and-heat-of-fusion/v/specific-heat"]'),
  ('heat_transfer_conduction_thermal_resistance', '{"en-us": "Heat transfer by conduction (Fourier''s law)"}', 'heat_transfer', 7, '{"en-us": "Fourier''s law gives the rate of conductive heat transfer through a homogeneous slab of thickness L and cross-sectional area A as the product of thermal conductivity, area, and the temperature difference across the slab, divided by the thickness. It applies to one-dimensional, steady-state conduction without internal heat generation and is the thermal analog of Ohm''s law for an electrical resistor."}', '["https://en.wikipedia.org/wiki/Thermal_conduction", "https://en.wikipedia.org/wiki/Fourier%27s_law_of_heat_conduction", "https://en.wikipedia.org/wiki/Thermal_resistance", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/01%3A_Temperature_and_Heat", "https://www.khanacademy.org/science/physics/thermodynamics/specific-heat-and-heat-transfer/v/thermal-conduction"]'),
  ('heat_transfer_radiation_stefan_boltzmann', '{"en-us": "Radiative heat transfer (Stefan-Boltzmann)"}', 'heat_transfer', 7, '{"en-us": "The Stefan-Boltzmann law gives the thermal radiation power emitted by a surface of area A and emissivity ε as the product of ε, the Stefan-Boltzmann constant σ, the area, and the absolute temperature raised to the fourth power. It applies to grey bodies in local thermodynamic equilibrium, where emissivity captures the deviation from ideal black-body behavior."}', '["https://en.wikipedia.org/wiki/Stefan%E2%80%93Boltzmann_law", "https://en.wikipedia.org/wiki/Thermal_radiation", "https://en.wikipedia.org/wiki/Stefan%E2%80%93Boltzmann_constant", "https://phys.libretexts.org/Bookshelves/Thermodynamics_%26_Statistical_Mechanics/Heat_and_Thermodynamics_(Cengel_and_Boles)/12%3A_Radiation_Heat_Transfer", "https://www.khanacademy.org/science/physics/quantum-physics/photons/v/deriving-the-stefan-boltzmann-law"]'),
  ('heisenberg_uncertainty_energy_time', '{"en-us": "Heisenberg energy-time uncertainty principle"}', 'quantum_mechanics', 9, '{"en-us": "The energy-time uncertainty relation bounds the product of the uncertainty in the energy of a quantum state and the characteristic time interval over which that state evolves. A short-lived excited state therefore has a large energy width, which is the basis for the natural linewidth of spectral lines and the lifetime-broadening observed in particle decays and resonances."}', '["https://en.wikipedia.org/wiki/Uncertainty_principle", "https://en.wikipedia.org/wiki/Energy%E2%80%93time_uncertainty_relation", "https://en.wikipedia.org/wiki/Planck_constant", "https://phys.libretexts.org/Bookshelves/Quantum_Mechanics/Quantum_Mechanics_(I)/10%3A_Measurements_in_Quantum_Mechanics", "https://www.khanacademy.org/science/physics/quantum-physics/heisenberg-uncertainty-principle/v/energy-time-uncertainty-principle"]'),
  ('heisenberg_uncertainty_principle', '{"en-us": "Heisenberg uncertainty principle"}', 'quantum_mechanics', 8, '{"en-us": "The position-momentum Heisenberg uncertainty relation states that the product of the uncertainty in position and the uncertainty in momentum of a quantum particle is bounded below by a constant of order the reduced Planck constant. It reflects the non-commutativity of the position and momentum operators and is the formal expression of the wave-particle duality of matter."}', '["https://en.wikipedia.org/wiki/Uncertainty_principle", "https://en.wikipedia.org/wiki/Introduction_to_quantum_mechanics", "https://en.wikipedia.org/wiki/Position_and_momentum", "https://phys.libretexts.org/Bookshelves/Quantum_Mechanics/Quantum_Mechanics_(I)/10%3A_Measurements_in_Quantum_Mechanics", "https://www.khanacademy.org/science/physics/quantum-physics/heisenberg-uncertainty-principle/v/position-momentum-uncertainty"]'),
  ('henderson_hasselbalch', '{"en-us": "Henderson-Hasselbalch equation"}', 'acids_and_bases', 7, '{"en-us": "The Henderson-Hasselbalch equation relates the pH of a buffer solution to the acid dissociation constant of the weak acid and the ratio of the concentrations of its conjugate base and the acid itself. It is derived from the acid dissociation equilibrium and applies in the buffer region where the concentrations of conjugate base and acid are both larger than the dissociated hydrogen ion concentration."}', '["https://en.wikipedia.org/wiki/Henderson%E2%80%93Hasselbalch_equation", "https://en.wikipedia.org/wiki/Acid_dissociation_constant", "https://en.wikipedia.org/wiki/Buffer_solution", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Acids_and_Bases/Buffers/Henderson-Hasselbalch_Approximation", "https://www.khanacademy.org/science/biology/acids-bases-and-water/acids-and-bases/v/henderson-hasselbalch-equation"]'),
  ('henrys_law', '{"en-us": "Henry''s law"}', 'solutions', 7, '{"en-us": "Henry''s law states that at constant temperature, the amount (or concentration) of a dissolved gas in a liquid is directly proportional to the partial pressure of that gas above the liquid. The proportionality factor is Henry''s law constant, which depends on the gas, the solvent, and the temperature. The relation holds only for dilute solutions and gases that do not react chemically with the solvent; it underlies gas-solubility phenomena from carbonated beverages to decompression sickness in divers."}', '["https://en.wikipedia.org/wiki/Henry%27s_law", "https://www.britannica.com/science/Henrys-law", "https://en.wikipedia.org/wiki/William_Henry_(chemist)"]'),
  ('hesss_law_enthalpy', '{"en-us": "Hess''s law for enthalpy change"}', 'thermochemistry', 7, '{"en-us": "Hess''s law states that the total enthalpy change for a chemical reaction is independent of the pathway taken and equals the sum of the enthalpy changes of the individual steps. Because enthalpy is a state function, intermediate-step enthalpies can be added (with appropriate signs) to obtain the overall reaction enthalpy, which is the basis for tabulating and using standard enthalpies of formation."}', '["https://en.wikipedia.org/wiki/Hess%27s_law", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_-_The_Central_Science_(Brown_et_al.)/05%3A_Thermochemistry/5.06%3A_Hess''s_Law", "https://en.wikipedia.org/wiki/Enthalpy", "https://www.chemteam.info/Chem-History/Hess-1840.html"]'),
  ('hill_equation', '{"en-us": "Hill equation (cooperative binding)"}', 'biochemistry', 9, '{"en-us": "The Hill equation describes the cooperative binding of a ligand to a macromolecule with multiple binding sites. It gives the fractional occupancy (or normalized response) as a sigmoidal function of ligand concentration, with the Hill coefficient n measuring the degree of cooperativity: n > 1 indicates positive cooperativity, n = 1 reduces to noncooperative (Michaelis-Menten-like) binding, and n < 1 indicates negative cooperativity. Originally formulated by Archibald Hill in 1910 to model sigmoidal oxygen binding to haemoglobin, it is widely used in pharmacology and enzyme kinetics to construct dose-response curves."}', '["https://en.wikipedia.org/wiki/Hill_equation_(biochemistry)", "https://en.wikipedia.org/wiki/Cooperative_binding"]'),
  ('hookes_law', '{"en-us": "Hooke''s law"}', 'springs', 4, '{"en-us": "Hooke''s law states that the restoring force exerted by an ideal elastic spring is linearly proportional to its displacement from equilibrium, with the negative sign indicating the force acts opposite to the displacement. The proportionality constant k is the spring''s stiffness, and the law holds only for small deformations within the elastic limit; beyond that, real materials depart from linear behavior and may yield or break. It is the foundation of the simple harmonic oscillator and underlies devices from spring scales and manometers to balance wheels in mechanical clocks."}', '["https://en.wikipedia.org/wiki/Hooke%27s_law", "https://en.wikipedia.org/wiki/Robert_Hooke", "https://www.britannica.com/science/Hookes-law", "https://courses.lumenlearning.com/suny-physics/chapter/15-5-hookes-law/"]'),
  ('horizontal_line_equation', '{"en-us": "Horizontal line"}', 'equations', 2, '{"en-us": "A horizontal line in the Cartesian plane is the set of all points that share the same y-coordinate, so its equation simply states that y equals a constant. Geometrically, it is a line parallel to the x-axis at a fixed height b, with slope zero. Such lines arise as constant functions, as level curves of the form f(x,y)=b, and as the special case of the slope-intercept form y = mx + b with m = 0."}', '["https://en.wikipedia.org/wiki/Linear_equation", "https://en.wikipedia.org/wiki/Horizontal_line_test", "https://mathworld.wolfram.com/HorizontalLine.html"]'),
  ('hybridization_electron_groups', '{"en-us": "Hybridization electron groups"}', 'chemical_bonding', 6, '{"en-us": "The number of electron groups (also called the steric number) around a central atom equals the total count of bonded atoms (sigma-bonded groups) plus the number of non-bonding lone pairs on that atom. This sum determines the underlying electron-group geometry, which in turn fixes the hybridization of the central atom (sp, sp², sp³, sp³d, sp³d², etc.) and the predicted molecular shape by VSEPR. The relation is the basis for assigning hybridization and predicting the geometry of molecules and polyatomic ions."}', '["https://en.wikipedia.org/wiki/VSEPR_theory", "https://en.wikipedia.org/wiki/Orbital_hybridisation", "https://chem.libretexts.org/Bookshelves/General_Chemistry/General_Chemistry_Supplement_(Eames)/Molecular_Geometry_and_VSEPR", "https://www.khanacademy.org/science/organic-chemistry/genetics-chemistry-review/hybridization-and-hybrid-orbitals-a-review"]'),
  ('hydraulic_displacement', '{"en-us": "Hydraulic piston displacement relation"}', 'pascals_law', 5, '{"en-us": "In a hydraulic system based on Pascal''s principle, the incompressibility of the fluid requires the volume displaced by one piston to equal the volume gained by the other. Combined with equal pressure, this yields the mechanical advantage that makes hydraulic lifts, brakes, and presses possible."}', '["https://en.wikipedia.org/wiki/Pascal%27s_law", "https://en.wikipedia.org/wiki/Hydraulic_press", "https://www.physics.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.05%3A_Pascal%27s_Principle_and_Hydraulics", "https://www.britannica.com/science/Pascal-principle", "https://www.grc.nasa.gov/www/k-12/WindTunnel/Activities/Pascals_principle.html"]'),
  ('hydrogen_energy_levels', '{"en-us": "Hydrogen atom energy levels"}', 'atomic_physics', 8, '{"en-us": "The allowed bound-state energies of an electron in a hydrogen-like atom, derived in the Bohr model and confirmed by quantum mechanics. Levels are negative, with the ground state at -13.6 eV and successive levels approaching zero as n grows large; transitions between levels produce the hydrogen spectral series."}', '["https://en.wikipedia.org/wiki/Rydberg_constant", "https://en.wikipedia.org/wiki/Bohr_model", "https://en.wikipedia.org/wiki/Hydrogen_atom", "https://en.wikipedia.org/wiki/Hydrogen_spectral_series", "https://www.physics.libretexts.org/Bookshelves/Quantum_Mechanics/Quantum_Mechanics_(I)_(Dimitri_Karafotias)/03%3A_One_Dimensional_Potentials/3.04%3A_Hydrogen_Atom", "https://byjus.com/physics/bohr-model-of-hydrogen-atom/"]'),
  ('hydrostatic_pressure', '{"en-us": "Hydrostatic pressure"}', 'pressure', 5, '{"en-us": "The pressure at a depth within a static fluid, due to the weight of the overlying fluid column. Used in calculations for dams, barometers, fluid columns, and the variation of pressure with depth (often combined with atmospheric pressure to give the absolute pressure)."}', '["https://en.wikipedia.org/wiki/Hydrostatics", "https://en.wikipedia.org/wiki/Hydrostatic_pressure", "https://en.wikipedia.org/wiki/Pascal%27s_law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.03%3A_Hydrostatic_Pressure", "https://www.britannica.com/science/hydrostatics", "https://www.grc.nasa.gov/www/k-12/WindTunnel/Activities/hydrostatic.html"]'),
  ('hyperbola_asymptote_equation', '{"en-us": "Asymptote equation of a hyperbola"}', 'coordinate_geometry', 6, '{"en-us": "The straight line that the branches of a centered hyperbola approach at large distance, used to sketch the curve and to analyze its behavior at infinity. A standard hyperbola has two symmetric asymptotes passing through the center with slope determined by the ratio of the semi-conjugate to the semi-transverse axis."}', '["https://en.wikipedia.org/wiki/Hyperbola#Asymptotes", "https://math.libretexts.org/Bookshelves/Algebra/Intermediate_Algebra/Intermediate_Algebra_2e_(OpenStax)/12%3A_Conic_Sections/12.04%3A_The_Hyperbola", "https://www.khanacademy.org/math/algebra/x2f8bb11595b61c86:conic-sections/x2f8bb11595b61c86:hyperbola-equations/v/horizontal-hyperbola", "https://www.britannica.com/science/hyperbola", "https://byjus.com/maths/hyperbola/"]'),
  ('hyperbola_eccentricity', '{"en-us": "Eccentricity of a hyperbola"}', 'coordinate_geometry', 6, '{"en-us": "The eccentricity of a hyperbola, a dimensionless number greater than 1 that measures how open the curve is. It is defined in terms of the semi-transverse axis a and the semi-conjugate axis b and determines the focal distance c and the angle the asymptotes make with the major axis."}', '["https://en.wikipedia.org/wiki/Hyperbola#Eccentricity", "https://en.wikipedia.org/wiki/Eccentricity_(mathematics)", "https://math.libretexts.org/Bookshelves/Algebra/Intermediate_Algebra/Intermediate_Algebra_2e_(OpenStax)/12%3A_Conic_Sections/12.04%3A_The_Hyperbola", "https://www.cuemath.com/geometry/eccentricity-of-hyperbola/", "https://www.khanacademy.org/math/algebra/x2f8bb11595b61c86:conic-sections/x2f8bb11595b61c86:hyperbola-equations/v/horizontal-hyperbola"]'),
  ('hyperbola_standard_form', '{"en-us": "Standard equation of a hyperbola"}', 'coordinate_geometry', 6, '{"en-us": "The standard Cartesian form of a hyperbola centered at the origin with its transverse axis along the x-axis, where a is the semi-transverse axis and b is the semi-conjugate axis. Replacing x by (x-h) and y by (y-k) shifts the center to (h, k)."}', '["https://en.wikipedia.org/wiki/Hyperbola#Equation", "https://math.libretexts.org/Bookshelves/Algebra/Intermediate_Algebra/Intermediate_Algebra_2e_(OpenStax)/12%3A_Conic_Sections/12.04%3A_The_Hyperbola", "https://www.cuemath.com/geometry/hyperbola/", "https://www.khanacademy.org/math/algebra/x2f8bb11595b61c86:conic-sections/x2f8bb11595b61c86:hyperbola-equations/v/horizontal-hyperbola", "https://www.britannica.com/science/hyperbola"]'),
  ('ideal_gas_density', '{"en-us": "Density of an ideal gas"}', 'ideal_gases', 6, '{"en-us": "The density of an ideal gas is the mass per unit volume expressed in terms of pressure, molar mass, the gas constant, and absolute temperature. It is valid only for ideal gases at conditions where intermolecular forces and finite molecular size are negligible."}', '["https://en.wikipedia.org/wiki/Ideal_gas", "https://en.wikipedia.org/wiki/Density", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Properties_of_Gases/Gas_Density", "https://www.khanacademy.org/science/chemistry/gases-and-kinetic-molecular-theory", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book:_Thermodynamics_(Tatum)/04:_Ideal_Gases"]'),
  ('ideal_gas_law', '{"en-us": "Ideal gas law"}', 'ideal_gases', 5, '{"en-us": "The ideal gas law relates the pressure, volume, temperature, and amount of an ideal gas in a single equation of state. It is an extension of Boyle''s, Charles''s, and Avogadro''s laws and provides a good approximation for real gases at low density and high temperature."}', '["https://en.wikipedia.org/wiki/Ideal_gas_law", "https://www.khanacademy.org/science/chemistry/gases-and-kinetic-molecular-theory/v/the-ideal-gas-law", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Properties_of_Gases/The_Ideal_Gas_Law", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book:_Thermodynamics_(Tatum)/04:_Ideal_Gases", "https://www.britannica.com/science/ideal-gas-law"]'),
  ('ideal_gas_law_molecular', '{"en-us": "Ideal gas law (molecular form)"}', 'ideal_gases', 6, '{"en-us": "The molecular form of the ideal gas law expresses the relationship between macroscopic state variables in terms of the number of gas particles and the Boltzmann constant rather than the moles and gas constant. It is equivalent to the standard form since nR = Nk_B, and is often used in statistical mechanics."}', '["https://en.wikipedia.org/wiki/Ideal_gas_law", "https://en.wikipedia.org/wiki/Boltzmann_constant", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Properties_of_Gases/The_Ideal_Gas_Law", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book:_Thermodynamics_(Tatum)/04:_Ideal_Gases", "https://www.khanacademy.org/science/chemistry/gases-and-kinetic-molecular-theory/v/ideal-gas-law-equation"]'),
  ('ideal_gas_partial_pressure_mole_ratio', '{"en-us": "Partial pressure from mole ratio"}', 'ideal_gases', 5, '{"en-us": "Following Dalton''s law of partial pressures, the partial pressure of a component in an ideal gas mixture equals its mole fraction times the total pressure. This mole-ratio form is particularly convenient when the mole fraction can be measured more easily than the partial pressure directly."}', '["https://en.wikipedia.org/wiki/Partial_pressure", "https://en.wikipedia.org/wiki/Dalton%27s_law", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Properties_of_Gases/The_Ideal_Gas_Law", "https://www.khanacademy.org/science/chemistry/gases-and-kinetic-molecular-theory/v/daltons-law-of-partial-pressure", "https://www.britannica.com/science/partial-pressure"]'),
  ('ideal_gas_pressure_from_kinetic_theory', '{"en-us": "Pressure from kinetic theory"}', 'ideal_gases', 8, '{"en-us": "The kinetic theory expression for the pressure of an ideal gas relates pressure to the number of molecules, the molecular mass, the mean-square molecular speed, and the volume occupied. It provides the microscopic basis for the ideal gas law and shows that temperature is proportional to the average translational kinetic energy of the molecules."}', '["https://en.wikipedia.org/wiki/Kinetic_theory_of_gases", "https://www.britannica.com/science/kinetic-theory-of-gases", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book:_Thermodynamics_(Tatum)/04:_Ideal_Gases", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Properties_of_Gases/Kinetic_Theory_of_Gases", "https://www.khanacademy.org/science/chemistry/gases-and-kinetic-molecular-theory"]'),
  ('illuminance_formula', '{"en-us": "Illuminance from luminous flux and area"}', 'electromagnetic_waves', 7, '{"en-us": "Illuminance is the total luminous flux incident per unit area on a surface, weighted by the standard luminosity function so that it correlates with the perceived brightness to the human eye. It is measured in lux (lumens per square metre) and is widely used in lighting design and photography."}', '["https://en.wikipedia.org/wiki/Illuminance", "https://en.wikipedia.org/wiki/Luminous_flux", "https://www.britannica.com/science/illuminance", "https://phys.libretexts.org/Bookshelves/Optics", "https://www.engineeringtoolbox.com/light-level-rooms-d_708.html"]'),
  ('impact_force_impulse', '{"en-us": "Average impact force from momentum change"}', 'collisions', 6, '{"en-us": "The average force experienced by an object during a brief impact or collision equals its change in momentum divided by the duration of the contact, a direct consequence of the impulse-momentum theorem. This expression is useful for estimating peak loads in crashes, sports impacts, and protective-equipment design."}', '["https://en.wikipedia.org/wiki/Impulse_(physics)", "https://en.wikipedia.org/wiki/Collision", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/08%3A_Linear_Momentum_and_Collisions", "https://en.wikipedia.org/wiki/Impact_force"]'),
  ('impedance_rc_series', '{"en-us": "Impedance of a series RC circuit"}', 'circuits', 8, '{"en-us": "The impedance of a series combination of a resistor and a capacitor is the magnitude of the vector sum of the resistance and the (negative) capacitive reactance. This expression governs the magnitude of the AC current drawn from the source and underlies the cutoff frequency of an RC filter."}', '["https://en.wikipedia.org/wiki/Electrical_impedance", "https://en.wikipedia.org/wiki/RC_circuit", "https://en.wikipedia.org/wiki/Capacitive_reactance", "https://phys.libretexts.org/Bookshelves/College_Physics/Book%3A_College_Physics_2e_(OpenStax)/20%3A_Electric_Current_Resistance_and_Ohm''s_Law/20.05%3A_Alternating_Current_versus_Direct_Current"]'),
  ('impedance_rlc_series', '{"en-us": "Impedance of a series RLC circuit"}', 'circuits', 8, '{"en-us": "The impedance of a series combination of a resistor, inductor, and capacitor is the magnitude of the vector sum of the resistance and the net reactance. At resonance X_L equals X_C so the impedance collapses to R; off-resonance it grows with the reactance difference."}', '["https://en.wikipedia.org/wiki/Electrical_impedance", "https://en.wikipedia.org/wiki/RLC_circuit", "https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_2e_(OpenStax)/21%3A_Circuits_Bioelectricity_and_DC_Instruments/21.06%3A_RLC_Series_Circuits", "https://en.wikipedia.org/wiki/Reactance_(electronics)"]'),
  ('impulse_formula', '{"en-us": "Impulse"}', 'impulse', 5, '{"en-us": "In classical mechanics, impulse is the integral of force over the time during which it acts, so for a constant force it is simply the product of force and the time interval. Impulse equals the change in momentum of the body on which the force acts, the basis of the impulse-momentum theorem."}', '["https://en.wikipedia.org/wiki/Impulse_(physics)", "https://en.wikipedia.org/wiki/Momentum", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/08%3A_Linear_Momentum_and_Collisions/8.02%3A_Impulse_and_Collisions", "https://www.britannica.com/science/impulse-physics"]'),
  ('impulse_momentum_change_general', '{"en-us": "General impulse-momentum relation"}', 'impulse', 6, '{"en-us": "The impulse-momentum theorem states that the impulse delivered to an object equals its change in linear momentum. For a constant mass this links the average applied force and the contact time interval to the change in the body''s velocity."}', '["https://en.wikipedia.org/wiki/Impulse_(physics)", "https://en.wikipedia.org/wiki/Momentum", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/08%3A_Linear_Momentum_and_Collisions/8.02%3A_Impulse_and_Collisions", "https://www.britannica.com/science/impulse-physics"]'),
  ('impulse_momentum_change_specific', '{"en-us": "Impulse as momentum change"}', 'impulse', 5, '{"en-us": "For an object of constant mass, the impulse delivered to it equals the change in its linear momentum, allowing impulse to be computed directly from the difference of the final and initial velocities multiplied by the mass. This is the specific (constant-mass) form of the impulse-momentum theorem, often used to analyze collisions where the force varies rapidly over a short contact time."}', '["https://en.wikipedia.org/wiki/Impulse_(physics)", "https://en.wikipedia.org/wiki/Momentum", "https://en.wikipedia.org/wiki/Impulse%E2%80%93momentum_theorem", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/09%3A_Linear_Momentum_and_Collisions/9.02%3A_Impulse_and_Collisions"]'),
  ('impulse_momentum_theorem', '{"en-us": "Impulse-momentum theorem"}', 'impulse', 5, '{"en-us": "The impulse-momentum theorem states that the impulse delivered to an object equals its change in linear momentum. It is especially useful for analyzing forces that act over short time intervals, such as collisions, where integrating the rapidly varying force is impractical."}', '["https://en.wikipedia.org/wiki/Impulse_(physics)", "https://www.britannica.com/science/impulse-physics", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/09%3A_Linear_Momentum_and_Collisions", "https://openstax.org/books/university-physics-volume-1/pages/9-introduction"]'),
  ('index_hydrogen_deficiency_formula', '{"en-us": "Index of hydrogen deficiency (formula)"}', 'organic_chemistry', 7, '{"en-us": "The index of hydrogen deficiency (IHD), also called the degree of unsaturation, indicates the total number of rings and pi-bonds in a molecular formula. It is computed by comparing a molecule to a saturated acyclic hydrocarbon reference of the same number of carbons."}', '["https://en.wikipedia.org/wiki/Degree_of_unsaturation", "https://www.britannica.com/science/degree-of-unsaturation", "https://chem.libretexts.org/Bookshelves/Organic_Chemistry/Organic_Chemistry_I_(LibreTexts)/02%3A_Structural_Organic_Chemistry/2.2%3A_Degrees_of_Unsaturation", "https://www.chem.purdue.edu/courses/chm25500/notes/IHD_notes.pdf"]'),
  ('induced_emf_coil_rate_change', '{"en-us": "Induced EMF from rate of change of magnetic flux"}', 'electromagnetic_induction', 7, '{"en-us": "Faraday''s flux rule (Faraday-Lenz law) states that the electromotive force induced in a closed conducting loop equals the negative time-rate-of-change of the magnetic flux through the loop. The negative sign (Lenz''s law) ensures the induced emf opposes the change that produced it."}', '["https://en.wikipedia.org/wiki/Faraday%27s_law_of_induction", "https://en.wikipedia.org/wiki/Lenz%27s_law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/13%3A_Electromagnetic_Induction/13.01%3A_Faradays_Law", "https://www.britannica.com/science/Faradays-law-of-induction", "https://www.khanacademy.org/science/physics/magnetic-forces-and-magnetic-fields/magnetic-flux-faradays-law/a/what-is-faradays-law"]'),
  ('induced_emf_faraday_flux_change_rate', '{"en-us": "Faraday''s law with N turns"}', 'electromagnetic_induction', 7, '{"en-us": "For a tightly wound coil of N identical turns, the magnetic flux change through each turn adds, multiplying the induced emf by N. This is the working principle of transformers, generators, and induction coils."}', '["https://en.wikipedia.org/wiki/Faraday%27s_law_of_induction", "https://en.wikipedia.org/wiki/Lenz%27s_law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/13%3A_Electromagnetic_Induction/13.01%3A_Faradays_Law", "https://www.britannica.com/science/Faradays-law-of-induction", "https://www.khanacademy.org/science/physics/magnetic-forces-and-magnetic-fields/magnetic-flux-faradays-law/a/what-is-faradays-law"]'),
  ('induced_emf_inductor', '{"en-us": "EMF induced in an inductor"}', 'electromagnetic_induction', 7, '{"en-us": "The voltage induced across an inductor equals the negative of its inductance times the time-rate-of-change of current through it. This is the defining constitutive relation of an ideal inductor and reflects the fact that an inductor opposes any change in current."}', '["https://en.wikipedia.org/wiki/Inductor", "https://en.wikipedia.org/wiki/Lenz%27s_law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/14%3A_Inductance/14.02%3A_Self-Inductance_and_Inductors", "https://www.britannica.com/technology/inductor-electronics"]'),
  ('inductance_formula', '{"en-us": "Inductance definition"}', 'electromagnetic_induction', 7, '{"en-us": "Inductance is defined as the ratio of the magnetic flux linkage through a circuit to the current that produces it. It measures the ability of a circuit to store energy in a magnetic field and is measured in henries."}', '["https://en.wikipedia.org/wiki/Inductance", "https://en.wikipedia.org/wiki/Inductor", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/14%3A_Inductance/14.02%3A_Self-Inductance_and_Inductors", "https://www.britannica.com/technology/inductor-electronics"]'),
  ('inductance_parallel', '{"en-us": "Parallel combination of inductors"}', 'electromagnetic_induction', 7, '{"en-us": "For two non-coupled inductors connected in parallel, the equivalent inductance is the product of the individual inductances divided by their sum. This is the ''product over sum'' rule and applies only when there is no mutual coupling between the coils; mutual inductance terms must be added when magnetic fields link the two inductors."}', '["https://en.wikipedia.org/wiki/Series_and_parallel_circuits#Inductors_2", "https://en.wikipedia.org/wiki/Inductance", "https://www.khanacademy.org/science/electrical-engineering/ee-circuit-analysis-topic/ee-natural-and-step-response/ee-inductor-networks", "https://phys.libretexts.org/Bookshelves/Electricity_and_Magnetism/Electricity_(OpenStax)/14%3A_Electromagnetic_Induction/14.06%3A_Inductance", "https://www.electronics-tutorials.ws/inductor/parallel-inductors.html"]'),
  ('inductance_series', '{"en-us": "Series combination of inductors"}', 'electromagnetic_induction', 7, '{"en-us": "For non-coupled inductors connected in series, the equivalent inductance is the sum of the individual inductances, because the same current flows through every inductor and the total voltage is the sum of the individual voltage drops. The rule requires mutual inductance to be negligible; otherwise mutual-coupling terms appear in the expression."}', '["https://en.wikipedia.org/wiki/Series_and_parallel_circuits#Inductors", "https://en.wikipedia.org/wiki/Inductance", "https://www.khanacademy.org/science/electrical-engineering/ee-circuit-analysis-topic/ee-natural-and-step-response/ee-inductor-networks", "https://phys.libretexts.org/Bookshelves/Electricity_and_Magnetism/Electricity_(OpenStax)/14%3A_Electromagnetic_Induction/14.06%3A_Inductance", "https://www.electronics-tutorials.ws/inductor/series-inductors.html"]'),
  ('inductive_reactance', '{"en-us": "Inductive reactance"}', 'circuits', 7, '{"en-us": "Inductive reactance is the opposition that an inductor presents to alternating current. It is proportional to both the angular frequency and the inductance, increasing linearly with frequency. Inductive reactance stores energy in the magnetic field during part of each AC cycle and returns it during the next quarter cycle, so no net power is dissipated."}', '["https://en.wikipedia.org/wiki/Electrical_reactance#Inductive_reactance", "https://en.wikipedia.org/wiki/Inductance", "https://www.khanacademy.org/science/electrical-engineering/ee-circuit-analysis-topic/ee-ac-analysis/ee-reactance", "https://phys.libretexts.org/Bookshelves/Electricity_and_Magnetism/Electricity_(OpenStax)/15%3A_Alternating-Current_Circuits/15.03%3A_Simple_Alternating-Current_Circuits", "https://www.electronics-tutorials.ws/accircuits/ac-inductance.html"]'),
  ('inorganic_radius_ratio_rule', '{"en-us": "Ionic radius ratio for coordination"}', 'inorganic_chemistry', 9, '{"en-us": "The cation-anion radius ratio is the ratio of the radius of the cation to that of the surrounding anions in an ionic crystal. It is used as a first-approximation predictor of coordination number and polyhedral geometry, with each coordination number (3, 4, 6, 8, ...) corresponding to a characteristic minimum ratio below which the structure becomes unstable."}', '["https://en.wikipedia.org/wiki/Cation-anion_radius_ratio", "https://en.wikipedia.org/wiki/Pauling%27s_rules#First_rule:_the_radius_ratio_rule", "https://chem.libretexts.org/Bookshelves/Inorganic_Chemistry/Map%3A_Inorganic_Chemistry_(Housecroft_and_Sharpe)/6%3A_Structures_and_energetics_of_metallic_and_ionic_solids/6.7%3A_Ionic_radii_(r_of_MX_n)", "https://www.khanacademy.org/science/chemistry/atomic-structure-and-properties/introduction-to-the-periodic-table/v/ionic-radius-trends", "https://en.wikipedia.org/wiki/Ionic_radius"]'),
  ('inscribed_angle', '{"en-us": "Inscribed angle theorem"}', 'circles', 5, '{"en-us": "The inscribed angle theorem states that the measure of an angle inscribed in a circle is exactly half of the central angle that subtends the same arc. As a result, every inscribed angle that intercepts a given arc has the same measure, regardless of where its vertex lies on the circle. The corollary includes Thales'' theorem, that any angle inscribed in a semicircle is a right angle."}', '["https://en.wikipedia.org/wiki/Inscribed_angle", "https://mathworld.wolfram.com/InscribedAngle.html", "https://math.libretexts.org/Bookshelves/Geometry/Geometry_(OpenStax)/09%3A_Circles/9.04%3A_Inscribed_Angles", "https://www.khanacademy.org/math/geometry/hs-geo-circles/hs-geo-inscribed-angles/v/inscribed-angle-theorem", "https://www.cut-the-knot.org/pythagoras/Munching/inscribed.shtml"]'),
  ('integral_constant_multiple', '{"en-us": "Integral constant multiple rule"}', 'integrals', 6, '{"en-us": "The constant multiple rule for integration states that a constant factor can be moved outside the integral sign. This is a direct consequence of the linearity of integration. The rule requires c to be independent of the variable of integration; for functions or variable-dependent coefficients it does not apply."}', '["https://en.wikipedia.org/wiki/Integral#Linearity", "https://mathworld.wolfram.com/ConstantFactorRule.html", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/03%3A_Derivatives/3.04%3A_Differentiation_Rules", "https://www.khanacademy.org/math/integral-calculus/indefinite-integrals/antiderivative-rules/v/constant-multiple-rule", "https://en.wikipedia.org/wiki/Linearity_of_integration"]'),
  ('integral_cos', '{"en-us": "Integral of cosine"}', 'integrals', 6, '{"en-us": "The antiderivative (indefinite integral) of the cosine function is the sine function. It is one of the most basic trigonometric integrals and follows directly from the fact that the derivative of sine is cosine."}', '["https://en.wikipedia.org/wiki/Trigonometric_functions", "https://en.wikipedia.org/wiki/List_of_integrals_of_trigonometric_functions", "https://www.khanacademy.org/math/differential-calculus/dc-diff-intro/dc-antiderivatives/v/antiderivative-of-cosx", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/01%3A_Functions_and_Graphs/1.04%3A_Trigonometric_Functions"]'),
  ('integral_cot', '{"en-us": "Integral of cot x"}', 'integrals', 7, '{"en-us": "The antiderivative of the cotangent function is the natural logarithm of the absolute value of sine. The absolute value is required because the integrand is undefined where sine is zero, so the antiderivative must be defined throughout each interval of continuity."}', '["https://en.wikipedia.org/wiki/List_of_integrals_of_trigonometric_functions", "https://en.wikipedia.org/wiki/Cotangent", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/03%3A_Derivatives/3.05%3A_Derivatives_of_Trigonometric_Functions", "https://www.khanacademy.org/math/differential-calculus/dc-diff-intro/dc-antiderivatives/v/antiderivative-of-cotx"]'),
  ('integral_csc', '{"en-us": "Integral of csc x"}', 'integrals', 8, '{"en-us": "The antiderivative of the cosecant function is the natural logarithm of the absolute value of the tangent of half the angle. The absolute value is required because csc x is undefined where sin x equals zero."}', '["https://en.wikipedia.org/wiki/List_of_integrals_of_trigonometric_functions", "https://en.wikipedia.org/wiki/Cosecant", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/03%3A_Derivatives/3.05%3A_Derivatives_of_Trigonometric_Functions", "https://www.khanacademy.org/math/differential-calculus/dc-diff-intro/dc-antiderivatives/v/antiderivative-of-cscx"]'),
  ('integral_csc_cot', '{"en-us": "Integral of csc x cot x"}', 'integrals', 8, '{"en-us": "The antiderivative of csc x cot x is the negative cosecant. The result can be obtained by direct integration using the derivative of csc x, which equals -csc x cot x."}', '["https://en.wikipedia.org/wiki/List_of_integrals_of_trigonometric_functions", "https://en.wikipedia.org/wiki/Cosecant", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/03%3A_Derivatives/3.05%3A_Derivatives_of_Trigonometric_Functions", "https://www.khanacademy.org/math/differential-calculus/dc-diff-intro/dc-antiderivatives/v/antiderivative-of-cscx-cotx"]'),
  ('integral_csc_squared', '{"en-us": "Integral of csc² x"}', 'integrals', 7, '{"en-us": "The antiderivative of csc squared x is the negative cotangent. The result follows from the Pythagorean identity, since the derivative of cot x equals -csc² x."}', '["https://en.wikipedia.org/wiki/List_of_integrals_of_trigonometric_functions", "https://en.wikipedia.org/wiki/Cosecant", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/03%3A_Derivatives/3.05%3A_Derivatives_of_Trigonometric_Functions", "https://www.khanacademy.org/math/differential-calculus/dc-diff-intro/dc-antiderivatives/v/antiderivative-of-csc2x"]'),
  ('integral_definite_definition', '{"en-us": "Definite integral as area"}', 'integrals', 7, '{"en-us": "A definite integral represents the signed area under the curve of a function between two bounds. In the Riemann-sum formulation the area is approximated as a finite sum of rectangles whose heights are the function values and whose widths are the subinterval widths; the integral is the limit of such sums as the partition becomes finer."}', '["https://en.wikipedia.org/wiki/Integral", "https://en.wikipedia.org/wiki/Riemann_integral", "https://en.wikipedia.org/wiki/Riemann_sum", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/03%3A_Derivatives/3.07%3A_Integrals", "https://www.khanacademy.org/math/calculus-1/cs1-limits-and-continuity/cs1-the-squeeze-theorem/v/sigma-notation-sum"]'),
  ('integral_exp_base', '{"en-us": "Integral of base-a exponential"}', 'integrals', 7, '{"en-us": "The antiderivative of an exponential function a^x with base a > 0, a != 1. It is derived using the substitution that any a^x can be written as e^(x ln a) and then applying the chain rule in reverse. The constant of integration is conventionally appended in the result."}', '["https://en.wikipedia.org/wiki/Lists_of_integrals", "https://en.wikipedia.org/wiki/Antiderivative", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/05%3A_Integration/5.06%3A_Integrals_Involving_Exponential_and_Logarithmic_Functions", "https://en.wikipedia.org/wiki/List_of_integrals_of_exponential_functions", "https://en.wikipedia.org/wiki/Exponential_function", "https://mathworld.wolfram.com/ExponentialIntegral.html"]'),
  ('integral_exponential', '{"en-us": "Integral of Exponential"}', 'integrals', 7, '{"en-us": "The antiderivative of the natural exponential function e^x. The function e^x is its own derivative, so its integral is the same function (up to a constant of integration). This identity is foundational in calculus and is used wherever continuous exponential growth or decay arises."}', '["https://en.wikipedia.org/wiki/Antiderivative", "https://en.wikipedia.org/wiki/List_of_integrals_of_exponential_functions", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/05%3A_Integration/5.06%3A_Integrals_Involving_Exponential_and_Logarithmic_Functions", "https://en.wikipedia.org/wiki/Exponential_function", "https://mathworld.wolfram.com/ExponentialIntegral.html"]'),
  ('integral_exponential_ax', '{"en-us": "Integral of Exponential ax"}', 'integrals', 7, '{"en-us": "The antiderivative of e^(a x) for a constant nonzero coefficient a. It is most easily obtained via the substitution u = a x, after which the standard integral of e^u applies; a scaling factor 1/a then emerges from the differential du = a dx. This generalises the natural exponential rule to any constant scaling of the argument."}', '["https://en.wikipedia.org/wiki/Antiderivative", "https://en.wikipedia.org/wiki/List_of_integrals_of_exponential_functions", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/05%3A_Integration/5.06%3A_Integrals_Involving_Exponential_and_Logarithmic_Functions", "https://en.wikipedia.org/wiki/Exponential_function", "https://mathworld.wolfram.com/ExponentialIntegral.html"]'),
  ('integral_ln_x', '{"en-us": "Integral of Natural Log"}', 'integrals', 7, '{"en-us": "The antiderivative of the natural logarithm ln(x). It is typically derived by integration by parts, choosing u = ln(x) and dv = dx, which yields x ln(x) - x plus an arbitrary constant. The result is the standard starting point for many integrals involving logarithmic factors."}', '["https://en.wikipedia.org/wiki/Antiderivative", "https://en.wikipedia.org/wiki/List_of_integrals_of_logarithmic_functions", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/05%3A_Integration/5.06%3A_Integrals_Involving_Exponential_and_Logarithmic_Functions", "https://en.wikipedia.org/wiki/Natural_logarithm", "https://mathworld.wolfram.com/NaturalLogarithm.html"]'),
  ('integral_one_over_x', '{"en-us": "Integral of 1/x"}', 'integrals', 6, '{"en-us": "The antiderivative of the reciprocal function 1/x. Unlike most power functions, x^n integrates to x^(n+1)/(n+1), but the case n = -1 must be treated separately, yielding the natural logarithm. The absolute value is required so the result is valid on both sides of the singularity at x = 0."}', '["https://en.wikipedia.org/wiki/Antiderivative", "https://en.wikipedia.org/wiki/List_of_integrals_of_logarithmic_functions", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/05%3A_Integration/5.06%3A_Integrals_Involving_Exponential_and_Logarithmic_Functions", "https://en.wikipedia.org/wiki/Natural_logarithm", "https://www.khanacademy.org/math/integral-calculus/indefinite-integrals/antiderivative-rules/v/antiderivatives-and-indefinite-integrals"]'),
  ('integral_power_rule', '{"en-us": "Integral of x^n"}', 'integrals', 6, '{"en-us": "The power rule for integration: the antiderivative of x^n is x^(n+1)/(n+1), valid for any real n except n = -1 (which is handled by the logarithm rule). The exponent is increased by one and the result is divided by the new exponent. Combined with the constant multiple and sum rules, it lets one integrate any polynomial."}', '["https://en.wikipedia.org/wiki/Antiderivative", "https://en.wikipedia.org/wiki/Power_rule", "https://en.wikipedia.org/wiki/Lists_of_integrals", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/05%3A_Integration/5.04%3A_Integration_Formulas_and_the_Net_Change_Theorem", "https://www.khanacademy.org/math/integral-calculus/indefinite-integrals/antiderivative-rules/v/antiderivative-of-x-1", "https://mathworld.wolfram.com/PowerRule.html"]'),
  ('integral_reciprocal_diff_squares', '{"en-us": "Integral of 1/(a²-x²)"}', 'integrals', 8, '{"en-us": "The antiderivative of 1/(a²-x²) is a logarithm of the ratio (a+x)/(a-x), divided by 2a. The integrand is typically handled by partial fractions after factoring the difference of squares, and the result is defined on each open interval between the poles at x = ±a."}', '["https://en.wikipedia.org/wiki/Partial_fractions_in_integration", "https://en.wikipedia.org/wiki/Trigonometric_substitution", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/05%3A_Integration/5.5%3A_Substitution", "https://www.khanacademy.org/math/integral-calculus/ic-integration-techniques/ic-partial-fractions/v/partial-fraction-expansion-1", "https://tutorial.math.lamar.edu/classes/calcii/partialfractions.aspx"]'),
  ('integral_reciprocal_quadratic', '{"en-us": "Integral of 1/(a²+x²)"}', 'integrals', 8, '{"en-us": "The antiderivative of 1/(a²+x²) is the inverse tangent of x/a divided by a. This rule follows from the substitution x = a tan θ, which converts the sum of squares into a form whose integral evaluates directly to the arctangent."}', '["https://en.wikipedia.org/wiki/Trigonometric_substitution", "https://en.wikipedia.org/wiki/Inverse_trigonometric_functions", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/05%3A_Integration/5.5%3A_Substitution", "https://www.khanacademy.org/math/differential-calculus/dc-diff-intro/dc-basic-differentiation-rules/v/proof-of-derivative-of-arctan", "https://tutorial.math.lamar.edu/classes/calcii/trigsub.aspx"]'),
  ('integral_reciprocal_root_quadratic', '{"en-us": "Integral of 1/√(a²-x²)"}', 'integrals', 8, '{"en-us": "The antiderivative of 1/√(a²-x²) is arcsin(x/a). The result follows from the substitution x = a sin θ, which converts the radical expression into a constant under the square root and reduces the integrand to dθ."}', '["https://en.wikipedia.org/wiki/Trigonometric_substitution", "https://en.wikipedia.org/wiki/Inverse_trigonometric_functions", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/05%3A_Integration/5.5%3A_Substitution", "https://www.khanacademy.org/math/differential-calculus/dc-diff-intro/dc-basic-differentiation-rules/v/proof-of-derivative-of-arcsin", "https://tutorial.math.lamar.edu/classes/calcii/trigsub.aspx"]'),
  ('integral_sec', '{"en-us": "Integral of sec x"}', 'integrals', 8, '{"en-us": "The antiderivative of the secant function is a logarithm of a rational expression in sin x, multiplied by 1/2. It was first evaluated by James Gregory in 1668 and historically underpinned the construction of the Mercator projection."}', '["https://en.wikipedia.org/wiki/Integral_of_the_secant_function", "https://en.wikipedia.org/wiki/Secant_(trigonometry)", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/05%3A_Integration/5.5%3A_Substitution", "https://www.khanacademy.org/math/differential-calculus/dc-diff-intro/dc-antiderivatives/v/antiderivative-of-secx", "https://tutorial.math.lamar.edu/classes/calcii/hyperbolicfunctions.aspx"]'),
  ('integral_sec_squared', '{"en-us": "Integral of sec² x"}', 'integrals', 7, '{"en-us": "The antiderivative of sec² x is tan x, since the derivative of tangent is the secant squared. This identity is one of the most frequently used basic integration rules and arises whenever one differentiates or integrates trigonometric functions."}', '["https://en.wikipedia.org/wiki/List_of_integrals_of_trigonometric_functions", "https://en.wikipedia.org/wiki/Secant_(trigonometry)", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/03%3A_Derivatives/3.05%3A_Derivatives_of_Trigonometric_Functions", "https://www.khanacademy.org/math/differential-calculus/dc-diff-intro/dc-antiderivatives/v/antiderivative-of-sec2x"]'),
  ('integral_sec_tan', '{"en-us": "Integral of sec x tan x"}', 'integrals', 7, '{"en-us": "The antiderivative of sec x tan x is sec x, because the derivative of the secant function is exactly sec x tan x. This identity is the natural companion to the sec² integral and is widely applied in trigonometric integration."}', '["https://en.wikipedia.org/wiki/List_of_integrals_of_trigonometric_functions", "https://en.wikipedia.org/wiki/Secant_(trigonometry)", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/03%3A_Derivatives/3.05%3A_Derivatives_of_Trigonometric_Functions", "https://www.khanacademy.org/math/differential-calculus/dc-diff-intro/dc-antiderivatives/v/antiderivative-of-secx-tanx"]'),
  ('integral_sin', '{"en-us": "Integral of sine"}', 'integrals', 6, '{"en-us": "The antiderivative of the sine function. It is one of the basic integration results used together with the fundamental theorem of calculus to evaluate definite trigonometric integrals, and follows directly from differentiating cosine."}', '["https://en.wikipedia.org/wiki/List_of_integrals_of_trigonometric_functions", "https://en.wikipedia.org/wiki/Antiderivative", "https://en.wikipedia.org/wiki/Trigonometric_functions", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/05%3A_Integration/5.04%3A_Integration_Formulas_and_the_Net_Change_Theorem"]'),
  ('integral_sum_rule', '{"en-us": "Integral sum rule"}', 'integrals', 6, '{"en-us": "The sum rule (a property of linearity) for integration: the integral of a sum equals the sum of the integrals. It allows complex integrands to be split into easier pieces and is one of the first rules used when evaluating integrals."}', '["https://en.wikipedia.org/wiki/Integral#Properties", "https://en.wikipedia.org/wiki/Linearity_of_integration", "https://en.wikipedia.org/wiki/Fundamental_theorem_of_calculus", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/05%3A_Integration/5.04%3A_Integration_Formulas_and_the_Net_Change_Theorem"]'),
  ('integral_tan', '{"en-us": "Integral of tan x"}', 'integrals', 7, '{"en-us": "The antiderivative of the tangent function. Following the standard approach of writing tangent as sine over cosine, integration by substitution (u = cos x) gives the natural logarithm of the cosine, with a negative sign."}', '["https://en.wikipedia.org/wiki/List_of_integrals_of_trigonometric_functions", "https://en.wikipedia.org/wiki/Antiderivative", "https://en.wikipedia.org/wiki/Trigonometric_functions", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/05%3A_Integration/5.04%3A_Integration_Formulas_and_the_Net_Change_Theorem"]'),
  ('integrated_first_order', '{"en-us": "Integrated rate law (first order)"}', 'chemical_kinetics', 7, '{"en-us": "The integrated form of the first-order rate law. Obtained by integrating the differential form d[A]/dt = -k[A], it relates the concentration of a reactant at time t to its initial concentration and the rate constant. A plot of ln[A] versus t is linear with slope -k."}', '["https://en.wikipedia.org/wiki/Rate_equation", "https://en.wikipedia.org/wiki/Chemical_kinetics", "https://en.wikipedia.org/wiki/Order_of_reaction", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Kinetics/Reaction_Rates/First-Order_Reactions"]'),
  ('integration_by_parts', '{"en-us": "Integration by parts"}', 'integrals', 8, '{"en-us": "A fundamental technique in calculus that expresses the integral of a product of functions in terms of the product of one function and the antiderivative of the other. It is the integral analogue of the product rule and is used when direct integration of a product is not feasible."}', '["https://en.wikipedia.org/wiki/Integration_by_parts", "https://en.wikipedia.org/wiki/Product_rule", "https://en.wikipedia.org/wiki/Antiderivative", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/06%3A_Techniques_of_Integration/6.02%3A_Integration_by_Parts", "https://www.khanacademy.org/math/ap-calculus-bc/bc-integration-new/bc-8-2/v/integration-by-parts"]'),
  ('intercept_form_line', '{"en-us": "Intercept form of a line"}', 'equations', 4, '{"en-us": "The intercept form expresses the equation of a non-vertical, non-horizontal straight line in the Cartesian plane that crosses both coordinate axes, using the x- and y-intercepts as parameters. The form is convenient for reading the two axis-intersection points directly and for computing the area of the right triangle formed by the line and the axes. It is derived from the two-point form and applies only when neither intercept is zero, i.e. the line does not pass through the origin and is not parallel to either axis."}', '["https://en.wikipedia.org/wiki/Linear_equation#Intercept_form", "https://www.cuemath.com/geometry/intercept-form/", "https://en.wikipedia.org/wiki/Zero_of_a_function", "https://www.encyclopediaofmath.org/index.php?title=Linear_equation"]'),
  ('interference_constructive_thin_film', '{"en-us": "Thin film interference constructive (normal incidence)"}', 'interference', 8, '{"en-us": "For light at normal incidence on a thin film, constructive interference of the reflected beams occurs when twice the optical path through the film equals an integer number of wavelengths. This assumes no net phase shift on reflection; if a half-wavelength phase shift occurs at one boundary, the condition is shifted by a half-integer."}', '["https://en.wikipedia.org/wiki/Thin-film_interference", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/03%3A_Interference", "https://www.britannica.com/science/thin-film-interference", "https://opentextbc.ca/physicstestbook2/chapter/thin-film-interference/", "https://www.animations.physics.unsw.edu.au/jw/light/thin-film-interference.htm"]'),
  ('interference_destructive_path_difference', '{"en-us": "Destructive interference path difference"}', 'wave_interference', 7, '{"en-us": "Destructive interference between two coherent waves of equal amplitude occurs when their path difference is an odd half-multiple of the wavelength. This condition causes the two waves to be 180° out of phase, cancelling the resultant amplitude."}', '["https://en.wikipedia.org/wiki/Wave_interference", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/03%3A_Interference", "https://www.britannica.com/science/interference-physics", "https://byjus.com/physics/path-difference/", "https://opentextbc.ca/physicstestbook2/chapter/youngs-double-slit-experiment/"]'),
  ('internal_energy_ideal_gas', '{"en-us": "Internal energy of an ideal monatomic gas"}', 'ideal_gases', 7, '{"en-us": "For an ideal monatomic gas, the internal energy depends only on temperature, scaling linearly with the amount of substance. It follows from the kinetic theory that each translational degree of freedom contributes (1/2)k_BT per molecule, giving (3/2)nRT for three translational modes. Polyatomic gases with rotational and vibrational modes require additional terms."}', '["https://en.wikipedia.org/wiki/Ideal_gas", "https://en.wikipedia.org/wiki/Internal_energy", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/03%3A_The_Kinetic_Theory_of_Gases", "https://www.britannica.com/science/internal-energy", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Thermodynamics/Thermodynamic_Systems/Internal_Energy"]'),
  ('interquartile_range', '{"en-us": "Interquartile range"}', 'statistics', 5, '{"en-us": "The interquartile range is a measure of statistical dispersion, defined as the spread between the first and third quartiles of a dataset. It is more robust to outliers than the total range and is used to construct box plots, identify outliers via the 1.5×IQR rule, and indicate skewness in the data."}', '["https://en.wikipedia.org/wiki/Interquartile_range", "https://www.britannica.com/statistic/interquartile-range", "https://www.statisticshowto.com/probability-and-statistics/interquartile-range/", "https://mathworld.wolfram.com/InterquartileRange.html", "https://www.scribbr.com/statistics/interquartile-range/"]'),
  ('iodine_number', '{"en-us": "Iodine number of a fat"}', 'organic_chemistry', 8, '{"en-us": "The iodine number (or iodine value) is the mass of iodine in grams that is consumed by 100 grams of a chemical substance, and is a measure of the degree of unsaturation in fats, oils, and waxes. It is determined by reacting the sample with an excess of a halogen reagent such as Wijs solution and back-titrating the unreacted halogen."}', '["https://en.wikipedia.org/wiki/Iodine_value", "https://www.britannica.com/science/iodine-value", "https://lipidlibrary.aocs.org/resource-material/scientific-milestones-in-lipid-research/arthur-von-h%C3%BCbl-and-the-iodine-value", "https://www.sciencedirect.com/topics/chemistry/iodine-value", "https://chem.libretexts.org/Bookshelves/Organic_Chemistry/Organic_Chemistry_Lab_Techniques_(Nichols)/06%3A_Miscellaneous_Techniques/6.04%3A_Iodine_Value"]'),
  ('ionization_energy', '{"en-us": "Ionization Energy"}', 'periodic_table', 5, '{"en-us": "Ionization energy is the minimum energy required to remove the most loosely bound electron from a neutral gaseous atom, ion, or molecule. It is computed as the difference between the energy of the resulting positive ion and the energy of the neutral atom, and exhibits periodic trends across the periodic table."}', '["https://en.wikipedia.org/wiki/Ionization_energy", "https://www.britannica.com/science/ionization-energy", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Atomic_Properties/Ionization_Energy", "https://www.khanacademy.org/science/chemistry/periodic-table-trends-bonding/x3a1ef0c5da9b9e0a:periodic-table-trends/v/ionization-energy", "https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/09%3A_Electronic_Structure_of_Atoms/9.07%3A_Ionization_Energies"]'),
  ('ionization_energy_effective_charge', '{"en-us": "Ionization energy from nuclear charge"}', 'atomic_structure', 8, '{"en-us": "In a hydrogen-like approximation the ionization energy of an electron in the valence shell scales with the square of the effective nuclear charge it experiences, so heavier atoms tend to lose their outermost electron less readily. This relation underpins periodic trends in ionization energy across the periodic table."}', '["https://en.wikipedia.org/wiki/Effective_nuclear_charge", "https://chem.libretexts.org/Courses/Mount_Royal_University/Chem_1201/Unit_2._Periodic_Properties_of_the_Elements/2.05%3A_Effective_Nuclear_Charge", "https://en.wikipedia.org/wiki/Ionization_energy", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/Atomic_and_Molecular_Properties/Ionization_Energy"]'),
  ('irradiance_formula', '{"en-us": "Irradiance from power and area"}', 'electromagnetic_waves', 6, '{"en-us": "Irradiance is the radiant flux received by a surface per unit area, measured in watts per square metre. It is used throughout radiometry, photometry, and solar-energy engineering to characterize how strongly electromagnetic radiation illuminates a surface."}', '["https://en.wikipedia.org/wiki/Irradiance", "https://en.wikipedia.org/wiki/Solar_irradiance", "https://www.britannica.com/science/irradiance"]'),
  ('isothermal_work_gas', '{"en-us": "Isothermal work on ideal gas"}', 'first_law', 7, '{"en-us": "For an ideal gas undergoing a reversible isothermal expansion or compression, the work exchanged depends logarithmically on the ratio of the final to initial volume. Because the temperature is fixed, heat must flow in or out to keep the internal energy constant."}', '["https://en.wikipedia.org/wiki/Isothermal_process", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Thermodynamics/Thermodynamics_of_Chemical_Reactions/Isothermal_Expansion_Work_of_an_Ideal_Gas", "https://www.chemguide.co.uk/physical/entropy/isothermal.html", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Thermodynamics/15.04%3A_Work_done_during_Isothermal_Expansion"]'),
  ('isotope_notation_formula', '{"en-us": "Isotope notation"}', 'atomic_structure', 4, '{"en-us": "Isotope notation labels a specific nuclide by its mass number A (the total count of protons and neutrons in the nucleus), its atomic number Z (the proton count), and the element symbol E. Isotopes of the same element share Z but differ in neutron number N, so A = Z + N determines the nucleon composition."}', '["https://en.wikipedia.org/wiki/Mass_number", "https://en.wikipedia.org/wiki/Atomic_number", "https://en.wikipedia.org/wiki/Isotope", "https://en.wikipedia.org/wiki/Neutron_number", "https://education.jlab.org/qa/pen_number.html", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_-_The_Central_Science_(Brown_et_al.)/02%3A_Atoms_Molecules_and_Ions/2.03%3A_Atomic_Number_Mass_Number_and_Isotopes"]'),
  ('ka_kb_relation', '{"en-us": "Relationship between Ka and Kb"}', 'acids_and_bases', 7, '{"en-us": "For a conjugate acid–base pair in aqueous solution, the product of the acid dissociation constant K_a and the base dissociation constant K_b equals the ion product of water K_w. This relation implies that a stronger acid has a weaker conjugate base, and equivalently pK_a + pK_b = pK_w at 25 °C."}', '["https://en.wikipedia.org/wiki/Acid_dissociation_constant", "https://en.wikipedia.org/wiki/Self-ionization_of_water", "https://en.wikipedia.org/wiki/Base_dissociation_constant", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Acids_and_Bases/Ionization_Constants", "https://www.chemguide.co.uk/physical/acidbaseeqia/kakb.html", "https://www.khanacademy.org/science/chemistry/acids-and-bases-topic/acids-and-bases/a/ka-and-kb"]'),
  ('kelvin_planck_statement', '{"en-us": "Second law: Kelvin-Planck statement"}', 'second_law', 8, '{"en-us": "It is impossible to construct a device that, operating in a thermodynamic cycle, converts heat absorbed from a single thermal reservoir entirely into work. Every cyclic heat engine must reject some heat to a lower-temperature sink, ruling out a perpetual-motion machine of the second kind."}', '["https://en.wikipedia.org/wiki/Second_law_of_thermodynamics", "https://en.wikipedia.org/wiki/Heat_engine", "https://en.wikipedia.org/wiki/Thermal_efficiency", "https://www.britannica.com/science/second-law-of-thermodynamics", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book%3A_Heat_and_Thermodynamics_(Tatum)/03%3A_The_Second_Law_of_Thermodynamics/3.02%3A_Kelvin%E2%80%93Planck_and_Clausius_Statements", "https://courses.lumenlearning.com/suny-physics/chapter/15-5-the-second-law-of-thermodynamics/"]'),
  ('kepler_first_law_ellipse', '{"en-us": "Kepler''s first law (elliptical orbit)"}', 'orbital_motion', 6, '{"en-us": "Kepler''s first law states that every planet moves in an elliptical orbit with the Sun at one of the two foci. The polar form of the ellipse equation gives the orbital radius as a function of the true anomaly, parameterized by the semi-major axis and orbital eccentricity."}', '["https://en.wikipedia.org/wiki/Kepler%27s_laws_of_planetary_motion", "https://en.wikipedia.org/wiki/Kepler_orbit", "https://en.wikipedia.org/wiki/Orbital_period", "https://en.wikipedia.org/wiki/Ellipse"]'),
  ('kepler_second_law', '{"en-us": "Kepler''s second law (areal velocity)"}', 'orbital_motion', 7, '{"en-us": "Kepler''s second law states that a line joining a planet to the Sun sweeps out equal areas in equal times, so the areal velocity is constant. Equivalently, the law is a direct consequence of conservation of angular momentum for motion under any central (radially directed) force."}', '["https://en.wikipedia.org/wiki/Kepler%27s_laws_of_planetary_motion", "https://en.wikipedia.org/wiki/Areal_velocity", "https://en.wikipedia.org/wiki/Angular_momentum", "https://en.wikipedia.org/wiki/Conservation_of_angular_momentum"]'),
  ('keplers_first_law', '{"en-us": "Kepler''s first law of planetary motion"}', 'orbital_motion', 6, '{"en-us": "Kepler''s first law of planetary motion states that every planet''s orbit is an ellipse with the Sun at one focus. The polar form of the ellipse gives the orbital radius in terms of the semi-major axis, eccentricity, and true anomaly."}', '["https://en.wikipedia.org/wiki/Kepler%27s_laws_of_planetary_motion", "https://en.wikipedia.org/wiki/Kepler_orbit", "https://en.wikipedia.org/wiki/Orbital_period", "https://en.wikipedia.org/wiki/Ellipse"]'),
  ('keplers_third_law', '{"en-us": "Kepler''s third law"}', 'orbital_motion', 6, '{"en-us": "Kepler''s third law states that the square of a planet''s orbital period is proportional to the cube of the semi-major axis of its orbit. In its Newtonian form it relates the period to the mass of the central body and the gravitational constant, and underlies calculations of planetary and satellite orbits."}', '["https://en.wikipedia.org/wiki/Kepler%27s_laws_of_planetary_motion", "https://en.wikipedia.org/wiki/Orbital_period", "https://en.wikipedia.org/wiki/Kepler_orbit", "https://en.wikipedia.org/wiki/Newton%27s_law_of_universal_gravitation"]'),
  ('kinetic_energy_center_of_mass', '{"en-us": "Kinetic energy of center of mass"}', 'kinetic_energy', 6, '{"en-us": "The total kinetic energy of a system of particles decomposes into the kinetic energy of the center of mass plus the kinetic energy of the motion of the particles relative to the center of mass. This separation, sometimes known as Křiženecký''s theorem or König''s theorem, makes it convenient to treat a many-body system as a single point mass at the CM for translational dynamics."}', '["https://en.wikipedia.org/wiki/Kinetic_energy", "https://en.wikipedia.org/wiki/Center_of_mass", "https://en.wikipedia.org/wiki/Koenig%27s_theorem_(kinetics)"]'),
  ('kinetic_energy_definition_work', '{"en-us": "Kinetic energy from work done"}', 'kinetic_energy', 5, '{"en-us": "The work-energy theorem states that the net work done by the resultant force on a body equals its change in kinetic energy. For a constant net force along the displacement, this work equals the product of the force magnitude and the displacement."}', '["https://en.wikipedia.org/wiki/Kinetic_energy", "https://en.wikipedia.org/wiki/Work_(physics)", "https://en.wikipedia.org/wiki/Work%E2%80%93energy_principle", "https://en.wikipedia.org/wiki/Mechanical_work"]'),
  ('kinetic_energy_formula', '{"en-us": "Kinetic energy"}', 'kinetic_energy', 4, '{"en-us": "Kinetic energy is the energy a body possesses by virtue of its motion. For a non-rotating object of mass m moving at speed v, the kinetic energy is one-half the product of the mass and the square of the speed, valid for speeds much less than the speed of light (Newtonian regime)."}', '["https://en.wikipedia.org/wiki/Kinetic_energy", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/07%3A_Work_and_Kinetic_Energy/7.03%3A_Kinetic_Energy", "https://www.britannica.com/science/kinetic-energy"]'),
  ('kinetic_energy_momentum', '{"en-us": "Kinetic energy from momentum"}', 'kinetic_energy', 6, '{"en-us": "Kinetic energy can be expressed directly in terms of an object''s momentum p and its mass m. This form is useful when momentum is the natural variable, such as in collision analysis and in relativistic mechanics where v may be inconvenient."}', '["https://en.wikipedia.org/wiki/Kinetic_energy", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/07%3A_Work_and_Kinetic_Energy/7.03%3A_Kinetic_Energy", "https://www.britannica.com/science/kinetic-energy"]'),
  ('kinetic_energy_translational_ideal_gas', '{"en-us": "Translational kinetic energy of an ideal gas"}', 'ideal_gases', 7, '{"en-us": "The total translational kinetic energy of an ideal gas depends only on its amount of substance n and its absolute temperature T. Per molecule the average translational kinetic energy is three halves k_B T; for n moles, multiplying by Avogadro''s number gives the same expression with the gas constant R."}', '["https://en.wikipedia.org/wiki/Kinetic_theory_of_gases", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/02%3A_Vectors/2.06%3A_Ideal_Gas_Law", "https://www.britannica.com/science/kinetic-theory-of-gases"]'),
  ('kirchhoff_current_law', '{"en-us": "Kirchhoff''s current law"}', 'circuits', 6, '{"en-us": "Kirchhoff''s current law (the junction rule) states that the algebraic sum of currents flowing into any node of an electrical circuit equals the sum flowing out. It is a consequence of conservation of electric charge and holds for lumped-element models."}', '["https://en.wikipedia.org/wiki/Kirchhoff%27s_circuit_laws", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/10%3A_Direct-Current_Circuits/10.03%3A_Kirchhoff%27s_Rules", "https://www.khanacademy.org/science/physics/circuits-topic/circuits-with-resistors/a/kirchhoffs-voltage-law"]'),
  ('kirchhoff_voltage_law', '{"en-us": "Kirchhoff''s voltage law"}', 'circuits', 6, '{"en-us": "Kirchhoff''s voltage law (the loop rule) states that the directed sum of the potential differences around any closed loop in a circuit is zero. It follows from the conservative nature of the electrostatic field in the lumped-circuit approximation."}', '["https://en.wikipedia.org/wiki/Kirchhoff%27s_circuit_laws", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/10%3A_Direct-Current_Circuits/10.03%3A_Kirchhoff%27s_Rules", "https://www.khanacademy.org/science/physics/circuits-topic/circuits-with-resistors/a/kirchhoffs-voltage-law"]'),
  ('kohlrausch_law', '{"en-us": "Kohlrausch''s law of independent migration"}', 'electrochemistry', 9, '{"en-us": "Kohlrausch''s law of independent migration of ions states that at infinite dilution the limiting molar conductivity of an electrolyte equals the sum of the limiting molar ionic conductivities of its cation and anion, each multiplied by the number of such ions in the formula unit. The contributions of different ions are additive and independent of the partner ion."}', '["https://en.wikipedia.org/wiki/Kohlrausch%27s_law", "https://en.wikipedia.org/wiki/Molar_conductivity", "https://en.wikipedia.org/wiki/Friedrich_Kohlrausch_(physicist)"]'),
  ('kp_kc_relation', '{"en-us": "Relationship between Kp and Kc"}', 'chemical_equilibrium', 7, '{"en-us": "Relates the pressure-based equilibrium constant Kp to the concentration-based equilibrium constant Kc for a gas-phase reaction. The exponent Δn is the change in the number of moles of gas between products and reactants, so the conversion factor depends on temperature and the stoichiometry of the gaseous species."}', '["https://en.wikipedia.org/wiki/Equilibrium_constant", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Equilibria/Chemical_Equilibria/The_Equilibrium_Constant", "https://www.khanacademy.org/science/chemistry/chemical-equilibrium", "https://www.chem.purdue.edu/chemed/Common/chemical_equil.html", "https://www.britannica.com/science/equilibrium-constant"]'),
  ('larmor_frequency', '{"en-us": "Larmor precession frequency"}', 'magnetism', 9, '{"en-us": "Gives the angular frequency at which the magnetic moment of a particle (such as an electron or nucleus) precesses about an external magnetic field. It is central to nuclear magnetic resonance, electron paramagnetic resonance, and magnetic resonance imaging, and depends only on the field magnitude and the particle''s gyromagnetic ratio, not on the orientation of the moment."}', '["https://en.wikipedia.org/wiki/Larmor_precession", "https://en.wikipedia.org/wiki/Gyromagnetic_ratio", "http://hyperphysics.phy-astr.gsu.edu/hbase/nuclear/larmor.html", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Spectroscopy/Magnetic_Resonance_Spectroscopies/Nuclear_Magnetic_Resonance_Theory", "https://www.britannica.com/science/Larmor-precession"]'),
  ('latent_heat', '{"en-us": "Latent heat"}', 'heat', 5, '{"en-us": "Relates the energy absorbed or released during a phase change (such as melting, freezing, or vaporization) to the mass of the substance and its specific latent heat. The temperature of the substance stays constant throughout the phase change, so the energy goes entirely into breaking or forming intermolecular bonds rather than raising the temperature."}', '["https://en.wikipedia.org/wiki/Latent_heat", "https://en.wikipedia.org/wiki/Enthalpy_of_fusion", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Thermodynamics/Energies_and_Potentials_of_Interaction/Enthalpy_of_Fusion", "https://www.britannica.com/science/latent-heat", "https://www.khanacademy.org/science/physics/thermodynamics/specific-heat-and-latent-heat"]'),
  ('lateral_surface_area_cone', '{"en-us": "Lateral surface area of a cone"}', 'plane_geometry', 4, '{"en-us": "Gives the curved surface area of a right circular cone, excluding its circular base. It is the product of the base radius, the slant height, and π, and is equivalent to the area of a circular sector of radius equal to the slant height and arc length equal to the base circumference."}', '["https://en.wikipedia.org/wiki/Cone", "https://mathworld.wolfram.com/Cone.html", "https://www.khanacademy.org/math/geometry/hs-geo-solids/hs-geo-solids-intro/v/surface-area-of-a-cone", "https://www.britannica.com/science/cone-mathematics", "https://math.libretexts.org/Bookshelves/Geometry/Geometry_(Topic_Review)/3%3A_3D_Geometry/3.02%3A_Surface_Area_of_Cone_Pyramid_and_Sphere"]'),
  ('lateral_surface_area_cylinder', '{"en-us": "Lateral surface area of a cylinder"}', 'plane_geometry', 3, '{"en-us": "Gives the curved (side) surface area of a right circular cylinder, excluding its two circular bases. It is the product of the circumference of the base and the height, and is equivalent to unrolling the lateral surface into a rectangle of width equal to the height and length equal to the circumference."}', '["https://en.wikipedia.org/wiki/Cylinder", "https://mathworld.wolfram.com/Cylinder.html", "https://www.khanacademy.org/math/geometry/hs-geo-solids/hs-geo-solids-intro/v/surface-area-of-a-cylinder", "https://www.britannica.com/science/cylinder", "https://math.libretexts.org/Bookshelves/Geometry/Geometry_(Topic_Review)/3%3A_3D_Geometry/3.01%3A_Surface_Area_of_Prisms_and_Cylinders"]'),
  ('lattice_energy_born_lande', '{"en-us": "Born-Landé lattice energy equation"}', 'inorganic_chemistry', 10, '{"en-us": "Calculates the lattice energy of an ionic crystal from the Madelung constant (set by the lattice geometry), the ionic charges, the nearest-neighbor distance, and the Born exponent (set by the electron configurations of the ions). The factor (1 − 1/n) accounts for short-range repulsion between ions, reducing the purely electrostatic Madelung energy by a small amount."}', '["https://en.wikipedia.org/wiki/Born%E2%80%93Land%C3%A9_equation", "https://en.wikipedia.org/wiki/Lattice_energy", "https://en.wikipedia.org/wiki/Madelung_constant", "https://chem.libretexts.org/Bookshelves/Inorganic_Chemistry/Inorganic_Chemistry_(LibreTexts)/06%3A_Properties_of_Solids/6.04%3A_Lattice_Energy", "https://www.britannica.com/science/lattice-energy", "https://www.chemguide.co.uk/physical/energetics/lattice.html"]'),
  ('lattice_energy_coulomb', '{"en-us": "Coulombic contribution to lattice energy"}', 'inorganic_chemistry', 9, '{"en-us": "This is the purely Coulombic (Madelung) contribution to the lattice energy of an ionic crystal, summing the electrostatic interaction of every ion with all the others via the Madelung constant, which encodes the geometry of the lattice. It forms the attractive component of the Born-Landé equation, paired with a short-range repulsive term to yield the equilibrium lattice energy."}', '["https://en.wikipedia.org/wiki/Born%E2%80%93Land%C3%A9_equation", "https://en.wikipedia.org/wiki/Madelung_constant", "https://chem.libretexts.org/Bookshelves/Inorganic_Chemistry/Supplemental_Modules_and_Websites_(Inorganic_Chemistry)/Crystal_Lattices/Thermodynamics_of_Lattices/Lattice_Energy", "https://en.wikipedia.org/wiki/Lattice_energy", "https://chem.libretexts.org/Bookshelves/Inorganic_Chemistry/Map%3A_Inorganic_Chemistry_(Housecroft)/06%3A_Structures_and_Energetics_of_Metallic_and_Ionic_solids/6.13%3A_Lattice_Energy_-_Estimates_from_an_Electrostatic_Model"]'),
  ('law_of_cosines', '{"en-us": "Law of cosines"}', 'laws_of_sines_and_cosines', 5, '{"en-us": "The law of cosines generalizes the Pythagorean theorem to all triangles, relating the lengths of the three sides to the cosine of one of the included angles. It is used to solve a triangle when two sides and the included angle (SAS) or all three sides (SSS) are known, and reduces to the Pythagorean relation when the included angle is a right angle."}', '["https://en.wikipedia.org/wiki/Law_of_cosines", "https://www.britannica.com/science/law-of-cosines", "https://www.mathsisfun.com/algebra/trig-cosine-law.html", "https://math.libretexts.org/Bookshelves/Precalculus/Elementary_Trigonometry_(Corral)/02%3A_General_Triangles/2.02%3A_The_Law_of_Cosines", "https://louis.pressbooks.pub/trigonometry/chapter/3-3-the-law-of-cosines/"]'),
  ('law_of_cosines_angle', '{"en-us": "Law of cosines for angle"}', 'laws_of_sines_and_cosines', 5, '{"en-us": "This rearrangement of the law of cosines solves for an unknown angle of a triangle when all three side lengths are known. Taking the inverse cosine of the rearranged expression avoids the angle ambiguity that arises when using the law of sines, since cosine distinguishes acute from obtuse angles by sign."}', '["https://en.wikipedia.org/wiki/Law_of_cosines", "https://www.britannica.com/science/law-of-cosines", "https://www.mathsisfun.com/algebra/trig-cosine-law.html", "https://math.libretexts.org/Bookshelves/Precalculus/Elementary_Trigonometry_(Corral)/02%3A_General_Triangles/2.02%3A_The_Law_of_Cosines", "https://louis.pressbooks.pub/trigonometry/chapter/3-3-the-law-of-cosines/"]'),
  ('law_of_cosines_angle_rearranged', '{"en-us": "Law of cosines rearranged for angle"}', 'laws_of_sines_and_cosines', 5, '{"en-us": "An equivalent form of the law of cosines solved for the cosine of an unknown angle. This form is convenient because cosine is sign-sensitive, distinguishing acute from obtuse angles without ambiguity, in contrast to the law of sines."}', '["https://en.wikipedia.org/wiki/Law_of_cosines", "https://www.britannica.com/science/law-of-cosines", "https://www.mathsisfun.com/algebra/trig-cosine-law.html", "https://math.libretexts.org/Bookshelves/Precalculus/Elementary_Trigonometry_(Corral)/02%3A_General_Triangles/2.02%3A_The_Law_of_Cosines", "https://louis.pressbooks.pub/trigonometry/chapter/3-3-the-law-of-cosines/"]'),
  ('law_of_sines', '{"en-us": "Law of sines"}', 'laws_of_sines_and_cosines', 5, '{"en-us": "The law of sines relates the side lengths of a triangle to the sines of their opposite angles. It is used for triangulation when two angles and a side (AAS/ASA) or two sides and a non-included angle (the ambiguous SSA case) are known, and the common ratio equals the diameter of the triangle''s circumscribed circle."}', '["https://en.wikipedia.org/wiki/Law_of_sines", "https://www.britannica.com/science/law-of-sines", "https://www.mathsisfun.com/algebra/trig-sine-law.html", "https://math.libretexts.org/Bookshelves/Precalculus/Elementary_Trigonometry_(Corral)/02%3A_General_Triangles/2.01%3A_The_Law_of_Sines", "https://louis.pressbooks.pub/trigonometry/chapter/3-2-the-law-of-sines/"]'),
  ('law_of_sines_angle_sum', '{"en-us": "Law of sines side ratio"}', 'laws_of_sines_and_cosines', 5, '{"en-us": "The full form of the law of sines expresses all three side-length-to-opposite-angle-sine ratios at once, making it clear that each ratio is equal to a common constant equal to the diameter of the triangle''s circumscribed circle. This is the form most often quoted in textbooks and used in derivations."}', '["https://en.wikipedia.org/wiki/Law_of_sines", "https://www.britannica.com/science/law-of-sines", "https://www.mathsisfun.com/algebra/trig-sine-law.html", "https://math.libretexts.org/Bookshelves/Precalculus/Elementary_Trigonometry_(Corral)/02%3A_General_Triangles/2.01%3A_The_Law_of_Sines", "https://louis.pressbooks.pub/trigonometry/chapter/3-2-the-law-of-sines/"]'),
  ('law_of_sines_circumradius', '{"en-us": "Law of sines with circumradius"}', 'laws_of_sines_and_cosines', 6, '{"en-us": "The law of sines states that in any triangle the ratio of each side to the sine of its opposite angle is constant, and this common value equals the diameter of the triangle''s circumscribed circle. It is used to compute unknown sides or angles in triangulation and surveying problems, with an ambiguous case when two sides and a non-included angle are given."}', '["https://en.wikipedia.org/wiki/Law_of_sines", "https://mathworld.wolfram.com/LawofSines.html", "https://www.cuemath.com/geometry/law-of-sines/", "https://www.britannica.com/science/law-of-sines", "https://math.libretexts.org/Bookshelves/Trigonometry/Trigonometry_(Lumen)/09%3A_Additional_Topics/9.01%3A_Law_of_Sines"]'),
  ('law_of_tangents', '{"en-us": "Law of tangents"}', 'laws_of_sines_and_cosines', 7, '{"en-us": "The law of tangents relates the tangent of half the sum and difference of two angles of a triangle to the corresponding opposite side lengths. Historically useful before calculators for solving triangles from two sides and the included angle, since it avoids the square root needed by the law of cosines and offers better numerical stability when two sides are nearly equal."}', '["https://en.wikipedia.org/wiki/Law_of_tangents", "https://mathworld.wolfram.com/LawofTangents.html", "https://math.libretexts.org/Bookshelves/Trigonometry/Trigonometry_(Lumen)/09%3A_Additional_Topics/9.04%3A_Law_of_Tangents", "https://www.cuemath.com/trigonometry/law-of-tangents/", "https://www.britannica.com/science/law-of-tangents"]'),
  ('law_of_total_probability', '{"en-us": "Law of total probability"}', 'probability', 7, '{"en-us": "The law of total probability expresses the marginal probability of an event as a weighted sum of its conditional probabilities over a partition of mutually exclusive and exhaustive events. It is a fundamental tool used together with Bayes'' theorem to update probabilities in hierarchical or partitioned sampling situations."}', '["https://en.wikipedia.org/wiki/Law_of_total_probability", "https://mathworld.wolfram.com/TotalProbabilityTheorem.html", "https://www.britannica.com/science/law-of-total-probability", "https://www.probabilitycourse.com/chapter1/1_4_2_total_probability.php", "https://stats.libretexts.org/Bookshelves/Probability_Theory/Probability_Models/05%3A_Important_Distributions_and_Density_Functions/5.02%3A_Law_of_Total_Probability"]'),
  ('laws_of_sines_projection_formula', '{"en-us": "Triangle side projection formula"}', 'laws_of_sines_and_cosines', 6, '{"en-us": "The projection formula expresses one side of a triangle as the sum of the projections of the other two sides onto it, using the cosine of the adjacent angles. It is a useful rearrangement of the law of cosines that connects sides and angles in a single linear relationship."}', '["https://en.wikipedia.org/wiki/Law_of_cosines", "https://mathworld.wolfram.com/LawofCosines.html", "https://www.cuemath.com/geometry/projection-formula/", "https://www.britannica.com/science/law-of-cosines", "https://math.libretexts.org/Bookshelves/Trigonometry/Trigonometry_(Lumen)/09%3A_Additional_Topics/9.03%3A_Law_of_Cosines"]'),
  ('lc_resonance', '{"en-us": "LC circuit resonance frequency"}', 'electromagnetic_induction', 7, '{"en-us": "An LC circuit consisting of an inductor and a capacitor oscillates at a resonant angular frequency determined by the inductance and capacitance. It is the basic electrical analogue of a harmonic oscillator and forms the building block of radio tuners, filters, and oscillators."}', '["https://en.wikipedia.org/wiki/LC_circuit", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/14%3A_Electromagnetic_Induction/14.06%3A_Reactance_Inductive_and_Capacitive", "https://www.britannica.com/technology/tuned-circuit", "https://www.electronics-tutorials.ws/accircuits/rlc-circuit.html", "https://www.allaboutcircuits.com/technical-articles/lc-natural-frequency/"]'),
  ('lens_magnification', '{"en-us": "Lens Magnification"}', 'lenses', 5, '{"en-us": "The transverse magnification of a thin lens equals the ratio of image distance to object distance, with a sign indicating whether the image is upright or inverted relative to the object. It is fundamental to image formation in cameras, microscopes, telescopes, and the human eye."}', '["https://en.wikipedia.org/wiki/Magnification", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_(OpenStax)/02%3A_Geometric_Optics_and_Image_Formation/2.06%3A_Thin_Lenses", "https://www.britannica.com/technology/magnification", "https://www.physics.lensless.org/notes/thin-lenses", "https://www.electronics-tutorials.ws/optics/lenses.html"]'),
  ('lens_power', '{"en-us": "Lens power"}', 'lenses', 6, '{"en-us": "Lens power (also called optical power or dioptric power) is the degree to which a lens converges or diverges light. It is the reciprocal of the focal length, measured in dioptres when the focal length is in metres, and is positive for converging lenses and negative for diverging lenses."}', '["https://en.wikipedia.org/wiki/Optical_power", "https://en.wikipedia.org/wiki/Dioptre", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/02%3A_Geometric_Optics_and_Image_Formation", "https://www.britannica.com/science/optical-power", "https://www.khanacademy.org/science/physics/geometric-optics/lenses/v/convex-lenses"]'),
  ('lensmaker_equation_thick_lens', '{"en-us": "Lensmaker''s equation for a thick lens"}', 'lenses', 9, '{"en-us": "The thick-lens form of the lensmaker''s equation gives the reciprocal focal length (optical power) of a spherical lens in terms of its refractive index, thickness, and the radii of curvature of its two surfaces. It reduces to the thin-lens form when the thickness is small compared to the radii of curvature."}', '["https://en.wikipedia.org/wiki/Lens_(optics)#Lensmaker%27s_equation", "https://phys.libretexts.org/Bookshelves/Optics/Supplemental_Modules_(Components)/Lenses", "https://www.britannica.com/technology/lens", "https://www.khanacademy.org/science/physics/geometric-optics/lenses/v/lensmaker-s-equation"]'),
  ('lensmakers_equation', '{"en-us": "Lensmaker''s equation (thin lens)"}', 'lenses', 8, '{"en-us": "The thin-lens form of the lensmaker''s equation gives the reciprocal focal length of a thin spherical lens in air as a function of its refractive index and the radii of curvature of its two surfaces. It assumes negligible lens thickness and paraxial rays, and is widely used to design and analyse optical instruments."}', '["https://en.wikipedia.org/wiki/Lens_(optics)#Thin_lens_approximation", "https://phys.libretexts.org/Bookshelves/Optics/Supplemental_Modules_(Components)/Lenses", "https://www.britannica.com/technology/lens", "https://www.khanacademy.org/science/physics/geometric-optics/lenses/v/lensmaker-s-equation", "https://www.rp-photonics.com/lensmaker_equation.html"]'),
  ('lever_mechanical_advantage', '{"en-us": "Mechanical advantage of a lever"}', 'forces', 4, '{"en-us": "The mechanical advantage of a lever is the ratio of the load force to the applied effort force, equal to the ratio of the effort-arm length to the load-arm length. A longer effort arm relative to the load arm allows a small effort to lift a larger load, with the trade-off being a greater distance moved by the effort."}', '["https://en.wikipedia.org/wiki/Lever", "https://en.wikipedia.org/wiki/Mechanical_advantage", "https://www.britannica.com/technology/lever", "https://www.khanacademy.org/science/physics/work-and-energy/mechanical-advantage/v/mechanical-advantage", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/09%3A_Linear_Momentum_and_Collisions"]'),
  ('limit_constant_rule', '{"en-us": "Limit of a constant"}', 'limits', 5, '{"en-us": "The limit of a constant is the constant itself, regardless of the point the variable approaches. This is one of the basic limit laws used in calculus to evaluate limits of more complicated expressions."}', '["https://en.wikipedia.org/wiki/Limit_of_a_function", "https://en.wikipedia.org/wiki/Limit_(mathematics)", "https://www.khanacademy.org/math/calculus-1/cs1-limits-and-continuity/cs1-introduction-to-limits/v/introduction-to-limits", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/02%3A_Limits_and_Continuity/2.02%3A_Limit_Laws", "https://www.britannica.com/science/limit-mathematics"]'),
  ('limit_derivative_definition', '{"en-us": "Limit definition of derivative"}', 'limits', 7, '{"en-us": "The limit definition of the derivative expresses the derivative of a real-valued function at a point as the limit of the slope of a secant line through two points on its graph as the second point approaches the first. The defining limit exists only when the function is differentiable at that point, in which case its value equals the slope of the tangent line and the instantaneous rate of change of the function. This definition is the foundation of differential calculus and is the starting point for deriving all standard differentiation rules and the derivatives of elementary functions."}', '["https://en.wikipedia.org/wiki/Derivative", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/02%3A_Limits_and_Continuity/2.03%3A_The_Limit_Laws", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/03%3A_Derivatives/3.01%3A_Defining_the_Derivative", "https://www.khanacademy.org/math/differential-calculus/dc-diff-intro/dc-defining-derivatives/v/derivative-as-a-concept", "https://www.britannica.com/science/derivative-mathematics", "https://www.cuemath.com/calculus/derivatives/"]'),
  ('limit_e_definition', '{"en-us": "Limit definition of e"}', 'limits', 7, '{"en-us": "Euler''s number e is defined as the limit of (1 + 1/n)^n as n approaches infinity, a value approximately equal to 2.71828. This limit arises naturally in compound interest when the compounding interval becomes infinitesimally small, and provides one of several equivalent characterizations of the natural exponential function."}', '["https://en.wikipedia.org/wiki/E_(mathematical_constant)", "https://en.wikipedia.org/wiki/Characterizations_of_the_exponential_function", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/01:_Functions_and_Graphs/1.04:_Exponential_and_Logarithmic_Functions", "https://www.khanacademy.org/math/calculus-1/cs1-limits-and-continuity/cs1-determining-limits-using-the-squeeze-theorem-and-graphs/v/introduction-to-e", "https://mathworld.wolfram.com/e.html", "https://www.britannica.com/science/e-mathematical-constant"]'),
  ('limit_exponential_minus_one', '{"en-us": "Limit of exponential difference"}', 'limits', 7, '{"en-us": "A foundational special limit in differential calculus expressing the derivative of e^x at the origin. It underlies the fact that the natural exponential function is its own derivative and is used in deriving rules for differentiating exponential functions via the limit definition of the derivative."}', '["https://en.wikipedia.org/wiki/List_of_limits", "https://en.wikipedia.org/wiki/Derivative", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/02:_Limits_and_Continuity/2.04:_Continuity", "https://www.khanacademy.org/math/calculus-1/cs1-limits-and-continuity/cs1-determining-limits-using-the-squeeze-theorem-and-graphs/v/limit-of-exponential-difference", "https://mathworld.wolfram.com/ExponentialFunction.html", "https://www.britannica.com/science/limit-mathematics"]'),
  ('limit_log_one_plus_x', '{"en-us": "Limit of Log Ratio"}', 'limits', 7, '{"en-us": "A foundational special limit establishing the derivative of the natural logarithm at 1. It is the logarithmic counterpart to the exponential limit and is used in deriving the derivative of ln(x) via the limit definition of the derivative."}', '["https://en.wikipedia.org/wiki/Logarithm", "https://en.wikipedia.org/wiki/Natural_logarithm", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/02:_Limits_and_Continuity/2.04:_Continuity", "https://www.khanacademy.org/math/calculus-1/cs1-limits-and-continuity/cs1-determining-limits-using-the-squeeze-theorem-and-graphs/v/limit-properties-of-logarithms", "https://mathworld.wolfram.com/NaturalLogarithm.html", "https://www.britannica.com/science/natural-logarithm"]'),
  ('limit_of_detection_formula', '{"en-us": "Limit of detection"}', 'analytical_chemistry', 8, '{"en-us": "The limit of detection is the lowest concentration of an analyte that can be reliably distinguished from a blank measurement, typically defined as the analyte concentration producing a signal three (or 3.3) standard deviations of the blank above the blank mean. The factor 3.3 arises from the one-sided t-distribution at 99% confidence for a small number of replicate blank measurements, and the slope of the calibration curve converts the signal-based definition into a concentration."}', '["https://en.wikipedia.org/wiki/Detection_limit", "https://goldbook.iupac.org/terms/view/L03540.html", "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC2556583/", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Analytical_Chemistry_2.1_(Harvey)/07%3A_Obtaining_and_Preparing_Samples_for_Analysis/7.4%3A_Limits_of_Detection", "https://www.chromatographyonline.com/view/detection-limit-and-limit-quantitation", "https://pubs.acs.org/doi/10.1021/ac00258a724"]'),
  ('limit_one_minus_cos_over_x', '{"en-us": "Limit of (1-cos(x))/x as x approaches 0"}', 'limits', 7, '{"en-us": "A small-angle limit in trigonometry. The numerator 1-cos x vanishes like x^2/2 near zero, which makes the ratio go to zero. The closely related limit (1-cos x)/x^2 = 1/2 is the more commonly used result and underlies the second-order small-angle approximation of cosine."}', '["https://en.wikipedia.org/wiki/Small-angle_approximation", "https://en.wikipedia.org/wiki/List_of_limits", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/02:_Limits_and_Continuity/2.04:_Continuity", "https://www.khanacademy.org/math/calculus-1/cs1-limits-and-continuity/cs1-determining-limits-using-the-squeeze-theorem-and-graphs/v/limit-of-1-minus-cos-x-over-x", "https://mathworld.wolfram.com/CosineIntegral.html", "https://www.britannica.com/science/limit-mathematics"]'),
  ('limit_power_rule', '{"en-us": "Limit power rule"}', 'limits', 6, '{"en-us": "The power rule for limits states that the limit of a function raised to a constant power equals that power applied to the limit of the function, provided the limit of the function exists. It is one of the standard algebraic limit laws used to evaluate limits by reducing them to limits of simpler constituent functions."}', '["https://en.wikipedia.org/wiki/Limit_of_a_function", "https://en.wikipedia.org/wiki/List_of_limits", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/02:_Limits_and_Continuity/2.03:_The_Limit_Laws", "https://www.khanacademy.org/math/calculus-1/cs1-limits-and-continuity/cs1-determining-limits-using-the-squeeze-theorem-and-graphs/v/limit-laws", "https://mathworld.wolfram.com/Limit.html", "https://www.britannica.com/science/limit-mathematics"]'),
  ('limit_product_rule', '{"en-us": "Limit of a product"}', 'limits', 6, '{"en-us": "The product rule for limits states that the limit of a product of two functions equals the product of their individual limits, when those limits exist. This is one of the fundamental algebraic limit laws used to evaluate limits of more complex expressions by breaking them into simpler pieces."}', '["https://en.wikipedia.org/wiki/Limit_of_a_function", "https://en.wikipedia.org/wiki/Limit_(mathematics)", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/02%3A_Limits_and_Continuity/2.03%3A_The_Limit_Laws", "https://www.britannica.com/science/limit-mathematics", "https://www.khanacademy.org/math/calculus-1/cs1-limits-and-continuity/cs1-limit-laws/v/limit-laws", "https://www.cuemath.com/calculus/limit-laws/"]'),
  ('limit_quotient_rule', '{"en-us": "Limit of a quotient"}', 'limits', 6, '{"en-us": "The quotient rule for limits states that the limit of a quotient of two functions equals the quotient of their individual limits, provided the limit of the denominator is nonzero. This law allows limits of rational expressions to be evaluated by treating the numerator and denominator separately."}', '["https://en.wikipedia.org/wiki/Limit_of_a_function", "https://en.wikipedia.org/wiki/Limit_(mathematics)", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/02%3A_Limits_and_Continuity/2.03%3A_The_Limit_Laws", "https://www.britannica.com/science/limit-mathematics", "https://www.khanacademy.org/math/calculus-1/cs1-limits-and-continuity/cs1-limit-laws/v/limit-laws", "https://www.cuemath.com/calculus/limit-laws/"]'),
  ('limit_sin_over_x', '{"en-us": "Limit of sin(x)/x as x approaches 0"}', 'limits', 7, '{"en-us": "This is a foundational trigonometric limit that evaluates to 1 when x is measured in radians. It underlies the small-angle approximation sin(x) ≈ x and is essential for deriving derivatives of sine and cosine in differential calculus."}', '["https://en.wikipedia.org/wiki/Sine", "https://en.wikipedia.org/wiki/Sinc_function", "https://en.wikipedia.org/wiki/Small-angle_approximation", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/02%3A_Limits_and_Continuity/2.04%3A_Continuity", "https://www.britannica.com/science/limit-mathematics", "https://www.khanacademy.org/math/calculus-1/cs1-limits-and-continuity/cs1-continuity-limit-laws/v/sinx-x"]'),
  ('limit_sum_rule', '{"en-us": "Limit of a sum"}', 'limits', 6, '{"en-us": "The sum rule for limits states that the limit of a sum of two functions equals the sum of their individual limits, when those limits exist. It is one of the basic algebraic limit laws used to evaluate limits of sums and differences by handling each term independently."}', '["https://en.wikipedia.org/wiki/Limit_of_a_function", "https://en.wikipedia.org/wiki/Limit_(mathematics)", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/02%3A_Limits_and_Continuity/2.03%3A_The_Limit_Laws", "https://www.britannica.com/science/limit-mathematics", "https://www.khanacademy.org/math/calculus-1/cs1-limits-and-continuity/cs1-limit-laws/v/limit-laws", "https://www.cuemath.com/calculus/limit-laws/"]'),
  ('limit_x_n_to_zero', '{"en-us": "Limit of x^n as x→0"}', 'limits', 6, '{"en-us": "For any fixed positive exponent n, the function x^n approaches 0 as x approaches 0. This basic limit law is used together with the product rule to evaluate limits of polynomials and other power expressions near the origin."}', '["https://en.wikipedia.org/wiki/Limit_of_a_function", "https://en.wikipedia.org/wiki/Limit_(mathematics)", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/02%3A_Limits_and_Continuity/2.03%3A_The_Limit_Laws", "https://www.britannica.com/science/limit-mathematics", "https://www.khanacademy.org/math/calculus-1/cs1-limits-and-continuity/cs1-limit-laws/v/limit-laws", "https://www.cuemath.com/calculus/limit-laws/"]'),
  ('limiting_reactant_excess_mass_calc', '{"en-us": "Excess reactant remaining mass"}', 'limiting_reactants', 6, '{"en-us": "The mass of an excess reactant that remains after a chemical reaction is complete equals its initial mass minus the mass that was consumed. The consumed mass is determined by stoichiometry from the limiting reactant, so once the limiting reagent is identified the leftover excess can be computed directly."}', '["https://en.wikipedia.org/wiki/Limiting_reagent", "https://en.wikipedia.org/wiki/Excess_(chemistry)", "https://www.britannica.com/science/limiting-reagent", "https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/04%3A_The_Structure_of_Atoms/4.08%3A_Limiting_Reactants", "https://www.khanacademy.org/science/chemistry/chemical-reactions-stoichiometry/v/limiting-reagent-and-theoretical-yield", "https://www.chem.tamu.edu/class/fyp/stone/tutorialstoich/stoich4.html"]'),
  ('limiting_reactant_identification', '{"en-us": "Limiting reactant identification"}', 'limiting_reactants', 5, '{"en-us": "The limiting reactant is the reactant that is fully consumed first and therefore caps the amount of product formed. For two reactants A and B, the one whose amount-of-substance divided by its stoichiometric coefficient is smallest is the limiting reactant, because that ratio equals the extent of reaction needed to drive that reagent to zero."}', '["https://en.wikipedia.org/wiki/Limiting_reagent", "https://en.wikipedia.org/wiki/Extent_of_reaction", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_-_The_Central_Science_(Brown_et_al.)/03%3A_Stoichiometry-_Chemical_Formulas_and_Equations/3.07%3A_Limiting_Reactants", "https://www.thoughtco.com/limiting-reagent-609580.html", "https://www.khanacademy.org/science/ap-chemistry-beta/x2eef969c74e0d802%3Astoichiometry/x2eef969c74e0d802%3Alimiting-reagent/v/limiting-reactant-example-problem-1"]'),
  ('limiting_reactant_mass_comparison', '{"en-us": "Limiting reactant by mass comparison"}', 'limiting_reactants', 6, '{"en-us": "When reactant amounts are given as masses, the limiting reactant is identified by computing the mass of one reactant that is required to react completely with a given mass of the other, using molar masses and stoichiometric coefficients. The reactant whose required mass exceeds the amount actually present is the limiting reactant."}', '["https://en.wikipedia.org/wiki/Limiting_reagent", "https://en.wikipedia.org/wiki/Extent_of_reaction", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_-_The_Central_Science_(Brown_et_al.)/03%3A_Stoichiometry-_Chemical_Formulas_and_Equations/3.07%3A_Limiting_Reactants", "https://www.thoughtco.com/limiting-reagent-609580.html", "https://www.khanacademy.org/science/ap-chemistry-beta/x2eef969c74e0d802%3Astoichiometry/x2eef969c74e0d802%3Alimiting-reagent/v/limiting-reactant-example-problem-1"]'),
  ('limiting_reactant_moles_comparison', '{"en-us": "Limiting reactant moles comparison"}', 'limiting_reactants', 6, '{"en-us": "When reactant amounts are expressed in moles, the limiting reactant is identified by computing each reactant''s amount of substance divided by its stoichiometric coefficient. The reactant with the smallest such scaled-mole value is the limiting reactant, since it is the first species to be driven to zero as the reaction proceeds."}', '["https://en.wikipedia.org/wiki/Limiting_reagent", "https://en.wikipedia.org/wiki/Extent_of_reaction", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_-_The_Central_Science_(Brown_et_al.)/03%3A_Stoichiometry-_Chemical_Formulas_and_Equations/3.07%3A_Limiting_Reactants", "https://www.thoughtco.com/limiting-reagent-609580.html", "https://www.khanacademy.org/science/ap-chemistry-beta/x2eef969c74e0d802%3Astoichiometry/x2eef969c74e0d802%3Alimiting-reagent/v/limiting-reactant-example-problem-1"]'),
  ('limiting_reactant_percent_excess', '{"en-us": "Percent excess reactant"}', 'limiting_reactants', 6, '{"en-us": "Percent excess quantifies how much more of a reactant was supplied than the stoichiometric amount required to react completely with the limiting reactant. It is computed as the surplus amount divided by the theoretical amount needed and expressed as a percentage; values above zero indicate an excess reagent, while zero indicates a stoichiometric mixture."}', '["https://en.wikipedia.org/wiki/Limiting_reagent", "https://en.wikipedia.org/wiki/Extent_of_reaction", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_-_The_Central_Science_(Brown_et_al.)/03%3A_Stoichiometry-_Chemical_Formulas_and_Equations/3.07%3A_Limiting_Reactants", "https://www.thoughtco.com/limiting-reagent-609580.html", "https://www.khanacademy.org/science/ap-chemistry-beta/x2eef969c74e0d802%3Astoichiometry/x2eef969c74e0d802%3Alimiting-reagent/v/limiting-reactant-example-problem-1"]'),
  ('linear_algebra_identity_matrix', '{"en-us": "Identity matrix definition"}', 'linear_algebra', 5, '{"en-us": "The identity matrix of size n is the square n-by-n matrix with ones on the main diagonal and zeros elsewhere. It is the multiplicative identity in matrix algebra, leaving any compatible matrix unchanged under left or right multiplication, and serves as the identity element of the general linear group of invertible n-by-n matrices."}', '["https://en.wikipedia.org/wiki/Identity_matrix", "https://en.wikipedia.org/wiki/General_linear_group", "https://mathworld.wolfram.com/IdentityMatrix.html", "https://www.khanacademy.org/math/precalculus/x9e81a4f98389efdf:matrices/x9e81a4f98389efdf:properties-of-matrix-multiplication/a/intro-to-identity-matrices", "https://www.britannica.com/science/identity-matrix"]'),
  ('linear_algebra_inverse_matrix_2x2', '{"en-us": "Inverse of a 2×2 matrix"}', 'linear_algebra', 7, '{"en-us": "The inverse of an invertible 2-by-2 matrix is the matrix''s adjugate (with diagonal entries swapped and off-diagonal entries sign-flipped) divided by the determinant, which equals the difference of the diagonal products of the original matrix. This closed form requires the determinant to be nonzero and is widely used in analytic and numerical work."}', '["https://en.wikipedia.org/wiki/Invertible_matrix", "https://en.wikipedia.org/wiki/Adjugate_matrix", "https://en.wikipedia.org/wiki/Identity_matrix", "https://mathworld.wolfram.com/MatrixInverse.html", "https://www.khanacademy.org/math/precalculus/x9e81a4f98389efdf:matrices/x9e81a4f98389efdf:inverse-of-a-2x2-matrix/a/inverse-of-a-2x2-matrix"]'),
  ('linear_algebra_vector_norm', '{"en-us": "Euclidean norm of a vector"}', 'linear_algebra', 5, '{"en-us": "The Euclidean norm (also called the 2-norm or magnitude) assigns to a vector in real n-dimensional space the non-negative real number that corresponds to its geometric length. It satisfies absolute homogeneity, the triangle inequality, and is zero only for the zero vector, and is the most commonly used norm on R^n."}', '["https://en.wikipedia.org/wiki/Norm_(mathematics)", "https://en.wikipedia.org/wiki/Euclidean_vector", "https://mathworld.wolfram.com/VectorNorm.html", "https://math.libretexts.org/Bookshelves/Linear_Algebra/Interactive_Linear_Algebra_(Margalit_and_Rabinoff)/06%3A_Orthogonality/6.01%3A_Vector_Norms"]'),
  ('linear_density', '{"en-us": "Linear mass density"}', 'mechanical_waves', 4, '{"en-us": "Linear mass density describes the mass per unit length of a one-dimensional object such as a string, rod, cable, or fibre, and is conventionally denoted μ in the context of mechanical waves on strings. It governs the wave speed on a stretched string and is widely used in textile engineering to characterize yarns and fibres."}', '["https://en.wikipedia.org/wiki/Linear_density", "https://en.wikipedia.org/wiki/Wave_on_a_string#Wave_equation", "https://www.khanacademy.org/science/physics/mechanical-waves-and-sound/wave-on-a-string/v/wave-on-a-string-introduction", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/16%3A_Waves-I", "https://www.britannica.com/science/density"]'),
  ('linear_equation_solution', '{"en-us": "Linear equation solution"}', 'equations', 2, '{"en-us": "The solution to a single-variable linear equation expresses the unknown in terms of the constants, valid for any coefficient values. This rule underpins algebraic manipulation in nearly every area of mathematics and applied science, from solving motion equations in physics to fitting straight-line models to data."}', '["https://en.wikipedia.org/wiki/Linear_equation#One_variable", "https://en.wikipedia.org/wiki/Linear_equation", "https://www.khanacademy.org/math/algebra/x2f8bb11595b61c86:solve-equations-inequalities/x2f8bb11595b61c86:linear-eq-unknown/v/solving-linear-equations-review", "https://math.libretexts.org/Bookshelves/Algebra/Algebra_(Boundless)/01%3A_Equations_and_Inequalities/1.01%3A_Solving_Linear_Equations_and_Inequalities_with_One_Variable", "https://www.britannica.com/science/linear-equation"]'),
  ('linear_momentum_formula', '{"en-us": "Linear momentum"}', 'linear_momentum', 4, '{"en-us": "Linear momentum is the product of an object''s mass and its velocity, defined for a single particle in classical mechanics. It is a vector quantity that points in the direction of motion and is central to Newton''s second law, where the net force equals the time derivative of momentum."}', '["https://en.wikipedia.org/wiki/Momentum#Single_particle", "https://en.wikipedia.org/wiki/Momentum", "https://www.britannica.com/science/momentum", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/09%3A_Linear_Momentum_and_Collisions", "https://www.khanacademy.org/science/physics/linear-momentum/momentum-tutorial/a/what-is-momentum"]'),
  ('linear_momentum_system', '{"en-us": "Total linear momentum of a system"}', 'linear_momentum', 5, '{"en-us": "The total linear momentum of a system of particles is the vector sum of the individual momenta, and equals the product of the system''s total mass and the velocity of its center of mass. Conservation of this quantity in isolated systems underlies the analysis of collisions, rocket propulsion, and many-body dynamics."}', '["https://en.wikipedia.org/wiki/Momentum#Many_particles", "https://en.wikipedia.org/wiki/Momentum", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/09%3A_Linear_Momentum_and_Collisions", "https://www.britannica.com/science/momentum", "https://www.khanacademy.org/science/physics/linear-momentum/momentum-tutorial/a/what-is-momentum"]'),
  ('linear_thermal_expansion', '{"en-us": "Linear thermal expansion"}', 'temperature', 5, '{"en-us": "Linear thermal expansion describes the change in length of a solid object when its temperature changes, assuming the body is free to expand. The relationship holds for small, uniform temperature changes and is widely used in engineering to design bridges, rails, bimetallic strips, and other structures that must accommodate dimensional changes."}', '["https://en.wikipedia.org/wiki/Thermal_expansion#Linear_expansion", "https://en.wikipedia.org/wiki/Thermal_expansion", "https://physics.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Temperature_and_Heat", "https://www.britannica.com/science/thermal-expansion", "https://www.khanacademy.org/science/physics/thermodynamics/temp-kinetic-theory-ideal-gas-law/a/thermal-expansion"]'),
  ('lineweaver_burk', '{"en-us": "Lineweaver-Burk equation"}', 'biochemistry', 8, '{"en-us": "The Lineweaver-Burk equation (double-reciprocal plot) is a linearized form of the Michaelis-Menten equation obtained by taking reciprocals. It is widely used to determine the Michaelis constant K_m and the limiting rate V_max graphically, although non-linear regression is now preferred for parameter estimation."}', '["https://en.wikipedia.org/wiki/Lineweaver%E2%80%93Burk_plot", "https://en.wikipedia.org/wiki/Michaelis%E2%80%93Menten_kinetics", "https://www.ncbi.nlm.nih.gov/books/NBK92007/", "https://bio.libretexts.org/Bookshelves/Biochemistry/Book%3A_Biochemistry_Free_For_All_(Ahern_Rajagopal_and_Tan)", "https://www.chem.fsu.edu/chem-fall/chm3210/lineweaver-burk.pdf"]'),
  ('lineweaver_burk_intercept', '{"en-us": "Lineweaver-Burk y-intercept"}', 'biochemistry', 8, '{"en-us": "The y-intercept of a Lineweaver-Burk plot equals 1/V_max, providing a direct graphical estimate of the limiting (maximum) enzyme reaction rate when the substrate concentration tends to infinity."}', '["https://en.wikipedia.org/wiki/Lineweaver%E2%80%93Burk_plot", "https://en.wikipedia.org/wiki/Michaelis%E2%80%93Menten_kinetics", "https://www.ncbi.nlm.nih.gov/books/NBK92007/", "https://www.chem.fsu.edu/chem-fall/chm3210/lineweaver-burk.pdf"]'),
  ('log_change_of_base', '{"en-us": "Logarithm change of base"}', 'logarithms', 5, '{"en-us": "The change-of-base formula expresses a logarithm in one base as a ratio of logarithms in another base, allowing logarithms with arbitrary bases to be computed using a calculator that only supports two fixed bases such as e or 10."}', '["https://en.wikipedia.org/wiki/Logarithm", "https://en.wikipedia.org/wiki/Natural_logarithm", "https://en.wikipedia.org/wiki/Common_logarithm", "https://mathworld.wolfram.com/ChangeofBaseFormula.html", "https://www.khanacademy.org/math/algebra2/x2ec2f6476b63c4d6:logs/x2ec2f6476b63c4d6:change-of-base/v/change-of-base-formula"]'),
  ('logarithm_base_definition', '{"en-us": "Logarithm change of base identity"}', 'logarithms', 4, '{"en-us": "The change-of-base identity expresses a logarithm with one base as the ratio of logarithms with another base, providing a unified way to convert between bases such as 2, 10, and e."}', '["https://en.wikipedia.org/wiki/Logarithm", "https://en.wikipedia.org/wiki/List_of_logarithmic_identities", "https://en.wikipedia.org/wiki/Natural_logarithm", "https://mathworld.wolfram.com/ChangeofBaseFormula.html", "https://www.khanacademy.org/math/algebra2/x2ec2f6476b63c4d6:logs/x2ec2f6476b63c4d6:change-of-base/v/change-of-base-formula"]'),
  ('logarithm_inverse_relation', '{"en-us": "Logarithm as inverse of exponent"}', 'logarithms', 4, '{"en-us": "The logarithm is the inverse function of exponentiation: if x equals base a raised to the power y, then y is the base-a logarithm of x. This relation defines the logarithm and underlies the conversion between multiplicative and additive scales."}', '["https://en.wikipedia.org/wiki/Logarithm", "https://en.wikipedia.org/wiki/Exponential_function", "https://en.wikipedia.org/wiki/Natural_logarithm", "https://www.khanacademy.org/math/algebra2/x2ec2f6476b63c4d6:logs/x2ec2f6476b63c4d6:log-introduction/v/introduction-to-logarithms", "https://mathworld.wolfram.com/Logarithm.html"]'),
  ('logarithm_of_base', '{"en-us": "Logarithm of the base"}', 'logarithms', 3, '{"en-us": "For any valid base b of a logarithm, the logarithm of the base itself equals 1, since b raised to the power 1 is b. This special value reflects the defining relationship that the logarithm answers the question ''to what power must the base be raised to obtain the argument.''"}', '["https://en.wikipedia.org/wiki/Logarithm", "https://en.wikipedia.org/wiki/Common_logarithm", "https://en.wikipedia.org/wiki/Natural_logarithm", "https://www.khanacademy.org/math/algebra2/x2ec2f6476b63c4d6:logs/x2ec2f6476b63c4d6:log-introduction/v/introduction-to-logarithms"]'),
  ('logarithm_of_one', '{"en-us": "Logarithm of 1"}', 'logarithms', 3, '{"en-us": "For any valid logarithm base, the logarithm of one equals zero, because raising the base to the power zero yields one. This identity is one of the fundamental logarithmic laws and follows directly from the definition of the logarithm as the inverse of exponentiation."}', '["https://en.wikipedia.org/wiki/Logarithm", "https://mathworld.wolfram.com/Logarithm.html", "https://www.khanacademy.org/math/algebra2/x2ec2f6976b45024c:logs/x2ec2f6976b45024c:log-intro/a/intro-to-logarithms", "https://math.libretexts.org/Bookshelves/Precalculus/Precalculus_(OpenStax)/12:_Introduction_to_Trigonometric_Functions/12.04:_Logarithmic_Properties"]'),
  ('logarithm_power_rule', '{"en-us": "Logarithm power rule"}', 'logarithms', 4, '{"en-us": "The logarithm of a number raised to a power equals the power times the logarithm of the number. This rule, a consequence of exponentiation and logarithms being inverse operations, is widely used to simplify expressions and solve equations involving powers and roots."}', '["https://en.wikipedia.org/wiki/Logarithm", "https://en.wikipedia.org/wiki/List_of_logarithmic_identities", "https://math.libretexts.org/Bookshelves/Precalculus/Precalculus_(OpenStax)/12:_Introduction_to_Trigonometric_Functions/12.04:_Logarithmic_Properties", "https://www.khanacademy.org/math/algebra2/x2ec2f6976b45024c:logs/x2ec2f6976b45024c:log-prop/a/logarithm-power-rule", "https://mathworld.wolfram.com/Logarithm.html"]'),
  ('logarithm_product_rule', '{"en-us": "Logarithm product rule"}', 'logarithms', 4, '{"en-us": "The logarithm of a product equals the sum of the logarithms of the factors. This identity, which historically justified the use of logarithm tables for multiplying large numbers, requires the base and the arguments to be positive."}', '["https://en.wikipedia.org/wiki/Logarithm", "https://en.wikipedia.org/wiki/List_of_logarithmic_identities", "https://math.libretexts.org/Bookshelves/Precalculus/Precalculus_(OpenStax)/12:_Introduction_to_Trigonometric_Functions/12.04:_Logarithmic_Properties", "https://www.khanacademy.org/math/algebra2/x2ec2f6976b45024c:logs/x2ec2f6976b45024c:log-prop/a/logarithm-properties-review", "https://mathworld.wolfram.com/Logarithm.html"]'),
  ('logarithm_quotient_rule', '{"en-us": "Logarithm quotient rule"}', 'logarithms', 4, '{"en-us": "The logarithm of a quotient equals the difference between the logarithm of the numerator and the logarithm of the denominator. This identity follows from the product rule together with the property that logarithms of reciprocals negate, and it requires positive arguments and a positive base not equal to one."}', '["https://en.wikipedia.org/wiki/Logarithm", "https://en.wikipedia.org/wiki/List_of_logarithmic_identities", "https://math.libretexts.org/Bookshelves/Precalculus/Precalculus_(OpenStax)/12:_Introduction_to_Trigonometric_Functions/12.04:_Logarithmic_Properties", "https://www.khanacademy.org/math/algebra2/x2ec2f6976b45024c:logs/x2ec2f6976b45024c:log-prop/a/logarithm-properties-review", "https://mathworld.wolfram.com/Logarithm.html"]'),
  ('logistic_growth_diff_eq', '{"en-us": "Logistic growth differential equation"}', 'differential_equations', 9, '{"en-us": "The logistic growth model describes a population whose per-capita growth rate declines linearly as the population approaches a carrying capacity. The model assumes a closed environment with limited resources and is foundational in ecology, epidemiology, and chemistry for modelling resource-limited growth."}', '["https://en.wikipedia.org/wiki/Logistic_function#Logistic_differential_equation", "https://mathworld.wolfram.com/LogisticEquation.html", "https://bio.libretexts.org/Bookshelves/Ecology/Environmental_Science_(Ha_and_Schleiger)/03:_Population_Ecology/3.03:_Population_Growth_Models/3.3.01:_Logistic_Growth", "https://www.khanacademy.org/science/ap-biology/ecology-ap/population-ecology/a/logistic-growth", "https://en.wikipedia.org/wiki/Logistic_growth"]'),
  ('lorentz_factor', '{"en-us": "Lorentz factor"}', 'relativity', 8, '{"en-us": "The Lorentz factor is a dimensionless quantity that quantifies how relativistic effects such as time dilation, length contraction, and relativistic mass increase scale with a particle''s velocity. It appears throughout special relativity and approaches infinity as the speed approaches that of light."}', '["https://en.wikipedia.org/wiki/Lorentz_factor", "https://en.wikipedia.org/wiki/Special_relativity", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/05%3A__Relativity", "https://mathworld.wolfram.com/LorentzFactor.html", "https://www.khanacademy.org/science/physics/special-relativity/minkowski-spacetime-2016-01-18t18-26-43-00-00/v/lorentz-transformation"]'),
  ('lorentz_force_electric_magnetic_general', '{"en-us": "General Lorentz force (electric and magnetic)"}', 'magnetism', 8, '{"en-us": "The complete electromagnetic force on a point charge q moving with velocity v through electric field E and magnetic field B, given by the Lorentz force law. The electric component accelerates the particle along E, while the magnetic component qv×B deflects it perpendicular to both v and B. Together with Maxwell''s equations it forms the foundation of classical electrodynamics."}', '["https://en.wikipedia.org/wiki/Lorentz_force", "https://en.wikipedia.org/wiki/Maxwell%27s_equations", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/11:_Magnetic_Forces_and_Fields", "https://www.britannica.com/science/Lorentz-force", "https://www.khanacademy.org/science/physics/magnetic-forces-and-magnetic-fields-and-the-magnetic-force-on-a-moving-charge"]'),
  ('lorentz_force_magnetic', '{"en-us": "Magnetic Lorentz force"}', 'magnetism', 6, '{"en-us": "The magnitude of the force on a charge q moving with velocity v through a magnetic field B, equal to qvB sinθ where θ is the angle between v and B. The force is always perpendicular to both v and B, does no work, and produces circular or helical motion in uniform fields."}', '["https://en.wikipedia.org/wiki/Lorentz_force", "https://en.wikipedia.org/wiki/Magnetic_force", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/11:_Magnetic_Forces_and_Fields", "https://www.britannica.com/science/Lorentz-force", "https://www.khanacademy.org/science/physics/magnetic-forces-and-magnetic-fields-and-the-magnetic-force-on-a-moving-charge"]'),
  ('luminance_formula', '{"en-us": "Luminance from luminous intensity and area"}', 'electromagnetic_waves', 8, '{"en-us": "Luminance is the photometric measure of luminous intensity per unit projected area of a surface, in a specified direction. It determines how bright a surface will appear to an observer, and is invariant along rays in lossless optical systems. The SI unit is the candela per square metre (cd/m²), also called the nit."}', '["https://en.wikipedia.org/wiki/Luminance", "https://en.wikipedia.org/wiki/Luminous_intensity", "https://en.wikipedia.org/wiki/Photometry", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/01:_The_Nature_of_Light", "https://www.britannica.com/science/luminance"]'),
  ('mach_number', '{"en-us": "Mach number"}', 'mechanical_waves', 6, '{"en-us": "Dimensionless ratio of the speed of an object moving through a fluid to the local speed of sound in that fluid, named after Ernst Mach. It characterizes flow regimes (subsonic, transonic, supersonic, hypersonic) and determines when compressibility effects become significant."}', '["https://en.wikipedia.org/wiki/Mach_number", "https://en.wikipedia.org/wiki/Speed_of_sound", "https://www.grc.nasa.gov/www/k-12/airplane/mach.html", "https://www.britannica.com/science/Mach-number", "https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/mach-number/"]'),
  ('magnetic_energy_density', '{"en-us": "Energy density of a magnetic field"}', 'magnetism', 8, '{"en-us": "Energy per unit volume stored in a magnetic field in free space (or a linear medium), expressed in terms of the magnetic flux density B and the permeability of the medium. It is the magnetic analogue of the electric-field energy density u_E = ε₀E²/2 and follows from Poynting''s theorem."}', '["https://en.wikipedia.org/wiki/Magnetic_energy", "https://en.wikipedia.org/wiki/Energy_density", "https://en.wikipedia.org/wiki/Magnetic_field", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/14:_Electromagnetic_Induction", "https://www.britannica.com/science/magnetic-field"]'),
  ('magnetic_field_circular_loop', '{"en-us": "Magnetic field at center of a current loop"}', 'magnetism', 7, '{"en-us": "The magnetic flux density at the center of a circular current loop of radius R carrying current I, obtained by integrating the Biot–Savart law around the loop. The field is directed along the loop''s axis and is the foundation of magnetic dipole behavior."}', '["https://en.wikipedia.org/wiki/Biot%E2%80%93Savart_law", "https://en.wikipedia.org/wiki/Magnetic_moment", "https://en.wikipedia.org/wiki/Magnetic_field", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12:_Sources_of_Magnetic_Fields", "https://www.britannica.com/science/Biot-Savart-law"]'),
  ('magnetic_field_solenoid', '{"en-us": "Magnetic field inside a solenoid"}', 'magnetism', 7, '{"en-us": "Relates the magnetic flux density inside a long, tightly wound solenoid to the free-space permeability, the number of turns per unit length of windings, and the current carried by the wire. It is the limiting (infinite-solenoid) result of Ampère''s law and assumes an air core, ignoring end and fringing effects."}', '["https://en.wikipedia.org/wiki/Solenoid", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields/12.07%3A_Solenoids_and_Toroids", "http://hyperphysics.phy-astr.gsu.edu/hbase/magnetic/solenoid.html", "https://en.wikipedia.org/wiki/Amp%C3%A8re%27s_circuital_law"]'),
  ('magnetic_field_solenoid_ideal', '{"en-us": "Magnetic field inside an ideal solenoid"}', 'magnetism', 7, '{"en-us": "Same as the standard solenoid-field expression but written using the total number of turns N and the solenoid length L instead of the turn density, so the turns-per-unit-length factor n becomes N/L. Useful when N and L are the directly measured quantities."}', '["https://en.wikipedia.org/wiki/Solenoid", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields/12.07%3A_Solenoids_and_Toroids", "http://hyperphysics.phy-astr.gsu.edu/hbase/magnetic/solenoid.html", "https://en.wikipedia.org/wiki/Amp%C3%A8re%27s_circuital_law"]'),
  ('magnetic_field_strength_h', '{"en-us": "Magnetic field strength"}', 'magnetism', 6, '{"en-us": "The H-field (magnetic field strength or magnetic field intensity) is the auxiliary magnetic vector whose curl equals the free current density in Ampère''s law. It is related to the magnetic flux density B and the permeability of the medium by H = B/μ, so in free space H = B/μ₀. H is measured in amperes per metre."}', '["https://en.wikipedia.org/wiki/Magnetic_field", "https://en.wikipedia.org/wiki/Permeability_(electromagnetism)", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields/12.08%3A_Magnetism_in_Matter", "https://en.wikipedia.org/wiki/Amp%C3%A8re%27s_circuital_law"]'),
  ('magnetic_field_toroid', '{"en-us": "Magnetic field inside a toroid"}', 'magnetism', 8, '{"en-us": "Gives the magnetic flux density inside a toroidal coil of N turns carrying current I, where r is the radius of the circular Amperian loop threading the toroid. Derived by applying Ampère''s law to the symmetry of the toroid, assuming a tightly wound, air-core coil of large mean radius compared with its cross-section."}', '["http://hyperphysics.phy-astr.gsu.edu/hbase/magnetic/toroid.html", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields/12.07%3A_Solenoids_and_Toroids", "https://en.wikipedia.org/wiki/Amp%C3%A8re%27s_circuital_law", "https://en.wikipedia.org/wiki/Toroid"]'),
  ('magnetic_field_wire', '{"en-us": "Magnetic field around a long straight wire"}', 'magnetism', 7, '{"en-us": "The magnitude of the magnetic flux density at a perpendicular distance r from an infinitely long, straight wire carrying steady current I, due to the Biot–Savart law (equivalently Ampère''s law). The field lines form concentric circles around the wire, with direction given by the right-hand grip rule."}', '["https://en.wikipedia.org/wiki/Magnetic_field", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields/12.03%3A_Magnetic_Field_due_to_a_Thin_Straight_Wire", "http://hyperphysics.phy-astr.gsu.edu/hbase/magnetic/magcur.html", "https://en.wikipedia.org/wiki/Amp%C3%A8re%27s_circuital_law"]'),
  ('magnetic_flux_angle_dependence', '{"en-us": "Magnetic flux with angle dependence"}', 'magnetism', 7, '{"en-us": "The magnetic flux through a planar surface of area A in a uniform magnetic field B depends on the angle θ between the field direction and the surface normal, reaching its maximum when the field is perpendicular to the surface and falling to zero when the field lies in the plane. This cosine dependence is the basis of Faraday''s law of induction."}', '["https://en.wikipedia.org/wiki/Magnetic_flux", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/13%3A_Electromagnetic_Induction/13.01%3A_Faradays_Law", "https://en.wikipedia.org/wiki/Faraday%27s_law_of_induction", "https://en.wikipedia.org/wiki/Magnetic_field"]'),
  ('magnetic_flux_density_definition', '{"en-us": "Magnetic flux density (B-field) from flux"}', 'magnetism', 7, '{"en-us": "Relates the magnetic flux density (B) to the magnetic flux passing through a surface, assuming the field is uniform and normal to the area. In general, the flux density equals the surface flux density and forms part of the foundation of electromagnetic induction."}', '["https://en.wikipedia.org/wiki/Magnetic_flux", "https://en.wikipedia.org/wiki/Magnetic_field", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields", "https://www.khanacademy.org/science/physics/magnetic-forces-and-magnetic-fields-and-induction/magnetic-flux-faradays-law/a/magnetic-flux"]'),
  ('magnetic_flux_formula', '{"en-us": "Magnetic flux"}', 'magnetism', 6, '{"en-us": "Magnetic flux quantifies the amount of magnetic field passing through a surface and is the surface integral of the normal component of B. It underlies Faraday''s law of induction, where the time-varying flux through a loop produces an electromotive force."}', '["https://en.wikipedia.org/wiki/Magnetic_flux", "https://en.wikipedia.org/wiki/Magnetic_field", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields", "https://www.britannica.com/science/magnetic-flux"]'),
  ('magnetic_force_between_parallel_wires_per_length', '{"en-us": "Magnetic force per unit length between parallel wires"}', 'magnetism', 8, '{"en-us": "Special case of Ampère''s force law giving the force per unit length between two long, straight, parallel current-carrying conductors, assuming thin wires and a separation small compared to their lengths. Historically, this relation underlay the definition of the ampere in the SI system."}', '["https://en.wikipedia.org/wiki/Amp%C3%A8re%27s_force_law", "https://en.wikipedia.org/wiki/Magnetic_field", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields", "https://www.britannica.com/science/Ampere-force-law"]'),
  ('magnetic_force_wire', '{"en-us": "Magnetic force on a current-carrying wire"}', 'magnetism', 7, '{"en-us": "Often called the Laplace force, this gives the mechanical force experienced by a straight current-carrying wire placed in an external magnetic field. The vector form involves a cross product, and the result underlies the operation of electric motors and the force between current-carrying conductors."}', '["https://en.wikipedia.org/wiki/Magnetic_field", "https://en.wikipedia.org/wiki/Lorentz_force", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields", "https://www.britannica.com/science/Lorentz-force"]'),
  ('magnetic_lorentz_force', '{"en-us": "Magnetic Lorentz force (magnetic_lorentz_force)"}', 'magnetism', 7, '{"en-us": "The magnetic component of the Lorentz force is the sideways force experienced by a moving charge in a magnetic field, perpendicular to both the velocity and the field. It is responsible for circular and helical motion of charged particles in magnetic fields and underlies devices such as cyclotrons and mass spectrometers."}', '["https://en.wikipedia.org/wiki/Lorentz_force", "https://en.wikipedia.org/wiki/Magnetic_field", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields", "https://www.khanacademy.org/science/physics/magnetic-forces-and-magnetic-fields-and-induction/magnetic-flux-faradays-law/a/magnetic-flux"]'),
  ('magnetic_moment_current_loop', '{"en-us": "Magnetic dipole moment of a current loop (magnetic_moment_current_loop)"}', 'magnetism', 7, '{"en-us": "Defines the magnetic dipole moment of a planar current loop, with the result scaled by the number of turns for a coil or solenoid. The magnetic moment determines the torque a loop experiences in an external magnetic field and the strength of the dipole field it produces."}', '["https://en.wikipedia.org/wiki/Magnetic_moment", "https://en.wikipedia.org/wiki/Magnetic_dipole", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields", "https://www.britannica.com/science/magnetic-dipole-moment"]'),
  ('magnetic_moment_unpaired_electrons', '{"en-us": "Magnetic moment from unpaired electrons"}', 'inorganic_chemistry', 8, '{"en-us": "The spin-only magnetic moment of a transition-metal complex or atom depends only on the number of unpaired electrons, in units of the Bohr magneton. It is used to deduce the electron configuration and high-spin vs. low-spin state of a complex from a measured magnetic susceptibility."}', '["https://en.wikipedia.org/wiki/Magnetic_moment#Atoms,_molecules,_and_elementary_particles", "https://en.wikipedia.org/wiki/Bohr_magneton", "https://en.wikipedia.org/wiki/Spin_magnetic_moment", "https://chem.libretexts.org/Bookshelves/General_Chemistry", "https://en.wikipedia.org/wiki/Paramagnetism"]'),
  ('magnetism_magnetic_flux_density_from_h', '{"en-us": "Magnetic flux density from magnetic field intensity"}', 'magnetism', 8, '{"en-us": "In a linear, isotropic, non-hysteretic medium the magnetic flux density B is proportional to the magnetizing field intensity H, with the permeability μ of the material as the proportionality constant (B = μ₀ μᵣ H in vacuum-free form)."}', '["https://en.wikipedia.org/wiki/Permeability_(electromagnetism)", "https://en.wikipedia.org/wiki/Magnetic_field", "https://en.wikipedia.org/wiki/Vacuum_permeability", "https://en.wikipedia.org/wiki/Magnetic_susceptibility"]'),
  ('magnification_formula', '{"en-us": "Linear magnification"}', 'lenses', 5, '{"en-us": "Linear (transverse) magnification of a lens or mirror is the ratio of image height to object height, equal in magnitude to the ratio of image distance to object distance. Its sign indicates whether the image is upright (positive) or inverted (negative)."}', '["https://en.wikipedia.org/wiki/Magnification", "https://en.wikipedia.org/wiki/Lens_(optics)", "https://en.wikipedia.org/wiki/Thin_lens", "https://en.wikipedia.org/wiki/Real_image", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/02%3A_Geometric_Optics_and_Image_Formation"]'),
  ('malus_law', '{"en-us": "Malus''s law"}', 'polarization', 7, '{"en-us": "When a perfectly polarized beam of light of irradiance I₀ passes through an ideal linear polarizer whose transmission axis makes an angle θ with the beam''s polarization direction, the transmitted irradiance is reduced by a factor of cos²θ. It is the basis for crossed-polarizer extinction and for quantitative polarimetry."}', '["https://en.wikipedia.org/wiki/Polarizer#Malus''s_law_and_other_properties", "https://en.wikipedia.org/wiki/Polarization_(waves)", "https://en.wikipedia.org/wiki/%C3%89tienne-Louis_Malus", "https://phys.libretexts.org/Bookshelves/Optics", "https://en.wikipedia.org/wiki/Polarizing_filter_(photography)"]'),
  ('mandelstam_invariant_s', '{"en-us": "Mandelstam invariant s"}', 'particle_physics', 10, '{"en-us": "The Mandelstam variable s is a Lorentz-invariant combination of the four-momenta of two scattering particles, equal to the square of the total four-momentum and to the square of the center-of-mass energy. It is widely used to characterize the energy available in two-body scattering processes."}', '["https://en.wikipedia.org/wiki/Mandelstam_variables", "https://en.wikipedia.org/wiki/Four-momentum", "https://en.wikipedia.org/wiki/Invariant_mass", "https://en.wikipedia.org/wiki/Feynman_diagram", "https://en.wikipedia.org/wiki/Stanley_Mandelstam"]'),
  ('margin_of_error', '{"en-us": "Margin of error"}', 'statistics', 7, '{"en-us": "The margin of error for a sample mean estimate is the critical z-score at the chosen confidence level multiplied by the population standard deviation divided by the square root of the sample size. It is the half-width of the corresponding confidence interval."}', '["https://en.wikipedia.org/wiki/Margin_of_error", "https://en.wikipedia.org/wiki/Confidence_interval", "https://en.wikipedia.org/wiki/Standard_error", "https://en.wikipedia.org/wiki/Standard_score", "https://mathworld.wolfram.com/MarginofError.html"]'),
  ('mass_balance_equation', '{"en-us": "Mass balance equation"}', 'analytical_chemistry', 6, '{"en-us": "The mass balance equation expresses conservation of mass (or moles) for a chemical species across all forms in which it appears in a system. For a monoprotic weak acid HA that dissociates into H⁺ and A⁻, the total analytical concentration equals the sum of the equilibrium concentrations of each species. It is a foundational relation in acid–base equilibrium calculations, reactor design, and process engineering."}', '["https://en.wikipedia.org/wiki/Mass_balance", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Supplemental_Modules_(Analytical_Chemistry)/Quantifying_Nature/Dilutions_and_Concentrations/Mass_Balance", "https://www.khanacademy.org/science/chemistry/acids-and-bases-topic", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Equilibria/Acid-Base_Equilibria/Mass_Balance"]'),
  ('mass_concentration_formula', '{"en-us": "Mass concentration"}', 'solutions', 4, '{"en-us": "Mass concentration (also called mass density of a component) expresses the mass of a constituent solute per unit volume of the mixture. It is widely used in chemistry, biology, and medicine, where the percent notation m/v is common for aqueous solutions. For a pure substance the mass concentration equals the bulk density."}', '["https://en.wikipedia.org/wiki/Mass_concentration_(chemistry)", "https://goldbook.iupac.org/terms/view/M03713.html", "https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/03%3A_Using_Chemical_Equations_in_Calculations/3.05%3A_Mass_Concentration", "https://www.britannica.com/science/mass-concentration"]'),
  ('mass_energy_equivalence', '{"en-us": "Mass-energy equivalence"}', 'relativity', 6, '{"en-us": "Mass–energy equivalence, expressed as E = mc², states that the rest energy of a body equals its mass multiplied by the speed of light squared. Introduced by Einstein in 1905, it implies that mass and energy are interchangeable manifestations of the same physical quantity. The relation underlies nuclear reactions, where small mass deficits release enormous energies, and is the conceptual basis for nuclear power and stellar energy production."}', '["https://en.wikipedia.org/wiki/Mass%E2%80%93energy_equivalence", "https://www.nist.gov/pml/energy-mass-equivalence", "https://www.britannica.com/science/E-mc2", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/09%3A__Relativity/9.06%3A__Energy_and_Momentum", "https://www.khanacademy.org/science/physics/special-relativity"]'),
  ('mass_flow_rate_formula', '{"en-us": "Mass flow rate"}', 'continuity_equation', 6, '{"en-us": "Mass flow rate is the mass of a fluid passing through a cross-section per unit time, commonly denoted ṁ. For a uniform flow through a pipe or duct it equals the fluid density times the cross-sectional area times the flow velocity. It is a central quantity in fluid dynamics, the continuity equation, and engine performance calculations such as those used in aerospace propulsion."}', '["https://en.wikipedia.org/wiki/Mass_flow_rate", "https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/mass-flow-rate/", "https://www.engineersedge.com/fluid_flow/mass_flow_rate.htm", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.02%3A__Mass_Density", "https://www.britannica.com/science/mass-flow-rate"]'),
  ('mass_from_concentration_volume', '{"en-us": "Mass from concentration and volume"}', 'solution_stoichiometry', 4, '{"en-us": "The mass of a solute dissolved in a solution can be recovered from its molar concentration, the solution volume, and the solute''s molar mass. Multiplying molarity by volume gives moles of solute, and multiplying by molar mass converts moles to grams. This relation underlies solution preparation, dilution calculations, and stoichiometric work in analytical chemistry."}', '["https://en.wikipedia.org/wiki/Molar_concentration", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/04%3A_Chemical_Reactions/4.4%3A_Mass_Relations_in_Reactions_and_Stoichiometry", "https://www.khanacademy.org/science/chemistry/chemical-reactions-stoichiometry", "https://www.britannica.com/science/molar-concentration"]'),
  ('mass_number_formula', '{"en-us": "Mass number"}', 'atomic_structure', 3, '{"en-us": "The mass number A of an atomic nucleus equals the total count of protons and neutrons (nucleons) it contains, so A = Z + N where Z is the atomic number and N the neutron number. It is a dimensionless integer that distinguishes isotopes of the same element and is approximately equal to the isotopic mass in daltons. Mass number plays a key role in nuclear notation, radioactive decay classifications, and nuclear reaction accounting."}', '["https://en.wikipedia.org/wiki/Mass_number", "https://education.jlab.org/qa/pen_number.html", "https://www.britannica.com/science/mass-number", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/02%3A_Atoms_and_the_Atomic_Theory/2.04%3A_Atomic_Number_and_Mass_Number", "https://www.khanacademy.org/science/chemistry/atomic-structure-and-properties"]'),
  ('mass_to_mass_stoichiometry', '{"en-us": "Mass-to-mass stoichiometry"}', 'limiting_reactants', 6, '{"en-us": "Mass-to-mass stoichiometry uses the balanced chemical equation and molar masses to convert the known mass of one substance into the mass of another participating in the reaction. The conversion chains the mass of reactant A through grams-to-moles, the mole ratio from stoichiometric coefficients, and moles-to-grams using molar mass. It assumes the reaction proceeds as written and that A is the limiting reactant."}', '["https://en.wikipedia.org/wiki/Stoichiometry", "https://en.wikipedia.org/wiki/Stoichiometric_coefficient", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/04_Chemical_Reactions/4.4%3A_Determining_the_Limiting_Reagent", "https://www.khanacademy.org/science/chemistry/chemical-reactions-stoichiome/stoichiometry-ideal/a/stoichiometry", "https://chem.libretexts.org/Bookshelves/Introductory_Chemistry/Introductory_Chemistry/09%3A_Quantities_in_Chemical_Reactions/9.04%3A_Mass-to-Mass_Stoichiometry"]'),
  ('mass_volume_percent', '{"en-us": "Mass-volume percent concentration"}', 'solution_stoichiometry', 4, '{"en-us": "Mass/volume percent is a common way to express the concentration of a solute in a solution, defined as the mass of solute per 100 mL of solution. It is widely used in clinical and pharmaceutical contexts (e.g. mg/mL is equivalent to 1% m/v) where the solute is a solid dissolved in a liquid. The expression is not the same as mass percent (m/m) or volume percent (v/v)."}', '["https://en.wikipedia.org/wiki/Mass_fraction_(chemistry)", "https://en.wikipedia.org/wiki/Concentration", "https://chem.libretexts.org/Bookshelves/General_Chemistry/General_Chemistry_Supplement_(Eames)/Solutions/Concentrations_of_Solutions", "https://www.khanacademy.org/science/chemistry/chemical-reactions-stoichiome/stoichiometry-ideal/a/mass-percent-composition-of-a-solution", "https://www.thoughtco.com/definition-of-mass-volume-percent-605232"]'),
  ('matrix_addition_2x2', '{"en-us": "Matrix addition (2x2)"}', 'linear_algebra', 5, '{"en-us": "Matrix addition is performed entrywise and is only defined for matrices of the same dimensions. For two m-by-n matrices A and B, the (i,j) entry of A+B is the sum of the corresponding entries A_{i,j} and B_{i,j}. The operation is commutative and associative, and a zero matrix of the same size acts as the additive identity."}', '["https://en.wikipedia.org/wiki/Matrix_addition", "https://en.wikipedia.org/wiki/Matrix_(mathematics)#Addition", "https://mathworld.wolfram.com/MatrixAddition.html", "https://www.khanacademy.org/math/linear-algebra/matrix-transformations/matrix-addition/v/matrix-addition-and-subtraction", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Book%3A_Mathematical_Methods_in_Chemistry_(Levitus)/11%3A_Matrices/11.2%3A_Matrix_Arithmetic"]'),
  ('matrix_multiplication_2x2', '{"en-us": "Matrix multiplication 2x2 (first element)"}', 'linear_algebra', 6, '{"en-us": "Matrix multiplication of a 2-by-2 matrix A by a 2-by-2 matrix B requires that the number of columns of A equals the number of rows of B; the product is then computed as the dot product of the i-th row of A with the j-th column of B for each entry. The operation is associative and distributive over addition but is generally not commutative. Shown here is the c₁₁ element of the product, obtained from the first row of A and the first column of B."}', '["https://en.wikipedia.org/wiki/Matrix_multiplication", "https://en.wikipedia.org/wiki/Matrix_(mathematics)#Matrix_multiplication", "https://mathworld.wolfram.com/MatrixMultiplication.html", "https://www.khanacademy.org/math/linear-algebra/matrix-transformations/matrix-multiplication/v/matrix-multiplication-intro", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Book%3A_Mathematical_Methods_in_Chemistry_(Levitus)/11%3A_Matrices/11.2%3A_Matrix_Arithmetic"]'),
  ('maximum_electrons_shell', '{"en-us": "Maximum number of electrons in a shell"}', 'periodic_table', 5, '{"en-us": "Each electron shell with principal quantum number n can hold at most 2n² electrons, a result that follows from the Pauli exclusion principle and the number of distinct orbitals in a shell (1, 4, 9, 16, ...). The first four shells (K, L, M, N) reach this maximum in known elements; higher shells never fill completely because of the aufbau filling order. The periodic table of elements is organized so that each row corresponds to the filling of a successive shell."}', '["https://en.wikipedia.org/wiki/Electron_shell", "https://en.wikipedia.org/wiki/Principal_quantum_number", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/08%3A_Electronic_Structure/8.3%3A_Quantum_Numbers", "https://www.khanacademy.org/science/chemistry/electronic-structure-of-atoms/electron-configurations-jay-sal/v/shells-subshells-and-orbitals", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Electronic_Structure_of_Atoms_and_Molecules/Electronic_Configuration/Shell"]'),
  ('maximum_stereoisomers', '{"en-us": "Maximum number of stereoisomers"}', 'organic_chemistry', 8, '{"en-us": "The Le Bel–van ''t Hoff rule gives an upper bound of 2ⁿ stereoisomers for a molecule containing n stereogenic (chiral) centers. This assumes no internal symmetry; molecules with meso forms or other degeneracies will have fewer distinct stereoisomers. The bound is widely used in carbohydrate and natural-product chemistry to enumerate possible stereoisomers, for example, the 16 stereoisomers expected for an aldohexose such as glucose."}', '["https://en.wikipedia.org/wiki/Stereoisomerism", "https://en.wikipedia.org/wiki/Le_Bel-van%27t_Hoff_rule", "https://en.wikipedia.org/wiki/Enantiomer", "https://chem.libretexts.org/Bookshelves/Organic_Chemistry/Organic_Chemistry_(Morsch_et_al.)/Chapter_05%3A_Stereochemistry_at_Tetrahedral_Centers/5.3%3A_Optical_Activity_and_the_21_Chiral_Centers", "https://www.masterorganicchemistry.com/2018/02/12/r-and-s-configuration-in-fischer-projections/"]'),
  ('maxwell_boltzmann_mode_speed', '{"en-us": "Most probable speed from Maxwell-Boltzmann distribution"}', 'ideal_gases', 9, '{"en-us": "The most probable speed is the speed at which the Maxwell-Boltzmann speed distribution attains its maximum; it equals the square root of twice the product of the gas constant and absolute temperature divided by the molar mass (equivalently, twice the Boltzmann constant times temperature divided by the molecular mass). It is the simplest characteristic speed of an ideal gas in thermal equilibrium, smaller than the mean speed and the rms speed."}', '["https://en.wikipedia.org/wiki/Maxwell%E2%80%93Boltzmann_distribution", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Map%3A_Physical_Chemistry_for_the_Biosciences_(Chang)/03%3A_The_Kinetic_Theory_of_Gases/3.4%3A_The_Maxwell-Boltzmann_Distribution", "https://www.phys.unsw.edu.au/PHYS1169/PDFs/MB.pdf", "https://farside.ph.utexas.edu/teaching/sm1/lectures/node13.html"]'),
  ('mayer_relation', '{"en-us": "Mayer''s relation for ideal gases"}', 'ideal_gases', 8, '{"en-us": "Mayer''s relation states that for an ideal gas the difference between the molar heat capacity at constant pressure and the molar heat capacity at constant volume is exactly the gas constant. It is a direct consequence of the first law of thermodynamics applied to a constant-pressure process and links the two principal specific heats of an ideal gas."}', '["https://en.wikipedia.org/wiki/Mayer%27s_relation", "https://www.britannica.com/science/Mayers-relation", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Heat_and_Thermodynamics_(Tatum)/09%3A_Ideal_Gases/9.07%3A_Specific_Heats_of_an_Ideal_Gas", "https://openstax.org/books/university-physics-volume-2/pages/3-5-heat-capacities-of-an-ideal-gas"]'),
  ('mean_free_path_ideal_gas', '{"en-us": "Mean free path of an ideal gas molecule"}', 'ideal_gases', 9, '{"en-us": "The mean free path is the average distance a gas molecule travels between successive collisions with other molecules in an ideal gas. For hard-sphere molecules of diameter d, it equals the Boltzmann constant times absolute temperature divided by the product of the pressure, the molecular cross-sectional area, and the square root of two."}', '["https://en.wikipedia.org/wiki/Mean_free_path", "https://www.britannica.com/science/mean-free-path", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Physical_Chemistry_(Flexter)/03%3A_Gases/3.3%3A_Kinetic-Molecular_Theory_of_Gases/3.3.3%3A_Mean_Free_Path", "https://farside.ph.utexas.edu/teaching/sm1/lectures/node13.html"]'),
  ('mechanical_energy_loss_friction', '{"en-us": "Energy loss due to friction"}', 'conservation_of_energy', 5, '{"en-us": "When kinetic friction acts on a sliding object, mechanical energy is not conserved: the work done by friction is negative and removes energy from the system. Equivalently, the final mechanical energy equals the initial mechanical energy (kinetic plus potential) plus the work done by friction, illustrating the conversion of mechanical energy into heat via dissipative forces."}', '["https://en.wikipedia.org/wiki/Work_(physics)", "https://en.wikipedia.org/wiki/Conservation_of_energy", "https://openstax.org/books/university-physics-volume-1/pages/7-6-conservation-of-energy", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/07%3A_Work_and_Kinetic_Energy/7.07%3A_Conservation_of_Energy"]'),
  ('mechanical_power_linear_definition', '{"en-us": "Mechanical power"}', 'power', 5, '{"en-us": "Average mechanical power is defined as the amount of work done (or energy transferred) divided by the time interval over which it is done, with the SI unit of the watt. Instantaneous power is recovered in the limit as the time interval approaches zero, giving the time derivative of the work."}', '["https://en.wikipedia.org/wiki/Power_(physics)", "https://www.britannica.com/science/power-physics", "https://openstax.org/books/university-physics-volume-1/pages/7-8-power", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/07%3A_Work_and_Kinetic_Energy/7.08%3A_Power"]'),
  ('mechanical_power_rotational', '{"en-us": "Mechanical rotational power"}', 'power', 6, '{"en-us": "For a rigid body rotating about a fixed axis, the instantaneous mechanical power delivered by a torque equals the scalar product of the torque and the angular velocity. This is the rotational analogue of the linear relation P = F·v and gives the rate at which rotational work is done on the shaft."}', '["https://en.wikipedia.org/wiki/Power_(physics)", "https://en.wikipedia.org/wiki/Torque", "https://openstax.org/books/university-physics-volume-1/pages/10-8-work-and-power-for-rotational-motion", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10%3A_Fixed-Axis_Rotation__Introduction/10.08%3A_Work_and_Power_for_Rotational_Motion"]'),
  ('mechanical_wave_frequency', '{"en-us": "Mechanical wave frequency from wave speed and wavelength"}', 'mechanical_waves', 5, '{"en-us": "Relates the frequency of a periodic traveling wave to its phase speed and wavelength, a fundamental kinematic identity for all wave motion. Valid in any non-dispersive or locally monochromatic regime where the speed, frequency, and wavelength are well defined."}', '["https://en.wikipedia.org/wiki/Wave_(physics)", "https://en.wikipedia.org/wiki/Frequency", "https://en.wikipedia.org/wiki/Wavelength", "https://en.wikipedia.org/wiki/Mechanical_wave", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/16%3A_Waves/16.01%3A_Traveling_Waves"]'),
  ('mechanical_wave_speed_tension', '{"en-us": "Wave speed from tension and linear density"}', 'mechanical_waves', 7, '{"en-us": "Gives the phase speed of small-amplitude transverse waves on an ideal stretched string under tension, assuming a perfectly flexible, uniform string. Applies to strings, wires, and ropes, and is the basis of stringed musical instrument acoustics."}', '["https://en.wikipedia.org/wiki/Mechanical_wave", "https://en.wikipedia.org/wiki/Linear_density", "https://en.wikipedia.org/wiki/String_vibration", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/16%3A_Waves/16.04%3A_The_Speed_of_a_Traveling_Wave_on_a_String"]'),
  ('michaelis_menten', '{"en-us": "Michaelis-Menten equation"}', 'biochemistry', 8, '{"en-us": "Models the rate of a simple enzyme-catalyzed reaction as a function of substrate concentration under steady-state (or rapid-equilibrium) assumptions, with Vmax the limiting rate at saturation and Km the substrate concentration at half-maximum velocity. Widely used in enzyme kinetics, pharmacology, and microbial growth modeling."}', '["https://en.wikipedia.org/wiki/Michaelis%E2%80%93Menten_kinetics", "https://en.wikipedia.org/wiki/Enzyme_kinetics", "https://en.wikipedia.org/wiki/Specificity_constant", "https://en.wikipedia.org/wiki/Turnover_number", "https://chem.libretexts.org/Bookshelves/Biological_Chemistry/Enzymes/Enzyme_Kinetics/Michaelis-Menten_Equation"]'),
  ('midpoint_formula', '{"en-us": "Midpoint formula"}', 'coordinate_geometry', 3, '{"en-us": "Locates the point exactly halfway between two given points on a coordinate axis or in Cartesian space, expressed as the arithmetic mean of their coordinates. Generalizes to higher dimensions by averaging each coordinate independently and to a weighted version for division of a segment in any ratio."}', '["https://en.wikipedia.org/wiki/Cartesian_coordinate_system", "https://en.wikipedia.org/wiki/Section_formula", "https://en.wikipedia.org/wiki/Euclidean_distance", "https://math.libretexts.org/Bookshelves/Algebra/Algebra_and_Trigonometry/Book%3A_Algebra_and_Trigonometry_(AIA)/09%3A_Conic_Sections_and_Systems_of_Nonlinear_Equations/9.01%3A_The_Circle", "https://www.khanacademy.org/math/geometry/hs-geo-analytic-geometry/hs-geo-distance-and-midpoints/a/midpoint-formula"]'),
  ('mirror_and_thin_lens_equation', '{"en-us": "Mirror and thin lens equation"}', 'mirrors', 6, '{"en-us": "The Gaussian mirror and thin-lens equation, relating object distance, image distance, and focal length for paraxial rays on spherical mirrors and thin lenses. Sign conventions distinguish real and virtual objects, images, and the converging/diverging nature of the optic."}', '["https://en.wikipedia.org/wiki/Curved_mirror", "https://en.wikipedia.org/wiki/Thin_lens", "https://en.wikipedia.org/wiki/Gaussian_optics", "https://openstax.org/books/university-physics-volume-3/pages/2-2-spherical-mirrors", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/02%3A_Geometric_Optics_and_Image_Formation/2.02%3A_Spherical_Mirrors"]'),
  ('mirror_image_distance_formula', '{"en-us": "Mirror image distance formula"}', 'mirrors', 6, '{"en-us": "A rearrangement of the Gaussian mirror equation that solves for the image distance of a spherical mirror from the object distance and the focal length. Valid for paraxial rays under the real-is-positive sign convention; for a plane mirror the focal length is infinite and the formula yields equal magnitude but opposite-signed object and image distances."}', '["https://en.wikipedia.org/wiki/Curved_mirror", "https://en.wikipedia.org/wiki/Plane_mirror", "https://en.wikipedia.org/wiki/Spherical_mirror", "https://openstax.org/books/university-physics-volume-3/pages/2-2-spherical-mirrors", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/02%3A_Geometric_Optics_and_Image_Formation/2.02%3A_Spherical_Mirrors"]'),
  ('mirror_magnification_formula', '{"en-us": "Mirror image magnification"}', 'reflection', 5, '{"en-us": "The lateral (transverse) magnification produced by a mirror equals the negative ratio of the image distance to the object distance. The sign convention makes positive magnification indicate an upright image and negative magnification an inverted image; the same expression governs both mirrors and thin lenses under the real-is-positive convention."}', '["https://en.wikipedia.org/wiki/Curved_mirror", "https://en.wikipedia.org/wiki/Magnification", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/02%3A_Geometric_Optics_and_Image_Formation/2.03%3A_Spherical_Mirrors", "https://byjus.com/physics/magnification-of-mirror/"]'),
  ('moi_annular_cylinder', '{"en-us": "Moment of inertia of an annular cylinder"}', 'moment_of_inertia', 8, '{"en-us": "The moment of inertia of a hollow cylindrical tube (thick-walled annular cylinder) about its longitudinal central axis equals one-half the total mass times the sum of the squares of the inner and outer radii. It is the standard result for tubes, pipes, and bearings, and reduces to the solid cylinder (R₁=0) or thin shell (R₁=R₂) cases in the appropriate limits."}', '["https://en.wikipedia.org/wiki/List_of_moments_of_inertia", "https://en.wikipedia.org/wiki/Moment_of_inertia", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10%3A_Fixed-Axis_Rotation/10.06%3A_Moments_of_Inertia", "https://www.britannica.com/science/moment-of-inertia"]'),
  ('moi_cone', '{"en-us": "Moment of inertia of a solid cone"}', 'moment_of_inertia', 8, '{"en-us": "The moment of inertia of a uniform solid right circular cone about its central axis equals three-tenths of the total mass times the square of the base radius. The height does not appear, so cones with the same base radius and mass have the same rotational inertia regardless of how tall or squat they are."}', '["https://en.wikipedia.org/wiki/List_of_moments_of_inertia", "https://en.wikipedia.org/wiki/Moment_of_inertia", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10%3A_Fixed-Axis_Rotation/10.06%3A_Moments_of_Inertia", "https://www.britannica.com/science/moment-of-inertia"]'),
  ('moi_disk', '{"en-us": "Moment of inertia of a solid disk"}', 'moment_of_inertia', 7, '{"en-us": "The moment of inertia of a uniform solid disk about the symmetry axis through its center equals one-half the mass times the radius squared. It is a special case of the solid cylinder (height h=0) and underlies the rotational dynamics of flywheels, record players, and rotating machinery."}', '["https://en.wikipedia.org/wiki/List_of_moments_of_inertia", "https://en.wikipedia.org/wiki/Moment_of_inertia", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10%3A_Fixed-Axis_Rotation/10.06%3A_Moments_of_Inertia", "https://www.britannica.com/science/moment-of-inertia"]'),
  ('moi_rectangular_plate_center', '{"en-us": "Moment of inertia of a rectangular plate (center axis)"}', 'moment_of_inertia', 8, '{"en-us": "The moment of inertia of a thin rectangular plate about the central axis perpendicular to the plate equals one-twelfth of the mass times the sum of the squares of the two side lengths. The plate is treated as flat (negligible thickness) and the axis passes through the geometric center."}', '["https://en.wikipedia.org/wiki/List_of_moments_of_inertia", "https://en.wikipedia.org/wiki/Moment_of_inertia", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10%3A_Fixed-Axis_Rotation/10.06%3A_Moments_of_Inertia", "https://www.britannica.com/science/moment-of-inertia"]'),
  ('moi_rod_center', '{"en-us": "Moment of inertia of a thin rod about center"}', 'moment_of_inertia', 7, '{"en-us": "The moment of inertia of a thin uniform rod about a perpendicular axis through its center equals one-twelfth of the mass times the squared length. The rod is idealized as a one-dimensional wire of negligible thickness, so the result applies to batons, baseball bats (approximately), and slender beams in torsional analyses."}', '["https://en.wikipedia.org/wiki/List_of_moments_of_inertia", "https://en.wikipedia.org/wiki/Moment_of_inertia", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10%3A_Fixed-Axis_Rotation/10.06%3A_Moments_of_Inertia", "https://www.britannica.com/science/moment-of-inertia"]'),
  ('moi_rod_end', '{"en-us": "Moment of inertia of a thin rod about end"}', 'moment_of_inertia', 7, '{"en-us": "The moment of inertia of a thin uniform rod of length L and mass m about an axis through one of its ends and perpendicular to the rod gives the rotational analog of mass for pivoting about that endpoint. The result scales with the square of the length because mass farther from the pivot contributes more to rotational inertia."}', '["https://en.wikipedia.org/wiki/List_of_moments_of_inertia", "https://en.wikipedia.org/wiki/Moment_of_inertia", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10:_Rotation_of_Rigid_Bodies_About_a_Fixed_Axis", "https://www.khanacademy.org/science/physics/torque-angular-momentum/rotational-inertia/v/rotational-inertia", "https://hyperphysics.phy-astr.gsu.edu/hbase/mi.html"]'),
  ('moi_solid_sphere', '{"en-us": "Moment of inertia of a solid sphere"}', 'moment_of_inertia', 7, '{"en-us": "The moment of inertia of a solid uniform sphere of radius R and mass m about any axis through its center is the rotational analog of mass. The factor 2/5 arises from integrating the squared distance of each mass element from the center over the volume of the sphere."}', '["https://en.wikipedia.org/wiki/List_of_moments_of_inertia", "https://en.wikipedia.org/wiki/Moment_of_inertia", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10:_Rotation_of_Rigid_Bodies_About_a_Fixed_Axis", "https://www.khanacademy.org/science/physics/torque-angular-momentum/rotational-inertia/v/rotational-inertia", "https://hyperphysics.phy-astr.gsu.edu/hbase/mi.html"]'),
  ('moi_spherical_shell', '{"en-us": "Moment of inertia of a thin spherical shell"}', 'moment_of_inertia', 7, '{"en-us": "The moment of inertia of a thin spherical shell (hollow sphere) of radius R and mass m about any axis through its center. All of the mass lies at the same distance R from the axis, so the result is larger than that of a solid sphere of the same mass and radius."}', '["https://en.wikipedia.org/wiki/List_of_moments_of_inertia", "https://en.wikipedia.org/wiki/Moment_of_inertia", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10:_Rotation_of_Rigid_Bodies_About_a_Fixed_Axis", "https://www.khanacademy.org/science/physics/torque-angular-momentum/rotational-inertia/v/rotational-inertia", "https://hyperphysics.phy-astr.gsu.edu/hbase/mi.html"]'),
  ('moi_thin_hoop', '{"en-us": "Moment of inertia of a thin hoop"}', 'moment_of_inertia', 7, '{"en-us": "The moment of inertia of a thin circular hoop (ring) of radius R and mass m about an axis through its center and perpendicular to the plane of the hoop. Because every element of mass lies at the same distance R from the axis, the moment of inertia simply equals mR²."}', '["https://en.wikipedia.org/wiki/List_of_moments_of_inertia", "https://en.wikipedia.org/wiki/Moment_of_inertia", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10:_Rotation_of_Rigid_Bodies_About_a_Fixed_Axis", "https://www.khanacademy.org/science/physics/torque-angular-momentum/rotational-inertia/v/rotational-inertia", "https://hyperphysics.phy-astr.gsu.edu/hbase/mi.html"]'),
  ('molality', '{"en-us": "Molality from amount and mass of solvent"}', 'solutions', 6, '{"en-us": "Molality expresses the concentration of a solution as the amount of solute (in moles) per kilogram of solvent. Because it is based on mass rather than volume, molality is independent of temperature and pressure, making it the preferred concentration unit in colligative-property calculations."}', '["https://en.wikipedia.org/wiki/Molality", "https://www.britannica.com/science/molality", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/Solutions_and_Phase_Equilibria/Concentration", "https://www.khanacademy.org/science/chemistry/states-of-matter-and-intermolecular-forces/solutions-and-mixtures/v/molarity-vs-molality", "https://www.thoughtco.com/definition-of-molality-604381"]'),
  ('molar_conductivity', '{"en-us": "Molar conductivity"}', 'electrochemistry', 7, '{"en-us": "Molar conductivity is the conductivity of an electrolyte solution divided by its molar concentration of electrolyte, with SI units of S m² mol⁻¹. It is used to compare the conducting ability of different electrolytes and forms the basis of Kohlrausch''s law of independent ionic migration."}', '["https://en.wikipedia.org/wiki/Molar_conductivity", "https://www.britannica.com/science/molar-conductivity", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Supplemental_Modules_(Analytical_Chemistry)/Electrochemistry/Conductivity", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/Solutions_and_Phase_Equilibria/Colligative_Properties/Determination_of_Molar_Mass", "https://www.khanacademy.org/science/chemistry/oxidation-reduction"]'),
  ('molar_energy_formula', '{"en-us": "Molar energy"}', 'thermochemistry', 7, '{"en-us": "Molar energy is the amount of energy per mole of substance, defined as the energy of a sample divided by its amount of substance. It is an intensive (molar) property used in thermochemistry to compare energies of different substances on a per-mole basis."}', '["https://en.wikipedia.org/wiki/Amount_of_substance", "https://en.wikipedia.org/wiki/Intensive_and_extensive_properties#Molar_properties", "https://en.wikipedia.org/wiki/Molar_quantity", "https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/02%3A_Atoms_Molecules_and_Chemical_Reactions/2.10%3A_Molar_Quantities", "https://goldbook.iupac.org/terms/view/M04001.html"]'),
  ('molar_entropy_formula', '{"en-us": "Molar entropy"}', 'entropy', 7, '{"en-us": "Molar entropy is the entropy of a sample divided by its amount of substance, expressing the disorder of a system per mole. It is an intensive property used to compare entropies of different substances and to compute entropy changes in chemical reactions from standard molar entropies."}', '["https://en.wikipedia.org/wiki/Entropy", "https://en.wikipedia.org/wiki/Intensive_and_extensive_properties#Molar_properties", "https://en.wikipedia.org/wiki/Amount_of_substance", "https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/02%3A_Atoms_Molecules_and_Chemical_Reactions/2.10%3A_Molar_Quantities", "https://goldbook.iupac.org/terms/view/M04002.html"]'),
  ('molar_heat_capacity', '{"en-us": "Molar heat capacity definition"}', 'thermochemistry', 6, '{"en-us": "Molar heat capacity is the amount of heat required to raise the temperature of one mole of a substance by one kelvin, i.e. the heat capacity of a sample divided by its amount of substance. It is an intensive property used to compare the thermal response of different substances on a per-mole basis."}', '["https://en.wikipedia.org/wiki/Heat_capacity", "https://en.wikipedia.org/wiki/Molar_heat_capacity", "https://en.wikipedia.org/wiki/Specific_heat_capacity", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Thermodynamics/Calorimetry/Heat_Capacity", "https://goldbook.iupac.org/terms/view/M04005.html"]'),
  ('molar_heat_capacity_constant_pressure', '{"en-us": "Molar heat capacity at constant pressure"}', 'thermochemistry', 7, '{"en-us": "Molar heat capacity at constant pressure (isobaric) is the heat required to raise the temperature of one mole of a substance by one kelvin while the pressure is held fixed. It is larger than the constant-volume value because some of the supplied energy does expansion work."}', '["https://en.wikipedia.org/wiki/Heat_capacity", "https://en.wikipedia.org/wiki/Molar_heat_capacity", "https://en.wikipedia.org/wiki/Specific_heat_capacity", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Thermodynamics/Calorimetry/Heat_Capacity", "https://goldbook.iupac.org/terms/view/M04006.html"]'),
  ('molar_heat_capacity_constant_volume', '{"en-us": "Molar heat capacity at constant volume"}', 'thermochemistry', 7, '{"en-us": "Molar heat capacity at constant volume (isochoric) is the heat required to raise the temperature of one mole of a substance by one kelvin at fixed volume, and equals the change in internal energy per mole per kelvin. It is smaller than the constant-pressure value because no expansion work is done."}', '["https://en.wikipedia.org/wiki/Heat_capacity", "https://en.wikipedia.org/wiki/Molar_heat_capacity", "https://en.wikipedia.org/wiki/Specific_heat_capacity", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Thermodynamics/Calorimetry/Heat_Capacity", "https://goldbook.iupac.org/terms/view/M04007.html"]'),
  ('molar_mass_colligative_freezing', '{"en-us": "Molar mass from freezing point depression"}', 'molar_mass', 8, '{"en-us": "This cryoscopic relation gives the molar mass of an unknown solute from the freezing-point depression it produces when dissolved in a solvent of known cryoscopic constant. The method assumes a dilute ideal solution and a non-dissociating (i = 1) solute."}', '["https://en.wikipedia.org/wiki/Freezing-point_depression", "https://en.wikipedia.org/wiki/Cryoscopic_constant", "https://en.wikipedia.org/wiki/Colligative_properties", "https://en.wikipedia.org/wiki/Molality", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Thermodynamics/Thermodynamics_of_Solutions/Freezing_Point_Depression"]'),
  ('molar_mass_compound', '{"en-us": "Molar mass of a compound"}', 'molar_mass', 4, '{"en-us": "The molar mass of a compound equals the sum of the atomic molar masses of its constituent elements, each weighted by the number of atoms of that element appearing in one formula unit. This is how a chemical formula is converted into a mass per mole, e.g. for water the molar mass is roughly twice the atomic mass of hydrogen plus the atomic mass of oxygen."}', '["https://en.wikipedia.org/wiki/Molar_mass#Molar_masses_of_compounds", "https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/02%3A_Atoms_Molecules_and_Chemical_Reactions/2.06%3A_Molar_Mass", "https://www.khanacademy.org/science/chemistry/atomic-structure-and-properties/mass-spectrometry/v/molecular-and-empirical-formulas", "https://courses.lumenlearning.com/introchem/chapter/molar-mass/"]'),
  ('molar_mass_empirical_weight', '{"en-us": "Molar mass from empirical formula weight"}', 'molar_mass', 6, '{"en-us": "Once the empirical formula of a compound is known, multiplying its empirical formula weight (EFW) by an integer n gives the molar mass of the molecular compound. The integer n is the ratio of the molecular mass to the empirical formula mass, and is used to convert an empirical formula into the true molecular formula."}', '["https://en.wikipedia.org/wiki/Empirical_formula", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_-_The_Central_Science_(Brown_et_al.)/03%3A_Stoichiometry%3A_Counting_Molecules_and_Atoms/3.2%3A_Determining_Empirical_and_Molecular_Formulas", "https://www.khanacademy.org/science/chemistry/chemical-reactions-stoichiometry/empirical-and-molecular-formulas/v/empirical-molecular-and-formula-mass", "https://www.chemistrylearner.com/empirical-formula.html"]'),
  ('molar_mass_from_atomic_masses', '{"en-us": "Molar mass from atomic masses"}', 'molar_mass', 4, '{"en-us": "In its most general form the molar mass of a substance is the sum over every constituent element of the number of atoms of that element in the chemical formula times the atomic mass of that element. This is the working equation used to compute molar masses from a formula and a table of standard atomic weights."}', '["https://en.wikipedia.org/wiki/Molar_mass#Molar_masses_of_compounds", "https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/02%3A_Atoms_Molecules_and_Chemical_Reactions/2.06%3A_Molar_Mass", "https://www.khanacademy.org/science/chemistry/atomic-structure-and-properties/mass-spectrometry/v/molecular-and-empirical-formulas", "https://www.chemistrysteps.com/molar-mass/"]'),
  ('molar_mass_from_boiling_point_elevation', '{"en-us": "Molar mass from boiling point elevation"}', 'molar_mass', 8, '{"en-us": "Boiling-point elevation is a colligative property, so a measured rise in boiling point of a solvent (with a known ebullioscopic constant Kb) can be inverted to obtain the molar mass of a dissolved solute. The technique, called ebullioscopy, requires careful temperature measurement to avoid superheating and is used in classical molecular-weight determination."}', '["https://en.wikipedia.org/wiki/Boiling-point_elevation", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_-_The_Central_Science_(Brown_et_al.)/13%3A_Properties_of_Solutions/13.05%3A_Colligative_Properties", "https://www.khanacademy.org/science/chemistry/thermodynamics/v/freezing-point-depression-and-boiling-point-elevation", "https://www.thoughtco.com/boiling-point-elevation-609301", "https://www.chemistryexplained.com/Bo-Ca/Boiling-Point-Elevation.html"]'),
  ('molar_mass_from_density', '{"en-us": "Molar mass of a gas from density"}', 'molar_mass', 6, '{"en-us": "Combining the ideal gas law with the definition of density (ρ = m/V) gives a direct route to the molar mass of a gas from its measured density at a known temperature and pressure. This relation underlies the classical vapour-density method of determining molecular weights, and is exact for an ideal gas and a good approximation for real gases at low pressure."}', '["https://en.wikipedia.org/wiki/Molar_mass#Vapour_density", "https://en.wikipedia.org/wiki/Ideal_gas_law", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_-_The_Central_Science_(Brown_et_al.)/10%3A_Gases/10.04%3A_The_Ideal-Gas_Equation", "https://www.thoughtco.com/definition-of-vapor-density-604953", "https://www.chemteam.info/GasLaw/Gas-Density.html"]'),
  ('mole_concept_avogadro_number_particles', '{"en-us": "Number of particles from amount and Avogadro constant"}', 'mole_concept', 4, '{"en-us": "One mole of any substance contains exactly the Avogadro number of elementary entities (atoms, molecules, ions, or formula units). Multiplying an amount of substance expressed in moles by the Avogadro constant gives the number of particles in the sample; this is the defining relation of the mole as a counting unit in chemistry."}', '["https://en.wikipedia.org/wiki/Avogadro_constant", "https://en.wikipedia.org/wiki/Mole_(unit)", "https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/01%3A_Introduction_-_The_Ambit_of_Chemistry/1.05%3A_The_Avogadro_Constant", "https://www.khanacademy.org/science/chemistry/atomic-structure-and-properties/mole-concept/v/the-mole-and-avogadro-s-number"]'),
  ('mole_formula', '{"en-us": "Amount of substance from mass"}', 'mole_concept', 4, '{"en-us": "The amount of substance in a sample is obtained by dividing its mass by the molar mass of the substance, exploiting the SI definition that one mole corresponds to Avogadro''s number of elementary entities. This conversion is the standard bridge between a bulk mass measurement and a chemical amount expressed in moles."}', '["https://en.wikipedia.org/wiki/Mole_(unit)", "https://en.wikipedia.org/wiki/Molar_mass", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/03%3A_Stoichiometry%3A_Counting_Molecules_and_Atoms/3.01%3A_Avogadro''s_Number_and_Mole_Conversions", "https://www.khanacademy.org/science/chemistry/atomic-structure-and-properties/introduction-to-the-atom/v/the-mole-and-avogadro''s-number", "https://www.britannica.com/science/mole-chemistry", "https://goldbook.iupac.org/terms/view/M03980"]'),
  ('mole_fraction', '{"en-us": "Mole fraction"}', 'solutions', 5, '{"en-us": "The mole fraction (or amount fraction) of a component in a mixture is the ratio of its amount of substance to the total amount of all components; it is a dimensionless quantity that is temperature-independent and widely used in phase diagrams, gas mixtures, and colligative-property calculations. Because the mole fractions of all components sum to one, the quantity for one component determines the rest in a binary mixture."}', '["https://en.wikipedia.org/wiki/Mole_fraction", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/Solutions_and_Mixtures/Nonideal_Solutions/Mole_Fraction", "https://www.khanacademy.org/science/chemistry/states-of-matter-and-intermolecular-forces/mixtures-and-solutions/a/mole-fraction", "https://www.britannica.com/science/mole-fraction", "https://goldbook.iupac.org/terms/view/A00295", "https://www.chem.purdue.edu/gchelp/howtosolveit/Equilibrium/Mole_Fraction.htm"]'),
  ('mole_fraction_mass_conversion', '{"en-us": "Mole fraction from mass"}', 'mole_concept', 6, '{"en-us": "When only the masses of the components in a binary mixture are known, the mole fraction can be computed by converting each mass to moles through its molar mass, then taking the ratio of one component''s moles to the total moles. This is the practical form used in laboratory work where balances measure mass rather than moles."}', '["https://en.wikipedia.org/wiki/Mole_fraction", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/Solutions_and_Mixtures/Nonideal_Solutions/Mole_Fraction", "https://www.khanacademy.org/science/chemistry/states-of-matter-and-intermolecular-forces/mixtures-and-solutions/a/mole-fraction", "https://www.britannica.com/science/mole-fraction", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_-_The_Central_Science_(Brown_et_al.)/04%3A_Reactions_in_Aqueous_Solution/4.04%3A_Concentrations_of_Solutions"]'),
  ('molecules_to_mass', '{"en-us": "Mass from number of molecules"}', 'mole_concept', 5, '{"en-us": "Divides a count of discrete molecules by the Avogadro number to obtain the amount of substance in moles, then multiplies by the molar mass to yield the total sample mass. It is the inverse of the particle-count from-mass conversion, and is used whenever one knows how many molecules are present (e.g. from a counting experiment) and needs the bulk mass."}', '["https://en.wikipedia.org/wiki/Avogadro_constant", "https://en.wikipedia.org/wiki/Molar_mass", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/03%3A_Stoichiometry%3A_Counting_Molecules_and_Atoms/3.01%3A_Avogadro''s_Number_and_Mole_Conversions", "https://www.khanacademy.org/science/chemistry/atomic-structure-and-properties/introduction-to-the-atom/v/the-mole-and-avogadro''s-number", "https://www.britannica.com/science/mole-chemistry"]'),
  ('moles_from_gas_stp', '{"en-us": "Moles from gas volume at STP"}', 'mole_concept', 5, '{"en-us": "At standard temperature and pressure, one mole of any ideal gas occupies a fixed molar volume (about 22.4 L at the historical 0 °C/1 atm STP, or 22.7 L at the modern IUPAC 0 °C/1 bar standard), so the amount of gas in moles is its measured volume divided by that molar volume. The relation is exact only for ideal gases, but serves as a useful approximation for many real gases near STP."}', '["https://en.wikipedia.org/wiki/Molar_volume", "https://en.wikipedia.org/wiki/Standard_temperature_and_pressure", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/03%3A_Stoichiometry%3A_Counting_Molecules_and_Atoms/3.02%3A_Avogadro''s_Number_and_Mole_Conversions", "https://www.khanacademy.org/science/chemistry/gases-and-kinetic-molecular-theory/states-of-matter/a/stp", "https://www.britannica.com/science/standard-temperature-and-pressure"]'),
  ('moles_from_solution_concentration', '{"en-us": "Moles from solution concentration"}', 'mole_concept', 4, '{"en-us": "The amount of solute in moles is obtained by multiplying the molar (amount-of-substance) concentration of the solution by the solution''s total volume. It is the rearranged form of the defining relation c = n/V and is the basis of stoichiometric calculations in solution chemistry and of dilution problems."}', '["https://en.wikipedia.org/wiki/Molar_concentration", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/03%3A_Stoichiometry%3A_Counting_Molecules_and_Atoms/3.03%3A_Molar_Mass", "https://www.khanacademy.org/science/chemistry/states-of-matter-and-intermolecular-forces/mixtures-and-solutions/a/molarity", "https://www.britannica.com/science/molar-concentration", "https://goldbook.iupac.org/terms/view/A00295"]'),
  ('momentum_force_integral', '{"en-us": "Momentum change from force integral"}', 'linear_momentum', 7, '{"en-us": "The impulse-momentum theorem states that the impulse delivered to an object equals its change in momentum. For a constant net force, this reduces to a simple product of the force and the time interval over which it acts. The general integral form expresses momentum change as the time integral of the net force and is foundational for analyzing collisions and short-duration forces."}', '["https://en.wikipedia.org/wiki/Impulse_(physics)", "https://en.wikipedia.org/wiki/Newton%27s_laws_of_motion", "https://en.wikipedia.org/wiki/Momentum", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/08%3A_Linear_Momentum_and_Collisions/8.01%3A_Impulse", "https://www.khanacademy.org/science/physics/linear-momentum/elastic-and-inelastic-collisions/a/what-are-impulse-and-momentum"]'),
  ('momentum_system_particles', '{"en-us": "Momentum of a system of particles"}', 'linear_momentum', 5, '{"en-us": "The total linear momentum of a system of particles equals the vector sum of the individual particle momenta, each computed as the product of mass and velocity. This result is the basis for the conservation of total momentum in isolated systems and connects the system momentum directly to the motion of the center of mass. It applies to any collection of particles, whether or not internal forces act between them."}', '["https://en.wikipedia.org/wiki/Momentum", "https://en.wikipedia.org/wiki/Center_of_mass", "https://en.wikipedia.org/wiki/Newton%27s_laws_of_motion", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/08%3A_Linear_Momentum_and_Collisions/8.02%3A_Conservation_of_Momentum", "https://www.khanacademy.org/science/physics/linear-momentum/center-of-mass/a/what-is-the-center-of-mass"]'),
  ('moseleys_law', '{"en-us": "Moseley''s law"}', 'periodic_table', 8, '{"en-us": "Moseley''s law is an empirical relationship discovered by Henry Moseley in 1913 that links the frequency of characteristic X-ray emission lines of an element to its atomic number. The square root of the X-ray frequency increases approximately linearly with the atomic number, offset by a screening constant. It provided the first physical justification for ordering the elements by atomic number rather than atomic weight and resolved several inconsistencies in the periodic table."}', '["https://en.wikipedia.org/wiki/Moseley%27s_law", "https://en.wikipedia.org/wiki/Characteristic_X-ray", "https://en.wikipedia.org/wiki/Henry_Moseley", "https://en.wikipedia.org/wiki/Atomic_number", "https://www.britannica.com/science/Moseleys-law"]'),
  ('motional_emf', '{"en-us": "Motional electromotive force"}', 'electromagnetic_induction', 8, '{"en-us": "Motional EMF is the electromotive force induced in a conductor that moves through a magnetic field, generated by the magnetic component of the Lorentz force separating charges along the conductor. It is the physical mechanism behind electrical generators and is a special case of Faraday''s law of induction. The formula assumes the velocity, magnetic field, and conductor length are mutually perpendicular."}', '["https://en.wikipedia.org/wiki/Electromotive_force", "https://en.wikipedia.org/wiki/Faraday%27s_law_of_induction", "https://en.wikipedia.org/wiki/Lorentz_force", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/14%3A_Electromagnetic_Induction/14.05%3A_Motional_EMF", "https://www.khanacademy.org/science/physics/magnetic-forces-and-magnetic-fields/magnetic-flux-faradays-law/a/what-is-motional-emf"]'),
  ('multiple_mirror_image_count', '{"en-us": "Number of images formed by two mirrors"}', 'reflection', 5, '{"en-us": "When an object is placed between two plane mirrors inclined at an angle, multiple images are formed by successive reflections between the mirrors. The number of images depends on the angle between the mirrors, with smaller angles producing more images. This principle is the basis for kaleidoscopes and other optical devices that produce symmetric repeating patterns."}', '["https://en.wikipedia.org/wiki/Mirror_image", "https://en.wikipedia.org/wiki/Reflection_(physics)", "https://en.wikipedia.org/wiki/Kaleidoscope", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_(OpenStax)/02%3A_Geometric_Optics_and_Image_Formation/2.02%3A_Images_Formed_by_Plane_Mirrors", "https://www.britannica.com/science/plane-mirror"]'),
  ('natural_log_definition', '{"en-us": "Natural logarithm definition"}', 'logarithms', 5, '{"en-us": "The natural logarithm is the logarithm taken to the base e, where e is Euler''s number, an irrational and transcendental constant approximately equal to 2.718. It is the inverse of the natural exponential function, and it is the logarithm that arises most naturally in calculus, particularly as the integral of 1/x. Natural logarithms are used throughout mathematics and science wherever continuous growth, decay, or integration is involved."}', '["https://en.wikipedia.org/wiki/Natural_logarithm", "https://en.wikipedia.org/wiki/E_(mathematical_constant)", "https://en.wikipedia.org/wiki/Logarithm", "https://mathworld.wolfram.com/NaturalLogarithm.html", "https://www.khanacademy.org/math/algebra2/x2ec2f6f830c9fb89:logs/x2ec2f6f830c9fb89:log-intro/v/natural-logarithm"]'),
  ('negative_exponent_rule', '{"en-us": "Negative exponent rule"}', 'exponents', 3, '{"en-us": "The negative exponent rule states that any nonzero base raised to a negative integer power equals the reciprocal of that base raised to the corresponding positive power. It is a defining identity that extends exponentiation beyond non-negative integers and is consistent with the multiplication rule b^m · b^n = b^(m+n)."}', '["https://en.wikipedia.org/wiki/Exponentiation#Negative_exponents", "https://mathworld.wolfram.com/NegativeExponent.html", "https://www.cuemath.com/algebra/negative-exponents/"]'),
  ('nernst_equation', '{"en-us": "Nernst equation"}', 'electrochemistry', 8, '{"en-us": "The Nernst equation relates the reduction potential of an electrochemical half-cell or full cell to its standard electrode potential, temperature, number of transferred electrons, and the activities of the chemical species. It is fundamental to electrochemistry, governing how cell potentials shift away from standard conditions."}', '["https://en.wikipedia.org/wiki/Nernst_equation", "https://www.britannica.com/science/Nernst-equation", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Supplemental_Modules_(Analytical_Chemistry)/Electrochemistry/Redox_Chemistry/The_Nernst_Equation", "https://www.khanacademy.org/science/ap-chemistry/thermodynamics-ap/effect-of-concentration-on-cell-potential/v/the-nernst-equation"]'),
  ('net_force_vector_sum', '{"en-us": "Net force from vector sum"}', 'forces', 4, '{"en-us": "The net force on a body is the vector sum of all individual forces acting on it. It determines the body''s acceleration through Newton''s second law and is the basis of free-body analysis in classical mechanics."}', '["https://en.wikipedia.org/wiki/Net_force", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/05%3A_Newton''s_Laws", "https://www.britannica.com/science/net-force"]'),
  ('neutron_number', '{"en-us": "Neutron number"}', 'atomic_structure', 3, '{"en-us": "The neutron number N of a nuclide is the count of neutrons in its nucleus, given by the mass number A minus the atomic number Z. Together with the atomic number it identifies a specific nuclide and determines its nuclear properties."}', '["https://en.wikipedia.org/wiki/Neutron_number", "https://en.wikipedia.org/wiki/Atomic_number", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_-_The_Central_Science_(Brown_et_al.)/02%3A_Atoms_Molecules_and_Ions/2.03%3A_The_Atomic_Theory_of_Matter", "https://www.britannica.com/science/atomic-number"]'),
  ('newtonian_gravitational_potential_energy', '{"en-us": "Gravitational potential energy of two point masses"}', 'newtonian_gravity', 7, '{"en-us": "Valid for two point masses, or spherically symmetric bodies treated as point masses."}', '["https://en.wikipedia.org/wiki/Gravitational_energy", "https://en.wikipedia.org/wiki/Gravitational_potential_energy", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Variational_Principles_in_Classical_Mechanics_(Fitzpatrick)/04%3A_Conservative_Systems/4.02%3A_Gravitational_Potential_Energy", "https://www.britannica.com/science/gravitational-potential-energy"]'),
  ('newtons_first_law', '{"en-us": "Newton''s first law of motion"}', 'newtons_laws', 3, '{"en-us": "Newton''s first law, the law of inertia, states that a body remains at rest or in uniform straight-line motion unless acted upon by a net external force. A body is in equilibrium precisely when the vector sum of all forces acting on it vanishes."}', '["https://en.wikipedia.org/wiki/Newton%27s_laws_of_motion", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/05%3A_Newton''s_Laws", "https://www.britannica.com/science/Newtons-first-law", "https://www.khanacademy.org/science/physics/forces-newtons-laws/newtons-laws-of-motion/a/what-is-newtons-first-law"]'),
  ('newtons_law_of_cooling', '{"en-us": "Newton''s law of cooling"}', 'heat_transfer', 7, '{"en-us": "Newton''s law of cooling states that the rate of heat loss of a body is proportional to the temperature difference between the body and its surroundings. The proportionality constant is the heat transfer coefficient, and the law is most accurate for forced convection, conduction, and small temperature differences; it fails for buoyancy-driven convection and thermal radiation, which require a fourth-power (Stefan–Boltzmann) treatment."}', '["https://en.wikipedia.org/wiki/Newton%27s_law_of_cooling", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Heat_Transfer_(Lienhard)/A:_Conduction_and_Convection/A.1:_Introduction_to_Heat_Transfer", "https://www.britannica.com/science/heat-transfer", "https://web.archive.org/web/20150614122639/http://paginas.fisica.uson.mx/laura.yeomans/tc/Sci-Edu-Springer-2010.pdf", "https://ahtt.mit.edu/"]'),
  ('newtons_law_of_gravitation', '{"en-us": "Newton''s law of universal gravitation"}', 'newtonian_gravity', 5, '{"en-us": "Every point mass attracts every other point mass with a force directed along the line joining them, proportional to the product of the masses and inversely proportional to the square of the separation. Spherically symmetric bodies behave as if all their mass were concentrated at their centers (shell theorem), and the law is the classical limit of general relativity."}', '["https://en.wikipedia.org/wiki/Newton%27s_law_of_universal_gravitation", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/13%3A_Gravitation/13.02%3A_Newton%27s_Law_of_Universal_Gravitation", "https://www.britannica.com/science/Newtons-law-of-gravitation", "https://www.physicsclassroom.com/class/circles/Lesson-3/Newton-s-Law-of-Universal-Gravitation", "https://www.khanacademy.org/science/physics/centripetal-force-and-gravitation/newtons-law-of-gravitation"]'),
  ('newtons_rings_radius', '{"en-us": "Newton''s rings radius"}', 'interference', 8, '{"en-us": "Newton''s rings are concentric bright and dark fringes produced by interference between light reflected from a plano-convex lens and an underlying flat glass surface. The radius of the m-th dark ring is given by a square root involving the ring order, the light wavelength, and the radius of curvature of the lens; this relation is the basis for using Newton''s rings to measure lens curvature or wavelength."}', '["https://en.wikipedia.org/wiki/Newton%27s_rings", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_(OpenStax)/03%3A_Interference/3.05%3A_Newton%27s_Rings", "https://www.britannica.com/science/Newton-s-rings", "https://opentextbc.ca/universityphysicsv3/chapter/3-5-newtons-rings/", "https://scienceworld.wolfram.com/physics/NewtonsRings.html"]'),
  ('newtons_second_law', '{"en-us": "Newton''s second law"}', 'newtons_laws', 3, '{"en-us": "Newton''s second law states that the net force on a body equals its mass times its acceleration. It is the defining dynamical relation of Newtonian mechanics, applies in inertial reference frames, and reduces to the constant-mass form F = m a; for systems with changing mass the momentum form F = dp/dt is required."}', '["https://en.wikipedia.org/wiki/Newton%27s_laws_of_motion", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/05%3A_Newton%27s_Laws/5.03%3A_Newton%27s_Second_Law", "https://www.britannica.com/science/Newtons-second-law", "https://www.khanacademy.org/science/physics/forces-newtons-laws/newtons-laws-of-motion/a/what-is-newtons-second-law", "https://www.physicsclassroom.com/class/newtlaws/Lesson-3/Newton-s-Second-Law"]'),
  ('newtons_second_law_momentum_form', '{"en-us": "Newton''s second law in terms of momentum"}', 'newtons_laws', 6, '{"en-us": "Expressed in terms of momentum, Newton''s second law states that the net external force on a body equals the time rate of change of its linear momentum. This formulation is the more general form and remains valid for systems with variable mass, such as rockets, where F = m a alone does not apply."}', '["https://en.wikipedia.org/wiki/Newton%27s_laws_of_motion", "https://en.wikipedia.org/wiki/Momentum", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/05%3A_Newton%27s_Laws/5.03%3A_Newton%27s_Second_Law", "https://www.britannica.com/science/Newtons-second-law", "https://www.khanacademy.org/science/physics/linear-momentum/momentum-tutorial/v/what-is-momentum"]'),
  ('newtons_third_law', '{"en-us": "Newton''s third law"}', 'newtons_laws', 3, '{"en-us": "Newton''s third law states that for every action there is an equal and opposite reaction: the force exerted by body 1 on body 2 is equal in magnitude and opposite in direction to the force exerted by body 2 on body 1. The two forces act on different bodies, so they do not cancel; the law is the microscopic origin of conservation of linear momentum."}', '["https://en.wikipedia.org/wiki/Newton%27s_laws_of_motion", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/05%3A_Newton%27s_Laws/5.05%3A_Newton%27s_Third_Law", "https://www.britannica.com/science/Newtons-third-law", "https://www.khanacademy.org/science/physics/forces-newtons-laws/newtons-laws-of-motion/a/what-is-newtons-third-law", "https://www.physicsclassroom.com/class/newtlaws/Lesson-4/Newton-s-Third-Law"]'),
  ('normal_force_incline', '{"en-us": "Dynamics: normal force on incline"}', 'forces', 5, '{"en-us": "The normal force on a body resting on an inclined surface is the contact force perpendicular to the surface. Its magnitude adjusts so that the body neither sinks into nor lifts off the surface, balancing the component of gravity normal to the plane."}', '["https://en.wikipedia.org/wiki/Normal_force", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/06:_Applications_of_Newton''s_Laws", "https://www.physicsclassroom.com/class/newtlaws/Lesson-2/Inclined-Planes", "https://courses.lumenlearning.com/suny-osuniversityphysics/chapter/6-3-inclined-planes/"]'),
  ('nuclear_binding_energy_per_nucleon', '{"en-us": "Binding energy per nucleon"}', 'nuclear_physics', 8, '{"en-us": "The binding energy per nucleon is the total nuclear binding energy of a nuclide divided by its mass number, giving the average energy required to remove a single nucleon from the nucleus. It characterizes nuclear stability and is maximum around iron-56."}', '["https://en.wikipedia.org/wiki/Nuclear_binding_energy", "https://www.nuclear-power.com/nuclear-power/nuclear-reactions/nuclear-binding-energy/", "https://hyperphysics.phy-astr.gsu.edu/hbase/NucEne/nucbin.html", "https://openstax.org/books/college-physics-2e/pages/31-5-nuclear-binding-energy"]'),
  ('nuclear_decay_chain_activity_ratio', '{"en-us": "Activity ratio in secular equilibrium"}', 'nuclear_physics', 9, '{"en-us": "In secular equilibrium a long-lived parent radionuclide sustains a much shorter-lived daughter, and after several daughter half-lives the daughter activity equals the parent activity. The relationship between parent and daughter activities and their half-lives underpins generator-based radionuclide production."}', '["https://en.wikipedia.org/wiki/Secular_equilibrium", "https://en.wikipedia.org/wiki/Transient_equilibrium", "https://www.nuclear-power.com/nuclear-power/radioactive-decay/activity/", "https://goldbook.iupac.org/S05532.html"]'),
  ('nuclear_fusion_q', '{"en-us": "Q-value of a fusion reaction"}', 'nuclear_physics', 9, '{"en-us": "The Q-value of a nuclear reaction is the energy released or absorbed, given by the mass difference between initial and final states times c². For fusion a positive Q means the reaction is exothermic, releasing energy when light nuclei combine into heavier ones."}', '["https://en.wikipedia.org/wiki/Fusion_energy_gain_factor", "https://en.wikipedia.org/wiki/Q_value_(nuclear_science)", "https://www.nuclear-power.com/nuclear-power/nuclear-reactions/nuclear-fusion-reactions/", "https://www.lehigh.edu/~eus204/teaching/ME362/lectures/lecture01.pdf"]'),
  ('nuclear_magneton_definition', '{"en-us": "Nuclear magneton"}', 'nuclear_physics', 9, '{"en-us": "The nuclear magneton is the natural unit of magnetic dipole moment for heavy particles such as nucleons and nuclei, defined from the elementary charge, the reduced Planck constant, and the proton rest mass. It serves the same role for nuclear magnetic moments that the Bohr magneton serves for atomic magnetic moments."}', '["https://en.wikipedia.org/wiki/Nuclear_magneton", "https://physics.nist.gov/cgi-bin/cuu/Value?mun", "https://hyperphysics.phy-astr.gsu.edu/hbase/magnetic/nucmag.html", "https://www.britannica.com/science/nuclear-magneton"]'),
  ('nuclear_q_value', '{"en-us": "Q-value of a nuclear reaction"}', 'nuclear_physics', 9, '{"en-us": "The Q-value of a nuclear reaction is the energy released or absorbed as a result of the reaction, computed from the difference between the rest masses of the initial reactants and final products via E=mc². A positive Q indicates an exothermic reaction, while a negative Q indicates an endothermic one."}', '["https://en.wikipedia.org/wiki/Q_value_(nuclear_science)", "https://www.nuclear-power.com/nuclear-power/nuclear-reactions/q-value/", "https://link.aps.org/doi/10.1103/PhysRevC.95.024310", "https://www.lehigh.edu/~eus204/teaching/ME362/lectures/lecture01.pdf"]'),
  ('nuclear_radius', '{"en-us": "Nuclear radius"}', 'nuclear_physics', 8, '{"en-us": "Empirical relation from the liquid-drop model giving the approximate radius of an atomic nucleus in terms of its mass number. The proportionality constant r_0 is typically 1.2–1.5 fm, reflecting the nearly constant nuclear matter density, and the relation holds well for heavier nuclei (A > 20)."}', '["https://en.wikipedia.org/wiki/Charge_radius", "https://en.wikipedia.org/wiki/Atomic_nucleus", "https://www.nuclear-power.com/nuclear-power/nuclear-physics/atomic-nucleus/nuclear-radius/", "https://physics.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_(OpenStax)/10%3A__Fixed-Axis_Rotation/10.5%3A_Nuclear_Physics"]'),
  ('number_average_molar_mass', '{"en-us": "Number average molar mass"}', 'organic_chemistry', 8, '{"en-us": "The number average molar mass of a polymer is the ordinary arithmetic mean of the molecular masses of the individual chains, weighted by the number of chains of each type. It is the first moment of the molar mass distribution and is the quantity measured by colligative methods such as osmometry."}', '["https://en.wikipedia.org/wiki/Molar_mass_distribution", "https://en.wikipedia.org/wiki/Number-average_molar_mass", "https://www.pslc.ws/macrog/number_avg.htm", "https://chem.libretexts.org/Bookshelves/Physical_Chemistry/Book%3A_Physical_Chemistry_(McQuarrie_and_Simon)/29%3A_Polymers/29.2%3A_Molecular_Weight_Distributions_in_Polymers"]'),
  ('octahedral_tetrahedral_splitting', '{"en-us": "Tetrahedral to octahedral crystal field splitting ratio"}', 'inorganic_chemistry', 9, '{"en-us": "For the same metal and ligands, the crystal field splitting in a tetrahedral complex is approximately 4/9 of the octahedral splitting. This weaker splitting, combined with the smaller crystal-field stabilization energy, is why tetrahedral complexes are almost always high-spin."}', '["https://en.wikipedia.org/wiki/Crystal_field_theory", "https://en.wikipedia.org/wiki/Spectrochemical_series", "https://chem.libretexts.org/Bookshelves/Inorganic_Chemistry/Map%3A_Inorganic_Chemistry_(Housecroft_and_Sharpe)/Chapter_19%3A_d-Block_Metal_Chemistry_-_General_Considerations/19.3%3A_Crystal_Field_Theory", "https://chem.libretexts.org/Bookshelves/Inorganic_Chemistry/Supplemental_Modules_and_Websites_(Inorganic_Chemistry)/Crystal_Field_Theory/Crystal_Field_Stabilization_Energy"]'),
  ('odds_formula', '{"en-us": "Odds from probability"}', 'probability', 4, '{"en-us": "The odds in favor of an event are the ratio of the probability that the event occurs to the probability that it does not. This statistical formulation differs from gambling usage, where odds are often expressed as the ratio of net profit to stake; for a fair bet the two coincide."}', '["https://en.wikipedia.org/wiki/Odds", "https://en.wikipedia.org/wiki/Odds_ratio", "https://mathworld.wolfram.com/Odds.html", "https://www.britannica.com/topic/odds", "https://stattrek.com/statistics/dictionary?definition=odds"]'),
  ('ohms_law', '{"en-us": "Ohm''s law"}', 'circuits', 4, '{"en-us": "Ohm''s law states that the voltage across a conductor is proportional to the current through it, with the resistance as the constant of proportionality. It applies to ohmic materials, where the resistance is independent of voltage or current; non-ohmic devices such as diodes and transistors do not obey it."}', '["https://en.wikipedia.org/wiki/Ohm%27s_law", "https://www.britannica.com/science/Ohms-law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_(OpenStax)/09%3A_Current_and_Resistance/9.3%3A_Resistivity_and_Resistance", "https://www.khanacademy.org/science/physics/circuits-topic/circuits-resistance/a/ohms-law", "https://hyperphysics.phy-astr.gsu.edu/hbase/electric/ohmlaw.html"]'),
  ('ohms_law_current', '{"en-us": "Ohm''s law (current form)"}', 'circuits', 4, '{"en-us": "Rearrangement of Ohm''s law expressing the current through a conductor in terms of the voltage across it and its resistance. It is useful in circuit analysis when one needs to compute the current from a known applied voltage and the resistance of a circuit element."}', '["https://en.wikipedia.org/wiki/Ohm%27s_law", "https://www.britannica.com/science/Ohms-law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_(OpenStax)/09%3A_Current_and_Resistance/9.3%3A_Resistivity_and_Resistance", "https://www.khanacademy.org/science/physics/circuits-topic/circuits-resistance/a/ohms-law", "https://hyperphysics.phy-astr.gsu.edu/hbase/electric/ohmlaw.html"]'),
  ('optical_absorbance', '{"en-us": "Optical absorbance"}', 'spectroscopy', 6, '{"en-us": "Absorbance is the common (base-10) logarithm of the ratio of incident to transmitted radiant power through a sample. It is widely used in ultraviolet–visible absorption spectroscopy, where it is linearly proportional to the concentration of the absorbing species and to the optical path length under the Beer–Lambert law (valid for dilute, non-scattering samples)."}', '["https://en.wikipedia.org/wiki/Absorbance", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Spectroscopy/Electronic_Spectroscopy/Electronic_Spectroscopy_Basics/The_Beer-Lambert_Law", "https://goldbook.iupac.org/terms/view/A00028.html", "https://www.khanacademy.org/science/chemistry/chem-analysis-titration/titration-experiments/a/beers-law"]'),
  ('optical_image_distance_mirror', '{"en-us": "Mirror equation (image distance)"}', 'mirrors', 6, '{"en-us": "The Gaussian mirror equation relates the object distance, image distance, and focal length of a spherical mirror. Using the Cartesian sign convention (real-is-positive, virtual-is-negative) the same algebraic form applies to concave and convex mirrors, with the focal length negative for a diverging (convex) mirror so that its image is always virtual and located behind the reflecting surface."}', '["https://en.wikipedia.org/wiki/Curved_mirror#Mirror_equation,_magnification,_and_focal_length", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/02%3A_Geometric_Optics_and_Image_Formation", "https://www.britannica.com/science/mirror-formula", "https://www.physicsclassroom.com/class/refln/Lesson-3/The-Mirror-Equation"]'),
  ('optical_magnification_mirror', '{"en-us": "Magnification from mirror equation"}', 'mirrors', 6, '{"en-us": "The linear (transverse) magnification of an image formed by a spherical mirror is the ratio of image height to object height. With the Cartesian sign convention it is negative of the ratio of image distance to object distance, so a negative magnification indicates a real, inverted image and a positive magnification a virtual, upright image (such as the image always produced by a convex mirror)."}', '["https://en.wikipedia.org/wiki/Magnification#Linear_or_transverse_magnification", "https://en.wikipedia.org/wiki/Curved_mirror#Mirror_equation,_magnification,_and_focal_length", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/02%3A_Geometric_Optics_and_Image_Formation", "https://www.physicsclassroom.com/class/refln/Lesson-3/Mirror-Magnification"]'),
  ('optical_path_length', '{"en-us": "Optical path length"}', 'interference', 7, '{"en-us": "Optical path length is the product of the geometric length of a light ray''s path through a medium and the refractive index of that medium, giving the equivalent distance light would travel in vacuum in the same time. It is the fundamental quantity that sets the phase accumulated by a wave, so it underlies thin-film interference, diffraction, and Fermat''s principle."}', '["https://en.wikipedia.org/wiki/Optical_path_length", "https://phys.libretexts.org/Bookshelves/Optics/Geometric_Optics_(Tatum)/02%3A_Optical_Path_Length", "https://www.britannica.com/science/optical-path-length"]'),
  ('optical_power_combination', '{"en-us": "Optical power of combined thin lenses"}', 'lenses', 7, '{"en-us": "When two thin lenses are placed in contact (or very close together) the combined optical power is the sum of the individual powers, because each lens adds its own convergence or divergence. Optical power is measured in dioptres (inverse metres); the rule fails if the separation between the lenses is not negligible compared with their focal lengths."}', '["https://en.wikipedia.org/wiki/Optical_power", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/02%3A_Geometric_Optics_and_Image_Formation", "https://www.britannica.com/science/optical-power", "https://opentextbc.ca/physics/chapter/16-3-the-simple-magnifier/"]'),
  ('optical_purity', '{"en-us": "Optical purity"}', 'organic_chemistry', 8, '{"en-us": "Optical purity is a measure of chiral purity expressed as the ratio of the observed specific rotation of a sample to the specific rotation of the enantiopure compound, usually given as a percentage. When the optical rotation of each enantiomer is proportional to its mole fraction, optical purity is numerically equal to the enantiomeric excess, although the two can diverge in cases such as concentration-dependent rotation or aggregation effects."}', '["https://en.wikipedia.org/wiki/Enantiomeric_excess", "https://goldbook.iupac.org/terms/view/O04310.html", "https://www.chemistrysteps.com/enantiomeric-excess/", "https://www.masterorganicchemistry.com/2012/04/09/racemic-mixtures-and-enantiomeric-excess/"]'),
  ('optical_transmittance', '{"en-us": "Optical transmittance"}', 'refraction', 6, '{"en-us": "Optical transmittance is the dimensionless ratio of radiant flux transmitted through a material to the incident flux, indicating the fraction of light that passes through. It depends on the angle of incidence, polarization, and the refractive indices of the materials at each interface, and is closely related to reflectance and absorptance by energy conservation."}', '["https://en.wikipedia.org/wiki/Transmittance", "https://phys.libretexts.org/Bookshelves/Optics/Geometric_Optics_(Tatum)/04:_Optical_Components/4.04:_Transmittance_and_Reflectance", "https://www.britannica.com/science/transmittance", "https://opentextbc.ca/universityphysicsv3/chapter/4-2-brewsters-angle/", "https://www.rp-photonics.com/transmittance.html"]'),
  ('optics_image_height_magnification', '{"en-us": "Image height from magnification"}', 'mirrors', 5, '{"en-us": "Linear (transverse) magnification of an optical system is the ratio of image height to object height, so the image height is simply the magnification multiplied by the object height. A negative value indicates the image is inverted relative to the object, which is characteristic of real images formed by converging mirrors and lenses."}', '["https://en.wikipedia.org/wiki/Magnification", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/02%3A_Images_Formed_by_Mirrors", "https://www.britannica.com/science/optical-magnification", "https://www.physicsclassroom.com/class/refln/Lesson-1/Image-Formation-and-Characteristics", "https://www.khanacademy.org/science/physics/geometric-optics/mirrors/v/object-image-height-converging-mirrors"]'),
  ('optics_total_internal_reflection_condition', '{"en-us": "Condition for total internal reflection"}', 'refraction', 6, '{"en-us": "Total internal reflection occurs when a wave traveling in an optically denser medium strikes a boundary with a less dense medium at an angle of incidence greater than the critical angle. Beyond this threshold Snell''s law cannot be satisfied, so the wave is entirely reflected back into the denser medium, with only an evanescent field penetrating across the interface."}', '["https://en.wikipedia.org/wiki/Total_internal_reflection", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/01%3A_The_Nature_of_Light", "https://www.britannica.com/science/total-internal-reflection", "https://www.physicsclassroom.com/class/refln/Lesson-3/Total-Internal-Reflection", "https://opentextbc.ca/physics152/chapter/25-1-the-interaction-of-waves-at-boundaries/"]'),
  ('orbital_angular_momentum_kepler', '{"en-us": "Kepler''s second law (areal velocity)"}', 'orbital_motion', 8, '{"en-us": "Kepler''s second law states that the line joining a planet to the Sun sweeps out equal areas in equal times, so the areal velocity is constant. Equivalently, the orbital angular momentum per unit mass is twice the rate at which area is swept out by the radius vector, a direct consequence of conservation of angular momentum in a central force field."}', '["https://en.wikipedia.org/wiki/Kepler%27s_laws_of_planetary_motion#Second_law", "https://en.wikipedia.org/wiki/Areal_velocity", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Dourmashkin)/06%3A_Central_Forces/6.02%3A_Kepler''s_Second_Law", "https://www.britannica.com/science/Keplers-laws-of-planetary-motion", "https://www.phys.libretexts.org/Bookshelves/Astronomy_and_Cosmology_TextMaps/Map%3A_Astronomy_(OpenStax)/3%3A_Orbits_and_Gravity/3.2%3A_Keplers_Laws_of_Planetary_Motion"]'),
  ('orbital_mechanical_energy', '{"en-us": "Orbital mechanical energy"}', 'orbital_motion', 8, '{"en-us": "The total mechanical energy of a bound two-body Keplerian orbit is negative and equal to minus the product of the gravitational constant, the two masses, divided by twice the semi-major axis. This constant combines the kinetic energy of orbital motion with the negative gravitational potential energy and is conserved throughout the orbit."}', '["https://en.wikipedia.org/wiki/Vis-viva_equation", "https://en.wikipedia.org/wiki/Specific_orbital_energy", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Dourmashkin)/06%3A_Central_Forces/6.04%3A_Energy_and_Orbits", "https://www.britannica.com/science/orbital-motion", "https://www.physicsclassroom.com/class/circles/Lesson-4/Kepler-s-Three-Laws"]'),
  ('orbital_velocity', '{"en-us": "Orbital velocity"}', 'orbital_motion', 6, '{"en-us": "For a small body in a circular orbit around a much more massive central body, the orbital velocity is the square root of the gravitational parameter divided by the orbital radius. It equals the circular speed at that radius and is the speed required for centripetal force to balance gravitational attraction in a closed circular orbit."}', '["https://en.wikipedia.org/wiki/Orbital_speed", "https://en.wikipedia.org/wiki/Circular_orbit", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Dourmashkin)/06%3A_Central_Forces/6.04%3A_Energy_and_Orbits", "https://www.britannica.com/science/orbital-motion", "https://www.physicsclassroom.com/class/circles/Lesson-4/Mathematics-of-Satellite-Motion"]'),
  ('orbital_velocity_escape_relation', '{"en-us": "Relation between orbital and escape velocity"}', 'escape_velocity', 7, '{"en-us": "The escape speed at a given distance from a primary body is √2 times the speed of a circular orbit at that same distance, because the potential energy of an orbiting object is minus twice its kinetic energy while escape requires their sum to be non-negative. The escape speed is also known as the second cosmic velocity and is independent of direction."}', '["https://en.wikipedia.org/wiki/Escape_velocity", "https://en.wikipedia.org/wiki/Orbital_speed", "https://en.wikipedia.org/wiki/Circular_orbit", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Dourmashkin)/05%3A_Circular_Motion/5.07%3A_Speed_and_Period_of_a_Satellite"]'),
  ('orbitals_in_subshell', '{"en-us": "Number of orbitals in a subshell"}', 'periodic_table', 5, '{"en-us": "A subshell designated by the azimuthal quantum number ℓ contains 2ℓ+1 orbitals (one for each allowed value of the magnetic quantum number mℓ from −ℓ to +ℓ). This underlies the periodic table''s blocks of 2, 6, 10, and 14 elements for the s, p, d, and f subshells, and reflects the fact that each orbital can hold at most two electrons of opposite spin."}', '["https://en.wikipedia.org/wiki/Atomic_orbital", "https://en.wikipedia.org/wiki/Electron_shell", "https://en.wikipedia.org/wiki/Azimuthal_quantum_number", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Quantum_Mechanics/09._The_Hydrogen_Atom/Atomic_Orbitals", "https://www.khanacademy.org/science/physics/quantum-physics/atoms-and-electrons/a/the-quantum-mechanical-model-of-the-atom"]'),
  ('organic_chemistry_index_hydrogen_deficiency', '{"en-us": "Index of hydrogen deficiency (IHD)"}', 'organic_chemistry', 7, '{"en-us": "The index of hydrogen deficiency (also called the degree of unsaturation or double bond equivalent) gives the total number of rings plus π bonds in an organic molecule from its molecular formula. Oxygen and other divalent atoms do not affect the count because they require no additional hydrogens relative to a saturated acyclic hydrocarbon skeleton."}', '["https://en.wikipedia.org/wiki/Degree_of_unsaturation", "https://en.wikipedia.org/wiki/Organic_chemistry", "https://chem.libretexts.org/Bookshelves/Organic_Chemistry/Supplemental_Modules_(Organic_Chemistry)/Fundamentals/Index_of_Hydrogen_Deficiency", "https://www.khanacademy.org/science/organic-chemistry/gen-chem-review/gold-book-video-series/v/organic-chemistry-fundamentals"]'),
  ('osmotic_pressure', '{"en-us": "Osmotic pressure"}', 'solutions', 7, '{"en-us": "Osmotic pressure is the minimum pressure that must be applied to a solution to stop the inward flow of pure solvent across a semipermeable membrane, and it is a colligative property. The van ''t Hoff relation gives the pressure as the product of the dimensionless van ''t Hoff factor (accounting for dissociating solutes), the molar solute concentration, the gas constant, and the absolute temperature, valid for dilute ideal solutions."}', '["https://en.wikipedia.org/wiki/Osmotic_pressure", "https://en.wikipedia.org/wiki/Van_%27t_Hoff_factor", "https://en.wikipedia.org/wiki/Colligative_property", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/Solutions_and_Mixtures/Colligative_Properties/Osmotic_Pressure"]'),
  ('otto_cycle_efficiency', '{"en-us": "Otto cycle efficiency"}', 'heat_engines', 9, '{"en-us": "The Otto cycle models an idealized spark-ignition internal combustion engine with two isentropic and two constant-volume (isochoric) processes, and its thermal efficiency depends only on the compression ratio r and the heat capacity ratio γ of the working gas. Real gasoline engines approach but cannot exceed this efficiency, and higher compression ratios give higher efficiency until knock limits the allowable ratio."}', '["https://en.wikipedia.org/wiki/Otto_cycle", "https://en.wikipedia.org/wiki/Heat_engine", "https://en.wikipedia.org/wiki/Thermal_efficiency", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Heat_and_Thermodynamics_(Tatum)/11%3A_Heat_Engines/11.03%3A_The_Otto_Cycle"]'),
  ('pair_production_threshold', '{"en-us": "Pair production threshold energy"}', 'particle_physics', 9, '{"en-us": "The minimum photon energy required for pair production equals twice the rest-mass energy of the produced particle, since energy must create both a particle and its antiparticle at rest. For an electron–positron pair this threshold is 2 m_e c² ≈ 1.022 MeV, and a nearby nucleus is required to conserve momentum."}', '["https://en.wikipedia.org/wiki/Pair_production", "https://en.wikipedia.org/wiki/Electron%E2%80%93positron_annihilation", "https://en.wikipedia.org/wiki/Photon", "https://phys.libretexts.org/Bookshelves/Modern_Physics/Book%3A_Nuclear_and_Particle_Physics_(Walet)/11%3A_Interactions_of_Photons_with_Matter/11.02%3A_Pair_Production"]'),
  ('parabola_vertex_form', '{"en-us": "Vertex form of a parabola"}', 'coordinate_geometry', 5, '{"en-us": "The vertex form writes a quadratic (parabola with vertical axis) as a vertical scaling plus a horizontal shift, making the vertex (h, k) and opening direction (sign of a) immediately visible. It is obtained from the general form by completing the square."}', '["https://en.wikipedia.org/wiki/Parabola", "https://math.libretexts.org/Bookshelves/Algebra/Intermediate_Algebra/Intermediate_Algebra_(OpenStax)/09%3A_Solving_Quadratic_Equations_and_Graphing_Parabolas/9.02%3A_Graphing_Quadratic_Functions_from_Standard_Form", "https://www.cuemath.com/geometry/vertex-form-of-a-parabola/", "https://www.khanacademy.org/math/algebra/x2f8bb11595b61c86:quadratic-functions-equations/x2f8bb11595b61c86:standard-form-vertex-form/v/vertex-form-introduction", "https://mathworld.wolfram.com/Parabola.html"]'),
  ('parallel_axis_theorem', '{"en-us": "Parallel axis theorem"}', 'moment_of_inertia', 8, '{"en-us": "The parallel axis theorem (Huygens-Steiner) relates the moment of inertia of a rigid body about any axis to its moment of inertia about a parallel axis through the center of mass, adding the body''s mass times the squared perpendicular distance between the axes. It is used to compute the inertia of composite bodies from a catalog of standard shapes."}', '["https://en.wikipedia.org/wiki/Parallel_axis_theorem", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10%3A_Fixed-Axis_Rotation/10.05%3A_Moments_of_Inertia", "https://scienceworld.wolfram.com/physics/ParallelAxisTheorem.html", "https://www.britannica.com/science/parallel-axis-theorem", "https://www.khanacademy.org/science/physics/torque-angular-momentum/rotational-inertia/v/moment-of-inertia"]'),
  ('parallel_capacitance', '{"en-us": "Capacitors in parallel"}', 'circuits', 5, '{"en-us": "When capacitors are connected in parallel, the same voltage appears across each, and the charges on each plate add. The total (equivalent) capacitance of the network is simply the sum of the individual capacitances, which is always greater than any single capacitance in the group."}', '["https://en.wikipedia.org/wiki/Series_and_parallel_circuits#Capacitors", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/08%3A_Capacitance/8.03%3A_Capacitors_in_Series_and_in_Parallel", "https://www.khanacademy.org/science/physics/circuits-topic/circuits-with-capacitors/v/capacitors-in-parallel", "https://www.electronics-tutorials.ws/capacitor/cap_4.html", "https://www.britannica.com/technology/capacitor/Capacitors-in-parallel"]'),
  ('parallel_lines_condition', '{"en-us": "Parallel lines condition"}', 'equations', 3, '{"en-us": "Two distinct non-vertical lines in the Cartesian plane are parallel if and only if they have the same slope. Vertical lines, which have undefined slope, are parallel to one another by convention when treated separately."}', '["https://en.wikipedia.org/wiki/Parallel_(geometry)", "https://math.libretexts.org/Bookshelves/Algebra/Intermediate_Algebra/Intermediate_Algebra_(OpenStax)/03%3A_Graphs_and_Functions/3.06%3A_Slope", "https://www.khanacademy.org/math/algebra/x2f8bb11595b61c86:linear-equations-graphs/x2f8bb11595b61c86:solving-slope-problems/v/slope-of-a-line", "https://www.britannica.com/biography/Euclid/Book-I-of-the-Elements"]'),
  ('parallel_plate_capacitance', '{"en-us": "Parallel plate capacitance"}', 'capacitance', 6, '{"en-us": "An ideal parallel-plate capacitor consists of two equal conducting plates of area A separated by a small distance d. Its capacitance is directly proportional to the plate area and inversely proportional to the separation, with the proportionality constant set by the permittivity of the dielectric between the plates (vacuum permittivity in the free-space case)."}', '["https://en.wikipedia.org/wiki/Capacitance", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/08%3A_Capacitance/8.02%3A_Parallel_Plate_Capacitor", "https://www.khanacademy.org/science/physics/circuits-topic/circuits-with-capacitors/v/parallel-plate-capacitor", "https://www.britannica.com/science/parallel-plate-capacitor", "https://hyperphysics.phy-astr.gsu.edu/hbase/electric/cappar.html"]'),
  ('parallel_resistance', '{"en-us": "Resistors in parallel (two)"}', 'circuits', 5, '{"en-us": "When two resistors are connected in parallel, they share the same voltage drop while the total current splits between them. The reciprocal of the equivalent resistance equals the sum of the reciprocals of the individual resistances, so the combined resistance is always less than the smallest individual resistance."}', '["https://en.wikipedia.org/wiki/Series_and_parallel_circuits#Resistance", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/09%3A_Current_and_Resistance/9.04%3A_Resistors_in_Series_and_Parallel", "https://www.khanacademy.org/science/physics/circuits-topic/circuits-with-resistors/v/parallel-resistors", "https://www.electronics-tutorials.ws/resistor/res_4.html", "https://www.britannica.com/science/parallel-resistance"]'),
  ('parallel_resistors_n_equal', '{"en-us": "Equivalent resistance of n equal parallel resistors"}', 'circuits', 5, '{"en-us": "When n identical resistors are wired in parallel, the equivalent resistance of the combination is the value of one resistor divided by the number of resistors. This special case of the parallel-resistance rule is widely used to design current dividers and to obtain standard resistance values from a single resistor stock."}', '["https://en.wikipedia.org/wiki/Resistor#Series_and_parallel_resistors", "https://en.wikipedia.org/wiki/Series_and_parallel_circuits", "https://en.wikipedia.org/wiki/Dalton%27s_law", "https://www.electronics-tutorials.ws/resistor/res_4.html", "https://www.khanacademy.org/science/physics/circuits-topic/circuits-resistance/a/parallel-circuits"]'),
  ('parametric_line_equation', '{"en-us": "Parametric form of a line"}', 'equations', 6, '{"en-us": "A straight line in the plane can be described by giving the coordinates of a point on the line and a direction vector, and letting a single parameter trace out all points. The parameter is usually denoted t (or s) and may represent time when the line describes the trajectory of a moving point."}', '["https://en.wikipedia.org/wiki/Parametric_equation", "https://en.wikipedia.org/wiki/Parametric_equation#Straight_line", "https://en.wikipedia.org/wiki/Line_(geometry)", "https://math.libretexts.org/Bookshelves/Precalculus/Book%3A_Precalculus_(Alder)/10%3A_Parametric_Equations_and_Polar_Coordinates/10.01%3A_Parametric_Equations", "https://www.britannica.com/science/parametric-equation"]'),
  ('partial_pressure_mole_fraction', '{"en-us": "Partial pressure from mole fraction"}', 'ideal_gases', 5, '{"en-us": "In an ideal-gas mixture, the partial pressure exerted by any component equals its mole fraction multiplied by the total pressure of the mixture. This is a direct consequence of Dalton''s law of partial pressures and follows from the fact that each gas in an ideal mixture behaves independently of the others."}', '["https://en.wikipedia.org/wiki/Partial_pressure", "https://en.wikipedia.org/wiki/Dalton%27s_law", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_-_The_Central_Science_(Brown_et_al.)/10%3A_Gases/10.06%3A_Gas_Mixtures_and_Partial_Pressures", "https://www.britannica.com/science/partial-pressure", "https://en.wikipedia.org/wiki/Mole_fraction"]'),
  ('particle_decay_constant_lifetime', '{"en-us": "Mean lifetime from decay constant"}', 'particle_physics', 7, '{"en-us": "The mean lifetime of an exponentially decaying population equals the reciprocal of the decay constant. It is the average time an individual member of the population survives, related to the half-life by a factor of ln(2)."}', '["https://en.wikipedia.org/wiki/Exponential_decay", "https://en.wikipedia.org/wiki/Exponential_decay#Mean_lifetime", "https://en.wikipedia.org/wiki/Radioactive_decay", "https://en.wikipedia.org/wiki/Half-life", "https://www.nist.gov/pml/radioactivity/radioactive-decay"]'),
  ('particle_in_a_box_energy', '{"en-us": "Particle in a box energy levels"}', 'quantum_mechanics', 9, '{"en-us": "A particle confined to a one-dimensional box with infinitely high walls can only occupy discrete energy levels, which scale with the square of an integer quantum number. This simple model, sometimes called the infinite square well, is the standard pedagogical example used to introduce quantization in quantum mechanics and illustrates how wave-like boundary conditions restrict the allowed energies of a bound particle."}', '["https://en.wikipedia.org/wiki/Particle_in_a_box", "https://en.wikipedia.org/wiki/Particle_in_a_box#Energy_levels", "https://en.wikipedia.org/wiki/Infinite_potential_well", "https://en.wikipedia.org/wiki/Schr%C3%B6dinger_equation", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Quantum_Mechanics/05.1%3A_Particle_in_a_1-Dimensional_Box"]'),
  ('particle_physics_invariant_mass_calculation', '{"en-us": "Invariant mass from energy and momentum"}', 'particle_physics', 9, '{"en-us": "The invariant (rest) mass of a particle is the Lorentz-invariant length of its four-momentum, obtained by combining the total energy and momentum measured in any frame. This relation underlies particle-identification techniques in collider experiments, where the invariant mass of decay products is used to determine the mass of the parent particle."}', '["https://en.wikipedia.org/wiki/Invariant_mass", "https://en.wikipedia.org/wiki/Invariant_mass#As_defined_in_particle_physics", "https://en.wikipedia.org/wiki/Energy%E2%80%93momentum_relation", "https://en.wikipedia.org/wiki/Four-momentum", "https://www.britannica.com/science/invariant-mass"]'),
  ('particle_width_lifetime_relation', '{"en-us": "Particle decay width and lifetime"}', 'particle_physics', 9, '{"en-us": "The decay width Γ of an unstable particle (resonance) is inversely related to its mean lifetime τ through the uncertainty principle. With natural units (ħ=1) the relation is τ = 1/Γ, and with conventional units Γ = h/(2πτ). Wider resonances correspond to shorter-lived particles, a relationship central to scattering and particle spectroscopy."}', '["https://en.wikipedia.org/wiki/Relativistic_Breit%E2%80%93Wigner_distribution", "https://en.wikipedia.org/wiki/Decay_width", "https://phys.libretexts.org/Bookshelves/Quantum_Mechanics/Quantum_Mechanics_(Boundless)/05%3A_Uncertainty_and_Commutation_Relations/5.3%3A_Heisenberg_Uncertainty_Principle", "https://pdg.lbl.gov/2024/reviews/rpp2024-rev-kinematics.pdf"]'),
  ('partition_coefficient', '{"en-us": "Partition coefficient"}', 'analytical_chemistry', 7, '{"en-us": "The partition coefficient (K or P) is the ratio of concentrations of a solute between two immiscible solvents at equilibrium, typically reported as the concentration in the organic phase divided by that in the aqueous phase. It is widely used in pharmaceutical and environmental chemistry to characterize lipophilicity, with log P being the common logarithmic form."}', '["https://en.wikipedia.org/wiki/Partition_coefficient", "https://goldbook.iupac.org/terms/view/P04440", "https://pubchem.ncbi.nlm.nih.gov/descriptor/Partition_Coefficient", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/Solutions_and_Mixtures/Partition_and_Distribution_Coefficients", "https://www.chem.purdue.edu/courses/chm333/Spring%202014/Lectures/Lecture%2023%20Partition%20Coefficients.pdf"]'),
  ('parts_per_formula', '{"en-us": "Parts per billion"}', 'solution_stoichiometry', 4, '{"en-us": "Parts per billion (ppb) is a dimensionless quantity expressing a mass (or mole) ratio as a fraction of 10⁻⁹. It is commonly used to report trace concentrations of dissolved substances, pollutants, or impurities, with the ratio of solute mass to total solution mass multiplied by 10⁹."}', '["https://en.wikipedia.org/wiki/Parts-per_notation", "https://www.bipm.org/en/publications/si-brochure", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Quantitative_Analysis/04%3A_General_Aspects_of_Quantitative_Analysis/4.3%3A_Parts_per_Million_and_Other_Parts_per_Notation", "https://www.nist.gov/pml/special-publication-811"]'),
  ('pascal_hydraulic_press_force', '{"en-us": "Pascal''s principle (hydraulic press)"}', 'pascals_law', 5, '{"en-us": "Pascal''s principle applied to a hydraulic press: when an input force is applied to a small piston, the transmitted pressure acts on the larger output piston, producing a proportionally larger output force equal to the input force times the area ratio. Energy is conserved because the larger piston moves a correspondingly smaller distance."}', '["https://en.wikipedia.org/wiki/Pascal%27s_law", "https://www.britannica.com/science/Pascals-principle", "https://www.grc.nasa.gov/www/k-12/WindTunnel/Activities/Pascals_principle.html", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.05%3A_Pascal''s_Principle", "https://www.physicsclassroom.com/class/fluids/Lesson-3/Pascal-s-Principle"]'),
  ('pascals_law', '{"en-us": "Pascal''s law (hydraulic lift)"}', 'pascals_law', 5, '{"en-us": "Pascal''s law applied to a hydraulic lift: the pressure (force per unit area) on a small piston equals the pressure on a large piston, so the output force scales with piston area. This pressure equality is the principle behind hydraulic jacks, brakes, and presses."}', '["https://en.wikipedia.org/wiki/Pascal%27s_law", "https://www.britannica.com/science/Pascals-principle", "https://www.grc.nasa.gov/www/k-12/WindTunnel/Activities/Pascals_principle.html", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.05%3A_Pascal''s_Principle", "https://courses.lumenlearning.com/physics/chapter/11-4-pascals-principle/"]'),
  ('pascals_law_hydraulic_pressure_ratio', '{"en-us": "Hydraulic pressure ratio (Pascal''s law)"}', 'pascals_law', 5, '{"en-us": "Pascal''s law states that a change in pressure applied to a confined incompressible fluid is transmitted undiminished throughout the fluid, so the pressure applied at one piston equals the pressure at any other point in the fluid. This is the foundational statement of Pascal''s principle in fluid statics."}', '["https://en.wikipedia.org/wiki/Pascal%27s_law", "https://www.britannica.com/science/Pascals-principle", "https://www.grc.nasa.gov/www/k-12/WindTunnel/Activities/Pascals_principle.html", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.05%3A_Pascal''s_Principle", "https://courses.lumenlearning.com/suny-physics/chapter/11-3-the-simplest-case-of-pascals-law/"]'),
  ('pendulum_period', '{"en-us": "Period of a simple pendulum"}', 'harmonic_motion', 5, '{"en-us": "The period of a simple pendulum, also called the small-angle approximation, is independent of the mass of the bob and of the swing amplitude (provided the angle is small). It depends only on the pendulum length and the local gravitational acceleration, which is the basis for using pendulums as clocks and gravimeters."}', '["https://en.wikipedia.org/wiki/Pendulum#Period_of_oscillation", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/16%3A_Oscillations/16.03%3A_Period_of_a_Simple_Pendulum", "https://www.khanacademy.org/science/physics/mechanical-waves-and-sound/harmonic-motion/v/simple-pendulum", "https://www.britannica.com/science/pendulum", "https://openstax.org/books/university-physics-volume-1/pages/16-3-period-of-a-simple-pendulum"]'),
  ('percent_composition', '{"en-us": "Percent composition"}', 'chemical_reactions', 4, '{"en-us": "Percent composition expresses the mass fraction of each element in a chemical compound, as a percentage of the compound''s total mass. It is determined experimentally by elemental analysis (such as CHNX combustion analysis) and is widely used to verify purity and to deduce empirical formulas."}', '["https://en.wikipedia.org/wiki/Elemental_analysis", "https://chem.libretexts.org/Bookshelves/General_Chemistry/General_Chemistry_Supplement_(Eames)/Chemical_Composition/Percent_Composition", "https://www.khanacademy.org/science/chemistry/chemical-reactions-stoichiometry/stoichiometry-ideal/v/stoichiometry-3", "https://chem.libretexts.org/Bookshelves/Introductory_Chemistry/Introductory_Chemistry/06%3A_Chemical_Composition/6.05%3A_Percent_Composition", "https://www.britannica.com/science/elemental-analysis"]'),
  ('percent_composition_element', '{"en-us": "Percent composition of an element"}', 'organic_chemistry', 4, '{"en-us": "The percent composition of a specific element in a compound equals the total mass of that element per formula unit divided by the molar mass of the whole compound, expressed as a percentage. It is used in combustion analysis to confirm the empirical and molecular formulas of unknown compounds."}', '["https://en.wikipedia.org/wiki/Elemental_analysis", "https://chem.libretexts.org/Bookshelves/General_Chemistry/General_Chemistry_Supplement_(Eames)/Chemical_Composition/Percent_Composition", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_-_The_Central_Science_(Brown_et_al.)/03%3A_Stoichiometry%3A_Counting_Atoms_and_Molecules/3.3%3A_Percent_Composition_and_Empirical_Formulas", "https://www.thoughtco.com/percent-composition-by-mass-chemistry-609585", "https://www.britannica.com/science/elemental-analysis"]'),
  ('percent_ionic_character', '{"en-us": "Percent ionic character"}', 'chemical_bonding', 7, '{"en-us": "Pauling''s empirical relation estimates the percent ionic character of a covalent bond from the electronegativity difference between the bonded atoms. The function approaches 100% as the difference grows and is small for bonds between atoms of similar electronegativity."}', '["https://en.wikipedia.org/wiki/Electronegativity#Methods_of_calculation", "https://chem.libretexts.org/Bookshelves/General_Chemistry/General_Chemistry_Supplement_(Eames)/Chemical_Bonding_I%3A_The_Ionic_Covalent_Bond_Continuum/Case_Study%3A_Percent_Ionic_Character", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Chemical_Bonding/Fundamentals_of_Chemical_Bonding/Pauling%27s_Equation", "https://chem.libretexts.org/Bookshelves/Inorganic_Chemistry/Inorganic_Chemistry_(LibreTexts)/05%3A_Chemical_Reactivity/5.1%3A_Chemical_Bonding/Pauling%27s_Electronegativity_Equation", "https://www.chem.purdue.edu/gchelp/gloss/electroneg.html"]'),
  ('percent_ionization', '{"en-us": "Percent ionization of a weak acid"}', 'acids_and_bases', 7, '{"en-us": "Percent ionization is the fraction of an initially dissolved weak acid that has dissociated into ions at equilibrium, expressed as a percentage. It is used to assess acid strength and depends on both the acid dissociation constant and the initial concentration, generally decreasing as the acid is diluted."}', '["https://en.wikipedia.org/wiki/Acid_strength#Weak_acids", "https://en.wikipedia.org/wiki/Acid_dissociation_constant", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Acids_and_Bases/Ionization_Constants/Percent_Ionization", "https://www.khanacademy.org/science/chemistry/acids-and-bases-topic/acids-and-bases/a/weak-acid-equilibrium", "https://www.thoughtco.com/percent-ionization-609605"]'),
  ('percent_yield', '{"en-us": "Percent yield"}', 'percent_yield', 5, '{"en-us": "Percent yield compares the amount of product actually obtained from a chemical reaction to the maximum amount predicted from stoichiometry (the theoretical yield). It is a key practical measure of reaction efficiency, accounting for losses from side reactions, incomplete conversion, and product purification."}', '["https://en.wikipedia.org/wiki/Yield_(chemistry)", "https://chem.libretexts.org/Bookshelves/General_Chemistry/General_Chemistry_Supplement_(Eames)/Stoichiometry/Percent_Yield", "https://www.khanacademy.org/science/chemistry/chemical-reactions-stoichiometry/limiting-reagent-stoichiometry/v/theoretical-yield-and-limiting-reagents", "https://www.thoughtco.com/calculate-percent-yield-609580", "https://www.britannica.com/science/chemical-yield"]'),
  ('percent_yield_atom_economy', '{"en-us": "Atom economy"}', 'percent_yield', 6, '{"en-us": "Atom economy, introduced by Barry Trost in 1991, is a measure of how efficiently a chemical reaction incorporates the atoms of its reactants into the desired product. It is a key metric of green chemistry and complements percent yield, because even a high-yielding reaction can produce large amounts of unwanted byproducts. The ideal value is 100%, achieved only when every reactant atom ends up in the target molecule."}', '["https://en.wikipedia.org/wiki/Atom_economy", "https://chem.libretexts.org/Bookshelves/Organic_Chemistry/Supplemental_Modules_(Organic_Chemistry)/Reactions/Case_Studies/Green_Chemistry/Atom_Economy", "https://www.acs.org/education/whatischemistry/landmarks/greenerx.html", "https://www.bbc.co.uk/bitesize/guides/zqcrq6f/revision/2", "https://www.thoughtco.com/definition-of-atom-economy-605810"]'),
  ('percent_yield_fractional_conversion', '{"en-us": "Fractional conversion to percent yield"}', 'percent_yield', 5, '{"en-us": "In a single-reaction process with no competing side products, the selectivity is unity and the fractional conversion of the limiting reactant equals the fractional yield. The percent yield is therefore simply 100 times the fractional conversion. For multi-reaction systems the relation generalises to Y = X·S, where S is the selectivity to the desired product."}', '["https://en.wikipedia.org/wiki/Conversion_(chemistry)", "https://en.wikipedia.org/wiki/Yield_(chemistry)", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Kinetics/Reaction_Rates/Conversion_and_Yield", "https://www.thoughtco.com/definition-of-percent-yield-in-chemistry-606345"]'),
  ('percent_yield_from_actual', '{"en-us": "Percent yield from actual and theoretical"}', 'chemical_reactions', 5, '{"en-us": "Percent yield compares the actual mass of product isolated from a laboratory reaction to the maximum mass predicted by stoichiometry (the theoretical yield) and expresses the result as a percentage. The theoretical yield assumes the limiting reagent is fully converted with no losses, so a percent yield below 100% reflects incomplete reaction, side products, and material lost during isolation and purification. It is the most commonly reported measure of reaction efficiency in synthetic chemistry."}', '["https://en.wikipedia.org/wiki/Yield_(chemistry)", "https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/04%3A_The_Basics_of_Chemistry/4.08%3A_Reaction_Yields", "https://www.thoughtco.com/percent-yield-definition-606345", "https://www.khanacademy.org/science/ap-chemistry/stoichiometry-ideal/ap-ch-percent-yield/v/percent-yield", "https://www.bbc.co.uk/bitesize/guides/zqcrq6f/revision/3"]'),
  ('percent_yield_sequential_reactions', '{"en-us": "Overall percent yield for multi-step synthesis"}', 'percent_yield', 7, '{"en-us": "In a linear multi-step synthesis each intermediate is the product of one reaction and the substrate of the next, so the overall percent yield is the product of the individual step yields. Because each step is typically less than quantitative, the overall yield falls off rapidly with the number of steps—for example, five steps each at 80% give only about 33% overall. Convergent syntheses, which combine independently prepared fragments, are often favoured for complex targets because their effective step count is shorter."}', '["https://en.wikipedia.org/wiki/Yield_(chemistry)", "https://en.wikipedia.org/wiki/Total_synthesis", "https://en.wikipedia.org/wiki/Convergent_synthesis", "https://www.organic-chemistry.org/Highlights/totalsynthesis.shtm", "https://www.chem.wisc.edu/areas/reich/syntheses/syntheses.htm"]'),
  ('percentage_difference', '{"en-us": "Percentage difference"}', 'arithmetic', 3, '{"en-us": "Percentage difference expresses how far apart two values are as a fraction of their average size, so the order of a and b does not affect the result. It is widely used in science and engineering to compare an experimental measurement to a reference value or to quantify the discrepancy between two measurements of the same quantity. The conventional form uses absolute values in the denominator to keep the result defined for numbers of mixed sign."}', '["https://en.wikipedia.org/wiki/Relative_change", "https://en.wikipedia.org/wiki/Relative_difference", "https://www.calculatorsoup.com/calculators/algebra/percent-difference-calculator.php", "https://www.mathsisfun.com/numbers/percentage-difference.html", "https://www.thoughtco.com/percentage-difference-formula-3126262"]'),
  ('percentage_error', '{"en-us": "Percentage error"}', 'arithmetic', 3, '{"en-us": "Percentage error quantifies the difference between an experimental measurement and a theoretical (accepted) value, normalised by the magnitude of the theoretical value and expressed as a percentage. It is widely used in experimental sciences to express the accuracy of a measurement, and its sign convention preserves the direction of the deviation (positive when the experimental value exceeds the accepted value). The formula is undefined when the theoretical value is exactly zero."}', '["https://en.wikipedia.org/wiki/Approximation_error", "https://en.wikipedia.org/wiki/Relative_change", "https://mathworld.wolfram.com/PercentageError.html", "https://www.thoughtco.com/percentage-error-formula-3126206", "https://www.khanacademy.org/math/statistics-probability/summarizing-quantitative-data/more-on-standard-deviation/v/population-standard-deviation-example"]'),
  ('percentage_formula', '{"en-us": "Percentage"}', 'arithmetic', 1, '{"en-us": "A percentage expresses a number as a fraction of one hundred, denoted by the percent sign (%). It is a dimensionless number used to indicate a proportionate share of a whole, and the value is obtained by multiplying the ratio of the part to the whole by 100."}', '["https://en.wikipedia.org/wiki/Percentage", "https://en.wikipedia.org/wiki/Percent_sign", "https://www.britannica.com/topic/percentage", "https://math.libretexts.org/Courses/Arkansas_State_University-Beebe/MATH11103_Quantitative_Literacy/01%3A_Unit_I_Essentials/1.03%3A_Percentages"]'),
  ('perfect_square_diff', '{"en-us": "Perfect square of a difference"}', 'polynomials', 3, '{"en-us": "The square of a binomial difference expands to a perfect square trinomial in which the cross term is subtracted. This identity is the algebraic basis for the technique known as completing the square, and it factors back into the original binomial squared."}', '["https://en.wikipedia.org/wiki/Factorization", "https://en.wikipedia.org/wiki/Polynomial", "https://math.libretexts.org/Bookshelves/Algebra/Intermediate_Algebra", "https://www.cuemath.com/algebra/perfect-square-trinomial/"]'),
  ('perfect_square_sum', '{"en-us": "Perfect square of a sum"}', 'polynomials', 3, '{"en-us": "The square of a binomial sum expands to a perfect square trinomial with a positive cross term, a common pattern used in expanding polynomials and in completing the square. The result factors back into the original binomial squared."}', '["https://en.wikipedia.org/wiki/Factorization", "https://en.wikipedia.org/wiki/Polynomial", "https://math.libretexts.org/Bookshelves/Algebra/Intermediate_Algebra", "https://www.cuemath.com/algebra/perfect-square-trinomial/"]'),
  ('perfectly_inelastic_collision', '{"en-us": "Perfectly inelastic collision"}', 'collisions', 6, '{"en-us": "In a perfectly inelastic collision the two bodies stick together and move with a common final velocity, so that kinetic energy is lost (in the center-of-mass frame) while total linear momentum is conserved. The single scalar relation between the initial and final velocities follows directly from conservation of momentum."}', '["https://en.wikipedia.org/wiki/Inelastic_collision", "https://en.wikipedia.org/wiki/Momentum", "https://en.wikipedia.org/wiki/Conservation_of_momentum", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/09%3A_Linear_Momentum_and_Collisions/9.07%3A_Types_of_Collisions"]'),
  ('periodic_atomic_number_composition', '{"en-us": "Atomic number from composition"}', 'periodic_table', 3, '{"en-us": "The atomic number (Z) of an element is defined as the number of protons in the nucleus, which uniquely identifies the element. In an electrically neutral atom, this is also equal to the number of electrons, and it is what determines the element''s position in the periodic table."}', '["https://en.wikipedia.org/wiki/Atomic_number", "https://en.wikipedia.org/wiki/Chemical_element", "https://en.wikipedia.org/wiki/Proton", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_Chemistry_-_The_Central_Science_(Brown_et_al.)/02%3A_Atoms_Molecules_and_Ions/2.03%3A_The_Atomic_Structure"]'),
  ('periodic_quantum_number_azimuthal_range', '{"en-us": "Range of azimuthal quantum number"}', 'periodic_table', 6, '{"en-us": "For a given principal quantum number n, the azimuthal (orbital angular momentum) quantum number ℓ takes integer values from 0 to n−1, so the maximum allowed value is n−1. These ℓ values are commonly labelled s, p, d, f, ... and describe the shape of an electron''s atomic orbital."}', '["https://en.wikipedia.org/wiki/Azimuthal_quantum_number", "https://en.wikipedia.org/wiki/Principal_quantum_number", "https://en.wikipedia.org/wiki/Quantum_number", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Map%3A_Physical_Chemistry_(McQuarrie_and_Simon)/02%3A_Quantum_Theory/2.02%3A_The_Allowed_Quantum_Numbers"]'),
  ('periodic_valence_electrons_formula', '{"en-us": "Valence electrons from group number"}', 'periodic_table', 4, '{"en-us": "For main-group elements the number of valence electrons equals the group number in groups 1–2 and 13–18 (using the units digit for the latter); the relationship is less clean for transition metals where d-electrons also contribute. This rule is widely used as a teaching shortcut for predicting bonding behavior and oxidation states."}', '["https://en.wikipedia.org/wiki/Valence_electron", "https://en.wikipedia.org/wiki/Periodic_table_group", "https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/05%3A_The_Structure_of_Atoms/5.10%3A_Periodic_Trends_in_Atomization_Energies_and_Electron_Configurations", "https://www.khanacademy.org/science/chemistry/periodic-table-trends-bonding/periodic-table-trends/v/the-periodic-table-classification-of-elements"]'),
  ('permeability_relation', '{"en-us": "Permeability relation"}', 'magnetism', 7, '{"en-us": "The absolute permeability of a medium equals its relative permeability (a dimensionless factor) multiplied by the permeability of free space, allowing the magnetic response of any material to be expressed relative to vacuum."}', '["https://en.wikipedia.org/wiki/Permeability_(electromagnetism)", "https://en.wikipedia.org/wiki/Relative_permeability", "https://en.wikipedia.org/wiki/Vacuum_permeability", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields/12.04%3A_Magnetic_Field_of_a_Current_Loop", "https://www.khanacademy.org/science/physics/magnetic-forces-and-magnetic-fields-and-induction/magnetic-field-current-carrying-wire/v/magnetic-permeability"]'),
  ('permittivity_relation', '{"en-us": "Permittivity relation"}', 'electrostatics', 7, '{"en-us": "The absolute permittivity of a dielectric medium equals its relative permittivity (a dimensionless factor, sometimes called the dielectric constant) multiplied by the permittivity of free space. This relation is used in Gauss''s law, capacitance calculations, and the Coulomb force constant."}', '["https://en.wikipedia.org/wiki/Permittivity", "https://en.wikipedia.org/wiki/Relative_permittivity", "https://en.wikipedia.org/wiki/Vacuum_permittivity", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/11%3A_Electric_Force_between_Charges/11.02%3A_Coulomb''s_Law", "https://www.khanacademy.org/science/physics/circuits-topic/circuits-with-capacitors/v/capacitance"]'),
  ('permutations', '{"en-us": "Number of permutations"}', 'probability', 5, '{"en-us": "The number of ordered arrangements of r distinct items chosen from n distinct items, sometimes called k-permutations of n. It is the foundation of counting problems in probability, cryptography, and the analysis of sorting algorithms."}', '["https://en.wikipedia.org/wiki/Permutation", "https://en.wikipedia.org/wiki/Factorial", "https://math.libretexts.org/Bookshelves/Combinatorics_and_Discrete_Mathematics/Book%3A_Combinatorics_(Hegarty)/02%3A_Applications_of_Basic_Counting/2.02%3A_Permutations", "https://www.khanacademy.org/math/statistics-probability/counting-permutations-and-combinations/permutations/v/permutation-formula", "https://www.britannica.com/science/permutation-mathematics"]'),
  ('perpendicular_lines_condition', '{"en-us": "Perpendicular lines condition"}', 'equations', 4, '{"en-us": "In the Cartesian plane, two non-vertical lines are perpendicular if and only if the product of their slopes is negative one. This is the classical slope-based test for right angles between lines."}', '["https://en.wikipedia.org/wiki/Perpendicular", "https://en.wikipedia.org/wiki/Slope", "https://math.libretexts.org/Bookshelves/Algebra/Intermediate_Algebra/06%3A_Graphing_Linear_Equations_and_Inequalities/6.05%3A_Slope_of_a_Line", "https://www.khanacademy.org/math/algebra/x2f8bb11595b61c86:linear-equations-graphs/x2f8bb11595b61c86:slope/v/slope-of-a-line"]'),
  ('ph_definition', '{"en-us": "Definition of pH"}', 'acids_and_bases', 5, '{"en-us": "pH is the negative base-10 logarithm of the hydrogen ion activity, used to specify the acidity or basicity of aqueous solutions. Values below 7 are acidic and values above 7 are basic at 25 °C; the scale is widely used in chemistry, biology, and environmental science."}', '["https://en.wikipedia.org/wiki/PH", "https://en.wikipedia.org/wiki/Hydronium", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/16%3A_Acids_and_Bases/16.04%3A_The_pH_Scale", "https://www.khanacademy.org/science/chemistry/acids-and-bases-topic/acids-and-bases/a/ph-poh-and-the-ph-scale", "https://www.britannica.com/science/pH"]'),
  ('ph_poh_relation', '{"en-us": "pH and pOH relation"}', 'acids_and_bases', 5, '{"en-us": "Aqueous solutions at 25 °C have an ionic product of water Kw = 1.0 × 10⁻¹⁴, which means the acid and base exponents always sum to a constant. The relation is exact only at about 24.87 °C and should be regarded as an approximation at other temperatures."}', '["https://en.wikipedia.org/wiki/PH#pOH", "https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/06%3A_Chemical_Equilibrium/6.13%3A_The_pH_and_pOH_Concepts_-_Ways_to_Express_Acidity_and_Basicity", "https://www.khanacademy.org/science/chemistry/acids-and-bases-topic/acids-and-bases/a/the-ph-scale", "https://www.chem.purdue.edu/~chembio/PopularTopics/pH.html", "https://courses.lumenlearning.com/introchem/chapter/the-ph-scale/"]'),
  ('phase_difference', '{"en-us": "Phase difference from path difference"}', 'wave_interference', 7, '{"en-us": "Converts a geometric path difference into a phase difference for two coherent waves of the same wavelength. The relation follows directly from the wave number k = 2π/λ and assumes both waves travel in the same medium."}', '["https://en.wikipedia.org/wiki/Phase_(waves)#For_shifted_signals", "https://en.wikipedia.org/wiki/Wave_interference#Between_two_plane_waves", "https://www.khanacademy.org/science/physics/light-waves/interference-of-light-waves/a/constructive-and-destructive-interference", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/03%3A_Interference_of_Light_Waves", "https://www.toppr.com/guides/physics-formulas/path-difference-formula/"]'),
  ('phase_shift_on_reflection', '{"en-us": "Phase shift on reflection"}', 'interference', 7, '{"en-us": "When a wave reflects off a boundary where the wave speed decreases (e.g., light entering a medium of higher refractive index), the reflected wave is inverted, acquiring a π radian (180°) phase shift. Waves reflecting from a faster medium back into a slower one experience no such shift."}', '["https://en.wikipedia.org/wiki/Reflection_phase_change", "http://hyperphysics.phy-astr.gsu.edu/hbase/phyopt/interf.html#c2", "https://www.acs.psu.edu/drussell/Demos/reflect/reflect.html", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/03%3A_Interference_of_Light_Waves", "https://opentextbc.ca/universityphysicsv3/chapter/3-2-interference-of-light-waves/"]'),
  ('photoelectric_equation', '{"en-us": "Photoelectric equation"}', 'quantum_mechanics', 7, '{"en-us": "Einstein''s 1905 photoelectric equation relates the maximum kinetic energy of electrons ejected from a metal to the frequency of the incident light. Below the threshold frequency (hν < φ) no electrons are emitted, regardless of light intensity, supporting the quantum nature of light."}', '["https://en.wikipedia.org/wiki/Photoelectric_effect#Theoretical_explanation", "https://www.khanacademy.org/science/physics/quantum-physics/photoelectric-effect/a/photoelectric-effect", "https://physics.info/photoelectric/", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Physical_Chemistry_(LibreTexts)/02%3A_Introduction_to_Quantum_Mechanics/2.01%3A_The_Photoelectric_Effect", "https://opentextbc.ca/universityphysicsv3/chapter/6-2-the-photoelectric-effect/"]'),
  ('photon_energy', '{"en-us": "Photon energy"}', 'quantum_mechanics', 6, '{"en-us": "The energy of a single photon is directly proportional to the frequency of the associated electromagnetic radiation, with the proportionality constant being the Planck constant. It establishes the quantum granularity of light and is the foundation of the Planck–Einstein relation."}', '["https://en.wikipedia.org/wiki/Photon#Energy_and_momentum", "https://en.wikipedia.org/wiki/Photon_energy", "https://www.khanacademy.org/science/physics/quantum-physics/photons/a/photons", "https://physics.info/photoelectric/", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Physical_Chemistry_(LibreTexts)/02%3A_Introduction_to_Quantum_Mechanics"]'),
  ('photon_momentum', '{"en-us": "Photon momentum"}', 'quantum_mechanics', 7, '{"en-us": "A photon carries momentum even though it has zero rest mass, a direct consequence of special relativity applied to a massless particle. The de Broglie relation p = h/λ applies to photons and links their particle-like and wave-like descriptions."}', '["https://en.wikipedia.org/wiki/Photon#Energy_and_momentum", "https://en.wikipedia.org/wiki/Photon_momentum", "https://www.khanacademy.org/science/physics/quantum-physics/photons/a/photon-momentum", "https://courses.lumenlearning.com/suny-physics/chapter/29-4-photon-momenta-and-compton-scattering/", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/06%3A_Photons_and_Matter_Waves/6.05%3A_Compton_Scattering"]'),
  ('physics_galilean_relativity', '{"en-us": "Galilean velocity addition"}', 'relativity', 5, '{"en-us": "Relates the velocity of a body in one reference frame to its velocity in another frame moving uniformly with respect to the first, an addition rule valid in the Newtonian (non-relativistic) limit where relative speeds are much smaller than the speed of light. It is the classical counterpart of the relativistic velocity-addition formula and embodies the assumption of absolute time shared by all inertial observers."}', '["https://en.wikipedia.org/wiki/Galilean_transformation", "https://en.wikipedia.org/wiki/Galilean_invariance", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Dourmashkin)/25%3A_Relativity", "https://www.britannica.com/science/Galilean-transformation", "https://mathworld.wolfram.com/GalileanTransformation.html"]'),
  ('pi_bond_count', '{"en-us": "Pi bond count in multiple bonds"}', 'chemical_bonding', 6, '{"en-us": "The number of pi bonds in a multiple bond equals the bond order minus the number of sigma bonds, since each multiple bond consists of one sigma bond plus additional pi bonds (e.g. one pi bond in a double bond, two in a triple bond). The relation is used to count pi bonds from a Lewis structure when determining molecular geometry, hybridization, and reactivity."}', '["https://en.wikipedia.org/wiki/Pi_bond", "https://en.wikipedia.org/wiki/Bond_order", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Chemical_Bonding/Fundamentals_of_Chemical_Bonding/Bond_Order_and_Lengths", "https://www.britannica.com/science/pi-bond", "https://www.chemistrysteps.com/bond-order-and-lengths/"]'),
  ('pka_definition', '{"en-us": "pKa from Ka"}', 'acids_and_bases', 6, '{"en-us": "Defines pKa as the negative base-10 logarithm of the acid dissociation constant Ka, providing a convenient logarithmic scale on which stronger acids have smaller (or more negative) pKa values. It is the standard way to report and compare the strengths of weak acids in chemistry, biochemistry, and pharmacology."}', '["https://en.wikipedia.org/wiki/Acid_dissociation_constant", "https://en.wikipedia.org/wiki/PKa", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Acids_and_Bases/Ionization_Constants/Calculating_ionization_constants_using_pKa", "https://www.britannica.com/science/pKa", "https://www.chem.purdue.edu/labs/weller/pdf/Finding_pKa.pdf"]'),
  ('planck_radiation_law_energy_density', '{"en-us": "Planck''s law for blackbody radiation"}', 'quantum_mechanics', 9, '{"en-us": "Gives the spectral energy density of electromagnetic radiation inside a blackbody cavity in thermal equilibrium as a function of frequency and temperature, resolving the ultraviolet catastrophe of classical Rayleigh–Jeans theory. It introduced energy quantization and is the foundation of quantum mechanics and modern radiation physics."}', '["https://en.wikipedia.org/wiki/Planck%27s_law", "https://en.wikipedia.org/wiki/Black-body_radiation", "https://phys.libretexts.org/Bookshelves/Quantum_Mechanics/Introduction_to_Quantum_Mechanics_(Cresser)/04%3A_Blackbody_Radiation", "https://www.britannica.com/science/Plancks-radiation-law", "https://hyperphysics.phy-astr.gsu.edu/hbase/mod6.html"]'),
  ('planck_relation_hbar', '{"en-us": "Planck relation (reduced Planck constant)"}', 'quantum_mechanics', 8, '{"en-us": "Relates the energy of a photon to its angular frequency through the reduced Planck constant (h-bar, h divided by two pi), the form of the Planck–Einstein relation most often used in quantum mechanics. It is the temporal component of the relativistic four-momentum carried by a photon and underlies quantization across quantum theory."}', '["https://en.wikipedia.org/wiki/Planck_constant", "https://en.wikipedia.org/wiki/Reduced_Planck_constant", "https://phys.libretexts.org/Bookshelves/Quantum_Mechanics/Quantum_Mechanics_(McIntyre)/02%3A_Mathematical_Background", "https://www.britannica.com/science/Planck-constant", "https://hyperphysics.phy-astr.gsu.edu/hbase/quantum/quantpho.html"]'),
  ('plane_geometry_polygon_area_triangulation', '{"en-us": "Area of a polygon by triangulation"}', 'plane_geometry', 4, '{"en-us": "Any simple polygon can be divided into non-overlapping triangles whose vertices are vertices of the polygon (a triangulation), and the polygon''s total area is the sum of the areas of those triangles. This decomposition reduces general polygon area computation to repeated triangle area calculations and is the conceptual basis of many computational geometry algorithms."}', '["https://en.wikipedia.org/wiki/Polygon", "https://en.wikipedia.org/wiki/Triangle#Computing_the_area_of_a_triangle", "https://en.wikipedia.org/wiki/Triangulation_(geometry)", "https://mathworld.wolfram.com/PolygonArea.html", "https://mathworld.wolfram.com/PolygonTriangulation.html", "https://www.cut-the-knot.org/WhatIs/WhatIsPolygons.shtml"]'),
  ('plane_geometry_similar_triangles_ratio', '{"en-us": "Similar triangles side ratio"}', 'plane_geometry', 3, '{"en-us": "When two triangles are similar, the ratios of lengths of their corresponding sides are equal, so the proportionality between any pair of corresponding sides gives the similarity (scale) factor between the figures."}', '["https://en.wikipedia.org/wiki/Similarity_(geometry)", "https://mathworld.wolfram.com/SimilarTriangles.html", "https://www.cuemath.com/geometry/similar-triangles/", "https://www.britannica.com/science/similar-triangles", "https://flexbooks.ck12.org/cbook/ck-12-conceptos-de-geometr%C3%ADa-de-la-escuela-secundaria-grado-10-en-espa%C3%B1ol/section/9.2/primary/lesson/tri%C3%A1ngulos-semejantes-geom-10/"]'),
  ('plane_mirror_image_distance', '{"en-us": "Plane mirror image distance"}', 'reflection', 4, '{"en-us": "A plane mirror forms a virtual image located the same distance behind the mirror as the object is in front of it. With the standard sign convention, the image distance is taken as negative because the image lies on the opposite side of the reflecting surface from the object."}', '["https://en.wikipedia.org/wiki/Plane_mirror", "https://www.physicsclassroom.com/class/refln/Lesson-2/Image-Formation-in-a-Plane-Mirror", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/02%3A_Geometric_Optics_and_Image_Formation", "https://www.britannica.com/science/optics-imaging/Plane-mirrors", "https://www.khanacademy.org/science/physics/geometric-optics/reflection/article/mirrors"]'),
  ('poh_definition', '{"en-us": "Definition of pOH"}', 'acids_and_bases', 5, '{"en-us": "pOH is defined as the negative base-10 logarithm of the hydroxide ion concentration in an aqueous solution. It is the complement of pH and is commonly used in basic (alkaline) solutions, where the hydroxide ion concentration is high."}', '["https://en.wikipedia.org/wiki/PH#pOH", "https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/08%3A_Properties_of_Solutions/8.13%3A_pH_and_pOH", "https://www.britannica.com/science/pH", "https://www.khanacademy.org/science/chemistry/acids-and-bases-topic/acids-and-bases/a/the-ph-scale", "https://www.thoughtco.com/definition-of-ph-and-ph-605890"]'),
  ('poiseuilles_law', '{"en-us": "Poiseuille''s law for laminar flow"}', 'reynolds_number', 8, '{"en-us": "The Hagen–Poiseuille (Poiseuille''s) law gives the steady-state volumetric flow rate of a viscous, incompressible, Newtonian fluid through a long cylindrical pipe under laminar flow conditions. The flow rate depends on the fourth power of the pipe radius and is inversely proportional to the fluid''s dynamic viscosity and the pipe length."}', '["https://en.wikipedia.org/wiki/Hagen%E2%80%93Poiseuille_equation", "https://www.britannica.com/science/Poiseuilles-law", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Dourmashkin)/23%3A_Fluid_Mechanics/23.05%3A_Viscosity_and_Poiseuilles_Law", "https://openstax.org/books/university-physics-volume-1/pages/14-7-viscosity-and-turbulent-flow", "https://www.khanacademy.org/science/physics/fluids/fluid-dynamics/a/what-is-viscosity"]'),
  ('poisson_distribution_mean', '{"en-us": "Poisson distribution mean"}', 'probability', 7, '{"en-us": "For a Poisson-distributed random variable counting the number of independent events in a fixed interval, the expected value (mean) equals the rate parameter λ, the average number of events per interval. The variance of the distribution also equals λ."}', '["https://en.wikipedia.org/wiki/Poisson_distribution", "https://mathworld.wolfram.com/PoissonDistribution.html", "https://www.britannica.com/science/Poisson-distribution", "https://www.khanacademy.org/math/statistics-probability/random-variables-stats-library/random-variables-mean-and-variance/a/poisson-distribution", "https://stat.ethz.ch/R-manual/R-devel/library/stats/html/Poisson.html"]'),
  ('poisson_probability', '{"en-us": "Poisson probability mass function"}', 'probability', 8, '{"en-us": "The Poisson probability mass function gives the probability of observing exactly k events in a fixed interval, given that the events occur independently at a constant average rate λ. It applies to rare events and counts the number of occurrences in a defined region of time, space, or another domain."}', '["https://en.wikipedia.org/wiki/Poisson_distribution", "https://mathworld.wolfram.com/PoissonDistribution.html", "https://www.britannica.com/science/Poisson-distribution", "https://www.khanacademy.org/math/statistics-probability/random-variables-stats-library/random-variables-mean-and-variance/a/poisson-distribution", "https://stattrek.com/probability-distributions/poisson"]'),
  ('polarization_angle_brewster', '{"en-us": "Brewster''s angle from refractive indices"}', 'polarization', 7, '{"en-us": "Brewster''s angle, also known as the polarization angle, is the angle of incidence at which light with a particular polarization is perfectly transmitted through a transparent dielectric surface with no reflection. Brewster''s law relates this angle to the ratio of the refractive indices of the two media at the interface."}', '["https://en.wikipedia.org/wiki/Brewster%27s_angle", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/01%3A_The_Nature_of_Light/1.06%3A_Polarization", "https://www.britannica.com/science/Brewsters-angle", "https://scienceworld.wolfram.com/physics/BrewstersAngle.html", "https://www.rp-photonics.com/brewster_angle.html"]'),
  ('polarization_orientation_angle', '{"en-us": "Polarization orientation angle"}', 'polarization', 8, '{"en-us": "The polarization orientation angle specifies the tilt of the electric field''s oscillation direction relative to a reference axis in the plane perpendicular to propagation. For a linearly polarized wave written as a superposition of orthogonal components, the tilt is set by the ratio of the component amplitudes."}', '["https://en.wikipedia.org/wiki/Polarization_(waves)", "https://en.wikipedia.org/wiki/Linear_polarization", "https://en.wikipedia.org/wiki/Polarization_ellipse", "https://en.wikipedia.org/wiki/Jones_calculus", "https://scienceworld.wolfram.com/physics/Polarization.html"]'),
  ('polygon_area_from_side', '{"en-us": "Polygon area from side length"}', 'polygons', 5, '{"en-us": "For a regular polygon with n equal sides of length s, the area can be expressed in closed form by dividing it into n isosceles triangles meeting at the center. The resulting expression is equivalent to one quarter of n times the squared side length times the cotangent of pi over n."}', '["https://en.wikipedia.org/wiki/Regular_polygon", "https://mathworld.wolfram.com/RegularPolygon.html", "https://math.libretexts.org/Bookshelves/Precalculus/Book%3A_Trigonometry_(Larson)/06%3A_Additional_Topics_in_Trigonometry/6.02%3A_Law_of_Cosines", "https://www.cuemath.com/geometry/area-of-polygon/", "https://www.britannica.com/science/regular-polygon"]'),
  ('polygon_circumradius', '{"en-us": "Polygon circumradius"}', 'polygons', 6, '{"en-us": "The circumradius of a regular polygon is the distance from the center to any vertex. It is related to the side length s and number of sides n by the central isosceles triangle formed by two adjacent vertices and the center."}', '["https://en.wikipedia.org/wiki/Regular_polygon", "https://en.wikipedia.org/wiki/Circumradius", "https://mathworld.wolfram.com/RegularPolygon.html", "https://math.libretexts.org/Bookshelves/Geometry/Book%3A_Geometry_(Averill_Faith)/04%3A_Polygons/4.04%3A_Regular_Polygons", "https://www.cuemath.com/geometry/regular-polygon/"]'),
  ('polygon_diagonal_count', '{"en-us": "Number of diagonals in a polygon"}', 'polygons', 4, '{"en-us": "The number of diagonals in a convex n-gon can be obtained by counting, for each vertex, the n minus 3 diagonals to all other non-adjacent vertices, then dividing by two to avoid double counting. The result is a quadratic in n that vanishes for the triangle."}', '["https://en.wikipedia.org/wiki/Diagonal", "https://en.wikipedia.org/wiki/Regular_polygon", "https://mathworld.wolfram.com/PolygonDiagonal.html", "https://www.cuemath.com/geometry/diagonals-of-a-polygon/", "https://math.libretexts.org/Bookshelves/Geometry/Book%3A_Geometry_(Averill_Faith)/04%3A_Polygons/4.04%3A_Regular_Polygons"]'),
  ('polygon_exterior_angle_regular', '{"en-us": "Exterior angle of a regular polygon"}', 'polygons', 3, '{"en-us": "The exterior angle of a regular polygon is the angle formed by one side and the extension of an adjacent side. Because the n exterior angles of any convex polygon sum to a full turn, each exterior angle in a regular polygon equals one full turn divided by n."}', '["https://en.wikipedia.org/wiki/Regular_polygon", "https://en.wikipedia.org/wiki/Exterior_angle", "https://mathworld.wolfram.com/ExteriorAngle.html", "https://www.cuemath.com/geometry/exterior-angles-of-a-polygon/", "https://math.libretexts.org/Bookshelves/Geometry/Book%3A_Geometry_(Averill_Faith)/04%3A_Polygons/4.04%3A_Regular_Polygons"]'),
  ('polygon_exterior_angle_sum', '{"en-us": "Sum of exterior angles of a polygon"}', 'polygons', 3, '{"en-us": "For any simple (non-self-intersecting) polygon, the exterior angles — taken one at each vertex — always sum to one full turn, i.e. 360° or 2π radians, regardless of the number of sides or the polygon''s shape."}', '["https://en.wikipedia.org/wiki/Polygon", "https://en.wikipedia.org/wiki/Internal_and_external_angles", "https://en.wikipedia.org/wiki/Exterior_angle", "https://mathworld.wolfram.com/ExteriorAngle.html", "https://www.cuemath.com/geometry/sum-of-exterior-angles-of-a-polygon/"]'),
  ('polygon_interior_angle_regular', '{"en-us": "Interior angle of a regular polygon"}', 'polygons', 4, '{"en-us": "Each interior angle of a regular n-gon has the same measure, found by dividing the total interior angle sum (n−2)·180° equally among the n vertices. As n grows, the interior angle approaches 180° and the polygon approaches a circle."}', '["https://en.wikipedia.org/wiki/Regular_polygon", "https://en.wikipedia.org/wiki/Internal_and_external_angles", "https://en.wikipedia.org/wiki/Interior_angle", "https://mathworld.wolfram.com/RegularPolygon.html", "https://www.cuemath.com/geometry/regular-polygon/"]'),
  ('polynomial_cubic_identity', '{"en-us": "Perfect square of a trinomial"}', 'polynomials', 5, '{"en-us": "The square of a three-term sum (a+b+c) expands to the sum of the three individual squares plus twice every cross-product pair. The same structure underlies the multinomial theorem and is the natural generalization of the two-term perfect-square identity."}', '["https://en.wikipedia.org/wiki/Polynomial", "https://en.wikipedia.org/wiki/Elementary_symmetric_polynomial", "https://mathworld.wolfram.com/Trinomial.html", "https://www.cuemath.com/algebra/square-of-a-trinomial/", "https://www.khanacademy.org/math/algebra/x2e8-multiplication-and-factoring/x2e8-factoring-polynomials-perfect-square/a/factoring-quadratics-perfect-squares"]'),
  ('polynomial_quadratic_product_roots', '{"en-us": "Product of roots of a quadratic"}', 'polynomials', 5, '{"en-us": "One of Vieta''s formulas: for the quadratic ax²+bx+c=0 with leading coefficient a ≠ 0 and constant term c, the product of its two roots equals c/a. This lets the roots be found or constrained without ever computing them individually."}', '["https://en.wikipedia.org/wiki/Vieta%27s_formulas", "https://en.wikipedia.org/wiki/Quadratic_equation", "https://mathworld.wolfram.com/QuadraticFormula.html", "https://www.cuemath.com/algebra/product-of-roots-of-quadratic-equation/", "https://www.khanacademy.org/math/algebra/x2e8-multiplication-and-factoring/x2e8-solving-quadratic-equations-by-factoring/v/using-the-quadratic-formula"]'),
  ('polynomial_quadratic_sum_roots', '{"en-us": "Sum of roots of a quadratic"}', 'polynomials', 5, '{"en-us": "One of Vieta''s formulas: for the quadratic ax²+bx+c=0 with leading coefficient a ≠ 0, the sum of its two roots equals −b/a. Combined with the product-of-roots formula, this lets the quadratic be reconstructed from its roots without solving it."}', '["https://en.wikipedia.org/wiki/Vieta%27s_formulas", "https://en.wikipedia.org/wiki/Quadratic_equation", "https://mathworld.wolfram.com/QuadraticFormula.html", "https://www.cuemath.com/algebra/sum-of-roots-of-quadratic-equation/", "https://www.khanacademy.org/math/algebra/x2e8-multiplication-and-factoring/x2e8-solving-quadratic-equations-by-factoring/v/using-the-quadratic-formula"]'),
  ('polytropic_process', '{"en-us": "Polytropic process"}', 'ideal_gases', 8, '{"en-us": "A polytropic process is a thermodynamic expansion or compression of a gas that obeys PV^n = constant, where n is the polytropic index. It unifies the standard ideal-gas processes as special cases: isobaric (n=0), isothermal (n=1), isentropic (n=γ), and isochoric (n→∞)."}', '["https://en.wikipedia.org/wiki/Polytropic_process", "https://en.wikipedia.org/wiki/Thermodynamic_process", "https://en.wikipedia.org/wiki/Ideal_gas_law", "https://www.britannica.com/science/polytropic-process", "https://www.engineersedge.com/thermodynamics/polytropic_process_equations_13820.htm"]'),
  ('population_variance', '{"en-us": "Population variance"}', 'statistics', 6, '{"en-us": "The population variance quantifies the dispersion of an entire finite population of values around its mean, computed as the average of the squared deviations of every member from that mean. It contrasts with the sample variance, which uses a denominator of N-1 to give an unbiased estimator."}', '["https://en.wikipedia.org/wiki/Variance", "https://en.wikipedia.org/wiki/Population_variance", "https://en.wikipedia.org/wiki/Standard_deviation", "https://mathworld.wolfram.com/SampleVariance.html", "https://www.khanacademy.org/math/statistics-probability/summarizing-quantitative-data/variance-standard-deviation-sample/a/population-and-sample-standard-deviation-review"]'),
  ('potential_energy_charge_configuration', '{"en-us": "Electric potential energy of a charge configuration"}', 'electric_potential', 8, '{"en-us": "This is the electrostatic potential energy associated with bringing two point charges from infinite separation to a fixed distance apart, equal to the work an external agent must do against the repulsive (or attractive) Coulomb force. For a general configuration of N charges the total energy is one half the sum over all distinct pairs to avoid double counting."}', '["https://en.wikipedia.org/wiki/Electric_potential_energy", "https://en.wikipedia.org/wiki/Coulomb%27s_law", "https://en.wikipedia.org/wiki/Electrostatic_potential_energy_stored_in_a_system_of_point_charges", "https://www.khanacademy.org/science/physics/work-and-energy/work-and-potential-energy/v/potential-energy-of-charges", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/07%3A_Electric_Potential"]'),
  ('potential_energy_dipole_field', '{"en-us": "Potential energy of a dipole in a field"}', 'electric_potential', 8, '{"en-us": "An electric dipole in a uniform external electric field possesses an orientation-dependent potential energy that is minimum when the dipole moment is aligned parallel to the field and maximum when anti-parallel. The interaction is conservative and produces a torque that tends to align the dipole with the field."}', '["https://en.wikipedia.org/wiki/Electric_dipole_moment", "https://en.wikipedia.org/wiki/Electric_potential_energy", "https://en.wikipedia.org/wiki/Energy_and_torque", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/05%3A_Electric_Charges_and_Fields", "https://www.physics.sjsu.edu/becker/physics51/24%20Dipole%20in%20Field.htm"]'),
  ('potential_energy_electric_field', '{"en-us": "Electric potential energy in uniform field"}', 'potential_energy', 6, '{"en-us": "The change in electric potential energy of a charge moved a displacement in a uniform electric field equals the negative of the work done by the field, which for a displacement parallel to the field direction reduces to the simple product of charge, field strength, and distance. The sign convention reflects that work must be done against the field to move a positive charge to higher potential."}', '["https://en.wikipedia.org/wiki/Electric_potential_energy", "https://en.wikipedia.org/wiki/Work_(electric_field)", "https://en.wikipedia.org/wiki/Electric_field", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/07%3A_Electric_Potential", "https://www.khanacademy.org/science/physics/work-and-energy/work-and-potential-energy/v/work-and-energy-conservation"]'),
  ('potential_energy_gravitational_definition', '{"en-us": "Gravitational potential energy near Earth''s surface"}', 'potential_energy', 4, '{"en-us": "Near the surface of a massive body the gravitational field is approximately uniform, allowing the gravitational potential energy of a mass to be expressed linearly in the height above a chosen reference level. This approximation is accurate when the height is much smaller than the radius of the gravitating body."}', '["https://en.wikipedia.org/wiki/Gravitational_energy", "https://en.wikipedia.org/wiki/Gravitational_potential", "https://en.wikipedia.org/wiki/Potential_energy", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_(OpenStax)/08%3A_Potential_Energy_and_Conservation_of_Energy", "https://www.khanacademy.org/science/physics/work-and-energy/work-and-potential-energy/v/gravitational-potential-energy"]'),
  ('potential_energy_gravitational_near_surface', '{"en-us": "Gravitational potential energy near surface"}', 'potential_energy', 4, '{"en-us": "The simplified gravitational potential energy in the uniform-field limit is proportional to the mass, the local gravitational acceleration, and the height above a reference, neglecting the radial dependence of the true inverse-square law. It is the work needed to lift the mass quasi-statically from the reference level against the constant gravitational force."}', '["https://en.wikipedia.org/wiki/Gravitational_energy", "https://en.wikipedia.org/wiki/Gravitational_potential", "https://en.wikipedia.org/wiki/Newton%27s_law_of_universal_gravitation", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_(OpenStax)/08%3A_Potential_Energy_and_Conservation_of_Energy", "https://www.khanacademy.org/science/physics/work-and-energy/work-and-potential-energy/v/gravitational-potential-energy"]'),
  ('power_efficiency_relation', '{"en-us": "Power efficiency"}', 'power', 4, '{"en-us": "Efficiency of a power-converting device is the ratio of useful output power to the input power supplied. For a lossless system the efficiency equals 1 (100%), and real systems are bounded above by unity because of unavoidable losses such as friction, heat, or electrical resistance."}', '["https://en.wikipedia.org/wiki/Efficiency", "https://en.wikipedia.org/wiki/Energy_conversion_efficiency", "https://en.wikipedia.org/wiki/Mechanical_efficiency", "https://en.wikipedia.org/wiki/Thermal_efficiency", "https://www.britannica.com/science/efficiency-physics"]'),
  ('power_mechanical_force_velocity_angle', '{"en-us": "Power from force, velocity and angle"}', 'power', 6, '{"en-us": "The instantaneous mechanical power delivered by a constant force equals the scalar product of the force and the velocity of the point of application, so only the component of the force along the direction of motion contributes to the rate of doing work."}', '["https://en.wikipedia.org/wiki/Power_(physics)", "https://en.wikipedia.org/wiki/Mechanical_work", "https://en.wikipedia.org/wiki/Mechanical_power", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/07%3A_Work_and_Kinetic_Energy/7.09%3A_Power", "https://www.britannica.com/science/power-physics"]'),
  ('power_of_a_point_circle', '{"en-us": "Power of a point theorem"}', 'circles', 6, '{"en-us": "The power of a point P with respect to a circle is the real number obtained by squaring the distance from P to the circle''s center minus the square of the radius. For any chord, secant, or tangent through P meeting the circle at points A and B, the signed product PA·PB is constant and equals this value, which lies inside, on, or outside the circle depending on its sign."}', '["https://en.wikipedia.org/wiki/Power_of_a_point", "https://en.wikipedia.org/wiki/Intersecting_chords_theorem", "https://en.wikipedia.org/wiki/Intersecting_secants_theorem", "https://en.wikipedia.org/wiki/Tangent%E2%80%93secant_theorem", "https://mathworld.wolfram.com/PowerofaPoint.html"]'),
  ('power_of_product_rule', '{"en-us": "Power of a product"}', 'exponents', 2, '{"en-us": "The power of a product rule states that raising a product to an exponent is equivalent to raising each factor to that exponent and then multiplying the results. This identity, together with the corresponding rule for quotients, follows from the repeated-multiplication definition of positive integer exponents."}', '["https://en.wikipedia.org/wiki/Exponentiation", "https://en.wikipedia.org/wiki/Exponent", "https://math.libretexts.org/Bookshelves/Algebra/Elementary_Algebra_(Wade)/02%3A_Introduction_to_Algebra/2.04%3A_Exponents_and_Scientific_Notation", "https://www.khanacademy.org/math/pre-algebra/pre-algebra-exponents-radicals/pre-algebra-exponents/v/exponent-properties-involving-products", "https://mathworld.wolfram.com/ExponentLaws.html"]'),
  ('power_of_quotient_rule', '{"en-us": "Power of a quotient"}', 'exponents', 3, '{"en-us": "The power of a quotient rule states that raising a quotient to an exponent is equivalent to separately raising the numerator and denominator to that exponent and then dividing. It follows directly from the power-of-a-product rule together with the definition of negative exponents."}', '["https://en.wikipedia.org/wiki/Exponentiation", "https://en.wikipedia.org/wiki/Exponent", "https://math.libretexts.org/Bookshelves/Algebra/Elementary_Algebra_(Wade)/02%3A_Introduction_to_Algebra/2.04%3A_Exponents_and_Scientific_Notation", "https://www.khanacademy.org/math/pre-algebra/pre-algebra-exponents-radicals/pre-algebra-exponents/v/exponent-properties-involving-quotients", "https://mathworld.wolfram.com/ExponentLaws.html"]'),
  ('power_resistive_circuit_voltage', '{"en-us": "Power from voltage and resistance"}', 'circuits', 5, '{"en-us": "In a purely resistive element, the power dissipated equals the square of the voltage across it divided by its resistance. This is one of three equivalent forms of Joule''s first law, derivable by combining P = IV with Ohm''s law V = IR."}', '["https://en.wikipedia.org/wiki/Electric_power", "https://en.wikipedia.org/wiki/Joule_heating", "https://en.wikipedia.org/wiki/Ohm%27s_law", "https://en.wikipedia.org/wiki/Electrical_resistance_and_conductance", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/09%3A_Current_and_Resistance/9.06%3A_Electrical_Energy_and_Power"]'),
  ('pressure_depth_fluid', '{"en-us": "Pressure at a depth in fluid"}', 'pressure', 5, '{"en-us": "The hydrostatic pressure exerted by a fluid at rest at depth h below its surface equals the product of the fluid''s density, gravitational acceleration, and depth. This relation holds for incompressible fluids with a free surface, neglecting variations of g with position."}', '["https://en.wikipedia.org/wiki/Pressure", "https://en.wikipedia.org/wiki/Hydrostatic_pressure", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.04%3A_Measuring_Pressure", "https://www.britannica.com/science/hydrostatic-pressure", "https://en.wikipedia.org/wiki/Fluid_pressure", "https://www.physicsclassroom.com/class/fluids/Lesson-3/Fluid-Pressures"]'),
  ('probability_addition_rule', '{"en-us": "Addition rule for probability"}', 'probability', 5, '{"en-us": "The probability that either of two events occurs equals the sum of their individual probabilities minus the probability that both occur simultaneously, a statement known as the inclusion-exclusion rule for two events. It reduces to simple addition when the events are mutually exclusive."}', '["https://en.wikipedia.org/wiki/Probability", "https://en.wikipedia.org/wiki/Mutual_exclusivity", "https://en.wikipedia.org/wiki/Complementary_event", "https://www.britannica.com/science/probability-theory"]'),
  ('probability_complement_rule', '{"en-us": "Complement rule of probability"}', 'probability', 4, '{"en-us": "The probability of an event''s complement equals one minus the probability of the event itself, reflecting the requirement that the event and its complement are mutually exclusive and collectively exhaustive."}', '["https://en.wikipedia.org/wiki/Complementary_event", "https://en.wikipedia.org/wiki/Probability", "https://www.britannica.com/science/probability-theory"]'),
  ('probability_from_odds', '{"en-us": "Probability from odds"}', 'probability', 5, '{"en-us": "The probability of an event can be recovered from its odds in favor by dividing the odds by one plus the odds. Equivalently, given the odds o = p/(1-p) against the alternative, p = o/(o+1)."}', '["https://en.wikipedia.org/wiki/Odds", "https://en.wikipedia.org/wiki/Probability", "https://www.britannica.com/science/odds", "https://en.wikipedia.org/wiki/Betting_odds"]'),
  ('probability_multiplication_independent', '{"en-us": "Probability of independent events"}', 'probability', 4, '{"en-us": "Two events are independent when the occurrence of one does not affect the probability of the other, in which case the probability of both occurring equals the product of their individual probabilities."}', '["https://en.wikipedia.org/wiki/Probability", "https://www.britannica.com/science/probability-theory"]'),
  ('probability_mutually_exclusive', '{"en-us": "Probability of mutually exclusive events"}', 'probability', 4, '{"en-us": "Two events are mutually exclusive when they cannot both occur, so the probability that either one happens equals the sum of their individual probabilities. This is the special case of the addition rule when the intersection has probability zero."}', '["https://en.wikipedia.org/wiki/Mutual_exclusivity", "https://en.wikipedia.org/wiki/Probability", "https://www.britannica.com/science/probability-theory"]'),
  ('probability_of_event', '{"en-us": "Probability of an event"}', 'probability', 3, '{"en-us": "Classical (theoretical) probability assigns to an event the ratio of the number of favorable outcomes to the total number of equally likely outcomes in the sample space. The result is a dimensionless number between 0 and 1, and is the foundation of the frequentist interpretation of probability used in combinatorics and elementary statistics."}', '["https://en.wikipedia.org/wiki/Probability", "https://en.wikipedia.org/wiki/Classical_definition_of_probability", "https://math.libretexts.org/Bookshelves/Probability_Theory/Probability%3A_for_the_Enthusiastic_Beginner", "https://www.britannica.com/science/probability-theory", "https://www.khanacademy.org/math/statistics-probability/probability-library"]'),
  ('product_to_sum_cosine_cosine', '{"en-us": "Product-to-sum: cos A cos B"}', 'trigonometric_identities', 7, '{"en-us": "Expresses the product of two cosines as a sum of cosines. It is widely used to simplify integrals of products of trigonometric functions and to convert products into sums in physics and engineering signal analysis."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities#Product-to-sum_identities", "https://en.wikipedia.org/wiki/Product-to-sum_identities", "https://math.libretexts.org/Bookshelves/Trigonometry", "https://www.cuemath.com/trigonometry/product-to-sum-formulas/", "https://www.khanacademy.org/math/trigonometry"]'),
  ('product_to_sum_sine_cosine', '{"en-us": "Product-to-sum: sin A cos B"}', 'trigonometric_identities', 7, '{"en-us": "Expresses the product of a sine and a cosine as a sum of sines. It is useful in harmonic analysis for converting products of sinusoids into sums, simplifying integration, and analyzing superposed waves."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities#Product-to-sum_identities", "https://en.wikipedia.org/wiki/Product-to-sum_identities", "https://math.libretexts.org/Bookshelves/Trigonometry", "https://www.cuemath.com/trigonometry/product-to-sum-formulas/", "https://www.khanacademy.org/math/trigonometry"]'),
  ('product_to_sum_sine_sine', '{"en-us": "Product-to-sum: sin A sin B"}', 'trigonometric_identities', 7, '{"en-us": "Expresses the product of two sines as a difference of cosines. It is used in signal processing and physics to convert products of sinusoidal signals into sums of harmonics, which is convenient for integration and Fourier analysis."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities#Product-to-sum_identities", "https://en.wikipedia.org/wiki/Product-to-sum_identities", "https://math.libretexts.org/Bookshelves/Trigonometry", "https://www.cuemath.com/trigonometry/product-to-sum-formulas/", "https://www.khanacademy.org/math/trigonometry"]'),
  ('projectile_height_at_time', '{"en-us": "Projectile height at time"}', 'projectile_motion', 5, '{"en-us": "Gives the vertical position of a projectile as a function of elapsed time, assuming launch from ground level with uniform downward gravitational acceleration and no air resistance. The first term represents the contribution of the initial vertical velocity and the second term the downward displacement due to gravity."}', '["https://en.wikipedia.org/wiki/Projectile_motion#Displacement", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/04%3A_Motion_in_Two_and_Three_Dimensions", "https://www.khanacademy.org/science/physics/two-dimensional-motion", "https://www.britannica.com/science/projectile-motion", "https://openstax.org/books/university-physics-volume-1/pages/4-3-projectile-motion"]'),
  ('projectile_horizontal_velocity', '{"en-us": "Horizontal velocity of a projectile"}', 'projectile_motion', 5, '{"en-us": "The horizontal component of a projectile''s velocity is constant throughout the flight (neglecting air resistance), since no horizontal force acts on the projectile. It is obtained by projecting the initial speed onto the horizontal axis using the cosine of the launch angle."}', '["https://en.wikipedia.org/wiki/Projectile_motion#Velocity", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/04%3A_Motion_in_Two_and_Three_Dimensions", "https://www.khanacademy.org/science/physics/two-dimensional-motion", "https://www.britannica.com/science/projectile-motion", "https://openstax.org/books/university-physics-volume-1/pages/4-3-projectile-motion"]'),
  ('projectile_launch_angle_range_factor', '{"en-us": "Projectile range dependence on launch angle"}', 'projectile_motion', 6, '{"en-us": "The horizontal range of a projectile launched and landing at the same height depends on launch angle through the sine of twice that angle, scaled by its maximum value. The two complementary angles that sum to 90° produce the same range. Assumes vacuum and uniform gravity."}', '["https://en.wikipedia.org/wiki/Projectile_motion#Maximum_distance_of_projectile", "https://en.wikipedia.org/wiki/Range_of_a_projectile", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_College_Physics_1e_(OpenStax)/03%3A_Two-Dimensional_Kinematics/3.04%3A_Projectile_Motion", "https://www.physicsclassroom.com/Class/vectors/u3l2d.cfm", "https://www.britannica.com/science/projectile-motion"]'),
  ('projectile_max_height', '{"en-us": "Maximum height of a projectile"}', 'projectile_motion', 5, '{"en-us": "The maximum height reached by a projectile occurs when the vertical component of its velocity becomes zero. It depends on the initial speed, the launch angle, and the local gravitational acceleration, and is independent of the projectile''s mass. Applies in the idealized case of no air resistance and uniform gravity."}', '["https://en.wikipedia.org/wiki/Projectile_motion#Maximum_height_of_projectile", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_College_Physics_1e_(OpenStax)/03%3A_Two-Dimensional_Kinematics/3.04%3A_Projectile_Motion", "https://www.khanacademy.org/science/physics/two-dimensional-motion/two-dimensional-projectile-mot/a/projectiles-launched-at-an-angle", "https://www.physicsclassroom.com/Class/vectors/u3l2d.cfm", "https://www.britannica.com/science/projectile-motion"]'),
  ('projectile_maximum_range', '{"en-us": "Maximum range of projectile"}', 'projectile_motion', 6, '{"en-us": "The maximum horizontal range of a projectile launched from and landing at the same elevation is reached at a 45° launch angle and equals the square of the initial speed divided by the gravitational acceleration. Assumes vacuum, uniform gravity, and launch and landing heights equal."}', '["https://en.wikipedia.org/wiki/Projectile_motion#Maximum_distance_of_projectile", "https://en.wikipedia.org/wiki/Range_of_a_projectile", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_College_Physics_1e_(OpenStax)/03%3A_Two-Dimensional_Kinematics/3.04%3A_Projectile_Motion", "https://www.physicsclassroom.com/Class/vectors/u3l2d.cfm", "https://www.britannica.com/science/projectile-motion"]'),
  ('projectile_optimal_angle', '{"en-us": "Optimal launch angle for maximum range"}', 'projectile_motion', 5, '{"en-us": "The launch angle that maximizes the horizontal range of a projectile on level ground is 45°. This follows from the fact that the range is proportional to the sine of twice the launch angle, which is unity only at this angle. Valid for the ideal case with no air resistance."}', '["https://en.wikipedia.org/wiki/Projectile_motion#Maximum_distance_of_projectile", "https://en.wikipedia.org/wiki/Range_of_a_projectile", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_College_Physics_1e_(OpenStax)/03%3A_Two-Dimensional_Kinematics/3.04%3A_Projectile_Motion", "https://www.physicsclassroom.com/Class/vectors/u3l2d.cfm", "https://www.khanacademy.org/science/physics/two-dimensional-motion/two-dimensional-projectile-mot/a/projectiles-launched-at-an-angle"]'),
  ('projectile_range', '{"en-us": "Range of a projectile"}', 'projectile_motion', 5, '{"en-us": "The horizontal range of a projectile launched and landing at the same height equals the square of the initial speed times the sine of twice the launch angle, divided by gravitational acceleration. This is the canonical relation for ideal projectile motion in vacuum."}', '["https://en.wikipedia.org/wiki/Projectile_motion#Maximum_distance_of_projectile", "https://en.wikipedia.org/wiki/Range_of_a_projectile", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_College_Physics_1e_(OpenStax)/03%3A_Two-Dimensional_Kinematics/3.04%3A_Projectile_Motion", "https://www.khanacademy.org/science/physics/two-dimensional-motion/two-dimensional-projectile-mot/a/projectiles-launched-at-an-angle", "https://www.physicsclassroom.com/Class/vectors/u3l2d.cfm", "https://www.britannica.com/science/projectile-motion"]'),
  ('projectile_time_of_flight', '{"en-us": "Time of flight of a projectile"}', 'projectile_motion', 5, '{"en-us": "The total time a projectile spends in the air, from launch until it returns to its original elevation, is twice the time to reach the apex. It depends on the initial vertical velocity component and the gravitational acceleration. Applies in vacuum with uniform gravity."}', '["https://en.wikipedia.org/wiki/Projectile_motion#Time_of_flight_or_total_time_of_the_whole_journey", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_College_Physics_1e_(OpenStax)/03%3A_Two-Dimensional_Kinematics/3.04%3A_Projectile_Motion", "https://www.khanacademy.org/science/physics/two-dimensional-motion/two-dimensional-projectile-mot/a/projectiles-launched-at-an-angle", "https://www.physicsclassroom.com/Class/vectors/u3l2d.cfm", "https://www.britannica.com/science/projectile-motion"]'),
  ('projectile_velocity_resultant', '{"en-us": "Resultant projectile velocity"}', 'projectile_motion', 5, '{"en-us": "The magnitude of a projectile''s velocity at any point along its trajectory is found by combining its independent horizontal and vertical components under the Pythagorean theorem. Since horizontal velocity is constant and vertical velocity changes linearly under gravity, the resultant gives the projectile''s instantaneous speed and direction."}', '["https://en.wikipedia.org/wiki/Projectile_motion", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_College_Physics_(OpenStax)/03%3A_Two-Dimensional_Kinematics/3.4%3A_Projectile_Motion", "https://www.britannica.com/science/projectile-motion", "https://openstax.org/books/college-physics-2e/pages/3-4-projectile-motion"]'),
  ('projectile_vertical_velocity', '{"en-us": "Vertical velocity of a projectile"}', 'projectile_motion', 5, '{"en-us": "In ideal projectile motion under constant gravitational acceleration, the vertical component of velocity decreases linearly with time because gravity acts only along the vertical direction. The horizontal component remains constant, while the vertical component determines when the projectile reaches its peak and returns to launch height."}', '["https://en.wikipedia.org/wiki/Projectile_motion", "https://www.britannica.com/science/projectile-motion", "https://openstax.org/books/college-physics-2e/pages/3-4-projectile-motion", "https://phys.libretexts.org/Bookshelves/University_Physics/Physics_(Boundless)/03%3A_Two-Dimensional_Kinematics/3.3%3A_Projectile_Motion"]'),
  ('proper_time', '{"en-us": "Proper time"}', 'relativity', 9, '{"en-us": "Proper time is the elapsed time measured by a clock traveling between two events along its own world line, making it a Lorentz-invariant scalar. In special relativity, the proper-time interval between two events is always less than or equal to the coordinate time measured in any inertial frame, with the difference captured by the Lorentz factor. This relation underlies phenomena such as time dilation, the twin paradox, and muon lifetime extension observed in cosmic-ray experiments."}', '["https://en.wikipedia.org/wiki/Proper_time", "https://en.wikipedia.org/wiki/Time_dilation", "https://en.wikipedia.org/wiki/Lorentz_factor", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_(OpenStax)/05%3A__Relativity/5.3%3A_Time_Dilation", "https://www.britannica.com/science/proper-time"]'),
  ('pulley_mechanical_advantage', '{"en-us": "Mechanical advantage of a pulley system"}', 'forces', 4, '{"en-us": "Mechanical advantage quantifies how much a pulley system multiplies the input effort force to lift or move a load. For an ideal frictionless pulley, the mechanical advantage equals the number of supporting rope sections sharing the load, while the actual (measured) value is reduced by friction, rope mass, and pulley inertia. This relation underlies the design of block-and-tackle hoists, cranes, and other lifting rigs."}', '["https://en.wikipedia.org/wiki/Mechanical_advantage", "https://en.wikipedia.org/wiki/Pulley", "https://en.wikipedia.org/wiki/Block_and_tackle", "https://www.britannica.com/technology/pulley", "https://openstax.org/books/physics/pages/9-3-simple-machines"]'),
  ('pythagorean_theorem', '{"en-us": "Pythagorean theorem"}', 'triangles', 3, '{"en-us": "A cornerstone of Euclidean geometry, the Pythagorean theorem states that in any right triangle the area of the square on the hypotenuse equals the sum of the areas of the squares on the other two sides. It underlies the Euclidean distance formula, the law of cosines, and many results in analytic geometry, trigonometry, and physics."}', '["https://en.wikipedia.org/wiki/Pythagorean_theorem", "https://www.britannica.com/science/Pythagorean-theorem", "https://mathworld.wolfram.com/PythagoreanTheorem.html", "https://www.khanacademy.org/math/geometry-home/triangle-properties/pythagorean-theorem/v/the-pythagorean-theorem", "https://math.libretexts.org/Bookshelves/Algebra/Intermediate_Algebra/05%3A_Radical_Functions_and_Equations/5.06%3A_Geometric_Applications"]'),
  ('pythagorean_trig_identity', '{"en-us": "Pythagorean trigonometric identity"}', 'trigonometric_identities', 5, '{"en-us": "The Pythagorean identity states that for any real angle, the sum of the squares of its sine and cosine equals one. It follows directly from the unit-circle equation x² + y² = 1, since (cos θ, sin θ) is a point on that circle. This identity is the foundation for the angle-addition formulas, the double- and half-angle identities, and many calculus simplifications."}', '["https://en.wikipedia.org/wiki/Pythagorean_trigonometric_identity", "https://en.wikipedia.org/wiki/List_of_trigonometric_identities", "https://mathworld.wolfram.com/TrigonometricPythagoreanIdentity.html", "https://www.khanacademy.org/math/trigonometry/trig-identities-and-proofs/trig-id-article-2/v/sin2x-plus-cos2x-equals-1", "https://math.libretexts.org/Bookshelves/Trigonometry/Trigonometry_(Lumen)/07%3A_Trigonometric_Identities_and_Equations/7.01%3A_Trigonometric_Identities"]'),
  ('q_factor_rlc', '{"en-us": "Q factor of an RLC circuit"}', 'circuits', 8, '{"en-us": "The Q factor of a series RLC circuit is a dimensionless measure of the sharpness of its resonance, equal to the ratio of reactive to resistive impedance at resonance. Higher Q means narrower bandwidth and slower decay of oscillations."}', '["https://en.wikipedia.org/wiki/Q_factor", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/16%3A_Alternating-Current_Circuits/16.04%3A_Q_Factor", "https://www.electronics-tutorials.ws/accircuits/series-resonance.html", "https://www.khanacademy.org/science/electrical-engineering/ee-circuit-analysis-topic/ee-resonance/a/ee-resonance-overview", "https://www.britannica.com/technology/Q-factor"]'),
  ('q_factor_series_rlc', '{"en-us": "Q factor of a series RLC circuit"}', 'circuits', 8, '{"en-us": "The Q factor of a series RLC circuit describes how underdamped the resonance is: it equals the ratio of inductive reactance to resistance at the resonant frequency, equivalently one over R times the square root of L over C."}', '["https://en.wikipedia.org/wiki/Q_factor", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/16%3A_Alternating-Current_Circuits/16.04%3A_Q_Factor", "https://www.electronics-tutorials.ws/accircuits/series-resonance.html", "https://www.khanacademy.org/science/electrical-engineering/ee-circuit-analysis-topic/ee-resonance/a/ee-resonance-overview"]'),
  ('quadratic_formula', '{"en-us": "Quadratic formula"}', 'polynomials', 4, '{"en-us": "The quadratic formula gives the roots of any quadratic equation in terms of its coefficients, and applies over the real or complex numbers depending on the discriminant. It is valid for any nonzero leading coefficient and handles repeated, real, or complex roots via the discriminant."}', '["https://en.wikipedia.org/wiki/Quadratic_formula", "https://mathworld.wolfram.com/QuadraticFormula.html", "https://www.khanacademy.org/math/algebra/x2f8bb11595b61c86:quadratic-functions-equations/x2f8bb11595b61c86:quadratic-formula/a/the-quadratic-formula", "https://www.britannica.com/science/quadratic-formula", "https://math.libretexts.org/Bookshelves/Algebra/Intermediate_Algebra_(OpenStax)/09%3A_Quadratic_Equations_and_Functions/9.01%3A_Solving_Quadratic_Equations_by_the_Quadratic_Formula"]'),
  ('quantum_mechanics_tunneling_probability', '{"en-us": "Quantum tunneling probability (WKB)"}', 'quantum_mechanics', 10, '{"en-us": "The WKB approximation gives an estimate of the probability that a quantum particle tunnels through a potential barrier whose height exceeds the particle''s energy. The result is dominated by an exponential decay with the barrier width, particle mass, and barrier height, and is the basis of alpha decay, field emission, and scanning tunneling microscopy."}', '["https://en.wikipedia.org/wiki/Quantum_tunnelling", "https://en.wikipedia.org/wiki/WKB_approximation", "https://phys.libretexts.org/Bookshelves/Quantum_Mechanics/Quantum_Mechanics_(McIntyre)/04%3A_The_Schrodinger_Equation/4.04%3A_Quantum_Tunneling", "https://www.britannica.com/science/tunneling"]'),
  ('quantum_number_magnetic_range', '{"en-us": "Quantum number magnetic range"}', 'atomic_structure', 7, '{"en-us": "The magnetic quantum number indexes the allowed orientations of an electron''s orbital angular momentum about a chosen axis in space. For a given azimuthal quantum number l, it takes integer values from negative l to positive l, yielding 2l plus 1 orbitals in the subshell."}', '["https://en.wikipedia.org/wiki/Magnetic_quantum_number", "https://www.britannica.com/science/magnetic-quantum-number", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Quantum_Mechanics/09._The_Hydrogen_Atom/Atomic_Orbitals", "https://phys.libretexts.org/Bookshelves/Quantum_Mechanics/Book%3A_Introduction_to_Quantum_Mechanics_(Schroeder)/03._One-Dimensional_Problems/3.04%3A_Quantum_Mechanics_in_Three_Dimensions", "https://www.khanacademy.org/science/physics/quantum-physics/atoms-and-electrons/a/the-quantum-number"]'),
  ('radiance_formula', '{"en-us": "Radiance from radiant intensity and area"}', 'electromagnetic_waves', 8, '{"en-us": "Radiance is the radiant flux emitted, reflected, transmitted, or received by a surface per unit solid angle per unit projected area. It is a directional quantity used to characterize how much power a surface delivers to an optical system observing it from a given direction, and is conserved by ideal lossless optical systems."}', '["https://en.wikipedia.org/wiki/Radiance", "https://physics.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_(OpenStax)/01%3A_The_Nature_of_Light/1.05%3A_Radiometry", "https://www.britannica.com/science/radiance", "https://www.rp-photonics.com/radiance.html", "https://www.edmundoptics.com/knowledge-center/tech-tools/radiance/"]'),
  ('radiation_pressure_absorbed', '{"en-us": "Radiation pressure on a perfect absorber"}', 'electromagnetic_waves', 8, '{"en-us": "Radiation pressure is the mechanical pressure exerted when electromagnetic radiation transfers momentum to a surface. On a perfect (black-body) absorber at normal incidence, the pressure equals the incident irradiance divided by the speed of light, in agreement with Maxwell''s theory and confirmed experimentally by Lebedev. The effect is small in everyday settings but governs solar-sail propulsion, dust dynamics in the solar system, and stellar-interior physics."}', '["https://en.wikipedia.org/wiki/Radiation_pressure", "https://en.wikipedia.org/wiki/Solar_sail", "https://en.wikipedia.org/wiki/Poynting%E2%80%93Robertson_effect", "https://www.britannica.com/science/radiation-pressure", "https://phys.libretexts.org/Bookshelves/Optics/Book%3A_Geometric_Optics_(Tunnell)/1%3A_Introduction/1.2%3A_Properties_of_Light"]'),
  ('radioactive_activity_from_half_life', '{"en-us": "Activity from half-life and number of nuclei"}', 'nuclear_physics', 8, '{"en-us": "The activity of a radioactive sample is the number of nuclear decays per unit time. It equals the decay constant lambda times the number of remaining nuclei, and since the decay constant is related to the half-life by t_{1/2} = ln(2)/lambda, the activity can be written directly in terms of the half-life and the number of parent nuclei. This relation is used to compute activities from known half-lives, particularly in radiometric dating and radioactive-equilibrium problems."}', '["https://en.wikipedia.org/wiki/Radioactive_decay", "https://en.wikipedia.org/wiki/Half-life", "https://en.wikipedia.org/wiki/Decay_constant", "https://en.wikipedia.org/wiki/Becquerel", "https://www.nuclear-power.com/nuclear-engineering/radiation-detection/activity/", "https://physics.info/half-life/"]'),
  ('radioactive_carbon_dating', '{"en-us": "Radiocarbon dating formula"}', 'nuclear_physics', 8, '{"en-us": "Radiocarbon dating determines the age of an organic sample by measuring how much carbon-14 remains relative to the original amount. The technique, developed by Willard Libby, relies on the fact that a living organism exchanges carbon with the atmosphere and so maintains a known C-14 fraction, but after death the C-14 decays with its characteristic half-life. Calibrated against tree-ring and other records, the formula is foundational to archaeology and Quaternary geology."}', '["https://en.wikipedia.org/wiki/Radiocarbon_dating", "https://en.wikipedia.org/wiki/Carbon-14", "https://en.wikipedia.org/wiki/Half-life", "https://en.wikipedia.org/wiki/Radioactive_decay", "https://www.britannica.com/science/radiocarbon-dating", "https://www.radiocarbon.com/carbon-dating.htm"]'),
  ('radioactive_decay', '{"en-us": "Radioactive decay law"}', 'nuclear_physics', 7, '{"en-us": "The radioactive decay law states that for a sample of a single radionuclide, the number of radioactive nuclei remaining after time t follows an exponential decay governed by a characteristic decay constant lambda. Each species of unstable nucleus has its own decay constant, related to its half-life by t_{1/2} = ln(2)/lambda. The law underpins radiometric dating, nuclear medicine dosimetry, and reactor physics."}', '["https://en.wikipedia.org/wiki/Radioactive_decay", "https://en.wikipedia.org/wiki/Exponential_decay", "https://en.wikipedia.org/wiki/Decay_constant", "https://en.wikipedia.org/wiki/Mean_lifetime", "https://physics.info/half-life/", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Nuclear_Chemistry/Rate_of_Radioactive_Decay"]'),
  ('radioactive_equilibrium_activity', '{"en-us": "Radioactive equilibrium activity"}', 'nuclear_physics', 8, '{"en-us": "In a parent-daughter radioactive chain, secular or transient equilibrium is reached when the daughter''s production rate equals its decay rate, so its activity matches the parent''s. This requires the parent to have a much longer half-life than the daughter, and it underpins radionuclide generator systems such as Mo-99/Tc-99m used in medical imaging."}', '["https://en.wikipedia.org/wiki/Secular_equilibrium", "https://en.wikipedia.org/wiki/Transient_equilibrium", "https://en.wikipedia.org/wiki/Bateman_equation", "https://en.wikipedia.org/wiki/Radioactive_decay", "https://en.wikipedia.org/wiki/Decay_chain", "https://goldbook.iupac.org/S05532.html"]'),
  ('range_statistics', '{"en-us": "Range of a data set"}', 'statistics', 2, '{"en-us": "The range is the simplest measure of statistical dispersion of a data set, defined as the difference between the largest and smallest observed values. Although it conveys only the extremes of the sample and is sensitive to outliers, it gives a quick sense of data spread in exploratory data analysis and is closely related to the distribution of order statistics."}', '["https://en.wikipedia.org/wiki/Range_(statistics)", "https://en.wikipedia.org/wiki/Sample_maximum_and_minimum", "https://en.wikipedia.org/wiki/Order_statistic", "https://en.wikipedia.org/wiki/Statistical_dispersion", "https://www.britannica.com/statistics/range-statistics", "https://www.scribbr.com/statistics/range/"]'),
  ('raoults_law', '{"en-us": "Raoult''s law"}', 'solutions', 7, '{"en-us": "Raoult''s law states that the partial vapor pressure of each component of an ideal solution is equal to the vapor pressure of the pure component multiplied by its mole fraction. It serves as the defining characteristic of an ideal solution and provides the basis for understanding vapor–liquid equilibrium, distillation, and the colligative lowering of vapor pressure when a nonvolatile solute is dissolved in a solvent."}', '["https://en.wikipedia.org/wiki/Raoult%27s_law", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/Solutions_and_Mixtures/Ideal_Solutions/Changes_In_Vapor_Pressure_Raoult''s_Law", "https://www.britannica.com/science/Raoults-law", "https://en.wikipedia.org/wiki/Ideal_solution", "https://www.chem.purdue.edu/ outreach/chemcamp/Resources/09_Raoult''s_Law.pdf"]'),
  ('rate_law', '{"en-us": "Rate law"}', 'chemical_kinetics', 6, '{"en-us": "A rate law (or rate equation) expresses the rate of a chemical reaction as proportional to a rate constant times the concentrations of the reactants raised to empirically determined powers called reaction orders. The exponents and overall order cannot in general be deduced from stoichiometry and must be found experimentally, then used to infer information about the reaction mechanism."}', '["https://en.wikipedia.org/wiki/Rate_equation", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Kinetics/02:_Reaction_Rates", "https://en.wikipedia.org/wiki/Order_of_reaction", "https://www.britannica.com/science/chemical-kinetics/The-rate-law", "https://www.chemguide.co.uk/physical/basicrates/rateorders.html"]'),
  ('rate_of_reaction_definition', '{"en-us": "Rate of chemical reaction"}', 'chemical_reactions', 5, '{"en-us": "The rate of a chemical reaction is defined as the change in concentration of a reactant or product per unit time, with the sign chosen so that the rate is always positive. It is typically expressed using the negative time derivative of a reactant concentration, or the positive time derivative of a product concentration, and serves as the basis for the rate law in chemical kinetics."}', '["https://en.wikipedia.org/wiki/Reaction_rate", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Kinetics/02:_Reaction_Rates/2.05:_Reaction_Rate", "https://www.britannica.com/science/chemical-kinetics/The-rate-law", "https://www.chemguide.co.uk/physical/basicrates/introduction.html", "https://opentextbc.ca/chemistry/chapter/12-2-chemical-reaction-rates/"]'),
  ('rational_exponent_rule', '{"en-us": "Rational exponent rule"}', 'exponents', 4, '{"en-us": "The rational exponent rule expresses a power with a fractional exponent equivalently as a radical: a^(m/n) is the same as the n-th root of a raised to the m-th power, or equivalently the n-th root of a^m. It links fractional exponents to radicals and is the basis for simplifying expressions that mix roots and powers."}', '["https://en.wikipedia.org/wiki/Exponentiation#Rational_exponents", "https://math.libretexts.org/Bookshelves/Algebra/Intermediate_Algebra/04%3A_Rational_Exponents_and_Radicals", "https://www.khanacademy.org/math/algebra/x2f8bb11595b61c86:rational-exponents-and-radicals", "https://www.cuemath.com/algebra/rational-exponents/", "https://www.britannica.com/science/exponentiation"]'),
  ('rayleigh_criterion', '{"en-us": "Rayleigh criterion"}', 'diffraction', 8, '{"en-us": "The Rayleigh criterion is the conventional diffraction-limited angular resolution for a circular aperture, defining the minimum angular separation at which two point sources can be distinguished. Two incoherent point sources are regarded as just resolved when the principal diffraction maximum of one image coincides with the first minimum of the Airy pattern of the other."}', '["https://en.wikipedia.org/wiki/Angular_resolution#The_Rayleigh_criterion", "https://en.wikipedia.org/wiki/Diffraction-limited_system", "https://www.britannica.com/science/Rayleigh-criterion", "https://www.microscopyu.com/microscopy-basics/resolution", "https://www.edmundoptics.com/knowledge-center/application-notes/optics/the-rayleigh-criterion/"]'),
  ('rayleigh_jeans_law', '{"en-us": "Rayleigh-Jeans law (blackbody radiation)"}', 'quantum_mechanics', 9, '{"en-us": "The Rayleigh–Jeans law is the classical low-frequency approximation to the spectral energy density of blackbody radiation, derived from the equipartition theorem applied to standing electromagnetic waves. It agrees with measurements at long wavelengths (low frequencies) but diverges at short wavelengths, the failure known as the ultraviolet catastrophe that motivated Planck''s quantum hypothesis."}', '["https://en.wikipedia.org/wiki/Rayleigh%E2%80%93Jeans_law", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Quantum_Mechanics/02._Fundamental_Concepts_of_Quantum_Mechanics/Deriving_the_Rayleigh-Jeans_Radiation_Law", "https://www.britannica.com/science/Rayleigh-Jeans-law", "https://hyperphysics.phy-astr.gsu.edu/hbase/quantum/rayj.html", "https://en.wikipedia.org/wiki/Ultraviolet_catastrophe"]'),
  ('rc_capacitor_voltage_charging', '{"en-us": "Capacitor voltage during RC charging"}', 'circuits', 7, '{"en-us": "In a series RC circuit driven by a DC source, the voltage across the charging capacitor rises asymptotically from zero toward the source voltage. The approach is exponential and at one time constant the capacitor reaches about 63.2% of its final value."}', '["https://en.wikipedia.org/wiki/RC_circuit", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/10%3A_Direct-Current_Circuits/10.06%3A_RC_Circuits", "https://en.wikipedia.org/wiki/Time_constant", "https://www.khanacademy.org/science/electrical-engineering/ee-circuit-analysis-topic/ee-natural-and-forced-response/v/ee-charging-capacitor", "https://www.allaboutcircuits.com/textbook/direct-current/chpt-16/voltage-and-current-calculations/"]'),
  ('rc_circuit_charging', '{"en-us": "RC circuit charging"}', 'circuits', 7, '{"en-us": "When a capacitor in a series RC circuit is charged by a DC source through a resistor, the charge on the capacitor grows exponentially toward its maximum value. At one time constant the capacitor holds about 63.2% of its final charge."}', '["https://en.wikipedia.org/wiki/RC_circuit", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/10%3A_Direct-Current_Circuits/10.06%3A_RC_Circuits", "https://en.wikipedia.org/wiki/Time_constant", "https://www.khanacademy.org/science/electrical-engineering/ee-circuit-analysis-topic/ee-natural-and-forced-response/v/ee-charging-capacitor"]'),
  ('rc_circuit_discharging', '{"en-us": "RC circuit discharging"}', 'circuits', 7, '{"en-us": "When a charged capacitor in a series RC circuit is allowed to discharge through a resistor, the charge on the capacitor decays exponentially from its initial value toward zero. At one time constant the remaining charge is about 36.8% of the initial value."}', '["https://en.wikipedia.org/wiki/RC_circuit", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/10%3A_Direct-Current_Circuits/10.06%3A_RC_Circuits", "https://en.wikipedia.org/wiki/Time_constant", "https://www.allaboutcircuits.com/textbook/direct-current/chpt-16/voltage-and-current-calculations/"]'),
  ('rc_cutoff_frequency', '{"en-us": "RC circuit cutoff frequency"}', 'circuits', 7, '{"en-us": "For a first-order RC filter, the cutoff (or corner) frequency is the frequency at which the output power falls to half its passband value, corresponding to a -3 dB gain. It is the reciprocal of the time constant and marks the boundary between a filter''s passband and transition band."}', '["https://en.wikipedia.org/wiki/RC_circuit", "https://en.wikipedia.org/wiki/Cutoff_frequency", "https://en.wikipedia.org/wiki/Time_constant", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/10%3A_Direct-Current_Circuits/10.06%3A_RC_Circuits", "https://www.allaboutcircuits.com/textbook/direct-current/chpt-16/voltage-and-current-calculations/"]'),
  ('rc_discharge_current', '{"en-us": "RC circuit discharge current"}', 'circuits', 7, '{"en-us": "When a charged capacitor discharges through a resistor, the current decays exponentially in magnitude. With the conventional sign choice the current flows opposite to the charging direction, so the signed current is negative of the initial value, and at one time constant it has fallen to about 36.8% of its initial magnitude."}', '["https://en.wikipedia.org/wiki/RC_circuit", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/10%3A_Direct-Current_Circuits/10.06%3A_RC_Circuits", "https://en.wikipedia.org/wiki/Time_constant", "https://www.allaboutcircuits.com/textbook/direct-current/chpt-16/voltage-and-current-calculations/"]'),
  ('rc_time_constant', '{"en-us": "RC time constant"}', 'circuits', 7, '{"en-us": "The RC time constant characterizes how quickly a first-order RC circuit responds to a step change in voltage or current. It is also the reciprocal of the angular cutoff frequency and sets the time scale for both charging and discharging transients."}', '["https://en.wikipedia.org/wiki/RC_circuit", "https://en.wikipedia.org/wiki/Time_constant", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/10%3A_Direct-Current_Circuits/10.06%3A_RC_Circuits", "https://www.allaboutcircuits.com/textbook/direct-current/chpt-16/voltage-and-current-calculations/"]'),
  ('reaction_quotient', '{"en-us": "Reaction quotient"}', 'chemical_equilibrium', 7, '{"en-us": "The reaction quotient Q is a dimensionless quantity that measures the relative amounts of products and reactants in a reaction mixture at any instant; comparing Q to the equilibrium constant K predicts the direction in which the reaction must shift to reach equilibrium."}', '["https://en.wikipedia.org/wiki/Reaction_quotient", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Equilibria/Chemical_Equilibria/The_Reaction_Quotient", "https://www.khanacademy.org/science/chemistry/chemical-equilibrium/xa3595dfbab0ae5e7:equilibrium-constant/xa3595dfbab0ae5e7/the-reaction-quotient", "https://www.chem.purdue.edu/gchelp/howtosolveit/Equilibrium/Reaction_Quotient.htm"]'),
  ('reaction_rate_appearance', '{"en-us": "Reaction rate from appearance of product"}', 'chemical_reactions', 5, '{"en-us": "The rate of a chemical reaction, by the IUPAC definition, equals the reciprocal of the stoichiometric coefficient of a product times the time derivative of its concentration; this relates the rate of product appearance to a single, species-independent reaction rate."}', '["https://en.wikipedia.org/wiki/Reaction_rate", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Kinetics/Reaction_Rates/Reaction_Rate", "https://www.khanacademy.org/science/chemistry/chemical-kinetics/xa3595dfbab0ae5e7:rate-law/xa3595dfbab0ae5e7/reaction-rates-and-rate-laws"]'),
  ('reaction_rate_consumption', '{"en-us": "Reaction rate from reactant consumption"}', 'chemical_reactions', 5, '{"en-us": "The rate of a chemical reaction, by the IUPAC definition, equals minus the reciprocal of the stoichiometric coefficient of a reactant times the time derivative of its concentration, ensuring the rate is positive even as reactant concentration decreases."}', '["https://en.wikipedia.org/wiki/Reaction_rate", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Kinetics/Reaction_Rates/Reaction_Rate", "https://www.khanacademy.org/science/chemistry/chemical-kinetics/xa3595dfbab0ae5e7:rate-law/xa3595dfbab0ae5e7/reaction-rates-and-rate-laws"]'),
  ('reactive_power_ac', '{"en-us": "Reactive power in AC circuit"}', 'circuits', 8, '{"en-us": "Reactive power Q in a sinusoidal AC circuit equals the product of the RMS voltage, RMS current, and the sine of the phase angle between them; it represents the rate at which energy is exchanged between the source and reactive storage elements (inductors and capacitors) without net energy transfer."}', '["https://en.wikipedia.org/wiki/AC_power", "https://en.wikipedia.org/wiki/Volt-ampere_reactive", "https://www.electronics-tutorials.ws/accircuits/power-in-ac-circuits.html", "https://www.khanacademy.org/science/electrical-engineering/ee-circuit-analysis-topic/ee-ac-analysis/v/ee-ac-power", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Alternating-Current_Circuits/15.04%3A_Power_in_an_AC_Circuit"]'),
  ('reduced_mass', '{"en-us": "Reduced mass"}', 'classical_mechanics', 8, '{"en-us": "The reduced mass mu of two bodies with masses m1 and m2 is the effective inertial mass appearing in the equivalent one-body problem; it allows a two-body system with an internal force to be treated as a single particle of mass mu under the same force, simplifying classical and quantum mechanical analysis."}', '["https://en.wikipedia.org/wiki/Reduced_mass", "https://physics.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Tatum)/4%3A_Two-Body_Central_Force_Problems/4.1%3A_Reduced_Mass", "https://hyperphysics.phy-astr.gsu.edu/hbase/orbv.html#rm", "https://www.britannica.com/science/reduced-mass", "https://openstax.org/books/university-physics-volume-1/pages/9-6-the-two-body-problem"]'),
  ('reflectance_formula', '{"en-us": "Reflectance"}', 'optics', 7, '{"en-us": "Reflectance is the dimensionless ratio of the radiant flux reflected by a surface to the radiant flux incident on it, characterizing how effectively a material reflects electromagnetic radiation; it generally depends on wavelength, polarization, and angle of incidence."}', '["https://en.wikipedia.org/wiki/Reflectance", "https://phys.libretexts.org/Bookshelves/Optics/Geometric_Optics_(Tatum)/04%3A_Reflection_and_Refraction/4.04%3A_Reflectance_and_Transmittance", "https://www.britannica.com/science/reflectance-optics", "https://www.rp-photonics.com/reflectance.html"]'),
  ('reflection_coefficient_normal_incidence', '{"en-us": "Reflection coefficient at normal incidence"}', 'reflection', 8, '{"en-us": "The reflectance at normal incidence from a single interface between two non-absorbing media, derived from the Fresnel equations. It gives the fraction of incident optical power reflected; for example, an air-glass interface (n ≈ 1.5) reflects about 4% of normally incident light per surface."}', '["https://en.wikipedia.org/wiki/Fresnel_equations", "https://en.wikipedia.org/wiki/Reflection_coefficient", "https://en.wikipedia.org/wiki/Refractive_index", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/01%3A_The_Nature_of_Light/1.03%3A_The_Law_of_Reflection", "https://www.britannica.com/science/Fresnel-equations"]'),
  ('reflection_law', '{"en-us": "Reflection Law"}', 'reflection', 3, '{"en-us": "The law of reflection states that the angle of incidence equals the angle of reflection, and that the incident ray, reflected ray, and surface normal all lie in the same plane. It applies to specular (mirror-like) reflection from smooth surfaces."}', '["https://en.wikipedia.org/wiki/Specular_reflection", "https://en.wikipedia.org/wiki/Law_of_reflection", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/01%3A_The_Nature_of_Light/1.03%3A_The_Law_of_Reflection", "https://www.britannica.com/science/law-of-reflection"]'),
  ('reflection_mirror_image_distance', '{"en-us": "Image distance in a plane mirror"}', 'reflection', 4, '{"en-us": "For an object placed in front of a plane mirror, the virtual image appears the same distance behind the mirror as the object is in front of it. The image is the same size as the object, erect, and laterally reversed."}', '["https://en.wikipedia.org/wiki/Mirror_image", "https://en.wikipedia.org/wiki/Plane_mirror", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/02%3A_Image_Formation/2.02%3A_Images_Formed_by_Plane_Mirrors", "https://www.britannica.com/technology/plane-mirror"]'),
  ('refractive_index_formula', '{"en-us": "Refractive index"}', 'refraction', 5, '{"en-us": "The absolute refractive index of a medium is the ratio of the speed of light in vacuum to the phase velocity of light in the medium. It determines how strongly light is refracted upon entering the medium, as described by Snell''s law, and is generally greater than or equal to 1."}', '["https://en.wikipedia.org/wiki/Refractive_index", "https://en.wikipedia.org/wiki/Snell%27s_law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/01%3A_The_Nature_of_Light/1.04%3A_Total_Internal_Reflection", "https://www.britannica.com/science/refractive-index", "https://www.khanacademy.org/science/physics/geometric-optics/index-of-refraction/v/index-of-refraction-and-dispersion"]'),
  ('regular_polygon_apothem_area', '{"en-us": "Regular polygon apothem area"}', 'polygons', 5, '{"en-us": "The area of a regular polygon equals half the product of its apothem (perpendicular distance from the center to a side) and its perimeter. This follows from decomposing the polygon into n congruent isosceles triangles of equal height."}', '["https://en.wikipedia.org/wiki/Regular_polygon", "https://en.wikipedia.org/wiki/Apothem", "https://mathworld.wolfram.com/Apothem.html", "https://math.libretexts.org/Bookshelves/Geometry/Geometry_(OpenStax)", "https://www.cuemath.com/geometry/area-of-regular-polygon/"]'),
  ('regular_polygon_area', '{"en-us": "Area of a regular polygon"}', 'polygons', 5, '{"en-us": "The area of a regular n-sided polygon expressed in terms of its side length s. Equivalent forms use the apothem a (A = n a² tan(π/n)) or circumradius R (A = nR² sin(2π/n)/2)."}', '["https://en.wikipedia.org/wiki/Regular_polygon", "https://en.wikipedia.org/wiki/Apothem", "https://mathworld.wolfram.com/RegularPolygon.html", "https://math.libretexts.org/Bookshelves/Geometry/Geometry_(OpenStax)", "https://www.cuemath.com/geometry/area-of-regular-polygon/"]'),
  ('regular_polygon_perimeter', '{"en-us": "Regular polygon perimeter"}', 'polygons', 3, '{"en-us": "A regular polygon is equiangular and equilateral. Because all n sides have the same length s, its perimeter is simply the number of sides multiplied by the side length."}', '["https://en.wikipedia.org/wiki/Regular_polygon", "https://mathworld.wolfram.com/RegularPolygon.html", "https://www.cuemath.com/geometry/perimeter-of-regular-polygon/", "https://www.khanacademy.org/math/geometry-home/triangle-properties/perimeter-and-area-of-triangles/a/perimeter-and-area-of-polygons"]'),
  ('regular_tetrahedron_volume', '{"en-us": "Volume of a regular tetrahedron"}', 'plane_geometry', 6, '{"en-us": "A regular tetrahedron is a triangular pyramid whose four faces are congruent equilateral triangles of edge length a. Its volume is one third the base area times the height, simplifying to a closed-form expression involving the square root of 2."}', '["https://en.wikipedia.org/wiki/Tetrahedron#Volume", "https://en.wikipedia.org/wiki/Regular_tetrahedron", "https://mathworld.wolfram.com/RegularTetrahedron.html", "https://www.cuemath.com/geometry/volume-of-tetrahedron/", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/01%3A_Units_and_Measurement/1.06%3A_Dimensional_Analysis"]'),
  ('relative_density_formula', '{"en-us": "Relative density (specific gravity)"}', 'buoyancy', 4, '{"en-us": "Relative density, also called specific gravity, is a dimensionless quantity defined as the ratio of the density of a substance to the density of a reference material, conventionally water at 4 degrees Celsius for liquids and solids, or air for gases."}', '["https://en.wikipedia.org/wiki/Relative_density", "https://www.britannica.com/science/specific-gravity", "https://chem.libretexts.org/Bookshelves/Introductory_Chemistry/Beginning_Chemistry_(Ball)/Chapter_03%3A_Matter_and_Energy/3.02%3A_Measuring_Matter", "https://www.thoughtco.com/definition-of-specific-gravity-605924", "https://www.engineeringtoolbox.com/specific-gravity-d_294.html"]'),
  ('relative_intensity_sound_pressure', '{"en-us": "Sound intensity level from pressure amplitude"}', 'mechanical_waves', 7, '{"en-us": "Because sound intensity is proportional to the square of the sound pressure amplitude, the sound intensity level in decibels can equivalently be expressed in terms of the sound pressure and a reference pressure. This is sometimes called the sound pressure level when referenced to the standard threshold of human hearing."}', '["https://en.wikipedia.org/wiki/Sound_pressure#Sound_pressure_level", "https://en.wikipedia.org/wiki/Sound_intensity", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/17%3A_Sound/17.04%3A_Sound_Intensity", "https://www.engineeringtoolbox.com/sound-intensity-d_739.html", "https://www.animations.physics.unsw.edu.au/jw/dB.htm"]'),
  ('relative_refractive_index', '{"en-us": "Relative refractive index"}', 'refraction', 5, '{"en-us": "The relative refractive index of one medium with respect to another is the ratio of the speed of light in the second medium to that in the first, and is what enters Snell''s law when neither medium is vacuum."}', '["https://en.wikipedia.org/wiki/Refractive_index#Definition", "https://en.wikipedia.org/wiki/Snell%27s_law", "https://phys.libretexts.org/Bookshelves/Optics/Geometric_Optics_(Konopinski)/03%3A_Refraction/3.02%3A_Snell''s_Law_and_the_Refractive_Index", "https://www.britannica.com/science/refractive-index", "https://opentextbc.ca/physicstestbook2/chapter/the-law-of-refraction/"]'),
  ('relativistic_doppler_effect', '{"en-us": "Relativistic Doppler effect (approaching)"}', 'relativity', 9, '{"en-us": "The relativistic Doppler effect describes the frequency shift of light between a source and observer moving toward or away from each other, accounting for time dilation in special relativity. It predicts a larger blueshift for approach than the classical Doppler formula and a redshift for recession."}', '["https://en.wikipedia.org/wiki/Relativistic_Doppler_effect", "https://en.wikipedia.org/wiki/Doppler_effect#Relativistic_Doppler_effect", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/05%3A_Relativity/5.09%3A_The_Relativistic_Doppler_Effect", "https://www.astronomy.ohio-state.edu/pogge.1/Ast162/Unit5/SpecShift.html", "https://www.feynmanlectures.caltech.edu/I_34.html"]'),
  ('relativistic_energy_momentum', '{"en-us": "Relativistic energy-momentum relation"}', 'relativity', 9, '{"en-us": "The energy-momentum relation of special relativity relates a free particle''s total energy, invariant (rest) mass, and the magnitude of its relativistic momentum. In flat (Minkowski) spacetime it follows from the Lorentz-invariant norm of the four-momentum and reduces to mass-energy equivalence in the rest frame."}', '["https://en.wikipedia.org/wiki/Energy%E2%80%93momentum_relation", "https://en.wikipedia.org/wiki/Four-momentum", "https://en.wikipedia.org/wiki/Special_relativity", "https://phys.libretexts.org/Bookshelves/Relativity/Book%3A_Special_Relativity_(Crowell)", "https://www.britannica.com/science/relativistic-mechanics"]'),
  ('relativistic_energy_particle', '{"en-us": "Relativistic energy of a particle"}', 'particle_physics', 9, '{"en-us": "The total relativistic energy of a free particle is the positive square root of the rest-energy squared plus the momentum-times-c squared. It is the time component of the particle''s four-momentum and is used throughout particle and high-energy physics to label states by their energy and momentum."}', '["https://en.wikipedia.org/wiki/Energy%E2%80%93momentum_relation", "https://en.wikipedia.org/wiki/Four-momentum", "https://en.wikipedia.org/wiki/Mass_in_special_relativity", "https://en.wikipedia.org/wiki/Special_relativity", "https://phys.libretexts.org/Bookshelves/Relativity/Book%3A_Special_Relativity_(Crowell)"]'),
  ('relativistic_kinetic_energy', '{"en-us": "Relativistic kinetic energy"}', 'relativity', 9, '{"en-us": "The relativistic kinetic energy of a particle is the difference between its total relativistic energy and its rest energy. In the low-velocity limit it reduces to the familiar ½mv², while for speeds approaching the speed of light it diverges, ensuring no massive particle can reach c."}', '["https://en.wikipedia.org/wiki/Kinetic_energy#Relativistic_kinetic_energy", "https://en.wikipedia.org/wiki/Energy%E2%80%93momentum_relation", "https://en.wikipedia.org/wiki/Mass_in_special_relativity", "https://phys.libretexts.org/Bookshelves/Relativity/Book%3A_Special_Relativity_(Crowell)", "https://www.britannica.com/science/relativistic-mechanics"]'),
  ('relativistic_mass', '{"en-us": "Relativistic mass"}', 'relativity', 9, '{"en-us": "Relativistic mass is the frame-dependent mass obtained by multiplying a body''s rest mass by the Lorentz factor. Modern particle and nuclear physics generally avoids the term in favor of working directly with relativistic energy, but the concept is still widely used in introductory treatments and in relativistic quantum chemistry."}', '["https://en.wikipedia.org/wiki/Mass_in_special_relativity", "https://en.wikipedia.org/wiki/Relativistic_mass", "https://en.wikipedia.org/wiki/Lorentz_factor", "https://phys.libretexts.org/Bookshelves/Relativity/Book%3A_Special_Relativity_(Crowell)", "https://www.britannica.com/science/relativistic-mass"]'),
  ('relativistic_momentum', '{"en-us": "Relativistic momentum"}', 'relativity', 8, '{"en-us": "Relativistic momentum is the spatial part of the four-momentum of a particle: the product of rest mass, velocity, and the Lorentz factor. It is conserved in collisions consistent with special relativity and reduces to the classical expression mv in the low-velocity limit."}', '["https://en.wikipedia.org/wiki/Momentum#Relativistic", "https://en.wikipedia.org/wiki/Four-momentum", "https://en.wikipedia.org/wiki/Lorentz_factor", "https://en.wikipedia.org/wiki/Special_relativity", "https://phys.libretexts.org/Bookshelves/Relativity/Book%3A_Special_Relativity_(Crowell)"]'),
  ('relativistic_velocity_addition', '{"en-us": "Relativistic velocity addition"}', 'relativity', 9, '{"en-us": "The relativistic velocity-addition formula combines the velocity of an object in one inertial frame with the relative velocity of a second frame, producing the object''s velocity as seen from the first. The result is always subluminal, in agreement with the postulate that no signal can outrun light."}', '["https://en.wikipedia.org/wiki/Velocity-addition_formula", "https://en.wikipedia.org/wiki/Special_relativity", "https://en.wikipedia.org/wiki/Lorentz_transformation", "https://phys.libretexts.org/Bookshelves/Relativity/Book%3A_Special_Relativity_(Crowell)", "https://www.britannica.com/science/relativistic-mechanics"]'),
  ('relativity_energy_momentum_invariant', '{"en-us": "Energy-momentum invariant"}', 'relativity', 9, '{"en-us": "The relativistic invariant relating a free particle''s total energy to its rest mass and momentum in special relativity. It reduces to the rest-energy relation when momentum vanishes and to E = pc for massless particles such as photons."}', '["https://en.wikipedia.org/wiki/Energy%E2%80%93momentum_relation", "https://en.wikipedia.org/wiki/Four-momentum", "https://en.wikipedia.org/wiki/Mass_in_special_relativity", "https://en.wikipedia.org/wiki/Mass%E2%80%93energy_equivalence"]'),
  ('residual_standard_error', '{"en-us": "Residual standard error"}', 'statistics', 8, '{"en-us": "The residual standard error is the square root of the residual sum of squares divided by the residual degrees of freedom, used to estimate the standard deviation of the unobserved errors in a linear regression. It serves as a goodness-of-fit measure, with smaller values indicating that observations lie closer to the fitted regression line."}', '["https://en.wikipedia.org/wiki/Errors_and_residuals", "https://en.wikipedia.org/wiki/Residual_sum_of_squares", "https://en.wikipedia.org/wiki/Standard_error", "https://en.wikipedia.org/wiki/Degrees_of_freedom_(statistics)"]'),
  ('resistance_formula', '{"en-us": "Resistance of a conductor"}', 'circuits', 5, '{"en-us": "The electrical resistance of a uniform conductor is proportional to its length and inversely proportional to its cross-sectional area, with the resistivity as the constant of proportionality. This relation, sometimes called Pouillet''s law, applies to ohmic materials with uniform geometry and resistivity."}', '["https://en.wikipedia.org/wiki/Electrical_resistivity_and_conductivity", "https://en.wikipedia.org/wiki/Electrical_resistance_and_conductance", "https://en.wikipedia.org/wiki/Resistor", "https://en.wikipedia.org/wiki/Pouillet%27s_law"]'),
  ('resistivity_temperature', '{"en-us": "Resistivity temperature dependence"}', 'circuits', 7, '{"en-us": "The resistance of a conductor varies approximately linearly with temperature over a limited range, expressed as the resistance at a reference temperature multiplied by one plus the temperature coefficient times the temperature change. This linear approximation is widely used for metals near room temperature, where the temperature coefficient of resistance is small and positive."}', '["https://en.wikipedia.org/wiki/Electrical_resistivity_and_conductivity#Temperature_dependence", "https://en.wikipedia.org/wiki/Electrical_resistance_and_conductance", "https://en.wikipedia.org/wiki/Temperature_coefficient_of_resistance", "https://en.wikipedia.org/wiki/Resistor"]'),
  ('resonance_bandwidth', '{"en-us": "Resonance bandwidth"}', 'circuits', 8, '{"en-us": "The bandwidth of a resonant system is inversely proportional to its quality factor, with higher Q producing narrower resonances and greater frequency selectivity. It is typically defined as the full width at half maximum of the resonance peak, governing how sharply a tuned circuit or filter responds around its center frequency."}', '["https://en.wikipedia.org/wiki/Q_factor", "https://en.wikipedia.org/wiki/Bandwidth_(signal_processing)", "https://en.wikipedia.org/wiki/Resonance", "https://en.wikipedia.org/wiki/RLC_circuit"]'),
  ('retention_factor', '{"en-us": "Retention factor in chromatography"}', 'analytical_chemistry', 7, '{"en-us": "The retention factor is the ratio of the distance traveled by an analyte to the distance traveled by the solvent front in planar chromatography, providing a characteristic value used to identify compounds. Values lie between zero and one, and the same stationary and mobile phases should be used when comparing R_f values across experiments."}', '["https://en.wikipedia.org/wiki/Retardation_factor", "https://en.wikipedia.org/wiki/Thin-layer_chromatography", "https://en.wikipedia.org/wiki/Paper_chromatography", "https://en.wikipedia.org/wiki/Chromatography"]'),
  ('reynolds_number_critical_flow', '{"en-us": "Critical Reynolds number for transition to turbulence"}', 'reynolds_number', 8, '{"en-us": "The critical (or transitional) Reynolds number marks the threshold above which pipe flow becomes unstable and transitions from laminar to turbulent. The value is geometry-dependent, typically Re_D ≈ 2300 for flow in a circular pipe, and is widely used to predict flow regime in engineering design."}', '["https://en.wikipedia.org/wiki/Reynolds_number", "https://en.wikipedia.org/wiki/Laminar%E2%80%93turbulent_transition", "https://www.britannica.com/science/Reynolds-number", "https://eng.libretexts.org/Bookshelves/Chemical_Engineering/Fluid_Mechanics_(Barmeier)/08%3A_Flow_in_Pipes/8.3%3A_Flow_Transitions_in_Pipes", "https://byjus.com/physics/reynolds-number/"]'),
  ('reynolds_number_flow_regime_lam_turb', '{"en-us": "Reynolds number flow regime criterion"}', 'reynolds_number', 8, '{"en-us": "The empirical criterion Re < 2000 indicates fully developed laminar flow in a pipe, while values above approximately 4000 indicate fully turbulent flow; intermediate values give transitional, intermittent flow. This widely used engineering rule of thumb helps predict flow regime in pipe systems."}', '["https://en.wikipedia.org/wiki/Reynolds_number", "https://en.wikipedia.org/wiki/Laminar%E2%80%93turbulent_transition", "https://www.engineeringtoolbox.com/laminar-transitional-turbulent-flow-d_577.html", "https://www.britannica.com/science/Reynolds-number", "https://byjus.com/physics/laminar-flow/"]'),
  ('reynolds_number_formula', '{"en-us": "Reynolds number"}', 'reynolds_number', 7, '{"en-us": "The Reynolds number is a dimensionless quantity that quantifies the ratio of inertial to viscous forces in a fluid, predicting whether flow will be laminar or turbulent. It is fundamental in fluid dynamics for scaling experiments, designing pipe systems, and modeling flow around objects such as aircraft wings."}', '["https://en.wikipedia.org/wiki/Reynolds_number", "https://www.britannica.com/science/Reynolds-number", "https://eng.libretexts.org/Bookshelves/Chemical_Engineering/Fluid_Mechanics_(Barmeier)/08%3A_Flow_in_Pipes/8.1%3A_Flow_Regimes", "https://www.khanacademy.org/science/physics/fluids/fluid-dynamics/v/reynolds-number", "https://byjus.com/physics/reynolds-number/", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.07%3A_Reynolds_Number"]'),
  ('reynolds_number_kinematic_viscosity', '{"en-us": "Reynolds number with kinematic viscosity"}', 'reynolds_number', 8, '{"en-us": "The Reynolds number can equivalently be expressed using kinematic viscosity ν = μ/ρ instead of dynamic viscosity μ, which is convenient when only kinematic viscosity is tabulated for a fluid. This form is widely used in aerodynamics and open-channel flow calculations."}', '["https://en.wikipedia.org/wiki/Reynolds_number", "https://en.wikipedia.org/wiki/Kinematic_viscosity", "https://www.britannica.com/science/Reynolds-number", "https://eng.libretexts.org/Bookshelves/Chemical_Engineering/Fluid_Mechanics_(Barmeier)/08%3A_Flow_in_Pipes/8.1%3A_Flow_Regimes", "https://www.engineeringtoolbox.com/reynolds-number-d_237.html"]'),
  ('right_triangle_30_60_90', '{"en-us": "30-60-90 special right triangle"}', 'right_triangles', 3, '{"en-us": "In a 30-60-90 right triangle, the sides are in the ratio 1:√3:2, opposite the corresponding angles. The long leg is √3 times the short leg, a property that follows from bisecting an equilateral triangle and used to compute trigonometric values without a calculator."}', '["https://en.wikipedia.org/wiki/Special_right_triangle", "https://www.mathopenref.com/triangle306090.html", "https://math.libretexts.org/Bookshelves/Geometry/Geometry_(Illustrated_Mathematics)/06%3A_Right_Triangles_and_Trigonometry/6.04%3A_Special_Right_Triangles", "https://www.khanacademy.org/math/geometry/triangle-properties/triangle-inequality-theorem/v/30-60-90-triangle", "https://www.cuemath.com/geometry/30-60-90-triangle/"]'),
  ('rl_circuit_current_growth', '{"en-us": "Current growth in an RL circuit"}', 'circuits', 8, '{"en-us": "When a DC voltage is suddenly applied to a series RL circuit, the current rises exponentially from zero toward its steady-state value V/R with time constant τ = L/R. This transient growth arises because the inductor opposes changes in current, and it characterizes the delay before circuits reach steady operation."}', '["https://en.wikipedia.org/wiki/RL_circuit", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/13%3A_Electromagnetic_Induction/13.06%3A_RL_Circuits", "https://www.khanacademy.org/science/physics/electromagnetic-induction/induction-ac-circuits/v/rl-circuit-growth-time-constant", "https://www.britannica.com/science/RL-circuit", "https://byjus.com/physics/rl-circuit/"]'),
  ('rl_time_constant', '{"en-us": "RL circuit time constant"}', 'circuits', 7, '{"en-us": "The time constant of an RL circuit characterizes how quickly the current reaches its steady-state value after a step change in voltage, governing the exponential transient response of the circuit. It equals the ratio of inductance to resistance."}', '["https://en.wikipedia.org/wiki/RL_circuit", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/11%3A_Further_Applications_of_Magnetism/11.04%3A_RL_Circuits", "https://www.electronics-tutorials.ws/inductor/rl-circuits.html", "https://en.wikipedia.org/wiki/Time_constant"]'),
  ('rlc_resonant_frequency', '{"en-us": "RLC circuit resonant frequency"}', 'circuits', 7, '{"en-us": "The resonant frequency of a series RLC circuit is the frequency at which the inductive and capacitive reactances cancel, leaving a purely resistive impedance. The same expression in angular form is ω₀ = 1/√(LC)."}', '["https://en.wikipedia.org/wiki/RLC_circuit", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/14%3A_Alternating-Current_Circuits/14.05%3A_Resonance_in_an_AC_Circuit", "https://en.wikipedia.org/wiki/Resonance", "https://www.electronics-tutorials.ws/accircuits/rlc-circuit.html"]'),
  ('rms_current', '{"en-us": "RMS current from peak current"}', 'circuits', 7, '{"en-us": "Root-mean-square current for a sinusoidal waveform; the RMS value equals the peak amplitude divided by √2, and represents the equivalent DC current that delivers the same average power to a resistive load."}', '["https://en.wikipedia.org/wiki/Root_mean_square", "https://en.wikipedia.org/wiki/Alternating_current", "https://en.wikipedia.org/wiki/Amplitude", "https://www.electronics-tutorials.ws/accircuits/rms-value.html", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/15%3A_Alternating-Current_Circuits/15.03%3A_Simple_AC_Circuits"]'),
  ('rms_speed', '{"en-us": "Root mean square speed of gas molecules"}', 'ideal_gases', 7, '{"en-us": "The root-mean-square speed characterizes the typical speed of molecules in an ideal gas in thermal equilibrium, derived from the Maxwell–Boltzmann distribution. It depends on the absolute temperature and the molar mass of the gas, increasing with temperature and decreasing for heavier molecules."}', '["https://en.wikipedia.org/wiki/Kinetic_theory_of_gases", "https://en.wikipedia.org/wiki/Maxwell%E2%80%93Boltzmann_distribution", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Properties_of_Gases/Gas_Laws/The_Ideal_Gas_Law/Root_Mean_Square_Speed", "https://www.grc.nasa.gov/WWW/K-12/airplane/eqstat.html"]'),
  ('rms_voltage', '{"en-us": "RMS voltage from peak voltage"}', 'circuits', 7, '{"en-us": "Root-mean-square voltage for a sinusoidal waveform; the RMS value equals the peak amplitude divided by √2. Mains AC voltages are universally quoted in RMS so that the quoted number equals the equivalent DC value delivering the same average power."}', '["https://en.wikipedia.org/wiki/Root_mean_square", "https://en.wikipedia.org/wiki/Alternating_current", "https://en.wikipedia.org/wiki/Mains_electricity", "https://www.electronics-tutorials.ws/accircuits/rms-value.html", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/15%3A_Alternating-Current_Circuits/15.03%3A_Simple_AC_Circuits"]'),
  ('rocket_thrust_equation', '{"en-us": "Rocket thrust equation"}', 'newtons_laws', 7, '{"en-us": "The thrust generated by a rocket equals the rate at which propellant mass is expelled multiplied by the exhaust velocity relative to the vehicle, a direct consequence of Newton''s third law. The simplified form omits a pressure-thrust correction term and assumes optimal expansion of the exhaust."}', '["https://en.wikipedia.org/wiki/Thrust", "https://en.wikipedia.org/wiki/Rocket_engine", "https://en.wikipedia.org/wiki/Rocket_equation", "https://www.grc.nasa.gov/WWW/K-12/airplane/rockth.html", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Variational_Principles_in_Classical_Mechanics_(Fitzpatrick)/12%3A_Rocket_Motion"]'),
  ('rolling_kinetic_energy', '{"en-us": "Rolling kinetic energy"}', 'rotational_energy', 7, '{"en-us": "The total kinetic energy of a rigid body rolling without slipping is the sum of its translational kinetic energy (motion of the center of mass) and its rotational kinetic energy (spin about that center). The pure-rolling constraint v_cm = rω links the two terms, and the combined expression is widely used in analyzing wheels, cylinders, and spheres."}', '["https://en.wikipedia.org/wiki/Rolling", "https://en.wikipedia.org/wiki/Rotational_energy", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10%3A_Fixed-Axis_Rotation__Introduction/10.05%3A_Moment_of_Inertia_and_Rotational_Kinetic_Energy", "https://www.britannica.com/science/kinetic-energy"]'),
  ('root_as_exponent', '{"en-us": "Root as fractional exponent"}', 'exponents', 4, '{"en-us": "An nth root can be rewritten as a fractional power, with the index of the radical becoming the denominator of the exponent on the base. This equivalence, introduced in modern notation by Michel Rolle in 1690, allows the usual laws of exponents to be applied to radical expressions and vice versa."}', '["https://en.wikipedia.org/wiki/Nth_root", "https://math.libretexts.org/Bookshelves/Algebra/Intermediate_Algebra_1e_(OpenStax)/08%3A_Roots_and_Radicals/8.04%3A_Simplify_Rational_Exponents"]'),
  ('rotational_energy_from_work', '{"en-us": "Rotational work-energy theorem"}', 'rotational_energy', 7, '{"en-us": "The mechanical work done on a rigid body rotating about a fixed axis equals the integral of the net torque over the angular displacement, the rotational analog of the linear work integral. Equivalently, the net rotational work performed on the body equals its change in rotational kinetic energy, a result known as the work-energy theorem for rotation."}', '["https://en.wikipedia.org/wiki/Rotational_energy", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10%3A_Fixed-Axis_Rotation__Introduction/10.09%3A_Work_and_Power_for_Rotational_Motion"]'),
  ('rotational_ke_formula', '{"en-us": "Rotational kinetic energy"}', 'rotational_energy', 6, '{"en-us": "The kinetic energy of a rigid body rotating about a fixed axis is half the product of its moment of inertia and the square of its angular velocity. This is the rotational counterpart of the linear formula, with moment of inertia acting as the rotational analogue of mass and angular velocity as the analogue of linear speed."}', '["https://en.wikipedia.org/wiki/Rotational_energy", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10%3A_Fixed-Axis_Rotation__Introduction/10.05%3A_Moment_of_Inertia_and_Rotational_Kinetic_Energy"]'),
  ('rotational_ke_from_angular_momentum', '{"en-us": "Rotational kinetic energy from angular momentum (rotational_ke_from_angular_momentum)"}', 'rotational_energy', 7, '{"en-us": "For a rigid body rotating about a fixed axis, the angular momentum equals the product of the moment of inertia and the angular velocity. Eliminating the angular velocity in favor of the angular momentum gives a useful alternative expression for the rotational kinetic energy, which is convenient when L is conserved or measured directly."}', '["https://en.wikipedia.org/wiki/Angular_momentum", "https://en.wikipedia.org/wiki/Rotational_energy", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/11%3A__Angular_Momentum"]'),
  ('rotational_kinetic_energy', '{"en-us": "Rotational kinetic energy (rotational_kinetic_energy)"}', 'rotational_energy', 6, '{"en-us": "The kinetic energy of a rigid body rotating about a fixed axis is half the product of its moment of inertia and the square of its angular velocity, the rotational analog of the linear formula. Moment of inertia plays the role of mass, and the expression underpins the analysis of flywheels, gyroscopes, and rolling motion."}', '["https://en.wikipedia.org/wiki/Rotational_energy", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10%3A_Fixed-Axis_Rotation__Introduction/10.05%3A_Moment_of_Inertia_and_Rotational_Kinetic_Energy"]'),
  ('rotational_work', '{"en-us": "Rotational work done by a constant torque"}', 'rotational_energy', 7, '{"en-us": "The mechanical work done by a constant torque acting through an angular displacement. It is the rotational analog of the linear work–force relation and equals the integral of torque over the angle rotated."}', '["https://en.wikipedia.org/wiki/Rotational_energy", "https://en.wikipedia.org/wiki/Work_(physics)", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10%3A_Fixed-Axis_Rotation/10.08%3A_Work_and_Power_for_Rotational_Motion", "https://www.khanacademy.org/science/physics/torque-angular-momentum/rotational-kinetics/v/work-and-energy-for-rotational-motion"]'),
  ('rydberg_formula', '{"en-us": "Rydberg formula"}', 'atomic_physics', 8, '{"en-us": "The Rydberg formula gives the wavenumber of spectral lines emitted in atomic electron transitions of hydrogen, expressed as a constant times the difference of reciprocals of squared principal quantum numbers. It generalizes the Balmer series and applies to hydrogen-like ions, providing the empirical basis later explained by the Bohr model."}', '["https://en.wikipedia.org/wiki/Rydberg_formula", "https://en.wikipedia.org/wiki/Rydberg_constant", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Physical_Chemistry_(LibreTexts)/01%3A_The_Dawn_of_the_Quantum_Theory/1.05%3A_The_Rydberg_Formula_and_the_Hydrogen_Atomic_Spectrum", "https://www.britannica.com/science/Rydberg-constant", "https://physics.info/rydberg/"]'),
  ('sample_variance_bessel', '{"en-us": "Sample variance (Bessel''s correction)"}', 'statistics', 7, '{"en-us": "The unbiased estimator of population variance from a sample, obtained by replacing the divisor n with n-1. It corrects the bias introduced because the sample mean is used in place of the unknown population mean, leaving n-1 independent residuals."}', '["https://en.wikipedia.org/wiki/Bessel%27s_correction", "https://en.wikipedia.org/wiki/Sample_variance", "https://mathworld.wolfram.com/BesselsCorrection.html", "https://www.khanacademy.org/math/statistics-probability/summarizing-quantitative-data/variance-standard-deviation-sample/a/population-and-sample-standard-deviation-review", "https://www.britannica.com/topic/sample-variance"]'),
  ('saponification_value', '{"en-us": "Saponification value"}', 'organic_chemistry', 8, '{"en-us": "The saponification value (SV) of a fat or oil is the number of milligrams of KOH required to saponify one gram of the sample, inversely related to the average molecular weight of the constituent triglycerides. For a pure triglyceride it can be computed from the molar mass of the fat, since each triglyceride consumes three equivalents of KOH (molar mass 56.1 g/mol)."}', '["https://en.wikipedia.org/wiki/Saponification_value", "https://en.wikipedia.org/wiki/Saponification", "https://www.aocs.org/attain-lab-services/methods/methods/search/search-results?method=111542", "https://chem.libretexts.org/Bookshelves/Organic_Chemistry/Supplemental_Modules_(Organic_Chemistry)/Lipids/Properties_of_Lipids/Saponification_Value", "https://www.britannica.com/science/saponification-number"]'),
  ('schwarzschild_radius', '{"en-us": "Schwarzschild radius"}', 'black_holes', 9, '{"en-us": "The Schwarzschild radius is the radius of the event horizon of a non-rotating, uncharged black hole, arising as a scale parameter in the Schwarzschild solution to Einstein''s field equations. Any mass compressed below this radius undergoes gravitational collapse to a black hole, so it sets the size of a static black hole for a given mass."}', '["https://en.wikipedia.org/wiki/Schwarzschild_radius", "https://en.wikipedia.org/wiki/Schwarzschild_metric", "https://en.wikipedia.org/wiki/Event_horizon", "https://www.britannica.com/science/Schwarzschild-radius", "https://phys.libretexts.org/Bookshelves/Astronomy_and_Cosmology_TextMaps/Maps%3A_Astronomy_12e_(OpenStax)/24%3A_Active_Galaxies_Quasars_and_Supermassive_Black_Holes/24.04%3A_The_Search_for_Black_Holes"]'),
  ('secant_identity', '{"en-us": "Secant identity"}', 'trigonometric_identities', 5, '{"en-us": "The secant is the reciprocal of the cosine, defined wherever cosine is non-zero. It is one of the six basic trigonometric functions and arises naturally as the ratio of the hypotenuse to the adjacent side of a right triangle."}', '["https://en.wikipedia.org/wiki/Trigonometric_functions", "https://en.wikipedia.org/wiki/Secant", "https://mathworld.wolfram.com/Secant.html", "https://www.khanacademy.org/math/trigonometry/trig-function-graphs/sec-csc-graph/v/sec-and-csc", "https://www.britannica.com/science/secant-trigonometry"]'),
  ('secant_squared_identity', '{"en-us": "Secant squared identity"}', 'trigonometric_identities', 5, '{"en-us": "A Pythagorean trigonometric identity obtained by dividing the fundamental identity sin²θ + cos²θ = 1 by cos²θ. It expresses the secant function in terms of the tangent and is valid wherever cos θ is nonzero. It is frequently used in calculus for integrating secant-based expressions and in derivations of integration formulas."}', '["https://en.wikipedia.org/wiki/Pythagorean_trigonometric_identity", "https://en.wikipedia.org/wiki/List_of_trigonometric_identities", "https://en.wikibooks.org/wiki/Trigonometry/Trigonometric_Formula_Reference", "https://mathworld.wolfram.com/SecantSquared.html"]'),
  ('second_law_carnot_limit', '{"en-us": "Second law: maximum possible efficiency"}', 'second_law', 7, '{"en-us": "Carnot''s theorem places an upper bound on the efficiency of any heat engine operating between two thermal reservoirs, the maximum being attained by a reversible (Carnot) cycle. The result follows from the second law of thermodynamics and depends only on the absolute temperatures of the hot and cold reservoirs."}', '["https://en.wikipedia.org/wiki/Carnot_cycle", "https://en.wikipedia.org/wiki/Carnot%27s_theorem_(thermodynamics)", "https://en.wikipedia.org/wiki/Second_law_of_thermodynamics", "https://phys.libretexts.org/Bookshelves/Thermodynamics_%26_Statistical_Mechanics/Book%3A_Thermodynamics_(Tietjen)/11%3A_The_Second_Law_of_Thermodynamics/11.02%3A_Carnot_Efficiency"]'),
  ('second_law_clausius_statement', '{"en-us": "Clausius statement of the second law"}', 'second_law', 8, '{"en-us": "The Clausius statement says heat cannot spontaneously flow from a colder body to a hotter body; any such transfer requires external work and produces changes elsewhere in the system. It is one of the classic equivalent formulations of the second law of thermodynamics and is equivalent to the Kelvin-Planck statement."}', '["https://en.wikipedia.org/wiki/Second_law_of_thermodynamics", "https://en.wikipedia.org/wiki/Clausius_theorem", "https://en.wikipedia.org/wiki/Heat", "https://www.britannica.com/science/second-law-of-thermodynamics"]'),
  ('second_law_entropy_increase', '{"en-us": "Second law: entropy of isolated system"}', 'second_law', 7, '{"en-us": "For any spontaneous process in an isolated thermodynamic system, the total entropy never decreases and approaches a maximum at equilibrium. This inequality, sometimes called the entropy principle, is a concise statement of the second law and underlies irreversibility in macroscopic systems."}', '["https://en.wikipedia.org/wiki/Second_law_of_thermodynamics", "https://en.wikipedia.org/wiki/Entropy", "https://en.wikipedia.org/wiki/Clausius_theorem", "https://www.chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Thermodynamics/The_Four_Laws_of_Thermodynamics/Second_Law_of_Thermodynamics"]'),
  ('second_law_heat_flow_direction', '{"en-us": "Direction of heat flow (second law)"}', 'second_law', 5, '{"en-us": "When two bodies at different temperatures are placed in thermal contact, heat flows spontaneously from the hotter to the colder body, never the reverse, until thermal equilibrium is reached. This directional rule is the everyday observational basis for the second law of thermodynamics."}', '["https://en.wikipedia.org/wiki/Second_law_of_thermodynamics", "https://en.wikipedia.org/wiki/Thermal_conduction", "https://en.wikipedia.org/wiki/Heat", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/03%3A_The_Second_Law_of_Thermodynamics"]'),
  ('second_order_half_life', '{"en-us": "Second-order reaction half-life"}', 'chemical_kinetics', 8, '{"en-us": "For a second-order chemical reaction, the half-life (the time required for a reactant''s concentration to fall to half its initial value) is inversely proportional to both the initial concentration and the rate constant. Unlike first-order reactions, the half-life grows shorter as the reaction proceeds because the rate depends on concentration."}', '["https://en.wikipedia.org/wiki/Rate_equation", "https://en.wikipedia.org/wiki/Half-life", "https://en.wikipedia.org/wiki/Reaction_rate_constant", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Kinetics/Reaction_Rates/Second-Order_Reactions"]'),
  ('second_order_rate_law_integrated', '{"en-us": "Integrated rate law (second order)"}', 'chemical_kinetics', 7, '{"en-us": "For a reaction that is second order in a single reactant, the integrated rate law is obtained by integrating the rate law d[A]/dt = -k[A]². It gives a linear relation between the reciprocal of the reactant concentration and time, and is used to extract the second-order rate constant k from experimental concentration-versus-time data."}', '["https://en.wikipedia.org/wiki/Rate_equation#Second_order", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Kinetics/Reaction_Rates/Second-Order_Reactions", "https://www.khanacademy.org/science/chemistry/chemical-kinetics/reaction-rates/v/second-order-reaction-with-two-reactants", "https://www.chemguide.co.uk/physical/basicrates/secondorder.html", "https://www.masterorganicchemistry.com/2013/03/08/integrated-rate-laws/"]'),
  ('self_inductance_solenoid', '{"en-us": "Self-inductance of a solenoid"}', 'electromagnetic_induction', 8, '{"en-us": "The self-inductance of an air-core solenoid (long, tightly wound helical coil) depends only on its geometry and the number of turns. Fringe effects are neglected and the magnetic field inside the coil is treated as uniform, so the inductance scales with the square of the turn count and the cross-sectional area, and inversely with the length."}', '["https://en.wikipedia.org/wiki/Solenoid#Inductance", "https://en.wikipedia.org/wiki/Inductance#Inductance_of_a_solenoid", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/14%3A_Inductance/14.04%3A_Self-Inductance_and_Inductors", "https://www.khanacademy.org/science/physics/magnetic-forces-and-magnetic-fields/magnetic-flux-faradays-law/v/lenz-s-law-induction-in-a-solenoid", "https://www.britannica.com/technology/solenoid"]'),
  ('sequential_reaction_yield', '{"en-us": "Overall yield of sequential reactions"}', 'chemical_reactions', 6, '{"en-us": "For a synthetic sequence in which one step feeds the next, the overall percent yield is the product of the individual step yields (each expressed as a decimal fraction). Knowing this, chemists can predict how many starting equivalents a long multi-step synthesis will require to obtain a target amount of product."}', '["https://en.wikipedia.org/wiki/Consecutive_reactions", "https://chem.libretexts.org/Bookshelves/Organic_Chemistry/Supplemental_Modules_(Organic_Chemistry)/Reactions/Overview_of_Reactions/Reaction_Overview", "https://www.masterorganicchemistry.com/2017/09/20/multistep-synthesis-yield/", "https://www.chemguide.co.uk/organicprops/amines/synthesis/yield.html", "https://www.thoughtco.com/definition-of-percent-yield-605896"]'),
  ('series_capacitance', '{"en-us": "Capacitors in series (two)"}', 'circuits', 6, '{"en-us": "When capacitors are connected in series, each carries the same charge while the voltages across them add. The reciprocal of the equivalent capacitance equals the sum of the reciprocals of the individual capacitances, so the combined capacitance is always less than the smallest individual capacitance in the group."}', '["https://en.wikipedia.org/wiki/Series_and_parallel_circuits#Capacitors", "https://en.wikipedia.org/wiki/Capacitor#Capacitors_in_series", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/08%3A_Capacitance/8.03%3A_Capacitors_in_Series_and_in_Parallel", "https://www.khanacademy.org/science/physics/circuits-topic/circuits-with-capacitors/v/capacitors-in-series", "https://www.electronics-tutorials.ws/capacitor/cap_5.html", "https://www.britannica.com/technology/capacitor/Capacitors-in-series"]'),
  ('series_rc_circuit_voltage_capacitor', '{"en-us": "Voltage across capacitor in RC circuit (discharging)"}', 'circuits', 7, '{"en-us": "When a charged capacitor in a series RC network is allowed to discharge through the resistor (no source), the voltage across the capacitor decays exponentially with time. The decay rate is set by the time constant RC, which is the resistance times the capacitance."}', '["https://en.wikipedia.org/wiki/RC_circuit#Natural_response", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/11%3A_Alternating-Current_Circuits/11.06%3A_RC_Circuits", "https://www.khanacademy.org/science/physics/circuits-topic/circuits-with-capacitors/v/rc-circuits-intro", "https://www.electronics-tutorials.ws/rc/rc_1.html", "https://www.allaboutcircuits.com/textbook/direct-current/chpt-16/time-constants/"]'),
  ('series_resistance', '{"en-us": "Resistors in series"}', 'circuits', 4, '{"en-us": "When resistors are connected end-to-end in a series loop, the same current flows through each, and the total voltage drop across the combination is the sum of the individual drops. The equivalent resistance is therefore the sum of the individual resistances, and is always larger than any single resistance in the group."}', '["https://en.wikipedia.org/wiki/Series_and_parallel_circuits#Resistance", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/09%3A_Current_and_Resistance/9.04%3A_Resistors_in_Series_and_Parallel", "https://www.khanacademy.org/science/physics/circuits-topic/circuits-with-resistors/v/series-resistors", "https://www.electronics-tutorials.ws/resistor/res_3.html", "https://www.britannica.com/science/series-resistance"]'),
  ('series_resistance_three', '{"en-us": "Resistors in series (three)"}', 'circuits', 4, '{"en-us": "When three resistors are connected end-to-end in a single loop, the same current flows through each and the total voltage drop is the sum of the individual drops. The equivalent resistance is therefore the arithmetic sum of the three individual resistances and is always larger than any one of them."}', '["https://en.wikipedia.org/wiki/Series_and_parallel_circuits#Resistance", "https://www.khanacademy.org/science/physics/circuits-topic/circuits-with-resistors/v/series-resistors", "https://www.electronics-tutorials.ws/resistor/res_3.html", "https://www.britannica.com/science/series-resistance", "https://www.physicsclassroom.com/class/circuits/Lesson-4/Combination-Circuits"]'),
  ('series_resistors_n_equal', '{"en-us": "Equivalent resistance of n equal series resistors"}', 'circuits', 5, '{"en-us": "For n identical resistors of value R connected in series, the equivalent resistance is the count multiplied by the individual resistance. This simplification is a special case of the general series rule, useful for designing matched networks, voltage dividers, and identical current-limiting strings."}', '["https://en.wikipedia.org/wiki/Series_and_parallel_circuits#Resistance", "https://www.physicsclassroom.com/class/circuits/Lesson-4/Combination-Circuits", "https://www.electronics-tutorials.ws/resistor/res_3.html", "https://www.britannica.com/science/series-resistance", "https://www.allaboutcircuits.com/textbook/direct-current/chpt-5/component-failure-analysis/"]'),
  ('shm_max_acceleration', '{"en-us": "Maximum acceleration in SHM"}', 'harmonic_motion', 6, '{"en-us": "In simple harmonic motion, the restoring acceleration is proportional to the displacement from equilibrium, so its magnitude is largest when the displacement equals the amplitude. The peak acceleration scales with the square of the angular frequency, which is why high-frequency oscillators experience much larger peak forces than low-frequency ones of the same amplitude."}', '["https://en.wikipedia.org/wiki/Simple_harmonic_motion#Dynamics", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Oscillations/15.02%3A_Simple_Harmonic_Motion", "https://www.khanacademy.org/science/physics/mechanical-waves-and-sound/harmonic-motion/v/introduction-to-harmonic-motion", "https://www.britannica.com/science/simple-harmonic-motion", "https://hyperphysics.phy-astr.gsu.edu/hbase/shm.html"]'),
  ('shm_ode_second_order', '{"en-us": "Simple harmonic motion differential equation"}', 'differential_equations', 8, '{"en-us": "The second-order linear differential equation governing undamped simple harmonic motion. Its solutions are sinusoidal with angular frequency equal to the coefficient under the square root of the restoring-force-to-mass ratio, and it is the limiting case of the damped harmonic oscillator when the damping coefficient vanishes."}', '["https://en.wikipedia.org/wiki/Simple_harmonic_motion#Dynamics", "https://en.wikipedia.org/wiki/Harmonic_oscillator", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Oscillations/15.02%3A_Simple_Harmonic_Motion", "https://math.libretexts.org/Bookshelves/Differential_Equations/Elementary_Differential_Equations_(Arnold)/01%3A_Introduction/1.01%3A_Simple_Harmonic_Oscillator", "https://www.khanacademy.org/science/physics/mechanical-waves-and-sound/harmonic-motion/v/introduction-to-harmonic-motion", "https://hyperphysics.phy-astr.gsu.edu/hbase/shm.html"]'),
  ('shm_position', '{"en-us": "Position in simple harmonic motion"}', 'harmonic_motion', 6, '{"en-us": "The instantaneous position of an undamped simple harmonic oscillator, expressed as a cosine of the angular frequency times elapsed time. With the standard choice of zero phase, the oscillator starts at maximum displacement; an arbitrary initial phase can be absorbed into the time origin for any equivalent sinusoidal description."}', '["https://en.wikipedia.org/wiki/Simple_harmonic_motion#Dynamics", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Oscillations/15.02%3A_Simple_Harmonic_Motion", "https://www.khanacademy.org/science/physics/mechanical-waves-and-sound/harmonic-motion/v/introduction-to-harmonic-motion", "https://hyperphysics.phy-astr.gsu.edu/hbase/shm.html", "https://www.britannica.com/science/simple-harmonic-motion"]'),
  ('shm_velocity_position', '{"en-us": "Velocity as function of position in SHM"}', 'harmonic_motion', 7, '{"en-us": "Relates the speed of a simple harmonic oscillator to its current position, derived from energy conservation (kinetic plus potential equals the total mechanical energy set by the amplitude). The expression under the square root vanishes at the turning points where the speed is zero, and reaches its maximum at the equilibrium position where displacement vanishes."}', '["https://en.wikipedia.org/wiki/Simple_harmonic_motion#Dynamics", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Oscillations/15.02%3A_Simple_Harmonic_Motion", "https://www.khanacademy.org/science/physics/mechanical-waves-and-sound/harmonic-motion/v/introduction-to-harmonic-motion", "https://hyperphysics.phy-astr.gsu.edu/hbase/shm.html", "https://www.britannica.com/science/simple-harmonic-motion"]'),
  ('sho_ode_standard', '{"en-us": "Simple harmonic oscillator ODE (standard form)"}', 'differential_equations', 8, '{"en-us": "The standard undamped simple harmonic oscillator equation governs the motion of a mass attached to an ideal spring (and, in the small-angle limit, a pendulum). Its solutions are sinusoidal, with the natural angular frequency set by the ratio of spring stiffness to mass, and form the prototype for oscillations, waves, and many quantum-mechanical bound states."}', '["https://en.wikipedia.org/wiki/Simple_harmonic_motion", "https://en.wikipedia.org/wiki/Harmonic_oscillator", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Oscillations/15.01%3A_Simple_Harmonic_Motion", "https://www.khanacademy.org/science/physics/mechanical-waves-and-sound/harmonic-motion/v/introduction-to-harmonic-motion", "https://math.libretexts.org/Bookshelves/Differential_Equations/Book%3A_Differential_Equations_for_Engineers_(Lebl)/3%3A_Systems_of_ODEs/3.1%3A_Harmonic_Oscillators"]'),
  ('signal_to_noise_ratio', '{"en-us": "Signal-to-noise ratio"}', 'analytical_chemistry', 7, '{"en-us": "The signal-to-noise ratio compares the level of a desired signal to the level of background noise in a measurement or transmission channel. It is a key figure of merit in communications, imaging, spectroscopy, and audio engineering, and is often quoted in decibels; the Shannon–Hartley theorem sets the maximum reliable data rate over a channel as a function of bandwidth and SNR."}', '["https://en.wikipedia.org/wiki/Signal-to-noise_ratio", "https://www.brown.edu/research/labs/idles/projects-software/signal-to-noise-ratio", "https://www.analog.com/en/resources/technical-articles/signal-to-noise-ratio.html", "https://www.sciencedirect.com/topics/engineering/signal-to-noise-ratio", "https://www.thinksrs.com/downloads/papers/AN301.pdf"]'),
  ('simple_interest', '{"en-us": "Simple interest future value"}', 'arithmetic', 4, '{"en-us": "Simple interest computes interest only on the original principal, so the amount grows linearly with time. It is used in short-term loans, certain bonds, and as the conceptual basis before introducing compound interest."}', '["https://en.wikipedia.org/wiki/Interest#Simple_interest", "https://www.investopedia.com/terms/s/simple_interest.asp", "https://www.khanacademy.org/math/algebra/x2f8bb11595b61c86:interest-and-exponential-growth/x2f8bb11595b61c86:interest/v/introduction-to-simple-interest", "https://math.libretexts.org/Bookshelves/Applied_Mathematics/Book%3A_College_Technology_Board_for_Certified_Accountants/05%3A_Business_Mathematics/5.02%3A_Simple_Interest_and_Aggregation", "https://corporatefinanceinstitute.com/resources/wealth-management/simple-interest/"]'),
  ('sine_definition', '{"en-us": "Sine definition"}', 'right_triangles', 3, '{"en-us": "In a right triangle, the sine of an acute angle is the ratio of the length of the side opposite that angle to the length of the hypotenuse. This right-triangle definition extends via the unit circle to angles of any measure and underlies the periodic trigonometric functions used throughout geometry, physics, and signal analysis."}', '["https://en.wikipedia.org/wiki/Sine", "https://en.wikipedia.org/wiki/Trigonometric_functions#Right-angled_triangle_definitions", "https://math.libretexts.org/Bookshelves/Trigonometry/Book%3A_Trigonometry_(Larson)/01%3A_Trigonometric_Angles_and_Real_Numbers/1.01%3A_Radian_and_Degree_Measure", "https://www.khanacademy.org/math/geometry/hs-geo-trig/hs-geo-trig-ratios-similarity/v/basic-trigonometry", "https://www.mathsisfun.com/definitions/sine.html"]'),
  ('single_slit_diffraction_minima', '{"en-us": "Single-slit diffraction minima"}', 'diffraction', 8, '{"en-us": "When a wave passes through a single narrow slit, the far-field intensity pattern has destructive-interference minima where the path-length difference across the slit equals an integer number of wavelengths. The condition sets the angles of the dark fringes observed on a distant screen and is fundamental to understanding resolution limits of optical instruments."}', '["https://en.wikipedia.org/wiki/Diffraction", "https://en.wikipedia.org/wiki/Diffraction_from_slits", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/04%3A_Diffraction/4.02%3A_Single-Slit_Diffraction", "https://www.brown.edu/research/labs/idles/resources-education/single-slit-diffraction", "https://opentextbc.ca/physicstestbook2/chapter/single-slit-diffraction/"]'),
  ('slope_intercept_form', '{"en-us": "Slope-intercept form"}', 'equations', 3, '{"en-us": "The slope-intercept form expresses a non-vertical straight line in the Cartesian plane as y equal to its slope times x plus its y-intercept. It is the most common way to write the equation of a line because it makes the slope and the point where the line crosses the y-axis immediately readable."}', '["https://en.wikipedia.org/wiki/Linear_equation#Slope%E2%80%93intercept_form_or_Gradient-intercept_form", "https://www.khanacademy.org/math/algebra/x2f8bb11595b61c86:linear-equations-graphs/x2f8bb11595b61c86:slope/v/slope-intercept-form", "https://math.libretexts.org/Bookshelves/Algebra/Book%3A_Intermediate_Algebra_(OpenStax)/03%3A_Graphs_and_Functions/3.2%3A_Linear_Functions", "https://www.cuemath.com/geometry/slope-intercept-form/", "https://www.mathsisfun.com/equation_of_line.html"]'),
  ('slope_line', '{"en-us": "Slope of a line"}', 'coordinate_geometry', 3, '{"en-us": "The slope of a line in the Cartesian plane is the ratio of its vertical change to its horizontal change between any two distinct points on the line. It is commonly denoted m and equals the tangent of the angle the line makes with the positive x-axis; horizontal lines have slope 0 and vertical lines have undefined slope."}', '["https://en.wikipedia.org/wiki/Slope", "https://mathworld.wolfram.com/Slope.html", "https://en.wikipedia.org/wiki/Linear_equation#Point%E2%80%93slope_form_or_Point-gradient_form", "https://math.libretexts.org/Bookshelves/Precalculus/Precalculus_1e_(OpenStax)/02%3A_Linear_Functions", "https://en.wikipedia.org/wiki/Slope_(mathematics)"]'),
  ('slope_point_form', '{"en-us": "Point-slope form of a line"}', 'coordinate_geometry', 4, '{"en-us": "The point-slope form gives the equation of a non-vertical line using its slope and the coordinates of any one point on the line. It is widely used in analytic geometry and is closely related to the slope-intercept form."}', '["https://en.wikipedia.org/wiki/Linear_equation#Point%E2%80%93slope_form_or_Point-gradient_form", "https://en.wikipedia.org/wiki/Slope", "https://en.wikipedia.org/wiki/Point%E2%80%93slope_form", "https://math.libretexts.org/Bookshelves/Precalculus/Precalculus_1e_(OpenStax)/02%3A_Linear_Functions/2.01%3A_Linear_Functions", "https://mathworld.wolfram.com/Slope.html"]'),
  ('snells_law', '{"en-us": "Snell''s law"}', 'refraction', 5, '{"en-us": "Snell''s law, also called the Snell–Descartes law, describes the relationship between the angles of incidence and refraction when a wave crosses a boundary between two isotropic media. It underlies ray tracing in optics and is also satisfied by sound and other waves."}', '["https://en.wikipedia.org/wiki/Snell%27s_law", "https://en.wikipedia.org/wiki/Refractive_index", "https://en.wikipedia.org/wiki/Total_internal_reflection", "https://en.wikipedia.org/wiki/Refraction", "https://en.wikipedia.org/wiki/Fermat%27s_principle"]'),
  ('soh_cah_toa_cosine', '{"en-us": "Right triangle: cosine ratio (CAH)"}', 'right_triangles', 3, '{"en-us": "The cosine of an acute angle in a right triangle is the ratio of the length of the side adjacent to the angle to the length of the hypotenuse. This is one of the SOH CAH TOA right-triangle definitions, also known as the CAH rule."}', '["https://en.wikipedia.org/wiki/Trigonometric_functions#Right-angled_triangle_definitions", "https://en.wikipedia.org/wiki/Trigonometry", "https://en.wikipedia.org/wiki/Cosine", "https://math.libretexts.org/Bookshelves/Precalculus/Precalculus_1e_(OpenStax)/05%3A_Trigonometric_Functions/5.04%3A_Right_Triangle_Trigonometry", "https://en.wikipedia.org/wiki/Sine_and_cosine"]'),
  ('soh_cah_toa_sine', '{"en-us": "Right triangle: sine ratio (SOH)"}', 'right_triangles', 3, '{"en-us": "The sine of an acute angle in a right triangle is the ratio of the length of the side opposite the angle to the length of the hypotenuse. This is one of the SOH CAH TOA right-triangle definitions, also known as the SOH rule."}', '["https://en.wikipedia.org/wiki/Trigonometric_functions#Right-angled_triangle_definitions", "https://en.wikipedia.org/wiki/Trigonometry", "https://en.wikipedia.org/wiki/Sine", "https://math.libretexts.org/Bookshelves/Precalculus/Precalculus_1e_(OpenStax)/05%3A_Trigonometric_Functions/5.04%3A_Right_Triangle_Trigonometry", "https://en.wikipedia.org/wiki/Sine_and_cosine"]'),
  ('soh_cah_toa_tangent', '{"en-us": "Right triangle: tangent ratio (TOA)"}', 'right_triangles', 3, '{"en-us": "The tangent of an acute angle in a right triangle is the ratio of the length of the side opposite the angle to the length of the side adjacent to it. This is one of the SOH CAH TOA right-triangle definitions, also known as the TOA rule."}', '["https://en.wikipedia.org/wiki/Trigonometric_functions#Right-angled_triangle_definitions", "https://en.wikipedia.org/wiki/Trigonometry", "https://en.wikipedia.org/wiki/Trigonometric_functions#Tangent", "https://math.libretexts.org/Bookshelves/Precalculus/Precalculus_1e_(OpenStax)/05%3A_Trigonometric_Functions/5.04%3A_Right_Triangle_Trigonometry", "https://en.wikipedia.org/wiki/Sine_and_cosine"]'),
  ('solenoid_inductance', '{"en-us": "Self-inductance of a solenoid"}', 'electromagnetic_induction', 8, '{"en-us": "The self-inductance of an air-core solenoid depends only on its geometry (number of turns, cross-sectional area, and length) and is independent of the current, assuming the magnetic field is uniform and end effects are negligible."}', '["https://en.wikipedia.org/wiki/Solenoid", "https://en.wikipedia.org/wiki/Inductance", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/14%3A_Inductance/14.04%3A_Self-Inductance_and_Inductors", "https://www.britannica.com/technology/solenoid", "https://www.electronics-tutorials.ws/inductor/solenoid.html", "http://hyperphysics.phy-astr.gsu.edu/hbase/magnetic/solenoid.html"]'),
  ('solid_angle_formula', '{"en-us": "Solid angle"}', 'geometry', 7, '{"en-us": "The solid angle subtended at a point by a surface patch equals the projected area of that patch onto a unit sphere centered at the point, with the SI unit of steradian. A small object near the apex can subtend the same solid angle as a much larger, more distant object."}', '["https://en.wikipedia.org/wiki/Solid_angle", "https://en.wikipedia.org/wiki/Steradian", "https://mathworld.wolfram.com/SolidAngle.html", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/01%3A_Units_and_Measurement/1.7%3A_Dimensional_Analysis", "https://www.britannica.com/science/solid-angle"]'),
  ('solubility_product_a2b', '{"en-us": "Solubility product for A₂B-type salt"}', 'solutions', 7, '{"en-us": "The solubility product K_sp expresses the equilibrium between a sparingly soluble ionic salt and its saturated solution, written as the product of the dissolved ion concentrations each raised to the power of its stoichiometric coefficient in the dissociation reaction. For a salt of stoichiometry A₂B that dissociates into 2 A ions and 1 B ion, K_sp governs solubility and the common-ion effect."}', '["https://en.wikipedia.org/wiki/Solubility_equilibrium", "https://en.wikipedia.org/wiki/Solubility_product", "https://chem.libretexts.org/Bookshelves/General_Chemistry/General_Chemistry_Supplement_(Eames)/Equilibria/Additional_Exercises/Solubility_Product", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Equilibria/Solubilty/Solubility_Product", "https://www.britannica.com/science/solubility-product", "https://www.khanacademy.org/science/chemistry/chemical-equilibrium-topic/solubility-equilibrium-topic/v/solubility-product-constant"]'),
  ('solubility_product_ab', '{"en-us": "Solubility product for AB-type salt"}', 'solutions', 7, '{"en-us": "The solubility product K_sp for a 1:1 salt like AgCl equals the product of the molar concentrations of its cation and anion in a saturated solution, with each raised to the first power. It is a temperature-dependent equilibrium constant that quantifies solubility and the common-ion effect."}', '["https://en.wikipedia.org/wiki/Solubility_equilibrium", "https://en.wikipedia.org/wiki/Solubility_product", "https://chem.libretexts.org/Bookshelves/General_Chemistry/General_Chemistry_Supplement_(Eames)/Equilibria/Additional_Exercises/Solubility_Product", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Equilibria/Solubilty/Solubility_Product", "https://www.khanacademy.org/science/chemistry/chemical-equilibrium-topic/solubility-equilibrium-topic/v/solubility-product-constant", "https://www.britannica.com/science/solubility-product"]'),
  ('solution_concentration_mass_percent', '{"en-us": "Mass percent concentration"}', 'solution_stoichiometry', 4, '{"en-us": "Mass percent (% m/m, also called weight percent or % w/w) expresses solute concentration as the mass of solute per 100 mass units of total solution. It is a common and convenient unit in chemistry, pharmacy, and industry because masses are easily measured on a balance."}', '["https://en.wikipedia.org/wiki/Mass_fraction_(chemistry)", "https://en.wikipedia.org/wiki/Mass_concentration_(chemistry)", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Analytical_Chemistry_2.1_(Harvey)/05%3A_Standardizing_Analytical_Methods/5.2%3A_Concentrations_of_Solutions", "https://www.khanacademy.org/science/chemistry/states-of-matter-and-intermolecular-forces/mixtures-and-solutions/v/mass-percent", "https://www.britannica.com/science/mass-fraction"]'),
  ('solution_conductivity_from_concentration', '{"en-us": "Solution conductivity from concentration and molar conductivity"}', 'solution_stoichiometry', 8, '{"en-us": "The specific (electrolytic) conductivity of a solution is the product of the electrolyte''s molar conductivity and its molar concentration. This relationship holds precisely at infinite dilution, where molar conductivity approaches its limiting value, and approximately for dilute strong-electrolyte solutions."}', '["https://en.wikipedia.org/wiki/Conductivity_(electrolytic)", "https://en.wikipedia.org/wiki/Molar_conductivity", "https://en.wikipedia.org/wiki/Kohlrausch%27s_law", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Electrochemistry/Electrolytic_Conductivity", "https://www.britannica.com/science/electrolytic-conductance", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Analytical_Chemistry_2.1_(Harvey)/06%3A_Equilibrium_Constants/6.06%3A_Conductivity"]'),
  ('solution_dilution_factor', '{"en-us": "Dilution factor"}', 'solution_stoichiometry', 4, '{"en-us": "The dilution factor expresses how much a solution has been diluted, defined as the ratio of the final (diluted) solution volume to the volume of the original concentrated stock solution. Together with the dilution equation c1V1 = c2V2, it is the basis for serial-dilution protocols used in microbiology, pharmacology, and analytical chemistry."}', '["https://en.wikipedia.org/wiki/Dilution_(equation)", "https://en.wikipedia.org/wiki/Serial_dilution", "https://en.wikipedia.org/wiki/Concentration", "https://en.wikipedia.org/wiki/Dilution_ratio"]'),
  ('solution_normality_formula', '{"en-us": "Normality from molarity and n-factor"}', 'solution_stoichiometry', 7, '{"en-us": "Normality is the equivalent concentration of a solution, defined as the number of equivalents of solute per liter of solution. It is obtained from the molar concentration by multiplying by an equivalence (n-)factor that depends on the reaction of interest: number of H+ or OH- in acid-base chemistry, electrons transferred in redox reactions, or ions exchanged in precipitation."}', '["https://en.wikipedia.org/wiki/Equivalent_concentration", "https://en.wikipedia.org/wiki/Molar_concentration", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Analytical_Chemistry_2.1_(Harvey)/16:_Appendix/16.01:_Normality", "https://en.wikipedia.org/wiki/Concentration"]'),
  ('solutions_henrys_law_constant', '{"en-us": "Henry''s law constant definition"}', 'solutions', 7, '{"en-us": "Henry''s law states that at constant temperature the amount of a gas dissolved in a liquid is proportional to its equilibrium partial pressure above the solution. The proportionality factor, called Henry''s law constant, is tabulated for many gas-solvent pairs and is widely used in chemical engineering, environmental chemistry, and decompression physiology."}', '["https://en.wikipedia.org/wiki/Henry%27s_law", "https://en.wikipedia.org/wiki/Partial_pressure", "https://en.wikipedia.org/wiki/Solubility", "https://en.wikipedia.org/wiki/Concentration"]'),
  ('sound_intensity_level', '{"en-us": "Sound intensity level in decibels"}', 'mechanical_waves', 6, '{"en-us": "Sound intensity level is a logarithmic measure of a sound''s acoustic intensity referenced to a standard threshold of audibility, expressed in decibels. Because the human ear responds to intensity on a logarithmic scale, this quantity is used to quantify loudness and is the basis of most noise-exposure standards."}', '["https://en.wikipedia.org/wiki/Sound_intensity", "https://en.wikipedia.org/wiki/Decibel", "https://en.wikipedia.org/wiki/Level_(logarithmic_quantity)", "https://en.wikipedia.org/wiki/Sound_pressure"]'),
  ('sound_pressure_amplitude', '{"en-us": "Sound pressure amplitude from intensity"}', 'mechanical_waves', 8, '{"en-us": "For a plane sinusoidal sound wave in a fluid, the sound pressure amplitude is related to the acoustic intensity, the medium''s density, and the speed of sound. This relation follows from the definition of intensity as the product of pressure and particle velocity, combined with the plane-wave relation between those two quantities."}', '["https://en.wikipedia.org/wiki/Sound_pressure", "https://en.wikipedia.org/wiki/Sound_intensity", "https://en.wikipedia.org/wiki/Acoustic_impedance", "https://en.wikipedia.org/wiki/Particle_velocity"]'),
  ('specific_activity', '{"en-us": "Specific activity"}', 'nuclear_physics', 8, '{"en-us": "Specific activity is the activity of a radionuclide per unit mass, a fundamental property that quantifies how ''hot'' a sample of a given isotope is. It depends only on the decay constant of the nuclide and (through the Avogadro constant and molar mass) on the number of radioactive atoms per gram, and is decisive in selecting radionuclides for radiopharmaceuticals and tracer studies."}', '["https://en.wikipedia.org/wiki/Specific_activity", "https://en.wikipedia.org/wiki/Radioactive_decay", "https://en.wikipedia.org/wiki/Avogadro_constant", "https://en.wikipedia.org/wiki/Becquerel"]'),
  ('specific_gravity_pressure_conversion', '{"en-us": "Pressure conversion using specific gravity"}', 'pressure', 5, '{"en-us": "Hydrostatic pressure at the bottom of a fluid column equals the fluid''s specific gravity times the density of water times the gravitational acceleration times the column height. It is used to convert tabulated specific-gravity values into a working pressure."}', '["https://en.wikipedia.org/wiki/Relative_density", "https://en.wikipedia.org/wiki/Hydrostatic_pressure", "https://en.wikipedia.org/wiki/Hydrostatics", "https://en.wikipedia.org/wiki/Specific_weight", "https://www.engineersedge.com/fluid_flow/specific_gravity.htm", "https://www.thoughtco.com/specific-gravity-formula-609309"]'),
  ('specific_heat_capacity_definition', '{"en-us": "Specific heat capacity definition"}', 'heat', 5, '{"en-us": "Specific heat capacity is an intensive property of a substance equal to the heat energy required to raise the temperature of a unit mass by one kelvin. It is commonly tabulated for solids, liquids, and gases, with separate values typically reported for constant-pressure and constant-volume conditions."}', '["https://en.wikipedia.org/wiki/Specific_heat_capacity", "https://en.wikipedia.org/wiki/Heat_capacity", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/06%3A_Thermochemistry/6.05%3A_Specific_Heat_Capacity_and_Calorimetry", "https://www.britannica.com/science/specific-heat", "https://physics.info/heat-capacity/", "https://www.chemteam.info/Thermochem/Heat-Capacity.html"]'),
  ('specific_impulse_definition', '{"en-us": "Specific impulse"}', 'newtons_laws', 8, '{"en-us": "Specific impulse measures how efficiently a reaction engine generates thrust from propellant. It is the thrust divided by the propellant mass flow rate and is also expressed in seconds by dividing further by standard gravity, so it is the time a unit mass of propellant can produce a unit of thrust."}', '["https://en.wikipedia.org/wiki/Specific_impulse", "https://en.wikipedia.org/wiki/Thrust", "https://en.wikipedia.org/wiki/Mass_flow_rate", "https://en.wikipedia.org/wiki/Tsiolkovsky_rocket_equation", "https://www.grc.nasa.gov/www/k-12/rocket/specimp.html", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Book%3A_Classical_Mechanics_(Tatum)/19%3A_Rocket_Motion/19.02%3A_Specific_Impulse"]'),
  ('specific_rotation_formula', '{"en-us": "Specific rotation in polarimetry"}', 'analytical_chemistry', 8, '{"en-us": "Specific rotation is an intensive property of a chiral compound that quantifies how much plane-polarized light is rotated per unit path length and per unit concentration. It is reported in units of deg·mL·g⁻¹·dm⁻¹ and depends on the wavelength, temperature, and solvent of the measurement."}', '["https://en.wikipedia.org/wiki/Specific_rotation", "https://en.wikipedia.org/wiki/Optical_rotation", "https://en.wikipedia.org/wiki/Polarimeter", "https://en.wikipedia.org/wiki/Enantiomeric_excess", "https://www.chem.libretexts.org/Bookshelves/Organic_Chemistry/Organic_Chemistry_Lab_Techniques_(Nichols)/06%3A_Infrared_Spectroscopy/6.03%3A_Physical_Constants_and_Reference_Tables", "https://goldbook.iupac.org/terms/view/ST07576"]'),
  ('specific_volume_formula', '{"en-us": "Specific volume"}', 'pressure', 6, '{"en-us": "Specific volume is the volume occupied by a unit mass of a substance and is the reciprocal of density. It is widely used in thermodynamics, particularly for gases whose specific volumes are highly sensitive to temperature and pressure changes."}', '["https://en.wikipedia.org/wiki/Specific_volume", "https://en.wikipedia.org/wiki/Density", "https://en.wikipedia.org/wiki/Molar_volume", "https://www.engineeringtoolbox.com/specific-volume-d_851.html", "https://www.britannica.com/science/specific-volume", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Properties_of_Liquids/Specific_Volume"]'),
  ('speed_of_light_from_permittivity', '{"en-us": "Speed of light from permittivity and permeability"}', 'electromagnetic_waves', 8, '{"en-us": "The speed of light in vacuum can be derived from the electromagnetic constants through Maxwell''s equations. This relationship, exact in SI units, was historically used to compute c before the metre was redefined in terms of the speed of light in 1983."}', '["https://en.wikipedia.org/wiki/Speed_of_light", "https://en.wikipedia.org/wiki/Vacuum_permittivity", "https://en.wikipedia.org/wiki/Vacuum_permeability", "https://en.wikipedia.org/wiki/Maxwell%27s_equations", "https://physics.info/speed-light/", "https://www.britannica.com/science/speed-of-light"]'),
  ('speed_of_sound_ideal_gas', '{"en-us": "Speed of sound in an ideal gas"}', 'mechanical_waves', 8, '{"en-us": "The Newton–Laplace relation for an ideal gas expresses the speed of sound in terms of the adiabatic index (ratio of specific heats), the gas constant, the absolute temperature, and the molar mass. It assumes the medium behaves as an ideal gas undergoing adiabatic compression, so it is accurate at low pressures and for small-amplitude perturbations."}', '["https://en.wikipedia.org/wiki/Speed_of_sound#Speed_of_sound_in_ideal_gases_and_air", "https://en.wikipedia.org/wiki/Newton%E2%80%93Laplace_equation", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/17%3A_Sound/17.02%3A_Speed_of_Sound", "https://www.khanacademy.org/science/physics/mechanical-waves-and-sound/sound-topic/v/speed-of-sound", "https://courses.lumenlearning.com/suny-osuniversityphysics/chapter/17-2-speed-of-sound/"]'),
  ('spherical_cap_volume', '{"en-us": "Volume of a spherical cap"}', 'plane_geometry', 7, '{"en-us": "A spherical cap is the portion of a sphere cut off by a single plane. Its volume depends on the height of the cap and the radius of the parent sphere and reduces to half the sphere''s volume when the cap height equals the sphere''s radius."}', '["https://en.wikipedia.org/wiki/Spherical_cap#Volume_and_surface_area", "https://mathworld.wolfram.com/SphericalCap.html", "https://en.wikipedia.org/wiki/Spherical_segment", "https://www.cuemath.com/geometry/volume-of-spherical-cap/", "https://byjus.com/maths/spherical-cap/"]'),
  ('spherical_segment_volume', '{"en-us": "Volume of a spherical segment"}', 'plane_geometry', 8, '{"en-us": "A spherical segment is the solid region of a sphere lying between two parallel cutting planes. Its volume depends on the distance between the planes and the radii of the two circular cross sections they produce."}', '["https://en.wikipedia.org/wiki/Spherical_segment", "https://mathworld.wolfram.com/SphericalSegment.html", "https://en.wikipedia.org/wiki/Spherical_cap", "https://www.ck12.org/geometry/spherical-segment/", "https://byjus.com/maths/spherical-segment/"]'),
  ('spherical_zone_area', '{"en-us": "Area of a spherical zone"}', 'plane_geometry', 7, '{"en-us": "A spherical zone (or spherical frustum) is the curved surface of a sphere bounded by two parallel planes. Its lateral area depends only on the sphere''s radius and the distance between the two planes, and equals the area of a cylinder of the same radius and height."}', '["https://en.wikipedia.org/wiki/Spherical_segment", "https://en.wikipedia.org/wiki/Spherical_cap", "https://mathworld.wolfram.com/SphericalZone.html", "https://www.ck12.org/geometry/spherical-zone/", "https://byjus.com/maths/spherical-zone/"]'),
  ('spin_only_magnetic_moment', '{"en-us": "Spin-only magnetic moment"}', 'inorganic_chemistry', 8, '{"en-us": "The spin-only formula estimates the magnetic moment of a transition-metal complex (in Bohr magnetons) by neglecting the orbital contribution and considering only the spin angular momentum of unpaired electrons. It is a good first approximation for high-spin complexes of first-row transition metals."}', '["https://en.wikipedia.org/wiki/Magnetic_moment#Atoms,_molecules,_and_elementary_particles", "https://en.wikipedia.org/wiki/Bohr_magneton", "https://en.wikipedia.org/wiki/Spin_(physics)", "https://chem.libretexts.org/Bookshelves/Inorganic_Chemistry/Inorganic_Chemistry_(LibreTexts)/10%3A_Coordination_Chemistry_-_Bonding/10.05%3A_Crystal_Field_Theory", "https://byjus.com/chemistry/magnetic-moment/"]'),
  ('spring_constant_hookes_law', '{"en-us": "Spring constant from Hooke''s law"}', 'springs', 5, '{"en-us": "Hooke''s law states that the restoring force exerted by an ideal spring is proportional to its displacement from equilibrium. The spring constant characterizes the stiffness of the spring and equals the ratio of the applied force to the resulting extension."}', '["https://en.wikipedia.org/wiki/Hooke%27s_law", "https://en.wikipedia.org/wiki/Spring_constant", "https://www.khanacademy.org/science/physics/work-and-energy/hookes-law/v/hookes-law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Oscillations/15.02%3A_Simple_Harmonic_Motion", "https://courses.lumenlearning.com/suny-osuniversityphysics/chapter/15-1-simple-harmonic-motion/"]'),
  ('spring_energy_density', '{"en-us": "Elastic energy density"}', 'springs', 8, '{"en-us": "Elastic energy density is the elastic potential energy stored per unit volume of a deformed Hookean material, equal to half the product of stress and strain. It is a local, intensive quantity used in continuum mechanics and is independent of the geometry of the particular spring."}', '["https://en.wikipedia.org/wiki/Elastic_energy", "https://en.wikipedia.org/wiki/Hooke%27s_law", "https://en.wikipedia.org/wiki/Linear_elasticity", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/12%3A_Static_Equilibrium_and_Elasticity/12.06%3A_Elasticity_and_Plasticity"]'),
  ('spring_energy_from_force_formula', '{"en-us": "Elastic potential energy from force"}', 'springs', 5, '{"en-us": "For a Hookean spring the restoring force grows linearly with extension, so the stored elastic energy equals the average force (half the peak) times the displacement. It is the area under the force–displacement line from the equilibrium position to a given extension."}', '["https://en.wikipedia.org/wiki/Elastic_energy", "https://en.wikipedia.org/wiki/Hooke%27s_law", "https://en.wikipedia.org/wiki/Work_(physics)", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Oscillations/15.03%3A_Energy_in_Simple_Harmonic_Motion"]'),
  ('spring_force_displacement', '{"en-us": "Spring force and displacement"}', 'springs', 4, '{"en-us": "Hooke''s law states that the restoring force of an ideal linear spring is proportional to its displacement from equilibrium and points opposite to that displacement. The law is a first-order approximation valid for small deformations within the elastic limit."}', '["https://en.wikipedia.org/wiki/Hooke%27s_law", "https://en.wikipedia.org/wiki/Spring_(device)", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Oscillations/15.02%3A_Simple_Harmonic_Motion", "https://www.khanacademy.org/science/physics/work-and-energy/hookes-law/a/what-is-hookes-law"]'),
  ('spring_period', '{"en-us": "Period of a mass-spring system"}', 'harmonic_motion', 6, '{"en-us": "For an undamped mass on an ideal linear spring, the period of small oscillations depends only on the mass and the spring constant, not on the amplitude. The motion is isochronous and is the prototypical example of simple harmonic motion."}', '["https://en.wikipedia.org/wiki/Simple_harmonic_motion", "https://en.wikipedia.org/wiki/Spring_(device)", "https://en.wikipedia.org/wiki/Hooke%27s_law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Oscillations/15.02%3A_Simple_Harmonic_Motion", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Oscillations/15.05%3A_Pendulums", "https://www.khanacademy.org/science/physics/mechanical-waves-and-sound/harmonic-motion/v/period-of-a-mass-on-a-spring-ap-physics-1"]'),
  ('spring_work_displacement_squared', '{"en-us": "Work done by a spring"}', 'springs', 5, '{"en-us": "The work done by an ideal spring as it moves between two displacements equals the change in its elastic potential energy. It is computed as the integral of the Hookean restoring force over the displacement, and it is path-independent for a conservative linear spring."}', '["https://en.wikipedia.org/wiki/Elastic_energy", "https://en.wikipedia.org/wiki/Work_(physics)", "https://en.wikipedia.org/wiki/Hooke%27s_law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Oscillations/15.03%3A_Energy_in_Simple_Harmonic_Motion"]'),
  ('springs_in_parallel', '{"en-us": "Springs in parallel"}', 'springs', 5, '{"en-us": "When two or more linear springs are connected side-by-side so each experiences the same displacement, their restoring forces add and the effective spring constant is the sum of the individual constants. This mirrors the rule for capacitances in parallel and the rule for resistances in series."}', '["https://en.wikipedia.org/wiki/Series_and_parallel_springs", "https://en.wikipedia.org/wiki/Spring_(device)", "https://en.wikipedia.org/wiki/Capacitor-spring_analogy", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/15%3A_Oscillations/15.02%3A_Simple_Harmonic_Motion", "https://www.khanacademy.org/science/physics/work-and-energy/hookes-law/a/what-is-hookes-law"]'),
  ('springs_in_series', '{"en-us": "Springs in series"}', 'springs', 6, '{"en-us": "When springs are connected end-to-end (in series) so that they share the same applied force, their compliances add. The equivalent spring constant is found by summing the reciprocals of the individual spring constants, analogous to resistors in parallel."}', '["https://en.wikipedia.org/wiki/Spring_(device)", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/16%3A_Oscillations/16.02%3A_Period_and_Frequency_in_Oscillations", "https://www.khanacademy.org/science/physics/work-and-energy/hookes-law/a/what-is-hookes-law", "https://www.britannica.com/science/elasticity-of-spring", "https://byjus.com/physics/spring-constant/"]'),
  ('standard_addition_calibration', '{"en-us": "Standard addition calibration"}', 'analytical_chemistry', 9, '{"en-us": "The standard addition (known addition) method determines an unknown analyte concentration by spiking the sample with a known quantity of the analyte. For a single-point addition, the unknown concentration is recovered from the ratio of the unspiked signal, the spiked signal, and the concentration of the standard added. The technique minimizes matrix-effect bias by ensuring the calibration standards experience the same matrix as the unknown."}', '["https://en.wikipedia.org/wiki/Standard_addition", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Analytical_Chemistry_2.1_(Harvey)/05%3A_Standardizing_Analytical_Methods/5.04%3A_Standard_Addition_Method", "https://www.khanacademy.org/science/chemistry/chem-analysis-topic", "https://byjus.com/chemistry/standard-addition-method/", "https://pubs.acs.org/doi/abs/10.1021/ed057p703"]'),
  ('standard_cell_nernst', '{"en-us": "Standard cell potential from equilibrium"}', 'electrochemistry', 8, '{"en-us": "The standard cell potential is connected to the equilibrium constant of the underlying redox reaction through the Gibbs free energy. Because the cell can do electrical work only when the reaction is spontaneous, this relation lets one determine tabulated E° values from thermodynamic equilibrium data (and vice versa) at any reference temperature, normally 298 K."}', '["https://en.wikipedia.org/wiki/Standard_electrode_potential", "https://en.wikipedia.org/wiki/Nernst_equation", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/20%3A_Electrochemistry/20.4%3A_Relating_E%C2%B0_to_Equilibrium_Constants", "https://www.khanacademy.org/science/chemistry/oxidation-reduction", "https://byjus.com/chemistry/nernst-equation/", "https://www.britannica.com/science/standard-electrode-potential"]'),
  ('standard_deviation', '{"en-us": "Standard deviation"}', 'statistics', 5, '{"en-us": "The standard deviation quantifies the average spread of a set of values around their mean and equals the square root of the variance. It is widely used in descriptive statistics, hypothesis testing, and quality control because, unlike the variance, it is expressed in the same units as the underlying data."}', '["https://en.wikipedia.org/wiki/Standard_deviation", "https://en.wikipedia.org/wiki/Variance", "https://www.khanacademy.org/math/statistics-probability/summarizing-quantitative-data/variance-standard-deviation-population", "https://math.libretexts.org/Bookshelves/Statistics/Introductory_Statistics/02%3A_Descriptive_Statistics/2.05%3A_Measures_of_Variability", "https://www.britannica.com/topic/standard-deviation"]'),
  ('standard_enthalpy_reaction', '{"en-us": "Standard enthalpy of reaction"}', 'thermochemistry', 7, '{"en-us": "The standard enthalpy of reaction is the enthalpy change when a reaction proceeds under standard-state conditions, with all reactants and products in their reference states. It is calculated from tabulated standard enthalpies of formation as the difference between the sum over products and the sum over reactants (each weighted by stoichiometric coefficients), in line with Hess''s law."}', '["https://en.wikipedia.org/wiki/Standard_enthalpy_of_reaction", "https://en.wikipedia.org/wiki/Standard_enthalpy_of_formation", "https://en.wikipedia.org/wiki/Hess%27s_law", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/06%3A_Thermochemistry/6.06%3A_Hess%27s_Law", "https://www.khanacademy.org/science/chemistry/thermodynamics-chemistry", "https://www.britannica.com/science/standard-enthalpy-of-reaction"]'),
  ('standard_entropy_of_reaction', '{"en-us": "Standard entropy of reaction"}', 'entropy', 7, '{"en-us": "The standard entropy of reaction is the entropy change when a reaction proceeds under standard-state conditions. It is computed by taking the sum of the standard molar entropies of the products and subtracting the sum of those of the reactants (each term weighted by its stoichiometric coefficient), analogous to the calculation for the standard enthalpy of reaction."}', '["https://en.wikipedia.org/wiki/Standard_molar_entropy", "https://en.wikipedia.org/wiki/Entropy", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/19%3A_Spontaneous_Change_-_Entropy_and_Gibbs_Energy/19.04%3A_Entropy_Changes_in_Chemical_Reactions", "https://www.khanacademy.org/science/chemistry/thermodynamics-chemistry", "https://www.britannica.com/science/standard-entropy"]'),
  ('standard_entropy_reaction', '{"en-us": "Standard entropy change of reaction"}', 'thermochemistry', 7, '{"en-us": "The standard entropy change of a reaction quantifies the change in disorder associated with converting reactants in their standard states into products in their standard states. It is computed as the difference between the sum of the standard molar entropies of the products and that of the reactants, each weighted by its stoichiometric coefficient. The sign and magnitude of this quantity indicate whether the reaction increases or decreases the disorder of the system at standard conditions."}', '["https://en.wikipedia.org/wiki/Entropy", "https://en.wikipedia.org/wiki/Thermodynamic_database_for_pure_substances", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Thermodynamics/Thermodynamic_Cycles/Standard_Entropy_Change_of_a_Reaction", "https://www.chem.purdue.edu/∼chembook/entropy-app.html", "https://www.khanacademy.org/science/chemistry/thermodynamics-chemistry/entropy-chemistry/v/entropy-and-the-second-law-of-thermodynamics", "https://chemed.chem.pitt.edu/entropy"]'),
  ('standard_error_definition', '{"en-us": "Standard error of the mean"}', 'statistics', 7, '{"en-us": "The standard error of the mean (SE) is the standard deviation of the sampling distribution of the sample mean, measuring how precisely the sample mean estimates the population mean. It equals the population standard deviation divided by the square root of the sample size, shrinking as more observations are collected. It is widely used to construct confidence intervals and to quantify the uncertainty of an estimated mean."}', '["https://en.wikipedia.org/wiki/Standard_error", "https://en.wikipedia.org/wiki/Standard_deviation", "https://www.khanacademy.org/math/statistics-probability/summarizing-quantitative-data/variance-standard-deviation-population/v/sample-standard-deviation", "https://stats.libretexts.org/Bookshelves/Probability_Theory/Book%3A_Introductory_Probability_(Grinstead_and_Snell)/07%3A_Sampling/7.2%3A_Sampling_Distributions", "https://www.bmj.com/content/331/7521/903", "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC1255808/"]'),
  ('standard_form_line', '{"en-us": "Standard form of a line"}', 'equations', 3, '{"en-us": "The standard form of a line expresses a linear equation in two variables as a sum of the variables each multiplied by a coefficient, equated to a constant, with at least one coefficient nonzero. It is convenient for quickly reading off the x- and y-intercepts and for solving systems of linear equations by elimination. Special cases include vertical and horizontal lines where one of the variable coefficients is zero."}', '["https://en.wikipedia.org/wiki/Linear_equation", "https://en.wikipedia.org/wiki/Equation_of_a_line", "https://math.libretexts.org/Bookshelves/Algebra/Intermediate_Algebra/04%3A_Graphing_Linear_Equations_and_Inequalities/4.01%3A_Graphing_Linear_Equations", "https://www.khanacademy.org/math/algebra/x2f8bb11595b61c86:forms-of-linear-equations/x2f8bb11595b61c86:standard-form/v/standard-form-of-linear-equations", "https://www.cuemath.com/geometry/standard-form-of-a-line/", "https://www.mathsisfun.com/algebra/line-equation-standardform.html"]'),
  ('standing_wave_frequency', '{"en-us": "Standing wave frequency"}', 'wave_interference', 6, '{"en-us": "Standing waves form on a string (or in a column) only at discrete resonant frequencies, each an integer multiple of a fundamental determined by the wave speed and twice the length of the medium for two-fixed-end boundary conditions. The integer n labels the harmonic or mode number, and the corresponding standing-wave pattern has n antinodes. These resonant frequencies underpin musical instruments and acoustic resonators."}', '["https://en.wikipedia.org/wiki/Standing_wave", "https://en.wikipedia.org/wiki/Harmonic", "https://en.wikipedia.org/wiki/Acoustic_resonance", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/16%3A_Waves_and_Acoustics/16.05%3A_Standing_Waves_and_Resonance", "https://www.khanacademy.org/science/physics/mechanical-waves-and-sound/standing-waves/v/standing-waves-on-strings", "https://physics.mit.edu/wp-content/uploads/2021/01/Cylinder.pdf"]'),
  ('standing_wave_node_positions', '{"en-us": "Standing wave node positions"}', 'wave_interference', 7, '{"en-us": "Nodes are the fixed points of zero amplitude in a standing wave, located at integer multiples of half a wavelength from a reference node. They arise from destructive interference of the two counter-propagating waves that superpose to create the standing pattern, and they remain stationary in time. The spacing between adjacent nodes is therefore half the wavelength of the underlying traveling waves."}', '["https://en.wikipedia.org/wiki/Standing_wave", "https://en.wikipedia.org/wiki/Node_(physics)", "https://en.wikipedia.org/wiki/Anti-node", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/16%3A_Waves_and_Acoustics/16.05%3A_Standing_Waves_and_Resonance", "https://www.physicsclassroom.com/class/waves/Lesson-4/Nodes-and-Antinodes", "https://www.khanacademy.org/science/physics/mechanical-waves-and-sound/standing-waves/v/nodes-and-anti-nodes-of-standing-waves"]'),
  ('statistics_median_odd', '{"en-us": "Median of an odd-sized dataset"}', 'statistics', 2, '{"en-us": "For a dataset containing an odd number of values, the median is the single middle observation once the data are arranged in order. Equivalently, it is the order statistic at position (n+1)/2, where n is the sample size, making it the 2-quantile of the empirical distribution. This definition of the median is robust to outliers, since it depends only on the rank of the central value rather than its magnitude."}', '["https://en.wikipedia.org/wiki/Median", "https://en.wikipedia.org/wiki/Order_statistic", "https://www.khanacademy.org/math/statistics-probability/summarizing-quantitative-data/mean-median-basics/v/statistics-intro-mean-median-and-mode", "https://math.libretexts.org/Bookshelves/Statistics_and_Probability/Introductory_Statistics/02%3A_Descriptive_Statistics/2.02%3A_Measures_of_Central_Tendency", "https://www.cuemath.com/data/median/", "https://www.mathsisfun.com/median.html"]'),
  ('statistics_mode_definition', '{"en-us": "Mode of a dataset"}', 'statistics', 2, '{"en-us": "The mode of a data set is the value that appears most often. It is one of the principal measures of central tendency, alongside the mean and median, and is the only such measure that is also meaningful for nominal (non-numeric) data."}', '["https://en.wikipedia.org/wiki/Mode_(statistics)", "https://www.mathsisfun.com/mode.html", "https://mathworld.wolfram.com/Mode.html", "https://www.britannica.com/science/mode-statistics"]'),
  ('stefan_boltzmann_constant_definition', '{"en-us": "Stefan-Boltzmann constant from fundamental constants"}', 'heat_transfer', 9, '{"en-us": "The Stefan–Boltzmann constant can be expressed entirely in terms of Boltzmann’s constant, Planck’s constant, the speed of light, and π. Following the 2019 SI redefinition, k, h, and c are fixed exactly, so σ is also exactly determined."}', '["https://en.wikipedia.org/wiki/Stefan%E2%80%93Boltzmann_law", "https://en.wikipedia.org/wiki/Boltzmann_constant", "https://en.wikipedia.org/wiki/Planck_constant", "https://www.britannica.com/science/blackbody-radiation", "https://physics.nist.gov/cgi-bin/cuu/Value?sigma"]'),
  ('stefan_boltzmann_law', '{"en-us": "Stefan-Boltzmann law"}', 'heat_transfer', 7, '{"en-us": "The Stefan–Boltzmann law states that the total thermal power radiated by a blackbody is proportional to the fourth power of its absolute temperature. Real (grey) surfaces emit less by a factor equal to their emissivity ε, so the general form is P = εσAT⁴."}', '["https://en.wikipedia.org/wiki/Stefan%E2%80%93Boltzmann_law", "https://en.wikipedia.org/wiki/Thermal_radiation", "https://en.wikipedia.org/wiki/Black_body", "https://www.britannica.com/science/blackbody-radiation", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/02%3A_The_Nature_of_Light"]'),
  ('stoichiometric_mass_proportion', '{"en-us": "Mass ratio from stoichiometric coefficients"}', 'chemical_reactions', 5, '{"en-us": "The mass ratio of two reactants (or products) in a balanced reaction is obtained by multiplying each species’ stoichiometric coefficient by its molar mass. This relation underlies composition and reaction stoichiometry, allowing conversion between moles and grams using the molar mass as a conversion factor."}', '["https://en.wikipedia.org/wiki/Stoichiometry", "https://en.wikipedia.org/wiki/Stoichiometric_amount", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/03%3A_Chemical_Reactions_-_Quantitative_Information_from_Balanced_Equations", "https://www.britannica.com/science/stoichiometry"]'),
  ('stoichiometric_mole_ratio', '{"en-us": "Stoichiometric mole ratio calculation"}', 'limiting_reactants', 5, '{"en-us": "The amount of a product obtained from a given amount of a reactant is found by multiplying the reactant moles by the ratio of the product’s to the reactant’s stoichiometric coefficient. This mole ratio is the basis of reaction stoichiometry."}', '["https://en.wikipedia.org/wiki/Stoichiometry", "https://en.wikipedia.org/wiki/Stoichiometric_amount", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/03%3A_Chemical_Reactions_-_Quantitative_Information_from_Balanced_Equations", "https://www.britannica.com/science/stoichiometry"]'),
  ('stoichiometric_proportion', '{"en-us": "Stoichiometric proportion for a reaction"}', 'chemical_reactions', 5, '{"en-us": "For any balanced reaction, the ratio of the amount of each species to its stoichiometric coefficient is the same for all species. This proportion lets one convert between moles of any two participants once one amount is known."}', '["https://en.wikipedia.org/wiki/Stoichiometry", "https://en.wikipedia.org/wiki/Stoichiometric_amount", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/03%3A_Chemical_Reactions_-_Quantitative_Information_from_Balanced_Equations", "https://www.britannica.com/science/stoichiometry"]'),
  ('stokes_law_drag', '{"en-us": "Stokes'' law for drag on a sphere"}', 'reynolds_number', 8, '{"en-us": "Stokes''s law gives the viscous drag force on a small sphere moving at very low Reynolds number through a fluid, assuming laminar flow, spherical shape, homogeneous material, and smooth non-interacting particles. It underlies falling-sphere viscometry and the derivation of the terminal velocity of microscopic particles settling in air or liquid."}', '["https://en.wikipedia.org/wiki/Stokes%27s_law", "https://en.wikipedia.org/wiki/Drag_(physics)", "https://en.wikipedia.org/wiki/Stokes_flow", "https://en.wikipedia.org/wiki/Terminal_velocity", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Dourmashkin)/21%3A_Fluid_Mechanics/21.07%3A_Terminal_Speed", "https://www.britannica.com/science/Stokess-law"]'),
  ('stopping_distance_braking', '{"en-us": "Stopping distance from friction"}', 'friction', 6, '{"en-us": "Braking distance is the distance a vehicle travels from full brake application to a complete stop, derived by equating the kinetic energy of motion to the work done by kinetic friction on a level surface. It is one of the two components of the total stopping distance, the other being the perception-reaction distance."}', '["https://en.wikipedia.org/wiki/Braking_distance", "https://en.wikipedia.org/wiki/Stopping_distance", "https://en.wikipedia.org/wiki/Kinetic_friction", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/06%3A_Applications_of_Newton''s_Laws/6.04%3A_Friction", "https://www.physicsclassroom.com/class/newtlaws/Lesson-3/Determining-Stopping-Distance"]'),
  ('stopping_potential', '{"en-us": "Stopping potential in photoelectric effect"}', 'quantum_mechanics', 8, '{"en-us": "The stopping (or cut-off) potential is the retarding voltage at which the photoelectric current vanishes, equal to the maximum kinetic energy of the emitted photoelectrons divided by the elementary charge. It is the experimental quantity used in Millikan-type tests of Einstein''s photoelectric law and provides a direct measure of the work function when the light frequency is known."}', '["https://en.wikipedia.org/wiki/Photoelectric_effect", "https://en.wikipedia.org/wiki/Work_function", "https://en.wikipedia.org/wiki/Einstein%27s_photoelectric_law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/05%3A_Photoelectric_Effect", "https://www.britannica.com/science/photoelectric-effect"]'),
  ('strain_definition', '{"en-us": "Engineering strain"}', 'forces', 6, '{"en-us": "Engineering (Cauchy) strain is the ratio of an axial elongation to the original length of a material element, used in the small-deformation analysis of metals, concrete, and other structural materials. For large deformations of elastomers and polymers, alternative strain measures such as logarithmic, Green, or Almansi strain must be used."}', '["https://en.wikipedia.org/wiki/Strain_(mechanics)", "https://en.wikipedia.org/wiki/Deformation_(engineering)", "https://en.wikipedia.org/wiki/Infinitesimal_strain_theory", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/12%3A_Static_Equilibrium_and_Elasticity/12.04%3A_Stress_Strain_and_Elastic_Modulus", "https://www.britannica.com/science/strain-physics"]'),
  ('sum_of_cubes', '{"en-us": "Sum of cubes"}', 'polynomials', 4, '{"en-us": "The sum of two cubes is the algebraic identity that decomposes a sum of two cubed terms into a product of a binomial and a quadratic trinomial. It is one of the standard ''recognizable patterns'' used in polynomial factorization, alongside the difference of squares and the difference of two cubes."}', '["https://en.wikipedia.org/wiki/Factorization", "https://en.wikipedia.org/wiki/Cubic_function", "https://en.wikipedia.org/wiki/Sophomore%27s_dream", "https://mathworld.wolfram.com/SumofCubes.html", "https://www.cuemath.com/algebra/sum-of-cubes/"]'),
  ('sum_of_interior_angles', '{"en-us": "Sum of interior angles of a polygon"}', 'polygons', 3, '{"en-us": "For any simple polygon with n sides, the interior angles sum to 180(n − 2) degrees or (n − 2)π radians, equivalent to partitioning the polygon into n − 2 triangles. The corresponding sum of exterior angles (one per vertex) is 360 degrees."}', '["https://en.wikipedia.org/wiki/Internal_and_external_angles", "https://en.wikipedia.org/wiki/Polygon", "https://en.wikipedia.org/wiki/Triangle", "https://www.mathsisfun.com/geometry/interior-angles-polygons.html", "https://mathworld.wolfram.com/Polygon.html"]'),
  ('sum_of_natural_numbers', '{"en-us": "Sum of first n natural numbers"}', 'arithmetic', 3, '{"en-us": "Gives the closed form for the nth triangular number, the sum of the positive integers from 1 through n. The formula is often attributed to the Pythagoreans and arises in counting, combinatorics, and proofs by induction."}', '["https://en.wikipedia.org/wiki/1_%2B_2_%2B_3_%2B_4_%2B_%E2%8B%AF", "https://en.wikipedia.org/wiki/Triangular_number", "https://mathworld.wolfram.com/TriangularNumber.html", "https://www.cuemath.com/algebra/sum-of-natural-numbers/", "https://www.britannica.com/science/triangular-number"]'),
  ('sum_to_product_cosine_minus', '{"en-us": "Sum-to-product: cos A - cos B"}', 'trigonometric_identities', 7, '{"en-us": "Converts the difference of two cosines into a product, expressing it in terms of half-angle sines. The identity follows from the cosine addition and subtraction formulas and is useful for combining or simplifying trigonometric expressions and solving certain trigonometric equations."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities#Sum-to-product_identities", "https://mathworld.wolfram.com/Sum-to-ProductFormulas.html", "https://www.cuemath.com/trigonometry/sum-to-product-formulas/", "https://www.khanacademy.org/math/trigonometry/trig-equations-and-identities/sum-to-product-formula/a/sum-to-product-formula-review", "https://www.britannica.com/science/sum-to-product-identities"]'),
  ('sum_to_product_cosine_plus', '{"en-us": "Sum-to-product: cos A + cos B"}', 'trigonometric_identities', 7, '{"en-us": "Converts the sum of two cosines into a product, expressed in terms of half-angle cosines. The identity follows from the cosine addition and subtraction formulas and is useful for combining or simplifying trigonometric expressions and solving certain trigonometric equations."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities#Sum-to-product_identities", "https://mathworld.wolfram.com/Sum-to-ProductFormulas.html", "https://www.cuemath.com/trigonometry/sum-to-product-formulas/", "https://www.khanacademy.org/math/trigonometry/trig-equations-and-identities/sum-to-product-formula/a/sum-to-product-formula-review", "https://www.britannica.com/science/sum-to-product-identities"]'),
  ('sum_to_product_sine_minus', '{"en-us": "Sum-to-product: sin A - sin B"}', 'trigonometric_identities', 7, '{"en-us": "Converts the difference of two sines into a product, expressed in terms of a half-angle cosine and a half-angle sine. The identity follows from the sine and cosine addition and subtraction formulas and is useful for combining or simplifying trigonometric expressions and solving certain trigonometric equations."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities#Sum-to-product_identities", "https://mathworld.wolfram.com/Sum-to-ProductFormulas.html", "https://www.cuemath.com/trigonometry/sum-to-product-formulas/", "https://www.khanacademy.org/math/trigonometry/trig-equations-and-identities/sum-to-product-formula/a/sum-to-product-formula-review", "https://www.britannica.com/science/sum-to-product-identities"]'),
  ('sum_to_product_sine_plus', '{"en-us": "Sum-to-product: sin A + sin B"}', 'trigonometric_identities', 7, '{"en-us": "Converts the sum of two sines into a product, expressed in terms of a half-angle sine and a half-angle cosine. The identity follows from the sine and cosine addition and subtraction formulas and is useful for combining or simplifying trigonometric expressions and solving certain trigonometric equations."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities#Sum-to-product_identities", "https://mathworld.wolfram.com/Sum-to-ProductFormulas.html", "https://www.cuemath.com/trigonometry/sum-to-product-formulas/", "https://www.khanacademy.org/math/trigonometry/trig-equations-and-identities/sum-to-product-formula/a/sum-to-product-formula-review", "https://www.britannica.com/science/sum-to-product-identities"]'),
  ('surface_area_cone', '{"en-us": "Surface area of a cone"}', 'plane_geometry', 4, '{"en-us": "Total surface area of a right circular cone, equal to the area of its circular base plus the area of its lateral (side) surface. The lateral surface is a circular sector of radius equal to the slant height when unrolled, giving the compact factored form."}', '["https://en.wikipedia.org/wiki/Cone#Surface_area", "https://mathworld.wolfram.com/Cone.html", "https://www.cuemath.com/geometry/surface-area-of-a-cone/", "https://www.khanacademy.org/math/geometry/x2f8bb11595b61c86:rounded-figures/x2f8bb11595b61c86:cones/v/surface-area-of-a-cone", "https://www.britannica.com/science/cone-mathematics"]'),
  ('surface_area_cone_total', '{"en-us": "Total surface area of a cone"}', 'plane_geometry', 4, '{"en-us": "The total surface area of a right circular cone includes its circular base plus the lateral area swept out by the slant height. \nIt assumes a right circular cone and uses the radius of the base together with the slant height measured from the base edge to the apex."}', '["https://en.wikipedia.org/wiki/Cone", "https://mathworld.wolfram.com/Cone.html", "https://www.cuemath.com/geometry/surface-area-of-a-cone/", "https://www.khanacademy.org/math/geometry/hs-geo-solids/hs-geo-solids-intro/v/surface-area-of-a-cone", "https://math.libretexts.org/Bookshelves/Geometry/Geometry_(OpenStax)/12%3A_Surface_Area/12.05%3A_Surface_Areas_of_Pyramids_and_Cones"]'),
  ('surface_area_cube', '{"en-us": "Surface area of a cube"}', 'plane_geometry', 2, '{"en-us": "A cube has six congruent square faces, so its total surface area is six times the area of one face. \nThe result holds for any right parallelepiped with equal edge lengths and is used in problems involving cubic volumes, materials estimation, and unit-cell calculations in crystallography."}', '["https://en.wikipedia.org/wiki/Cube", "https://mathworld.wolfram.com/Cube.html", "https://www.cuemath.com/geometry/surface-area-of-cube/", "https://www.khanacademy.org/math/geometry/hs-geo-solids/hs-geo-solids-intro/v/surface-area-of-a-cube", "https://math.libretexts.org/Bookshelves/Geometry/Geometry_(OpenStax)/12%3A_Surface_Area/12.04%3A_Surface_Area_of_a_Cube"]'),
  ('surface_area_cylinder', '{"en-us": "Surface area of a cylinder"}', 'plane_geometry', 3, '{"en-us": "The total surface area of a right circular cylinder combines the two circular end caps with the curved lateral area obtained by unrolling the side. \nIt assumes a right circular cylinder of constant radius and is widely used in engineering contexts such as pipe, tank, and pressure-vessel design."}', '["https://en.wikipedia.org/wiki/Cylinder", "https://mathworld.wolfram.com/Cylinder.html", "https://www.cuemath.com/geometry/surface-area-of-a-cylinder/", "https://www.khanacademy.org/math/geometry/hs-geo-solids/hs-geo-solids-intro/v/surface-area-of-a-cylinder", "https://math.libretexts.org/Bookshelves/Geometry/Geometry_(OpenStax)/12%3A_Surface_Area/12.06%3A_Surface_Area_of_a_Cylinder"]'),
  ('surface_area_rectangular_prism', '{"en-us": "Surface area of a rectangular prism"}', 'plane_geometry', 3, '{"en-us": "A rectangular prism has three pairs of congruent rectangular faces, so its total surface area is twice the sum of the areas of the three distinct face types. \nThe formula holds for any right box (orthogonal parallelepiped) and is the generalisation of which the cube''s formula is the special case where all three edge lengths are equal."}', '["https://en.wikipedia.org/wiki/Rectangular_cuboid", "https://en.wikipedia.org/wiki/Cuboid", "https://mathworld.wolfram.com/Cuboid.html", "https://www.cuemath.com/geometry/surface-area-of-a-rectangular-prism/", "https://www.khanacademy.org/math/geometry/hs-geo-solids/hs-geo-solids-intro/v/surface-area-of-a-box", "https://math.libretexts.org/Bookshelves/Geometry/Geometry_(OpenStax)/12%3A_Surface_Area/12.05%3A_Surface_Area_of_a_Rectangular_Prism"]'),
  ('surface_area_sphere', '{"en-us": "Surface area of a sphere"}', 'plane_geometry', 3, '{"en-us": "The surface area of a sphere equals four times the area of a great circle on it, a result Archimedes first obtained by comparing a sphere with its circumscribed cylinder. \nIt is the limiting case for any closed surface of given volume and appears in physics wherever spherical geometry arises, from planetary science to bubble mechanics."}', '["https://en.wikipedia.org/wiki/Sphere", "https://mathworld.wolfram.com/Sphere.html", "https://www.cuemath.com/geometry/surface-area-of-a-sphere/", "https://www.khanacademy.org/math/geometry/hs-geo-solids/hs-geo-solids-intro/v/surface-area-of-a-sphere", "https://math.libretexts.org/Bookshelves/Geometry/Geometry_(OpenStax)/12%3A_Surface_Area/12.07%3A_Surface_Area_of_a_Sphere"]'),
  ('surface_area_torus', '{"en-us": "Surface area of a torus"}', 'plane_geometry', 7, '{"en-us": "The surface area of a ring torus equals the product of the circumference of its generating circle and the circumference traced by the circle''s centre, a direct consequence of Pappus''s centroid theorem. \nThe formula assumes R greater than r (a non-self-intersecting ring torus) and is used in engineering analyses of pipes, gaskets, and toroidal coils."}', '["https://en.wikipedia.org/wiki/Torus", "https://mathworld.wolfram.com/Torus.html", "https://www.cuemath.com/geometry/surface-area-of-a-torus/", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/06%3A_Applications_of_Integration/6.02%3A_Determining_Volumes_by_Slicing/6.2.06%3A_Volume_of_a_Torus", "https://www.khanacademy.org/math/multivariable-calculus/integrating-multivariable-functions/double-integrals-aa/v/surface-area-of-torus"]'),
  ('surface_area_triangular_prism', '{"en-us": "Surface area of a triangular prism"}', 'plane_geometry', 3, '{"en-us": "A triangular prism has two triangular ends and three rectangular lateral faces. Its total surface area is the area of the two triangular bases plus the lateral surface area, which equals the perimeter of the triangular base multiplied by the prism length."}', '["https://en.wikipedia.org/wiki/Triangular_prism", "https://mathworld.wolfram.com/TriangularPrism.html", "https://www.cuemath.com/geometry/surface-area-of-a-triangular-prism/", "https://flexbooks.ck12.org/cbook/ck-12-conceptual-geometry-flexbook-2.0/section/11.4/primary/lesson/surface-areas-of-prisms-and-pyramids-geo/", "https://www.mathopenref.com/prism.html"]'),
  ('surface_charge_density_formula', '{"en-us": "Surface charge density"}', 'electrostatics', 6, '{"en-us": "Surface charge density is the amount of electric charge distributed per unit area of a surface. It is defined as the limit of charge over an infinitesimal area element and is central to electrostatics, particularly in applying Gauss''s law to charged conductors and capacitor plates."}', '["https://en.wikipedia.org/wiki/Charge_density", "https://en.wikipedia.org/wiki/Surface_charge", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/06%3A_Gauss''s_Law/6.01%3A_Electric_Flux", "https://www.britannica.com/science/charge-density", "https://www.khanacademy.org/science/physics/electric-charge-electric-force-and-voltage/electric-field/a/what-is-electric-field"]'),
  ('surface_density_formula', '{"en-us": "Surface density"}', 'plane_geometry', 4, '{"en-us": "Surface (areal) density is the mass per unit area of a thin, approximately two-dimensional object. It is widely used to characterize paper (grammage), fabrics, snowpack, and astronomical column densities integrated along a line of sight."}', '["https://en.wikipedia.org/wiki/Area_density", "https://en.wikipedia.org/wiki/Column_density", "https://www.britannica.com/science/areal-density", "https://www.tec-science.com/materials-science/density/density-of-flat-objects/", "https://www.nist.gov/pml/weights-and-measures/si-units"]'),
  ('surface_energy_tension', '{"en-us": "Surface energy from surface tension"}', 'surface_tension', 7, '{"en-us": "The total surface energy of a liquid interface is the surface tension multiplied by the area of the interface. It represents the work required to create that surface and equals the excess free energy of molecules at the boundary compared to those in the bulk."}', '["https://en.wikipedia.org/wiki/Surface_tension", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Properties_of_Liquids/Surface_Tension", "https://www.britannica.com/science/surface-tension", "https://en.wikipedia.org/wiki/Surface_energy", "https://physics.info/surface-tension/"]'),
  ('surface_tension_energy_definition', '{"en-us": "Surface tension from surface energy"}', 'surface_tension', 7, '{"en-us": "Surface tension can be defined as the change in surface free energy per unit change in surface area of the liquid interface. This energy-based definition is equivalent to the force-per-length definition through dimensional analysis."}', '["https://en.wikipedia.org/wiki/Surface_tension", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Properties_of_Liquids/Surface_Tension", "https://www.britannica.com/science/surface-tension", "https://en.wikipedia.org/wiki/Surface_energy", "https://physics.info/surface-tension/"]'),
  ('surface_tension_force', '{"en-us": "Surface tension force"}', 'surface_tension', 6, '{"en-us": "Surface tension exerts a tensile force along a contact line, with magnitude equal to the surface tension coefficient times the length of the line. This is the force a liquid surface applies to a movable wetted edge, responsible for capillary rise, droplet formation, and the ability of small insects to walk on water."}', '["https://en.wikipedia.org/wiki/Surface_tension", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Properties_of_Liquids/Surface_Tension", "https://en.wikipedia.org/wiki/Capillary_action", "https://www.britannica.com/science/surface-tension", "https://physics.info/surface-tension/"]'),
  ('surface_tension_formula', '{"en-us": "Surface tension"}', 'surface_tension', 6, '{"en-us": "Surface tension is the property of a liquid surface that causes it to behave like a stretched elastic membrane, allowing, for example, small insects to rest on water. It is defined as the force per unit length acting along a line on the liquid surface and arises from cohesive attractions between molecules at the interface."}', '["https://en.wikipedia.org/wiki/Surface_tension", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Properties_of_Liquids/Surface_Tension", "https://physics.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(D''Incecco)/01%3A_Kinematics/1.03%3A_Surface_Tension", "https://www.britannica.com/science/surface-tension", "https://www.khanacademy.org/science/biology/water-properties/v/hydrogen-bonding-in-water"]'),
  ('t_test_statistic', '{"en-us": "t-test statistic"}', 'statistics', 8, '{"en-us": "The one-sample t-statistic measures how many standard errors the sample mean lies from a hypothesized population mean, and under the null hypothesis it follows Student''s t-distribution with n−1 degrees of freedom. It is the basis of t-tests used to assess whether an observed mean is consistent with a reference value when the population standard deviation is unknown."}', '["https://en.wikipedia.org/wiki/Student%27s_t-test", "https://en.wikipedia.org/wiki/Student%27s_t-distribution", "https://www.khanacademy.org/math/statistics-probability/significance-tests-one-sample/more-significance-testing-videos/v/small-sample-hypothesis-test", "https://stats.libretexts.org/Bookshelves/Introductory_Statistics/Introductory_Statistics_(OpenStax)/09%3A_Hypothesis_Testing_with_One_Sample", "https://www.britannica.com/topic/t-test"]'),
  ('tangent_definition', '{"en-us": "Tangent definition"}', 'right_triangles', 3, '{"en-us": "In a right triangle, the tangent of an acute angle is the ratio of the length of the side opposite that angle to the length of the side adjacent to it (and not the hypotenuse). This right-triangle definition is the most elementary one and underpins the standard mnemonic SOH-CAH-TOA used in trigonometry."}', '["https://en.wikipedia.org/wiki/Trigonometric_functions#Right-angled_triangle_definitions", "https://math.libretexts.org/Bookshelves/Trigonometry/Trigonometry_(OpenStax)/01%3A_Right_Triangles_and_An Introduction_to_Trigonometry/1.02:_Right_Triangles_and_Trigonometry", "https://www.khanacademy.org/math/geometry/hs-geo-trig/hs-geo-trig-ratios-intro/v/basic-trigonometry", "https://www.britannica.com/science/tangent-trigonometry"]'),
  ('tangent_identity', '{"en-us": "Tangent identity"}', 'trigonometric_identities', 4, '{"en-us": "The tangent of an angle equals the sine of that angle divided by the cosine of the same angle, with cos(θ) ≠ 0. This quotient identity is fundamental and is consistent with the right-triangle definition since sin/cos = (opposite/hypotenuse)/(adjacent/hypotenuse) = opposite/adjacent."}', '["https://en.wikipedia.org/wiki/Trigonometric_functions", "https://en.wikipedia.org/wiki/List_of_trigonometric_identities", "https://math.libretexts.org/Bookshelves/Trigonometry/Trigonometry_(OpenStax)/01%3A_Right_Triangles_and_An_Introduction_to_Trigonometry/1.03%3A_The_Other_Four_Trigonometric_Functions", "https://www.khanacademy.org/math/trigonometry/trig-function-graphs/trig-identities-review/v/trig-identities", "https://www.britannica.com/science/tangent-trigonometry"]'),
  ('tangent_line_equation', '{"en-us": "Tangent line equation"}', 'derivatives', 6, '{"en-us": "Given a differentiable function and a point on its graph, the tangent line at that point is the best linear approximation to the function there. The line passes through the point and has slope equal to the derivative at that point, which is the point-slope form specialized to the derivative."}', '["https://en.wikipedia.org/wiki/Tangent#Equations", "https://en.wikipedia.org/wiki/Slope#Calculus", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/03%3A_Derivatives/3.02%3A_Defining_the_Derivative", "https://www.khanacademy.org/math/differential-calculus/dc-context-app/dc-linearization/v/linearization-and-tangents", "https://www.britannica.com/science/tangent-line-mathematics"]'),
  ('tangent_secant_theorem', '{"en-us": "Tangent-secant theorem"}', 'circles', 6, '{"en-us": "If a tangent from an external point meets a circle at T and a secant from the same point meets the circle at A (near) and B (far), then the squared tangent length equals the product of the external and whole secant segments. It is one of three classical cases (along with the intersecting chords and intersecting secants theorems) of the more general power-of-a-point theorem, originally proved in Euclid''s Elements (Book III, Proposition 36)."}', '["https://en.wikipedia.org/wiki/Tangent%E2%80%93secant_theorem", "https://en.wikipedia.org/wiki/Power_of_a_point", "https://math.libretexts.org/Bookshelves/Geometry/Geometry_(OpenStax)/10%3A_Circles/10.04%3A_Other_Segments_from_a_Chord", "https://www.khanacademy.org/math/geometry/hs-geo-circles/hs-geo-tangent-secant-angles/v/tangent-secant-angles", "https://www.britannica.com/science/power-of-a-point"]'),
  ('tangential_acceleration', '{"en-us": "Tangential acceleration"}', 'circular_motion', 6, '{"en-us": "The tangential component of an object''s acceleration along a curved path; it equals the radius times the angular acceleration and points along the direction of motion. It governs the rate of change of speed (as opposed to the centripetal component, which changes the direction of velocity)."}', '["https://en.wikipedia.org/wiki/Acceleration", "https://en.wikipedia.org/wiki/Circular_motion", "https://en.wikipedia.org/wiki/Angular_acceleration", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/04%3A_Motion_in_Two_and_Three_Dimensions", "https://www.khanacademy.org/science/physics/centripetal-force-and-gravitation/centripetal-acceleration/a/centripetal-acceleration-review"]'),
  ('tangential_velocity', '{"en-us": "Tangential velocity"}', 'circular_motion', 5, '{"en-us": "The linear speed of a point moving along a circular path, equal to the radius times the angular velocity. Although called a velocity, it has the same magnitude as the tangential component of the linear velocity vector (which also has a direction tangent to the circle)."}', '["https://en.wikipedia.org/wiki/Circular_motion", "https://en.wikipedia.org/wiki/Angular_velocity", "https://en.wikipedia.org/wiki/Tangential_speed", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/04%3A_Motion_in_Two_and_Three_Dimensions", "https://www.khanacademy.org/science/physics/centripetal-force-and-gravitation/centripetal-acceleration/a/centripetal-acceleration-review"]'),
  ('temperature_absolute_value', '{"en-us": "Absolute zero temperature"}', 'temperature', 3, '{"en-us": "On the absolute (Kelvin) temperature scale, the lowest theoretically attainable temperature is zero. In other words, absolute thermodynamic temperature is strictly positive; absolute zero is unattainable in a finite number of steps by the third law of thermodynamics."}', '["https://en.wikipedia.org/wiki/Absolute_zero", "https://en.wikipedia.org/wiki/Thermodynamic_temperature", "https://www.britannica.com/science/absolute-zero", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Properties_of_Gases/Gas_Laws/The_Ideal_Gas_Law", "https://www.khanacademy.org/science/chemistry/gases-and-kinetic-molecular-theory/v/the-ideal-gas-law"]'),
  ('temperature_celsius_fahrenheit', '{"en-us": "Celsius to Fahrenheit conversion"}', 'temperature', 2, '{"en-us": "Linear conversion between temperatures expressed on the Celsius and Fahrenheit scales. Because the two scales have different zero points (0 °C = 32 °F) and different degree sizes, a Celsius temperature is first scaled by 9/5 and then shifted by 32."}', '["https://en.wikipedia.org/wiki/Conversion_of_scales_of_temperature", "https://en.wikipedia.org/wiki/Fahrenheit", "https://en.wikipedia.org/wiki/Celsius", "https://www.britannica.com/science/Fahrenheit-temperature-scale", "https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/02%3A_Atoms_Molecules_and_Chemical_Reactions/2.08%3A_Temperature"]'),
  ('temperature_fahrenheit_celsius', '{"en-us": "Fahrenheit to Celsius conversion"}', 'temperature', 2, '{"en-us": "Linear conversion between temperatures expressed on the Fahrenheit and Celsius scales. The Fahrenheit value is first shifted by −32 to align the two scales'' zero points, then scaled by 5/9 to convert from Fahrenheit-sized to Celsius-sized degrees."}', '["https://en.wikipedia.org/wiki/Conversion_of_scales_of_temperature", "https://en.wikipedia.org/wiki/Fahrenheit", "https://en.wikipedia.org/wiki/Celsius", "https://www.britannica.com/science/Fahrenheit-temperature-scale", "https://chem.libretexts.org/Bookshelves/General_Chemistry/ChemPRIME_(Moore_et_al.)/02%3A_Atoms_Molecules_and_Chemical_Reactions/2.08%3A_Temperature"]'),
  ('temperature_ideal_gas_kinetic', '{"en-us": "Temperature from average kinetic energy"}', 'temperature', 7, '{"en-us": "Valid for an ideal gas; relates absolute temperature to average translational kinetic energy per molecule."}', '["https://en.wikipedia.org/wiki/Kinetic_theory_of_gases", "https://en.wikipedia.org/wiki/Boltzmann_constant", "https://en.wikipedia.org/wiki/Ideal_gas_law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/02%3A_Motion_Along_a_Straight_Line", "https://www.khanacademy.org/science/chemistry/gases-and-kinetic-molecular-theory/v/kinetic-molecular-theory-of-gases"]'),
  ('temperature_rankine_conversion', '{"en-us": "Rankine to Fahrenheit conversion"}', 'temperature', 5, '{"en-us": "Converts a temperature expressed on the absolute Rankine scale to the equivalent reading on the Fahrenheit scale. Rankine degrees are defined equal in size to Fahrenheit degrees, so the conversion is simply a zero-point shift of 459.67 degrees, since absolute zero (0 °R) corresponds to −459.67 °F."}', '["https://en.wikipedia.org/wiki/Rankine_scale", "https://en.wikipedia.org/wiki/Fahrenheit", "https://www.thoughtco.com/absolute-temperature-scales-609226", "https://www.unitconverters.net/temperature/rankine-to-fahrenheit.htm"]'),
  ('temperature_rankine_from_fahrenheit', '{"en-us": "Temperature in Rankine from Fahrenheit"}', 'temperature', 6, '{"en-us": "Converts a Fahrenheit reading to the equivalent temperature on the absolute Rankine scale. Because Rankine uses Fahrenheit-sized degree intervals but is anchored at absolute zero, the conversion is just a constant offset of 459.67 degrees, used in engineering systems that work in Fahrenheit while still requiring an absolute thermodynamic scale."}', '["https://en.wikipedia.org/wiki/Rankine_scale", "https://en.wikipedia.org/wiki/Fahrenheit", "https://en.wikipedia.org/wiki/Conversion_of_scales_of_temperature", "https://www.engineeringtoolbox.com/temperature-conversion-d_216.html"]'),
  ('temperature_rankine_kelvin', '{"en-us": "Rankine to Kelvin conversion"}', 'temperature', 5, '{"en-us": "Converts a temperature on the Rankine scale to kelvins. Since one Rankine degree equals 5/9 of a kelvin, dividing the Rankine value by 1.8 (or 9/5) yields the equivalent kelvin reading, preserving the absolute scale since both begin at absolute zero."}', '["https://en.wikipedia.org/wiki/Rankine_scale", "https://en.wikipedia.org/wiki/Kelvin", "https://en.wikipedia.org/wiki/Conversion_of_scales_of_temperature", "https://www.metric-conversions.org/temperature/rankine-to-kelvin.htm"]'),
  ('tension_atwood', '{"en-us": "Tension in an Atwood machine"}', 'forces', 6, '{"en-us": "Gives the tension in the massless, inextensible string of an ideal Atwood machine, where two hanging masses m₁ and m₂ are connected over a frictionless pulley. It is derived from Newton''s second law applied to each mass, and is intermediate between the two weights m₁g and m₂g."}', '["https://en.wikipedia.org/wiki/Atwood_machine", "https://openstax.org/books/university-physics-volume-1/pages/6-5-friction", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/05%3A_Newtons_Laws/5.04%3A_Atwood_Machine", "https://www.physicsclassroom.com/Class/newtlaws/u2l2e.cfm"]'),
  ('tension_hanging_mass', '{"en-us": "Dynamics: tension in a hanging mass"}', 'forces', 5, '{"en-us": "Newton''s second law applied to a single mass m hanging from a string, where the mass is accelerating upward at rate a. The upward tension must support the weight mg and additionally accelerate the mass, giving the net tension as the difference between gravitational and inertial contributions."}', '["https://en.wikipedia.org/wiki/Newton%27s_laws_of_motion", "https://www.physicsclassroom.com/Class/newtlaws/u2l2e.cfm", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/05%3A_Newtons_Laws", "https://openstax.org/books/university-physics-volume-1/pages/6-5-friction"]'),
  ('terminal_velocity', '{"en-us": "Terminal velocity"}', 'reynolds_number', 7, '{"en-us": "The constant speed reached by a falling object when the downward gravitational force balances the upward drag force from the surrounding fluid, neglecting buoyancy. It depends on the object''s mass and projected area as well as the fluid''s density and the drag coefficient, and is widely applied in skydiving, aerosol and sediment transport, and meteorology."}', '["https://en.wikipedia.org/wiki/Terminal_velocity", "https://en.wikipedia.org/wiki/Drag_equation", "https://openstax.org/books/university-physics-volume-1/pages/6-4-drag-force-and-terminal-speed", "https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/termvel/", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/06%3A_Applications_of_Newton%27s_Laws"]'),
  ('terminal_velocity_stokes', '{"en-us": "Terminal velocity in Stokes flow"}', 'reynolds_number', 8, '{"en-us": "Stokes'' law gives the drag force on a small sphere moving through a viscous fluid at very low Reynolds number, and equating it to the gravitational (and optional buoyancy) force gives the terminal settling velocity. The simplified form here is valid for a sphere whose effective mass m already accounts for buoyancy, or for a sphere in vacuum-like conditions where buoyancy is negligible."}', '["https://en.wikipedia.org/wiki/Terminal_velocity", "https://en.wikipedia.org/wiki/Stokes%27_law", "https://www.britannica.com/science/Stokes-law-fluid-mechanics", "https://courses.lumenlearning.com/physics/chapter/9-6-terminal-velocity/", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.06%3A_Stokes''_Law"]'),
  ('thermal_resistance_formula', '{"en-us": "Thermal resistance (R-value)"}', 'heat_transfer', 7, '{"en-us": "Thermal resistance (the R-value used in building insulation) is the thickness of a material divided by its thermal conductivity, giving a measure of how well the material resists conductive heat flow per unit area. It assumes one-dimensional steady-state conduction and is most useful for comparing insulating layers of different materials and thicknesses."}', '["https://en.wikipedia.org/wiki/Thermal_resistance", "https://www.energy.gov/energysaver/insulation-r-value", "https://www.archtoolbox.com/materials-systems/insulation/r-value.html", "https://www.omnicalculator.com/physics/r-value", "https://www.thoughtco.com/what-is-r-value-4071782"]'),
  ('thermal_stress_formula', '{"en-us": "Thermal stress formula"}', 'temperature', 7, '{"en-us": "Thermal stress is the mechanical stress induced in a material when a temperature change is prevented from producing free thermal expansion, such as when the body is rigidly constrained. The stress is the product of Young''s modulus, the linear thermal expansion coefficient, and the temperature change, and it is a key consideration in the design of bridges, rails, pipelines, and bimetallic strips."}', '["https://en.wikipedia.org/wiki/Thermal_stress", "https://www.engineersedge.com/material_science/thermal_stress.htm", "https://www.thomasnet.com/articles/custom-manufacturing-fabricating/thermal-stress/", "https://www.efatigue.com/constant_amplitude_thermal_stress/", "https://www.doitpoms.ac.uk/tlplib/thermal_expansion/printall.php"]'),
  ('thermodynamic_temperature_definition', '{"en-us": "Thermodynamic definition of temperature"}', 'second_law', 8, '{"en-us": "The thermodynamic definition of temperature arises from the second law of thermodynamics and is grounded in the Carnot cycle. In differential form, 1/T equals the partial derivative of entropy with respect to internal energy at constant volume and particle number; the discrete ratio shown here is a useful approximation for finite reversible heat transfers and entropy changes."}', '["https://en.wikipedia.org/wiki/Temperature#Thermodynamic_approach", "https://en.wikipedia.org/wiki/Thermodynamic_temperature", "https://www.britannica.com/science/temperature", "https://phys.libretexts.org/Bookshelves/Thermodynamics_and_Statistical_Mechanics/Book%3A_Thermodynamics_(Tong)/01%3A_Introduction_to_Thermodynamics/1.03%3A_What_is_Temperature", "https://www.phys.ubbcluj.ro/~emil.matthaios/Lectures/Thermodynamics/03_Thermodynamic_definition_of_temperature.pdf"]'),
  ('thin_film_constructive', '{"en-us": "Thin film constructive interference"}', 'interference', 8, '{"en-us": "Thin-film interference arises when light reflected from the upper and lower surfaces of a thin transparent film recombines, producing constructive or destructive fringes depending on the optical path difference. The relation shown gives the bright (constructive) fringe condition for a film whose two reflected waves incur equal phase shifts, in which case the round-trip optical path 2nt must equal an integer number of wavelengths."}', '["https://en.wikipedia.org/wiki/Thin-film_interference", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/03%3A_Interference/3.06%3A_Thin_Film_Interference", "https://www.britannica.com/science/thin-film-interference", "https://opentextbc.ca/universityphysicsv3/chapter/3-6-thin-film-interference/", "https://www.animations.physics.unsw.edu.au/jw/light/interference-thin-film.html", "https://www.toppr.com/guides/physics/wave-optics/thin-film-interference/"]'),
  ('thin_film_constructive_m_half', '{"en-us": "Thin film constructive (m+½)"}', 'interference', 8, '{"en-us": "When one of the two reflections at a thin film undergoes a 180° phase change (such as light reflecting off a soap film in air), the constructive interference condition shifts so that the round-trip optical path equals a half-integer number of wavelengths. The full relation for normal incidence is 2 n t = (m + 1/2) λ; the entry isolates the geometric factors for clarity."}', '["https://en.wikipedia.org/wiki/Thin-film_interference", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_III_-_Optics_and_Modern_Physics_(OpenStax)/03%3A_Interference/3.06%3A_Thin_Film_Interference", "https://www.britannica.com/science/thin-film-interference", "https://opentextbc.ca/universityphysicsv3/chapter/3-6-thin-film-interference/", "https://www.animations.physics.unsw.edu.au/jw/light/interference-thin-film.html"]'),
  ('thin_film_destructive', '{"en-us": "Thin film destructive interference"}', 'interference', 8, '{"en-us": "Condition for destructive interference of light reflected from a thin film, accounting for the half-wavelength phase shift that occurs upon reflection at a boundary where light enters a medium of higher refractive index. This form applies when reflection at both film boundaries produces a 180° phase shift (such as an anti-reflection coating on a substrate of higher index), so the optical path difference for destructive interference is a half-integer multiple of the wavelength."}', '["https://en.wikipedia.org/wiki/Thin-film_interference", "https://en.wikipedia.org/wiki/Anti-reflective_coating", "https://en.wikipedia.org/wiki/Reflection_phase_change", "https://phys.libretexts.org/Bookshelves/Optics/Supplemental_Modules_(Components)", "https://en.wikipedia.org/wiki/Thin_film", "https://en.wikipedia.org/wiki/Refractive_index"]'),
  ('thin_film_destructive_zero_order', '{"en-us": "Thin film destructive interference (zero order)"}', 'interference', 8, '{"en-us": "The zero-order special case of the destructive-interference condition for a thin film whose reflections at both boundaries undergo a 180° phase shift, such as a single-layer anti-reflection coating. The required film thickness is one quarter of the in-film wavelength, the standard quarter-wave coating thickness."}', '["https://en.wikipedia.org/wiki/Thin-film_interference", "https://en.wikipedia.org/wiki/Anti-reflective_coating", "https://en.wikipedia.org/wiki/Reflection_phase_change", "https://phys.libretexts.org/Bookshelves/Optics/Supplemental_Modules_(Components)"]'),
  ('thin_film_interference_condition', '{"en-us": "Thin film interference condition"}', 'interference', 8, '{"en-us": "General condition for constructive interference in a thin film at normal incidence when the reflections at both film boundaries undergo equal phase shifts (or no net phase shift). The optical path difference between light reflected from the top and bottom surfaces must equal an integer multiple of the wavelength in vacuum."}', '["https://en.wikipedia.org/wiki/Thin-film_interference", "https://en.wikipedia.org/wiki/Anti-reflective_coating", "https://en.wikipedia.org/wiki/Reflection_phase_change", "https://phys.libretexts.org/Bookshelves/Optics/Supplemental_Modules_(Components)", "https://en.wikipedia.org/wiki/Thin_film"]'),
  ('thin_film_interference_constructive', '{"en-us": "Thin film interference (constructive)"}', 'interference', 8, '{"en-us": "Condition for constructive interference in the light reflected from a thin film in which only one of the two boundaries introduces a 180° phase shift (the typical case for a film of higher refractive index than both surrounding media, such as a soap film in air or an oil film on water). The half-wavelength phase shift displaces the constructive maxima to half-integer multiples of the wavelength."}', '["https://en.wikipedia.org/wiki/Thin-film_interference", "https://en.wikipedia.org/wiki/Anti-reflective_coating", "https://en.wikipedia.org/wiki/Reflection_phase_change", "https://phys.libretexts.org/Bookshelves/Optics/Supplemental_Modules_(Components)", "https://en.wikipedia.org/wiki/Thin_film"]'),
  ('thin_film_phase_shift', '{"en-us": "Thin film reflection phase shift condition"}', 'interference', 8, '{"en-us": "Interference condition for light reflected from a thin film when a 180° phase change occurs on reflection, shifting the condition by a half-wavelength so the optical path difference equals a half-integer multiple of the wavelength. This is the situation for a film whose refractive index exceeds that of the medium on at least one side, and it underlies the colors of soap bubbles and oil films on water."}', '["https://en.wikipedia.org/wiki/Thin-film_interference", "https://en.wikipedia.org/wiki/Reflection_phase_change", "https://en.wikipedia.org/wiki/Anti-reflective_coating", "https://phys.libretexts.org/Bookshelves/Optics/Supplemental_Modules_(Components)", "https://en.wikipedia.org/wiki/Thin_film"]'),
  ('torque_angular_momentum_rate', '{"en-us": "Torque as rate of change of angular momentum"}', 'angular_momentum', 7, '{"en-us": "The net external torque on a system equals the time rate of change of its angular momentum, the rotational analogue of Newton''s second law. This is the finite-difference form used for impulsive interactions; when the net external torque is zero, the total angular momentum of an isolated system is conserved."}', '["https://en.wikipedia.org/wiki/Torque", "https://en.wikipedia.org/wiki/Angular_momentum", "https://en.wikipedia.org/wiki/Newton%27s_laws_of_motion", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics", "https://en.wikipedia.org/wiki/Rotational_energy"]'),
  ('torque_from_force', '{"en-us": "Torque from force"}', 'torque', 5, '{"en-us": "Torque is the rotational equivalent of a linear force, producing a tendency to rotate a body about an axis. The scalar (moment-arm) form states that the magnitude equals the force multiplied by the perpendicular distance from the axis to the line of action of the force."}', '["https://en.wikipedia.org/wiki/Torque", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10%3A_Fixed-Axis_Rotation/10.04%3A_Torque", "https://www.britannica.com/science/torque", "https://www.khanacademy.org/science/physics/torque-angular-momentum/torque-tutorial/v/introduction-to-torque", "https://courses.lumenlearning.com/suny-osuniversityphysics/chapter/10-4-torque/"]'),
  ('torque_on_current_loop', '{"en-us": "Torque on a current loop in a magnetic field"}', 'magnetism', 7, '{"en-us": "A current loop placed in a uniform external magnetic field experiences a torque that tends to align the loop''s magnetic moment with the field. The torque is maximum when the plane of the loop lies along the field and zero when the loop''s normal is parallel or antiparallel to the field."}', '["https://en.wikipedia.org/wiki/Magnetic_moment", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/12%3A_Sources_of_Magnetic_Fields/12.04%3A_Magnetic_Field_of_a_Current_Loop", "https://www.britannica.com/science/magnetic-dipole-moment", "https://www.khanacademy.org/science/physics/magnetic-forces-and-magnetic-fields/magnetic-flux-faradays-law/v/magnetic-flux", "https://courses.lumenlearning.com/suny-osuniversityphysics/chapter/12-4-magnetic-field-of-a-current-loop/"]'),
  ('torque_rotational', '{"en-us": "Torque from moment of inertia"}', 'torque', 6, '{"en-us": "The net torque on a rigid body rotating about a fixed axis equals its moment of inertia about that axis times its angular acceleration. This is the rotational analogue of Newton''s second law of motion, valid when the body''s shape and mass distribution are constant."}', '["https://en.wikipedia.org/wiki/Moment_of_inertia", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/10%3A_Fixed-Axis_Rotation/10.05%3A_Newton''s_Second_Law_for_Rotation", "https://www.britannica.com/science/moment-of-inertia", "https://www.khanacademy.org/science/physics/torque-angular-momentum/torque-tutorial/v/rotational-inertia", "https://courses.lumenlearning.com/suny-osuniversityphysics/chapter/10-5-newtons-second-law-for-rotation/"]'),
  ('torque_vector_cross_product', '{"en-us": "Torque from cross product (vector)"}', 'torque', 7, '{"en-us": "In three dimensions, the torque produced by a force about a point is the cross product of the position vector from that point to the point of force application with the force vector. The resulting torque vector is perpendicular to the plane of r and F, with direction given by the right-hand rule."}', '["https://en.wikipedia.org/wiki/Torque", "https://en.wikipedia.org/wiki/Cross_product", "https://phys.libretexts.org/Bookshelves/Classical_Mechanics/Classical_Mechanics_(Dourmashkin)/06%3A_Work_and_Energy/6.04%3A_Cross_Product_Review", "https://www.britannica.com/science/cross-product", "https://www.khanacademy.org/science/physics/torque-angular-momentum/torque-tutorial/v/cross-product-and-torque"]'),
  ('torricellis_theorem', '{"en-us": "Torricelli''s theorem"}', 'bernoulli_equation', 6, '{"en-us": "Torricelli''s theorem states that the speed of fluid flowing out of an orifice equals the speed a body would attain in free fall from the same height above the orifice. It applies under the idealized conditions of an incompressible, non-viscous fluid and an orifice that is small compared to the container''s cross-section, and is a special case of Bernoulli''s principle."}', '["https://en.wikipedia.org/wiki/Torricelli%27s_law", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.06%3A_Bernoulli%27s_Equation", "https://www.britannica.com/science/Torricellis-theorem", "https://www.khanacademy.org/science/physics/fluids/what-is-fluids/v/what-is-fluids-introduction", "https://courses.lumenlearning.com/suny-osuniversityphysics/chapter/14-6-bernoullis-equation/"]'),
  ('total_mechanical_energy', '{"en-us": "Total mechanical energy"}', 'conservation_of_energy', 5, '{"en-us": "Total mechanical energy is the sum of the macroscopic kinetic and potential energies of a system. In the absence of non-conservative forces such as friction, this sum is conserved over time and energy merely transfers between its kinetic and potential components."}', '["https://en.wikipedia.org/wiki/Mechanical_energy", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/08%3A_Potential_Energy_and_Conservation_of_Energy/8.01%3A_Potential_Energy_of_a_System", "https://www.britannica.com/science/mechanical-energy", "https://www.khanacademy.org/science/physics/work-and-energy/work-and-energy-tutorial/v/conservation-of-energy", "https://courses.lumenlearning.com/suny-osuniversityphysics/chapter/8-1-potential-energy-of-a-system/"]'),
  ('trajectory_equation_projectile', '{"en-us": "Projectile trajectory equation"}', 'projectile_motion', 6, '{"en-us": "Describes the parabolic path of an object launched near Earth''s surface and moving only under a constant gravitational acceleration, with air resistance neglected. The relationship gives the vertical height as a function of horizontal distance traveled from the launch point, assuming level ground and an initial height of zero. It is the foundation of classical ballistics, sports trajectory analysis, and water-jet or fountain modeling."}', '["https://en.wikipedia.org/wiki/Projectile_motion", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/03%3A_Motion_Along_a_Straight_Line", "https://www.khanacademy.org/science/physics/two-dimensional-motion/projectile-motion/v/projectile-motion-introduction", "https://courses.lumenlearning.com/boundless-physics/chapter/projectile-motion/"]'),
  ('transformer_current', '{"en-us": "Transformer current relationship"}', 'electromagnetic_induction', 6, '{"en-us": "Derived from conservation of power in an ideal transformer, equating the apparent electrical power in the primary and secondary windings. Combined with the turns-ratio relationship it links primary and secondary currents to primary and secondary voltages. It underpins the design of step-up and step-down power transformers used in AC power distribution."}', '["https://en.wikipedia.org/wiki/Transformer", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/14%3A_Electromagnetic_Induction/14.05%3A_Transformers", "https://www.khanacademy.org/science/physics/magnetic-forces-and-magnetic-fields/electromagnetic-induction/v/transformers", "https://www.allaboutcircuits.com/textbook/alternating-current/chpt-9/mutual-inductance/"]'),
  ('transformer_equation', '{"en-us": "Transformer equation"}', 'electromagnetic_induction', 6, '{"en-us": "Relates the voltages of the secondary and primary windings of an ideal transformer to the number of turns in each winding, following directly from Faraday''s law of induction. Step-up and step-down transformers are designed by choosing the appropriate turns ratio, and the same relationship holds for the equivalent inductances of the windings. It is the fundamental design equation for power and signal transformers."}', '["https://en.wikipedia.org/wiki/Transformer", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/14%3A_Electromagnetic_Induction/14.05%3A_Transformers", "https://www.khanacademy.org/science/physics/magnetic-forces-and-magnetic-fields/electromagnetic-induction/v/transformers", "https://www.allaboutcircuits.com/textbook/alternating-current/chpt-9/transformer-construction/"]'),
  ('transmittance_from_absorbance', '{"en-us": "Transmittance from absorbance"}', 'analytical_chemistry', 6, '{"en-us": "Gives the fractional transmittance of light through a sample directly from its decadic absorbance, equivalent to rearranging the definition A = -log10(T). It is widely used in UV-Vis and infrared spectrophotometry to convert between the two common ways of expressing light attenuation. The relation holds for monochromatic light and samples that obey the Beer-Lambert law."}', '["https://en.wikipedia.org/wiki/Transmittance", "https://en.wikipedia.org/wiki/Absorbance", "https://chem.libretexts.org/Bookshelves/Analytical_Chemistry/Instrumental_Analysis_(LibreTexts)/13%3A_Introduction_to_Ultraviolet_Visible_Absorption_Spectrometry/13.01%3A_Transmittance_and_Absorbance", "https://www.sigmaaldrich.com/GB/en/support/calculators-and-apps/absorbance-transmittance-conversion"]'),
  ('triangle_altitude_formula', '{"en-us": "Altitude of a triangle"}', 'triangles', 4, '{"en-us": "Relates the altitude (height) of a triangle to its area and the length of the chosen base, derived by inverting the standard area formula A = (1/2) b h. It is useful whenever the area and base are known and the perpendicular height is required, for example in coordinate-geometry problems or in surveying. The altitude is the perpendicular distance from the opposite vertex to the line containing the base."}', '["https://en.wikipedia.org/wiki/Triangle", "https://mathworld.wolfram.com/Altitude.html", "https://math.libretexts.org/Bookshelves/Geometry/Book%3A_Geometry_(OpenStax)/10%3A_Area/10.02%3A_Area_and_Circumference", "https://www.khanacademy.org/math/geometry/triangle-properties/triangle-area/v/area-of-a-triangle"]'),
  ('triangle_angle_sum', '{"en-us": "Triangle angle sum"}', 'triangles', 2, '{"en-us": "States that the three interior angles of any Euclidean plane triangle add up to a straight angle, which is pi radians or 180 degrees. It is equivalent to Euclid''s parallel postulate and fails in spherical and hyperbolic geometry. The relation lets one compute a missing angle when the other two are known and underpins many theorems in Euclidean geometry and trigonometry."}', '["https://en.wikipedia.org/wiki/Triangle", "https://math.libretexts.org/Bookshelves/Geometry/Book%3A_Geometry_(OpenStax)/02%3A_Reasoning_and_Proofs/2.08%3A_Proofs_in_Geometry", "https://www.khanacademy.org/math/geometry/triangle-properties/triangle-angles/v/sum-of-interior-angles-of-a-triangle", "https://mathworld.wolfram.com/TriangleInteriorAngles.html"]'),
  ('triangle_area_sas', '{"en-us": "Triangle area (SAS)"}', 'triangles', 5, '{"en-us": "The area of a triangle whose two sides a and b and the included angle C are known is computed from those two adjacent sides and the sine of the angle between them. This side-angle-side form is useful in surveying and navigation when the included angle can be measured directly rather than the height."}', '["https://en.wikipedia.org/wiki/Area_of_a_triangle", "https://en.wikipedia.org/wiki/Law_of_sines", "https://math.libretexts.org/Bookshelves/Trigonometry", "https://www.cuemath.com/geometry/area-of-triangle/"]'),
  ('triangle_area_sides_heron', '{"en-us": "Triangle area from three sides (Heron''s formula)"}', 'triangles', 5, '{"en-us": "Heron''s formula expresses the area of a triangle purely in terms of the three side lengths a, b, and c, using the semiperimeter s = (a+b+c)/2. It is attributed to Heron of Alexandria and is widely applied in surveying, navigation, and any setting where side lengths are easier to obtain than heights."}', '["https://en.wikipedia.org/wiki/Heron%27s_formula", "https://en.wikipedia.org/wiki/Area_of_a_triangle", "https://en.wikipedia.org/wiki/Semiperimeter", "https://mathworld.wolfram.com/HeronsFormula.html", "https://www.cuemath.com/geometry/herons-formula/"]'),
  ('triangle_circumradius', '{"en-us": "Circumradius of a triangle"}', 'triangles', 6, '{"en-us": "The circumradius is the radius of the unique circle that passes through all three vertices of a triangle (the circumcircle). It is given by the product of the three side lengths divided by four times the triangle''s area, and is closely related to the law of sines."}', '["https://en.wikipedia.org/wiki/Circumcircle", "https://en.wikipedia.org/wiki/Semiperimeter", "https://en.wikipedia.org/wiki/Law_of_sines", "https://mathworld.wolfram.com/Circumradius.html", "https://www.cuemath.com/geometry/circumradius-of-a-triangle/"]'),
  ('triangle_inradius', '{"en-us": "Inradius of a triangle"}', 'triangles', 6, '{"en-us": "The inradius is the radius of the incircle, the largest circle that fits inside a triangle and is tangent to all three sides. It equals the triangle''s area divided by its semiperimeter, a relationship that follows from the incircle splitting the triangle into three sub-triangles of heights equal to the inradius."}', '["https://en.wikipedia.org/wiki/Incircle_and_excircles", "https://en.wikipedia.org/wiki/Semiperimeter", "https://mathworld.wolfram.com/Inradius.html", "https://www.cuemath.com/geometry/inradius-of-a-triangle/"]'),
  ('triangle_median_formula', '{"en-us": "Median length of a triangle"}', 'triangles', 6, '{"en-us": "The length of a triangle''s median to side a is determined by the two sides b and c adjacent to that median and by side a itself, via Apollonius''s theorem. The three medians always meet at the centroid, which divides each in a 2:1 ratio measured from the vertex."}', '["https://en.wikipedia.org/wiki/Median_(geometry)", "https://en.wikipedia.org/wiki/Apollonius%27s_theorem", "https://mathworld.wolfram.com/TriangleMedian.html", "https://www.cuemath.com/geometry/median-of-a-triangle/"]'),
  ('triangle_semiperimeter', '{"en-us": "Semiperimeter of a triangle"}', 'triangles', 3, '{"en-us": "The semiperimeter of a triangle is half of its perimeter, equal to half the sum of the three side lengths. It appears as a building block in many triangle formulas, most notably Heron''s formula for the area and the inradius relation r = A/s."}', '["https://en.wikipedia.org/wiki/Semiperimeter", "https://en.wikipedia.org/wiki/Heron%27s_formula", "https://en.wikipedia.org/wiki/Incircle_and_excircles", "https://mathworld.wolfram.com/Semiperimeter.html"]'),
  ('trigonometric_cosine_double_angle_alternate', '{"en-us": "Cosine double angle (cosine form)"}', 'trigonometric_identities', 5, '{"en-us": "This is one of the standard double-angle identities expressing the cosine of twice an angle purely in terms of the cosine of that angle. It is derived from the angle sum formula for cosine and the Pythagorean identity, and is widely used to simplify products of cosines and to reduce powers of cosine in integration and signal-processing problems."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities", "https://en.wikipedia.org/wiki/Trigonometric_functions", "https://en.wikipedia.org/wiki/De_Moivre%27s_formula", "https://mathworld.wolfram.com/Double-AngleFormulas.html", "https://mathworld.wolfram.com/Multiple-AngleFormulas.html"]'),
  ('trigonometric_cosine_squared_identity', '{"en-us": "Cosine squared identity"}', 'trigonometric_identities', 5, '{"en-us": "This power-reduction identity rewrites the square of the cosine of an angle in terms of the cosine of twice the angle. It is the cosine form of the half-angle / power-reduction formulas, and is useful in calculus for integrating powers of cosine and in signal processing for handling squared sinusoidal quantities."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities", "https://en.wikipedia.org/wiki/Trigonometric_functions", "https://mathworld.wolfram.com/Multiple-AngleFormulas.html", "https://en.wikipedia.org/wiki/De_Moivre%27s_formula"]'),
  ('trigonometric_sine_squared_identity', '{"en-us": "Sine squared identity"}', 'trigonometric_identities', 5, '{"en-us": "This power-reduction identity rewrites the square of the sine of an angle in terms of the cosine of twice the angle. It is the sine form of the half-angle / power-reduction formulas, and is used in calculus for integrating powers of sine and in physics for expressing time-averaged values of squared sinusoidal functions."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities", "https://en.wikipedia.org/wiki/Trigonometric_functions", "https://mathworld.wolfram.com/Multiple-AngleFormulas.html", "https://en.wikipedia.org/wiki/De_Moivre%27s_formula"]'),
  ('trigonometric_tangent_sine_cosine_ratio', '{"en-us": "Tangent as ratio of sine and cosine"}', 'trigonometric_identities', 4, '{"en-us": "This fundamental identity defines the tangent of an angle as the quotient of its sine and cosine. It underlies nearly every tangent identity, including the double-angle, sum, and product-to-sum formulas, and is the analytic extension of the geometric opposite-over-adjacent definition."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities", "https://en.wikipedia.org/wiki/Trigonometric_functions", "https://mathworld.wolfram.com/Tangent.html", "https://en.wikipedia.org/wiki/De_Moivre%27s_formula"]'),
  ('triple_angle_cosine', '{"en-us": "Triple Angle Cosine"}', 'trigonometric_identities', 7, '{"en-us": "This triple-angle identity expresses the cosine of three times an angle as a polynomial in the cosine of that angle. It is derived from the angle-addition formulas and is the Chebyshev polynomial T_3 evaluated at cos θ. The identity is used in simplifying cubic expressions in cos θ and in solving trigonometric equations of degree three."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities", "https://en.wikipedia.org/wiki/Trigonometric_functions", "https://en.wikipedia.org/wiki/De_Moivre%27s_formula", "https://mathworld.wolfram.com/Multiple-AngleFormulas.html"]'),
  ('triple_angle_sine', '{"en-us": "Triple Angle Sine"}', 'trigonometric_identities', 7, '{"en-us": "This triple-angle identity expresses the sine of three times an angle as a polynomial in the sine of that angle. It is derived from the angle-addition formulas and is closely related to the corresponding triple-angle formula for cosine. The identity is used in simplifying cubic expressions in sin θ and in solving trigonometric equations of degree three."}', '["https://en.wikipedia.org/wiki/List_of_trigonometric_identities", "https://en.wikipedia.org/wiki/Trigonometric_functions", "https://en.wikipedia.org/wiki/De_Moivre%27s_formula", "https://mathworld.wolfram.com/Multiple-AngleFormulas.html"]'),
  ('two_point_form_line', '{"en-us": "Two-point form of a line"}', 'equations', 4, '{"en-us": "A linear equation that passes through two given distinct points in the plane. It can be rearranged into the determinant form and into the symmetric form."}', '["https://en.wikipedia.org/wiki/Linear_equation#Two-point_form", "https://mathworld.wolfram.com/Two-PointForm.html", "https://en.wikipedia.org/wiki/Determinant"]'),
  ('uncompetitive_inhibition_velocity', '{"en-us": "Uncompetitive inhibition velocity"}', 'biochemistry', 9, '{"en-us": "Rate equation for an enzyme subject to uncompetitive inhibition, in which the inhibitor binds only to the enzyme–substrate complex. Both the apparent K_m and V_max decrease with inhibitor concentration."}', '["https://en.wikipedia.org/wiki/Enzyme_inhibitor#Uncompetitive", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Physical_Chemistry_for_the_Biosciences_(LibreTexts)/10%3A_Enzyme_Kinetics/10.05%3A_Enzyme_Inhibition", "https://en.wikipedia.org/wiki/Michaelis%E2%80%93Menten_kinetics"]'),
  ('unit_vector_definition', '{"en-us": "Unit vector definition"}', 'linear_algebra', 5, '{"en-us": "A unit vector in a normed vector space is a vector of length one, conventionally written with a circumflex (hat). Every non-zero vector can be normalized by dividing it by its own magnitude, and unit vectors are widely used to express direction and to form orthonormal bases."}', '["https://en.wikipedia.org/wiki/Unit_vector", "https://en.wikipedia.org/wiki/Vector_space", "https://mathworld.wolfram.com/UnitVector.html"]'),
  ('van_der_waals_equation', '{"en-us": "Van der Waals equation"}', 'ideal_gases', 8, '{"en-us": "Approximate equation of state for real (non-ideal) gases that accounts for the finite size of molecules and the attractive forces between them. The constants a and b are substance-specific, with a representing intermolecular attraction and b the excluded volume per mole."}', '["https://en.wikipedia.org/wiki/Van_der_Waals_equation", "https://en.wikipedia.org/wiki/Real_gas", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Gas_Laws"]'),
  ('van_t_hoff_equation', '{"en-us": "Van ''t Hoff equation"}', 'chemical_equilibrium', 8, '{"en-us": "Relates the change in the equilibrium constant of a chemical reaction to a change in temperature, assuming a constant standard enthalpy change. The integrated form is often used to estimate reaction enthalpies from equilibrium constants measured at two temperatures."}', '["https://en.wikipedia.org/wiki/Van_%27t_Hoff_equation", "https://en.wikipedia.org/wiki/Equilibrium_constant", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Physical_Chemistry_(McQuarrie_and_Simon)/29%3A_Chemical_Equilibrium/29.04%3A_Temperature_Dependence_of_the_Equilibrium_Constant"]'),
  ('variance_binomial', '{"en-us": "Variance of a binomial distribution"}', 'probability', 7, '{"en-us": "For a binomial random variable counting the number of successes in n independent trials each with success probability p, the variance is the product of the number of trials and the two outcome probabilities."}', '["https://en.wikipedia.org/wiki/Binomial_distribution", "https://en.wikipedia.org/wiki/Variance", "https://mathworld.wolfram.com/BinomialDistribution.html"]'),
  ('variance_shortcut', '{"en-us": "Variance shortcut formula"}', 'statistics', 7, '{"en-us": "An identity expressing the variance of a random variable as the difference between the mean of the square and the square of the mean. It is useful for algebra but suffers from catastrophic cancellation in floating-point arithmetic, so numerically stable algorithms (e.g. Welford''s) are preferred in practice."}', '["https://en.wikipedia.org/wiki/Variance", "https://en.wikipedia.org/wiki/Expected_value", "https://en.wikipedia.org/wiki/Algorithms_for_calculating_variance", "https://mathworld.wolfram.com/Variance.html", "https://www.khanacademy.org/math/statistics-probability/random-variables-stats-library/random-variables-mean-and-variance/v/variance-of-a-random-variable"]'),
  ('vector_norm_3d', '{"en-us": "3D vector norm (magnitude)"}', 'linear_algebra', 5, '{"en-us": "The Euclidean norm (length) of a three-dimensional vector, computed as the square root of the sum of the squares of its Cartesian components. It generalizes the Pythagorean theorem to vectors in R^3 and equals the distance from the origin to the point (v_x, v_y, v_z)."}', '["https://en.wikipedia.org/wiki/Norm_(mathematics)", "https://en.wikipedia.org/wiki/Euclidean_vector", "https://en.wikipedia.org/wiki/Euclidean_norm", "https://mathworld.wolfram.com/VectorNorm.html", "https://www.khanacademy.org/math/linear-algebra/vectors-and-spaces/vectors/v/vector-magnitude-and-direction"]'),
  ('vector_projection_magnitude', '{"en-us": "Scalar projection of a onto b"}', 'linear_algebra', 7, '{"en-us": "The scalar (or resolute) component of a vector along the direction of another nonzero vector, equal in magnitude to the length of the vector projection and signed according to whether the angle is acute or obtuse. It equals the dot product of a with the unit vector in the direction of b."}', '["https://en.wikipedia.org/wiki/Vector_projection", "https://en.wikipedia.org/wiki/Scalar_projection", "https://en.wikipedia.org/wiki/Dot_product", "https://mathworld.wolfram.com/ScalarProjection.html", "https://www.khanacademy.org/math/linear-algebra/vectors-and-spaces/dot-cross-products/v/projections-using-unit-vectors"]'),
  ('velocity_constant_acceleration', '{"en-us": "Velocity at constant acceleration"}', 'constant_acceleration', 4, '{"en-us": "First kinematic equation: the velocity of an object under uniform acceleration increases linearly with time, given an initial velocity. It is valid when the acceleration is constant and motion is along a straight line."}', '["https://en.wikipedia.org/wiki/Kinematics", "https://en.wikipedia.org/wiki/Equations_of_motion", "https://en.wikipedia.org/wiki/Acceleration", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/03%3A_Motion_Along_a_Straight_Line/3.04%3A_Constant_Acceleration", "https://www.khanacademy.org/science/physics/one-dimensional-motion/kinematic-formulas/v/kinematic-formulas"]'),
  ('velocity_squared_constant_acceleration', '{"en-us": "Velocity squared relation"}', 'constant_acceleration', 5, '{"en-us": "Third kinematic equation: it relates the squares of the initial and final velocities of an object undergoing uniform acceleration to the displacement traversed. It is time-independent and is useful when the time interval is unknown."}', '["https://en.wikipedia.org/wiki/Kinematics", "https://en.wikipedia.org/wiki/Equations_of_motion", "https://en.wikipedia.org/wiki/Uniform_acceleration", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/03%3A_Motion_Along_a_Straight_Line/3.05%3A_Free_Fall", "https://mathworld.wolfram.com/KinematicEquations.html", "https://www.khanacademy.org/science/physics/one-dimensional-motion/kinematic-formulas/v/kinematic-formulas"]'),
  ('venturi_effect', '{"en-us": "Venturi effect (pressure difference)"}', 'bernoulli_equation', 7, '{"en-us": "Quantifies the pressure drop that occurs when a fluid speeds up through a constriction, derived from Bernoulli''s principle. Valid for steady, incompressible, inviscid flow; underlies the operation of Venturi meters, carburetors, and atomizers."}', '["https://en.wikipedia.org/wiki/Venturi_effect", "https://en.wikipedia.org/wiki/Bernoulli%27s_principle", "https://en.wikipedia.org/wiki/Venturi_meter", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.06%3A_Bernoulli%27s_Equation", "https://www.khanacademy.org/science/physics/fluids/fluid-dynamics/v/what-is-venturi-effect"]'),
  ('venturi_pressure_difference', '{"en-us": "Venturi tube pressure difference"}', 'bernoulli_equation', 7, '{"en-us": "The Venturi tube pressure difference gives the static pressure drop between the wider inlet and the narrower throat of a Venturi tube, derived from Bernoulli''s equation for steady, incompressible, inviscid flow. It is the operating principle behind Venturi meters, which infer volumetric flow rate from a measured pressure differential."}', '["https://en.wikipedia.org/wiki/Venturi_effect", "https://www.britannica.com/technology/venturi-tube", "https://en.wikipedia.org/wiki/Bernoulli%27s_principle"]'),
  ('vertex_parabola_x', '{"en-us": "Vertex of a parabola"}', 'polynomials', 5, '{"en-us": "The vertex of a parabola is the point at which it attains its maximum or minimum value, lying on the axis of symmetry. The vertex x-coordinate is found by completing the square or by setting the first derivative of the quadratic to zero, depending only on the linear and quadratic coefficients of the parabola."}', '["https://en.wikipedia.org/wiki/Parabola#Vertex", "https://mathworld.wolfram.com/Parabola.html", "https://math.libretexts.org/Bookshelves/Algebra/Algebra_and_Trigonometry_1e_(OpenStax)/05%3A_Polynomial_and_Rational_Functions/5.05%3A_Zeros_of_Polynomial_Functions", "https://www.cuemath.com/geometry/vertex-of-a-parabola/"]'),
  ('vertical_line_equation', '{"en-us": "Vertical line"}', 'equations', 2, '{"en-us": "A vertical line in the Cartesian plane is the set of all points sharing the same x-coordinate. It is the limiting case of a linear equation whose slope is undefined, and is the dual concept to the horizontal line y = b."}', '["https://en.wikipedia.org/wiki/Linear_equation", "https://en.wikipedia.org/wiki/Vertical_line_test", "https://en.wikipedia.org/wiki/Slope"]'),
  ('vis_viva_equation', '{"en-us": "Vis-viva equation"}', 'orbital_motion', 9, '{"en-us": "The vis-viva equation relates the square of an orbiting body''s relative speed to the gravitational parameter of the central body, the instantaneous distance between the bodies, and the semi-major axis of the orbit. It follows directly from conservation of mechanical energy in a two-body Keplerian orbit and applies to elliptic, parabolic, hyperbolic, and radial trajectories."}', '["https://en.wikipedia.org/wiki/Vis-viva_equation", "https://en.wikipedia.org/wiki/Two-body_problem", "https://en.wikipedia.org/wiki/Kepler%27s_laws_of_planetary_motion", "https://en.wikipedia.org/wiki/Specific_orbital_energy"]'),
  ('voltage_divider', '{"en-us": "Voltage divider"}', 'circuits', 5, '{"en-us": "A voltage divider produces an output voltage that is a fixed fraction of the input voltage using two resistors in series. The relationship assumes an ideal load (no current drawn from the output); if current is drawn the result is approximated by Thevenin''s theorem."}', '["https://en.wikipedia.org/wiki/Voltage_divider", "https://en.wikipedia.org/wiki/Resistor#Voltage_divider", "https://en.wikipedia.org/wiki/Series_and_parallel_circuits", "https://en.wikipedia.org/wiki/Ohm%27s_law"]'),
  ('volume_annular_cylinder', '{"en-us": "Volume of an annular cylinder"}', 'plane_geometry', 6, '{"en-us": "An annular cylinder (cylindrical shell) is the region between two concentric right circular cylinders of the same height. Its volume is the difference between the outer and inner solid cylinder volumes, equal to the cross-sectional annular area multiplied by the height."}', '["https://en.wikipedia.org/wiki/Cylinder_(geometry)#Right_circular_hollow_cylinder_(cylindrical_shell)", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/06%3A_Applications_of_Integration/6.02%3A_Determining_Volumes_by_Slicing", "https://www.cuemath.com/geometry/cylinder/", "https://en.wikipedia.org/wiki/Annulus_(mathematics)"]'),
  ('volume_area_height', '{"en-us": "Volume from cross-sectional area and height"}', 'plane_geometry', 3, '{"en-us": "Relates the volume of a right prism or cylinder-like solid to its uniform cross-sectional area and the perpendicular distance between its two parallel bases. Cavalieri''s principle shows it extends to any solid whose horizontal cross-sectional area is constant along the height."}', '["https://en.wikipedia.org/wiki/Volume", "https://en.wikipedia.org/wiki/Cross_section_(geometry)", "https://mathworld.wolfram.com/Volume.html", "https://en.wikipedia.org/wiki/Prism_(geometry)"]'),
  ('volume_cone', '{"en-us": "Volume of a cone"}', 'plane_geometry', 3, '{"en-us": "The volume of any conic solid is one third of the product of the area of its base and its height. For a right circular cone this reduces to the familiar form, and a proof without calculus can be given by comparing horizontal cross-sections with a square pyramid via Cavalieri''s principle."}', '["https://en.wikipedia.org/wiki/Cone", "https://en.wikipedia.org/wiki/Volume", "https://mathworld.wolfram.com/Cone.html", "https://en.wikipedia.org/wiki/Cavalieri%27s_principle"]'),
  ('volume_cube', '{"en-us": "Volume of a cube"}', 'plane_geometry', 1, '{"en-us": "The volume of a cube is the side length raised to the third power, following directly from the fact that a cube is a special rectangular cuboid whose three edge lengths are all equal. The unit cube serves as the canonical reference for three-dimensional volume."}', '["https://en.wikipedia.org/wiki/Cube", "https://en.wikipedia.org/wiki/Volume", "https://mathworld.wolfram.com/Cube.html", "https://en.wikipedia.org/wiki/Unit_cube"]'),
  ('volume_cylinder', '{"en-us": "Volume of a cylinder"}', 'plane_geometry', 3, '{"en-us": "The volume of a circular cylinder equals the area of its circular base multiplied by its height. The result holds for both right and oblique cylinders, and a proof without calculus follows from Cavalieri''s principle by stacking disks along the axis."}', '["https://en.wikipedia.org/wiki/Cylinder", "https://en.wikipedia.org/wiki/Volume", "https://mathworld.wolfram.com/Cylinder.html", "https://en.wikipedia.org/wiki/Right_circular_cylinder"]'),
  ('volume_ellipsoid', '{"en-us": "Volume of an ellipsoid"}', 'plane_geometry', 6, '{"en-us": "The volume enclosed by a triaxial ellipsoid equals two thirds of its circumscribing elliptic cylinder, generalizing the sphere volume. When two semi-axes coincide the body becomes a spheroid, and when all three are equal it reduces to a sphere."}', '["https://en.wikipedia.org/wiki/Ellipsoid", "https://en.wikipedia.org/wiki/Volume", "https://mathworld.wolfram.com/Ellipsoid.html", "https://en.wikipedia.org/wiki/Spheroid"]'),
  ('volume_percent', '{"en-us": "Volume percent concentration"}', 'solution_stoichiometry', 4, '{"en-us": "Volume percent expresses the concentration of a solute in a solution as the volume of solute divided by the total volume of the solution, multiplied by 100. It is most commonly used when mixing two fluids such as liquids or gases, although percentages are strictly additive only for ideal mixtures."}', '["https://en.wikipedia.org/wiki/Volume_fraction", "https://en.wikipedia.org/wiki/Volume_concentration", "https://en.wikipedia.org/wiki/Mass_fraction_(chemistry)", "https://en.wikipedia.org/wiki/Percentage", "https://www.chembuddy.com/?left=concentration&right=volume-volume-percentage"]'),
  ('volume_pyramid', '{"en-us": "Volume of a pyramid"}', 'plane_geometry', 4, '{"en-us": "The volume of a pyramid equals one-third the product of its base area and its perpendicular height. This formula holds for any pyramid regardless of the shape of its polygonal base, and is a special case of the more general prismatoid formula."}', '["https://en.wikipedia.org/wiki/Pyramid_(geometry)", "https://mathworld.wolfram.com/Pyramid.html", "https://math.libretexts.org/Bookshelves/Geometry/Book%3A_Geometry_(OpenStax)/09%3A_Polygons_and_Polyhedra/9.05%3A_Other_Types_of_Polyhedra", "https://www.cuemath.com/geometry/volume-of-pyramid/"]'),
  ('volume_rectangular_prism', '{"en-us": "Volume of a rectangular prism"}', 'plane_geometry', 2, '{"en-us": "A rectangular prism (box) has three pairs of congruent rectangular faces meeting at right angles. Its volume is the product of its three edge lengths, and follows from the fact that any right prism''s volume equals the area of its base times its height."}', '["https://en.wikipedia.org/wiki/Cuboid", "https://mathworld.wolfram.com/Cuboid.html", "https://math.libretexts.org/Bookshelves/Geometry/Book%3A_Geometry_(OpenStax)/10%3A_Three-Dimensional_Geometry/10.05%3A_Surface_Area_and_Volume_of_Prisms", "https://www.cuemath.com/geometry/volume-of-rectangular-prism/"]'),
  ('volume_sphere', '{"en-us": "Volume of a sphere"}', 'plane_geometry', 3, '{"en-us": "The volume enclosed by a sphere of radius r is four-thirds times pi times the cube of the radius. Archimedes first derived this result by showing that the volume of a sphere equals two-thirds the volume of its circumscribing cylinder. It is equivalent to the volume obtained by integrating circular cross-sections from one pole to the other."}', '["https://en.wikipedia.org/wiki/Sphere", "https://mathworld.wolfram.com/Sphere.html", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/06%3A_Applications_of_Integration/6.02%3A_Determining_Volumes_by_Slicing", "https://www.britannica.com/science/sphere-geometry"]'),
  ('volume_thermal_expansion', '{"en-us": "Volume thermal expansion"}', 'heat', 6, '{"en-us": "The change in volume of a body due to a temperature change is approximately three times the linear expansion coefficient times the initial volume times the change in temperature, valid for isotropic solids and small temperature intervals. This comes from the fact that the volumetric expansion coefficient is roughly three times the linear one."}', '["https://en.wikipedia.org/wiki/Thermal_expansion", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/17%3A_Temperature_and_Heat/17.04%3A_Thermal_Expansion", "https://www.britannica.com/science/thermal-expansion", "https://courses.lumenlearning.com/suny-physics/chapter/13-3-thermal-expansion/"]'),
  ('volume_thermal_expansion_definition', '{"en-us": "Volume thermal expansion definition"}', 'heat', 6, '{"en-us": "For a solid undergoing a small temperature change, the new volume equals the initial volume times one plus three times the linear expansion coefficient times the change in temperature. This expansion is an isotropic volume change that reflects the cumulative effect of linear expansion in three independent directions."}', '["https://en.wikipedia.org/wiki/Thermal_expansion", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/17%3A_Temperature_and_Heat/17.04%3A_Thermal_Expansion", "https://www.britannica.com/science/thermal-expansion", "https://courses.lumenlearning.com/suny-physics/chapter/13-3-thermal-expansion/"]'),
  ('volume_torus', '{"en-us": "Volume of a torus"}', 'plane_geometry', 7, '{"en-us": "A torus (ring shape) is the surface of revolution generated by revolving a circle about an external coplanar axis. The volume of the solid torus equals two pi squared times the major radius times the square of the minor radius, derivable from Pappus''s centroid theorem applied to a disk."}', '["https://en.wikipedia.org/wiki/Torus", "https://mathworld.wolfram.com/Torus.html", "https://math.libretexts.org/Bookshelves/Calculus/Calculus_(OpenStax)/05%3A_Integration/5.10%3A_Applications_of_Definite_Integrals_(Area%2C_Volume%2C_Work%2C_Average_Value%2C_etc.)", "https://www.britannica.com/science/torus"]'),
  ('volume_triangular_prism', '{"en-us": "Volume of a triangular prism"}', 'plane_geometry', 3, '{"en-us": "The volume of any prism equals the area of its base times the perpendicular distance between the two parallel base planes. For a triangular prism the base is a triangle, so multiplying the triangle''s area by the prism''s length gives the volume; for a right triangular prism with equilateral bases the result further reduces to a closed form in the edge length."}', '["https://en.wikipedia.org/wiki/Triangular_prism", "https://en.wikipedia.org/wiki/Prism_(geometry)", "https://math.libretexts.org/Bookshelves/Geometry/Geometry_(OpenStax)/11%3A_Measurement_and_Geometry/11.04%3A_Volume", "https://www.cuemath.com/geometry/volume-of-a-triangular-prism/", "https://www.khanacademy.org/math/geometry/hs-geo-solids/hs-geo-volume/v/volume-of-a-triangular-prism"]'),
  ('volume_truncated_pyramid', '{"en-us": "Volume of a truncated pyramid (frustum)"}', 'plane_geometry', 6, '{"en-us": "A pyramidal frustum is the portion of a pyramid cut off by a plane parallel to its base. The volume of any pyramidal or conical frustum is one third of the perpendicular height times the Heronian mean of the two base areas, a result known since Heron of Alexandria and recorded even earlier for square frusta in the Moscow Mathematical Papyrus."}', '["https://en.wikipedia.org/wiki/Frustum", "https://en.wikipedia.org/wiki/Pyramid_(geometry)#Frustum", "https://mathworld.wolfram.com/PyramidalFrustum.html", "https://math.libretexts.org/Bookshelves/Geometry/Geometry_(OpenStax)/11%3A_Measurement_and_Geometry/11.04%3A_Volume", "https://www.cuemath.com/geometry/volume-of-a-frustum/"]'),
  ('volumetric_flow_rate', '{"en-us": "Volumetric flow rate"}', 'continuity_equation', 5, '{"en-us": "Volumetric flow rate is the volume of fluid that passes through a given cross section per unit time, conventionally denoted Q. For uniform flow across a flat cross section it reduces to the product of the cross-sectional area and the flow speed; in general it is the surface integral of the velocity field through the section, a relation fundamental to fluid dynamics, hydrology, and the continuity equation."}', '["https://en.wikipedia.org/wiki/Volumetric_flow_rate", "https://en.wikipedia.org/wiki/Continuity_equation", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/14%3A_Fluid_Mechanics/14.04%3A_Flow_Rate_and_Its_Relation_to_Velocity", "https://www.khanacademy.org/science/physics/fluids/fluid-dynamics/v/what-is-volume-flow-rate", "https://www.britannica.com/science/flow-rate"]'),
  ('water_ion_product', '{"en-us": "Ion product of water"}', 'acids_and_bases', 5, '{"en-us": "Water self-ionizes to a small extent into hydronium and hydroxide ions, with the equilibrium constant for this process known as the ion product of water, Kw. At 25 degrees Celsius Kw has the value 1.0 times ten to the negative fourteenth, and pKw plus pH plus pOH sums to 14; Kw depends strongly on temperature, pressure, and ionic strength."}', '["https://en.wikipedia.org/wiki/Self-ionization_of_water", "https://en.wikipedia.org/wiki/Dissociation_constant", "https://chem.libretexts.org/Bookshelves/General_Chemistry/General_Chemistry_(OpenStax)/14%3A_Acid-Base_Equilibria/14.02%3A_The_Ion_Product_of_Water", "https://www.khanacademy.org/science/chemistry/acids-and-bases-topic/acids-and-bases/a/autoionization-of-water", "https://goldbook.iupac.org/terms/view/A00532.html"]'),
  ('wave_equation_1d', '{"en-us": "One-dimensional wave equation"}', 'differential_equations', 9, '{"en-us": "The one-dimensional wave equation is a second-order linear partial differential equation that governs the displacement of a vibrating string and many other one-dimensional wave phenomena. The second time derivative of the displacement is proportional to the second space derivative, with the proportionality constant being the square of the wave speed; its general solution is a superposition of left- and right-traveling waves known as d''Alembert''s formula."}', '["https://en.wikipedia.org/wiki/Wave_equation", "https://en.wikipedia.org/wiki/D%27Alembert%27s_formula", "https://math.libretexts.org/Bookshelves/Differential_Equations/Elementary_Differential_Equations_(Arnold)/03%3A_Second_Order_Linear_ODEs/3.04%3A_The_Wave_Equation", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/16%3A_Waves/16.04%3A_The_Wave_Equation", "https://www.khanacademy.org/science/physics/mechanical-waves-and-sound/wave-fundamentals/v/the-wave-equation"]'),
  ('wave_function_normalization_condition', '{"en-us": "Normalization condition for a wave function"}', 'quantum_mechanics', 9, '{"en-us": "The Born rule identifies the squared magnitude of a quantum-mechanical wave function as a probability density, so the integral of that density over all space must equal one. This normalization condition, together with the Schrodinger equation, fixes the allowed scale of the wave function and underpins the probabilistic interpretation of quantum mechanics."}', '["https://en.wikipedia.org/wiki/Wave_function#Position-space_wave_functions", "https://en.wikipedia.org/wiki/Normalizable_wave_function", "https://en.wikipedia.org/wiki/Born_rule", "https://phys.libretexts.org/Bookshelves/Quantum_Mechanics/Quantum_Mechanics_(McIntyre)/02%3A_One-Dimensional_Wave_Functions/2.01%3A_The_Wave_Function_and_Its_Meaning", "https://www.khanacademy.org/science/physics/quantum-physics-welcome/quantum-physics-basics-welcome/v/normalization-of-wave-functions"]'),
  ('wave_intensity', '{"en-us": "Wave intensity"}', 'mechanical_waves', 6, '{"en-us": "Wave intensity is the time-averaged power transmitted by a wave per unit area perpendicular to the direction of propagation, with SI units of watts per square metre. It quantifies how concentrated a wave''s energy flux is at a surface and underlies the inverse-square attenuation of a point source."}', '["https://en.wikipedia.org/wiki/Intensity_(physics)", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/16%3A_Waves/16.05%3A_Energy_and_Power_of_a_Wave", "https://en.wikipedia.org/wiki/Sound_intensity", "https://en.wikipedia.org/wiki/Poynting_vector"]'),
  ('wave_interference_path_length_difference', '{"en-us": "Path length difference for two sources"}', 'wave_interference', 7, '{"en-us": "The path length difference is the difference in distances from two coherent wave sources to a given observation point, and it controls whether the waves arrive in or out of phase. Combined with the wavelength, it determines the type of interference (constructive when the path difference is an integer multiple of the wavelength and destructive when it is a half-integer multiple)."}', '["https://en.wikipedia.org/wiki/Wave_interference", "https://en.wikipedia.org/wiki/Wavelength#Interference_and_diffraction", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/16%3A_Waves/16.06%3A_Interference_of_Waves", "https://en.wikipedia.org/wiki/Path_length"]'),
  ('wave_speed_string', '{"en-us": "Wave speed on a string"}', 'mechanical_waves', 6, '{"en-us": "The speed of a transverse wave on a stretched string is set by the balance between the restoring tension and the string''s inertia, expressed as the square root of tension divided by linear mass density. It depends only on the medium''s elastic and inertial properties and is independent of the wave''s frequency or amplitude."}', '["https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/16%3A_Waves/16.04%3A_Wave_Speed_on_a_Stretched_String", "https://en.wikipedia.org/wiki/Wave#Wave_in_elastic_medium", "https://en.wikipedia.org/wiki/String_vibration", "https://en.wikipedia.org/wiki/Transverse_wave"]'),
  ('wave_superposition_amplitude', '{"en-us": "Wave superposition amplitude"}', 'wave_interference', 6, '{"en-us": "When two coherent waves of the same frequency superpose in phase, their amplitudes combine in quadrature, giving a resultant amplitude equal to the square root of the sum of the squares of the individual amplitudes. This in-phase (constructive) result is a special case of the more general interference law that includes a phase-dependent cross term."}', '["https://en.wikipedia.org/wiki/Wave_interference", "https://en.wikipedia.org/wiki/Superposition_principle", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/16%3A_Waves/16.06%3A_Interference_of_Waves", "https://en.wikipedia.org/wiki/Interference_(wave_propagation)"]'),
  ('wave_superposition_principle', '{"en-us": "Principle of wave superposition"}', 'wave_interference', 5, '{"en-us": "The principle of superposition states that when two or more waves of the same type occupy the same region of a linear medium, the resulting displacement at any point is the algebraic sum of the individual wave displacements. It holds exactly in linear systems and approximately in weakly nonlinear media for small-amplitude waves, and is the basis for interference, diffraction, and Fourier analysis."}', '["https://en.wikipedia.org/wiki/Superposition_principle", "https://en.wikipedia.org/wiki/Wave_interference", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/16%3A_Waves/16.06%3A_Interference_of_Waves", "https://en.wikipedia.org/wiki/Linear_system"]'),
  ('wave_velocity', '{"en-us": "Wave velocity"}', 'mechanical_waves', 4, '{"en-us": "The wave velocity, also called phase speed, relates a periodic wave''s frequency and wavelength, expressing the distance a crest travels per unit time. It is set by the medium''s properties, so a given frequency determines a unique wavelength and vice versa."}', '["https://en.wikipedia.org/wiki/Wavelength", "https://en.wikipedia.org/wiki/Wave#Wave_velocity", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/16%3A_Waves/16.03%3A_Mathematics_of_Waves", "https://en.wikipedia.org/wiki/Phase_velocity"]'),
  ('wave_velocity_period', '{"en-us": "Wave velocity from wavelength and period"}', 'mechanical_waves', 5, '{"en-us": "The phase velocity of a periodic wave relates how fast a wave crest travels to its spatial wavelength and its temporal period. It applies to any non-dispersive medium where the wave speed is independent of frequency, and is the basic form of the universal wave equation."}', '["https://en.wikipedia.org/wiki/Phase_velocity", "https://en.wikipedia.org/wiki/Frequency", "https://en.wikipedia.org/wiki/Wavelength", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/16%3A_Waves/16.04%3A_Wave_Speed", "https://www.physicsclassroom.com/class/waves/Lesson-2/The-Wave-Equation"]'),
  ('wavelength_from_cfse', '{"en-us": "Wavelength from CFSE"}', 'inorganic_chemistry', 9, '{"en-us": "The wavelength of light absorbed by a transition-metal complex is set by the energy gap between split d-orbitals. Reading this wavelength from the visible spectrum gives the crystal field splitting energy directly, and the spectrochemical series is built by ranking ligands according to this absorption wavelength."}', '["https://en.wikipedia.org/wiki/Crystal_field_theory", "https://en.wikipedia.org/wiki/Spectrochemical_series", "https://en.wikipedia.org/wiki/Energy", "https://chem.libretexts.org/Bookshelves/General_Chemistry/Map%3A_General_Chemistry_(Petrucci_et_al.)/24%3A_Complex_Ions_and_Coordination_Compounds/24.04%3A_Crystal_Field_Theory", "https://www.chemguide.co.uk/inorganic/complexions/colour.html"]'),
  ('wedge_film_fringe_spacing', '{"en-us": "Wedge film interference fringe spacing"}', 'interference', 8, '{"en-us": "In a thin wedge-shaped film, successive bright (or dark) interference fringes are equally spaced along the film surface. The spacing is set by the wavelength, the refractive index of the film and the wedge angle, and the result is widely used to assess surface flatness and film thickness."}', '["https://en.wikipedia.org/wiki/Newton%27s_rings", "https://en.wikipedia.org/wiki/Thin-film_interference", "https://en.wikipedia.org/wiki/Interference_(wave_propagation)", "https://phys.libretexts.org/Bookshelves/Optics/Book%3A_Geometric_Optics_(Tatum)/05%3A_Interference", "https://www.animations.physics.unsw.edu.au/waves/wave-interference/Newton%27s-rings.html"]'),
  ('weight_force', '{"en-us": "Weight force"}', 'forces', 3, '{"en-us": "The weight of a body is the gravitational force exerted on it, equal to the body''s mass multiplied by the local acceleration due to gravity. It is a vector quantity, measured in newtons in SI, and is distinct from the body''s mass (an intrinsic scalar)."}', '["https://en.wikipedia.org/wiki/Weight", "https://en.wikipedia.org/wiki/Standard_gravity", "https://en.wikipedia.org/wiki/Newton%27s_laws_of_motion", "https://www.physicsclassroom.com/class/newtlaws/Lesson-3/The-Mass-Weight-Relationship", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/05%3A_Newton%27s_Laws/5.06%3A_Newton%27s_Second_Law"]'),
  ('weighted_arithmetic_mean', '{"en-us": "Weighted arithmetic mean"}', 'statistics', 5, '{"en-us": "A weighted mean generalises the ordinary arithmetic mean by attaching a separate weight to each value, so that values with larger weights contribute more strongly to the result. It is widely used for combining averages from samples of unequal size and for inverse-variance averaging in the physical sciences."}', '["https://en.wikipedia.org/wiki/Weighted_arithmetic_mean", "https://en.wikipedia.org/wiki/Weighted_average", "https://mathworld.wolfram.com/WeightedMean.html", "https://www.britannica.com/science/arithmetic-mean", "https://stats.libretexts.org/Bookshelves/Introductory_Statistics/Book%3A_Introductory_Statistics_(OpenStax)/02%3A_Descriptive_Statistics/2.07%3A_Measures_of_the_Center_of_the_Data"]'),
  ('wheatstone_bridge_balance', '{"en-us": "Wheatstone bridge balance condition"}', 'circuits', 7, '{"en-us": "A Wheatstone bridge is balanced when the ratio of resistances in one leg equals the ratio in the other, so that the galvanometer reads zero current. The bridge is widely used to measure an unknown resistance with high precision, and to transduce small changes in resistance due to strain, temperature, or other physical quantities."}', '["https://en.wikipedia.org/wiki/Wheatstone_bridge", "https://www.electronics-tutorials.ws/blog/wheatstone-bridge.html", "https://www.physics-and-radio-electronics.com/electronic-devices-and-circuits/uncategorized/wheatstonebridge.html", "https://www.britannica.com/technology/Wheatstone-bridge", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/09%3A_Current_and_Resistance/9.09%3A_Superconductors"]'),
  ('wiens_displacement_law', '{"en-us": "Wien''s displacement law"}', 'heat_transfer', 8, '{"en-us": "States that the wavelength at which a blackbody''s spectral radiance is maximum is inversely proportional to its absolute temperature, with the proportionality given by Wien''s displacement constant. This explains why hot objects shift from red to blue as their temperature rises, and underlies stellar color-temperature relations and infrared applications."}', '["https://en.wikipedia.org/wiki/Wien%27s_displacement_law", "https://physics.info/wien-displacement/", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Physical_Chemistry_(LibreTexts)/01%3A_The_Dawn_of_the_Quantum_Theory/1.02%3A_Blackbody_Radiation", "https://www.physnet.uni-hamburg.de/joomla/index.php/en/physics-of-the-universe/wiens-displacement-law"]'),
  ('work_against_friction', '{"en-us": "Work done against friction"}', 'work', 5, '{"en-us": "The work that must be supplied to overcome kinetic friction equals the product of the kinetic friction force and the displacement over which it acts. This energy is dissipated as heat and is independent of the speed of sliding (in the Coulomb model)."}', '["https://en.wikipedia.org/wiki/Friction", "https://en.wikipedia.org/wiki/Work_(physics)", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/06%3A_Applications_of_Newton%27s_Laws/6.04%3A_Friction_(Part_1)", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/07%3A_Work_and_Kinetic_Energy"]'),
  ('work_area_under_force_curve', '{"en-us": "Work from force-displacement graph"}', 'work', 5, '{"en-us": "Geometric interpretation of mechanical work: the work done by a force on a body equals the area under the force-versus-displacement curve. For a linearly varying force from zero to a final value, this area is one half the product of the final force and the displacement."}', '["https://en.wikipedia.org/wiki/Work_(physics)", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/07%3A_Work_and_Kinetic_Energy", "https://www.physics.uci.edu/~lvd/scalarwork.pdf"]'),
  ('work_by_gas', '{"en-us": "Work done by a gas"}', 'first_law', 6, '{"en-us": "Pressure-volume work performed by (or on) a gas during a process. For a constant external pressure (isobaric process) the work equals the product of the pressure and the change in volume; the general reversible form involves integrating the pressure over the volume change."}', '["https://en.wikipedia.org/wiki/Work_(thermodynamics)", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_II_-_Thermodynamics_Electricity_and_Magnetism_(OpenStax)/03%3A_The_First_Law_of_Thermodynamics", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Physical_Chemistry_for_Biological_Sciences_(LibreTexts)/07%3A_Thermodynamics/7.02%3A_Pressure-Volume_Work", "https://www.chem.fsu.edu/chemfsu/WORK/Gas-Work.html"]'),
  ('work_energy_theorem', '{"en-us": "Work-energy theorem"}', 'work', 5, '{"en-us": "States that the net work done by all forces acting on a particle equals the change in its kinetic energy between the initial and final states. A direct consequence of Newton''s second law that connects a scalar energy balance to the underlying vector forces."}', '["https://en.wikipedia.org/wiki/Work%E2%80%93energy_theorem", "https://en.wikipedia.org/wiki/Work_(physics)", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/07%3A_Work_and_Kinetic_Energy", "https://www.physnet.uni-hamburg.de/joomla/images/pdfs/Work_Energy_Theorem.pdf"]'),
  ('work_force_displacement_general', '{"en-us": "Work as dot product of force and displacement"}', 'work', 6, '{"en-us": "For a constant force applied at a fixed angle to the displacement of its point of application, the work done equals the product of the force magnitude, the displacement magnitude, and the cosine of the angle between them. Work is positive when the force has a component along the displacement and negative when it opposes it."}', '["https://en.wikipedia.org/wiki/Work_(physics)", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/07%3A_Work_and_Kinetic_Energy", "https://www.math.ubc.ca/~feldman/m120/work.pdf", "https://openstax.org/books/university-physics-volume-1/pages/7-2-work"]'),
  ('work_formula', '{"en-us": "Work"}', 'work', 3, '{"en-us": "In physics, work is the energy transferred to or from an object by a force acting along a displacement. This simple form applies only when the force is constant and parallel to the direction of motion; the general expression is the line integral of force along the path."}', '["https://en.wikipedia.org/wiki/Work_(physics)", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/07%3A_Work_and_Kinetic_Energy", "https://www.khanacademy.org/science/physics/work-and-energy/work-and-energy-tutorial/a/what-is-work", "https://www.britannica.com/science/work-physics", "https://openstax.org/books/university-physics-volume-1/pages/7-1-work"]'),
  ('work_nonconservative_energy', '{"en-us": "Work done by non-conservative forces"}', 'conservation_of_energy', 6, '{"en-us": "The work done by non-conservative forces on an object equals the change in its mechanical energy, since only non-conservative forces can change the sum of kinetic and potential energy. Examples of non-conservative forces include friction, air drag, and applied (external) forces."}', '["https://en.wikipedia.org/wiki/Conservative_force", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/08%3A_Conservation_of_Energy", "https://www.khanacademy.org/science/physics/work-and-energy/conservation-of-energy/a/what-is-conservation-of-energy", "https://openstax.org/books/university-physics-volume-1/pages/8-2-conservative-and-nonconservative-forces", "https://www.britannica.com/science/conservative-force"]'),
  ('work_zero_displacement', '{"en-us": "Work done when force is perpendicular to displacement"}', 'work', 5, '{"en-us": "When a force is perpendicular to the displacement of its point of application, it does no work on the object, because W = F s cos θ and cos 90° = 0. This is why the normal force from a surface, the gravitational force on a horizontally moving object, and centripetal forces do no work."}', '["https://en.wikipedia.org/wiki/Work_(physics)", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/07%3A_Work_and_Kinetic_Energy", "https://www.physicsclassroom.com/Class/energy/u5l1c.cfm", "https://www.britannica.com/science/work-physics", "https://openstax.org/books/university-physics-volume-1/pages/7-1-work"]'),
  ('youngs_contact_angle', '{"en-us": "Contact angle from Young''s equation"}', 'surface_tension', 9, '{"en-us": "Young''s equation relates the equilibrium contact angle of a liquid drop on a solid surface to the three interfacial surface tensions (solid-gas, solid-liquid, and liquid-gas). The contact angle quantifies the wettability of a surface; it applies to an ideal smooth, homogeneous, rigid surface in thermodynamic equilibrium."}', '["https://en.wikipedia.org/wiki/Contact_angle", "https://en.wikipedia.org/wiki/Wetting", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Physical_Properties_of_Matter/States_of_Matter/Properties_of_Liquids/Contact_Angles", "https://www.britannica.com/science/wettability", "https://openstax.org/books/university-physics-volume-1/pages/11-7-wetting-and-capillary-action"]'),
  ('youngs_modulus', '{"en-us": "Young''s modulus"}', 'forces', 6, '{"en-us": "Young''s modulus is a mechanical property of solid materials that measures tensile or compressive stiffness when force is applied along one axis. It is defined as the ratio of uniaxial stress to the resulting strain in the linear elastic region of the material, and is valid only within the Hookean (small-strain, reversible) limit."}', '["https://en.wikipedia.org/wiki/Young%27s_modulus", "https://phys.libretexts.org/Bookshelves/University_Physics/University_Physics_(OpenStax)/Book%3A_University_Physics_I_-_Mechanics_Sound_Oscillations_and_Waves_(OpenStax)/12%3A_Static_Equilibrium_and_Elasticity", "https://www.britannica.com/science/Youngs-modulus", "https://www.khanacademy.org/science/physics/work-and-energy/hookes-law/a/what-is-youngs-modulus", "https://openstax.org/books/university-physics-volume-1/pages/12-4-stress-strain-and-tensile-modulus"]'),
  ('z_score_formula', '{"en-us": "Z-score"}', 'statistics', 6, '{"en-us": "The z-score (standard score) expresses how many standard deviations a raw observation lies from the population mean. It is a dimensionless quantity used to compare values measured on different scales and to assess relative position in a distribution, assuming the population parameters are known."}', '["https://en.wikipedia.org/wiki/Standard_score", "https://www.khanacademy.org/math/statistics-probability/modeling-distributions-of-data/z-scores/a/z-scores-review", "https://www.britannica.com/statistic/z-score", "https://stats.libretexts.org/Bookshelves/Introductory_Statistics/Introductory_Statistics/06%3A_The_Normal_Distribution/6.04%3A_Standard_Scores_and_z-scores", "https://mathworld.wolfram.com/z-Score.html"]'),
  ('zeeman_splitting_energy', '{"en-us": "Zeeman splitting energy"}', 'atomic_physics', 9, '{"en-us": "In the weak-field (anomalous) Zeeman effect, an external magnetic field shifts atomic energy levels by an amount proportional to the Bohr magneton, the magnetic field strength, the Landé g-factor, and the magnetic quantum number for the total electronic angular momentum. This splitting of degenerate atomic states into multiple sublevels is the basis for techniques such as electron spin resonance and for measuring stellar and laboratory magnetic fields."}', '["https://en.wikipedia.org/wiki/Zeeman_effect", "https://en.wikipedia.org/wiki/Land%C3%A9_g-factor", "https://en.wikipedia.org/wiki/Bohr_magneton", "https://phys.libretexts.org/Bookshelves/Quantum_Mechanics/Quantum_Mechanics_(McIntyre)/04%3A_Foundations_of_Quantum_Mechanics/4.09%3A_The_Zeeman_Effect", "https://www.britannica.com/science/Zeeman-effect"]'),
  ('zero_exponent_rule', '{"en-us": "Zero exponent rule"}', 'exponents', 2, '{"en-us": "The zero exponent rule states that any nonzero base raised to the power of zero equals one. It follows from the requirement that the law of exponents b^{m+n} = b^m b^n remain consistent when n = 0, and is equivalent to defining exponentiation as the empty product."}', '["https://en.wikipedia.org/wiki/Exponentiation#Zero_exponent", "https://mathworld.wolfram.com/Power.html", "https://www.cuemath.com/algebra/zero-exponent-rule/", "https://www.khanacademy.org/math/algebra/x2f8bb11595b61c86:rational-exponents-radicals/x2f8bb11595b61c86:exponent-properties/v/zero-exponent-property", "https://www.britannica.com/science/exponentiation"]'),
  ('zero_order_half_life', '{"en-us": "Zero-order reaction half-life"}', 'chemical_kinetics', 7, '{"en-us": "The half-life of a zero-order reaction is the time required for the reactant concentration to fall to half of its initial value. Unlike first-order kinetics, the half-life depends on the initial concentration and the zero-order rate constant k, so it lengthens as the reaction proceeds. Zero-order behavior typically arises when a catalyst or surface is saturated, such as in many enzyme-catalyzed reactions at high substrate concentration."}', '["https://en.wikipedia.org/wiki/Half-life#Zero_order_kinetics", "https://en.wikipedia.org/wiki/Rate_equation#Zero_order", "https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Kinetics/Reaction_Rates/Zero-Order_Reactions", "https://www.khanacademy.org/science/chemistry/chemical-kinetics-topic/zero-order-reactions", "https://www.britannica.com/science/zero-order-reaction"]'),
  ('zero_order_rate_law_integrated', '{"en-us": "Integrated rate law (zero order)"}', 'chemical_kinetics', 7, '{"en-us": "The integrated zero-order rate law expresses the concentration of a reactant as a linear function of time. Because the rate is independent of concentration, the reactant decays at a constant rate, giving a straight line on a plot of concentration versus time with slope equal to minus the rate constant. Zero-order behavior is most often observed when a catalyst or surface is saturated, such as in many enzyme-catalyzed reactions."}', '["https://chem.libretexts.org/Bookshelves/Physical_and_Theoretical_Chemistry_Textbook_Maps/Supplemental_Modules_(Physical_and_Theoretical_Chemistry)/Kinetics/02%3A_Reaction_Rates/2.10%3A_Zero-Order_Reactions", "https://en.wikipedia.org/wiki/Rate_equation#Zero_order", "https://www.khanacademy.org/science/chemistry/chemical-kinetics-topic/zero-order-reactions", "https://courses.lumenlearning.com/suny-mcc-organicchemistry/chapter/zero-order-reactions/", "https://www.chemteam.info/kinetics/zero-order.html"]');

